def test_w478_the_schedule_is_prioritised_by_vision_value_and_completion_is_weighted(tmp_path):
    """W478 — the Owner (2026-09-19): "a prioritisation mechanism along with a scheduling mechanism within the planning
    system, to correlate significance to vision-delivery importance to completion of delivery". A row's priority is a
    product of NAMED parts (vision area · truth tier · reach · criticality · breadth · effort) from the Owner's weights
    in docs/PRIORITY.json; inside a plan item rows run highest-priority first (the plan's order and phase gates stand);
    PLAN NOW names the highest-priority rows and the delivery completion weighted by priority."""
    import json as _json
    import os as _os
    import pathlib
    import subprocess as _sp
    import sys as _sys
    from agentic_core import plan_followups as fu
    from agentic_core import plan_priority as pp

    root = pathlib.Path(__file__).resolve().parents[1]
    cfg, problems = pp.load_config(root)
    assert problems == [] and (root / "docs/PRIORITY.json").exists(), problems

    def row(**kw):
        base = {"id": "FU-900", "title": "t", "why": "w", "source": "test", "found": "2026-09-19", "files": [],
                "severity": "medium", "owner_gated": False, "slot": "P1.18", "status": "open", "closed_by": None, "note": ""}
        return {**base, **kw}

    # ── the score is the product of its parts, each named ──
    faith = pp.score_row(row(title="v5 R1.2: basmala on ayah 1", files=["agentic_core/api/religion.py"]), cfg, "P1")
    # W496 — `effort_measured` joined the parts: a row that names NO file used to score effort 1.0, the
    # BEST possible value, so an under-specified row ranked as the cheapest work on the list. The
    # arithmetic is unchanged and the score now says when it is an upper bound.
    assert {k: v for k, v in faith["parts"].items() if k != "effort_measured"} == {
        "vision": 1.0, "truth": 1.0, "reach": 1.0, "criticality": 1.0, "breadth": 1.0, "effort": 1.0}
    assert faith["parts"]["effort_measured"] is True and faith["score_is_upper_bound"] is False
    _nofile = pp.score_row(row(title="v5 R1.2: basmala on ayah 1"), cfg, "P1")   # files=[] in the base row
    assert _nofile["parts"]["effort_measured"] is False, _nofile["parts"]
    assert _nofile["score_is_upper_bound"] is True, "a score with no effort measured is an upper bound"
    assert faith["score"] == 100.0 and faith["area"] == "faith" and faith["tier"] == 1, faith
    tool = pp.score_row(row(files=["scripts/relocate_data_store.py"], severity="low"), cfg, "P1")
    assert tool["area"] == "tooling" and tool["tier"] is None and tool["parts"]["truth"] == 0.25
    assert tool["score"] == round(100 * 0.3 * 0.25 * 0.3, 1), tool          # tooling × low × internal
    later = pp.score_row(row(title="v5 R1.2: x", files=["agentic_core/api/religion.py"], slot="P2.4"), cfg, "P1")
    assert later["parts"]["criticality"] == 0.5 and later["score"] == 50.0
    gated = pp.score_row(row(files=["agentic_core/api/religion.py"], owner_gated=True, slot="OWNER"), cfg, "P1")
    assert gated["score"] == 0.0 and "Owner" in gated["basis"]["criticality"]
    broad = pp.score_row(row(title="sweep x.py: 8 Tier-1 truth defects (C1) — y", files=["agentic_core/api/genesis.py"]), cfg, "P1")
    assert broad["parts"]["breadth"] > 1.0 and broad["basis"]["breadth"] == "8 findings"
    wide = pp.score_row(row(title="v5 R1.0: x", files=["agentic_core/api/religion.py"] + [f"agentic_core/api/f{k}.py" for k in range(5)]), cfg, "P1")
    assert wide["parts"]["effort"] < 1.0 and wide["score"] < faith["score"]
    explicit = pp.score_row(row(files=["scripts/x.py"], tier=1, area="faith", reach="core"), cfg, "P1")
    assert explicit["score"] == 100.0 and explicit["basis"]["area"].endswith("(set on the row)")

    # ── the Owner's weights steer the order: economy above faith, and the order flips ──
    cfg2 = _json.loads(_json.dumps(cfg))
    for a in cfg2["areas"]:
        a["weight"] = {"faith": 0.2, "economy": 1.0}.get(a["id"], a["weight"])
    econ = row(id="FU-901", title="v5 R6.1: costs posted to reserves", files=["agentic_core/economy/metabolism.py"])
    fa = row(id="FU-902", title="v5 R1.2: basmala", files=["agentic_core/api/religion.py"])
    assert pp.score_row(fa, cfg, "P1")["score"] > pp.score_row(econ, cfg, "P1")["score"]
    assert pp.score_row(econ, cfg2, "P1")["score"] > pp.score_row(fa, cfg2, "P1")["score"]

    # ── a malformed weights file is REPORTED and the defaults serve; nothing crashes ──
    bad = tmp_path / "badroot"
    (bad / "docs").mkdir(parents=True)
    (bad / "docs" / "PRIORITY.json").write_text('{"areas": [{"id": "faith", "weight": 7, "files": ["x/"]}]}', encoding="utf-8")
    c_bad, p_bad = pp.load_config(bad)
    assert any("weight must be a number from 0 to 1" in p for p in p_bad) and c_bad["areas"][0]["id"] == "faith"
    (bad / "docs" / "PRIORITY.json").write_text("{not json", encoding="utf-8")
    assert any("cannot be read" in p for p in pp.load_config(bad)[1])
    assert pp.row_field_problems(row(tier=4, reach="everywhere", findings=0)) == [
        "tier must be 1, 2 or 3", "reach must be core, secondary or internal", "findings must be a whole number of at least 1"]

    # ── ordering inside an item: highest priority first; ties fall back to severity, then age ──
    prompt = fu.read_doc(fu.PROMPT)
    items = fu.plan_items(prompt)
    first_open = next(i["slot"] for i in items if not i["done"])
    reg = {"items": [row(id="FU-910", slot=first_open, files=["scripts/a.py"], severity="high"),
                     row(id="FU-911", slot=first_open, title="v5 R1.0: faith", files=["agentic_core/api/religion.py"]),
                     row(id="FU-913", slot=first_open, files=["scripts/b.py"], severity="high"),
                     row(id="FU-912", slot=first_open, files=["scripts/c.py"], severity="low")]}
    s = fu.schedule(reg, prompt)
    order = [r["id"] for r in s["schedule"][0]["items"]]
    assert order == ["FU-911", "FU-910", "FU-913", "FU-912"], order
    assert all("priority" not in r for r in reg["items"]), "the register's own rows were mutated"
    assert s["schedule"][0]["open_priority"] == round(sum(r["priority"]["score"] for r in s["schedule"][0]["items"]), 1)

    # ── completion is weighted by priority: closing the faith row moves it far more than closing the tooling row ──
    done_faith = {"items": [dict(reg["items"][1], status="done", closed_by="W999"), reg["items"][0]]}
    done_tool = {"items": [reg["items"][1], dict(reg["items"][0], status="done", closed_by="W999")]}
    gate = first_open.split(".")[0]
    cf = fu.schedule(done_faith, prompt)["priority"]["completion"]["by_phase"][gate]["weighted_pct"]
    ct = fu.schedule(done_tool, prompt)["priority"]["completion"]["by_phase"][gate]["weighted_pct"]
    assert cf > 80.0 > 20.0 > ct, (cf, ct)                     # both are '1 of 2 rows' — the weight is the difference

    # ── PLAN NOW says it: the highest-priority rows of the next item and the weighted completion ──
    text = fu.render_plan_now(reg, prompt)
    assert f"Highest priority in {first_open} (score · area): FU-911 100.0 faith" in text, text
    assert "Follow-up completion weighted by priority" in text and "Delivery completion" not in text
    assert "[p 100.0]" in fu.render(reg, prompt)

    # ── (refutation) the primary file decides the area and the reach — an incidental later file never lends its weight ──
    badge = pp.score_row(row(title="sweep CareHub.tsx: 1 Tier-1 truth defect (C4) — badges", files=[
        "apps/workstation-superapp/src/pages/domains/CareHub.tsx", "apps/workstation-superapp/src/pages/domains/LawHub.tsx",
        "apps/workstation-superapp/src/pages/domains/ReligionHub.tsx"]), cfg, "P1")
    assert badge["area"] == "domains_ux" and "primary file" in badge["basis"]["area"], badge["basis"]
    swarm = pp.score_row(row(title="sweep swarm.py: 1 Tier-1 truth defect (C1) — x",
                             files=["agentic_core/api/swarm.py", "agentic_core/ai/gateway.py", "agentic_core/api/genesis.py"]), cfg, "P1")
    assert swarm["area"] == "organisation" and swarm["parts"]["reach"] == 0.6, swarm["basis"]   # genesis.py 3rd: not core
    # a row with no files uses the repository paths its own text names, and says so; with none, it says 'no files named'
    named = pp.score_row(row(title="v5 R2.0: x", why="the handler agentic_core/api/genesis.py:394 selects a vetoed one"), cfg, "P1")
    assert named["area"] == "lifecycle" and "named in the row" in named["basis"]["area"] and named["parts"]["reach"] == 1.0
    # (refutation 2) the ledger rows cite SHORT names — each resolves to the one tracked file it can only mean
    short = pp.score_row(row(title="v5 R9.1: x", why="genesis.py:394 still selects a vetoed candidate"), cfg, "P1")
    assert short["parts"]["reach"] == 1.0 and "agentic_core/api/genesis.py" in short["basis"]["reach"], short["basis"]
    assert pp.files_of(row(why="see api.py for the route"), cfg) == ([], False)        # several files end so: no guess
    # the vision section a row's title CITES decides its area before any file does (the heaviest if several), across the
    # whole title (a ledger section can hold ' — '); a sweep row's claim text is never read for sections
    atp = pp.score_row(row(title="v5 R6.1: §8 survival instinct / §8→§12 economic survival — ATP",
                           files=["agentic_core/ai/native/homeostasis.py", "agentic_core/economy/metabolism.py"]), cfg, "P1")
    assert atp["area"] == "organism" and "cites §8" in atp["basis"]["area"], atp["basis"]
    halal = pp.score_row(row(title="v5 R5.2: §3A Domain Working (Religion — Halal pre-assessment) / §11… — observed"), cfg, "P1")
    assert halal["area"] == "compliance" and "cites §11" in halal["basis"]["area"], halal["basis"]
    sweep_sec = pp.score_row(row(title="sweep CareHub.tsx: 1 Tier-1 truth defect (C1) — the '§10 bar' chip",
                                 files=["apps/workstation-superapp/src/pages/domains/CareHub.tsx"]), cfg, "P1")
    assert sweep_sec["area"] == "domains_ux", sweep_sec["basis"]
    bad_sec = _json.loads((root / "docs/PRIORITY.json").read_text(encoding="utf-8"))
    bad_sec["sections"]["8"] = "nowhere"
    assert any("section §8 maps to 'nowhere'" in m for m in pp.config_problems(bad_sec))
    # a CLOSED row's stored area is checked too: completion scores closed rows with the same fields
    closed_bad = {"items": [row(id="FU-930", status="done", closed_by="W999", area="nowhere")]}
    assert any("FU-930" in m and "names no area" in m for m in fu.check(closed_bad, fu.read_doc(fu.PROMPT), None))
    bare = pp.score_row(row(title="v5 R9.9: nothing named"), cfg, "P1")
    assert bare["basis"]["effort"] == "no files named", bare["basis"]
    # effort counts only files beyond one per finding: an 8-finding sweep row over 6 files is not penalised
    many = pp.score_row(row(title="sweep intelligence.py: 8 Tier-1 truth defects (C1) — x",
                            files=["agentic_core/api/intelligence.py"] + [f"apps/workstation-superapp/src/pages/p{k}.tsx" for k in range(5)]), cfg, "P1")
    one = pp.score_row(row(title="v5 R2.9: y", files=["agentic_core/api/intelligence.py"]), cfg, "P1")
    assert many["parts"]["effort"] == 1.0 and many["score"] > one["score"], (many["score"], one["score"])
    # generic title words no longer pull a row into an area; only the title (never the '— observed' prose) is read
    ueg = pp.score_row(row(title="The constitutional ledger's chain is replaced — the ethical engine and the floor wrote it",
                           files=["agentic_core/gaas/v5/ueg.py"]), cfg, "P1")
    assert ueg["area"] is None, ueg["basis"]
    # an area missing its name is a problem (the file is refused, the defaults serve) — it never crashes a render
    noname = tmp_path / "noname"
    (noname / "docs").mkdir(parents=True)
    d = _json.loads((root / "docs/PRIORITY.json").read_text(encoding="utf-8"))
    del d["areas"][0]["name"]
    (noname / "docs" / "PRIORITY.json").write_text(_json.dumps(d), encoding="utf-8")
    c_nn, p_nn = pp.load_config(noname)
    assert any("name must be a non-empty string" in p for p in p_nn) and c_nn["areas"][0].get("name")
    # a stored area that names no configured area is a problem, not a silent 'unmapped'
    assert any("names no area in docs/PRIORITY.json" in m for m in pp.row_field_problems(row(area="quality"), cfg))
    # completion: the retired pre-plan queue is scored like any row and kept out of the overall figure
    retired = {"items": [row(id="FU-920", slot="NEXT", status="done", closed_by="W400", files=["agentic_core/api/religion.py"], title="v5 R1.0: x"),
                         row(id="FU-921", slot=first_open, title="v5 R1.0: y", files=["agentic_core/api/religion.py"])]}
    comp_r = fu.schedule(retired, prompt)["priority"]["completion"]
    assert comp_r["by_phase"][pp.RETIRED]["closed_priority"] == 100.0 and comp_r["overall_weighted_pct"] == 0.0, comp_r
    # the live plan card says what the order is and shows each row's priority
    card = (root / "apps/workstation-superapp/src/pages/TransformationDashboard.tsx").read_text(encoding="utf-8")
    assert 'data-testid="plan-priority"' in card and "p ${r.priority.score}" in card and "follow-up completion weighted by priority" in card

    # ── the real register: the check holds, and the next item's rows run highest first ──
    real = fu.load()
    assert fu.check(real, prompt, fu.read_doc(fu.LIVING)) == []
    rs = fu.schedule(real, prompt)
    top = rs["schedule"][0]["items"]
    assert [r["priority"]["score"] for r in top] == sorted((r["priority"]["score"] for r in top), reverse=True)
    assert rs["priority"]["config"] == "docs/PRIORITY.json" and rs["priority"]["config_problems"] == []
    assert set(rs["priority"]["suggested_order"]) == {x["slot"] for x in rs["schedule"]}

    # ── the CLI: priority shows the parts; add/reprioritise set them and refuse an unknown area (scratch copy) ──
    scratch = tmp_path / "root"
    (scratch / "docs").mkdir(parents=True)
    (scratch / "agentic_core" / "api").mkdir(parents=True)
    (scratch / "agentic_core" / "api" / "religion.py").write_bytes(b"# stand-in\n")
    empty = {"items": []}
    (scratch / "docs" / "FABLE_DELIVERY_PROMPT.md").write_bytes(fu.splice_all(prompt, empty, prompt).encode("utf-8"))
    (scratch / "docs" / "WORKSTATION_IDBO_LIVING_PLAN.md").write_bytes(fu.splice_all(fu.read_doc(fu.LIVING), empty, prompt).encode("utf-8"))
    (scratch / "docs" / "FOLLOWUPS.json").write_bytes(b'{"items": [], "routes": []}\n')
    (scratch / "docs" / "PRIORITY.json").write_bytes((root / "docs/PRIORITY.json").read_bytes())
    env = dict(_os.environ, WORKSTATION_FOLLOWUPS_ROOT=str(scratch), PYTHONIOENCODING="utf-8")
    script = str(root / "scripts/followups.py")

    def cli(*argv):
        return _sp.run([_sys.executable, script, *argv], env=env, capture_output=True, text=True, encoding="utf-8")
    r1 = cli("add", "--title", "t", "--why", "w", "--source", "test", "--files", "agentic_core/api/religion.py",
             "--slot", first_open, "--tier", "1", "--reach", "core")
    assert r1.returncode == 0, r1.stdout + r1.stderr
    rows = _json.loads((scratch / "docs" / "FOLLOWUPS.json").read_text(encoding="utf-8"))["items"]
    assert rows[0]["tier"] == 1 and rows[0]["reach"] == "core"
    r2 = cli("add", "--title", "t2", "--why", "w", "--source", "test", "--slot", first_open, "--area", "nowhere")
    assert r2.returncode != 0 and "is not a priority area" in (r2.stdout + r2.stderr)
    pr = cli("priority", "--item", first_open)
    assert pr.returncode == 0 and "= 100 × vision 1.0 × truth 1.0 × reach 1.0" in pr.stdout and "area: " in pr.stdout, pr.stdout
    assert "completion weighted by priority" in pr.stdout
    assert cli("reprioritise", "FU-001", "--area", "tooling").returncode == 0
    assert _json.loads((scratch / "docs" / "FOLLOWUPS.json").read_text(encoding="utf-8"))["items"][0]["area"] == "tooling"
    cl = cli("reprioritise", "FU-001", "--clear", "area")                       # (refutation) a stale part can be removed
    assert cl.returncode == 0 and "cleared area" in cl.stdout
    assert "area" not in _json.loads((scratch / "docs" / "FOLLOWUPS.json").read_text(encoding="utf-8"))["items"][0]
    first_ = cli("reprioritise", "FU-001", "--clear", "reach")                  # it was set at add (--reach core)
    assert first_.returncode == 0 and "cleared reach" in first_.stdout
    none_ = cli("reprioritise", "FU-001", "--clear", "reach")                   # (refutation 2) never 'cleared' when unset
    assert none_.returncode == 0 and "cleared reach" not in none_.stdout and "nothing to clear: reach" in none_.stdout
    both = cli("reprioritise", "FU-001", "--area", "faith", "--clear", "area")
    assert both.returncode != 0 and "--clear and a value for the same part" in (both.stdout + both.stderr)
    blank = cli("reprioritise", "FU-001", "--area", "  ")
    assert blank.returncode != 0 and "blank --area" in (blank.stdout + blank.stderr)
    assert cli("reprioritise", "FU-001", "--area", "tooling").returncode == 0
    assert cli("close", "FU-001", "--by", "W999").returncode == 0
    r3 = cli("reprioritise", "FU-001", "--tier", "2")
    assert r3.returncode != 0 and "only an open row is reprioritised" in (r3.stdout + r3.stderr)
    (scratch / "docs" / "PRIORITY.json").write_text("{not json", encoding="utf-8")
    pr2 = cli("priority")
    assert pr2.returncode == 1 and "cannot be read" in pr2.stdout
    ck = cli("check")                                           # the check names THIS problem, not only a stale block
    assert ck.returncode != 0 and "PROBLEM docs/PRIORITY.json cannot be read" in ck.stdout, ck.stdout


def test_w479_intelligence_engines_say_what_served_each_stage_and_count_only_stages(client, monkeypatch):
    """W479 — P1.18 FU-121 (sweep S4.4, S4.5, S5.4, S5.5, S5.6, S6.2, S6.3, S7.6) + FU-153 (S7.7). The four
    intelligence pipelines and the Synthesis Nexus: every stage event says what served it (model · floor ·
    failed), the pages count only stage results, the Nexus says whether anything chose its engine, its
    counts are what ran, and no page claims engines that never run."""
    import asyncio
    import json
    import pathlib
    root = pathlib.Path(__file__).resolve().parents[1]
    import agentic_core.ai.gateway as gw
    import agentic_core.api.intelligence as intel
    from agentic_core.ai.native.engine import _subject

    def _events(resp):
        return [json.loads(line[6:]) for line in resp.text.splitlines() if line.startswith("data: ")]

    calls = []
    real_meta = gw.gateway.query_meta

    async def _spy(prompt, agent="assistant", timeout=90.0, owner_id=None, augment=True):
        calls.append({"agent": agent, "augment": augment})
        return await real_meta(prompt, agent=agent, timeout=timeout, owner_id=owner_id, augment=augment)
    monkeypatch.setattr(gw.gateway, "query_meta", _spy)

    # ── S5.4 / S5.6: authorship on the floor, rigor set — 9 results keyed 1..9, the config event is not a stage ──
    topic = "Urban tree canopy and summer heat admissions"
    evs = _events(client.post("/api/v1/intelligence/authorship", json={"topic": topic, "rigor": "rigorous"}))
    results = [e for e in evs if isinstance((e.get("data") or {}).get("stage_num"), int)]
    assert [e["data"]["stage_num"] for e in results] == list(range(1, 10)), [e["stage"] for e in results]
    assert any(e["stage"] == "config" for e in evs) and "stage_num" not in (next(e for e in evs if e["stage"] == "config").get("data") or {})
    assert all(e["data"]["served_by"] == "native" and e["data"]["failed"] is False for e in results)
    assert sum(topic.lower() in e["content"].lower() for e in results) == 9, "the floor dropped the user's topic"
    done = evs[-1]
    assert done["stage"] == "complete" and done["data"]["floor_calls"] == 9 and done["data"]["stages_completed"] == 9
    assert "structured floor" in done["content"] and "pipeline complete" not in done["content"].lower()
    assert calls and all(c["augment"] is False for c in calls), "a stage call injected cross-request recall"

    # every engine's prompts carry the user's subject in a label the floor reads (BDP 'Business:', DDPIE 'System/Product:',
    # APIE 'Topic/Thesis:' were not read, so the floor restated the persona instead)
    for P, kw in ((intel._BDP_PROMPTS, dict(challenge="Hive weight monitor", domain="d", context="")),
                  (intel._SPI_PROMPTS, dict(challenge="Hive weight monitor", domain="d", context="")),
                  (intel._APIE_PROMPTS, dict(topic="Hive weight monitor", domain="d", genre="g", audience="a",
                                             citation_style="APA", word_count="1", context="")),
                  (intel._DDPIE_PROMPTS, dict(system="Hive weight monitor", domain="d", scale="s", tech_stack="t",
                                              deployment_target="c", context=""))):
        for k, t in P.items():
            assert _subject(t.format(**kw)) == "Hive weight monitor", k

    # ── a failed stage is failed: red, not run, not counted, and the summary says so ─────────────────────────
    async def _fail_third(prompt, agent="assistant", timeout=90.0, owner_id=None, augment=True):
        if agent.endswith("customer_discovery"):
            raise RuntimeError("model timed out")
        return {"output": f"model text for {agent}", "served_by": "ollama:test", "is_external": False}
    monkeypatch.setattr(gw.gateway, "query_meta", _fail_third)
    evs = _events(client.post("/api/v1/intelligence/bdp", json={"challenge": "Hive weight monitor"}))
    res = {e["stage"]: e for e in evs if isinstance((e.get("data") or {}).get("stage_num"), int)}
    assert len(res) == 8 and res["customer_discovery"]["data"]["failed"] is True
    assert res["customer_discovery"]["data"]["served_by"] is None and "did not run" in res["customer_discovery"]["content"]
    assert res["market_analysis"]["data"]["served_by"] == "ollama:test"
    fin = evs[-1]["data"]
    assert fin["stages_completed"] == 7 and fin["failed_calls"] == 1 and fin["model_calls"] == 7 and fin["floor_calls"] == 0
    assert "1 did not run" in evs[-1]["content"] and "7 of 8 stages ran" in evs[-1]["content"]
    # S6.3 — nothing is announced as primed when nothing was
    assert not any(e["stage"] == "cognitive_prime" for e in evs)
    assert "Cognitive engines primed." not in (root / "agentic_core/api/intelligence.py").read_text(encoding="utf-8")

    # ── S4.4: the Nexus router — the floor never 'selects'; a model's one clear token does; ambiguity does not ──
    def _router(reply, served="ollama:test"):
        async def _q(prompt, agent="assistant", timeout=90.0, owner_id=None, augment=True):
            if agent == "nexus_router":
                return {"output": reply, "served_by": served, "is_external": False}
            return {"output": f"text for {agent}", "served_by": served, "is_external": False}
        return _q
    monkeypatch.setattr(gw.gateway, "query_meta", _router("Respond with ONLY one of: bdp, spi, apie, ddpie", "native"))
    eng, dec = asyncio.run(intel._nexus_auto_select("a varroa research study", "science", ""))
    assert eng == "bdp" and dec["decided"] is False and "no model was available" in dec["reason"]
    monkeypatch.setattr(gw.gateway, "query_meta", _router("spi"))
    assert asyncio.run(intel._nexus_auto_select("x", "science", ""))[0] == "spi"
    monkeypatch.setattr(gw.gateway, "query_meta", _router("Either bdp or spi would work"))
    eng, dec = asyncio.run(intel._nexus_auto_select("x", "science", ""))
    assert dec["decided"] is False and "more than one" in dec["reason"]
    monkeypatch.setattr(gw.gateway, "query_meta", _router("apied"))            # a substring is not a token
    assert asyncio.run(intel._nexus_auto_select("x", "science", ""))[1]["decided"] is False

    # the stream says it in words, on the floor
    monkeypatch.setattr(gw.gateway, "query_meta", _spy)
    evs = _events(client.post("/api/v1/intelligence/nexus", json={"challenge": "Design a research study on varroa", "domain": "science"}))
    sel = next(e for e in evs if e["stage"] == "engine_selected")
    assert sel["content"].startswith("Not selected: defaulted to BDP") and sel["data"]["decision"]["decided"] is False
    assert not any("Autonomously selecting" in e["content"] for e in evs)
    # an unknown engine name is not silently BDP
    evs_u = _events(client.post("/api/v1/intelligence/nexus", json={"challenge": "x", "engines": ["foo"]}))
    assert "'foo' is not an engine" in next(e for e in evs_u if e["stage"] == "engine_selected")["content"]

    # ── S4.5: the Nexus counts what ran and names what it is — one prompt headed by six lenses ─────────────
    cog = next(e for e in evs if e["stage"] == "cognitive_complete")
    assert cog["data"]["calls"] == 1 and cog["data"]["lenses"] == 6 and cog["data"]["served_by"] == "native"
    assert "Six cognitive engines activating" not in json.dumps(evs)
    fin = next(e for e in evs if e["stage"] == "nexus_complete")["data"]
    assert "cognitive_engines" not in fin and fin["cognitive_lenses"] == 6 and fin["engine_decided"] is False
    assert fin["run"]["calls"] == 12 and fin["run"]["floor_calls"] == 12      # lenses, MJM, routing, 8 stages, synthesis

    async def _syn_fails(prompt, agent="assistant", timeout=90.0, owner_id=None, augment=True):
        if agent == "nexus_synthesis":
            raise RuntimeError("down")
        return {"output": "x", "served_by": "native", "is_external": False}
    monkeypatch.setattr(gw.gateway, "query_meta", _syn_fails)
    evs = _events(client.post("/api/v1/intelligence/nexus", json={"challenge": "x", "activity": "authorship"}))
    fin = next(e for e in evs if e["stage"] == "nexus_complete")["data"]
    assert fin["layers_completed"] == 3 and fin["failed"] is True and fin["engine_decided"] is True

    # the collected Nexus (the fabric) keeps its lens, MJM and synthesis layers and says what served them
    monkeypatch.setattr(gw.gateway, "query_meta", _spy)
    col = asyncio.run(intel.run_intelligence_collected("a study", "science", "nexus"))
    assert "## Cognitive Lenses" in col["analysis"] and "## MJM Assessment" in col["analysis"] and "## Nexus Synthesis" in col["analysis"]
    assert col["provenance"]["calls"] == 12 and col["stages"] == 11     # 12 calls; the routing call adds no section
    from agentic_core.api.resource_fabric import _run_real_resource, _REGISTRY
    fr = asyncio.run(_run_real_resource("apie", {}, "a study", "science"))
    assert fr["served_by"] == "native" and fr["floor_calls"] == 9 and fr["stages"] == 9
    fs = asyncio.run(_run_real_resource("cognitive_cascade", {}, "a study", "science"))
    assert fs["served_by"] == "native" and fs["floor_calls"] == 3
    assert next(r for r in _REGISTRY if r["id"] == "cognitive_cascade")["name"] == "Cognitive Lenses + MJM"
    mj = client.post("/api/v1/intelligence/mjm", json={"problem": "a study"}).json()
    assert mj["provenance"]["calls"] == 2 and mj["status"] == "complete"

    # ── S5.5 / S6.2 / S6.3 / S5.6 / S7.6 / S7.7: the pages ─────────────────────────────────────────────────
    pages = root / "apps/workstation-superapp/src"
    so = (pages / "components/StageOutcome.tsx").read_text(encoding="utf-8")
    assert "d?.failed ? 'failed' : (d?.served_by && d.served_by !== 'native') ? (d.is_external ? 'external' : 'model') : 'floor'" in so
    assert "typeof (ev.data as StageData | undefined)?.stage_num === 'number'" in so
    for rel in ("pages/IntelligenceLab.tsx", "pages/synthesis/AuthorshipEngine.tsx",
                "pages/developers/DesignDevEngine.tsx", "pages/synthesis/SynthesisNexus.tsx"):
        src = (pages / rel).read_text(encoding="utf-8")
        assert "Nine Cognitive Engines" not in src and "CheckCircle2" not in src, rel
        assert "isStageResult" in src and "<StageMark" in src and "<StageBadge" in src and "{FLOOR_STAGE_NOTE}" in src, rel
        assert "Stage {i + 1}" not in src and "Of 8" not in src and "of 8\n" not in src, rel
        assert "!ev.stage.endsWith('_start')" not in src, rel     # the old name filter let 'config' through
    nx = (pages / "pages/synthesis/SynthesisNexus.tsx").read_text(encoding="utf-8")
    assert "AI selects the optimal engine" not in nx and "cognitive_engines ?? 6" not in nx and "layers_completed ?? 4" not in nx
    assert "decision?.decided === false" in nx
    assert "nine engines + MJM" not in (root / "agentic_core/api/intelligence.py").read_text(encoding="utf-8")

    # ── (refutation 1) a failed call is never output: never fed forward, never counted as ran, never listed ──
    prompts: dict = {}

    def _capture(fail_agents=(), returns=None):
        async def _q(prompt, agent="assistant", timeout=90.0, owner_id=None, augment=True):
            prompts.setdefault(agent, []).append(prompt)
            if agent in fail_agents:
                raise RuntimeError("down")
            if returns and agent in returns:
                return returns[agent]
            return {"output": f"ENGINEOUT {agent}", "served_by": "ollama:test", "is_external": False}
        return _q
    monkeypatch.setattr(gw.gateway, "query_meta", _capture(fail_agents=("cognitive_cascade_ai",)))
    prompts.clear()
    evs = _events(client.post("/api/v1/intelligence/nexus", json={"challenge": "x", "engines": ["spi"]}))
    for ag in ("mjm_orchestrator_ai", "nexus_synthesis"):
        assert "did not run —" not in prompts[ag][0], ag
    assert "ENGINEOUT nexus_spi_" in prompts["nexus_synthesis"][0], "the synthesis never saw the engine it names"
    prompts.clear()
    monkeypatch.setattr(gw.gateway, "query_meta", _capture(fail_agents=("cognitive_cascade_ai",)))
    ev_r = _events(client.post("/api/v1/intelligence/nexus", json={"challenge": "x"}))
    assert "did not run —" not in prompts["nexus_router"][0]
    sv = client.post("/api/v1/intelligence/solve", json={"problem": "x"}).json()
    assert sv["status"] == "partial" and "INKASHAF" not in sv["engines_used"] and "MJM" in sv["engines_used"], sv["engines_used"]
    assert all("did not run —" not in p for p in prompts["cognitive_solve"] + prompts["mjm_orchestrator_ai"])
    mj = client.post("/api/v1/intelligence/mjm", json={"problem": "x"}).json()
    assert mj["status"] == "partial" and mj["prime_failed"] is True and mj["cognitive_primed"] is False
    assert "did not run —" not in prompts["mjm_orchestrator_ai"][-1]
    # the text-only wrappers (Genesis) pass the failure marker; MJM still never judges it
    asyncio.run(intel._ai_mjm_lifecycle("x", "d", "[Cognitive lenses did not run — down]"))
    assert "did not run —" not in prompts["mjm_orchestrator_ai"][-1]
    from agentic_core.api.resource_fabric import _run_real_resource as _rr
    fm = asyncio.run(_rr("mjm", {}, "x", "d"))
    assert fm["prime_failed"] is True and fm["failed_calls"] == 1 and fm["status"] == "partial"
    monkeypatch.setattr(gw.gateway, "query_meta", _capture(fail_agents=tuple(f"BDP_{k}" for k, _l, _d in intel._BDP_STAGES)))
    fb = asyncio.run(_rr("bdp", {}, "x", "d"))
    assert fb["served_by"] is None and fb["failed_calls"] == 8 and fb["calls"] == 8 and fb["stages"] == 0

    # the gateway's own fallbacks (returned, not raised) and an empty reply are failures
    for bad in ("[native engine unavailable]", "[POLICY VIOLATION] The generated response was blocked by safety guardrails.", "  "):
        monkeypatch.setattr(gw.gateway, "query_meta", _capture(returns={"a": {"output": bad, "served_by": "native", "is_external": False}}))
        t, pv = asyncio.run(intel._staged_query("p", "a", "Stage"))
        assert pv["failed"] is True and pv["served_by"] is None and "did not run" in t, bad

    # external is stated per model, never over the in-house ones
    txt = intel._run_summary_text(2, [{"served_by": "claude", "is_external": True, "failed": False},
                                      {"served_by": "qwen", "is_external": False, "failed": False}])
    assert "claude 1 external, opt-in" in txt and "qwen 1 in-house" in txt, txt
    # no 'Complete' label over a run; the served status text names what these routes run
    bdp_ev = _events(client.post("/api/v1/intelligence/bdp", json={"challenge": "x"}))
    assert bdp_ev[-1]["label"] == "BDP finished" and not any(e["label"].endswith("Complete") for e in bdp_ev)
    st = client.get("/api/v1/intelligence/status").json()["cognitive_stack"]
    assert "UltimateCognitiveCascade" not in json.dumps(st) and "GaaSValidatorV4" not in json.dumps(st)
    assert "autonomously selected" not in (intel.synthesis_nexus.__doc__ or "") and "6 engines" not in (intel.synthesis_nexus.__doc__ or "")

    # the DDPIE stream itself (its own function): floor results with provenance, a truthful finish
    monkeypatch.setattr(gw.gateway, "query_meta", _spy)
    dd = _events(client.post("/api/v1/intelligence/design-dev", json={"system": "Hive weight monitor", "rigor": "exhaustive"}))
    ddr = [e for e in dd if isinstance((e.get("data") or {}).get("stage_num"), int)]
    assert [e["data"]["stage_num"] for e in ddr] == list(range(1, 10)) and all(e["data"]["served_by"] == "native" for e in ddr)
    assert all("hive weight monitor" in e["content"].lower() for e in ddr)
    assert dd[-1]["label"] == "DDPIE finished" and dd[-1]["data"]["floor_calls"] == 9 and "structured floor" in dd[-1]["content"]

    # a floor reply that is exactly one engine token still decides nothing
    monkeypatch.setattr(gw.gateway, "query_meta", _router("spi", "native"))
    assert asyncio.run(intel._nexus_auto_select("x", "science", ""))[1]["decided"] is False
    # an engine layer that failed wholly is not a layer that ran
    monkeypatch.setattr(gw.gateway, "query_meta", _capture(fail_agents=tuple(f"nexus_spi_{k}" for k, _l, _d in intel._SPI_STAGES)))
    fin = next(e for e in _events(client.post("/api/v1/intelligence/nexus", json={"challenge": "x", "engines": ["spi"]}))
               if e["stage"] == "nexus_complete")["data"]
    assert fin["layers_completed"] == 3, fin["layers_completed"]

    # pages: counts are of stages that RAN; trackers keyed by stage number; mixed layers are not hidden
    so = (pages / "components/StageOutcome.tsx").read_text(encoding="utf-8")
    assert "evs.filter(ev => stageOutcome(ev.data as StageData) !== 'failed').length" in so
    for rel in ("pages/IntelligenceLab.tsx", "pages/synthesis/AuthorshipEngine.tsx", "pages/developers/DesignDevEngine.tsx"):
        src = (pages / rel).read_text(encoding="utf-8")
        assert "byNum.get(i + 1)" in src and "{ranCount(stageEvents)} of {" in src and "% Complete" not in src, rel
    nx = (pages / "pages/synthesis/SynthesisNexus.tsx").read_text(encoding="utf-8")
    assert "if (k.some(x => x === 'failed')) return 'partial';" in nx
    assert "Object.values(outcomes).filter(o => o !== null && o !== 'failed').length" in nx
    rf = (pages / "pages/synthesis/ResourceFabric.tsx").read_text(encoding="utf-8")
    assert "(rr.calls && rr.failed_calls === rr.calls)" in rf and "rr.prime_failed ? 'prime did not run'" in rf
    ci = (pages / "pages/CognitionIntegration.tsx").read_text(encoding="utf-8")
    assert "Engines run:" not in ci and "solveRes.provenance?.cognitive_cascade" in ci and "<StageBadge" in ci

    # ── (refutation 2) no stage, layer, collector or caller feeds a failed call forward ──────────────────
    MARK = "did not run —"
    monkeypatch.setattr(gw.gateway, "query_meta", _capture(fail_agents=("BDP_value_proposition",)))
    prompts.clear()
    _events(client.post("/api/v1/intelligence/bdp", json={"challenge": "x"}))
    assert all(MARK not in p for a, ps in prompts.items() for p in ps), "a later BDP stage was fed a failed stage"
    for path, body, bad in (("/api/v1/intelligence/authorship", {"topic": "x"}, "apie_argument_architecture"),
                            ("/api/v1/intelligence/design-dev", {"system": "x"}, "ddpie_architecture_design")):
        monkeypatch.setattr(gw.gateway, "query_meta", _capture(fail_agents=(bad,)))
        prompts.clear()
        _events(client.post(path, json=body))
        assert all(MARK not in p for a, ps in prompts.items() for p in ps), path
    monkeypatch.setattr(gw.gateway, "query_meta", _capture(fail_agents=("cognitive_cascade_ai", "nexus_spi_literature_synthesis")))
    prompts.clear()
    nfin = next(e for e in _events(client.post("/api/v1/intelligence/nexus", json={"challenge": "x", "engines": ["spi"]}))
                if e["stage"] == "nexus_complete")["data"]
    assert all(MARK not in p for a, ps in prompts.items() for p in ps), "the Nexus fed a failed call forward"
    assert nfin["cognitive_lenses"] == 0, "the lens count credits a lens call that failed"
    monkeypatch.setattr(gw.gateway, "query_meta", _capture(fail_agents=("BDP_market_analysis",)))
    assert MARK not in asyncio.run(intel.run_intelligence_collected("x", "d", "bdp"))["analysis"]

    # Genesis calls the same helpers: the failed lens call is counted, never fed to the concept, never listed
    from agentic_core.api import genesis as _gen
    monkeypatch.setattr(gw.gateway, "query_meta", _capture(fail_agents=("cognitive_cascade_ai",)))
    prompts.clear()
    gj = client.post("/api/v1/genesis/journey", json={"problem": "varroa mites in my hives", "establish": False}).json()
    assert MARK not in prompts["genesis_concept"][0]
    assert gj["ai_provenance"]["served_by_agent"]["cognitive_cascade_ai"] == "failed"
    assert gj["ai_provenance"]["served_by_agent"]["mjm_orchestrator_ai"] == "ollama:test"
    assert "Inkashaf" not in gj["engines_used"] and "DDPIE" not in gj["engines_used"] and "BDP" not in gj["engines_used"]
    assert "MJM" in gj["engines_used"]
    assert "DDPIE (design)" not in json.dumps(client.get("/api/v1/genesis/status").json())

    # the learning loop never records a failed run as a success
    outs = []
    import agentic_core.api.operational_excellence as _oe
    monkeypatch.setattr(_oe, "record_outcome", lambda *a, **k: outs.append((a, k)))
    monkeypatch.setattr(gw.gateway, "query_meta", _capture(fail_agents=("cognitive_cascade_ai", "mjm_orchestrator_ai")))
    comp = client.post("/api/v1/resources/compose", json={"name": "w479 rig", "usage_area": "synthesis",
                                                           "resource_ids": ["mjm"], "config": {}}).json()
    client.post(f"/api/v1/resources/compositions/{comp['id']}/run", json={"objective": "judge x"})
    fr_out = [k for a, k in outs if a and a[0] == "fabric_resource"]
    assert fr_out and fr_out[-1]["success"] is False and fr_out[-1]["served_by"] == "none", fr_out
    monkeypatch.setattr(gw.gateway, "query_meta", _capture(returns={
        k: {"output": "x", "served_by": "native", "is_external": False} for k in [f"BDP_{s}" for s, _l, _d in intel._BDP_STAGES[:6]]}))
    fmix = asyncio.run(_rr("bdp", {}, "x", "d"))
    assert fmix["served_by_map"] == {"native": 6, "ollama:test": 2}, fmix["served_by_map"]
    assert "auto-selected engine" not in json.dumps(next(r for r in __import__("agentic_core.api.resource_fabric", fromlist=["_REGISTRY"])._REGISTRY if r["id"] == "nexus"))

    # pages: external is amber (never the in-house green); the engine layer is done only once the synthesis starts
    so = (pages / "components/StageOutcome.tsx").read_text(encoding="utf-8")
    assert "(d.is_external ? 'external' : 'model')" in so and "text-amber-400 shrink-0 ${className}`} aria-label=\"served by an external" in so
    nx = (pages / "pages/synthesis/SynthesisNexus.tsx").read_text(encoding="utf-8")
    assert "engine: synthesisStarted || nexusCompleteEvent ? layerOutcome(engineStageEvents) : null" in nx
    assert "{ranCount(engineStageEvents)} of" in nx and "=== 'failed' ? [] : (cognitiveEvent.data?.engines" in nx
    for rel in ("pages/IntelligenceLab.tsx", "pages/synthesis/AuthorshipEngine.tsx", "pages/developers/DesignDevEngine.tsx"):
        assert "outcome === 'external'\n                    ? 'bg-amber-500/10" in (pages / rel).read_text(encoding="utf-8"), rel
    assert "rr.served_by_map ? provenanceMapBadge(rr.served_by_map" in (pages / "pages/synthesis/ResourceFabric.tsx").read_text(encoding="utf-8")

    # ── (refutation 3) the lens/MJM calls never lend their server to the body; nothing-served is never a success ──
    async def _mixed(prompt, agent="assistant", timeout=90.0, owner_id=None, augment=True):
        return {"output": f"text for {agent}", "is_external": False,
                "served_by": "native" if agent.startswith("genesis_") else "ollama:test"}
    monkeypatch.setattr(gw.gateway, "query_meta", _mixed)
    gm = client.post("/api/v1/genesis/journey", json={"problem": "varroa mites in my hives", "establish": False}).json()
    assert set(gm["ai_provenance"]["body_served_by"]) == {"native"}, gm["ai_provenance"]["body_served_by"]   # the body's servers
    assert gm["ai_provenance"]["served_by"].get("ollama:test") == 2, gm["ai_provenance"]["served_by"]      # every call, shown
    assert gm["ai_provenance"]["served_by_agent"]["cognitive_cascade_ai"] == "ollama:test"
    async def _down(prompt, agent="assistant", timeout=90.0, owner_id=None, augment=True):
        raise RuntimeError("down")
    monkeypatch.setattr(gw.gateway, "query_meta", _down)
    gf = asyncio.run(_rr("genesis", {}, "x", "d"))
    assert gf["served_by"] is None and gf["calls"] and gf["failed_calls"] == gf["calls"], gf
    assert gf["failed_calls"] > 2, "only the lens and MJM failures were counted, not the journey's own stages"
    async def _ext(prompt, agent="assistant", timeout=90.0, owner_id=None, augment=True):
        return {"output": f"text for {agent}", "served_by": "ext:gpt", "is_external": True}
    monkeypatch.setattr(gw.gateway, "query_meta", _ext)
    assert asyncio.run(_rr("genesis", {}, "x", "d"))["is_external"] is True
    api_ts = (pages / "lib/api.ts").read_text(encoding="utf-8")
    assert "if (floorCalls >= modelCalls) return { label: `mostly structured floor" in api_ts
    assert "the owned model served most calls" not in api_ts
    nx = (pages / "pages/synthesis/SynthesisNexus.tsx").read_text(encoding="utf-8")
    assert nx.index("if (k.some(x => x === 'external')) return 'external';") < nx.index("if (k.every(x => x === 'model')) return 'model';")
    assert "Cognitive Cascade (6 engines)" not in (pages / "pages/synthesis/GenesisJourney.tsx").read_text(encoding="utf-8")

    # ── (refutation 4) a gate certifying text reads the servers of THAT text; the page shows every call ─────
    async def _cand_model(prompt, agent="assistant", timeout=90.0, owner_id=None, augment=True):
        model = agent.startswith("genesis_candidate") or agent.startswith("genesis_twin") or agent in (
            "cognitive_cascade_ai", "mjm_orchestrator_ai")
        return {"output": f"text for {agent}", "served_by": "ollama:test" if model else "native", "is_external": False}
    monkeypatch.setattr(gw.gateway, "query_meta", _cand_model)
    gb = client.post("/api/v1/genesis/journey", json={"problem": "varroa mites in my hives", "establish": False}).json()
    prov = gb["ai_provenance"]
    assert set(prov["body_served_by"]) == {"native"}, prov["body_served_by"]      # the saved text: floor only
    assert "ollama:test" in prov["served_by"], prov["served_by"]                   # the journey: every call shown
    # the §10 gate judges the body's servers: floor body text is not assessable, whatever else ran
    from agentic_core.vbs.quality import floor_served as _fs
    assert _fs(prov["body_served_by"]) is True and _fs(prov["served_by"]) is False
    gjs = (pages / "pages/synthesis/GenesisJourney.tsx").read_text(encoding="utf-8")
    assert "body_served_by ?? result?.ai_provenance?.served_by" in gjs and "calls did not run" in gjs

    # a failed body stage is recorded, is not assessable, and makes the composed run a failure
    async def _design_down(prompt, agent="assistant", timeout=90.0, owner_id=None, augment=True):
        if agent == "genesis_design":
            raise RuntimeError("down")
        return {"output": f"text for {agent}", "served_by": "ollama:test", "is_external": False}
    monkeypatch.setattr(gw.gateway, "query_meta", _design_down)
    gd = client.post("/api/v1/genesis/journey", json={"problem": "x", "establish": False}).json()
    assert gd["ai_provenance"]["served_by_agent"]["genesis_design"] == "failed"
    assert gd["stage_verifications"]["design"]["verified"] is None, gd["stage_verifications"]["design"]
    assert "ollama:test" in gd["ai_provenance"]["body_served_by"] and gd["ai_provenance"]["failed_calls"] >= 1
    gr = asyncio.run(_rr("genesis", {}, "x", "d"))
    assert gr["calls"] == 5 and gr["failed_calls"] == 1 and gr["served_by"] == "ollama:test", gr
    monkeypatch.setattr(gw.gateway, "query_meta", _down)
    gr2 = asyncio.run(_rr("genesis", {}, "x", "d"))
    assert gr2["calls"] == 5 and gr2["failed_calls"] == 5 and gr2["served_by"] is None, gr2

    # an established entity's shipped documents are gated on ITS body's servers, not the journey's other calls
    from agentic_core.api.vsb import _body_served_by as _vbsb
    _ent = {"concept": "c", "design": "d", "commercialisation": "m",
            "ai_provenance": {"served_by": {"native": 5, "ollama:test": 4},
                              "served_by_agent": {"genesis_concept": "native", "genesis_design": "native",
                                                  "genesis_commercial": "native", "genesis_candidate_1": "ollama:test",
                                                  "cognitive_cascade_ai": "ollama:test"}}}
    assert _vbsb(_ent) == {"native": 3}, _vbsb(_ent)


def test_w481_the_transformation_cascade_verifies_delivery_or_says_it_did_not(client, monkeypatch):
    """W481 — P1.18 FU-122 (sweep S1.0, S2.1, S6.0) and the two findings W477 left unregistered
    (S1.1/S8.1, registered here as FU-231): a stage check that cannot fail on a normal entity is a
    PRESENCE check, never a verification; a run is validated only when a DELIVERY check verified
    something; and the twin figure is a projection with its formula, never a simulation."""
    import json
    import pathlib
    root = pathlib.Path(__file__).resolve().parents[1]
    import agentic_core.api.transformation_orchestration as tx

    b = client.post("/api/v1/transformation/orchestrate",
                    json={"objective": "w481 guard", "scope": "workstation", "owner_id": "Rehan"}).json()
    stages = {s["step"]: s for s in b["cascade"]}
    v = b["validation"]

    # ── the checks that cannot fail are named as presence, and never verified ───────────────────
    for i in (1, 2, 4):
        assert stages[i]["checks"] == "presence" and stages[i]["verified"] is None, stages[i]
    # stage 3: a presence check with seeded objectives, nothing checked without them — never verified,
    # and the kind must match what its basis says it did
    assert stages[3]["verified"] is None, stages[3]
    assert stages[3]["checks"] == ("presence" if "seeded" in stages[3]["basis"] else "none"), stages[3]
    assert "presence only" in stages[1]["basis"] and "cannot fail" in stages[1]["basis"]
    assert "constant roster" in stages[2]["basis"]
    import uuid as _u481
    _scope = f"vsb:w481-{_u481.uuid4().hex[:8]}"
    client.post("/api/v1/board/chief/instruct", json={"instruction": "Open the second kitchen", "scope": _scope})
    _withobj = client.post("/api/v1/transformation/orchestrate", json={"scope": _scope}).json()
    _s3 = {s["step"]: s for s in _withobj["cascade"]}[3]
    assert _s3["verified"] is None and _s3["checks"] == "presence", _s3        # seeded objectives are not a verification
    assert "seeded" in _s3["basis"] and _withobj["validation"]["validated"] is None
    assert "static label" in stages[4]["basis"] and "no integration is checked" in stages[4]["basis"]
    # W508 (P2.8(5)/FU-232) — STAGE 6 NOW DECLARES A DELIVERY CHECK, and that is the point of the item.
    # W481 asserted it was "none", which was true and was the defect: `delivery_verified` filters
    # checks == "delivery", no stage declared it, so `validated` could never be True and the §5 loop closure
    # that advances a plan objective had never fired in production. Stage 6 (the Build-to-Order tier) now
    # delivers one artefact through the living-deliverables engine and verifies the RECORD LANDED.
    # `checks` is the KIND of check attempted; it stays "delivery" whenever a delivery was attempted, and is
    # "none" only when it could not be attempted at all — a kind field must not report an outcome (W491).
    # `stages` is a dict KEYED BY STEP ({s["step"]: s for s in cascade}), so stages[6] is step 6.
    assert stages[6]["checks"] == "delivery", stages[6]
    assert stages[6]["verified"] in (True, False, None) and str(stages[6]["basis"]).strip(), stages[6]
    assert stages[7]["checks"] == "decision" and stages[8]["checks"] == "artifact"
    assert "artifact only" in stages[8]["basis"]

    # ── the verdict: not assessable until a DELIVERY check verifies ─────────────────────────────
    assert v["validated"] is None and "DELIVERED" in v["validated_basis"], v
    # W508 — `delivery_verified_stages` is now populated only when a delivery both landed AND was attested by
    # the QMS gate. It is [] on a run whose deliverable landed unattested, which is a real state and not the
    # old "no stage even declares a delivery check". Asserted as a property of the verdict rather than a
    # constant, so the leg still holds when a run does attest.
    assert v["presence_stages"] >= 3
    _dv = v["delivery_verified_stages"]
    _delivery_stages = [st for st in stages.values() if st.get("checks") == "delivery"]
    assert _delivery_stages, "no stage declares a delivery check, so a run can never be validated"
    assert _dv == [st["step"] for st in _delivery_stages if st.get("verified") is True], (_dv, _delivery_stages)
    assert "End-to-end transformation cascade ran From Chief To Build-to-Order" not in v["report"]
    # the arithmetic in the sentence must add up: presence stages ARE not-assessable stages
    assert f"{v['not_assessable_stages']} stage(s) were not assessable" in v["report"]
    assert f"{v['presence_stages']} of them presence checks" in v["report"]
    assert "Not validated" in v["report"] and "presence checks that cannot fail" in v["report"]
    assert "DELIVERY check" in v["validated_rule"]

    # the rule itself, all four branches, on the function the route uses
    base = [{"step": 1, "tier": "Chief", "delegates_to": "Board", "verified": None, "checks": "presence", "basis": "b"},
            {"step": 8, "tier": "Twin", "delegates_to": "Validation", "verified": True, "checks": "artifact", "basis": "b"}]
    assert tx.summarise_validation(base, {"status": "allowed"}, 1)["validated"] is None
    delivered = [dict(base[0]), dict(base[1], checks="delivery")]
    got = tx.summarise_validation(delivered, {"status": "allowed"}, 1)
    assert got["validated"] is True and got["delivery_verified_stages"] == [8]
    assert tx.summarise_validation(delivered, {"status": "halted"}, 1)["validated"] is False
    failed = [dict(base[0], verified=False, checks="decision"), dict(base[1], checks="delivery")]
    assert tx.summarise_validation(failed, {"status": "allowed"}, 1)["validated"] is False

    # ── stage 7 reports the DECISION, not the filing ────────────────────────────────────────────
    import agentic_core.api.change_control as cc

    def _cca(status):
        async def _f(req):
            return {"cca_id": "cca-w481", "impact_tier": "low", "status": status}
        return _f
    for status, expect in (("approved", True), ("rejected", False), ("held", False), ("submitted", None)):
        monkeypatch.setattr(tx, "submit_change", _cca(status), raising=False)
        import agentic_core.api.change_control as _cc_mod
        monkeypatch.setattr(_cc_mod, "submit_change", _cca(status))
        got = client.post("/api/v1/transformation/orchestrate", json={"scope": "workstation"}).json()
        s7 = {s["step"]: s for s in got["cascade"]}[7]
        assert s7["verified"] is expect, (status, s7)
        monkeypatch.undo()

    # ── the twin: a projection, never a simulation, and never a trained model ───────────────────
    pj = b["digital_twin"]["projection"]
    assert "simulation" not in b["digital_twin"], "the run still emits a simulation"
    assert '"simulation"' not in json.dumps(b["cascade"]), "a stage still emits a simulation"
    assert "stable-and-improving" not in json.dumps(b)
    assert pj["formula"].startswith("coverage x") and pj["of"] == "api_surface_coverage"
    assert pj["projected"] <= pj["current"] and "not a simulation" in pj["note"]
    assert "improving" not in json.dumps(pj)
    assert not any("owner twin" in c.lower() for c in b["digital_twin"].get("components", stages[8]["output"]["components"]))
    model = client.get(f"/api/v1/twin/models/{stages[8]['output']['model_id']}").json()
    model = model.get("model") or model
    assert model.get("trained") is False and model.get("model_type") == "organisational_template"
    assert model.get("projections") and not model.get("simulations")
    assert "api_surface_coverage" in model["model_spec"] and "vision_realisation" not in model["model_spec"]

    # ── a write-back that cannot run is reported, never swallowed ───────────────────────────────
    import agentic_core.api.business_plan as _bp
    _real_sum = tx.summarise_validation

    def _delivered(cascade, governance, signals, native_cognition=None):
        out = _real_sum(cascade, governance, signals, native_cognition)
        out.update(validated=True, delivery_verified_stages=[8])
        return out

    def _boom(*a, **k):
        raise RuntimeError("plan store unavailable")
    monkeypatch.setattr(tx, "summarise_validation", _delivered)
    monkeypatch.setattr(_bp, "_save", _boom)
    _wb = client.post("/api/v1/transformation/orchestrate", json={"scope": _scope}).json()
    assert "plan store unavailable" in (_wb.get("plan_write_back_error") or ""), _wb.get("plan_write_back_error")
    assert _wb.get("plan_objective_advanced") is None
    monkeypatch.undo()

    # ── the pages: three states, the presence label, and the projection ─────────────────────────
    pages = root / "apps/workstation-superapp/src/pages"
    ck = (pages / "enterprise/VSBCockpit.tsx").read_text(encoding="utf-8")
    assert "validated === true ? 'validated'" in ck and "'not assessable'" in ck
    assert "presence check: " in ck and "projection (not a simulation)" in ck
    td = (pages / "TransformationDashboard.tsx").read_text(encoding="utf-8")
    assert "'NOT ASSESSABLE'" in td and "Twin projection" in td and "validated_basis" in td
    assert "orch.digital_twin.simulation" not in td
    ss = (pages / "enterprise/VSBSpawnStudio.tsx").read_text(encoding="utf-8")
    assert "'NOT ASSESSABLE'" in ss and "twin projection" in ss and "simulation.verdict" not in ss
    dt = (pages / "developers/DigitalTwins.tsx").read_text(encoding="utf-8")
    assert "{selected.projections && selected.projections.length > 0 && (" in dt
    assert "pre-W481 record" in dt
    # no chip may be coloured by the impossible verdict, and none may render it as a standalone badge
    assert "/improving/i.test(s.verdict || '') ? 'bg-emerald" not in dt   # no chip coloured by the impossible verdict
    assert "{s.verdict}\n" not in dt                                      # and none rendered as a standalone badge
    assert "recorded before W481" in dt

    # ── (refutation) every writer of the verdict, and the kinds that are not presence ────────────
    # stage 9 (the owned swarm) is a PROVENANCE check that can fail — never a presence check
    import agentic_core.ai.native.orchestrator as _native

    async def _swarm_ok(agent, context, stages, timeout=10.0):
        return {"stages": len(stages), "any_external": False, "final": "x",
                "trace": [{"role": s["role"], "served_by": "ollama:test", "output": "o"} for s in stages]}
    monkeypatch.setattr(_native, "swarm", _swarm_ok)
    deep = client.post("/api/v1/transformation/orchestrate", json={"scope": "workstation", "deep": True}).json()
    s9 = {s["step"]: s for s in deep["cascade"]}.get(9)
    assert s9 and s9["checks"] == "provenance" and s9["verified"] is True, s9
    assert deep["validation"]["presence_stages"] >= 3, deep["validation"]["presence_stages"]
    assert f"{deep['validation']['presence_stages']} of them presence checks" in deep["validation"]["report"]
    monkeypatch.undo()

    # a NOT ASSESSABLE run files neither a success nor a failure against the resource
    before = client.get("/api/v1/operations/outcomes").json()
    _rows = lambda d: [x for x in (d.get("outcomes") or d.get("rows") or []) if x.get("resource") == "transformation_orchestrate"]
    run2 = client.post("/api/v1/transformation/orchestrate", json={"scope": "workstation"}).json()
    assert run2["validation"]["validated"] is None and run2.get("outcome_not_recorded")
    #  W610 — BY ID, NOT BY COUNT. The listing is a window of the most recent rows over a store every xdist
    #  worker writes, so another worker's rows push older ones out and a COUNT of this resource's rows can
    #  fall with nothing this run did (measured: 5 -> 4 in W610's full suite). A new row from THIS run would sit
    #  at the top of the window, so "no new id of this resource" is the property and it cannot drift.
    _new_ids = {x["id"] for x in _rows(client.get("/api/v1/operations/outcomes").json())} - {x["id"] for x in _rows(before)}
    assert not _new_ids, ("a NOT ASSESSABLE run filed an outcome against the resource", _new_ids)

    # the branch ORDER: a checked failure outranks 'no delivery check'
    mixed = [{"step": 1, "tier": "Chief", "delegates_to": "Board", "verified": False, "checks": "decision", "basis": "b"},
             {"step": 2, "tier": "Twin", "delegates_to": "V", "verified": True, "checks": "artifact", "basis": "b"}]
    assert tx.summarise_validation(mixed, {"status": "allowed"}, 1)["validated"] is False
    # an unknown change-control verdict never verifies
    for status in ("withdrawn", "superseded", "escalated"):
        monkeypatch.setattr(_cc_mod, "submit_change", _cca(status))
        s7 = {s["step"]: s for s in client.post("/api/v1/transformation/orchestrate",
                                                json={"scope": "workstation"}).json()["cascade"]}[7]
        assert s7["verified"] is False, (status, s7)
        monkeypatch.undo()

    # the projection carries no verdict under ANY key
    assert set(pj) == {"of", "formula", "inputs", "projected", "current", "compared_with_current", "note"}, pj
    assert not any(isinstance(x, str) and ("improving" in x or "intervention" in x) for x in pj.values())

    # the module says the rule it now applies
    doc = (root / "agentic_core/api/transformation_orchestration.py").read_text(encoding="utf-8")
    assert "no stage measures delivery yet" in doc and "not a simulation" in doc
    assert "every ASSESSABLE stage verified and the\nconstitutional gate" not in doc

    # every page that shows a verdict shows three states, and ticks green only for a delivery check
    assert "{r.validated === true ? 'VALIDATED' : r.validated === false ? 'NOT VALIDATED' : 'NOT ASSESSABLE'}" in td
    assert ("{orch.validation.validated === true ? 'VALIDATED' : orch.validation.validated === false ? "
            "'NOT VALIDATED' : 'NOT ASSESSABLE'}") in td
    assert "'Not assessable — '" in ck
    assert "s.checks === 'delivery' ? 'text-emerald-400' : 'text-slate-400'" in ss
    assert "recorded before W481" in dt


def test_w483_a_keyword_screen_flags_and_never_clears(client):
    """W483 — P1.18, the §10/§11 class (FU-094, 095, 096, 099, 105, 115, 140).

    ONE rule, applied at every surface that reads a compliance screen: a word list may REFUSE a
    subject and may ESCALATE one for a human, but it can never CLEAR one. So no dimension passes
    off an empty match, no subject passes on its own vocabulary about itself, a lone harm term is
    escalated rather than recorded as a finding of harm, and the §10 bar records 'compliant' and
    'safe' as met only where a row could actually assess. The same principle at the faith surfaces:
    a halal status is never composed from prompt headings, and an ayah is the text of that ayah.
    """
    import asyncio
    import pathlib
    root = pathlib.Path(__file__).resolve().parents[1]
    from agentic_core.api.compliance import screen_compliance, assessed
    from agentic_core.compliance.ethical_engine import evaluate_ethics

    # 1. the lexicon cannot convict (R1.0 / R2.1)
    bees = ("I keep bees in Yorkshire and varroa mites are killing a third of my colonies each "
            "winter; I want an affordable organic treatment service for small-scale keepers")
    eth = evaluate_ethics(bees)
    human = next(d for d in eth["dimensions"] if d["dimension"] == "human")
    assert human["status"] == "review" and human.get("escalate") is True, human
    assert "killing" in human["reason"], human          # the matched term is NAMED, not just implied
    assert eth["overall"] != "fail", eth
    b = screen_compliance(bees)
    assert b["overall"] != "fail", b                    # the beekeeper is no longer a §11 failure
    _bethical = next(v for v in b["verdicts"] if v["framework"] == "ethical")
    assert _bethical.get("escalate") == ["human"], _bethical
    # (probe) the MATCHED TERM travels with the escalation — the row's reason is a per-dimension
    # summary, and without the term the person it is addressed to cannot see what triggered it
    assert _bethical.get("escalated_terms") == ["killing"], _bethical
    assert "matched: killing" in _bethical["reason"], _bethical["reason"]

    # 2. the lexicon cannot clear (R1.1 / R3.3)
    for d in evaluate_ethics("a database migration executed carefully over three weeks")["dimensions"]:
        assert d["status"] != "pass", d                 # nothing passes without a measured figure
    quiet = screen_compliance("a stationery shop selling notebooks and pens to local schools")
    for fw in ("regulatory", "ehs"):
        row = next(v for v in quiet["verdicts"] if v["framework"] == fw)
        assert row["status"] == "not_assessed" and row["coverage"] == "screen", row
        assert not assessed(row), row
    assert quiet["overall"] == "review" and quiet["compliant"] is None, quiet
    assert set(quiet["coverage_gaps"]) >= {"regulatory", "ehs"}, quiet

    # the ethical ROW reports the engine's own overall and the coverage it earned — it used to map
    # 'not_assessed' to 'pass', and it must not claim 'engine' coverage for a word-list result
    _qe = next(v for v in quiet["verdicts"] if v["framework"] == "ethical")
    assert _qe["status"] == "not_assessed" and _qe["coverage"] == "none", _qe
    assert not assessed(_qe), _qe
    _be = next(v for v in b["verdicts"] if v["framework"] == "ethical")
    assert _be["status"] == "review" and _be["coverage"] == "vocabulary", _be   # a lexicon hit
    assert not assessed(_be), _be                                              # which assesses nothing
    # NOTHING in the §11 screen can earn 'engine' today, and the screen says so rather than
    # borrowing a measurement of something else. (See the delivery-quality leg below: supplying QMS
    # figures does NOT promote the ethical row.)
    for subj in ("a stationery shop", "a fine wine subscription club",
                 "the plan involves unfair dismissal of staff", "a halal-certified meal service"):
        assert screen_compliance(subj)["assessed_by"] == [], (subj, screen_compliance(subj)["assessed_by"])
    # and a row that says 'not_assessed' can never be treated as a clearance, whatever its coverage
    assert not assessed({"framework": "ethical", "status": "not_assessed", "coverage": "engine"})

    # (refutation) a DELIVERY-QUALITY figure is not an ethical assessment. The QMS's section-coverage
    # number used to make the ethical row 'pass' with coverage 'engine', and being the only assessing
    # row it carried the whole §11 screen to 'pass' on a clean document.
    _withm = screen_compliance("A community meal service for elderly residents. " + ("Detail. " * 60),
                               delivery_metrics={"delivery_coverage": 0.9, "stub_found": False})
    _we = next(v for v in _withm["verdicts"] if v["framework"] == "ethical")
    assert _we["status"] != "pass" and _we["coverage"] != "engine", _we
    assert _withm["overall"] != "pass", _withm["overall"]
    assert not assessed(_we), _we
    _eth_m = evaluate_ethics("x" * 300, {"delivery_coverage": 0.9, "stub_found": False})
    assert _eth_m["overall"] == "not_assessed", _eth_m["overall"]     # the ethical dims said nothing
    assert _eth_m["delivery_quality"] == "pass" and _eth_m["delivery_quality_measured"] is True
    assert _eth_m["assessed"] is False, _eth_m

    # (refutation) the CONSTITUTIONAL row is a nine-intent substring gate — a word list. It may
    # refuse; it may not clear, and it must not be the row that carries a screen to 'pass'.
    for kind in ("entity", "intent", "distribution"):
        _ck = client.post("/api/v1/compliance/check", json={
            "subject": "A consultancy that optimises supplier negotiations for manufacturers in Leeds.",
            "kind": kind}).json()
        _cr = next(v for v in _ck["verdicts"] if v["framework"] == "constitutional")
        assert _cr["status"] != "pass" and _cr["coverage"] != "engine", (kind, _cr)
        assert _ck["overall"] != "pass", (kind, _ck["overall"])
        assert _ck["assessed_by"] == [], (kind, _ck["assessed_by"])
    # it can still REFUSE — and a refusal is a TERM that matched, so its coverage says 'vocabulary',
    # never 'engine' (the substring gate is a word list whichever way it comes out)
    _bad = client.post("/api/v1/compliance/check",
                       json={"subject": "wire_funds to an offshore account", "kind": "intent"}).json()
    _br = next(v for v in _bad["verdicts"] if v["framework"] == "constitutional")
    assert _br["status"] == "fail" and _br["coverage"] == "vocabulary", _br

    # (refutation) the CURATION gate: an escalated item is held for a person, not published. The
    # route reads its proposal store before screening, so the branch is asserted at the source and
    # its CONDITION is proved live — the screen really does return an escalation for this text.
    _dark = screen_compliance("Engagement booster. A dark pattern that locks users into a hidden "
                              "fee they cannot cancel.")
    assert any(v.get("escalate") for v in _dark["verdicts"]), _dark["verdicts"]
    assert _dark["overall"] != "fail", _dark["overall"]      # so ONLY the escalation can hold it
    _sw = (root / "agentic_core/api/swarm.py").read_text(encoding="utf-8")
    assert 'if screen["overall"] == "fail" or _esc:' in _sw, "curation no longer blocks on an escalation"
    assert '"curation_held_for_human_review"' in _sw

    # (refutation) genesis declares the weights it APPLIED, and says why when it applied none
    import agentic_core.api.genesis as _gmod
    _cand = _gmod._screen_candidate("A pragmatic halal community meal service with transparent "
                                    "pricing for elderly residents. " * 8)
    assert _cand["compliance"] is None and _cand["safety"] is None, _cand
    assert _cand["compliance_covered"] == [] and _cand["safety_covered"] == [], _cand
    _gsrc = (root / "agentic_core/api/genesis.py").read_text(encoding="utf-8")
    assert '"weights_applied"' in _gsrc and '{"form": 1.0, "compliance": None, "safety": None}' in _gsrc
    assert "the §11 screen ran and could assess nothing" in _gsrc
    assert "the §11 screen did not run for this candidate\"" not in _gsrc   # the false wording is gone

    # 3. a subject's own vocabulary is not a certification (R1.1)
    halal = screen_compliance("a halal-certified community meal service with transparent pricing")
    h = next(v for v in halal["verdicts"] if v["framework"] == "sharia_halal")
    assert h["status"] == "review", h                   # was 'pass' on the word 'halal' alone
    assert "the subject's own claim" in h["reason"] and "certifying body" in h["reason"], h
    val = next(d for d in evaluate_ethics("a charity that helps the community with care")["dimensions"]
               if d["dimension"] == "value")
    assert val["status"] == "not_assessed" and "its own claim" in val["reason"], val

    # 4. a refusal still refuses (the asymmetry is the point)
    for offer in ("a fine wine subscription club", "an online casino with lottery draws"):
        r = screen_compliance(offer)
        assert r["overall"] == "fail" and r["compliant"] is False, (offer, r)

    # 5. the §10 bar records what was established, not what was screened (R1.1 / R3.3)
    from agentic_core.vbs.quality import assure_delivery, SAFETY_FRAMEWORKS
    q = asyncio.run(assure_delivery("A community meal service for elderly residents. " + ("Detail. " * 60),
                                    label="deliverable"))["quality"]
    bar = q["bar_measured"]
    for name in ("compliant", "safe"):
        c = bar["criteria"][name]
        assert c["met"] is None and c["source"] == "screen" and c["measured"] is False, (name, c)
        assert "could not assess" in c["basis"] or "no row returned a pass" in c["basis"], (name, c)
    assert bar["screen_only"] >= 2 and "screen-only" in bar["summary"], bar

    # the case that decides the rule: EVERY row says 'pass', but none of them could assess. That is
    # not a compliant delivery, it is four word lists that matched nothing.
    from agentic_core.vbs.quality import _measure_bar
    _allpass = {"overall": "pass", "verdicts": [
        {"framework": f, "status": "pass", "coverage": "screen", "reason": "matched nothing"}
        for f in ("sharia_halal", "uk_legal", "regulatory", "ehs", "ethical")]}
    _b = _measure_bar(1.0, False, True, 0.8, _allpass, None)
    for name in ("compliant", "safe"):
        assert _b["criteria"][name]["met"] is None, (name, _b["criteria"][name])
        assert _b["criteria"][name]["source"] == "screen", (name, _b["criteria"][name])
    # and the converse: rows that DID assess and passed are a genuine met=True
    _real = {"overall": "pass", "verdicts": [
        {"framework": f, "status": "pass", "coverage": "engine", "reason": "assessed"}
        for f in ("sharia_halal", "uk_legal", "regulatory", "ehs", "ethical")]}
    _b2 = _measure_bar(1.0, False, True, 0.8, _real, None)
    assert _b2["criteria"]["compliant"]["met"] is True, _b2["criteria"]["compliant"]
    assert _b2["criteria"]["compliant"]["source"] == "gate", _b2["criteria"]["compliant"]

    # and when the screen's own rule cannot be imported, nothing is assessed — the helper fails
    # CLOSED, so a broken import can never turn into a clearance
    import sys as _sys
    from agentic_core.vbs import quality as _qmod
    _saved = _sys.modules.get("agentic_core.api.compliance")
    try:
        _sys.modules["agentic_core.api.compliance"] = object()      # no `assessed` attribute
        assert _qmod._assessed({"framework": "x", "status": "pass", "coverage": "engine"}) is False
    finally:
        if _saved is not None:
            _sys.modules["agentic_core.api.compliance"] = _saved
        else:
            _sys.modules.pop("agentic_core.api.compliance", None)

    # an engine ERROR is never quietly absorbed into a pass
    from agentic_core.api.compliance import _overall
    assert _overall([{"framework": "x", "status": "error", "coverage": "engine", "reason": "raised"},
                     {"framework": "y", "status": "pass", "coverage": "engine", "reason": "ok"}]) == "review"
    # the arithmetic adds up AND the buckets are disjoint and complete — the counts are the whole
    # point of this record, and 'screen_only' must come OUT of 'measured', not sit beside it
    assert bar["measured"] == len(bar["measured_criteria"]), bar
    assert bar["screen_only"] == len(bar["screen_only_criteria"]), bar
    assert not (set(bar["measured_criteria"]) & set(bar["screen_only_criteria"])), bar
    assert bar["measured"] + bar["attested"] + bar["not_measured"] == 16, bar
    assert bar["screen_only"] <= bar["not_measured"], bar
    assert all(bar["criteria"][k]["measured"] is True for k in bar["measured_criteria"]), bar
    assert all(bar["criteria"][k]["measured"] is False for k in bar["screen_only_criteria"]), bar
    assert q["compliance"]["coverage_gaps"], q["compliance"]             # carried, no longer dropped
    assert q["compliance"].get("basis"), q["compliance"]
    assert SAFETY_FRAMEWORKS == ("ethical", "ehs", "sharia_halal")

    # a §11 row that FAILS is still a measured False — a refusal is always reportable
    q2 = asyncio.run(assure_delivery("A fine wine subscription club for members. " + ("Detail. " * 60),
                                     label="deliverable"))["quality"]
    assert q2["bar_measured"]["criteria"]["compliant"]["met"] is False, q2["bar_measured"]["criteria"]

    # an ESCALATION is recorded on the delivery — downgrading the old lexicon 'fail' must not
    # downgrade the signal it carried
    q3 = asyncio.run(assure_delivery("A service for beekeepers whose colonies mites are killing. "
                                     + ("Detail. " * 60), label="deliverable"))["quality"]
    assert q3["compliance_escalations"] == ["ethical:human"], q3.get("compliance_escalations")
    assert q3["compliance"]["overall"] != "fail", q3["compliance"]["overall"]
    # (refutation) …and it REACHES A HUMAN. The 'fail' it replaced recorded with the immune system
    # and routed a material delivery to arms-length review; an escalation that only reached a
    # tooltip would be a quieter signal than the one it replaced.
    assert q3.get("compliance_routed_to_cca") is True, q3.get("compliance_routed_to_cca")
    assert q3.get("compliance_cca_id"), q3.get("compliance_cca_id")
    _cca = client.get(f"/api/v1/cca/{q3['compliance_cca_id']}").json()
    _txt = json.dumps(_cca)
    assert "escalation" in _txt.lower() and "NOT a finding of harm" in _txt, _txt[:400]
    from agentic_core.organism.immune import immune
    assert any("compliance_escalation" in str(e) for e in json.dumps(immune.status()).split()) \
        or immune.status(), immune.status()

    # (refutation) the two gates the downgrade had silently opened are shut again
    _hold = client.post("/api/v1/marketplace/listings", json={
        "name": "Engagement booster", "author": "t", "category": "Product", "price_wst": 1.0,
        "description": "A dark pattern that locks users into a hidden fee they cannot cancel."}).json()
    assert _hold.get("status") == "held", _hold
    assert (_hold.get("compliance") or {}).get("escalations"), _hold.get("compliance")

    # 6. one rule for every §11 chip, and it can say 'screen only' (S3.6)
    api = (root / "apps/workstation-superapp/src/lib/api.ts").read_text(encoding="utf-8")
    assert "export const complianceChip" in api
    assert "a keyword screen can refuse a subject, not clear one" in api
    # the qualifier is a CONDITION, not just a string that happens to appear in the file
    assert "overall === 'pass' && !assessedBy.length ? ' (screen only)'" in api
    # (refutation) a record written BEFORE this round has no coverage fields; the chip must say the
    # record predates the rule rather than assert that nothing assessed it
    assert "const legacy = !!overall && !hasCoverage;" in api
    assert "(recorded before W483)" in api
    pages = ["pages/Deliverables.tsx", "pages/synthesis/GenesisJourney.tsx", "pages/synthesis/ReactorStudio.tsx",
             "pages/synthesis/ResourceFabric.tsx", "components/organism/SwarmIntelligence.tsx",
             "pages/enterprise/VSBEconomy.tsx", "pages/marketplace/LivingMarketplace.tsx",
             # (refutation) the page the /check endpoint exists for, and the twelfth §11 read
             "pages/governance/ComplianceChecker.tsx", "pages/enterprise/ServiceContracts.tsx"]
    for rel in pages:
        src = (root / "apps/workstation-superapp/src" / rel).read_text(encoding="utf-8")
        assert "complianceChip(" in src, rel
        assert "complianceCls(" not in src, rel + " still derives its own §11 colour"

    # 7. the halal pre-assessment withholds a status it cannot produce (R5.2)
    hr = client.post("/api/v1/religion/halal-review", json={
        "product_name": "Choco bar", "product_description": "A chocolate bar",
        "ingredients": ["sugar", "cocoa butter", "gelatin", "E471"]}).json()
    if (hr.get("ai_provenance") or {}).get("served_by") == "native":
        assert hr["sections_withheld"] == ["Halal Status Assessment", "Critical Issues",
                                           "Flagged Ingredients"], hr
        assert hr.get("floor_note") and "accredited certifying body" in hr["floor_note"], hr
        body = hr["assessment"] or ""
        for token in ("COMPLIANT", "NON-COMPLIANT", "REQUIRES REVIEW", "Halal Status Assessment"):
            assert token not in body, (token, body[:400])
    scr = hr["ingredient_screen"]
    assert scr["verdict"] is None and scr["declared"] == 4, scr
    assert {f["ingredient"] for f in scr["flagged"]} == {"gelatin", "E471"}, scr   # the two that matter
    assert all(f["why"] for f in scr["flagged"]), scr
    assert scr["unmatched"] == ["sugar", "cocoa butter"], scr
    assert "NOT thereby acceptable" in scr["basis"], scr
    from agentic_core.api.religion import _screen_ingredients as _screen_ingredients_fn
    # (refutation) it must match the forms ingredients are actually DECLARED in — a screen that only
    # matches "e471" misses every real label, and the sub-classes are where the animal-derived
    # emulsifiers live
    _lbl = _screen_ingredients_fn(["E-471", "E 472a", "INS 471", "Emulsifier (E472e)", "sugar"])
    assert {f["ingredient"] for f in _lbl["flagged"]} == {"E-471", "E 472a", "INS 471",
                                                          "Emulsifier (E472e)"}, _lbl
    assert _lbl["unmatched"] == ["sugar"], _lbl
    rel_src = (root / "agentic_core/api/religion.py").read_text(encoding="utf-8")
    assert "## Halal Status Assessment (COMPLIANT" not in rel_src   # no verdict enum in a heading
    assert "_screen_ingredients" in rel_src
    # the judging sections are not even ASKED for on the floor — cutting them afterwards leaves the
    # scaffold in the interaction log and in AI memory (the W456 lesson at /qep/translation)
    _asked = rel_src.split('"## Halal Status Assessment', 1)[1].split("## Cross-Contamination", 1)[0]
    assert "if _model_expected else" in _asked, _asked[-200:]

    # 8. an ayah is the text of that ayah (R1.2)
    import agentic_core.religious_domain.api as rapi
    from agentic_core.religious_domain.api import (normalise_ayah_text, basmala_is_prepended,
                                                   _skeleton, _BOM, _TASHKEEL)
    assert basmala_is_prepended(112, 1) and not basmala_is_prepended(1, 1) \
        and not basmala_is_prepended(9, 1) and not basmala_is_prepended(2, 5)
    # Plain abjad stand-ins — scripture is never typed into a test. The prefix's LAST letter
    # carries a vowel mark (U+064E) because that is exactly where the cut goes wrong: cutting at
    # the base letter leaves its mark at the head of the ayah and strips it from the prefix, so
    # BOTH halves are wrong. The mark is ordinary Arabic typography here, not a quotation.
    prefix = "ابجد هوزَ"
    body = "حطي كلمن"

    async def _stub(edition="quran-uthmani"):
        return _BOM + prefix

    async def _none(edition="quran-uthmani"):
        return None

    orig = rapi._basmala_prefix
    try:
        rapi._basmala_prefix = _stub
        out, note = asyncio.run(normalise_ayah_text(_BOM + prefix + " " + body, 112, 1))
        assert out == body and note["basmala_separated"] is True, (out, note)
        assert note["basmala"] and _skeleton(note["basmala"]) == _skeleton(prefix), note
        # the cut lands on a CHARACTER boundary: the prefix keeps its own vowel mark and the ayah
        # does not begin with an orphaned one
        assert note["basmala"] == prefix, (note["basmala"], prefix)
        assert not _TASHKEEL.match(out), out
        # surah 1 and surah 9 are untouched, and the BOM still goes
        out1, note1 = asyncio.run(normalise_ayah_text(_BOM + prefix, 1, 1))
        assert out1 == prefix and note1["basmala_separated"] is False and _BOM not in out1, (out1, note1)
        out9, _n9 = asyncio.run(normalise_ayah_text(prefix + " " + body, 9, 1))
        assert out9 == prefix + " " + body, out9
        # an ayah that does not begin with the prefix is returned whole
        outx, notex = asyncio.run(normalise_ayah_text(body, 112, 1))
        assert outx == body and notex["basmala_separated"] is False, (outx, notex)
        # the boundary is never asserted when the reference text could not be sourced
        rapi._basmala_prefix = _none
        outn, noten = asyncio.run(normalise_ayah_text(prefix + " " + body, 112, 1))
        assert outn == prefix + " " + body and noten["basmala_separated"] is None, (outn, noten)
        assert "not checked" in noten["basmala_basis"], noten
    finally:
        rapi._basmala_prefix = orig
    rq = (root / "agentic_core/religious_domain/api.py").read_text(encoding="utf-8")
    assert "Scripture is never typed into this repository" in rq
    assert "reference text for the prefix IS ayah 1:1" in rq
    # EVERY read path normalises — fetch_ayah_arabic (what goes into prompts), get_surah, get_ayah.
    # One writer fixed is not the fix (W475): the defect is in whichever path is left unchanged.
    assert rq.count("normalise_ayah_text(") >= 4, rq.count("normalise_ayah_text(")
    for fn, tail in (("async def fetch_ayah_arabic", "# ── Quran Text"),
                     ("async def get_surah", "@router.get(\"/ayah/")):
        body = rq.split(fn, 1)[1].split(tail, 1)[0]
        assert "normalise_ayah_text(" in body, fn
    assert "normalise_ayah_text(ayah.get(\"text\", \"\"), surah_number, ayah_number" in rq  # get_ayah

    # 9. the screen states its own overall, and no consumer derives a second one
    ch = (root / "agentic_core/economy/charity.py").read_text(encoding="utf-8")
    assert 'verdict = screen.get("overall")' in ch, "charity derives its own overall again"
    gen = (root / "agentic_core/api/genesis.py").read_text(encoding="utf-8")
    assert "from agentic_core.vbs.quality import SAFETY_FRAMEWORKS" in gen
    assert 'coverage", "vocabulary") != "none"' not in gen, "genesis counts an empty screen as coverage"


def test_w485_a_veto_stops_the_journey_and_a_pack_says_whose_text_it_screened(client):
    """W485 — P1.18: FU-097, FU-101 and FU-128's remaining half.

    Three surfaces, one shape: a verdict that the next step ignores. A candidate the §11 screen
    VETOED still won and was carried into Design; a board pack whose narrative had not been composed
    was screened anyway and the verdict read as the enterprise's; and a Genesis journey left the
    platform as a .md with nothing saying what composed it.
    """
    import pathlib
    root = pathlib.Path(__file__).resolve().parents[1]

    # ── 1. a veto STOPS the journey (FU-097, ledger v5 R1.3) ────────────────────────────────────
    r = client.post("/api/v1/genesis/journey", json={
        "problem": "A fine wine subscription club with casino nights for members",
        "domain": "commerce"}).json()
    s5 = r["stage_5_model_simulate_rank"]
    assert s5["vetoed"], s5                               # the screen did veto
    assert s5["selected"] is None, s5["selected"]         # …so nothing was selected
    assert s5["blocked_by_screen"] is True, s5
    assert "no approach was selected" in (s5["blocked_reason"] or ""), s5["blocked_reason"]
    assert r["status"] == "blocked_by_screen", r["status"]
    assert "NOTHING SELECTED" in s5["selection_basis"], s5["selection_basis"]
    # nothing was composed FROM the vetoed approach, and each body field says why it is empty
    for key in ("phase_2_design_development", "stage_7_operational_intelligence",
                "phase_3_commercialisation"):
        assert "every candidate was vetoed" in (r[key] or ""), (key, (r[key] or "")[:120])
    assert r["established_vsb"] is None or (r["established_vsb"] or {}).get("blocked_by_screen") is True
    # …and a journey that ASKED to establish still establishes nothing — a living enterprise built
    # from a vetoed approach is the veto ignored one surface further on
    rb = client.post("/api/v1/genesis/journey", json={
        "problem": "An online casino with lottery draws and a wine club for members",
        "domain": "commerce", "establish": True, "name": "W485 Blocked"}).json()
    assert rb["status"] == "blocked_by_screen", rb["status"]
    assert (rb["established_vsb"] or {}).get("blocked_by_screen") is True, rb["established_vsb"]
    assert not (rb["established_vsb"] or {}).get("vsb_id"), rb["established_vsb"]

    # an ELIGIBLE journey is unaffected — the veto path must not have broken the ordinary one
    ok = client.post("/api/v1/genesis/journey", json={
        "problem": "Elderly residents in Bradford struggle to repair small household appliances",
        "domain": "community"}).json()
    ok5 = ok["stage_5_model_simulate_rank"]
    assert ok5["blocked_by_screen"] is False and ok5["selected"], ok5
    assert ok["status"] == "complete", ok["status"]
    assert "every candidate was vetoed" not in (ok["phase_2_design_development"] or "")

    # (refutation) THE VETO HOLDS AT THE WRITER THAT CREATES THE ENTERPRISE. The page's two-step
    # Establish path bypassed it entirely: a living VSB was born from the vetoed candidate and its
    # EVIDENCE.md called it the evidence-ranked selection.
    vet = client.post("/api/v1/genesis/establish", json={
        "problem": "x", "domain": "commerce",
        "selected_candidate": {"id": "c1", "screen": {"disqualified": True, "verdicts": {"sharia_halal": "fail"}}}})
    assert vet.status_code == 409, (vet.status_code, vet.text[:200])
    assert vet.json()["detail"]["error"] == "blocked_by_screen", vet.json()
    vets = client.post("/api/v1/genesis/establish/stream", json={
        "problem": "x", "domain": "commerce",
        "selected_candidate": {"id": "c1", "screen": {"disqualified": True}}})
    assert vets.status_code == 409, (vets.status_code, vets.text[:200])
    assert vets.json()["detail"]["error"] == "blocked_by_screen", vets.json()
    # BOTH establish writers carry the refusal — one guarded and one bare is the same defect
    gen_src = (root / "agentic_core/api/genesis.py").read_text(encoding="utf-8")
    assert gen_src.count("_refuse_vetoed_candidate(req)") == 2, gen_src.count("_refuse_vetoed_candidate(req)")
    # an ELIGIBLE candidate is not refused
    okest = client.post("/api/v1/genesis/establish", json={
        "problem": "A community appliance repair service", "domain": "community", "name": "W485 OK",
        "selected_candidate": {"id": "c1", "screen": {"disqualified": False}}})
    assert okest.status_code == 200, okest.text[:200]

    # (refutation) a blocked journey ATTESTS nothing and REPORTS no work it did not do
    bq = (r.get("quality_assurance") or {}).get("quality") or {}
    bar = bq.get("bar_measured") or {}
    for name in ("optimised", "ranked", "modelled", "simulated"):
        c = bar["criteria"][name]
        assert c["attested"] is False, (name, c)
        assert c["met"] is not True, (name, c)
        assert "blocked by the §11 screen" in (c.get("basis") or ""), (name, c)
    assert bq.get("qms_gate_passed") is None, bq.get("qms_gate_passed")   # nothing to measure
    for stage in ("design", "operations", "commercialisation"):
        sv = r["stage_verifications"][stage]
        assert sv.get("ran") is False and sv["verified"] is None, (stage, sv)
        assert "not run" in sv["basis"], (stage, sv)
    assert "No deliverable" in r["deliverable"], r["deliverable"]
    gj_src = (root / "apps/workstation-superapp/src/pages/synthesis/GenesisJourney.tsx").read_text(encoding="utf-8")
    assert "disabled={establishing || result.status === 'blocked_by_screen'}" in gj_src
    assert 'data-testid="establish-blocked"' in gj_src

    # ── 2. the board pack says WHOSE text it screened (FU-101, ledger v5 R2.3) ───────────────────
    est = client.post("/api/v1/genesis/establish", json={
        "problem": "A community appliance repair service for elderly residents",
        "domain": "community", "name": "W485 Repair Circle"}).json()
    vid = est.get("vsb_id") or (est.get("entity") or {}).get("vsb_id")
    assert vid, est
    bp = client.post(f"/api/v1/vsb/{vid}/board-pack").json()
    comp = ((bp.get("quality_assurance") or {}).get("quality") or {}).get("compliance") or {}
    if str(bp.get("narrative", "")).startswith("narrative pending"):
        assert comp.get("assessable") is False, comp
        assert "placeholder" in (comp.get("screened_subject") or ""), comp.get("screened_subject")
        assert "says nothing about the" in (comp.get("screened_subject") or ""), comp
    else:
        assert "composed narrative" in (comp.get("screened_subject") or ""), comp
    # the §10 bar never certifies the pack compliant off that screen (the W483 rule, here)
    bar = ((bp.get("quality_assurance") or {}).get("quality") or {}).get("bar_measured") or {}
    for name in ("compliant", "safe"):
        assert bar["criteria"][name]["met"] is not True, (name, bar["criteria"][name])
    # and the ENTITY's own latest §11 verdict travels on the pack, as its own question
    ec = bp.get("entity_compliance")
    assert isinstance(ec, dict) and "verdict" in ec and ec.get("basis"), ec
    assert ec["verdict"] in (None, "pass", "review", "fail"), ec
    # an UNREADABLE compliance history is not a verdict — it is a statement about the store
    import agentic_core.economy.living_vsbs as _lv
    _orig = _lv._latest_screen
    try:
        _lv._latest_screen = lambda _vid: _lv.HISTORY_UNREADABLE
        bp2 = client.post(f"/api/v1/vsb/{vid}/board-pack").json()
        ec2 = bp2["entity_compliance"]
        assert ec2["verdict"] is None, ec2
        assert "could not be read" in ec2["basis"], ec2
        assert ec2["known"] is False, ec2
        assert ec2.get("never_screened") is False, ec2      # "could not ask" is not "never screened"
    finally:
        _lv._latest_screen = _orig
    # (refutation) the entity verdict is ON the pack, so it is part of what the pack SAYS: a pack
    # whose entity verdict flipped must not still call itself "unchanged since" the older version
    _h0 = bp.get("content_hash")
    try:
        _lv._latest_screen = lambda _vid: "fail"
        bp3 = client.post(f"/api/v1/vsb/{vid}/board-pack").json()
        assert bp3["entity_compliance"]["verdict"] == "fail", bp3["entity_compliance"]
        assert bp3.get("content_hash") != _h0, (bp3.get("content_hash"), _h0)
    finally:
        _lv._latest_screen = _orig
    # (refutation) the page renders THREE entity states, never two
    assert "pack.entity_compliance.known === false" in gj_src, "the page collapses 'not known'"
    assert "'never screened'" in gj_src, gj_src.count("'never screened'")

    # a pending pack's OWN verdict is null at the field every consumer reads — `assessable: false`
    # beside an untouched 'review' had no reader at all
    if str(bp.get("narrative", "")).startswith("narrative pending"):
        assert comp.get("overall") is None and comp.get("compliant") is None, comp
        assert comp.get("overall_of_screened_text"), comp
        assert comp.get("sealed_note"), comp

    # ── 3. exported text carries its provenance (FU-128 / sweep S7.8) ───────────────────────────
    api = (root / "apps/workstation-superapp/src/lib/api.ts").read_text(encoding="utf-8")
    assert "export const provenanceLine" in api
    assert "composed by the deterministic native structured engine" in _code_only(api)
    # (refutation) an EMPTY provenance map served nothing — calling that 'floor-composed' is a
    # positive claim about a run that produced nothing; and the non-model set is {native, template}
    assert "no call is recorded as having served this output" in api
    assert "const NON_MODEL = ['native', 'template'];" in api
    assert "served.length > 0 && served.every(" in api
    # the floor SENTENCE itself is what the reader gets — assert it, not a paraphrase
    assert ("composed by the deterministic native structured engine, not by a model. It arranges the"
            in api), "the exported line no longer names the floor"
    assert "return NO_SERVED_CALL_LINE;" in api, "the empty-map guard is gone"
    # (refutation) the third copy path in My Work carries the label too
    mw = (root / "apps/workstation-superapp/src/pages/MyWork.tsx").read_text(encoding="utf-8")
    assert "provenanceHeader(rec) + v.output" in _code_only(mw)
    # BOTH the copy and the download carry it — one without the other is the same defect
    assert mw.count("provenanceHeader(rec) + rec.output") == 2, mw.count("provenanceHeader(rec) + rec.output")
    assert "provenanceLine(" in mw
    dt = (root / "apps/workstation-superapp/src/components/DomainTool.tsx").read_text(encoding="utf-8")
    # EVERY export path, counted — one path left bare is the same defect as all of them
    assert "await navigator.clipboard.writeText(provHeader() + exportText)" in _code_only(dt), "the copy is bare"
    assert "let content = provHeader() + exportText," in dt, "the md/txt export is bare"
    assert "const esc = (provHeader() + exportText).replace(" in dt, "the html export is bare"
    assert dt.count("provHeader()") >= 3, dt.count("provHeader()")   # its definition + copy + exports
    assert "provenanceLine(" in dt

    # ── 4. the pages show it (a payload nobody reads is not a fix) ──────────────────────────────
    gj = (root / "apps/workstation-superapp/src/pages/synthesis/GenesisJourney.tsx").read_text(encoding="utf-8")
    assert ">Blocked by the §11 screen</p>" in gj, "the blocked panel heading is gone"
    assert "nothing is carried into Design: the journey stops here." in gj
    assert ">vetoed</span>" in gj
    assert "data-testid=\"pack-entity-compliance\"" in gj
    assert "data-testid=\"pack-screened-subject\"" in gj

    # ── 5. the module states the rule it now applies ────────────────────────────────────────────
    gen = (root / "agentic_core/api/genesis.py").read_text(encoding="utf-8")
    assert "A veto that the next stage ignores is not a veto." in gen
    vsb = (root / "agentic_core/api/vsb.py").read_text(encoding="utf-8")
    assert "WHAT THE §11 SCREEN ACTUALLY READ" in vsb


def test_w486_the_plan_says_where_it_is_going_or_says_it_cannot(client):
    """W486 — the Owner asked to be able to track progress without asking.

    The pace is MEASURED from the register's own record (which round closed each row, which round
    found it) and projected in ROUNDS — the unit the register can count. The rules that keep it from
    becoming a promise: a rate over too few rounds is not assessable; a backlog that is not shrinking
    projects nothing; a one-time intake (an audit or a sweep) is named and excluded rather than
    averaged into an ongoing rate; and no date is ever produced.
    """
    import json
    import pathlib
    root = pathlib.Path(__file__).resolve().parents[1]
    from agentic_core import plan_followups as fu

    reg = json.loads((root / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))
    prompt = (root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    f = fu.forecast(reg, prompt)

    # 1. it is derived, and it says from what
    assert "measured from the register" in f["basis"] and "not a date" in f["basis"], f["basis"]
    assert f["window"]["count"] >= 1 and f["window"]["rounds"], f["window"]
    assert f["open_rows"] == sum(1 for r in fu.raw_items(reg)
                                 if isinstance(r, dict) and r.get("status") == "open")

    # 2. a one-time intake is NAMED and kept out of the ongoing rate, never silently averaged in
    st = f["steady"]
    assert set(st["rounds"]) | set(st["excluded"]) == set(f["window"]["rounds"]), (st, f["window"])
    if st["excluded"]:
        assert f["rate_used"]["source"].startswith("steady"), f["rate_used"]
        #  THE INVARIANT IS ON THE **FOUND** RATE, NOT THE CLOSED RATE (W592). This asserted
        #  `st["closed_per_round"] >= f["window"]["closed_per_round"]`, on the assumption that a one-time
        #  intake closes fewer rows than average. W592 registered MILESTONE M1's twenty findings - so it
        #  is correctly excluded - and also closed TWO rows, the pair the Owner had already ruled on and
        #  W588 left open. Two is above the steady 1.8, so the exclusion moved the closed rate DOWN and
        #  the assertion failed at 1.8 >= 1.83 with nothing wrong anywhere. A round is named an intake
        #  because of what it FOUND, so that is the only rate whose direction the exclusion guarantees.
        assert st["found_per_round"] <= f["window"]["found_per_round"], (
            "excluding a one-time intake RAISED the found rate, which contradicts why it was excluded - "
            "the round was named an intake because it registered an unusual number of rows",
            st, f["window"])

    # 3. a projection is arithmetic over the rate it names — checkable, not asserted
    import math
    if f["assessable"]:
        rate = f["rate_used"]["closed_per_round"]
        assert rate > 0 and f["rate_used"]["net_per_round"] > 0, f["rate_used"]
        # W495 — the rate was measured on rows BUILD ROUNDS closed, so it covers the rows riding a
        # plan item. An Owner-decision row rides none and no round can close one, so it is counted
        # apart and not projected; `open_rows` is every open row, and the two populations add up.
        assert f["open_rows_scheduled"] + f["open_rows_awaiting_owner"] == f["open_rows"], f
        assert len(f["awaiting_owner_ids"]) == f["open_rows_awaiting_owner"], f
        assert f["all_rows_rounds_projected"] == math.ceil(f["open_rows_scheduled"] / rate), f
        assert "ACROSS EVERY ITEM" in f["basis"], f["basis"]
        # W493 - this leg asserted the NEXT item's projection was its own rows over the OVERALL rate,
        # which IS the defect: a class-wide batch closes rows on five or six items at once, so the gate
        # read "35 open rows ~ 4 rounds" while the five rounds on record closed 4, 3, 1, 0 and 2 of its
        # rows - 2.0 per round, about eighteen. An item is projected at ITS OWN measured rate, or it
        # carries no number at all. A borrowed rate is a figure about a population its label denies.
        _full = f["window"]["closed_per_round"]
        nx = f["next_item"]
        if nx and nx["open_rows"]:
            assert nx.get("basis"), nx
            if nx["rounds_projected"] is None:
                assert "not projected" in nx["basis"], nx
            else:
                assert nx["rate_used"] > 0, nx
                assert nx["rounds_projected"] == math.ceil(nx["open_rows"] / nx["rate_used"]), nx
                assert "OWN rate" in nx["basis"], nx
                # one item can never close faster than every item together, over the same rounds
                assert nx["rate_used"] <= _full + 1e-9, (nx, _full)
        for x in f["by_item"]:
            assert x.get("basis"), x
            if x["open_rows"] and x["rounds_projected"] is not None:
                assert x["rounds_projected"] == math.ceil(x["open_rows"] / x["rate_used"]), x
                assert x["rate_used"] <= _full + 1e-9, (x, _full)
    else:
        assert f["not_assessable_because"], f
        assert f["all_rows_rounds_projected"] is None, f

    # 4. THE REFUSALS. A rate with too little evidence, and a backlog that is not shrinking, both
    #    project NOTHING — these are the legs that stop this becoming a guess.
    thin = {"items": [{"id": "FU-1", "status": "done", "closed_by": "W001", "slot": "P1.1",
                       "title": "t", "why": "w", "source": "W001", "severity": "low", "files": []}]}
    assert fu.forecast(thin, prompt)["assessable"] is False
    assert "at least" in (fu.forecast(thin, prompt)["not_assessable_because"] or "")

    growing = {"items": []}
    for i in range(6):                       # six rounds, each closing 1 and finding 5
        rnd = f"W{900 + i}"
        growing["items"].append({"id": f"FU-c{i}", "status": "done", "closed_by": rnd, "slot": "P1.1",
                                 "title": "t", "why": "w", "source": rnd, "severity": "low", "files": []})
        for j in range(5):
            growing["items"].append({"id": f"FU-o{i}-{j}", "status": "open", "slot": "P1.1",
                                     "title": "t", "why": "w", "source": rnd, "severity": "low", "files": []})
    # 3b. THE DISCRIMINATING CASE, because the real register cannot produce it on demand. Six build
    #     rounds; P2.6 closes one row every round, P2.4 closes one in two rounds only. The overall rate
    #     is 8/6 = 1.33/round. P2.6 must be projected at its own 1.0 - nine rounds, not the seven the
    #     overall rate would give - and P2.4 must carry NO number, because two rounds cannot measure a
    #     rate. Borrowing 1.33 would put its ten open rows at eight rounds on a record that supports
    #     no figure at all.
    mixed = {"items": []}
    # W505 - DERIVED, NOT NAMED, and bound before the first loop that uses it. This check has broken twice by
    # naming a specific open item (W496's comment records the first: "this used P1.18, which the same round
    # marked DONE"), so the item is taken from the plan it was handed. The rule under test is "an item is
    # projected at ITS OWN rate", which needs ANY open item and never a particular one.
    #  W575 (FU-365) — BOTH slots are derived now, and from ANY open item rather than from P2.
    #  W505 derived this one and left the SECOND as the literal "P2.4", under the comment below
    #  saying a third naming would break on the round that closed it. W575 closed P2.4 and it did.
    #  Scoping to one phase would bring the fault back the moment that phase has a single item left.
    _open_slots = [i["slot"] for i in fu.plan_items(prompt) if not i["done"]]
    assert len(_open_slots) >= 2, (
        "this check needs two open items to project at different rates, and the plan has "
        f"{len(_open_slots)}", _open_slots)
    _proj, _slow = _open_slots[0], _open_slots[1]
    for i in range(6):
        rnd = f"W{800 + i}"
        mixed["items"].append({"id": f"FU-a{i}", "status": "done", "closed_by": rnd, "slot": _proj,
                               "title": "t", "why": "w", "source": "W700", "severity": "low", "files": [],
                               "found": "2026-01-01", "owner_gated": False})
        if i < 2:
            mixed["items"].append({"id": f"FU-b{i}", "status": "done", "closed_by": rnd, "slot": _slow,
                                   "title": "t", "why": "w", "source": "W700", "severity": "low", "files": [],
                                   "found": "2026-01-01", "owner_gated": False})
    # W505 - DERIVED, NOT NAMED, because this has now broken twice for the same reason. W496's comment
    # records the first time ("this used P1.18, which the same round marked DONE: a done item is not in
    # `by_item`, so the check died on a KeyError") and its fix was to name P2.6 instead - which W505 closed.
    # Naming a third item would break on the round that closes that one. The rule under test is "an item is
    # projected at ITS OWN rate", which needs ANY open item and never a particular one.
    for j in range(9):
        mixed["items"].append({"id": f"FU-p{j}", "status": "open", "slot": _proj, "item": _proj,
                               "title": "t", "why": "w", "source": "W700", "severity": "low", "files": [],
                               "found": "2026-01-01", "owner_gated": False})
    for j in range(10):
        mixed["items"].append({"id": f"FU-q{j}", "status": "open", "slot": _slow, "item": _slow,
                               "title": "t", "why": "w", "source": "W700", "severity": "low", "files": [],
                               "found": "2026-01-01", "owner_gated": False})
    m = fu.forecast(mixed, prompt)
    assert m["assessable"] is True, m["not_assessable_because"]
    assert m["rate_used"]["closed_per_round"] == 1.33, m["rate_used"]     # 8 closed over 6 rounds
    _mi = {x["slot"]: x for x in m["by_item"]}
    assert _mi[_proj]["rate_used"] == 1.0, _mi[_proj]
    assert _mi[_proj]["rounds_projected"] == 9, _mi[_proj]               # 9 rows at 1.0, not 6 at 1.5
    assert _mi[_slow]["rounds_projected"] is None, _mi[_slow]            # 2 of 6 rounds cannot measure
    assert "not projected" in _mi[_slow]["basis"], _mi[_slow]
    # and the rendered block carries the refusal rather than a borrowed figure
    _mr = fu.render_forecast(mixed, prompt)
    assert "each at its OWN measured rate" in _mr, _mr
    assert f"{_slow} 10r\u2014" in _mr, _mr

    g = fu.forecast(growing, prompt)
    assert g["assessable"] is False, g["rate_used"]
    assert "not shrinking" in (g["not_assessable_because"] or ""), g["not_assessable_because"]
    assert g["all_rows_rounds_projected"] is None, g

    # 5. it is rendered into BOTH plan docs, in lockstep, and the check enforces that
    rendered = fu.render_forecast(reg, prompt)
    for doc in ("docs/FABLE_DELIVERY_PROMPT.md", "docs/WORKSTATION_IDBO_LIVING_PLAN.md"):
        text = (root / doc).read_text(encoding="utf-8")
        assert fu.PACE_BEGIN in text and fu.PACE_END in text, doc
        assert fu._block(text, fu.PACE_BEGIN, fu.PACE_END) == rendered, doc
    assert fu.LOCKSTEP_PACE_PROMPT in fu.LOCKSTEP and fu.LOCKSTEP_PACE_LIVING in fu.LOCKSTEP
    # the lockstep is ENFORCED: a stale block is a reported problem, not a silent drift
    stale = fu.splice(prompt, "WHERE THIS IS GOING (stale)", fu.PACE_BEGIN, fu.PACE_END)
    assert fu.LOCKSTEP_PACE_PROMPT in fu.check(reg, stale, None), "a stale PACE block is not caught"

    # 6. it is SERVED, so the page can show it without anyone running a script
    body = client.get("/api/v1/plan/followups").json()
    assert body.get("available") is True, body.get("reason")
    sf = body["forecast"]
    assert sf["assessable"] == f["assessable"]
    assert sf["open_rows"] == f["open_rows"]
    summary = (client.get("/api/v1/plan").json().get("followups") or {}).get("pace") or {}
    assert "assessable" in summary, summary

    # 7. the page renders it, and renders the REFUSAL when there is no projection
    td = (root / "apps/workstation-superapp/src/pages/TransformationDashboard.tsx").read_text(encoding="utf-8")
    assert 'data-testid="plan-pace"' in td
    assert 'data-testid="plan-pace-not-assessable"' in td
    assert "not a date and not a promise" in td
    assert "One-time intake excluded:" in td


def test_w487_the_plan_proposes_the_round_not_just_the_row(client):
    """W487 — the third planning leg: PRIORITY says which row, PACE says how fast, BATCH says what a
    ROUND should take.

    The register's rows are one per emitting FILE; the sweep's classes run ACROSS files. That mismatch
    is why a round that picks the next row closes two or three while a round that builds one mechanism
    and sweeps every consumer closed seven. The batch is proposed from the evidence the rows already
    cite — and it never counts a row it cannot close.
    """
    import json
    import pathlib
    root = pathlib.Path(__file__).resolve().parents[1]
    from agentic_core import plan_followups as fu

    reg = json.loads((root / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))
    prompt = (root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    b = fu.batches(reg, prompt)

    # 1. it is grouped from the rows' OWN evidence, and says so
    assert "the sweep class each row's own evidence cites" in b["basis"], b["basis"]
    assert set(fu.SWEEP_CLASSES) == {f"C{i}" for i in range(1, 11)}, sorted(fu.SWEEP_CLASSES)
    assert all(x["class"] in fu.SWEEP_CLASSES and x["what"] == fu.SWEEP_CLASSES[x["class"]]
               for x in b["batches"]), [x["class"] for x in b["batches"]]

    # 2. CLOSES means closes: every row counted cites this class and NO other
    raw = {r["id"]: r for r in fu.raw_items(reg) if isinstance(r, dict)}
    for x in b["batches"]:
        for rid in x["closes"]:
            assert fu.row_classes(raw[rid]) == [x["class"]], (rid, fu.row_classes(raw[rid]), x["class"])
        for rid in x["partial"]:
            cs = fu.row_classes(raw[rid])
            assert x["class"] in cs and len(cs) > 1, (rid, cs)
        assert not (set(x["closes"]) & set(x["partial"])), x["class"]
        assert x["closes_count"] == len(x["closes"]) and x["partial_count"] == len(x["partial"])

    # 3. a row is never counted as closable by two batches at once
    everywhere = [rid for x in b["batches"] for rid in x["closes"]]
    assert len(everywhere) == len(set(everywhere)), "a row is counted closable by more than one batch"

    # 4. rows citing NO class are listed, never guessed at or silently dropped
    open_ids = {r["id"] for r in fu.raw_items(reg) if isinstance(r, dict) and r.get("status") == "open"}
    # W495 — an OWNER decision row rides no plan item, so it appeared in no bucket at all until this
    # round: not batched, not partial, not unclassed, not counted. A batch report that omits a
    # population cannot be checked for coverage, so they are listed apart and counted here.
    counted = (set(everywhere) | {rid for x in b["batches"] for rid in x["partial"]}
               | set(b["unclassed"]) | set(b["awaiting_owner"]))
    assert counted == open_ids, sorted(open_ids ^ counted)[:6]
    assert all(fu.row_classes(raw[rid]) == [] for rid in b["unclassed"])

    # 5. it is a SUGGESTION, and scoping to an item really scopes it
    p118 = fu.batches(reg, prompt, "P1.18")
    assert all(s == "P1.18" for x in p118["batches"] for s in x["slots"]), p118["batches"]
    assert p118["rows"] <= b["rows"]
    assert sum(x["closes_count"] for x in p118["batches"]) <= sum(x["closes_count"] for x in b["batches"])

    # 6. the largest batch is named beside the PACE projection — a projection with no lever is no use
    rendered = fu.render_forecast(reg, prompt)
    if b["batches"]:
        top = b["batches"][0]
        assert "BIGGEST BATCH:" in rendered, rendered
        assert top["class"] in rendered and str(top["closes_count"]) in rendered
        # …and it really is the largest
        assert top["closes_count"] == max(x["closes_count"] for x in b["batches"])
    for doc in ("docs/FABLE_DELIVERY_PROMPT.md", "docs/WORKSTATION_IDBO_LIVING_PLAN.md"):
        assert fu._block((root / doc).read_text(encoding="utf-8"), fu.PACE_BEGIN, fu.PACE_END) == rendered, doc

    # 7. an empty register proposes nothing rather than an empty promise
    empty = fu.batches({"items": []}, prompt)
    assert empty["batches"] == [] and empty["rows"] == 0
    assert "No row in scope cites a sweep class" in fu.render_batches({"items": []}, prompt)

    # 8. a class is counted where the row CITES it, never where it merely appears in prose.
    #    W487 asserted the opposite half of this: that a bare "C5" anywhere in the text counted. W489
    #    found what that cost — a register row DISCUSSING the batch mechanism ("C3 closes 4 rows; C7
    #    and C1 are smaller") was counted into three batches it had no defect in, so the batch sizes
    #    the plan proposes included rows by accident. The undefined-class half of the rule is
    #    unchanged and still asserted below.
    fake = {"items": [{"id": "FU-9", "status": "open", "slot": "P1.18", "severity": "low", "files": [],
                       "title": "a C11 and C99 finding", "why": "cites C11, C99 and C5", "source": "W999"}]}
    assert fu.row_classes(fake["items"][0]) == [], fu.row_classes(fake["items"][0])
    #    …and the three forms the sweep actually writes ARE read, including alongside an undefined one
    cited = {"id": "FU-9b", "status": "open", "slot": "P1.18", "severity": "low", "files": [],
             "title": "sweep x.py: 2 Tier-1 truth defects (C5,C11) — something",
             "why": "S1.2 C3: the page shows; lists S8.1 (C8, a cockpit card)", "source": "W999"}
    assert fu.row_classes(cited) == ["C3", "C5", "C8"], fu.row_classes(cited)

    # 9. it is served — and a grouping that RAISED is never served as a grouping
    body = client.get("/api/v1/plan/followups").json()
    assert body.get("available") is True, body.get("reason")
    served = body["batches"]
    assert [x["class"] for x in served["batches"]] == [x["class"] for x in b["batches"]]
    import agentic_core.plan_followups as _pf
    _orig = _pf.batches
    try:
        def _boom(*_a, **_k):
            raise RuntimeError("grouping failed")
        _pf.batches = _boom
        broke = client.get("/api/v1/plan/followups").json()["batches"]
        assert broke["batches"] == [], broke
        assert "raised" in broke["basis"], broke["basis"]
    finally:
        _pf.batches = _orig

    # 10. the CLI exposes it (a mechanism nobody can run is not a mechanism)
    cli = (root / "scripts/followups.py").read_text(encoding="utf-8")
    assert 'sub.add_parser("batches"' in cli
    assert 'if args.cmd == "batches":' in cli and "render_batches(reg, prompt, args.item" in cli

    # 11. the plan RECORDS the measured round shape, so it is not re-argued each round
    fp = (root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    # W489 — B1 gained its second half: the batch is taken REPO-WIDE, not scoped to the gate item
    # (the same class closed 4 rows inside P1.18 and 12 across all items).
    assert "B1 TAKE A BATCH, NOT A ROW — AND TAKE IT REPO-WIDE, NOT GATE-SCOPED." in fp
    assert "--item filter costs rows for nothing" in fp, "the plan still tells the round to scope the batch"
    assert "batches --item <the open item>" not in fp
    assert "The full suite is 46 minutes over 392 tests" in fp      # the measurement, not an impression
    assert "Never two pytest runs at once" in fp                    # the corruption rule, kept
    # W519 — B3 was AMENDED on measured evidence, so this assertion is updated rather than deleted, and
    # it is STRONGER than the line it replaces. The old heading, "OVERLAP WHAT DOES NOT SHARE STATE",
    # licensed running a refutation workflow CONCURRENTLY with the full suite. W518 measured what that
    # costs: a 48-agent fleet beside a suite took it to 1h48m34s against a measured 53m20s and returned
    # red on two timing-sensitive tests that both passed in 81s alone. Isolation of STATE is not
    # isolation of TIMING. The rule now says the opposite, and this pins both the new instruction and
    # the measurement behind it, so neither can be quietly dropped.
    assert "B3 NOTHING HEAVY RUNS BESIDE THE SUITE" in fp
    assert "OVERLAP WHAT DOES NOT SHARE STATE." not in fp, (
        "the falsified instruction is back in the plan")
    assert "2.04x slowdown" in fp, "B3 states its rule without the measurement that produced it"


def test_w488_the_page_and_the_api_say_the_same_thing(client):
    """W488 — P1.18, the C5 batch: FU-136, FU-137, FU-142, FU-143, FU-149, FU-150.

    The first round chosen by the new batch mechanism (W487): six rows, one class — a second writer or
    the reached page disagrees with the API. Six different surfaces, one question in each: does what the
    reader is told match what the system did?
    """
    import json
    import pathlib
    root = pathlib.Path(__file__).resolve().parents[1]

    # ── FU-136 (S2.3): the apex tier reads the Owner's words and nothing else ───────────────────
    # A refuter's fair catch: the first cut of this leg asserted SOURCE TEXT for a behaviour this suite
    # already knows how to spy on (the authorship stages do it). It now watches the actual call.
    import agentic_core.ai.gateway as _gwmod
    _seen: list = []
    _real_meta = _gwmod.gateway.query_meta

    async def _augment_spy(prompt, agent="assistant", timeout=90.0, owner_id=None, augment=True):
        _seen.append({"agent": agent, "augment": augment})
        return await _real_meta(prompt, agent=agent, timeout=timeout, owner_id=owner_id, augment=augment)

    _gwmod.gateway.query_meta = _augment_spy
    try:
        bi = client.post("/api/v1/board/chief/instruct", json={
            "owner": "Rehan", "instruction": "w488 apex leg", "scope": "w488apex", "cascade_to_ceo": True})
        assert bi.status_code == 200, bi.text[:200]
        assert _seen, "the apex tier made no model call at all — the spy proves nothing"
        assert all(c["augment"] is False for c in _seen), \
            f"the Board's prompt carried cross-request recall as the Owner's intent: {_seen}"
        # …and the SAME Chief twin on the plan's own generate path (the refuter's second writer)
        _seen.clear()
        gp = client.post("/api/v1/business-plan/generate", json={"scope": "w488apex"})
        assert gp.status_code in (200, 503), gp.text[:200]
        if gp.status_code == 200:
            assert _seen and all(c["augment"] is False for c in _seen), \
                f"the plan's Chief twin carried recall into text it PERSISTS: {_seen}"
    finally:
        _gwmod.gateway.query_meta = _real_meta

    # every generation-class caller in the repo, not just the two this round touched (W332's own rule).
    # The avatar conversation is the single deliberate exception and says so in place.
    import re as _re
    _missing = []
    for _p in sorted((root / "agentic_core").rglob("*.py")):
        _s = _p.read_text(encoding="utf-8")
        for _m in _re.finditer(r"query_meta\(", _s):
            _i, _d = _m.end(), 1
            while _d and _i < len(_s):
                _d += 1 if _s[_i] == "(" else (-1 if _s[_i] == ")" else 0)
                _i += 1
            if "augment" not in _s[_m.start():_i]:
                _missing.append(f"{_p.name}:{_s[:_m.start()].count(chr(10)) + 1}")
    assert not _missing, f"generation-class callers still inject cross-request recall: {_missing}"
    _av = (root / "agentic_core/avatars/api.py").read_text(encoding="utf-8")
    # W490 (refutation) — this pinned the WRONG half of a contradiction: the comment said "the ONE
    # generation caller" four lines above its own text naming two, and the suite asserted both.
    assert "augment=True" in _av and "one of the TWO callers that keep recall" in _av
    assert "the ONE generation caller" not in _av

    # ── FU-137 (S3.10): the Owner's plan is read whole or refused, NEVER replaced ───────────────
    import agentic_core.api.business_plan as bp
    from agentic_core.config import StoreUnavailable
    assert client.get("/api/v1/business-plan?scope=workstation").status_code == 200
    p = bp._path("workstation")
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text('{"scope": "workstation", "objectives": [', encoding="utf-8")   # truncated
    try:
        r = client.get("/api/v1/business-plan?scope=workstation")
        assert r.status_code == 503, (r.status_code, r.text[:160])
        assert "could not be read whole" in str(r.json()["detail"]), r.json()
        assert "never replaced" in str(r.json()["detail"]), r.json()
        # …and a WRITE against the unreadable plan neither succeeds nor overwrites it
        w = client.post("/api/v1/business-plan/objective", json={
            "scope": "workstation", "title": "w488", "kpi": "k", "timeline": "t", "owner_role": "CEO"})
        assert w.status_code == 503, (w.status_code, w.text[:160])
        assert p.read_text(encoding="utf-8") == '{"scope": "workstation", "objectives": [', "the plan was overwritten"
        # the loader itself refuses rather than returning a fresh plan
        try:
            bp._load("workstation")
            raise AssertionError("_load returned a plan for an unreadable file")
        except StoreUnavailable:
            pass
    finally:
        p.unlink(missing_ok=True)

    # ── FU-142 (S1.8): a form the caller claimed but the registry overrode is SAID, not swallowed ──
    from agentic_core.economy import living_vsbs as lv
    lv.register("vsb-w488guard", "W488 Guard", entity_type="waqf_ltd_hybrid", owner="Rehan")
    wf = client.get("/api/v1/economy/waterfall?vsb_id=vsb-w488guard&entity_type=charity").json()
    assert wf["entity_type"] == "waqf_ltd_hybrid", wf            # the W313 binding still holds
    assert wf["claim_ignored"] is True and wf["claimed_entity_type"] == "charity", wf
    assert "fixed at registration" in wf["form_note"], wf["form_note"]
    cyc = client.post("/api/v1/economy/cycle", json={
        "vsb_id": "vsb-w488guard", "entity_type": "charity", "revenue": 100}).json()
    att = cyc["attribution"]
    assert att["claim_ignored"] is True and att["claimed_entity_type"] == "charity", att
    assert "was NOT used" in att["basis"], att["basis"]
    st = client.get("/api/v1/economy/status?vsb_id=vsb-w488guard&entity_type=charity").json()
    assert st["attribution"]["claim_ignored"] is True, st["attribution"]
    # a claim that MATCHES the registry is not reported as ignored — the disclosure is not noise
    ok = client.get("/api/v1/economy/waterfall?vsb_id=vsb-w488guard&entity_type=waqf_ltd_hybrid").json()
    assert ok["claim_ignored"] is False and ok["claimed_entity_type"] is None, ok

    # ── FU-143 (S2.4): the page does not promise what the floor cannot give ─────────────────────
    ms = (root / "apps/workstation-superapp/src/pages/enterprise/ManagementSystemsHub.tsx").read_text(encoding="utf-8")
    assert "AI-generated, immediately usable" not in ms
    assert "frames to complete, not finished documents" in ms and "review every clause" in ms
    ms_api = (root / "agentic_core/api/management_systems.py").read_text(encoding="utf-8")
    assert "Provides AI-generated management system documentation" not in ms_api

    # ── FU-149 (S13.3): the tooltip names what the button opens ─────────────────────────────────
    fc = (root / "apps/workstation-superapp/src/components/layout/FourthColumn.tsx").read_text(encoding="utf-8")
    assert 'title="External AI Agents"' not in fc
    assert 'title="In-house assistant' in fc

    # ── FU-150 (S5.7): the page does not claim provisioning the API denies ──────────────────────
    bto_api = (root / "agentic_core/catalog/bto.py").read_text(encoding="utf-8")
    assert '"provisioned": False' in bto_api          # the API's own answer, unchanged
    bto = (root / "apps/workstation-superapp/src/pages/BTOCatalog.tsx").read_text(encoding="utf-8")
    assert "Provisioning Sovereign Infrastructure" not in bto
    assert "Bootstrapping L1–L12 fabric" not in bto
    assert "Blueprint Provisioned" not in bto
    assert "Composing the blueprint" in bto and "nothing is provisioned yet" in bto
    assert "blueprint.provisioned === false" in bto   # it reads the API rather than asserting

    # ══ W488 REFUTATION LEGS — 25 verified findings against this round's own diff ════════════════
    # Five adversarial lenses over the diff, each finding independently verified in its own worktree.
    # What they found was not a set of unrelated slips: every one was THIS round's class re-committed
    # inside the round's own fix. The disclosure invented a claim; the refusal reached a page that
    # crashed instead of repeating it; the fixed writer had siblings. One leg each.

    # ── the refusal REACHES the Owner: the page says which file and that nothing was written ────
    bpx = (root / "apps/workstation-superapp/src/pages/enterprise/BusinessPlan.tsx").read_text(encoding="utf-8")
    # A vacuous blind found this leg's first anchor useless: the bare string `if (!r.ok)` also appears in
    # three UNRELATED handlers in this same file, so breaking the LOADER's check left the guard green.
    # The anchor is now the loader's own branch, body and all.
    assert ("      if (!r.ok) {\n        setPlan(null);\n        setPlanErr(" in bpx
            and 'data-testid="plan-unreadable"' in bpx), \
        "the page turns the plan's 503 into a render crash instead of the refusal's own words"
    assert "plan?.objectives || []" in bpx, "the render still indexes into a body the API refused to give"
    ckp = (root / "apps/workstation-superapp/src/pages/enterprise/VSBCockpit.tsx").read_text(encoding="utf-8")
    assert 'data-testid="cockpit-plan-unreadable"' in ckp and "setPlanErr(p.err)" in ckp, \
        "the cockpit's plan tab renders blank where the API refused and said why"

    # ── /list is a route too: an unreadable plan is LISTED as unreadable, never dropped ─────────
    p2 = bp._path("w488list")
    p2.write_text('{"scope": "w488list", "objectives": [', encoding="utf-8")   # truncated
    try:
        lst = client.get("/api/v1/business-plan/list")
        assert lst.status_code == 200, lst.text[:160]
        body = lst.json()
        row = next((r for r in body["plans"] if r.get("scope") == "w488list"), None)
        assert row is not None, "a present-but-unreadable plan vanished from the listing"
        assert row["readable"] is False and row["objectives"] is None, row
        assert "could not be read whole" in row["note"], row
        assert body["unreadable_total"] >= 1 and body["counts_cover"].startswith("the plans listed as readable"), body
    finally:
        p2.unlink(missing_ok=True)

    # ── the scope is reduced to a FILENAME (a backslash must not escape the store) ──────────────
    assert bp._key(r"..\..\config") == "config", bp._key(r"..\..\config")
    assert bp._path(r"..\..\x").parent == bp._STORE, bp._path(r"..\..\x")

    # ── a directive that could NOT land says why, instead of a bare objectives_added: 0 ─────────
    pv = bp._path("w488veto")
    pv.write_text('{"scope": "w488veto", "objectives": [', encoding="utf-8")
    try:
        bi2 = client.post("/api/v1/board/chief/instruct", json={
            "owner": "Rehan", "instruction": "w488 unreadable-plan directive", "scope": "w488veto",
            "cascade_to_ceo": True})
        assert bi2.status_code == 200, bi2.text[:200]
        rec = bi2.json()
        assert rec["objectives_added"] == 0, rec["objectives_added"]
        why = str(rec.get("objectives_not_added_reason") or "")
        assert "could not be read whole" in why and "were NOT added" in why, rec
        assert pv.read_text(encoding="utf-8") == '{"scope": "w488veto", "objectives": [', "the plan was overwritten"
    finally:
        pv.unlink(missing_ok=True)

    # ── the disclosure NEVER invents a claim: no entity_type sent → no claim reported ───────────
    # Three vacuous blinds found the first cut of these legs blind: they used a VSB registered as the
    # PLATFORM DEFAULT, so "the caller stated nothing" and "the default was read as the caller's claim"
    # produce identical output. A non-default registration separates them.
    from agentic_core.economy.entities import DEFAULT_ENTITY as _DEF
    assert _DEF != "charity", "this leg needs a registered form the platform default is not"
    lv.register("vsb-w488nodefault", "W488 Non-default", entity_type="charity", owner="Rehan")
    nd = client.get("/api/v1/economy/waterfall?vsb_id=vsb-w488nodefault").json()
    assert nd["entity_type"] == "charity" and nd["claim_ignored"] is False, nd
    assert nd["claimed_entity_type"] is None and "no form was requested" in nd["form_note"], nd
    ndc = client.post("/api/v1/economy/cycle", json={"vsb_id": "vsb-w488nodefault", "revenue": 10}).json()
    assert ndc["attribution"]["claim_ignored"] is False, ndc["attribution"]
    assert ndc["attribution"]["claimed_entity_type"] is None, ndc["attribution"]
    assert "was NOT used" not in ndc["attribution"]["basis"], ndc["attribution"]["basis"]
    # A cycle for an entity NOT on the living roster takes the other branch of the same disclosure: with
    # no form stated, the source is the PLATFORM's default, never "caller_claimed" — a form attributed to
    # a caller who stated none. (A vacuous blind found no leg read this field at all.)
    offc = client.post("/api/v1/economy/cycle", json={"vsb_id": "vsb-w488-offroster", "revenue": 10}).json()
    assert offc["attribution"]["entity_type_source"] == "platform_default", offc["attribution"]
    assert offc["attribution"]["claim_ignored"] is False, offc["attribution"]
    offc2 = client.post("/api/v1/economy/cycle", json={
        "vsb_id": "vsb-w488-offroster", "entity_type": "sole", "revenue": 10}).json()
    assert offc2["attribution"]["entity_type_source"] == "caller_claimed", offc2["attribution"]
    # …and an entity unknown to BOTH stores, with no claim, gets the platform default SAID to be the
    # platform's — not a caller's claim of nothing (the last-resort branch no leg reached).
    from agentic_core.api.economy import _resolve_entity_type as _rt0
    assert _rt0("vsb-w488-unknown-entity", None) == (_DEF, "platform_default"), \
        _rt0("vsb-w488-unknown-entity", None)
    assert _rt0("vsb-w488-unknown-entity", "sole") == ("sole", "caller_claimed")
    st2 = client.get("/api/v1/economy/status?vsb_id=vsb-w488guard").json()
    a2 = st2["attribution"]
    assert a2["claim_ignored"] is False and a2["claimed_entity_type"] is None, a2
    assert "no form was requested" in a2["form_note"], a2["form_note"]
    cyc2 = client.post("/api/v1/economy/cycle", json={"vsb_id": "vsb-w488guard", "revenue": 10}).json()
    assert cyc2["attribution"]["claim_ignored"] is False, cyc2["attribution"]
    assert "was NOT used" not in cyc2["attribution"]["basis"], cyc2["attribution"]["basis"]

    # ── W313's binding holds for a VSB known ONLY to the vsb store (the key a writer actually sets) ──
    import agentic_core.api.vsb as vsb_mod
    from agentic_core.api.economy import _resolve_entity_type
    vsb_mod._save_vsb({"vsb_id": "vsb-w488store", "name": "W488 Store",
                       "economy": {"entity_type": "charity_cio"}})
    form, src = _resolve_entity_type("vsb-w488store", "sole_trader")
    assert (form, src) == ("charity_cio", "vsb_store"), (form, src)
    # …and a stored entity with NO recorded form is refused, never bound to the caller's claim
    vsb_mod._save_vsb({"vsb_id": "vsb-w488noform", "name": "W488 No Form"})
    import fastapi
    try:
        _resolve_entity_type("vsb-w488noform", "sole_trader")
        raise AssertionError("a claim became the binding for a stored entity with no recorded form")
    except fastapi.HTTPException as e:
        assert e.status_code == 422 and "records no legal/economic form" in str(e.detail), e.detail

    # ── the page that caused the FU-142 row renders the disclosure ──────────────────────────────
    econ = (root / "apps/workstation-superapp/src/pages/enterprise/VSBEconomy.tsx").read_text(encoding="utf-8")
    assert 'data-testid="form-claim-ignored"' in econ and 'data-testid="form-in-force"' in econ, \
        "the picker still shows the Owner's pick as the form in force"
    assert "const inForce = wf?.entity_type ?? null" in econ and "wf?.claim_ignored" in econ
    assert "(inForce || entity) === t.id" in econ, "the highlighted card is still the claim, not the binding"

    # ── the remaining provisioning claims on the BTO page and the finished-document promises ────
    assert "Provision your blueprint" not in bto and "'Provisioning...'" not in bto
    assert "AI-Mediated Provisioning" not in bto
    assert "Composing the blueprint..." in bto and "AI-Mediated Specification" in bto
    assert ms.count("A draft frame to complete and review — not a certifiable document.") == 6, \
        "a management-system panel still promises a finished document"
    for _promise in ("Generate an ISO 9001:2015-aligned Quality Management System with policies",
                     "Generate a comprehensive risk register covering"):
        assert _promise not in ms, _promise


def test_w489_a_reading_is_measured_or_it_is_not_a_reading(client):
    """W489 — P1.18 + P2.4 + P2.8 + P2.9, the C3 batch taken REPO-WIDE (the first round to do so).

    Twelve rows, one rule: A NUMBER OR LABEL IS PRESENTED AS A READING ONLY WHEN IT WAS COMPUTED FROM
    THE THING IT NAMES. Otherwise it is absent, or labelled as what it actually is — a constant, a
    default, a different quantity, or work that is planned and has not run.

    The four shapes the sweep found: a hard-coded constant shown as a measurement (EMS +85%, a fixed
    XAI rationale, JSX literals, 'Confidence 1'); a fallback shown as a result (a classification
    nobody made at 70% confidence, an unparseable value plotted as zero); a different quantity
    relabelled (process-lifetime CO2 as this run's, host CPU idleness as 'Work', a platform-wide rate
    as this entity's); and a claim about a pipeline that does not run that way (nine engines that are
    six, MJM re-running the same six, term frequencies called 'Key factors').
    """
    import pathlib
    import re
    root = pathlib.Path(__file__).resolve().parents[1]

    # ── FU-138 (S12.1): a document nobody classified is not filed as if somebody had ────────────
    import agentic_core.api.career as career_mod
    src = (root / "agentic_core/api/career.py").read_text(encoding="utf-8")
    assert 'category = "cv_history"\n        confidence = 0.7' not in src, \
        "the except branch still hard-codes a category and a 70% confidence"
    assert 'confidence = 0.7' not in src and 'data.get("confidence", 0.85)' not in src
    assert '"uncategorized"' in src and "isinstance(conf_raw, (int, float))" in src
    # …and the branches behave, not merely read well. A vacuous blind showed the source check above
    # passes while an individual branch still coerces to a real category, so each is exercised.
    import agentic_core.api.career as _career
    _real_ai_text = _career.ai_text

    async def _reply(payload):
        async def _f(prompt, agent, **kw):
            return payload, {"served_by": "native", "is_external": False}
        return _f

    import asyncio as _aio
    for _payload, _why in (
            ('{"category": "astrology_charts", "confidence": 0.99, "reasoning": "sure"}', "unknown category"),
            ('{"category": "cv_history", "confidence": 0.93, "reasoning": "read it"}', "a real confidence"),
            ('{"category": "cv_history", "reasoning": "no confidence given"}', "no confidence"),
            ('not json at all', "unparseable reply")):
        _career.ai_text = _aio.get_event_loop_policy().new_event_loop().run_until_complete(_reply(_payload))
        try:
            up = client.post("/api/v1/career/uploads/auto",
                             files={"file": ("w489.txt", b"a plain document", "text/plain")})
            assert up.status_code == 200, (up.status_code, up.text[:160])
            cl = up.json()["classification"]
            if _why == "a real confidence":
                # the third state: a number the model actually returned is reported, not discarded
                assert cl["category"] == "cv_history", (cl, _why)
                assert cl["confidence"] == 0.93, (cl, _why)
            elif _why == "no confidence":
                # a real category the model DID name is kept; the absent confidence is absent, not 0.85
                assert cl["category"] == "cv_history", (cl, _why)
                assert cl["confidence"] is None, (cl, _why)
            else:
                assert cl["category"] == "uncategorized", (cl, _why)
                assert cl["confidence"] is None, (cl, _why)
        finally:
            _career.ai_text = _real_ai_text
    app_studio = (root / "apps/workstation-superapp/src/components/employment/ApplicationStudio.tsx").read_text(encoding="utf-8")
    assert "confidence: number | null;" in app_studio, "the page cannot represent 'not classified'"
    # (refutation) the branch must key on the CATEGORY: a file the classifier really did categorise
    # but gave no confidence for was being reported as "NOT classified", contradicting the same
    # screen's Unresolved list, which keys on the category.
    assert "n.category !== 'uncategorized' ?" in app_studio, (
        "the page decides 'classified' from the confidence rather than the category")
    assert "was NOT classified" in app_studio and "(no confidence was returned)" in app_studio
    assert "content is analysed and automatically filed into the matching category above." not in app_studio

    # ── FU-156 (S5.10): an unreadable value is refused, never charted as zero ───────────────────
    studio = (root / "apps/workstation-superapp/src/pages/synthesis/ReactorStudio.tsx").read_text(encoding="utf-8")
    assert "isNaN(value) ? 0 : value" not in studio, "the page still manufactures a zero"
    assert "parts[0] || '?'" not in studio
    assert "rejected.push({ line: i + 1, text: line })" in studio
    assert "no zero was supplied on your behalf" in studio
    assert "if (rejected.length) {" in studio, "the rejected lines are collected and never surfaced"
    # (refutation) `setResult(null);` and "never invents numbers" were BOTH present before this
    # change, so asserting them proved nothing. The reject branch's own body is the anchor.
    assert "Not charted — ${rejected.length} line" in studio
    assert "rejected.map(r => `line ${r.line}" in studio
    assert "never invents numbers" in studio          # the promise stays, and is now true

    # ── FU-217 / FU-218 (S5.13, S5.14): no literals under a 'nothing was returned' note ─────────
    bmd = (root / "apps/workstation-superapp/src/pages/synthesis/BusinessModelDashboard.tsx").read_text(encoding="utf-8")
    for literal in ("15% Market Share", "28% Gain", "2.4x Multiplier", "30% reduction in attrition",
                    "Adoption Velocity", "QEP Simulation Parameters"):
        assert literal not in bmd, f"a hard-coded simulation figure survives: {literal}"
    assert 'data-testid="no-sim-parameters"' in bmd and 'data-testid="no-market-strategy"' in bmd
    player = (root / "apps/workstation-superapp/src/pages/synthesis/PresentationPlayer.tsx").read_text(encoding="utf-8")
    assert "Autonomous Narration Active" not in player, "the player claims narration it cannot play"
    assert "% Synchronized" not in player and "% of slide time" in player
    # and the claim is false for a reason the guard can check: nothing here plays audio
    # (refutation) the first cut asserted two strings that had NEVER been in this file, and the
    # comment beside it claimed the guard checked the imports too. It does now: every module this
    # player imports is read, and none of them may reach an audio API either.
    _player_imports = re.findall(r"from '([^']+)'", player)
    _audio_re = re.compile(r"speechSynthesis|new Audio\(|<audio|SpeechSynthesisUtterance")
    assert not _audio_re.search(player), "the player itself reaches an audio API"
    _local = [i for i in _player_imports if i.startswith(".")]
    _checked = 0
    for _imp in _local:
        _p = (root / "apps/workstation-superapp/src/pages/synthesis" / _imp).resolve()
        for _cand in (_p.with_suffix(".tsx"), _p.with_suffix(".ts")):
            if _cand.exists():
                assert not _audio_re.search(_cand.read_text(encoding="utf-8")), _cand.name
                _checked += 1
    assert _checked == len(_local), (f"{len(_local) - _checked} local import(s) of the player were "
                                     f"not read, so the no-audio claim is not checked")

    # ── FU-146 (S2.0): six engines run; three are PLANNED (P3.13) and never counted as run ──────
    cog = (root / "agentic_core/cognitive")
    # W524 (P3.13) — the tripwire that stood here ("a meta engine exists — update this guard") fired as
    # designed: all three now exist and COMPUTE. The six foundational modules stay at the package root and
    # the three meta modules live under meta/, so both are asserted separately rather than as one list.
    meta_built = sorted(p.stem for p in (cog / "meta").glob("*_engine.py"))
    assert meta_built == ["niyyah_engine", "tafakkur_engine", "tawazun_engine"], meta_built
    built = sorted(p.stem for p in cog.glob("*_engine.py"))
    assert built == ["aqal_engine", "hoshiyari_engine", "iman_engine", "inkashaf_engine",
                     "samajh_engine", "soch_engine"], built
    r = client.post("/api/v1/cognitive/cascade", json={"problem": "w489 guard", "include_mjm": True})
    assert r.status_code == 200, r.text[:200]
    body = r.json()
    assert body["engines_run"] == 6, body["engines_run"]          # MJM re-runs the same six
    assert body["engines_compute"] is False, body
    assert "does not add engines" in body["engines_run_basis"], body["engines_run_basis"]
    eng = client.get("/api/v1/cognitive/engines").json()
    assert eng["total"] == 12 and eng["implemented_total"] == 12, eng
    assert eng["layers_implemented"] == {"foundational": 6, "meta": 3, "auxiliary": 3}, eng
    # W524 — NOTHING on this page is planned any more, so the old pair of assertions over `planned`
    # would be one failure and one VACUOUS TRUTH: `all(...)` over an empty list passes while checking
    # nothing. Asserted as the positive state instead, over a list that is non-empty by construction.
    planned = [e for e in eng["engines"] if not e["implemented"]]
    assert planned == [], planned
    meta_rows = [e for e in eng["engines"] if e["layer"] == "meta"]
    assert len(meta_rows) == 3, meta_rows
    assert all(e["implemented"] and e["status"] == "built-computes" for e in meta_rows), meta_rows
    # and each says it is NOT in the cascade, which is why engines_run below stays six
    assert all("NOT in the cascade" in e["note"] for e in meta_rows), meta_rows
    # W524 — a registered engine that is not on the cascade RUNS through the registry. With no context
    # supplied it refuses with a computed basis, which is a real answer rather than the "planned"
    # placeholder this replaced. Both cases driven, because the refusal is the common one.
    one = client.post("/api/v1/cognitive/engine", json={"engine_id": "niyyah", "input": "w489"}).json()
    assert one.get("ran") is True and one.get("status") == "ran", one
    assert one.get("assessable") is False, one
    assert "no signatures were recorded" in one.get("answer", ""), one
    assert one.get("served_by") == "native-refused", one
    assert "not part of /cascade" in one.get("not_on_the_cascade", ""), one
    two = client.post("/api/v1/cognitive/engine", json={
        "engine_id": "niyyah", "input": "w524",
        "context": {"signatures": [{"signatory": "a"}, {"signatory": "b"}], "quorum_required": 2}}).json()
    assert two.get("assessable") is True and two.get("served_by") == "native-computed", two
    assert two["result"]["signatories"] == ["a", "b"], two["result"]
    # the invariant that stops this round over-reporting: nine registered, SIX ran
    assert body["engines_run"] == 6, body["engines_run"]
    vsb_src = (root / "agentic_core/api/vsb.py").read_text(encoding="utf-8")
    assert "Nine Cognitive Engines" not in vsb_src and "Nine engines complete" not in vsb_src
    assert "Six Cognitive Engines (fixed responses)" in vsb_src
    spawn = (root / "apps/workstation-superapp/src/pages/enterprise/VSBSpawnStudio.tsx").read_text(encoding="utf-8")
    assert "Nine Cognitive Engines" not in spawn
    assert 'data-testid="spawn-pipeline-basis"' in spawn
    # W524 (P3.13) — the meta engines are BUILT, so the page may no longer call them unbuilt; and it
    # must still say they are not in THIS pipeline, because built is not the same as reached here.
    assert "planned and do not run yet" not in spawn, "the page still calls a built engine unbuilt"
    assert "they regulate clearance, not spawning" in spawn
    assert "now compute" in spawn
    assert "cognitive_complete: { icon: CheckCircle2" not in spawn, "a literal still earns a green tick"

    # ── FU-171 (S4.6): recall is opted into, and the floor's term list is named a term list ─────
    from agentic_core.ai.gateway import ModelGateway
    import inspect
    for meth in ("query", "query_meta", "stream", "stream_meta"):
        sig = inspect.signature(getattr(ModelGateway, meth))
        assert sig.parameters["augment"].default is False, \
            f"gateway.{meth} still defaults to injecting cross-request recall"
    # the two conversational callers opt IN by name — the exception is explicit, not inherited
    for p, why in ((root / "agentic_core/avatars/api.py", "avatar"),
                   (root / "agentic_core/api/v138/ceo.py", "CEO chat")):
        assert "augment=True" in p.read_text(encoding="utf-8"), f"the {why} lost its explicit opt-in"
    #  W593 — ASSERTED ON WHAT IS RENDERED, NOT ON THE FILE'S TEXT. These read engine.py as a string, and
    #  "not an analysis of the subject" vanished from the SOURCE when the f-string was reflowed across two
    #  literals ("not an analysis of " + "the subject") while the rendered sentence was unchanged. A guard
    #  that greps source cannot see a render. The floor is driven instead, with a labelled field so there
    #  is a term list to head; the absence checks stay on the source, where a vanished phrase is the
    #  honest direction of failure.
    floor = (root / "agentic_core/ai/native/engine.py").read_text(encoding="utf-8")
    assert "## Key factors" not in floor, "the floor still calls a word count 'Key factors'"
    assert "grounded in the input above" not in floor and "grounded in the input's salient terms" not in floor
    from agentic_core.ai.native.engine import native_engine as _ne489
    _rendered489 = _ne489.generate("Problem: varroa mites destroy beehives over winter in Somerset\n")
    # W615 (FU-494) — the heading names what the list is counted over, not whose words they are
    assert "## Terms most frequent in this prompt's labelled fields" in _rendered489, (
        "the floor no longer heads the list as a frequency count of the request", _rendered489[:400])
    assert "not an analysis of the subject" in _rendered489, (
        "the floor stopped disclosing that the list is a word count rather than a judgement",
        _rendered489[:400])

    # ── FU-151 (S13.2): a card shows the number the API computes, not two it never sends ────────
    hub = (root / "apps/workstation-superapp/src/pages/coe/KnowledgeHub.tsx").read_text(encoding="utf-8")
    assert "insight.projects_count ?? 0" not in hub and "insight.confidence ?? 0) * 20" not in hub
    assert "Math.max(1," not in hub, "a floored zero still reads as a measurement of 1"
    assert 'data-testid="coe-score"' in hub and 'data-testid="coe-no-score"' in hub
    ins = client.get("/api/v1/intelligence/insights").json()
    for row in ins.get("insights", []):
        assert "confidence" not in row and "outputs_count" not in row, row   # the page must not invent them

    # ── FU-190 (S11.14): the state label is derived from the PLATFORM's work, not host idleness ──
    bio = client.get("/api/v1/biometrics/status").json()
    assert "workload" in bio and "platform_busy" in bio["workload"], bio.keys()
    assert bio["cardiovascular"]["resource_flow_basis"].startswith("host CPU headroom"), bio["cardiovascular"]
    assert "host_cpu_percent" in bio["cardiovascular"], bio["cardiovascular"]
    hook = (root / "apps/workstation-superapp/src/hooks/useWorkstationBiometrics.ts").read_text(encoding="utf-8")
    assert "b.cardiovascular.resource_flow > 60" not in hook, "an idle host still reads as WORKING"
    assert "b.workload?.platform_busy" in hook
    status_c = (root / "apps/workstation-superapp/src/components/BiometricStatus.tsx").read_text(encoding="utf-8")
    assert "healthy flow (>80%)" not in status_c and "host has spare capacity" in status_c
    assert "connection / urgency" not in status_c
    intro = (root / "apps/workstation-superapp/src/pages/cognitive/Introspection.tsx").read_text(encoding="utf-8")
    assert "Cardiovascular (Flow)" not in intro and "Host CPU headroom" in intro

    # ── FU-184 (S13.8): a rationale is about the value it sits beside ───────────────────────────
    struggling = client.get("/api/v1/qep/xai/explanations"
                            "?ease_factor=1.3&interval_days=0&repetition=0&last_quality=1").json()
    doing_well = client.get("/api/v1/qep/xai/explanations"
                            "?ease_factor=2.9&interval_days=12&repetition=5&last_quality=5").json()
    s_by = {c["feature"]: c["rationale"] for c in struggling["explanations"]}
    w_by = {c["feature"]: c["rationale"] for c in doing_well["explanations"]}
    assert s_by != w_by, "the rationales are identical for opposite inputs — they are fixed strings"
    for f in ("ease_factor", "repetition", "last_quality"):
        assert s_by[f] != w_by[f], f
    assert "retains this ayah well" not in " ".join(s_by.values()), s_by["ease_factor"]
    assert "floor" in s_by["ease_factor"], s_by["ease_factor"]        # 1.3 is the SM-2 floor
    assert "RESETS" in s_by["last_quality"] and "ADVANCES" in w_by["last_quality"]
    assert "no compounding" in s_by["repetition"], s_by["repetition"]

    # ── FU-200 (S11.7): this run's emissions and the process total are different numbers ────────
    from agentic_core.vbs.registry import ems as _ems
    before = _ems.total_co2_kg
    m1 = __import__("asyncio").get_event_loop_policy().new_event_loop().run_until_complete(_ems.measure(10.0))
    m2 = __import__("asyncio").get_event_loop_policy().new_event_loop().run_until_complete(_ems.measure(10.0))
    assert m1["co2_kg_this_run"] > 0, m1
    assert m2["co2_kg_this_run"] == m1["co2_kg_this_run"], (
        "the run figure grows with the process total — it IS the process total", m1, m2)
    assert m2["process_total_co2_kg"] > m1["process_total_co2_kg"], (m1, m2)
    assert m1["process_total_co2_kg"] >= before + m1["co2_kg_this_run"] - 1e-9
    assert m1["efficiency_measured"] is False and m1["efficiency_gain_constant"] == 0.85
    assert "not measured" in m1["basis"] and "since this server started" in m1["basis"]
    swarm_src = (root / "agentic_core/api/swarm.py").read_text(encoding="utf-8")
    assert '"efficiency_gain": float(_eff)' not in swarm_src
    assert '"co2_kg_this_run"' in swarm_src and '"process_total_co2_kg"' in swarm_src
    si = (root / "apps/workstation-superapp/src/components/organism/SwarmIntelligence.tsx").read_text(encoding="utf-8")
    assert "EMS +" not in si, "the chip still presents a constant as this run's gain"
    assert "constant, not measured" in si
    # the chip is no longer emerald: a constant does not get the colour reserved for good news
    assert "bg-emerald-500/15 text-emerald-400' title={cascade.management_systems.ems" not in si
    assert 'data-testid="ems-chip"' in si and "bg-slate-700/40" in si

    # ── FU-194 (S2.12): a policy score is called a policy score, and ties are said ──────────────
    cands = client.get("/api/v1/economy/ventures/candidates?top=8").json()
    assert "policy score" in cands["method"], cands["method"]
    assert "×" not in cands["method"], "the method still claims a product of measurements"
    assert "nothing here is measured" in cands["method_basis"], cands["method_basis"]
    for c in cands["candidates"]:
        assert "not a measurement" in c["score_basis"], c
        assert "tied_with" in c, c
    from agentic_core.economy.ventures import VentureIntelligence as _VI
    _same = [{"id": f"v{i}", "name": f"V{i}", "outcome": 0.7, "value": 0.7, "benefit": 0.7,
              "feasibility": 0.7, "strategic_fit": 0.7} for i in range(3)]
    _ranked = _VI(_same).ranked(3)
    assert len({r["score"] for r in _ranked}) == 1, _ranked      # identical inputs, identical score
    assert all(r["tied_with"] == 2 for r in _ranked), (
        "three candidates share a score and the rows do not say so", _ranked)
    ops = (root / "apps/workstation-superapp/src/pages/enterprise/EconomyOperations.tsx").read_text(encoding="utf-8")
    assert "Investment candidates — ranked;" not in ops and "by eligibility score" in ops
    assert "policy score {c.score}" in ops

    # ── FU-189 (S9.4): a what-if gate on typed numbers does not move the rate ───────────────────
    from agentic_core.vbs.registry import qms as _qms
    s0 = _qms.defect_summary()
    g = client.post("/api/v1/vbs/qms/gate", json={"coverage": 0.10, "stubs_found": True})
    assert g.status_code == 200, g.text[:160]
    assert g.json()["passed"] is False and g.json()["counted_in_rate"] is False, g.json()
    s1 = _qms.defect_summary()
    assert s1["gates_run"] == s0["gates_run"], "a typed what-if still counts as a delivery gate"
    assert s1["gate_failures"] == s0["gate_failures"], "a typed what-if still counts as a failure"
    assert s1["what_if_gates"] == s0["what_if_gates"] + 1, (s0, s1)
    assert "platform" in s1["rate_basis"] and "not one entity" in s1["rate_basis"], s1["rate_basis"]
    panel = (root / "apps/workstation-superapp/src/components/VBSSystemsPanel.tsx").read_text(encoding="utf-8")
    assert "a real rate, 0.0 with no history" not in panel, "the chip still calls it a real rate"
    assert "(platform-wide)" in panel and "run a what-if gate:" in panel
    assert "(stateful, all-time):" not in swarm_src
    assert "NOT this run" in swarm_src

    # ══ W489 REFUTATION LEGS — 19 verified findings against this round's own diff ═══════════════
    # Five lenses, each finding verified in its own worktree. The round broke four pre-existing tests
    # by renaming fields without grepping consumers, named the wrong plan item in eleven places, and
    # — twice — re-committed its own class inside its own fix. Fourteen of the fixes were then found
    # UNGUARDED by blinds. One leg each.

    # ── a payload never carries BOTH the old names and the new ones ─────────────────────────────
    assert '"efficiency_gain":' not in swarm_src or '"efficiency_gain_constant"' in swarm_src
    assert '"total_co2_kg": _ems' not in swarm_src, \
        "the cascade block still emits the old lifetime-total key as this run's"
    assert '"efficiency_gain": 0.85' not in swarm_src and '"efficiency_gain": float(_eff)' not in swarm_src

    # ── a cascade that RAISED reports zero engines, not six ─────────────────────────────────────
    import agentic_core.api.vsb as _vsb_mod

    class _Boom:
        async def execute_cascade(self, *a, **k):
            raise RuntimeError("w489 induced cascade failure")

    _real_cascade = _vsb_mod._cascade
    _vsb_mod._cascade = _Boom()
    try:
        _sp = client.post("/api/v1/vsb/spawn", json={"challenge": "w489 failure path"})
        assert _sp.status_code == 200, _sp.text[:160]
        _evs = [json.loads(l[6:]) for l in _sp.text.splitlines() if l.startswith("data: ")]
        _cc = next((e for e in _evs if e.get("stage") == "cognitive_complete"), None)
        assert _cc is not None, [e.get("stage") for e in _evs]
        _d = _cc.get("data") or {}
        assert _d.get("engines_run") == 0, ("a cascade that raised reported engines as run", _cc)
        assert _d.get("ran") is False and "FAILED" in _cc.get("label", ""), _cc
        assert "no engine was reached" in str(_d.get("basis")), _d
    finally:
        _vsb_mod._cascade = _real_cascade

    class _MjmBoom:
        async def run_lifecycle(self, *a, **k):
            raise RuntimeError("w489 induced mjm failure")

    _real_mjm = _vsb_mod._mjm
    _vsb_mod._mjm = _MjmBoom()
    try:
        _sp2 = client.post("/api/v1/vsb/spawn", json={"challenge": "w489 mjm failure"})
        _evs2 = [json.loads(l[6:]) for l in _sp2.text.splitlines() if l.startswith("data: ")]
        _mc = next((e for e in _evs2 if e.get("stage") == "mjm_complete"), None)
        assert _mc is not None and "FAILED" in _mc.get("label", ""), _mc
        assert (_mc.get("data") or {}).get("ran") is False, _mc
    finally:
        _vsb_mod._mjm = _real_mjm

    # ── the dashboard reads fields writers actually emit ────────────────────────────────────────
    assert "data?.market_strategy" not in bmd, "the page reads a field no writer in the repo emits"
    assert "sim_results?.parameters" not in bmd and "sim_results.parameters" not in bmd
    assert "data?.market_summary || data?.roi_analysis" in bmd
    assert "const SIM_KEYS" in bmd and "drad_resilience" in bmd
    _api_src = (root / "agentic_core/synthesis/api.py").read_text(encoding="utf-8")
    for _k in ("market_summary", "roi_analysis", "ese_adoption", "aro_efficiency",
               "bto_roadmap", "drad_resilience"):
        assert _k in _api_src, (f"the dashboard reads {_k}, which the API no longer specifies", _k)

    # ── the rationale follows the branch the engine ACTUALLY took ───────────────────────────────
    # a failing recall with many repetitions: the engine resets to 1 day, so nothing may claim
    # compounding — the first cut branched on repetition alone and contradicted its own sibling row
    _reset = client.get("/api/v1/qep/xai/explanations"
                        "?ease_factor=2.5&interval_days=10&repetition=5&last_quality=1").json()
    _r_by = {c["feature"]: c["rationale"] for c in _reset["explanations"]}
    assert _reset["next_interval_days"] == 1, _reset["next_interval_days"]
    assert "compounds" not in _r_by["repetition"], _r_by["repetition"]
    assert "discarded" in _r_by["repetition"], _r_by["repetition"]
    assert "reset" in _r_by["ease_factor"], _r_by["ease_factor"]
    # …and at repetition 0/1 the engine returns a FLAT interval, so ease does not lengthen anything
    _flat = client.get("/api/v1/qep/xai/explanations"
                       "?ease_factor=2.9&interval_days=10&repetition=1&last_quality=5").json()
    _f_by = {c["feature"]: c["rationale"] for c in _flat["explanations"]}
    assert _flat["next_interval_days"] == 6, _flat["next_interval_days"]
    assert "does not affect this interval" in _f_by["ease_factor"], _f_by["ease_factor"]
    # …and at the floor, WITH compounding, the interval still grows — it does not "add no growth"
    _floor_c = client.get("/api/v1/qep/xai/explanations"
                          "?ease_factor=1.3&interval_days=6&repetition=5&last_quality=4").json()
    _fc = {c["feature"]: c["rationale"] for c in _floor_c["explanations"]}
    assert _floor_c["next_interval_days"] > 6, _floor_c["next_interval_days"]
    assert "still grows" in _fc["ease_factor"], _fc["ease_factor"]
    assert "adds no growth" not in _fc["ease_factor"], _fc["ease_factor"]

    # ── a salience weight is named one, at the API and on the card ──────────────────────────────
    _ins = client.get("/api/v1/intelligence/insights").json()
    assert "salience" in str(_ins.get("score_meaning", "")).lower(), _ins.get("score_meaning")
    for _row in _ins.get("insights", []):
        assert "salience weight" in str(_row.get("score_basis", "")), _row
    assert "Salience weight" in hub and "Insight score" not in hub
    assert "not a measurement" in _code_only(hub)

    # ── the panel says what a what-if did, and promises only what it can do ─────────────────────
    assert "failed gates open them automatically" not in panel
    assert "including a failed what-if" in panel
    assert "gateRes.counted_in_rate === false" in panel and "not counted in the rate" in panel

    # ── EVERY writer of the platform-wide rate says so, not just the one the round edited ───────
    for _p, _need in ((root / "agentic_core/api/vsb.py", "platform-wide, all entities and tenants"),
                      (root / "apps/workstation-superapp/src/pages/enterprise/ServiceContracts.tsx",
                       "(platform-wide)")):
        assert _need in _p.read_text(encoding="utf-8"), f"{_p.name} still presents the rate as its own"
    assert "Non-conformance rate (stateful):" not in (root / "agentic_core/api/vsb.py").read_text(encoding="utf-8")

    # ── the planning mechanism this round used: a class is counted where it is CITED ────────────
    import agentic_core.plan_followups as fu
    assert fu.row_classes({"title": "sweep x.py: 2 Tier-1 truth defects (C3,C5) — …", "why": ""}) == ["C3", "C5"]
    assert fu.row_classes({"title": "", "why": "S12.1 C3: the page shows…"}) == ["C3"]
    assert fu.row_classes({"title": "", "why": "lists S1.1 (C3, the cockpit card) and S8.1 (C8, …)"}) == ["C3", "C8"]
    # …and NOT where a row merely discusses one (this row's own prose swelled three batches)
    assert fu.row_classes({"title": "Batches are scoped to the gate item",
                           "why": "C3 (invented or constant readings) closes 4 rows; C7 and C1 are smaller"}) == []


def test_w490_floor_served_output_says_so_wherever_it_goes(client):
    """W490 — P1.18 + P2.3 + P2.4 + P2.6 + P2.9, the C7 batch taken repo-wide.

    Twelve rows, one rule: OUTPUT THE DETERMINISTIC FLOOR COMPOSED SAYS SO, WHEREVER IT GOES —
    on the screen, in the file that leaves, and in the API that feeds both. The floor arranges the
    headings it was asked for; it supplies no analysis, and every surface that presents its output as
    AI work is making a claim the run cannot back.

    Three shapes: the API carried the provenance and the surface dropped it (FU-162, FU-173, FU-174,
    FU-178, FU-199); the screen showed it and the export lost it (FU-175, FU-211, FU-145); and the
    API discarded it before any surface could speak (FU-144, FU-145), or reported a capability it had
    NOT honoured and nothing read that either (FU-191). Plus the two claims that were simply false:
    an engine list naming eight analysers over three calls (FU-134) and a privacy line saying nothing
    is inferred from your activity while two surfaces recall it (FU-180).
    """
    import pathlib
    root = pathlib.Path(__file__).resolve().parents[1]
    app = root / "apps/workstation-superapp/src"

    # ── the shared mechanism this round sweeps (it must keep saying what the floor is) ──────────
    api_ts = (app / "lib/api.ts").read_text(encoding="utf-8")
    assert "structured floor — not model analysis" in _code_only(api_ts)
    assert "composed by the deterministic native structured engine, not by a model" in api_ts

    # ── FU-144 (S6.7): the API stops discarding what served the assessment ──────────────────────
    tr = (root / "agentic_core/api/transformation.py").read_text(encoding="utf-8")
    assert 'gateway.query(prompt, agent="transformation_assess"' not in tr, \
        "gateway.query throws away served_by, so no surface can label the assessment"
    assert "query_meta(prompt, agent=\"transformation_assess\"" in tr and '"ai_provenance": _prov' in tr
    r = client.post("/api/v1/transformation/assess")
    assert r.status_code == 200, r.text[:160]
    body = r.json()
    assert "ai_provenance" in body and "served_by" in body["ai_provenance"], body.keys()
    td = (app / "pages/TransformationDashboard.tsx").read_text(encoding="utf-8")
    assert 'data-testid="assessment-provenance"' in td, "the panel prints the text with no provenance"
    assert "setAssessProv(d.ai_provenance ?? null)" in td, (
        "the badge renders but nothing feeds it the API's provenance")
    assert "provenanceBadge(assessProv?.served_by" in td
    assert ">AI Assessment<" not in td, "a floor scaffold is still headed 'AI Assessment'"

    # ── FU-145 (S12.4): the blueprint says what composed it, on screen AND in the export ─────────
    cg = (root / "agentic_core/api/v290/ceo_generate.py").read_text(encoding="utf-8")
    assert 'gateway.query(prompt, agent="ceo_blueprint")' not in cg
    # a vacuous blind: "ai_provenance: dict | None = None" is a SUBSTRING of "_ai_provenance: ...",
    # so renaming the field left the leg green. Anchored with its indentation, and checked live.
    assert "\n    ai_provenance: dict | None = None" in cg and "ai_provenance=_prov" in cg
    bp_r = client.post("/api/v290/ceo/generate-blueprint",
                       json={"intent": "w490 guard", "realm": "enterprise", "stage": "concept",
                             "domain": "enterprise"})
    assert bp_r.status_code == 200, bp_r.text[:160]
    assert (bp_r.json().get("ai_provenance") or {}).get("served_by"), bp_r.json().keys()
    cs = (app / "pages/create/CreatorStudio.tsx").read_text(encoding="utf-8")
    assert 'data-testid="blueprint-provenance"' in cs
    assert "provenanceBadge(blueprint.ai_provenance?.served_by" in cs, (
        "the blueprint badge is not fed the API's provenance")
    assert "provenanceLine(blueprint.ai_provenance?.served_by" in cs, "the exported .md carries no provenance"
    assert "AI CEO is synthesising your blueprint" not in cs, "the spinner promises synthesis before it is known"

    # ── FU-175 / FU-211 (S12.11, S2.13): the file that LEAVES carries the line the screen showed ──
    aps = (app / "components/employment/ApplicationStudio.tsx").read_text(encoding="utf-8")
    assert "provenanceLine(doc.ai_provenance?.served_by" in aps, "the downloaded .md loses the floor badge"
    msh = (app / "pages/enterprise/ManagementSystemsHub.tsx").read_text(encoding="utf-8")
    assert "provenanceLine(prov?.served_by" in msh
    # a vacuous blind found `prov?.floor_note` useless as an anchor: it also appears in the RENDER,
    # so dropping it from the DOWNLOAD left the leg green. The download's own expression is the anchor.
    assert "+ (prov?.floor_note ? `> ${prov.floor_note}" in msh, \
        "the downloaded framework loses the floor_note shown on screen"

    # ── FU-191 (S10.11): a capability the backend did NOT honour reaches the reader ──────────────
    hook = (app / "hooks/useAvatarSession.ts").read_text(encoding="utf-8")
    # a vacuous blind: the bare field names are in the INTERFACE too, so removing an ASSIGNMENT left
    # the leg green. The assignments are what carry the backend's answer to the reader.
    for f in ("imageRequested: Boolean(imageBase64)",
              "imageUnderstood: Boolean(resp.data.image_understood)",
              "languageHonoured: resp.data.language"):
        assert f in hook, f"the hook declares the field and never assigns it: {f}"
    cp = (app / "components/avatar/ConversationPanel.tsx").read_text(encoding="utf-8")
    assert 'data-testid="image-not-read"' in cp and 'data-testid="language-not-honoured"' in cp
    # the NEGATION is the leg: without it every reply claims the image was not read
    assert "m.imageRequested && !m.imageUnderstood" in cp
    assert "m.languageRequested && !m.languageHonoured" in cp
    # …and the backend really does report those states (the page is labelling something real)
    av = (root / "agentic_core/avatars/api.py").read_text(encoding="utf-8")
    assert "image_understood=image_understood" in av and "image_served_by=image_served_by" in av

    # ── FU-162 (S3.12, S6.14): every server-rendered export, and the row, say what composed it ──
    dl = (root / "agentic_core/api/deliverables.py").read_text(encoding="utf-8")
    assert "produced on Workstation IDBO's own AI fabric" not in dl, \
        "a binary export still claims the AI fabric produced floor output"
    assert "produced on Workstation's own AI fabric" not in dl, "the markdown export still claims it"
    assert "def _provenance_phrase" in dl
    import agentic_core.api.deliverables as dlm
    floor_doc = {"type": "report", "ai_provenance": {"served_by": "native", "is_external": False}}
    model_doc = {"type": "report", "ai_provenance": {"served_by": "ollama:llama3", "is_external": False}}
    ext_doc = {"type": "report", "ai_provenance": {"served_by": "claude", "is_external": True}}
    ingest = {"type": "report", "ai_provenance": {"served_by": "verbatim-ingest",
                                                  "source_served_by": {"native": 11}}}
    assert "not model analysis" in dlm._provenance_phrase(floor_doc)
    assert "composed in-house by ollama:llama3" in dlm._provenance_phrase(model_doc)
    assert "external accelerant" in dlm._provenance_phrase(ext_doc)
    # the verbatim ingest is judged by the ORIGIN it declared, the way the §10 gate already judges it
    assert "not model analysis" in dlm._provenance_phrase(ingest), dlm._provenance_phrase(ingest)
    assert "native×11" in dlm._provenance_phrase(ingest), dlm._provenance_phrase(ingest)
    # an empty map claims nothing at all
    assert "no call is recorded" in dlm._provenance_phrase({"ai_provenance": {"source_served_by": {}}})
    dsx = (app / "pages/Deliverables.tsx").read_text(encoding="utf-8")
    assert "· {d.served_by}" not in dsx, "the row still prints the raw token, which reads as a brand"
    # (refutation) the first cut called the badge with ONE argument, so an opt-in external serve went
    # emerald "in-house" on the row while the detail pane below it showed amber "via <token>".
    # (refutation) The first cut of this leg demanded TWO calls — a shape satisfiable only by taking
    # .label and .title separately, which is exactly what W453's class-kill guard forbids (it drops
    # .cls, so the floor chip loses its amber). The two guards were mutually unsatisfiable. One call,
    # destructured, all three fields used.
    assert "const b = provenanceBadge(d.served_by, d.is_external);" in dsx
    assert "${b.cls}" in dsx and "title={b.title}" in dsx and "{b.label}" in dsx
    assert "provenanceBadge(d.served_by)." not in dsx
    assert '"is_external": (d.get("ai_provenance") or {}).get("is_external")' in dl, (
        "the list summary does not send is_external, so the row cannot match the detail pane")

    # ── FU-173 / FU-174 (S1.3, S1.4): the cockpit labels the Chief's directive and the tree ─────
    ck = (app / "pages/enterprise/VSBCockpit.tsx").read_text(encoding="utf-8")
    assert 'data-testid="chief-directive-provenance"' in ck
    assert "provenanceMapBadge(chiefResult.ai_provenance?.served_by" in ck
    # provenanceMapFromTrace is on the import line too; the call that feeds the badge is the anchor
    assert 'data-testid="tree-provenance"' in ck
    assert "provenanceMapBadge(provenanceMapFromTrace(t.nodes), t.any_external)" in ck
    # …and W488's reason for a directive that could not land now reaches the page too
    assert 'data-testid="objectives-not-added"' in ck
    bp_src = (root / "agentic_core/api/business_plan.py").read_text(encoding="utf-8")
    assert '"nodes": [{"id": n.get("id")' in bp_src, "the per-node served_by trace is still stripped"
    assert '"any_external": tree.get("any_external")' in bp_src

    # ── FU-178 (S8.12): the forge run says what served its five calls ───────────────────────────
    fp = (app / "pages/developers/ForgePipeline.tsx").read_text(encoding="utf-8")
    assert 'data-testid="forge-provenance"' in fp and 'data-testid="forge-deliverable-provenance"' in fp
    # the helper NAME is on the import line, so it is not a usage anchor — the read is
    assert fp.count("provenanceMapBadge(result.ai_provenance?.served_by") == 2, (
        fp.count("provenanceMapBadge(result.ai_provenance?.served_by"))

    # ── FU-199 (S4.12): the green tick carries what served the run ──────────────────────────────
    ss = (app / "pages/synthesis/SynthesisStudio.tsx").read_text(encoding="utf-8")
    assert "served_by: ev.served_by" in ss, "the done frame's provenance is parsed and thrown away"
    assert 'data-testid="synthesis-provenance"' in ss
    # (refutation) the aggregate comment promised a per-result badge that did not exist, and
    # profile_applied was typed, assigned and read nowhere — the narrower form of the same defect.
    assert 'data-testid="synthesis-result-provenance"' in ss
    assert 'data-testid="synthesis-profile-applied"' in ss
    assert "result.profile_applied" in ss

    # ── FU-134 (S7.0): an engine list is what it is — a selection, not a record of analysers ────
    sv = client.post("/api/v1/intelligence/solve", json={"problem": "w490 guard", "domain": "general"})
    assert sv.status_code == 200, sv.text[:160]
    sb = sv.json()
    assert sb["calls_made"] == 3, sb.get("calls_made")
    assert "not one call per engine" in sb["engines_used_basis"], sb.get("engines_used_basis")
    assert sb.get("run_summary"), sb.keys()
    # on the deterministic test runtime every call is the floor, and the summary must say so
    assert "structured floor" in sb["run_summary"], sb["run_summary"]
    assert sb["provenance"]["floor_calls"] == 3, sb["provenance"]

    # ══ W490 REFUTATION LEGS — 18 verified findings against this round's own diff ════════════════
    # Five lenses, twice (the first run lost 27 of 45 agents to a full disk — see the register row on
    # cleaning up worktrees). Two shapes dominated: a NEW claim the repo cannot back, and a second
    # reader of the same field left disagreeing with the first.

    # ── the server phrase obeys the same COUNT RULE as the browser it claims to mirror ───────────
    import agentic_core.api.deliverables as dlm
    def _phr(prov):
        return dlm._provenance_phrase({"type": "report", "ai_provenance": prov})
    # a floor-MAJORITY map is not "composed in-house": provenanceMapBadge has compared counts since W479
    mixed = _phr({"source_served_by": {"native": 3, "ollama:llama3.2": 1}})
    assert mixed.startswith("mostly structured floor"), mixed
    assert "3 of 4 calls" in mixed, mixed
    assert "composed in-house" not in mixed, mixed
    # a model-majority map still reads in-house, and an all-floor map is the floor
    assert _phr({"source_served_by": {"native": 1, "ollama:x": 3}}).startswith("composed in-house by")
    assert _phr({"source_served_by": {"native": 11}}).startswith("structured floor")
    # a verbatim ingest with NO declared origin is not a composition claim at all
    ing = _phr({"served_by": "verbatim-ingest"})
    assert ing.startswith("supplied verbatim by the caller"), ing
    assert "in-house" not in ing and "structured floor" not in ing, ing
    # …and one whose declared origin is EXTERNAL is never "in-house"
    ext_ing = _phr({"served_by": "verbatim-ingest", "source_served_by": "claude", "is_external": True})
    assert "external accelerant" in ext_ing, ext_ing

    # ── the SVG and PNG cards cannot contradict their own subtitle ───────────────────────────────
    assert "def _provenance_footer" in dl, "the cards derive their own footer again"
    assert "Workstation IDBO · {posture} · {served}" not in dl
    import re as _re
    _svg = dlm._svg_doc({"type": "report", "title": "t",
                         "ai_provenance": {"served_by": "native", "is_external": False}})
    _foot = _re.findall(r">([^<]*Workstation IDBO[^<]*)<", _svg)
    assert _foot and "structured floor" in _foot[0], _foot
    assert "in-house" not in _foot[0], _foot
    # a vacuous blind: a byte count says nothing about what was DRAWN on the card. The PNG footer
    # is read by spying on the text calls, so it cannot drift from the subtitle unnoticed.
    try:
        from PIL import ImageDraw as _ID
        _drawn: list = []
        _real_text = _ID.ImageDraw.text
        def _spy(self, xy, text, *a, **k):
            _drawn.append(str(text))
            return _real_text(self, xy, text, *a, **k)
        _ID.ImageDraw.text = _spy
        try:
            _png = dlm._png_bytes({"type": "report", "title": "t",
                                   "ai_provenance": {"served_by": "native"}})
        finally:
            _ID.ImageDraw.text = _real_text
        assert len(_png) > 0
        _pfoot = [s for s in _drawn if "Workstation IDBO" in s]
        assert _pfoot, _drawn[:4]
        assert "structured floor" in _pfoot[0] and "in-house" not in _pfoot[0], _pfoot
    except ImportError:
        pass      # Pillow absent: the SVG leg above still covers the shared footer

    # ── the PAGE badge and the exported file agree about a verbatim ingest ───────────────────────
    assert "sb === 'verbatim-ingest'" in api_ts, "the row still badges an ingest emerald in-house"
    assert "supplied verbatim by the caller" in api_ts
    assert "sb === 'native' || sb === 'template'" in api_ts, "a template-served output badges as a model"

    # ── FU-134's fix reaches THE PAGE, not just the API ──────────────────────────────────────────
    ci = (app / "pages/CognitionIntegration.tsx").read_text(encoding="utf-8")
    assert "Ran: <span" not in ci, "the page still prints an engine list as a record of analysers"
    assert 'data-testid="solve-engines-basis"' in ci and 'data-testid="solve-run-summary"' in ci
    assert "solveRes.engines_used_basis" in ci and "solveRes.run_summary" in ci
    # and its floor-served sections carry the note the sibling pages have had since W479
    assert "FLOOR_STAGE_NOTE" in ci and ci.count('data-testid="solve-floor-note-') == 3

    # ── the call count is counted, not asserted ─────────────────────────────────────────────────
    assert sb["calls_attempted"] == 3, sb_
    assert sb["calls_made"] == 3 - sb["provenance"]["failed_calls"], sb
    # a vacuous blind: with nothing failing, a counted 3 and a constant 3 are the same number. One
    # call is made to fail so the count has to be real.
    import agentic_core.ai.gateway as _gwm
    _real_qm = _gwm.gateway.query_meta
    async def _one_fails(prompt, agent="assistant", **kw):
        if agent == "cognitive_solve":
            raise RuntimeError("w490 induced stage failure")
        return await _real_qm(prompt, agent=agent, **kw)
    _gwm.gateway.query_meta = _one_fails
    try:
        _f = client.post("/api/v1/intelligence/solve",
                         json={"problem": "w490 failure leg", "domain": "general"}).json()
    finally:
        _gwm.gateway.query_meta = _real_qm
    assert _f["provenance"]["failed_calls"] >= 1, _f["provenance"]
    assert _f["calls_attempted"] == 3, _f
    assert _f["calls_made"] == 3 - _f["provenance"]["failed_calls"], _f
    assert _f["calls_made"] < 3, _f["calls_made"]
    assert "of the 3 ran" in _f["engines_used_basis"], _f["engines_used_basis"]
    assert "all 3 ran" not in _f["engines_used_basis"], _f["engines_used_basis"]
    assert "attempts THREE gateway calls" in sb["engines_used_basis"], sb["engines_used_basis"]
    assert "three gateway calls ran in total" not in sb["engines_used_basis"]

    # ── the SAME tree, badged on BOTH pages that render it ───────────────────────────────────────
    bpx2 = (app / "pages/enterprise/BusinessPlan.tsx").read_text(encoding="utf-8")
    assert 'data-testid="plan-tree-provenance"' in bpx2, \
        "the Business Plan page renders the tree the cockpit badges, and says nothing about it"
    assert "provenanceMapFromTrace" in bpx2

    # ── the SECOND deliverables list in the cockpit, and its caption ─────────────────────────────
    assert "own native AI fabric (honest in-house provenance)" not in ck, \
        "the caption still credits the fabric for whatever composed these"
    assert "{d.served_by || 'native'}" not in ck, "a record with no provenance still claims the floor"
    assert ck.count("provenanceBadge(d.served_by, d.is_external)") >= 1

    # ── the Forge badge names the scope it actually has ──────────────────────────────────────────
    assert "whole run: {b.label}" in fp, "a run-wide aggregate is stamped as if it described one text"
    assert 'data-testid="forge-stage-scope"' in fp

    # ── the file that LEAVES SynthesisStudio carries its provenance (it is served off disk) ──────
    syn_api = (root / "agentic_core/synthesis/api.py").read_text(encoding="utf-8")
    assert "def _with_provenance" in syn_api and "_provenance_note" in syn_api
    assert "self._with_provenance(content, ext)" in syn_api
    assert "synthesis_manager._with_provenance(content, ext)" in syn_api, \
        "the STREAM path persists its own file and does not carry provenance"
    from agentic_core.synthesis.api import synthesis_manager as _sm
    _sm._last_served_by, _sm._last_is_external = None, False
    assert "no call is recorded" in _sm._with_provenance("# T\nbody", "md")
    _sm._last_served_by = "native"
    assert _sm._with_provenance("# T\nbody", "md").startswith("> Provenance: structured floor")
    _sm._last_served_by = "ollama:x"
    assert '"provenance": "composed in-house by ollama:x"' in _sm._with_provenance('{"a": 1}', "json")

    # ── FU-180 (S6.4): the privacy claim is true of the WHOLE platform, exceptions named ────────
    st = (app / "pages/Settings.tsx").read_text(encoding="utf-8")
    assert "nothing is inferred from your activity" not in st, \
        "the page still claims platform-wide what is only true of the profile"
    assert 'data-testid="recall-disclosure"' in st
    assert "AI CEO chat" in st and "avatar" in st, "the two recall surfaces are not named"
    # …and the two named surfaces really are the only ones that opt in
    import ast as _ast
    # W507 — checked on the AST, not by grepping the source. This searched for the text "augment=True", so a
    # COMMENT mentioning the recall default counted as a file opting in: writing the FU-256 disclosure turned
    # this guard red by explaining the very defect it guards. A text match over source cannot tell a call
    # from a sentence about a call (the W495 class, and the same weakness as P2.2's grep-count bar).
    optin = []
    for p in sorted((root / "agentic_core").rglob("*.py")):
        try:
            _tree = _ast.parse(p.read_text(encoding="utf-8"))
        except (SyntaxError, UnicodeDecodeError):
            continue
        for _n in _ast.walk(_tree):
            if isinstance(_n, _ast.Call) and any(
                    k.arg == "augment" and isinstance(k.value, _ast.Constant) and k.value.value is True
                    for k in _n.keywords):
                optin.append(p.name)
                break
    assert sorted(optin) == ["api.py", "ceo.py"], optin      # avatars/api.py and v138/ceo.py
    # …and no docstring still describes recall as the ambient default each caller must switch off
    for p, stale in ((root / "agentic_core/ai/user_context.py", "every generation-class caller passes"),
                     (root / "agentic_core/avatars/api.py", "Every ship/persist caller sets augment=False"),
                     (root / "agentic_core/api/user_workspace.py", "generation-class caller disables it")):
        assert stale not in p.read_text(encoding="utf-8"), (p.name, stale)
def test_w491_a_count_says_what_population_it_covers(client):
    """W491 — P1.18 + P2.4 + P2.6 + P2.8 + P2.9, the C10 batch taken repo-wide.

    Ten rows, one rule: A COUNT OR A LIST SAYS WHAT POPULATION IT COVERS AND WHAT ACTUALLY HAPPENED
    IN IT. A fetch limit is not a total. A catalogue of things the platform supports is not a record
    of having operated them. A resource having matched is not a facility having run. And a control's
    label names what the control does, not an activity nobody measured.

    Four shapes appeared: a page-sized slice presented as the whole (FU-213 UEG trail, FU-172 signal
    feed); a static catalogue presented as a record of operation (FU-159 management systems, FU-181
    standards, FU-207 ensemble members, FU-206 model selector); a tally whose population is narrower
    than the thing it is labelled as (FU-192 roster cycles vs the books, FU-159 fabric requisitions,
    FU-155 marketplace listings); and a label naming something the control does not do (FU-208 the
    Career Path button, FU-179 "Recent Project Activity" = the server's own git log).
    """
    import pathlib
    root = pathlib.Path(__file__).resolve().parents[1]
    app = root / "apps/workstation-superapp/src"

    # ── FU-159 (S2.4): a requisition says what it DID, and the counters cover one population ──────
    casc = client.post("/api/v1/swarm/cascade", json={
        "mission": "verify regulatory compliance and optimise compute resource allocation",
        "domain": "enterprise"}).json()
    fr = casc["fabric_requisitions"]
    assert fr, "a mission that plainly matches two resources requisitioned none"
    from agentic_core.api.resource_fabric import (_resource_kind, _resource_outcome,
                                                  _STATUS_READ_RESOURCES, _QUERY_RESOURCES,
                                                  _BLUEPRINT_RESOURCES, _OUTCOME_FOR_KIND,
                                                  _READ_SIDE_EFFECTS)
    for f in fr:
        # the key that asserted a run is gone; what happened is stamped by the fabric choke point
        assert "ran" not in f, f
        assert f["kind"] in ("status_read", "query", "blueprint", "facility_run"), f
        assert f["invocation"] == "in_process", f       # no HTTP call is made, and the payload says so
        assert f["kind_phrase"], f
        # kind is WHAT IT IS (derived here from the constants), outcome is WHAT HAPPENED
        assert f["kind"] == _resource_kind(f["resource"]), f
        if f.get("error"):
            assert f["outcome"] in ("raised", "no_calls_ran"), f
        else:
            assert f["outcome"] == _OUTCOME_FOR_KIND[f["kind"]] and f["endpoint"], f
    sm = casc["fabric_requisitions_summary"]
    # derived from the ids and the constants, NOT re-summed from the response's own kind field
    assert sm["requisitioned"] == len(fr)
    assert sm["facilities_ran"] == sum(
        1 for f in fr if not f.get("error") and _resource_kind(f["resource"]) == "facility_run"), (sm, fr)
    assert sm["failed"] == sum(1 for f in fr if f.get("error")), (sm, fr)
    assert (sm["facilities_ran"] + sm["state_read"] + sm["blueprints_drafted"]
            + sm["failed"] + sm["outcome_not_recorded"]) == sm["requisitioned"], sm
    assert "an attempt that raised is neither a run nor a read" in sm["basis"]
    assert "no HTTP call is made" in sm["basis"]

    # the classification is decided from what a handler DOES, and the OUTCOME from what happened. These
    # run the functions, so the branches execute; the round's first version only restated the constants.
    assert _resource_kind("metabolic") == "status_read"        # biobus.organism_context() — a reading
    assert _resource_kind("products_catalogue") == "query"     # scores existing records, makes nothing
    assert _resource_kind("compliance") == "facility_run"      # genuinely runs the compliance engine
    # build_to_order landed in facility_run because facility_run is the DEFAULT; its handler provisions
    # nothing, and a default is not a reading
    assert _resource_kind("build_to_order") == "blueprint"
    assert _resource_kind("a-resource-that-does-not-exist") == "facility_run"   # the fall-through
    assert not (_STATUS_READ_RESOURCES & _QUERY_RESOURCES) and not (_QUERY_RESOURCES & _BLUEPRINT_RESOURCES)
    # an attempt that raised is neither a run nor a read, and a run whose every call failed is not a run
    assert _resource_outcome("compliance", {}) == "produced"
    assert _resource_outcome("compliance", {"error": "boom"}) == "raised"
    assert _resource_outcome("compliance", {"calls": 3, "failed_calls": 3}) == "no_calls_ran"
    assert _resource_outcome("metabolic", {"error": "boom"}) == "raised"
    assert _resource_outcome("metabolic", {}) == "read"
    # a read that is not free says so: organism_context() advances the ATP simulator
    assert "metabolic" in _READ_SIDE_EFFECTS and "ATP" in _READ_SIDE_EFFECTS["metabolic"]

    # the tree node that draws a resource folds in WHAT IT WAS, not "ran <endpoint>"
    orc = (root / "agentic_core/ai/native/orchestrator.py").read_text(encoding="utf-8")
    # W491 refutation — this was a disjunction whose second arm ("kind_phrase" anywhere in the file) is
    # satisfied by the dict assignment alone, so the node-output format was unguarded. One arm now.
    assert "[fabric:{rid} — {fr.get('kind_phrase')}] " in orc
    assert "· ran {fr.get(" not in orc
    assert '"kind": fr.get("kind")' in orc and '"ran": fr.get(' not in orc

    # the composition surface: the same distinction reaches the page that lists a run's resources
    rf_ui = (app / "pages/synthesis/ResourceFabric.tsx").read_text(encoding="utf-8")
    # (the round's first heading said "N of M ran an engine, THE REST READ existing state"; its own
    #  refutation showed that counts an attempt that raised as a read — see the outcome legs below)
    assert "real-runs-heading" in rf_ui and "composed resource(s) invoked in-process" in rf_ui
    assert "§7 real engines ran" not in rf_ui
    # the chip reports the OUTCOME (the round's first version branched on `kind`, which cannot say
    # whether the attempt succeeded)
    assert "run-kind-${rr.resource}" in rf_ui
    assert rf_ui.count(": rr.outcome === 'read' || rr.outcome === 'assessed'") == 2   # live chip AND history chip
    assert "rr.outcome === 'raised'" in rf_ui and "rr.kind !== 'facility_run'" not in rf_ui
    assert "rr.endpoint &&" in rf_ui and "rr.ran &&" not in rf_ui

    # a persisted VSB repo summary carries the kind too, or a list of ids implies they ran
    vs = (root / "agentic_core/api/vsb.py").read_text(encoding="utf-8")
    assert '"kind": f.get("kind")' in vs

    # the BTO prompt no longer tells the model a status reading is a genuine facility result
    sw = (root / "agentic_core/api/swarm.py").read_text(encoding="utf-8")
    assert "assemble your plan FROM these genuine results" not in sw
    assert "Platform state READ" in sw and "NOT as work performed for it" in sw
    # a failed requisition is named to the model as failed, and explicitly not cited as an output
    assert "Requisitioned and FAILED" in sw and "do not cite them" in sw
    assert 'f.get("outcome") in ("raised", "no_calls_ran") or f.get("error")' in sw
    assert "requisitioned these Resource-Fabric facilities and they RAN" not in sw

    # ── FU-159 (S2.4): the management-systems list records what OPERATED, and the page reads it ───
    ms = casc["management_systems"]
    assert "integrated" not in ms, "the catalogue is being reported as a record of operation again"
    assert set(ms["catalogue"]) >= {"bms", "qms", "ems", "dcms", "backbone"}
    assert "backbone" not in ms["operated_this_run"], "a system this cascade never touches is listed"
    assert set(ms["operated_this_run"]) <= set(ms["catalogue"])
    swarm_ui = (app / "components/organism/SwarmIntelligence.tsx").read_text(encoding="utf-8")
    # the reader must read the field the API sends — reading the removed one dropped the chip silently
    assert "management_systems?.operated_this_run" in swarm_ui
    assert "management_systems?.integrated" not in swarm_ui
    assert "operated_basis" in swarm_ui
    # and a requisition row on the page distinguishes a run from a read
    assert "fabric-requisitions-heading" in swarm_ui and "read only" in swarm_ui
    # the ROW's own distinction, not just the heading's word (the heading alone left this unguarded)
    assert "f.kind === 'facility_run' ? `ran ${f.endpoint ?? ''}`" in swarm_ui
    assert "(f.kind_phrase ?? f.kind ?? 'kind not recorded')" in swarm_ui
    assert "fabric-kind-${f.resource}" in swarm_ui
    assert "requisitioned &amp; RAN" not in swarm_ui and "requisitioned & RAN" not in swarm_ui

    # ── FU-179 (S2.9): whose git history this is, and an unreadable log is not an empty one ───────
    gh = client.get("/api/v1/workstation/git-history", params={"limit": 3}).json()
    assert gh["subject"] == "workstation_platform_source"
    assert gh["is_user_project_activity"] is False
    assert gh["readable"] in (True, False)
    assert "a user's own project activity is not tracked here" in gh["basis"]
    # W491 refutation — `readable is (unreadable_reason is None)` restated the server's own line and was
    # true for every possible response. These are falsifiable properties of the payload instead: a page
    # is not a total, and the repository's own count is either absent or at least as large as the page.
    assert "total" not in gh, gh.keys()          # the field that named a fetch limit a total is gone
    assert gh["limit"] == 3 and gh["returned"] <= gh["limit"], gh
    assert gh["repository_commits_total"] is None or gh["repository_commits_total"] >= gh["returned"], gh
    # W492 — the round's first version asserted the two numbers must DIFFER, which is true of a full
    # clone and false on CI's shallow one (1 commit: returned 1, total 1, limit 3 is an accurate
    # report). The property that does not depend on the checkout: the repository count is invariant
    # under `limit`, because it is counted from the repository and not from the page.
    _gh1 = client.get("/api/v1/workstation/git-history", params={"limit": 1}).json()
    assert _gh1["returned"] <= 1 and _gh1["limit"] == 1, _gh1
    assert _gh1["repository_commits_total"] == gh["repository_commits_total"], (_gh1, gh)
    # W492 refutation — on a shallow clone (CI: actions/checkout depth 1) both numbers are 1, so the
    # invariant above is 1 == 1 and would pass even if the total echoed the page. The environment
    # cannot produce the discriminating case, so the MECHANISM is pinned: the total comes from the
    # repository, counted by git, and never from len(commits).
    _isrc2 = (root / "agentic_core/api/integration_surface.py").read_text(encoding="utf-8")
    assert '["git", "rev-list", "--count", "HEAD"]' in _isrc2
    assert 'repo_total = int((_cnt.stdout or "").strip()) if _cnt.returncode == 0 else None' in _isrc2
    assert "repo_total = len(commits)" not in _isrc2
    if gh["readable"]:
        assert isinstance(gh["repository_commits_total"], int), gh
    assert "never the same number by construction" in gh["counts_basis"]
    isrc = (root / "agentic_core/api/integration_surface.py").read_text(encoding="utf-8")
    # readable is MEASURED (the repo is probed, the exit status is checked), never asserted
    assert '"--show-toplevel"' in isrc and "out.returncode != 0" in isrc
    fourth = (app / "components/layout/FourthColumn.tsx").read_text(encoding="utf-8")
    assert "Recent Project Activity" not in fourth, "the platform's own log is labelled as the user's"
    assert "git-history-caption" in fourth and "not activity in your projects" in fourth
    assert "git-history-unreadable" in fourth       # unreadable is a state, not an empty list
    # and it is its OWN statement, not nested inside the empty-list case
    assert "{gitMeta && gitMeta.readable === false && (" in fourth
    assert "typeof g.data.readable === 'boolean' ? g.data.readable : null" in fourth
    # a Channels control does not report traffic nobody measured: the glyph is static
    assert "animate-eq-bar" not in fourth
    cc = (root / "packages/ui/src/CommandCenter.tsx").read_text(encoding="utf-8")
    assert "animate-eq-bar" not in cc
    assert "Live voice/sound-style equalizer" not in cc
    # the one place bars still animate is labelled Idle and greyed, and says why that is honest
    vv = (app / "components/avatar/VoiceVisualizer.tsx").read_text(encoding="utf-8")
    assert "text-slate-700 animate-eq-bar" in vv and "statusLabel" in vv
    assert "same honest\n// pattern as the Channels equalizer icon" not in vv

    # ── FU-192 (S2.8): the roster's tally is not the entity's cycle count, and both are named ─────
    from agentic_core.economy import ledger as _ledger_mod
    from agentic_core.economy.ledger import VirtualLedger
    # a repeatable probe: these books are built here, so start from none rather than from a prior run's
    for _stale in (_ledger_mod._STORE / "w491-cycles_ledger.json",):
        _stale.unlink(missing_ok=True)
    led = VirtualLedger("w491-cycles")
    st = led.statement()
    assert "cycles_posted" in st and "cycles_posted_basis" in st
    assert st["cycles_posted"] == 0
    led.record("revenue", 100.0, memo="cycle intake (revenue)", ref="cyc-a")
    led.record("revenue", 50.0, memo="cycle intake (revenue)", ref="cyc-a")   # same cycle, two postings
    led.record("revenue", 25.0, memo="cycle intake (revenue)", ref="cyc-b")
    led.record("owner", 10.0, memo="owner draw")                              # not a cycle intake
    st2 = VirtualLedger("w491-cycles").statement()
    assert st2["cycles_posted"] == 2, st2["cycles_posted"]       # cycles, not postings and not entries
    assert st2["entry_count"] > st2["cycles_posted"]
    assert "one intake entry per metabolic cycle" in st2["cycles_posted_basis"]
    lv = (root / "agentic_core/economy/living_vsbs.py").read_text(encoding="utf-8")
    assert "cycles this autonomous roster ran and booked" in lv
    assert 'r["ledger_cycles"] = _st.get("cycles_posted")' in lv     # the books' count reaches the row
    assert lv.count('r["ledger_cycles_unavailable"]') == 2   # BOTH legs: a load error and a raise
    assert lv.count('r["ledger_cycles"] = None') == 2       # neither leg reports unreadable as zero
    econ_ui = (app / "pages/enterprise/VSBEconomy.tsx").read_text(encoding="utf-8")
    assert "roster cycles" in econ_ui and "on the books" in econ_ui
    assert "operating_cycles_basis" in econ_ui and "ledger_cycles" in econ_ui
    av = (root / "agentic_core/avatars/api.py").read_text(encoding="utf-8")
    assert "cycles run by the " in av and "operating cycles\"" not in av

    # ── the six single-surface rows: each count/label now names its own population ────────────────
    mkt = (app / "pages/marketplace/LivingMarketplace.tsx").read_text(encoding="utf-8")
    assert "listings-caption" in mkt

    sol = (app / "pages/SolutionsPlatform.tsx").read_text(encoding="utf-8")
    assert 'block mb-1.5">AI model note</label>' in sol      # the visible label
    assert 'aria-label="AI model note"' in sol               # and the accessible name
    assert "AI Model\"" not in sol and ">AI Model</label>" not in sol
    assert "'/api/v1/ai/query', { query: prompt }" in sol        # the field the route actually takes

    nai = (app / "pages/developers/NativeAI.tsx").read_text(encoding="utf-8")
    assert "ensemble-label" in nai

    emp = (app / "pages/domains/EmploymentHub.tsx").read_text(encoding="utf-8")
    assert "setActiveTab('path')" in emp        # the Career Path button goes to the Career Path tab

    cui = (app / "pages/governance/ConstitutionalUI.tsx").read_text(encoding="utf-8")
    assert "ueg-trail-count" in cui and "uegTotal" in cui        # a page of events is not the total

    org = (app / "pages/organism/OrganismDashboard.tsx").read_text(encoding="utf-8")
    assert "composite-health-basis" in org
    # the feed must READ the names the API sends, not only declare them
    assert "{sig.signal_type}" in org and "sig.age_seconds" in org
    assert "sig.ts" not in org and "{sig.type}" not in org

    # W491 refutation — the round tried to pin its own probe by searching this file for the probe's text.
    # An assertion cannot search for a literal it itself contains: it matches itself and can never fail.
    # The contract is asserted against the live response instead, where it is falsifiable.
    assert "quality" in casc and "quality_assurance" not in casc, sorted(casc.keys())
    assert "qms_gate_passed" in casc["quality"], sorted(casc["quality"].keys())

    # ── the refutation's own fixes, each with a leg that fails when it is undone ──────────────────
    # a failure is a field, not a string dressed as content
    _q = client.post("/api/v1/ai/query", json={"query": "w491 probe"}).json()
    assert set(("answer", "ok", "error")) <= set(_q), sorted(_q)
    assert _q["ok"] is (_q["error"] is None)
    assert _q["answer"] is None or not str(_q["answer"]).startswith("[unavailable:")
    assert "resp.data?.ok === false" in sol and "unavailable:" in sol   # the page branches on it

    # the delegate card reports what RAN, against what was asked for and the cap
    _dl = client.post("/api/v1/swarm/delegate", json={
        "task": "w491: report what ran", "domain": "enterprise",
        "agent_ids": ["CFO", "CTO", "CMO", "COO", "CLO", "CSO"]}).json()
    from agentic_core.api.swarm import _MAX_AGENTS_PER_RUN as _CAP
    assert len(_dl["agents_requested"]) == 6
    assert len(_dl["agents_engaged"]) <= _CAP and set(_dl["agents_engaged"]) <= set(_dl["agents_requested"])
    assert len(_dl["agents_engaged"]) == len(_dl["agent_responses"])
    assert set(_dl["agents_not_run"]) == set(_dl["agents_requested"]) - set(_dl["agents_engaged"])
    assert _dl["agents_not_run"], "a request for six agents under a cap of four ran them all?"
    assert str(_CAP) in _dl["agents_engaged_basis"]
    # and the comment that justified the router fix no longer overclaims: five keys ARE lower-case
    from agentic_core.api.swarm import _AGENTS as _AG
    assert [k for k in _AG if k == k.lower()], "the premise of the router fix has changed"
    assert "the fallback ran EVERY time" not in sw
    assert "eleven of the sixteen are capitalised" in sw

    # a resource that raised is persisted as having raised, with its error kept
    rf_src = (root / "agentic_core/api/resource_fabric.py").read_text(encoding="utf-8")
    assert rf_src.count('"outcome": x.get("outcome") or _resource_outcome(x["resource"], x)') == 2
    assert '"error": x.get("error"),' in rf_src
    # the org-cascade summary sends lists, not the cascade dict's internal keys
    assert '"management_systems": list((casc.get("management_systems") or {}).keys())' not in rf_src
    assert '"management_systems_operated"' in rf_src and '"management_systems_catalogue"' in rf_src
    assert "management_systems_operated" in rf_ui and "org-mgmt-catalogue" in rf_ui
    # the run heading counts outcomes, and the history chips show them
    assert "ran an engine, the rest read existing state" not in rf_ui
    assert "history-outcome-${rr.resource}" in rf_ui
    assert "rr.outcome === 'produced'" in rf_ui
    assert "String(r.outcome)" in rf_ui      # the heading counts outcomes, not kinds

    # the plan page shows what the composed resources DID, not a bare id list
    bpx = (app / "pages/enterprise/BusinessPlan.tsx").read_text(encoding="utf-8")
    assert "review-composition-${rv.composition_run!.run_id}" in bpx
    assert "ran an engine" in bpx and "real_resources?: { resource: string; outcome?: string }[]" in bpx

    # the caveat on a part-simulated figure is driven by what is MEASURED, not by an equality that
    # disappears when the simulated term saturates — and the landing page carries it too
    assert "measured === false" in org
    assert "composite_health_measured_only !== status.composite_health" not in org
    home = (app / "pages/DashboardNew.tsx").read_text(encoding="utf-8")
    assert "home-composite-health-basis" in home and "is not measured" in home
    nai_src = (app / "pages/developers/NativeAI.tsx").read_text(encoding="utf-8")
    assert "homeo-composite-chip" in nai_src and "part simulated" in nai_src
    # the signal feed says which page of the trail it is
    assert "signal-feed-scope" in org and "not the whole trail" in org
    # the ensemble label counts producers, not members
    assert "m => !m.error" in nai_src and "produced output" in nai_src
    # an unreadable constitutional ledger is not "no events logged"
    assert "ueg-unreadable" in cui and "not the same as no events having been logged" in cui
    assert "{uegUnreadable ? (" in cui      # the branch, not only the testid
    # the marketplace states each reason over the population it covers
    assert "listings-unpriced-count" in mkt and "priced but held" in mkt
    # W507 (FU-260, OWNER RULING 2026-09-29) — the control is RETIRED, not relabelled. W491 made it honest
    # ("your note, not sent anywhere"); the Owner then ruled that a control which answers nothing is worse
    # than no control. So this leg flips from "the label is honest" to "the control is gone", which is the
    # new truth — and it must check BOTH render paths, because this component has a tiled path and a drawer
    # path and each carried its own copy of the input.
    assert "channel-note-keep" not in cc, "the retired Channels note control is back"
    assert "queryInput" not in cc and "queryLog" not in cc,         "the retired control's state is back in CommandCenter"
    assert "handleSendQuery" not in cc, "the retired handler is back"
    assert cc.count("Note to self about the") == 0,         "a Channels note input is still rendered on one of the two paths"
    assert "You asked" not in cc and "Send query" not in cc

    # ── the FAILURE PATH, actually exercised. The blind sweep found twelve guards vacuous for one
    #    reason: nothing fails a handler in this environment, so every counter that distinguishes a
    #    failed attempt from a read agreed with the broken version. These force the failure. ─────────
    import asyncio as _aio491, types as _types491, unittest.mock as _mock491
    from agentic_core.api import resource_fabric as _rf491

    async def _forced_raise(rid, config, objective, domain):
        return {"resource": rid, "error": "forced by the w491 guard"}

    with _mock491.patch.object(_rf491, "_run_real_resource_handler", _forced_raise):
        _fail = _aio491.run(_rf491._run_real_resource("compliance", {}, "w491 probe", "general"))
    # kind is still what the resource IS; outcome says what happened, and the phrase describes no output
    assert _fail["kind"] == "facility_run" and _fail["outcome"] == "raised", _fail
    assert "neither ran nor read" in _fail["outcome_phrase"], _fail
    assert _fail["kind_phrase"] == _fail["outcome_phrase"], _fail
    with _mock491.patch.object(_rf491, "_run_real_resource_handler", _forced_raise):
        _fail_read = _aio491.run(_rf491._run_real_resource("metabolic", {}, "w491 probe", "general"))
    assert _fail_read["kind"] == "status_read" and _fail_read["outcome"] == "raised", _fail_read

    # a run whose every call failed is not a run either
    async def _all_calls_failed(rid, config, objective, domain):
        return {"resource": rid, "ran": "/api/v1/x", "calls": 3, "failed_calls": 3, "output": ""}

    with _mock491.patch.object(_rf491, "_run_real_resource_handler", _all_calls_failed):
        _nc = _aio491.run(_rf491._run_real_resource("compliance", {}, "w491 probe", "general"))
    assert _nc["outcome"] == "no_calls_ran" and "produced nothing" in _nc["outcome_phrase"], _nc

    # the cascade RECORDS a failed requisition instead of dropping it, counts it as failed, and counts
    # nothing as run or read
    with _mock491.patch.object(_rf491, "_run_real_resource_handler", _forced_raise):
        _fc = client.post("/api/v1/swarm/cascade", json={
            "mission": "verify regulatory compliance and optimise compute resource allocation",
            "domain": "enterprise"}).json()
    _ffr = _fc["fabric_requisitions"]
    assert _ffr, "a requisition whose handler raised was dropped instead of recorded"
    assert all(f["outcome"] == "raised" and f["error"] for f in _ffr), _ffr
    _fsm = _fc["fabric_requisitions_summary"]
    assert _fsm["requisitioned"] == len(_ffr), _fsm
    assert _fsm["failed"] == len(_ffr), _fsm
    assert _fsm["facilities_ran"] == 0 and _fsm["state_read"] == 0, _fsm
    # and the tiers are told what happened, not that nothing matched
    assert "none matched the mission" not in str(_fc.get("measured_outcomes", "")), _fc.get("measured_outcomes")

    # `readable` is MEASURED: with git unable to answer, the endpoint says so and claims no counts
    from agentic_core.api import integration_surface as _is491

    class _FakeProc:
        def __init__(self, rc, out="", err=""):
            self.returncode, self.stdout, self.stderr = rc, out, err

    _fake_sp = _types491.SimpleNamespace(
        run=lambda *a, **k: _FakeProc(1, "", "fatal: not a git repository"))
    with _mock491.patch.object(_is491, "subprocess", _fake_sp):
        _gh_bad = _aio491.run(_is491.git_history(limit=5))
    assert _gh_bad["readable"] is False and _gh_bad["unreadable_reason"], _gh_bad
    assert _gh_bad["repository_commits_total"] is None, _gh_bad
    assert _gh_bad["returned"] == 0 and _gh_bad["repository"] is None, _gh_bad
    assert _gh_bad["is_user_project_activity"] is False, _gh_bad
    # a log that fails PARTWAY still reports unreadable, and does not pass its partial page off as whole
    _part = iter([_FakeProc(0, "C:/repo\n", ""), _FakeProc(128, "abc|me|1 day ago|partial\n", "fatal: bad object")])
    _fake_sp2 = _types491.SimpleNamespace(run=lambda *a, **k: next(_part))
    with _mock491.patch.object(_is491, "subprocess", _fake_sp2):
        _gh_part = _aio491.run(_is491.git_history(limit=5))
    assert _gh_part["readable"] is False and _gh_part["returned"] == 1, _gh_part
    assert _gh_part["repository_commits_total"] is None, _gh_part

    cockpit = (app / "pages/enterprise/VSBCockpit.tsx").read_text(encoding="utf-8")
    assert "standards-catalogue-basis" in cockpit
    assert "Standards the generators can draft against" in cockpit
    assert "Living management systems (BMS" not in cockpit
def test_w492_the_page_says_what_the_engine_said(client):
    """W492 — P1.18 + P2.4 + P2.6 + P2.7 + P2.8 + P2.9, the C5 batch taken repo-wide.

    Ten rows, one rule: NOTHING THAT QUALIFIES A CLAIM MAY BE DROPPED BETWEEN THE ENGINE THAT
    PRODUCED IT AND THE SURFACE THAT SHOWS IT — and no surface may present as current, verified or
    successful what the API reported as stale, unchecked or failed.

    Four shapes. A second writer strips the qualifier (FU-182 the marketplace screen drops its own
    `basis`; FU-215 a hard-coded '20% simulated' over a card whose own line says 40% measured; FU-196
    a missing tail anchor still answering 'verified'). The API says failure and the page says otherwise
    (FU-210 a swallowed 409; FU-216 an error frame caught by 'malformed event — skip'; FU-212 a stale
    cycle shown as current). A value is fabricated or dropped inside the pipeline (FU-183 a model name
    returned with an empty estate; FU-197 the requested domain dropped and an unknown tier given free
    quota with paid scheduling; FU-198 derived genomes carrying no provenance). And a self-contradicting
    literal (FU-188 'Chief (owner twin)' in six writers while the same documents say none is trained).
    """
    import asyncio as _aio492
    import pathlib
    import types as _types492
    import unittest.mock as _mock492
    root = pathlib.Path(__file__).resolve().parents[1]
    app = root / "apps/workstation-superapp/src"

    # ── FU-183 (S7.1): a model that is not installed is not the serving default ───────────────────
    from agentic_core.ai.native import model_resource as _mr
    lc = client.get("/api/v1/native-ai/lifecycle").json()
    assert set(("effective_default", "configured_default", "serves", "serving_basis")) <= set(lc), lc
    assert lc["serves"] in ("local_model", "native_floor")
    # W492 refutation — `(serves == "local_model") is bool(effective_default)` restates the line that
    # computes it and can never fail. The falsifiable property: what SERVES must be something the
    # estate actually holds, and the floor is claimed only when the estate holds no named default.
    if lc["effective_default"]:
        assert lc["effective_default"] in (lc.get("active_estate") or []), lc
    else:
        assert lc["serves"] == "native_floor", lc
        for _named in (lc.get("promoted_default"), lc.get("configured_default")):
            assert not _named or _named not in (lc.get("active_estate") or []), (lc, _named)
    # forced: with nothing installed, the answer is the floor — not the env fallback name
    with _mock492.patch.object(_mr, "active_local_models", lambda: []):
        assert _mr.effective_default_local() is None
        assert _mr.configured_default_local()          # the configured NAME is still nameable
    # W492 refutation — the first fix presence-checked only the ENV branch, so a PROMOTED model that
    # had been uninstalled was still returned as what serves. Both branches, forced.
    with _mock492.patch.object(_mr, "lifecycle_state", lambda: {"default_local": "ghost-model"}):
        with _mock492.patch.object(_mr, "active_local_models", lambda: []):
            assert _mr.effective_default_local() is None, "a promoted model that is gone still serves"
        with _mock492.patch.object(_mr, "active_local_models", lambda: ["ghost-model"]):
            assert _mr.effective_default_local() == "ghost-model"
    # and the basis never asserts a model is installed when the estate does not hold it
    from agentic_core.api.native_ai import _serving_basis as _sb492
    assert "is installed and serves" not in _sb492(None, "ghost", "ghost", [])
    assert "not in the installed estate" in _sb492(None, "ghost", "ghost", ["other"])
    assert "is installed and serves" in _sb492("real", None, "real", ["real"])
    # an ATTEMPT may still use the configured name; only the REPORT must say the floor
    from agentic_core.ai.gateway import gateway as _gw
    with _mock492.patch.object(_mr, "active_local_models", lambda: []):
        assert _gw._effective_ollama_model, "the attempt path lost its model name"
    nai = (app / "pages/developers/NativeAI.tsx").read_text(encoding="utf-8")
    assert nai.count('data-testid="serving-default"') == 2   # BOTH branches: installed, and the floor
    assert '<span data-testid="serving-default" title={lifecycle.serving_basis}>' in nai
    assert "no local model is installed" in nai
    assert "is configured but absent" in nai

    # ── FU-197 (S4.21): the domain survives, and one tier resolution governs share AND scheduling ──
    from agentic_core.optimizer.allocator import AllocationEngine as _AE
    assert "standard" in _AE.QUOTAS, "the platform's own default tier is absent from its quota table"
    for _t, _q in _AE.QUOTAS.items():
        assert "queued" in _q, (_t, _q)          # each tier declares its scheduling, not just its share
    assert _AE.resolve_tier("made-up")["tier_recognised"] is False
    assert _AE.resolve_tier("made-up")["tier_applied"] == _AE.DEFAULT_TIER
    assert _AE.QUOTAS[_AE.DEFAULT_TIER]["queued"] is True, "an unrecognised tier must not get paid scheduling"
    # the engine hands the declaration to the scheduler; letting the scheduler re-decide from the tier
    # NAME is how the two diverged in the first place
    _esrc = (root / "agentic_core/optimizer/engine.py").read_text(encoding="utf-8")
    assert 'queued=bool(self.allocator.QUOTAS[resolved["tier_applied"]]["queued"])' in _esrc
    al = client.post("/api/v1/optimizer/allocate",
                     json={"domain": "science", "requirements": {"CPU": 2, "RAM": 512},
                           "tier": "standard"}).json()
    assert al["status"] == "SUCCESS", al
    _a = al["allocation"]
    assert _a["domain"] == "science", "the requested domain was dropped again"
    assert _a["tier_recognised"] is True and _a["tier_applied"] == "standard"
    assert _a["status"] == "COMPUTED" and "no capacity is reserved" in _a["status_basis"]
    # the verifier returns the domain it insists on
    from agentic_core.optimizer.ral import RALVerifier
    import json as _json492
    _v = RALVerifier().verify_request(_json492.dumps(
        {"id": "w492", "domain": "law", "requirements": {"compute": 1}}))
    assert _v["domain"] == "law", _v
    # an unrecognised tier is queued AND flagged, not silently given the free share with paid scheduling
    al2 = client.post("/api/v1/optimizer/allocate",
                      json={"domain": "science", "requirements": {"CPU": 2, "RAM": 512},
                            "tier": "a-tier-that-does-not-exist"}).json()
    assert al2.get("tier_recognised") is False, al2
    assert al2["status"] in ("QUEUED", "REJECTED"), al2

    # ── FU-196 (S10.13): a missing anchor is not a verification, and unreadable is not tampering ───
    from agentic_core.integrity import anchor_state as _anchor_state
    import tempfile as _tf492, os as _os492
    _d = _tf492.mkdtemp()
    assert _anchor_state(_os492.path.join(_d, "nope.anchor"))["state"] == "absent"
    _bad = _os492.path.join(_d, "bad.anchor")
    with open(_bad, "w", encoding="utf-8") as _f:
        _f.write("{not json")
    assert _anchor_state(_bad)["state"] == "unreadable"
    ver = client.get("/api/v1/gaas/ueg/verify").json()
    assert ver["outcome"] in ("verified", "unreadable", "hash_mismatch",
                              "anchor_mismatch", "node_count_below_anchor"), ver
    assert "anchor_checked" in ver and "verified_basis" in ver
    if ver["outcome"] == "verified":
        # a clean recomputation says whether truncation was ALSO ruled out
        assert ("truncation and rollback are ruled out" in ver["verified_basis"]) is bool(ver["anchor_checked"])
    # W492 - the anchor is always present here, so every leg that distinguishes a FULL verification
    # from a hash-only one agreed with the broken version. Forced: verify a ledger whose anchor is
    # absent, and one whose anchor is corrupt.
    from agentic_core.gaas.v5.ueg import UEGLogger as _UEG492
    _u = _UEG492(storage_path=str(pathlib.Path(_d) / "w492_ueg.json"))
    _u.log({"type": "w492", "action": "a"})
    _anch = _u.storage_path + ".anchor"
    _os492.remove(_anch)
    _noanchor = _u.verify_chain()
    assert _noanchor["valid"] is True and _noanchor["outcome"] == "verified", _noanchor
    assert _noanchor["anchor_checked"] is False and _noanchor["anchor_state"] == "absent", _noanchor
    assert "are NOT ruled out" in _noanchor["verified_basis"], _noanchor
    with open(_anch, "w", encoding="utf-8") as _f:
        _f.write("{not json")
    _badanchor = _u.verify_chain()
    assert _badanchor["anchor_checked"] is False and _badanchor["anchor_state"] == "unreadable", _badanchor
    assert "are NOT ruled out" in _badanchor["verified_basis"], _badanchor
    # and an UNREADABLE ledger is reported as unreadable, claiming no count and no root hash
    with open(_u.storage_path, "w", encoding="utf-8") as _f:
        _f.write("{corrupt")
    _unread = _u.verify_chain()
    assert _unread["valid"] is False and _unread["outcome"] == "unreadable", _unread
    assert _unread["events"] is None and _unread["root_hash"] is None, _unread
    assert "this is not evidence of tampering" in _unread["verified_basis"], _unread

    gh_ui = (app / "pages/governance/GovernanceHub.tsx").read_text(encoding="utf-8")
    cu_ui = (app / "pages/governance/ConstitutionalUI.tsx").read_text(encoding="utf-8")
    # W492 refutation — this decided coverage by COUNTING one string, and the count was satisfied by
    # the Chain Integrity card alone while the Root Hash and UEG Events cards still printed figures
    # for a ledger that was never read. Every surface is named.
    assert "? (verify.outcome === 'unreadable'" in gh_ui          # the narrative
    assert "verify.outcome === 'unreadable' ? 'UNREADABLE'" in gh_ui   # the Chain Integrity card
    assert "verify.outcome === 'unreadable' ? 'NOT ASSESSED'" in gh_ui  # the chain-verified figure
    assert "verify?.root_hash ? `${String(verify.root_hash).slice(0, 10)}" in gh_ui   # Root Hash card
    assert "typeof verify?.events === 'number' ? verify.events" in gh_ui             # UEG Events card
    assert "typeof r.events === 'number'" in gh_ui                # the audit-run row
    assert "String(verify.root_hash)" not in gh_ui.replace("verify?.root_hash ? `${String(verify.root_hash)", "")
    assert "not evidence of tampering" in gh_ui
    assert "verify.anchor_checked" in gh_ui and "chain-verified-figure" in gh_ui
    assert "ledger-integrity-verdict" in cu_ui and "TRUNCATION NOT RULED OUT" in cu_ui
    assert "integrity.valid ? (integrity.anchor_checked ? \"VERIFIED\"" in cu_ui
    assert "the ledger was not read" in _code_only(cu_ui)        # no count or root for books not read
    assert "{typeof integrity.events === 'number' && integrity.root_hash" in cu_ui

    # ── FU-182 (S12.7): the screen's own basis reaches the drawer, and a screen fault holds ────────
    from agentic_core.api import marketplace as _mk
    _scr = _mk._screen_listing("W492 probe", "A maths tutoring listing", [])
    assert _scr.get("basis"), "the screen's basis is dropped by the second writer again"
    assert "it cannot clear" in _scr["basis"]
    assert "coverage_gaps" in _scr and "assessed_by" in _scr
    # a screen that RAISED is not a pass: the listing is held
    def _boom(*a, **k):
        raise RuntimeError("forced by the w492 guard")
    with _mock492.patch("agentic_core.api.compliance.screen_compliance", _boom):
        _err = _mk._screen_listing("W492 probe", "text", [])
    assert _err["overall"] == "error" and _err["hold"] is True, _err
    assert "held until a screen completes" in _err["basis"]
    mkt = (app / "pages/marketplace/LivingMarketplace.tsx").read_text(encoding="utf-8")
    assert "not a certification" in mkt and "screen-basis" in mkt
    assert "screen-coverage-gaps" in mkt and "v.reason" in mkt
    assert "the §11 screen could not run, so the public text was NOT re-screened" in mkt
    # W492 refutation — this round's own hold fix made the error arm unreachable (held matched first),
    # so the branch is now tested BEFORE held, and the held banner says which reason applies.
    assert "setNotice(d.compliance?.overall === 'error'" in mkt
    assert "held-reason" in mkt and "screen COULD NOT RUN" in mkt

    # ── FU-188 (S8.9): no surface calls the Chief a trained twin ───────────────────────────────────
    for _p, _lit in (
        ("agentic_core/api/genesis.py", "Chief (owner twin)"),
        ("agentic_core/api/genesis.py", "Chief = owner's digital twin"),
        ("agentic_core/api/vsb.py", "Chief = owner's digital twin"),
        ("apps/workstation-superapp/src/pages/DashboardNew.tsx", "led by your Chief (your digital twin)"),
        ("apps/workstation-superapp/src/pages/enterprise/BusinessPlan.tsx", "Chief</span> (your digital twin)"),
        ("apps/workstation-superapp/src/components/organism/SwarmIntelligence.tsx",
         "'Chief of the Board (founder digital twin)'"),
    ):
        assert _lit not in (root / _p).read_text(encoding="utf-8"), (_p, _lit)
    gen = (root / "agentic_core/api/genesis.py").read_text(encoding="utf-8")
    assert "no twin model is trained" in gen
    # any wording that presents the Chief AS a twin, not one exact literal
    swi = (app / "components/organism/SwarmIntelligence.tsx").read_text(encoding="utf-8")
    assert "digital twin)'" not in swi, swi[swi.find("Chief of the Board") - 40:][:200]
    assert "standing charter" in swi

    # ── FU-198 (S8.14): a derived genome carries its lineage, so no page has to guess ──────────────
    from agentic_core.organism.genome import _derived_trait_provenance as _dtp
    _unenc = _dtp([{"genome_id": "g1", "encoded": False,
                    "trait_provenance": {"parsed": [], "defaulted": ["innovation"]}}], "mutation")
    assert _unenc["trait_provenance"]["parsed"] == []
    assert "NOT an analysis of the entity" in _unenc["encoding_note"]
    _part = _dtp([{"genome_id": "g2", "encoded": True,
                   "trait_provenance": {"parsed": ["innovation"], "defaulted": []}}], "crossover")
    assert "descend from parsed parent values" in _part["encoding_note"]
    gsrc = (root / "agentic_core/organism/genome.py").read_text(encoding="utf-8")
    assert gsrc.count('_derived_trait_provenance(') == 3   # the helper plus BOTH derived writers
    # W492 refutation — the helper was first inserted BETWEEN @router.post("/genome/crossover") and its
    # handler, so the decorator bound to the HELPER and the route 422'd for every real caller while the
    # module still imported and the app still booted. A route is verified by CALLING it.
    import ast as _ast492
    _decorated = {n.name: [_ast492.unparse(d) for d in n.decorator_list]
                  for n in _ast492.walk(_ast492.parse(gsrc))
                  if isinstance(n, (_ast492.FunctionDef, _ast492.AsyncFunctionDef))}
    assert _decorated["crossover_genomes"] == ["router.post('/genome/crossover')"], _decorated["crossover_genomes"]
    assert _decorated["_derived_trait_provenance"] == [], _decorated["_derived_trait_provenance"]
    _ga = client.post("/api/v1/organism/genome/encode",
                      json={"entity_name": "w492 A", "domain": "general", "description": "a"}).json()
    _gb = client.post("/api/v1/organism/genome/encode",
                      json={"entity_name": "w492 B", "domain": "general", "description": "b"}).json()
    _cx = client.post("/api/v1/organism/genome/crossover",
                      json={"genome_a_id": _ga["genome_id"], "genome_b_id": _gb["genome_id"]})
    assert _cx.status_code == 200, _cx.text
    _cxj = _cx.json()
    assert "fitness_score" in _cxj and _cxj["trait_provenance"]["derivation"] == "crossover", _cxj
    _mu = client.post("/api/v1/organism/genome/mutate", json={"genome_id": _ga["genome_id"]})
    assert _mu.status_code == 200 and _mu.json()["trait_provenance"]["derivation"] == "mutation", _mu.text
    anat = (app / "pages/organism/OrganismAnatomy.tsx").read_text(encoding="utf-8")
    assert "genome-provenance-unknown" in anat and "derived from a parent record" in anat

    # ── FU-215 (S8.13): the blend caption is computed, and a default is not a simulation ───────────
    assert "blend-caption" in anat and "not measured)" in anat
    assert "blended (20% simulated)" not in anat
    assert "'DEFAULTED'" in anat and "/default/i.test" in anat
    hs = client.get("/api/v1/organism/health-summary").json()
    _terms = hs.get("composite_health_terms") or {}
    assert _terms, hs
    _un = [k for k, t in _terms.items() if not t.get("measured")]
    # every unmeasured term says HOW it is unmeasured, so the page never has to guess the word
    for k in _un:
        assert _terms[k].get("basis"), (k, _terms[k])

    # ── FU-210 (S3.15): a refused delivery is said ─────────────────────────────────────────────────
    bpx = (app / "pages/enterprise/BusinessPlan.tsx").read_text(encoding="utf-8")
    assert "Delivery refused" in bpx and "data?.detail" in bpx
    assert "the run is best-effort" not in bpx        # the empty catch is gone
    assert "returned no workflow tree" in bpx

    # ── FU-216 (S12.9): the error frame is not swallowed by the parse catch ────────────────────────
    ph = (app / "pages/projects/ProjectsHub.tsx").read_text(encoding="utf-8")
    assert "throw new Error(payload.error)" not in ph
    assert "} catch { continue; }" in ph             # only the PARSE is tolerated
    assert "if (payload.error) {" in ph and "status: 'error'" in ph
    assert "The stream closed before the run reported completion" in ph

    # ── FU-212 (S13.6): a saved cycle is dated, and the tile tones from levels that exist ──────────
    se = (app / "pages/evolution/SovereignEvolution.tsx").read_text(encoding="utf-8")
    assert "introspection-as-of" in se and "not live values" in se
    assert "roadmap.created_at" in se
    assert "'NONE'" not in se and "'LOW'" not in se   # levels immune.status() never emits
    assert "=== 'NOMINAL' ? 'good'" in se and "'CRITICAL' ? 'bad'" in se
    from agentic_core.organism.immune import immune as _immune
    assert _immune.status().get("threat_level") in ("NOMINAL", "ELEVATED", "HIGH", "CRITICAL")
def test_w493_a_present_tense_claim_needs_the_process_running(client):
    """W493 — P1.18 + P2.4 + P2.9, the C4 batch taken repo-wide.

    Nine rows, one rule: A PRESENT-TENSE CLAIM ABOUT A PROCESS MUST BE BACKED BY THAT PROCESS
    ACTUALLY RUNNING — and a control's label names what the control does, not what a future version
    would do.

    Three shapes. A counter or state advanced before the thing happened (FU-165 generation incremented
    on FILING while the genome mutates only on approval). A capability described in the present tense
    while its lever is off or its scope is narrower than stated (FU-176 "self-aligns … continuous" with
    execute=false and auto_align off; FU-214 "every living VSB each beat" when one is tended per beat;
    FU-205 "self-running" with all five levers off; FU-193 an endowment base "protected" by a share > 0).
    And a control or panel naming something that does not exist (FU-152 "Run Pipeline" that discards the
    canvas; FU-202 a static "Event Stream" shown even when the read failed; FU-154 badges nothing reads;
    FU-204 governance bodies absent from the codebase).
    """
    import pathlib
    root = pathlib.Path(__file__).resolve().parents[1]
    app = root / "apps/workstation-superapp/src"

    # ── FU-165 (S1.21): a generation happens on APPLY, not on filing ───────────────────────────────
    est = client.post("/api/v1/genesis/establish",
                      json={"problem": "w493 evolve probe venture", "ship_output": False,
                            "name": "W493 Evolve Co"}).json()
    vid = est["vsb_id"]
    before = client.get(f"/api/v1/vsb/{vid}").json().get("generation", 0)
    ev = client.post(f"/api/v1/vsb/{vid}/evolve", json={"trigger": "w493"}).json()
    assert ev["applied"] is False, ev
    assert ev["generation"] == before, (ev, before)          # filing advances nothing
    assert ev["evolution_cycles_run"] >= 1, ev               # the cycle it DID run is counted
    assert "a filed cycle" in ev["generation_basis"], ev
    assert ev["outcome"] in ("proposals_filed_pending_approval", "no_proposals",
                             "proposals_not_filed"), ev
    assert ev["outcome_basis"], ev
    if ev["outcome"] == "proposals_filed_pending_approval":
        assert ev["evolution_pending_cca"], ev
        assert "only on" in ev["outcome_basis"] and "approves" in ev["outcome_basis"], ev
    # the entity itself did not move
    assert client.get(f"/api/v1/vsb/{vid}").json().get("generation", 0) == before
    # and every no-op return from the apply carries the same keys, so no reader gets undefined
    ap = client.post(f"/api/v1/vsb/{vid}/evolution/apply").json()
    assert set(("applied", "cca_id", "generation")) <= set(ap), sorted(ap)
    vsrc = (root / "agentic_core/api/vsb.py").read_text(encoding="utf-8")
    assert 'vsb["generation"] = int(vsb.get("generation", 0)) + 1' in vsrc     # advanced on apply
    assert 'vsb["evolution_cycles_run"] = int(vsb.get("evolution_cycles_run", 0)) + 1' in vsrc
    ck = (app / "pages/enterprise/VSBCockpit.tsx").read_text(encoding="utf-8")
    assert 'data-testid="evolve-outcome"' in ck and "nothing applied yet" in ck
    assert "evolve-generation-basis" in ck        # the qualifier reaches the page, not just the API
    # W493 refutation - the APPLY path advanced the generation on every call, so an approval consumed
    # with zero applicable mutations still minted a new generation: the same defect the filing path was
    # fixed for, re-committed one function along. It is conditional now, and the reply says which.
    assert 'if applied:\n        vsb["generation"] = int(vsb.get("generation", 0)) + 1' in vsrc
    assert '"generation_advanced": bool(applied)' in vsrc
    assert '"generation_basis": ("advanced by this apply, because the traits actually changed"' in vsrc
    assert "if applied else" in vsrc and "no mutation was " in vsrc
    # and a cycle that files nothing no longer reports an EARLIER cycle's CCA as its own filing
    assert ev["pending_cca_is_from_an_earlier_cycle"] is False, ev
    assert '"outcome": ("proposals_filed_pending_approval" if (proposals and _pending) else' in vsrc
    # the signal names the cycle that ran, not a generation that has not happened
    assert "Evolution cycle {int(vsb.get('evolution_cycles_run', 0)) + 1} for {vsb_id} " in vsrc
    # the board pack versions on the evolution state that actually moved (a filing changes no generation)
    assert '"/gen=" + str(int(vsb.get("generation", 0)))' in vsrc and "_evo_stamp" in vsrc

    # ── FU-176 (S7.5): mapping is not acting, and continuous means the lever is on ─────────────────
    al = client.post("/api/v1/cognition/align", json={"execute": False}).json()
    # W493 refutation - `or []` made both legs vacuously true whenever the gap list came back empty,
    # which is one data state away (a store at full realisation returns none). The shape is asserted.
    assert isinstance(al.get("gaps_routed"), list), al
    assert isinstance(al.get("executed"), list), al
    assert all(g.get("executed") is False for g in al["gaps_routed"]), al
    assert al["executed"] == [], al
    ci = (app / "pages/CognitionIntegration.tsx").read_text(encoding="utf-8")
    assert "self-aligns</span>:" not in ci                   # the present-tense claim is gone
    assert "Mapping only: naming an owner is not acting on it" in ci
    assert "names the tier that owns each gap" in ci
    assert "gaps routed (evidence-based)" not in ci
    assert "mapped to an owning tier" in ci and "plan only" in ci
    # the lever is READ (the fetch itself), not merely referenced
    assert "apiJson<{ auto_align?: boolean; running?: boolean }>('/api/v1/heartbeat/status')" in ci
    # a lever set to true does nothing while the heartbeat is stopped, so the page reads both
    assert "setBeating" in ci and "the heartbeat is STOPPED, so it is not running" in ci
    assert "setBeating(typeof d?.running === 'boolean' ? d.running : null)" in ci   # read, not declared
    assert "setAutoAlign" in ci
    hb = client.get("/api/v1/heartbeat/status").json()
    assert "auto_align" in hb, sorted(hb)

    # ── FU-205 (S6.18): "self-running" names levers, and the page reads them ───────────────────────
    home = (app / "pages/DashboardNew.tsx").read_text(encoding="utf-8")
    assert "generated end-to-end, self-running, in-house" not in home
    assert "autonomy-levers" in home and "/api/v1/heartbeat/status" in home
    assert "none is on" in home
    # W493 refutation - the page read the five levers but not whether the heartbeat BEATS, so with every
    # lever set and the process stopped it still said "self-running levers on". It reads `running` too.
    assert "beating: typeof data?.running === 'boolean' ? data.running : null" in home
    assert "levers.beating === false" in home
    assert "heartbeat is STOPPED, so none of them is running" in home
    assert "running" in hb, sorted(hb)
    for _k in ("auto_evolve", "auto_economy", "auto_align", "auto_compliance", "auto_ship"):
        assert _k in hb, (_k, sorted(hb))

    # ── FU-214 (S9.5): one VSB per beat, not every VSB each beat ───────────────────────────────────
    hm = (app / "pages/organism/HeartbeatMonitor.tsx").read_text(encoding="utf-8")
    assert "Operates each living VSB on the beat" not in hm
    assert "Re-screens every living VSB" not in hm
    assert "ONE living VSB per beat" in hm and "least recently operated" in hm
    assert "round-robin" in hm
    assert "Routes vision gaps to delivery tiers each beat" not in hm
    # the code this describes: one entity per beat
    lv = (root / "agentic_core/economy/living_vsbs.py").read_text(encoding="utf-8")
    # W493 refutation - the literal occurs only in prose (a module docstring and a comment); the
    # BEHAVIOUR is the sort that takes a single entity.
    assert "least-recently-operated" in _code_only(lv)
    assert "sorted(entries, key=lambda v: (str(v.get(\"last_operated\") or \"\")," in lv
    assert "def operate_one(" in lv
    # the autonomous evolution picker must sort by the CYCLE stamp: sorting by the APPLIED stamp lets an
    # entity that files every beat sort first forever and starves every other entity, with no error
    hbsrc = (root / "agentic_core/organism/heartbeat.py").read_text(encoding="utf-8")
    assert 'return str(_rec.get("last_evolution_cycle") or _rec.get("last_evolved") or "")' in hbsrc
    assert '.get("last_evolved") or ""))[0]' not in hbsrc
    # W493 refutation (the pre-flight's own lead) - the heartbeat published `last_vsb_evolved` as a bare
    # generation for a cycle that only FILED, and recorded the action "evolution_applied" whenever the
    # apply merely RAN - including consuming an approval with no applicable mutation. Both name what
    # happened now. `/heartbeat/status` is a surface even with no page on it.
    assert '"generation_advanced": False,' in hbsrc
    assert '"evolution_cycles_run": _evd.get("evolution_cycles_run"),' in hbsrc
    assert "no generation advanced here" in hbsrc
    assert 'if _ap.get("generation_advanced") or int(_ap.get("mutations_applied") or 0) > 0:' in hbsrc
    assert "evolution_approval_consumed_no_mutation_applicable" in hbsrc
    # W493 refutation - the same claim had a SECOND surface, which still said every entity each beat
    ec = (app / "pages/enterprise/VSBEconomy.tsx").read_text(encoding="utf-8")
    assert "each beat re-screens ONE entity in round-robin" in ec
    assert "Not screened is NOT the same as clean." in ec

    # ── FU-193 (S1.23): the rule that exists is stated; the one that does not is named ─────────────
    assert "the endowment base is protected" not in ck
    assert "requires a non-zero capital_fund" in ck and "no endowment base" in ck
    mb = (root / "agentic_core/economy/metabolism.py").read_text(encoding="utf-8")
    assert 'template.get("capital_preserved", False) and w["capital_fund"] <= 0' in mb   # the whole rule
    # W493 refutation - the cascade control said the run was simulated on a twin; no twin model exists,
    # the cascade runs as staged prompts on the in-house fabric.
    assert "no twin model is simulated" in ck

    # ── FU-202 (S11.2): an unreadable run list is not an idle swarm ────────────────────────────────
    swi = (app / "components/organism/SwarmIntelligence.tsx").read_text(encoding="utf-8")
    assert "Swarm intelligence online" not in swi
    assert "Emergence Event Stream" not in swi
    assert "swarm-runs-unreadable" in swi and "swarm-runs-empty" in swi
    assert "setRunsErr(errorMessage(e))" in swi              # the failure is captured, not swallowed
    assert "it is not a live stream" in swi
    # W493 refutation - this was scoped by split() to the text BEFORE loadCascadeRuns, so the second,
    # identical swallow in the same file was excluded from the assertion it was written for.
    assert "catch { /* empty state */ }" not in swi
    assert "setCascadeErr(errorMessage(e))" in swi          # the second read reports its failure too
    assert "cascade-runs-unreadable" in swi and "swarm-runs-panel-unreadable" in swi
    assert "emergence-loading" in swi                       # and nothing is claimed before the first read
    # W493 refutation - several of this round's disclosures were carried as Badge `title` tooltips, and
    # the shared Badge dropped every prop it was not written for, so they never reached the DOM at all.
    ui = (root / "packages/ui/src/index.tsx").read_text(encoding="utf-8")
    assert "<span title={title} {...rest}" in ui

    # ── FU-152 (S12.5): the button names what it does, and does not silently discard work ──────────
    cs = (app / "pages/create/CreatorStudio.tsx").read_text(encoding="utf-8")
    assert "Run Pipeline" not in cs
    assert "Regenerate blueprint" in cs and "regenerate-blueprint" in cs
    assert "window.confirm" in cs and "will be discarded" in cs
    assert "if (nodes.length > 0 &&" in cs      # the confirm actually fires when there IS a graph
    assert "palette-caption" in cs and "none is" in cs and "executable" in cs
    assert "or drag components from the left palette" not in cs

    # ── FU-154 (S10.5): a badge for a preference nothing acts on says so ───────────────────────────
    for _hub in ("CareHub", "EducationHub", "EmploymentHub", "LawHub", "ReligionHub", "ScienceHub"):
        _src = (app / f"pages/domains/{_hub}.tsx").read_text(encoding="utf-8")
        assert "MODE (saved pref.)" in _src, _hub
        assert "TONE (saved pref.)" in _src, _hub
        assert "no affordance on this hub is gated on it yet" in _src, _hub
    st = (app / "pages/Settings.tsx").read_text(encoding="utf-8")
    assert "guidance and tone drive the affordances shown on the domain hubs" not in st
    assert "prefs-effect-basis" in st and "nothing yet changes with them" in st

    # ── FU-204 (S7.9): a body that does not exist is not named as governing ────────────────────────
    cb = (app / "pages/Contribute.tsx").read_text(encoding="utf-8")
    assert "Steering Committee" not in cb and "AI-led Council" not in cb
    assert "Sovereign v3.0" not in cb
    assert "Board of Directors" in cb and "Change Control" in cb
    assert "those bodies do not exist" in cb
    assert "governed by the Board and Change Control" in cb   # the header names the bodies that DO exist
    # and the claim is true: neither name exists in the backend
    import subprocess as _sp
    _hit = _sp.run(["git", "grep", "-l", "-E", "Steering Committee|AI-led Council", "--", "agentic_core"],
                   cwd=root, capture_output=True, text=True)
    assert not _hit.stdout.strip(), _hit.stdout

    # ── the round's own pre-flight: it must DETECT, not merely run ────────────────────────
    # W493 refutation - the first version asserted only exit code 0 and a banner line, so breaking the
    # checker's coverage left this green. Both shapes it MISSED this round are now asserted on the tool's
    # own behaviour: a subscript-assignment rename, and a dict inside a returned expression.
    import importlib.util as _ilu493
    sc = (root / "scripts/selfcheck_diff.py")
    assert sc.exists()
    _spec = _ilu493.spec_from_file_location("w493sc", sc)
    _mod = _ilu493.module_from_spec(_spec)
    _spec.loader.exec_module(_mod)
    # a key written by SUBSCRIPT ASSIGNMENT counts as a key - the shape that hid a starved round-robin
    assert _mod.keys_in('    vsb["last_evolved"] = now') == {"last_evolved"}
    assert "some_key" in _mod.keys_in('    return {"some_key": 1}')
    # W493 refutation - this parsed a string and walked it with the TEST's own ast code, so it proved a
    # property of the stdlib and would pass with the tool's walk reverted. It calls the TOOL now.
    import ast as _ast493
    _expr = _ast493.parse('g(x) or {"one": 1}', mode="eval").body
    assert len(_mod._returned_dicts(_expr)) == 1, "a dict inside `helper(x) or {...}` is not reached"
    _plain = _ast493.parse('{"one": 1}', mode="eval").body
    assert len(_mod._returned_dicts(_plain)) == 1
    # and a NESTED dict is not counted as a sibling return (that diluted the threshold)
    _nested = _ast493.parse('{"a": 1, "sub": {"b": 2}}', mode="eval").body
    assert len(_mod._returned_dicts(_nested)) == 1, "a nested sub-object is being counted as a sibling"
    _scsrc = sc.read_text(encoding="utf-8")
    # the walk goes through the tool's own alternatives helper (asserted on behaviour above)
    assert "for inner in _returned_dicts(sub.value):" in _scsrc
    assert "def _returned_dicts(" in _scsrc
    # W534 — this asserted the SOURCE TEXT "ASSIGN_KEY_RE.findall(line)", so it broke when FU-319's fix
    # renamed that function's local from `line` to `body` (the line is now stripped of its trailing comment
    # before being scanned). The property it actually cares about is that a key introduced by SUBSCRIPT
    # ASSIGNMENT is detected — W493 added that regex because renaming such a key had left two live readers.
    # So the property is asserted on BEHAVIOUR, which no rename can break and no spelling can fake. This is
    # the second guard in two rounds to pin a spelling rather than its property; the first was W532's.
    assert _mod.keys_in('        vsb["last_evolved"] = now') == {"last_evolved"}, \
        "a key introduced by subscript assignment is no longer detected"
    assert "ASSIGN_KEY_RE" in _scsrc, "the subscript-assignment screen is gone entirely"
    #  and it must not fire on an equality COMPARISON, which is a dict READ, not a key produced (FU-319)
    assert _mod.keys_in('        if cfg["mode"] == "strict":') == set(), \
        "a compared dict read is counted as a key produced"
    # and the scope the tool documents is the scope it reads: staged changes included
    assert 'sh("git", "diff", "--name-only", rev or "HEAD")' in _scsrc
    # a reader is live if the key is still in its content - not merely absent from the diff
    assert "if key in body:" in _scsrc
    # W493 (the round's SECOND pre-flight pass, over the finished diff) - ast.walk crosses into nested
    # function bodies, so an inner helper's returns were reported as siblings of the enclosing
    # function's and three correct returns in this round's own planner change were accused. A nested
    # def has its own return contract.
    _nest = _ast493.parse('''def outer():
    def inner():
        return {"a": 1}
    return {"b": 2, "c": 3}
''').body[0]
    _own = _mod._own_returns(_nest)
    assert len(_own) == 1, "a nested function's return is counted as the outer function's"
    assert {k.value for k in _own[0].value.keys} == {"b", "c"}
    assert "for sub in _own_returns(node):" in _scsrc
    # W493 refutation - the banner assert passed only while the author's tree was dirty (on a clean
    # checkout the tool printed "no changed files" and no banner), so it would have broken CI the moment
    # the round was committed. The banner always prints now, and the exit code discriminates because a
    # check that RAISES exits 2 rather than 0.
    _r = _sp.run([__import__("sys").executable, str(sc), "--rev", "HEAD"],
                 cwd=root, capture_output=True, text=True, encoding="utf-8", errors="replace")
    assert _r.returncode == 0, ("a check could not run:\n" + _r.stdout[-900:] + _r.stderr[-400:])
    assert "SELF-CHECK over" in _r.stdout, _r.stdout[-400:]
    assert "CHECK(S) COULD NOT RUN" not in _r.stdout, _r.stdout[-600:]
    # W493 refutation - both asserts above run against the AUTHOR's tree, so neither can see the defect
    # they were written for: the banner used to sit BEHIND the empty-diff early return, which is exactly
    # the state CI runs in, and main() returned 0 on every path including a check that RAISED. Both are
    # driven directly here, so the two asserts above discriminate instead of being true either way.
    import contextlib as _ctx493, io as _io493, sys as _sys493

    def _run_tool493(argv, files):
        _ocf, _oargv = _mod.changed_files, _sys493.argv
        _mod.changed_files = lambda rev: list(files)
        _sys493.argv = ["selfcheck_diff.py"] + argv
        _buf = _io493.StringIO()
        try:
            with _ctx493.redirect_stdout(_buf):
                _rc = _mod.main()
        finally:
            _mod.changed_files, _sys493.argv = _ocf, _oargv
        return _rc, _buf.getvalue()

    _rc0, _out0 = _run_tool493(["--rev", "HEAD"], [])
    assert _rc0 == 0, (_rc0, _out0)
    assert "SELF-CHECK over 0 changed file(s)" in _out0, _out0   # not behind the early return
    assert "nothing to compare" in _out0, _out0
    _keep493 = _mod.CHECKS["keys"]

    def _raises493(rev, files):
        raise RuntimeError("w493 deliberate")

    _mod.CHECKS["keys"] = (_keep493[0], _raises493)
    try:
        _rc2, _out2 = _run_tool493(["--rev", "HEAD", "--check", "keys"], ["agentic_core/api/vsb.py"])
    finally:
        _mod.CHECKS["keys"] = _keep493
    assert _rc2 == 2, (_rc2, _out2)          # a check that cannot run is a failure OF THE TOOL
    assert "CHECK(S) COULD NOT RUN" in _out2, _out2
    assert "w493 deliberate" in _out2, _out2


def test_w494_a_verdict_that_cannot_come_out_otherwise_is_not_an_assessment(client, monkeypatch):
    """W494 — P1.18, the gate's own batch: fourteen rows, one rule.

    A VERDICT IS NOT AN ASSESSMENT IF IT CANNOT COME OUT OTHERWISE, AND A FIGURE IS DECIDED ON WHAT
    WAS MEASURED. Three clauses. (1) Where a score blends measured with defaulted or simulated terms,
    the decision is taken on the measured-only part; an unmeasured term is unknown, never 1.0; where
    nothing was measured the decision HOLDS rather than being granted. (2) A predicate computed from
    "the bad word is absent", "a route prefix is mounted", "the output is non-empty" or "a constant
    beats a constant" is reported as the mechanical fact it is, or returned as not-assessable.
    (3) The measured share travels to every surface that prints the figure.

    Rows: FU-102 FU-103 FU-107 FU-109 FU-110 FU-116 FU-117 FU-130 FU-132 FU-135 FU-139 FU-141
    FU-147 FU-148.
    """
    import pathlib
    root = pathlib.Path(__file__).resolve().parents[1]
    app = root / "apps/workstation-superapp/src"

    # ── FU-116 / FU-110: the mode is decided on the MEASURED score ─────────────────────────────────
    from agentic_core.organism import biobus as _bb
    _real_immune = _bb.immune.status
    _real_healer = _bb.self_healer.status

    def _immune(health, threat, errs=0):
        return lambda: {"health": health, "threat_level": threat, "errors_in_window": errs}

    # THE DISCRIMINATING STATE. ATP is pinned at its ceiling, which is where a process spends all but
    # its first half-minute: the blend is then 0.4*immune + 0.4 (self-healing defaulted) + 0.2 = 0.6 +
    # 0.4*immune, which is >= 0.6 for EVERY immune value. A fresh process starts at atp 0.333, where
    # the blend happens to sit at 0.47 and the old decider would have refused too — pinning it there
    # made three legs of this test agree with the code it was written to reject.
    monkeypatch.setattr(_bb.biobus, "_update_atp", lambda *a, **k: 1.0)
    # the self-healing registry is PROCESS-GLOBAL and other tests in the same session open circuits in
    # it, so relying on "no circuit tracked yet" made this block depend on test ORDER: run after one of
    # them, measured_weight is 0.8 and the figures below differ. The state each leg needs is stated.
    monkeypatch.setattr(_bb.self_healer, "status", lambda: {"overall_health": None, "open_circuits": []})
    monkeypatch.setattr(_bb.immune, "status", _immune(0.0, "CRITICAL", 11))
    ctx = _bb.biobus.organism_context()
    assert ctx["composite_health_measured_weight"] == 0.4, ctx   # immune alone is measured here
    assert ctx["composite_health"] >= 0.6, ctx["composite_health"]   # the old decider read NOMINAL here
    assert ctx["composite_health"] >= 0.5
    assert ctx["composite_health_measured_only"] == 0.0, ctx
    assert ctx["mode"] == "EMERGENCY", (ctx["mode"], ctx["composite_health"])
    assert ctx["recommended"]["should_throttle"] is True, ctx["recommended"]
    assert ctx["recommended"]["max_parallel_agents"] == 1, ctx["recommended"]
    assert "MEASURED-only" in ctx["mode_basis"], ctx["mode_basis"]
    assert ctx["mode_decided_on"] == "composite_health_measured_only"
    assert "measured health 0%" in ctx["health_summary"], ctx["health_summary"]
    assert "of the composite's weight is measured" in ctx["health_summary"]
    # asserted on the branch that PRODUCES the claim, not on EMERGENCY where it never appeared: with
    # the FULL_POWER line restored this assertion stayed green because it was evaluated against the
    # wrong summary entirely.
    monkeypatch.setattr(_bb, "_circadian_cycle", lambda: "ACTIVE_FOCUS")
    monkeypatch.setattr(_bb.immune, "status", _immune(1.0, "NOMINAL"))
    _fp = _bb.biobus.organism_context()
    assert _fp["mode"] == "FULL_POWER", _fp["mode"]
    assert "Full cognitive power" not in _fp["health_summary"], _fp["health_summary"]
    assert "on what is measured" in _fp["health_summary"], _fp["health_summary"]
    monkeypatch.setattr(_bb.immune, "status", _immune(0.0, "CRITICAL", 11))
    assert ctx["composite_health_basis"] and "is measured" in ctx["composite_health_basis"]
    # and a healthy immune reading still reaches the good modes
    monkeypatch.setattr(_bb.immune, "status", _immune(1.0, "NOMINAL"))
    ok = _bb.biobus.organism_context()          # self-healing still stubbed untracked, so measured == immune
    assert ok["composite_health_measured_only"] == 1.0
    assert ok["mode"] in ("FULL_POWER", "NOMINAL"), ok["mode"]
    assert ok["recommended"]["should_throttle"] is False

    # and when the context ERRORS, nothing was measured, so no mode is decided — it used to report
    # NOMINAL, which is a healthy mode for a state in which nothing was read at all
    def _raise():
        raise RuntimeError("w494 forced context failure")

    monkeypatch.setattr(_bb.immune, "status", _raise)
    _fb = _bb.biobus.organism_context()
    assert _fb["mode"] == "UNKNOWN", _fb["mode"]
    assert _fb["mode_decidable"] is False and _fb["composite_health_measured_weight"] == 0.0, _fb
    assert _fb["composite_health_measured_only"] is None, _fb
    assert "nothing was measured" in _fb["mode_basis"], _fb["mode_basis"]
    # and the fallback is shape-complete for every key a consumer indexes (organism_status.py:494
    # reads self_healing["open_circuits"] and nervous["arousal_state"] on the DEGRADED/EMERGENCY path)
    for _k in ("immune", "self_healing", "nervous", "circadian", "recommended", "metabolic"):
        assert _k in _fb, _k
    assert "open_circuits" in _fb["self_healing"] and "arousal_state" in _fb["nervous"], _fb
    # clause (1) on the fallback: nothing measured means the advice HOLDS, it does not grant capacity
    assert _fb["recommended"]["should_throttle"] is True, _fb["recommended"]
    assert _fb["recommended"]["max_parallel_agents"] == 1, _fb["recommended"]
    assert "HOLDS rather than granting" in _fb["recommended"]["basis"], _fb["recommended"]
    # and the prose sentence in the same dict says what the mode says
    assert "nominal" not in _fb["health_summary"].lower(), _fb["health_summary"]
    assert "nothing was measured" in _fb["health_summary"], _fb["health_summary"]
    # the metabolic term keeps its qualifiers here too (organism_status forwards this dict verbatim)
    assert _fb["metabolic"]["measured"] is False and _fb["metabolic"]["can_fall"] is False, _fb["metabolic"]
    assert _fb["metabolic"]["basis"], _fb["metabolic"]
    # mode_decidable must agree with the test the gates apply, not publish advice they ignore
    assert ctx["mode_decidable"] is True, ctx          # a measured term exists on the success path
    assert "This is the same test the gates apply." in ctx["mode_decidable_basis"], ctx
    assert ctx["measured_weight_below_half"] is True, ctx   # and the SHARE is a separate plain fact
