def test_w521_a_failed_computation_is_not_reported_as_an_absence(monkeypatch):
    """The forecast says NOT KNOWN when the computation raised, and 'none' only when it truly found none.

    Both lines were emitted only when there was something to report, and both sat under an
    `except Exception` that produced the same empty result as success. So three different states - a batch
    exists, no batch exists, the batch computation crashed - rendered as two, with the crash borrowing the
    appearance of the honest empty case. W521 separated them; this is the leg that holds them apart, because
    the absence wording alone would pass on a generator that had silently stopped working.
    """
    import json
    from pathlib import Path as _P
    from agentic_core import plan_followups as fu

    root = _P(__file__).resolve().parents[1]
    reg = json.loads((root / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))
    txt = (root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")

    # ── 1. the honest empty case: every sweep class's rows are closed, and the line SAYS that ──────
    live = fu.render_forecast(reg, txt)
    assert "BIGGEST BATCH:" in live, live[-300:]
    assert "BIGGEST BUNDLE:" in live, live[-300:]

    # ── 2. the batch computation raises: the line must not claim there is no batch ─────────────────
    def _boom(*a, **k):
        raise RuntimeError("the register could not be grouped")

    monkeypatch.setattr(fu, "batches", _boom)
    broken = fu.render_forecast(reg, txt)
    batch_line = [ln for ln in broken.splitlines() if "BIGGEST BATCH:" in ln]
    assert batch_line, broken[-300:]
    assert "NOT KNOWN" in batch_line[0], batch_line[0]
    assert "RuntimeError" in batch_line[0], batch_line[0]      # the reason travels, not just the fact
    # and it must NOT say the reassuring thing it says when the answer really is none
    assert "no sweep class has an open row left" not in batch_line[0], batch_line[0]

    # ── 3. the bundle computation raises: the same distinction, the same wording ───────────────────
    monkeypatch.setattr(fu, "bundles", _boom)
    broken2 = fu.render_forecast(reg, txt)
    bundle_line = [ln for ln in broken2.splitlines() if "BIGGEST BUNDLE:" in ln]
    assert bundle_line, broken2[-300:]
    assert "NOT KNOWN" in bundle_line[0], bundle_line[0]
    assert "RuntimeError" in bundle_line[0], bundle_line[0]
    assert "no open row rides a plan item" not in bundle_line[0], bundle_line[0]

    # ── 4. and the rest of the page still renders — one broken computation is not a blank forecast ─
    assert "WHERE THIS IS GOING" in broken2 and "PACE," in broken2, broken2[:200]


def test_w524_the_three_meta_engines_compute_or_refuse_with_a_basis():
    """P3.13 — the meta tier computes its named quantity, or refuses and says which input was missing.

    The archived versions (`_archive/jules-unwired/.../cognitive/meta/`) are NOT recovered and this asserts
    why: Tawazun returned a graded `balance_score` of 0.95 with `resource_allocation: "OPTIMAL"`; Niyyah
    returned `ratified: True` with THREE INVENTED SIGNATORIES; Tafakkur hardcoded `drift = 0.003` with the
    formula it did not compute in a comment directly above, plus a `loeb_proof` of three strings. Recovering
    them would have re-committed the defect class W520 removed from the six foundational engines, into the
    item next door.
    """
    import asyncio as _aio
    from agentic_core.consultation.interface import ConsultationRequest as R
    from agentic_core.cognitive.meta.niyyah_engine import NiyyahEngine
    from agentic_core.cognitive.meta.tafakkur_engine import TafakkurEngine
    from agentic_core.cognitive.meta.tawazun_engine import TawazunEngine

    # ── LEG 1: every engine REFUSES on absent input, naming what was missing ────────────────────
    for name, cls in (("tawazun", TawazunEngine), ("niyyah", NiyyahEngine), ("tafakkur", TafakkurEngine)):
        r = _aio.run(cls().consult(R(engine=name, query="q")))
        assert r.metadata.get("assessable") is False, (name, r.metadata)
        assert r.answer.startswith("Not assessable:"), (name, r.answer)
        assert (r.metadata.get("basis") or "").strip(), (name, "refused with no reason")
        assert r.confidence is None, (name, r.confidence)
        assert r.served_by == "native-refused", (name, r.served_by)
        assert r.constitutional_validation.passed is None, (name, "claims a verdict over a check not run")

    # ── LEG 2: TAWAZUN computes a real frontier, and returns a SET with NO score ────────────────
    t = _aio.run(TawazunEngine().consult(R(engine="tawazun", query="q", context={
        "objectives": [{"name": "speed", "direction": "max"}, {"name": "cost", "direction": "min"}],
        "candidates": [{"id": "A", "speed": 10, "cost": 5},
                       {"id": "B", "speed": 8, "cost": 9},
                       {"id": "C", "speed": 12, "cost": 3}]})))
    # C is better than both on BOTH objectives, so the frontier is exactly {C} — a real dominance result,
    # not an ordering of the input
    assert t.metadata["frontier"] == ["C"], t.metadata
    assert t.metadata["dominated"] == ["A", "B"], t.metadata
    assert t.served_by == "native-computed", t.served_by
    assert "balance_score" not in t.metadata, "a frontier collapsed back into a score"
    assert "OPTIMAL" not in str(t.metadata), "a superlative is back"
    # a direction cannot be assumed, because assuming it INVERTS the frontier
    bad = _aio.run(TawazunEngine().consult(R(engine="tawazun", query="q", context={
        "objectives": [{"name": "speed"}], "candidates": [{"id": "A", "speed": 1}]})))
    assert bad.metadata["assessable"] is False and "direction" in bad.metadata["basis"], bad.metadata

    # ── LEG 3: NIYYAH counts real signatures and CANNOT name one that was not supplied ──────────
    n = _aio.run(NiyyahEngine().consult(R(engine="niyyah", query="q", context={
        "signatures": [{"signatory": "a"}, {"signatory": "b"}, {"signatory": "a"}, {"noname": 1}],
        "quorum_required": 2})))
    assert n.metadata["signatories"] == ["a", "b"], n.metadata
    assert n.metadata["distinct_count"] == 2 and n.metadata["duplicates_ignored"] == 1, n.metadata
    assert n.metadata["unusable_entries"] == 1, n.metadata
    assert n.metadata["ratified"] is True, n.metadata
    # THE INVARIANT: every name reported came out of the input. The archived engine invented these three.
    for invented in ("council_node_1", "council_node_2", "council_node_owner"):
        assert invented not in str(n.metadata), (invented, "a signatory nobody supplied is being named")
    # MISSING IS NOT ZERO — an absent list refuses; a present empty list is a measured zero
    absent = _aio.run(NiyyahEngine().consult(R(engine="niyyah", query="q",
                                               context={"quorum_required": 1})))
    assert absent.metadata["assessable"] is False, absent.metadata
    empty = _aio.run(NiyyahEngine().consult(R(engine="niyyah", query="q",
                                              context={"signatures": [], "quorum_required": 1})))
    assert empty.metadata["assessable"] is True, empty.metadata
    assert empty.metadata["ratified"] is False and empty.metadata["distinct_count"] == 0, empty.metadata
    # and a quorum is never defaulted, because the number IS the verdict
    noq = _aio.run(NiyyahEngine().consult(R(engine="niyyah", query="q",
                                            context={"signatures": [{"signatory": "a"}]})))
    assert noq.metadata["assessable"] is False and "quorum" in noq.metadata["basis"], noq.metadata

    # ── LEG 4: TAFAKKUR measures drift, reports its COVERAGE, and calls its threshold untuned ───
    d = _aio.run(TafakkurEngine().consult(R(engine="tafakkur", query="q", context={
        "baseline": {"x": 3.0, "y": 4.0, "z": 9.0}, "current": {"x": 3.0, "y": 8.0}})))
    # ||(0,4)|| / ||(3,8)|| = 4/sqrt(73); computed, not asserted
    assert abs(d.metadata["drift"] - (4.0 / (73 ** 0.5))) < 1e-9, d.metadata["drift"]
    # z is in the baseline only, so it was NOT measured — and is not silently counted as unchanged
    assert d.metadata["keys_measured"] == ["x", "y"], d.metadata
    assert d.metadata["baseline_keys_total"] == 3 and d.metadata["keys_measured_count"] == 2, d.metadata
    assert "were not measured and are not counted as unchanged" in d.metadata["coverage_basis"], d.metadata
    # the threshold is a DEFAULT until tuned, and the record says so in the same breath as the verdict
    assert d.metadata["threshold_is_a_default"] is True, d.metadata
    assert "NOT TUNED" in d.metadata["threshold_basis"], d.metadata["threshold_basis"]
    assert "an untuned default" in d.answer, d.answer
    # no proof is claimed, because none is performed
    assert "performs NO fixpoint" in d.metadata["no_fixpoint_proof"], d.metadata
    assert "loeb_proof" not in d.metadata and "lob_stable" not in d.metadata, d.metadata
    # a caller's own threshold is used and is NOT reported as a default
    own = _aio.run(TafakkurEngine().consult(R(engine="tafakkur", query="q", context={
        "baseline": {"x": 1.0}, "current": {"x": 1.0}, "stable_below": 0.5})))
    assert own.metadata["threshold"] == 0.5 and own.metadata["threshold_is_a_default"] is False, own.metadata
    assert own.metadata["drift"] == 0.0 and own.metadata["stable"] is True, own.metadata

    # ── LEG 5: all three are REGISTERED and reachable through the registry, not just importable ─
    from agentic_core.cognitive.registry import CognitiveEngineRegistry as Reg, EngineTier, EngineType
    from agentic_core.cognitive.registry import ENGINE_TIERS
    for et in (EngineType.TAWAZUN, EngineType.NIYYAH, EngineType.TAFAKKUR):
        assert ENGINE_TIERS[et] == EngineTier.META, et
        assert hasattr(Reg.get(et), "consult"), et


def test_w525_a_gate_with_no_input_blocks_and_the_chain_records_every_verdict():
    """P3.14 — three gates defaulted to APPROVAL on a missing field, and one raised instead of refusing.

    Measured before building: of the five gates, THREE read their field with a default that meant approval,
    so an engine returning an empty dict cleared them; gate 1 indexed its field directly and raised
    KeyError, which is neither clearing nor refusing; and gate 2 was ALREADY correct. The item's own text
    said all five defaulted to pass — corrected in the same round, because a bar that mis-states its subject
    is how a criterion comes to be written against correct output.
    """
    import asyncio as _aio
    from agentic_core.avatars.core.clearance_chain import ConstitutionalClearanceChain as _Chain

    class _UEG:
        def __init__(self):
            self.events = []

        async def log_event(self, kind, payload):
            self.events.append((kind, payload))

    #  An orchestrator whose gates all affirm, with one field removable so each gate can be driven alone.
    class _Orch:
        def __init__(self, drop=None, risk=0.05):
            self.drop, self.risk = drop, risk

        def _maybe(self, gate, payload):
            return {} if self.drop == gate else payload

        async def consult(self, emission, engines):
            return self._maybe("mushawara", {"status": "APPROVED"})

        async def process_engine(self, name, emission, context):
            if name == "niyyah":
                return self._maybe("niyyah", {"ratified": True})
            if name == "tawazun":
                return self._maybe("tawazun", {"balanced": True})
            return self._maybe("tafakkur", {"risk_score": self.risk})

        async def verify_output(self, emission):
            return self._maybe("tahqeeq", {"verified": True})

    # ── 1. every ENGINE affirms — and the chain still does not clear, at GATE 6 ─────────────────
    #  W555 (FU-364) added the sixth gate: the enforcement pattern this chain had always constructed,
    #  registered nineteen validators onto, and never consulted. Consulting it changes what this leg can
    #  assert, and the change is the honest one rather than a regression. The pattern cannot CLEAR while
    #  fifteen declared constraints have no instrument in this repository — a constraint that cannot be
    #  checked is neither a pass nor a breach — so a chain that consults it cannot clear either. Reading
    #  "could not check" as "checked and fine" at the top of the stack would be the certifies-an-absence
    #  defect this whole programme removes, one level above the screens that have it removed already.
    #  THE OBSERVABLE PLATFORM IS UNCHANGED: the live recirculation loop already withholds every emission
    #  at gate 1, so no path that cleared before stops clearing now.
    ueg = _UEG()
    ok = _aio.run(_Chain(ueg, _Orch()).validate_emission({"id": "e-ok"}, {}))
    #  OWNER RULING 2026-10-06 (FU-472, choice 1) — REWRITTEN W607, as the rule this leg encoded was changed
    #  by the Owner: gate 6 now DECIDES BY COVERAGE. It clears when every constraint that can be checked
    #  passed and none was violated, and its record NAMES every constraint it did not check, so "could not
    #  check" is never read as "checked and fine" - it is stated, constraint by constraint.
    assert ok.passed is True, ("gate 6 did not clear by coverage under the Owner's ruling", ok.reason)
    _g6 = ok.gates[5]
    assert _g6["gate"] == "enforcement" and _g6["verdict"] == "cleared", _g6
    assert "BY COVERAGE" in _g6["basis"] and "NOT CHECKED" in _g6["basis"] and "no instrument" in _g6["basis"], (
        "gate 6 cleared without stating what it did not check", _g6["basis"][:200])
    assert set(_g6["coverage"]["not_checked"]) and set(_g6["coverage"]["assessed"]), _g6.get("coverage")
    assert [g["verdict"] for g in ok.gates] == ["cleared"] * 6, ok.gates
    assert sorted(ok.attestations) == ["enforcement", "mushawara", "niyyah", "tafakkur", "tahqeeq", "tawazun"], (
        ok.attestations)

    # ── 1b. AND THE CLEARED STATE IS STILL REACHABLE, which is why 1 is not simply a weaker claim ──
    #  A chain that can NEVER clear under any circumstance is as useless as one that always does, and a
    #  leg that only ever drove the withholding path would not notice the difference. The pattern is
    #  given validators that all assess and pass, and the chain then clears through all six gates.
    class _Clear:
        def validate(self, target, context=None):
            from agentic_core.validation.enforcement_pattern import ValidationResult as _VR
            return _VR(passed=True, basis="driven by the guard")
    _ueg2 = _UEG()
    _chain2 = _Chain(_ueg2, _Orch())
    for _n in [k for ph in sorted(_chain2.enforcement.phases) for k in _chain2.enforcement.phases[ph]]:
        _chain2.enforcement.register_validator(_n, _Clear())
    _cleared = _aio.run(_chain2.validate_emission({"id": "e-clear", "text": "ordinary words here"}, {}))
    assert _cleared.passed is True, ("the chain cannot clear even when every constraint assesses and "
                                     "passes, so its cleared state is unreachable", _cleared.reason)
    assert [g["verdict"] for g in _cleared.gates] == ["cleared"] * len(_Chain._GATES), _cleared.gates
    ok = _cleared          # the converged-event assertions below describe a CLEARED run
    ueg = _ueg2
    # W526 (P3.15) — the five placeholder literals are gone. Each attestation is now a RECORD: a real
    # HMAC-SHA3-512 signature over the gate's canonical verdict, or a stated refusal naming the missing key.
    # This suite configures no attestation key, so the honest outcome here is an unsigned record WITH a
    # reason — never a placeholder, which is the distinction P3.15 exists to make.
    assert ok.attestations_signed is False, ok.attestations_basis
    assert "NOT SIGNED" in (ok.attestations_basis or ""), ok.attestations_basis
    assert all(isinstance(v, dict) for v in ok.attestations.values()), ok.attestations
    assert all(v.get("signed") is False and (v.get("basis") or "").strip()
               for v in ok.attestations.values()), ok.attestations
    assert not any("SIG_" in str(v) for v in ok.attestations.values()), ok.attestations
    kind, payload = ueg.events[-1]
    assert kind == "CONSTITUTIONAL_CLEARANCE_CONVERGED", kind
    #  COUNTED FROM THE CHAIN, not pinned at five (FU-365). W555 added a sixth gate — the
    #  enforcement pattern the chain had always held and never consulted — and a literal here would
    #  have failed for the growth the chain's own comment says this tuple exists to make visible.
    _declared = len(_Chain._GATES)
    assert payload["gates_declared"] == _declared, (payload["gates_declared"], _declared)
    assert payload["gates_passed"] == _declared, (
        "a gate did not clear on the all-clear double, so the chain cannot reach its cleared state",
        payload)
    assert payload["attestations_signed"] is False, payload
    assert "NOT SIGNED" in payload["attestations_basis"], payload

    # ── 2. EACH gate blocks on its own missing field — driven one at a time ─────────────────────
    #  READ FROM THE CHAIN so a new gate is covered by this loop the moment it is declared, rather
    #  than silently skipped by a list nobody updated.
    order = [k for k, _n, _s in _Chain._GATES]
    for i, gate in enumerate(order):
        _ch525 = _Chain(_UEG(), _Orch(drop=gate))
        if gate == "enforcement":
            #  W607 — THIS GATE'S "NO INPUT" WAS NEVER DRIVEN. Its input is the enforcement pattern, not an
            #  engine field, so dropping a field changed nothing and the leg passed only because the gate
            #  always blocked. Driven now: a pattern that assessed NOTHING is this gate's missing input.
            class _NothingAssessed:
                def validate(self, text):
                    return type("R", (), {"passed": None, "violation": None, "basis": "nothing assessed",
                                          "details": {"assessed": [], "unassessable": ["lob_fixpoint"]}})()
            _ch525.enforcement = _NothingAssessed()
        r = _aio.run(_ch525.validate_emission({"id": f"e-{gate}"}, {}))
        assert r.passed is False, (gate, "a gate with no input CLEARED the chain")
        verdicts = {g["gate"]: g["verdict"] for g in r.gates}
        assert verdicts[gate] == "blocked", (gate, verdicts)
        # the gates BEFORE it cleared and are still recorded — a block used to discard them
        for earlier in order[:i]:
            assert verdicts[earlier] == "cleared", (gate, earlier, verdicts)
        # the gates AFTER it are NOT_EVALUATED, not silently absent and not reported as approving
        for later in order[i + 1:]:
            assert verdicts[later] == "not_evaluated", (gate, later, verdicts)
        # the block names a reason, and never the bare word None
        assert r.reason and "None" not in r.reason, (gate, r.reason)
        assert (next(g for g in r.gates if g["gate"] == gate)["basis"] or "").strip(), (gate, r.gates)
        # an earlier gate's attestation survives the block
        assert sorted(r.attestations) == sorted(order[:i]), (gate, r.attestations)

    # ── 3. A MISSING RISK IS NOT A ZERO RISK — the sharpest of the three defaults ───────────────
    #  This gate read an absent score as 0.0, which is the strongest possible pass. Asserted separately
    #  from the loop above because the wording matters: the basis must say the risk was not measured.
    r = _aio.run(_Chain(_UEG(), _Orch(drop="tafakkur")).validate_emission({"id": "e-risk"}, {}))
    tf = next(g for g in r.gates if g["gate"] == "tafakkur")
    assert "unmeasured risk is not" in tf["basis"], tf["basis"]

    # ── 4. a non-numeric risk cannot be compared, and does not slip through ─────────────────────
    r = _aio.run(_Chain(_UEG(), _Orch(risk="low")).validate_emission({"id": "e-str"}, {}))
    assert r.passed is False, "a non-numeric risk score cleared the chain"
    assert "not a number" in r.reason, r.reason

    # ── 5. a high risk still blocks, so the threshold itself is live ────────────────────────────
    r = _aio.run(_Chain(_UEG(), _Orch(risk=0.9)).validate_emission({"id": "e-high"}, {}))
    assert r.passed is False and "threshold" in r.reason.lower(), r.reason

    # ── 6. AN ENGINE THAT RAISES BLOCKS WITH A REASON, rather than propagating a crash ──────────
    class _Boom(_Orch):
        async def consult(self, emission, engines):
            raise RuntimeError("the deliberation backend is down")

    r = _aio.run(_Chain(_UEG(), _Boom()).validate_emission({"id": "e-boom"}, {}))
    assert r.passed is False, "a raising engine did not block"
    assert "RuntimeError" in next(g for g in r.gates if g["gate"] == "mushawara")["basis"], r.gates


def test_w526_attestations_are_attestations(client, monkeypatch):
    """P3.15 — a tampered payload fails verification, and no placeholder signature is written.

    The chain wrote five literal strings into the UEG as signatures, each a DEFAULT on the engine's own
    field, so an engine that returned nothing produced an attestation indistinguishable from one that had
    signed. And five modules named post-quantum algorithms over operations that never happened, the sharpest
    being a retired module that keyed its "signature" with a constant in the source and padded the output to
    look the part.
    """
    import os
    from pathlib import Path as _P
    from agentic_core import attestation as _att

    root = _P(__file__).resolve().parents[1]

    # ── 1. WITH NO KEY: a refusal, never a placeholder ─────────────────────────────────────────
    monkeypatch.delenv(_att.KEY_ENV, raising=False)
    unsigned = _att.attest({"a": 1})
    assert unsigned["signed"] is False, unsigned
    assert "signature" not in unsigned, "an unsigned attestation carries a signature field"
    assert "NOT SIGNED" in unsigned["basis"], unsigned["basis"]
    # unverifiable is NOT invalid — reporting a missing key as tampering sends an operator after the wrong fault
    assert _att.verify({"a": 1}, unsigned)["verified"] is None, "an unsigned payload reported a verdict"

    # ── 2. WITH A KEY: a real MAC that recomputes, and a TAMPERED payload FAILS ─────────────────
    monkeypatch.setenv(_att.KEY_ENV, "w526-guard-key")
    payload = {"gate": "niyyah", "emission_id": "e1", "verdict": "cleared"}
    a = _att.attest(payload)
    assert a["signed"] is True and a["algorithm"] == "HMAC-SHA3-512", a
    assert len(a["signature"]) == 128, len(a["signature"])          # SHA3-512 hex
    assert _att.verify(payload, a)["verified"] is True, _att.verify(payload, a)
    for field, altered in (("verdict", "blocked"), ("gate", "tawazun"), ("emission_id", "e2")):
        bad = {**payload, field: altered}
        v = _att.verify(bad, a)
        assert v["verified"] is False, (field, "a tampered payload verified")
        assert v["payload_digest_matches"] is False, (field, v)
    # a signature altered by ONE character fails too
    flipped = {**a, "signature": ("0" if a["signature"][0] != "0" else "1") + a["signature"][1:]}
    assert _att.verify(payload, flipped)["verified"] is False, "a flipped signature verified"
    # a DIFFERENT key is unverifiable rather than invalid
    monkeypatch.setenv(_att.KEY_ENV, "a-different-key")
    assert _att.verify(payload, a)["verified"] is None, "another key's signature was called invalid"

    # ── 3. THE ROUTE RECOMPUTES — a stored verdict would satisfy neither half of the bar ───────
    monkeypatch.setenv(_att.KEY_ENV, "w526-guard-key")
    st = client.get("/api/v1/attestation/status").json()
    assert st["can_sign"] is True and st["post_quantum"] is False, st
    signed = client.post("/api/v1/attestation/sign", json={"payload": payload}).json()["attestation"]
    assert client.post("/api/v1/attestation/verify",
                       json={"payload": payload, "attestation": signed}).json()["verified"] is True
    tampered = client.post("/api/v1/attestation/verify",
                           json={"payload": {**payload, "verdict": "blocked"},
                                 "attestation": signed}).json()
    assert tampered["verified"] is False, tampered
    assert tampered["recomputed"] is True, tampered

    # ── 4. THE CHAIN WRITES NO PLACEHOLDER — asserted on the source, since the literals are the defect
    chain = (root / "agentic_core/avatars/core/clearance_chain.py").read_text(encoding="utf-8")
    for gate in ("MUSHAWARA", "NIYYAH", "TAWAZUN", "TAFAKKUR", "TAHQEEQ"):
        assert f"SIG_{gate}_v1" not in chain, f"the {gate} placeholder signature is back"
    #  COUNTED FROM THE CHAIN'S OWN TUPLE, not pinned at five (FU-365): W555 declared a sixth gate, and
    #  a literal here would have failed for exactly the growth _GATES exists to make visible.
    from agentic_core.avatars.core.clearance_chain import ConstitutionalClearanceChain as _CC526
    assert chain.count("self._attest_gate(emission, _rec)") == len(_CC526._GATES), (
        "a declared gate does not attest its own verdict",
        chain.count("self._attest_gate(emission, _rec)"), len(_CC526._GATES))

    # ── 5. THE GUARD TWO MODULES CLAIMED AND NOBODY BUILT ──────────────────────────────────────
    #  pqc_hardening.py has said since W506 that "a guard forbids" these words as descriptions of what it
    #  computes. No such guard existed. Here it is. Permitted files are those RECORDING a retired claim, and
    #  each occurrence in them must sit on a line that also carries a retirement marker — otherwise a fresh
    #  over-claim could be added to a permitted file and nothing would notice.
    #  W535 — these were matched CASE-SENSITIVELY, and that blind spot had a live consequence:
    #  products/capital_fund/reporting/regulatory_reporter.py built a manifest signature string from
    #  a lower-cased form of the first word, so a FABRICATED signature in a report typed
    #  FCA_QUARTERLY_MIFID_II sat in front of this screen and the screen could not see it. Matching is
    #  now case-insensitive, done where the comparison happens rather than by listing more spellings.
    WORDS = ("Dilithium", "Kyber")
    MARKERS = ("W506", "W526", "W521", "retired", "not post-quantum", "NOT post-quantum",
               "once named", "do not appear", "simulation", "does not exist", "no such operation",
               "which made it worse", "had claimed", "claimed a post-quantum")
    RECORDING = {
        "agentic_core/security/pqc_hardening.py",
        "agentic_core/governance/gaas/gaas.py",
        "agentic_core/reactor/religion/qep_flagship.py",
        "agentic_core/attestation/__init__.py",
        "agentic_core/api/attestation.py",
    }
    #  EXCLUSIONS, each justified against what it excludes rather than left as a quiet skip:
    #    _archive/   — retired trees; recovering their SHAPE is the plan's work, their claims are not live
    #    core/       — top-level, holds the real Landauer meter; its claims are FU-329's subject
    #    integration_tests/, scripts/ — this file names the words in order to forbid them
    #    products/   — NO LONGER EXCLUDED, as of W535. The exclusion was declared in W526 against FU-332
    #                  and named two live claims there; the Owner ruled FU-332 LIVE WORK on 2026-10-02 and
    #                  the measurement found FIVE files claiming cryptography the platform does not
    #                  implement, importing it from a package that is EMPTY. The three that asserted
    #                  something untrue are fixed — the multisig verifies three-state, the on-chain
    #                  withdrawal is money-gated and attests for real instead of returning a literal True,
    #                  and the regulatory manifest no longer carries a fabricated signature, a hard-coded
    #                  FINAL_CERTIFIED or a placeholder where a PDF belongs. Scanning products/ is what
    #                  PROVES that, so the scope gap is closed rather than re-declared.
    EXCLUDED = ("_archive/", "core/", "integration_tests/", "scripts/")
    offenders = []
    scanned = 0
    for py in sorted(root.rglob("*.py")):
        rel = py.relative_to(root).as_posix()
        if rel.startswith(EXCLUDED) or "site-packages" in rel:
            continue
        try:
            text = py.read_text(encoding="utf-8")
        except Exception:                                  # noqa: BLE001
            continue
        scanned += 1
        lines = text.splitlines()
        for lineno, line in enumerate(lines, 1):
            if not any(w.lower() in line.lower() for w in WORDS):
                continue
            #  a marker may sit a line or two away, because these explanations run to several lines. The
            #  WINDOW keeps the check real — a fresh claim added far from any retirement note still fails —
            #  while not demanding that every line of a paragraph repeat the round id.
            window = chr(10).join(lines[max(0, lineno - 4):lineno + 3])
            if rel in RECORDING and any(m in window for m in MARKERS):
                continue
            offenders.append(f"{rel}:{lineno}")
    #  and the scan must actually have read the tree: a path typo would otherwise scan nothing and pass
    assert scanned > 200, f"the scan only read {scanned} modules, so finding nothing proves nothing"
    assert not offenders, ("a post-quantum algorithm is named outside a line that records its retirement: "
                           f"{offenders}")

    # and the four live over-claims W521 measured are each gone, named individually so a partial fix shows
    surf = (root / "agentic_core/api/integration_surface.py").read_text(encoding="utf-8")
    assert "(configured)" not in surf, "the surface still reports a configured post-quantum posture"
    assert "_attestation_posture()" in surf, "the surface no longer reports its real attestation state"
    inter = (root / "agentic_core/network/interstellar.py").read_text(encoding="utf-8")
    assert "UNENCRYPTED-LABELLED-ENVELOPE(" in inter, "the envelope no longer says it is unencrypted"
    assert "_encrypt_pqc" not in inter, "a labelling function is still named as encryption"
    ceo = (root / "agentic_core/ai/ceo/autonomy_pipelines.py").read_text(encoding="utf-8")
    assert "Falcon mode" not in ceo, "the CEO surface still recommends a parameter set that does not exist"
    avatar = (root / "agentic_core/avatars/core/avatar_engine.py").read_text(encoding="utf-8")
    assert "NIST-standard PQC primitives" not in avatar, "the avatar class still claims NIST primitives"
    assert "NOT a keypair" in avatar, "the fixed digest is not named as one"
    # FU-246, the live half: a SHA3 digest was returned prefixed with the name of a recursive
    # zero-knowledge proof system. Nothing calls it, so the name is kept and the VALUE stops
    # asserting a proof.
    assert "content-digest:sha3-512:v1:" in avatar, "the digest is not named as a digest"
    assert "proof at all" in avatar, "nothing says a proof is not computed"
    from agentic_core.avatars.core.avatar_engine import AvatarIdentityManager as _AIM
    _not = _AIM.what_the_provenance_digest_is_not()
    assert _not["proof_system"] is None and _not["proof_system_basis"], _not

    os.environ.pop(_att.KEY_ENV, None)


def test_w527_every_stage_is_timed_on_its_own_clock_and_a_breach_is_a_fact():
    """P3.16 (part) — per-stage latencies, all six of them, and breaches recorded rather than logged.

    Three defects measured before building. The four timed stages all passed the cycle's ORIGINAL start
    time, so each figure after the first was the sum of itself and everything before it — a figure carrying
    the name of one stage while measuring several. A breach went to `logger.warning` and nowhere else. And
    only FOUR OF SIX stages were timed at all: LEARN and REFLECT had no check, so the loop reported on two
    thirds of itself.
    """
    import ast
    import asyncio as _aio
    from pathlib import Path as _P
    from agentic_core.avatars.core.recirculation_orchestrator import AvatarRecirculationOrchestrator as _O

    #  built without __init__: this exercises the stopwatch, not five collaborators
    orch = object.__new__(_O)

    async def _slow(seconds):
        await _aio.sleep(seconds)
        return "done"

    # ── 1. a stage's figure is ITS OWN, not cumulative ─────────────────────────────────────────
    async def _drive():
        first = await orch._measure_stage("SENSE", _slow(0.12))
        second = await orch._measure_stage("INTEND", _slow(0.0))
        return first, second

    (r1, rec1), (r2, rec2) = _aio.run(_drive())
    assert r1 == "done" and r2 == "done", (r1, r2)
    assert rec1["ms"] >= 100, rec1                      # the slow stage is seen as slow
    #  THE LEG THAT MATTERS: the fast stage that FOLLOWS it is not charged for it. Under the cumulative
    #  version this figure was ~120ms and INTEND breached its 200ms budget on SENSE's work.
    assert rec2["ms"] < 50, ("a later stage is being charged for an earlier one", rec2)
    assert rec2["breached"] is False, rec2
    assert "not cumulative" in rec1["measured"], rec1

    # ── 2. a breach is IN THE RECORD, with its budget beside it ────────────────────────────────
    _res, rec = _aio.run(orch._measure_stage("SENSE", _slow(0.15)))
    assert rec["breached"] is True, rec
    assert rec["budget_ms"] == 100 and rec["ms"] > 100, rec
    #  and the budget is declared an UNTUNED DEFAULT in the same record as the verdict
    assert rec["budget_is_a_default"] is True, rec
    assert "untuned DEFAULT" in _O._BUDGETS_ARE_DEFAULTS, _O._BUDGETS_ARE_DEFAULTS

    # ── 3. a stage that RAISES is recorded and re-raised, not swallowed into a timing ───────────
    async def _boom():
        raise ValueError("stage exploded")

    try:
        _aio.run(orch._measure_stage("ACT", _boom()))
        raise AssertionError("a failing stage did not propagate")
    except RuntimeError as exc:
        assert "ACT" in str(exc) and "ValueError" in str(exc), str(exc)

    # ── 4. ALL SIX stages are declared, and ALL SIX are timed — asserted on the AST, because this is a
    #      reachability question and a source count would pass on a call in a branch that never runs ──
    assert sorted(_O._STAGE_BUDGETS_MS) == sorted(
        ["ACT", "ANALYZE", "INTEND", "LEARN", "REFLECT", "SENSE"]), _O._STAGE_BUDGETS_MS
    src = (_P(__file__).resolve().parents[1]
           / "agentic_core/avatars/core/recirculation_orchestrator.py").read_text(encoding="utf-8")
    tree = ast.parse(src)
    #  the method is `execute_cycle`. Asserted non-None BEFORE walking it: with a wrong name and an
    #  `if cycle:` instead, this whole leg would skip and the test would pass having checked nothing.
    cycle = next((n for n in ast.walk(tree)
                  if isinstance(n, ast.AsyncFunctionDef) and n.name == "execute_cycle"), None)
    assert cycle is not None, "execute_cycle not found — the method was renamed"
    timed = []
    for node in ast.walk(cycle):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) \
                and node.func.attr == "_measure_stage" and node.args:
            first = node.args[0]
            if isinstance(first, ast.Constant):
                timed.append(first.value)
    assert sorted(timed) == sorted(
        ["ACT", "ANALYZE", "INTEND", "LEARN", "REFLECT", "SENSE"]), ("not every stage is timed", timed)
    #  the misnamed warner is gone: it was called _assert_latency and it asserted nothing, it warned
    assert "_assert_latency" not in src, "the method that asserted nothing is back"
    #  and no call passes the cycle's start time into a per-stage measurement any more
    assert "_measure_stage(start_time" not in src, "a cumulative start time is back"

    # ── 5. the p95 claim is named an aspiration, because nothing retains a series to compute one ─
    assert "Target p95 latency: <500ms (SENSE -> ACT)." not in src, "the p95 claim is back as a statement"
    assert "AN ASPIRATION, NOT A RESULT" in src, "the aspiration is not named as one"
    assert "needs many runs ranked against one another" in src, "nothing says why a p95 cannot be computed"


def test_w528_the_three_auxiliary_engines_compute_or_refuse():
    """P3.16 (part) — Tahqeeq, Mushawara and Mudrik, which were declared in EngineType with no module.

    Two of the three sit behind clearance-chain gates W525 taught to refuse: Mushawara is gate 1, which
    previously RAISED on a missing field, and Tahqeeq is gate 5, which approved on one. The gates were fixed
    before the engines existed; this is the other half.
    """
    import asyncio as _aio
    from agentic_core.consultation.interface import ConsultationRequest as R
    from agentic_core.cognitive.auxiliary.mudrik_engine import MudrikEngine
    from agentic_core.cognitive.auxiliary.mushawara_engine import MushawaraEngine
    from agentic_core.cognitive.auxiliary.tahqeeq_engine import TahqeeqEngine

    # ── 1. each refuses on absent input, with a basis and a refusal provenance ──────────────────
    for name, cls in (("tahqeeq", TahqeeqEngine), ("mushawara", MushawaraEngine), ("mudrik", MudrikEngine)):
        r = _aio.run(cls().consult(R(engine=name, query="q")))
        assert r.metadata.get("assessable") is False, (name, r.metadata)
        assert r.answer.startswith("Not assessable:"), (name, r.answer)
        assert (r.metadata.get("basis") or "").strip(), (name, "refused with no reason")
        assert r.confidence is None and r.served_by == "native-refused", (name, r.served_by)

    # ── 2. TAHQEEQ verifies the constraints it is given, per constraint ─────────────────────────
    ok = _aio.run(TahqeeqEngine().consult(R(engine="tahqeeq", query="q", context={
        "output": "a real answer",
        "constraints": [{"kind": "non_empty"}, {"kind": "forbidden_text", "text": "TODO"},
                        {"kind": "min_chars", "limit": 5}]})))
    assert ok.metadata["verified"] is True and ok.metadata["constraints_checked"] == 3, ok.metadata
    bad = _aio.run(TahqeeqEngine().consult(R(engine="tahqeeq", query="q", context={
        "output": "TODO", "constraints": [{"kind": "forbidden_text", "text": "TODO"}]})))
    assert bad.metadata["verified"] is False, bad.metadata
    assert bad.metadata["constraints_failed"] == 1, bad.metadata
    #  AN UNKNOWN KIND IS A REFUSAL, NOT A SKIP: skipping reports a pass over a check that never ran
    unk = _aio.run(TahqeeqEngine().consult(R(engine="tahqeeq", query="q", context={
        "output": "x", "constraints": [{"kind": "no_such_check"}]})))
    assert unk.metadata["assessable"] is False, unk.metadata
    assert "not implemented" in unk.metadata["basis"], unk.metadata["basis"]
    #  and it does not claim more than it checked
    assert "not 'this output is correct'" in ok.metadata["what_this_does_not_establish"], ok.metadata

    # ── 3. MUSHAWARA counts positions, and ABSTENTIONS ARE NOT AGREEMENT ───────────────────────
    appr = _aio.run(MushawaraEngine().consult(R(engine="mushawara", query="q", context={"opinions": [
        {"engine": "inkashaf", "verdict": "approve"}, {"engine": "aqal", "verdict": "approve"},
        {"engine": "samajh", "verdict": "approve"}]})))
    assert appr.metadata["status"] == "APPROVED", appr.metadata
    assert appr.metadata["minimum_engines"] == 3, appr.metadata
    #  THE LEG THAT MATTERS: three engines that all abstained did not approve anything
    absts = _aio.run(MushawaraEngine().consult(R(engine="mushawara", query="q", context={"opinions": [
        {"engine": "a", "verdict": "abstain"}, {"engine": "b", "verdict": "abstain"},
        {"engine": "c", "verdict": "abstain"}]})))
    assert absts.metadata["status"] == "BLOCKED", ("three abstentions cleared the gate", absts.metadata)
    assert absts.metadata["abstentions"] == ["a", "b", "c"], absts.metadata
    #  one objection blocks, however many approve
    obj = _aio.run(MushawaraEngine().consult(R(engine="mushawara", query="q", context={"opinions": [
        {"engine": "a", "verdict": "approve"}, {"engine": "b", "verdict": "approve"},
        {"engine": "c", "verdict": "object"}]})))
    assert obj.metadata["status"] == "BLOCKED" and obj.metadata["objections"] == ["c"], obj.metadata
    #  too few engines blocks, even unanimously
    few = _aio.run(MushawaraEngine().consult(R(engine="mushawara", query="q", context={"opinions": [
        {"engine": "a", "verdict": "approve"}, {"engine": "b", "verdict": "approve"}]})))
    assert few.metadata["status"] == "BLOCKED", few.metadata
    #  an opinion naming no engine cannot be counted
    anon = _aio.run(MushawaraEngine().consult(R(engine="mushawara", query="q", context={
        "opinions": [{"verdict": "approve"}]})))
    assert anon.metadata["assessable"] is False and "names no engine" in anon.metadata["basis"], anon.metadata

    # ── 4. MUDRIK carries only a CLEARED emission, and never submits ───────────────────────────
    cleared = {"passed": True,
               "gates": [{"gate": "mushawara", "verdict": "cleared"}, {"gate": "tahqeeq", "verdict": "cleared"}],
               "attestations": {"mushawara": {"signed": False}}, "attestations_signed": False}
    car = _aio.run(MudrikEngine().consult(R(engine="mudrik", query="q", context={
        "emission": {"id": "e1", "summary": "a change"}, "clearance": cleared})))
    assert car.metadata["carried"] is True, car.metadata
    assert car.metadata["proposal"]["target_surface"] == "change_control_agency", car.metadata
    assert car.metadata["proposal"]["cleared_by_gates"] == ["mushawara", "tahqeeq"], car.metadata
    #  IT SHAPES, IT DOES NOT SUBMIT — said on the result, not only in a docstring
    assert car.metadata["submitted"] is False, car.metadata
    assert "belongs to the caller" in car.metadata["submission_basis"], car.metadata
    #  the unsigned attestations are carried THROUGH rather than hidden, so governance sees what it gets
    assert car.metadata["proposal"]["attestations_signed"] is False, car.metadata
    #  AN UNCLEARED EMISSION IS NOT CARRIED
    blocked = _aio.run(MudrikEngine().consult(R(engine="mudrik", query="q", context={
        "emission": {"id": "e2"},
        "clearance": {"passed": False, "reason": "Gate 3 block",
                      "gates": [{"gate": "tawazun", "verdict": "blocked"}]}})))
    assert blocked.metadata["carried"] is False, blocked.metadata
    assert "NOT cleared" in blocked.metadata["basis"], blocked.metadata
    #  AND NEITHER IS ONE WHOSE CLEARANCE HAS NO GATE RECORDS: passed:true with nothing behind it did not
    #  come from the chain P3.14 built
    hollow = _aio.run(MudrikEngine().consult(R(engine="mudrik", query="q", context={
        "emission": {"id": "e3"}, "clearance": {"passed": True}})))
    assert hollow.metadata["assessable"] is False, hollow.metadata
    assert "nothing behind it" in hollow.metadata["basis"], hollow.metadata["basis"]

    # ── 5. all three are REGISTERED in the auxiliary tier and reachable through the registry ───
    from agentic_core.cognitive.registry import (CognitiveEngineRegistry as Reg, ENGINE_TIERS,
                                                 EngineTier, EngineType)
    for et in (EngineType.TAHQEEQ, EngineType.MUSHAWARA, EngineType.MUDRIK):
        assert ENGINE_TIERS[et] == EngineTier.AUXILIARY, et
        assert hasattr(Reg.get(et), "consult"), et
    #  Mushawara is NOT Mushahida, and they are in different tiers
    assert ENGINE_TIERS[EngineType.MUSHAHIDA] == EngineTier.MJM


def test_w530_the_mutation_gate_refuses_instead_of_rubber_stamping(tmp_path):
    """FU-333 — the avatar orchestrator handed its epigenetic engine gates that could not say no.

    Measured before building: `regulator=type('Mock', (), {'validate_mutation': mock_validate})` where
    mock_validate returned `{'approved': True, 'confidence': 0.95}`, and
    `lob_fixpoint=type('Mock', (), {'verify': lambda *a: True})` — both in the live constructor, behind no
    flag and no except. The ENGINE was never the defect: its `approved` default is already False, so a
    regulator returning nothing blocks. Its fail-closed default was being bypassed by injecting something
    that always said yes.
    """
    import ast
    import asyncio as _aio
    from agentic_core.avatars.core.recirculation_orchestrator import (_RefusingFixpoint, _RefusingRegulator)
    from agentic_core.avatars.memory.epigenetic_engine import EpigeneticMemoryEngine

    class _UEG:
        def __init__(self):
            self.events = []

        async def log_event(self, kind, payload):
            self.events.append((kind, payload))

    # ── 1. the injected regulator REFUSES, and the refusal is recorded ─────────────────────────
    ueg = _UEG()
    eng = EpigeneticMemoryEngine(ueg, _RefusingRegulator(), _RefusingFixpoint())
    marker = _aio.run(eng.propose_adaptation("u1", "cycle", "strategy_tuning", {"w": 1}, {"w": 2}))
    assert marker is None, "an unconfigured mutation gate approved an adaptation"
    assert [k for k, _ in ueg.events] == ["EPIGENETIC_REJECTION"], ueg.events
    assert ueg.events[0][1]["reason"] == "REGULATOR_VETO", ueg.events[0][1]
    #  it reports NO confidence: a regulator that approved nothing has none, and emitting one is how a
    #  fabricated 0.95 reached a stored marker
    verdict = _aio.run(_RefusingRegulator().validate_mutation("t", {}, {}))
    assert verdict["approved"] is False, verdict
    assert "confidence" not in verdict, "a refusal is reporting a confidence"
    assert "REFUSAL, not an error" in verdict["basis"], verdict["basis"]
    assert _RefusingFixpoint().verify("t", {}, {}) is False, "the stability constraint passes vacuously"

    # ── 2. THE NON-VACUOUS LEG: a gate that always blocks is as useless as one that always approves ──
    class _Approve:
        async def validate_mutation(self, t, b, a):
            return {"approved": True, "proof": "sig-xyz"}

    class _Stable:
        def verify(self, t, b, a):
            return True

    ueg2 = _UEG()
    eng2 = EpigeneticMemoryEngine(ueg2, _Approve(), _Stable())
    m2 = _aio.run(eng2.propose_adaptation("u1", "cycle", "strategy_tuning", {"w": 1}, {"w": 2}))
    assert m2 is not None, "a genuinely approved adaptation was refused — the gate is shut, not refusing"
    assert m2.constitutional_validation == "sig-xyz", m2.constitutional_validation
    assert m2.lob_fixpoint_stable is True, m2.lob_fixpoint_stable

    # ── 3. NO PROOF is said, never defaulted to a literal that looks like a signature ───────────
    class _ApproveNoProof:
        async def validate_mutation(self, t, b, a):
            return {"approved": True}

    m3 = _aio.run(EpigeneticMemoryEngine(_UEG(), _ApproveNoProof(), _Stable())
                  .propose_adaptation("u1", "cycle", "strategy_tuning", {"w": 1}, {"w": 2}))
    assert m3.constitutional_validation.startswith("NOT ATTESTED:"), m3.constitutional_validation
    assert "MOCK" not in m3.constitutional_validation, m3.constitutional_validation

    # ── 4. no Mock is constructed in the orchestrator's __init__ — on the AST, because this is about a
    #      BINDING and a source search would pass on one in a comment ────────────────────────────
    from pathlib import Path as _P
    root = _P(__file__).resolve().parents[1]
    src = (root / "agentic_core/avatars/core/recirculation_orchestrator.py").read_text(encoding="utf-8")
    tree = ast.parse(src)
    init = next((n for n in ast.walk(tree)
                 if isinstance(n, ast.FunctionDef) and n.name == "__init__"), None)
    assert init is not None, "__init__ not found — the class was renamed"
    type_calls = [n for n in ast.walk(init)
                  if isinstance(n, ast.Call) and getattr(n.func, "id", "") == "type" and len(n.args) == 3]
    assert not type_calls, f"a type(...) stand-in is being constructed in __init__: {len(type_calls)}"
    assert "mock_validate" not in src, "the always-approving validator is back"
    #  and the marker's stability flag is no longer a constant
    eng_src = (root / "agentic_core/avatars/memory/epigenetic_engine.py").read_text(encoding="utf-8")
    assert "lob_fixpoint_stable=True," not in eng_src, "the stability flag is a literal again"

    # ── 5. A MISSING OUTCOME IS NOT A WIN. update_skill is not called at all without an observation ──
    from agentic_core.avatars.core.recirculation_orchestrator import AvatarRecirculationOrchestrator as _O
    orch = object.__new__(_O)

    class _Profiler:
        def __init__(self):
            self.calls = []

        async def update_skill(self, user_id, domain, success):
            self.calls.append((user_id, domain, success))

    class _TFEL:
        #  W546 — `bits_basis` is part of the real signature now: the six stages stopped passing invented
        #  bit counts and pass the account of where each measured figure came from. A test double is a
        #  CONSUMER OF A SIGNATURE, and this one still had the old one, so the producer change raised
        #  TypeError here while every direct caller was correct. Second-writer class, in a fake.
        def meter_operation(self, name, bits, bits_basis: str = ""):
            return {}

    orch.skill_profiler = _Profiler()
    orch.tfel = _TFEL()
    orch.epigenetic_memory = None          # unreached: the stage proposes nothing

    ctx_missing = {"user_id": "u1", "domain": "d", "user_context": {}}
    out = _aio.run(orch._stage_learn(ctx_missing))
    assert orch.skill_profiler.calls == [], "an unmeasured cycle updated a stored skill profile"
    assert "NOT updated" in out["skill"], out["skill"]
    assert "needs an observation" in out["skill"], out["skill"]

    #  a RECORDED outcome does update it — so leg 5 is not merely asserting that nothing happens
    orch.skill_profiler = _Profiler()
    out_ok = _aio.run(orch._stage_learn({"user_id": "u1", "domain": "d",
                                         "user_context": {"success": False}}))
    assert orch.skill_profiler.calls == [("u1", "d", False)], orch.skill_profiler.calls
    assert "recorded outcome" in out_ok["skill"], out_ok["skill"]

    # ── 6. NO PLACEHOLDER ADAPTATION, and the reason names the constant hash ───────────────────
    assert out["adaptation_proposed"] is False, out
    assert "identical for every user and every cycle" in out["adaptation_basis"], out["adaptation_basis"]
    assert "REFINED_BY_EPIGENETIC_ENGINE" not in src, "the placeholder new-state literal is back"


def test_w531_the_cascade_count_is_computed_and_the_nine_engine_reader_calls_consult(client, monkeypatch):
    """FU-322 and FU-320 — a literal count, and a consumer calling a method nothing implements.

    `engines_run` was the hard literal 6 with a basis sentence beside it, and MEASURED: execute_cascade's
    report never said which engines ran, so there was nothing to compute it from. And
    nine_engine_registry.get_engine_response called `engine.process(...)`, which NO engine implements — once
    W520 populated the registry it stopped failing with "Engine not found" and began failing with
    AttributeError instead.
    """
    import ast
    import asyncio as _aio

    # ── 1. the cascade records what it ran, and the route COUNTS it ─────────────────────────────
    body = client.post("/api/v1/cognitive/cascade", json={"problem": "w531", "include_mjm": False}).json()
    assert body["engines_run_is_counted"] is True, body
    assert body["engines_ran"] == ["inkashaf", "samajh", "soch", "aqal", "hoshiyari", "iman"], body["engines_ran"]
    assert body["engines_run"] == 6, body["engines_run"]
    assert "counted from the engines the cascade recorded" in body["engines_run_basis"], body

    # the cascade stopped claiming integration it never measured
    assert body["cascade"]["status"] == "completed", body["cascade"]["status"]
    assert "nothing here measures integration" in body["cascade"]["status_basis"], body["cascade"]

    # ── 2. THE LEG THAT TELLS A COUNT FROM A LITERAL: make the cascade report FEWER engines and the
    #      route's number must MOVE. A count that happens to equal 6 looks exactly like the 6 it replaced.
    import agentic_core.api.cognitive as _c

    class _Short:
        async def execute_cascade(self, problem):
            return {"engines_ran": ["inkashaf", "samajh"], "engines_ran_count": 2, "status": "completed",
                    "status_basis": "nothing here measures integration", "patterns": {}, "understanding": {},
                    "plan": {}, "alignment": {}, "alerts": {}}

    monkeypatch.setattr(_c, "_cascade", _Short())
    short = client.post("/api/v1/cognitive/cascade", json={"problem": "w531b", "include_mjm": False}).json()
    assert short["engines_run"] == 2, ("the count did not move — it is still a literal", short["engines_run"])
    assert short["engines_ran"] == ["inkashaf", "samajh"], short["engines_ran"]

    # and a cascade reporting NO list gives 0 that says NOT RECORDED rather than implying none ran
    class _Silent:
        async def execute_cascade(self, problem):
            return {"status": "completed", "patterns": {}, "understanding": {}, "plan": {}, "alignment": {}}

    monkeypatch.setattr(_c, "_cascade", _Silent())
    silent = client.post("/api/v1/cognitive/cascade", json={"problem": "w531c", "include_mjm": False}).json()
    assert silent["engines_run"] == 0, silent["engines_run"]
    assert "NOT RECORDED" in silent["engines_run_basis"], silent["engines_run_basis"]

    # ── 3. FU-320 — the reader is CALLED, not read. Its defect was an AttributeError at call time, so a
    #      source search for `consult` would pass on a call that never executes.
    from agentic_core.avatars.cognition.nine_engine_registry import EngineRegistry9
    reg9 = EngineRegistry9(None, None)
    out = _aio.run(reg9.get_engine_response("soch", "a query", {}))
    assert out["engine"] == "soch", out
    assert out["served_by"], "the reader drops the provenance the contract carries"
    assert out["confidence"] is None, out               # the six do not compute, and say so
    assert (out["confidence_basis"] or "").strip(), out
    assert out["constitutional_validation"]["passed"] is None, out
    #  and it reaches a META engine too, which is the half that only worked after P3.13
    meta = _aio.run(reg9.get_engine_response("niyyah", "q", {}))
    assert meta["engine"] == "niyyah", meta
    assert meta["result"]["assessable"] is False, meta["result"]      # refuses with no signatures supplied

    # ── 4. no caller invokes a method the engines do not implement — on the AST ─────────────────
    from pathlib import Path as _P
    src = (_P(__file__).resolve().parents[1]
           / "agentic_core/avatars/cognition/nine_engine_registry.py").read_text(encoding="utf-8")
    tree = ast.parse(src)
    bad = [n for n in ast.walk(tree)
           if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr == "process"]
    assert not bad, f"a caller is invoking .process(), which no engine implements: {len(bad)}"


def test_w532_the_beat_drives_the_loop_and_records_a_failure_as_a_failure():
    """P3.16 — the recirculation loop is driven from the heartbeat, paced and off by default.

    Wiring it RAN THE LOOP FOR THE FIRST TIME: execute_cycle has one caller and nothing calls that caller, so
    the loop was reached by nothing and every defect in it was invisible to this suite. It currently fails at
    stage INTEND. This guard therefore asserts what W532 BUILT — the drive, its pacing, its default-off, and
    that a failure is recorded with its exception — not that the loop works, which it does not.
    """
    import asyncio as _aio
    from agentic_core.organism.heartbeat import OrganismHeartbeat

    # ── 1. OFF BY DEFAULT, so no existing deployment changes behaviour ─────────────────────────
    h = OrganismHeartbeat()
    assert h.auto_metabolic is False, "the expensive loop is on by default"
    assert h._metabolic_every == 10, h._metabolic_every
    assert h.last_metabolic is None, h.last_metabolic

    first = _aio.run(h.beat())
    acts = first.get("actions") or []
    assert not [a for a in acts if "metabolic" in a], ("the loop ran while switched off", acts)
    assert h.last_metabolic is None, "a cycle was recorded while switched off"

    # ── 2. PACED: on, but not yet due, still does not run ──────────────────────────────────────
    h2 = OrganismHeartbeat()
    h2.auto_metabolic = True
    h2._metabolic_every = 5
    h2._beats_since_metabolic = 0
    _aio.run(h2.beat())
    assert h2.last_metabolic is None, "the pacing counter is not gating the cycle"

    # ── 3. DUE: it runs, and whatever happens is RECORDED on the beat ──────────────────────────
    h3 = OrganismHeartbeat()
    h3.auto_metabolic = True
    h3._metabolic_every = 1
    third = _aio.run(h3.beat())
    acts3 = third.get("actions") or []
    assert [a for a in acts3 if "metabolic" in a], ("the cycle did not run when due", acts3)
    rec = h3.last_metabolic or {}
    assert rec, "the beat ran a cycle and recorded nothing"
    assert rec.get("at"), rec

    # ── 4. THE LEG THAT MATTERS: a failure is a FAILURE, never a clean beat ────────────────────
    #  The loop fails today. What this round owns is that the beat says so — with the exception — instead
    #  of appending a clean action and moving on. A silent failure here would be indistinguishable from a
    #  cycle that measured nothing, which is the defect this whole programme removes.
    if rec.get("failed"):
        assert "metabolic_cycle_failed" in acts3, ("a failure was reported as a clean cycle", acts3)
        assert ":" in rec["failed"], ("the failure does not name its exception type", rec["failed"])
        assert "not a clean beat" in rec["basis"], rec["basis"]
        assert rec["stages_measured"] == 0, rec
    else:
        #  when the loop becomes runnable this branch takes over, and an empty stage list is NOT a pass.
        #  W533 — IT TOOK OVER, which is what it was written for, and it was wrong in one way the round
        #  before could not have known: it asserted an EXACT action name, and making the loop runnable
        #  revealed a THIRD beat state. The loop can now run, measure all six stages and deliberately
        #  deliver nothing, because clearance gate 1 withholds the emission. A guard that insisted on the
        #  delivered name would have forced that real state to be renamed away to keep a test green.
        metab = [a for a in acts3 if a.startswith("metabolic_cycle")]
        assert len(metab) == 1, ("a beat must record exactly one metabolic outcome", acts3)
        assert metab[0] in ("metabolic_cycle", "metabolic_cycle_withheld"), ("unknown outcome", metab)
        assert rec["stages_measured"] > 0, ("the cycle reported no stages, which is unmeasured and not "
                                            "clean", rec)
        assert isinstance(rec.get("breached_stages"), list), rec
        assert "measured individually" in rec["basis"], rec["basis"]
        #  and the two non-failure states must stay distinguishable: a cycle that measured everything and
        #  emitted nothing is not a delivery, and must never be recorded as one.
        if metab[0].endswith("withheld"):
            assert rec["cycle_status"] == "WITHHELD", rec
            assert rec["emitted"] is False, rec
            assert (rec.get("withheld_reason") or "").strip(), ("nothing was emitted and the beat does "
                                                                "not say why", rec)
        else:
            assert rec.get("emitted") is True, ("a delivered cycle does not say it emitted", rec)

    # ── 5. the subject is the ORGANISM and says why, rather than naming an invented user ───────
    from pathlib import Path as _P
    src = (_P(__file__).resolve().parents[1] / "agentic_core/organism/heartbeat.py").read_text(encoding="utf-8")
    assert "subject_basis" in src, "the beat does not say whose cycle it is running"
    #  the phrase is asserted as it appears in SOURCE: the runtime string is assembled by implicit
    #  concatenation across three lines, so a contiguous-phrase check on the full sentence fails
    #  even though the value is right. Source checks match source, not the assembled value.
    assert "no avatar population is recorded for the" in src, "the subject rationale is absent"
    assert "not a user" in src, "the beat does not say the subject is the organism"
    #  and the section is placed with the expensive work, not the cheap work
    assert "paced and opt-in" in src.lower() or "Paced and opt-in" in src, "the pacing rationale is absent"


def test_w533_the_loop_runs_and_a_withheld_emission_is_not_a_success():
    """P3.16 — the six-stage recirculation loop RUNS from the heartbeat, and withholds honestly.

    W532 wired the beat to the loop and the loop could not run. Four defects stood in the way, each hidden
    from a source search: a stub detector that substring-matched the word every constitutional verdict
    carries; an interceptor handing data to a method that enforces a property of code; an aggregator that
    multiplied by a three-state confidence; and a deliberation whose status was a literal. With those gone the
    loop reaches its last stage and clearance gate 1 WITHHOLDS the emission, because the engines supply no
    verdict. That is the governance layer working, so it must read as neither a crash nor a clean delivery.
    """
    import ast as _ast
    import asyncio as _aio
    from pathlib import Path as _P

    # ── 1. THE LOOP RUNS FROM THE BEAT, and all six stages are measured ────────────────────────
    from agentic_core.organism.heartbeat import OrganismHeartbeat
    h = OrganismHeartbeat()
    h.auto_metabolic = True
    h._metabolic_every = 1
    beat = _aio.run(h.beat())
    rec = h.last_metabolic or {}
    assert rec, "the beat ran a cycle and recorded nothing"
    assert not rec.get("failed"), ("the cycle failed: " + str(rec.get("failed")))
    assert rec["stages_measured"] == 6, ("the loop did not run all six stages", rec["stages_measured"],
                                         [g.get("stage") for g in (rec.get("stages") or [])])
    assert [g["stage"] for g in rec["stages"]] == ["SENSE", "INTEND", "ANALYZE", "ACT", "LEARN", "REFLECT"], \
        [g["stage"] for g in rec["stages"]]
    assert all(isinstance(g["ms"], float) for g in rec["stages"]), rec["stages"]

    # ── 2. AND IT EMITTED NOTHING, which must not read as a clean cycle ────────────────────────
    #  Six measured stages and an empty mouth is this platform's normal state today. Before W533 that had
    #  the same record as a delivered cycle, and before W532's chain it raised instead.
    assert rec["cycle_status"] == "WITHHELD", rec["cycle_status"]
    assert rec["emitted"] is False, rec["emitted"]
    assert (rec.get("withheld_reason") or "").strip(), "the beat does not say WHY nothing was emitted"
    #  W604 (P3.28) — gate 1 now decides by coverage and CLEARS a screened emission, so the first block
    #  moved to gate 2, whose intent ratification has no signatures to count (an Owner ruling is open on
    #  where they would honestly come from). Still withheld, and the reason now names the next gate.
    #  W606 (FU-471, option 3) — gate 2 now COUNTS recorded approvals, and none is recorded for the beat's
    #  subject ("platform"), so it counts zero and the ratification fails; before the store existed it was
    #  not assessable. Either way the beat is withheld at gate 2, which is the fact this leg protects.
    assert "Gate 2" in rec["withheld_reason"] and (
        "not assessable" in rec["withheld_reason"] or "failed ratification" in rec["withheld_reason"]), (
        rec["withheld_reason"])
    acts = [a for a in (beat.get("actions") or []) if "metabolic" in a]
    assert acts == ["metabolic_cycle_withheld"], ("a withheld cycle is indistinguishable from a delivered "
                                                  "one in the action list", acts)

    # ── 3. THE AGGREGATE IS NOT MEAN CONFIDENCE WEARING THE NAME AGREEMENT ─────────────────────
    from agentic_core.consultation.mushawara.perspective_aggregator import PerspectiveAggregator
    agg = PerspectiveAggregator(None)

    #  (a) a three-state confidence no longer raises — this is what stopped stage ANALYZE
    none_conf = [{"engine": "aqal", "confidence": None, "vector": None, "trace": {"passed": None}}] * 3
    out = _aio.run(agg.synthesize(none_conf))
    assert out["consensus_vector"] is None, "an embedding was invented for perspectives that supplied none"
    assert "NOT BUNDLED" in out["consensus_vector_basis"], out["consensus_vector_basis"]
    #  (b) nothing assessed it, so agreement is UNDEFINED — never 0.0 and never 1.0
    assert out["agreement_score"] is None, ("an unassessed deliberation reported a number", out)
    assert "NOT COMPUTED" in out["agreement_basis"], out["agreement_basis"]
    assert out["confidence_mean"] is None, out
    #  (c) real disagreement is expressible, which the constant-vector bundle could not do
    mixed = [{"confidence": 0.9, "vector": None, "trace": {"passed": True}},
             {"confidence": 0.1, "vector": None, "trace": {"passed": True}},
             {"confidence": None, "vector": None, "trace": {"passed": False}}]
    out2 = _aio.run(agg.synthesize(mixed))
    assert abs(out2["agreement_score"] - 2.0 / 3.0) < 1e-9, out2["agreement_score"]
    assert out2["verdicts_supplied"] == 3, out2
    #  and the mean confidence keeps its OWN name, computed over the engines that reported one
    assert abs(out2["confidence_mean"] - 0.5) < 1e-9, out2["confidence_mean"]
    assert "2 of 3" in out2["confidence_basis"], out2["confidence_basis"]
    #  (d) the hyperdimensional path still works when vectors are REAL, and says it was weighted
    real = [{"confidence": 1.0, "vector": [1.0, -1.0], "trace": {"passed": True}},
            {"confidence": 1.0, "vector": [1.0, 1.0], "trace": {"passed": True}}]
    out3 = _aio.run(agg.synthesize(real))
    assert out3["consensus_vector"] == [1.0, 0.0], out3["consensus_vector"]
    assert "weighted by each engine" in out3["consensus_vector_basis"], out3["consensus_vector_basis"]

    # ── 4. THE STATUS IS DERIVED, and clearance gate 1 reads it ────────────────────────────────
    from agentic_core.consultation.mushawara.mushawara_bridge_2 import MushawaraBridge2

    class _FixedAgg:
        async def synthesize(self, ps):
            return {"agreement_score": None}

    def _bridge(verdicts):
        b = MushawaraBridge2(None, None)
        b.agg = _FixedAgg()

        async def _p(q, et, _v=iter(verdicts)):
            return {"engine": "x", "confidence": None, "trace": {"passed": next(_v)}}
        b._get_p = _p
        return b

    q = type("Q", (), {"query": "q", "context": {}})()
    three = [None, None, None]
    assert _aio.run(_bridge(three).deliberate(q, [0, 1, 2]))["status"] == "NOT ASSESSED", \
        "a deliberation nothing assessed reported an approval, and gate 1 clears on that"
    assert _aio.run(_bridge([True, False, True]).deliberate(q, [0, 1, 2]))["status"] == "BLOCKED"
    allp = _aio.run(_bridge([True, True, True]).deliberate(q, [0, 1, 2]))
    assert allp["status"] == "APPROVED", allp["status"]
    assert (allp.get("reason") or "").strip(), "gate 1 reads `reason` and it is empty"

    # ── 5. THE READER STOPS CLAIMING A DEFINITIVE STRATEGY off a number nothing assessed ───────
    from agentic_core.avatars.cognition.mushawara_bridge import AvatarCognitiveOrchestrator
    orch = AvatarCognitiveOrchestrator(None, None)
    unassessed = orch._synthesize_text({"context": {"input": "a plan"}}, None, {"status": "NOT ASSESSED"})
    assert "definitive" not in unassessed.lower(), unassessed
    assert "not been able to assess" in unassessed, unassessed
    blocked = orch._synthesize_text({"context": {"input": "a plan"}}, 1.0, {"status": "BLOCKED"})
    assert "cannot proceed" in blocked, blocked

    # ── 6. A PLACEHOLDER GATE WITH TWO UNMATCHABLE NEEDLES — both halves ───────────────────────
    #  The test was `p in content.upper()` with lowercase needles, so against an uppercased haystack they
    #  could never fire whatever the emission said. Proven by driving the needle that could not match:
    cannot_before = _aio.run(orch.verify_output({"text": "the body is raise NotImplementedError here"}))
    assert cannot_before["verified"] is False, ("a needle that could never match still cannot", cannot_before)
    assert _aio.run(orch.verify_output({"text": "TODO: finish"}))["verified"] is False
    assert _aio.run(orch.verify_output({"text": "a stub remains"}))["verified"] is False
    #  and the other half: an ordinary English word inside prose written for a user is NOT a placeholder
    ok = _aio.run(orch.verify_output({"text": "You will pass the assessment, and your progress compasses it."}))
    assert ok["verified"] is True, ("an ordinary word in prose is refused as a placeholder", ok)
    #  W538 renamed this key: a digest of one object is not a Merkle proof, so it is now
    #  emission_digest_sha3_512 with a basis saying it proves no inclusion. The pre-flight's rename screen
    #  named THIS FILE as a surviving reader and I attributed the hit to the new guard asserting the key is
    #  ABSENT — there were two occurrences, and this was the other one. When the screen names a file you are
    #  also editing, check every occurrence in it, not the one you remember writing.
    assert ok.get("emission_digest_sha3_512"), ok

    # ── 7. THE CALL SHAPE THAT RECURRED TWICE, over the WHOLE package ──────────────────────────
    #  W531 asserted this over ONE FILE and a second caller survived in the consultation package and stopped
    #  stage ANALYZE. The receivers below are the ones that genuinely implement the method; anything else
    #  resolved from a registry is the defect shape.
    root = _P(__file__).resolve().parents[1] / "agentic_core"
    offenders, receivers = [], []
    for path in sorted(root.rglob("*.py")):
        if "_archive" in path.parts:
            continue
        try:
            tree = _ast.parse(path.read_text(encoding="utf-8"))
        except SyntaxError:
            continue
        for n in _ast.walk(tree):
            if isinstance(n, _ast.Call) and isinstance(n.func, _ast.Attribute) and n.func.attr == "process":
                recv = _ast.unparse(n.func.value)
                receivers.append((path.name, n.lineno, recv))
                if recv not in ("self.vrpr",):
                    offenders.append((path.name, n.lineno, recv))
    assert not offenders, ("a caller invokes .process() on a receiver not known to implement it; the engines "
                           "do not, and this shape has now broken the loop twice: " + repr(offenders))
    assert receivers, "the scan found no .process calls at all, so it is not looking at the package"


def test_w534_the_preflight_stops_reading_comparisons_as_keys_and_qms_discloses_its_store():
    """P2.4 — FU-319, FU-262 and the first of FU-298's thirteen readers.

    The first two subjects are the pre-flight itself, which every round depends on, so each screen is driven
    BOTH ways: it must fire on the defect it exists for and stay silent on the honest shape it kept mistaking
    for one. Three of this instrument's screens have already needed a precision pass (FU-303, FU-317, FU-319),
    and the claims screen needed one within this round - its first version flagged 9 things across 25 rounds
    of real commits and 8 were noise.
    """
    import asyncio as _aio
    import importlib.util as _ilu
    from pathlib import Path as _P

    _root = _P(__file__).resolve().parents[1]
    _spec = _ilu.spec_from_file_location("_sc_w534", _root / "scripts/selfcheck_diff.py")
    sc = _ilu.module_from_spec(_spec)
    _spec.loader.exec_module(sc)

    # ── 1. FU-319 — a COMPARISON is not a produced key, and a compared dict READ is not one either ──
    #  Every dispatcher in this repository is built from `if x == "name":` lines, so the old screen asked
    #  which page displays a CLI subcommand name. No page displays one and none should.
    assert sc.keys_in('        if args.cmd == "satisfied":') == set(), "a comparison still reads as a key"
    assert sc.keys_in('    elif args.cmd == "bundles":') == set(), "an elif comparison still reads as a key"
    assert sc.keys_in('        case "withheld":') == set(), "a match/case label still reads as a key"
    #  the second defect, which FU-319 did not name: `\]\s*=` matched the FIRST `=` OF `==`
    assert sc.keys_in('        if cfg["mode"] == "strict":') == set(), \
        "a dict READ inside a comparison still counts as a key PRODUCED"
    #  and the exclusion must be NARROW — these are all real keys and must survive it
    assert sc.keys_in('            "agreement_score": agreement,') == {"agreement_score"}
    assert sc.keys_in('        vsb["last_evolved"] = now') == {"last_evolved"}
    assert sc.keys_in('                    "withheld_reason":') == {"withheld_reason"}, \
        "a key whose value sits on the next line was excluded with the comparisons"
    assert sc.keys_in('        if d == {"inner_key": 1}:') == {"inner_key"}, \
        "a real key inside an if-line was excluded because the line opens a block"

    # ── 2. FU-262 — the claims screen fires on an ASSERTED bound and not on a REPORTED one ─────
    assert "claims" in sc.CHECKS, "the claims screen is not registered, so no round would run it"
    #  (a) it fires on the shapes the labelled set is made of, including W494's own ground truth
    for lit in ("the blend cannot fall below 0.6",
                "at least 3 signatories are always required",
                "the p95 never exceeds 100ms",
                "the maximum is 240 and it must be respected"):
        assert sc._numeric_claim(lit), ("the claims screen cannot fire on an asserted bound", lit)
    #  (b) and it stays SILENT on honest bases — the half that made its first version unusable, because
    #      every basis in this repository opens with a round or item id and those digits are not claims
    for lit in ("W530 - no mutation regulator is configured, so no adaptation is approved",
                "not computed: this engine has no path to a model (measured: no gateway) - P3.16",
                "6 stage(s) measured individually; 0 breached an untuned default budget",
                "FU-310 made confidence three-state so an engine must say None rather than inventing a "
                "number, and nothing here is ever assumed",
                #  THESE THREE ARE THE ONES THAT TEST THE STANDALONE-NUMBER RULE, and they were added
                #  after driving this leg red exposed that the four above do not. Their modal word sits
                #  only a few characters from a ROUND OR ITEM ID, which is the commonest sentence shape
                #  in this repository's bases - so without the lookbehind that rejects a digit preceded
                #  by a letter, dot or hyphen, each of these fires and the screen becomes unreadable.
                "W494 showed that a basis cannot assert what nothing measured",
                "P3.16 - the loop must be driven from the beat",
                "W533 - a gate cannot clear on a literal"):
        assert not sc._numeric_claim(lit), ("the claims screen fires on an honest basis", lit)

    # ── 3. FU-298 (1 of 13) — qms figures say whether the store could be read WHOLE ─────────────
    from agentic_core.config import data_path as _dp
    from agentic_core.vbs.qms import QualityManagementSystem as _QMS

    whole = _QMS("w534_whole")
    _dp(whole._store_name).write_text('{"gates_run": 4, "defects_total": 2, "defects": []}',
                                      encoding="utf-8")
    sw = whole.defect_summary()
    assert "store_incomplete" not in sw, "a store read WHOLE claims to be incomplete"
    assert "counts_are_incomplete" not in sw, sw
    assert sw["gates_run"] == 4, sw
    assert "INCOMPLETE" not in sw["rate_basis"], sw["rate_basis"]

    cut = _QMS("w534_cut")
    _dp(cut._store_name).write_text('{"gates_run": 4, "defects_total": 2, "defe', encoding="utf-8")
    sc2 = cut.defect_summary()
    assert sc2.get("counts_are_incomplete") is True, ("a truncated store reports complete counts", sc2)
    assert (sc2.get("store_incomplete") or "").strip(), "the reason for the incompleteness is empty"
    #  and the RATE must say which way an unreadable store moves it, because it moves it in a known one
    assert "THIS RATE IS INCOMPLETE" in sc2["rate_basis"], sc2["rate_basis"]
    assert "may be better" in sc2["rate_basis"], ("the basis does not say which way the rate is wrong",
                                                  sc2["rate_basis"])

    # ── 4. AND THE ROUTE THAT PRINTS THE ROWS SAYS SO, because a caller may never read the summary ──
    import agentic_core.api.vbs_systems as _vbs
    _store = _dp(_vbs.qms._store_name)
    _before = _store.read_text(encoding="utf-8") if _store.exists() else None
    try:
        _store.write_text('{"gates_run": 1, "defects_total": 1, "defe', encoding="utf-8")
        _vbs.qms._state, _vbs.qms._store_unreadable = None, None
        res = _aio.run(_vbs.qms_defects("", None))
        assert res.get("listing_is_incomplete") is True, ("the rows are short and the route does not say "
                                                          "why", {k: res.get(k) for k in res if k != "defects"})
        assert (res.get("store_incomplete") or "").strip(), res
    finally:
        #  the module-level instance is shared with every other test in this run, so it is put back
        if _before is None:
            _store.unlink(missing_ok=True)
        else:
            _store.write_text(_before, encoding="utf-8")
        _vbs.qms._state, _vbs.qms._store_unreadable = None, None

    # ── 5. AND THE PAGE PRINTING THE RATE SHOWS IT, because a reason stopping at the API is not shown ──
    #  My own pre-flight asked this of this round's work - "no page reads it; if it qualifies a claim,
    #  which surface shows it?" - and measuring found NO frontend read store_incomplete at all, so the
    #  readers converted in W506 do not reach a page either. The rate is the figure an unreadable store
    #  flatters most, since the defects it cannot read are the ones missing from the numerator.
    panel = (_root / "apps/workstation-superapp/src/components/VBSSystemsPanel.tsx").read_text(
        encoding="utf-8")
    assert "counts_are_incomplete?: boolean" in panel, "the page's type does not carry the disclosure"
    #  the VISIBLE label, not only a tooltip: nobody hovers a percentage to learn it is partial
    assert "counts incomplete — rate may be better than the truth" in panel,         "the disclosure is not rendered as visible text"
    #  and the gate must be the FIELD, not a disabled conditional — a presence check cannot see {false && ...}
    assert "{defects.summary.counts_are_incomplete && (" in panel,         "the chip is not gated on the field the API sends"
    assert "{false &&" not in panel, "a disabled conditional renders nothing while naming the field"
    #  the rate chip itself changes tone, so the number carries the warning and not just its neighbour
    assert "tone={defects.summary.counts_are_incomplete ? 'warn' : 'dim'}" in panel,         "the rate is printed in the same tone whether or not it is complete"

    # ── 6. AN EMPTY LIST IS NOT A RECORD OF ZERO — the absence class, on a reached panel ───────
    #  This panel said "no defects recorded" whenever the list came back empty, so an unreadable store
    #  rendered as a positive statement that there are none: a failure shown as an absence, and the most
    #  flattering possible reading of a store nobody could read. Found by this round's own pre-flight,
    #  which asked which surface shows listing_is_incomplete and the answer was none.
    assert "the defect list could NOT be read" in panel,         "an unreadable defect list still renders as a record of zero defects"
    assert "defects.listing_is_incomplete" in panel, "the branch is not gated on the route's own flag"
    #  and the TRUE statement must survive: with the store read whole and no defects, there ARE none.
    #  Removing a true statement to fix an over-claim is itself a defect.
    assert "no defects recorded" in panel,         "the honest zero-defects message was deleted along with the over-claim"


def test_w535_the_owners_four_rulings_of_2026_10_02():
    """The four rulings: sequencing stands, three bars corrected, HIGH routes by area, FU-332 is live work.

    The two bar legs matter most, because an item closes on its ACCEPT clause: P2.12's bar demanded a list the
    Owner had ruled it ships WITHOUT, and P2.13's declared itself blocked on two answers already given. Neither
    item could be closed by any quality of work while its bar said that.
    """
    import ast as _ast
    import asyncio as _aio
    import os as _os
    from pathlib import Path as _P

    _root = _P(__file__).resolve().parents[1]
    prompt = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")

    # ── 1. THE RULINGS ARE RECORDED, where a later round will read them ────────────────────────
    assert prompt.count("OWNER RULINGS 2026-10-02") == 1, "the rulings of 2026-10-02 are not in the prompt"
    #  and they sit BEFORE the older block, so the newest ruling is the first one read
    assert prompt.index("OWNER RULINGS 2026-10-02") < prompt.index("OWNER RULINGS 2026-09-30"), \
        "the newest rulings block is filed below an older one"

    # ── 2. THE THREE BARS ARE CORRECTED — the stale demands are GONE, not merely annotated ─────
    assert prompt.count("CORRECTED W535 by Owner ruling 2026-10-02") == 3, \
        "three bars were ruled corrected; the prompt does not record three"
    #  P2.12 no longer requires the Owner to hand over a route list it was ruled to ship without
    assert "the distress routes are data with a reviewed-on date shown beside them (OWNER" not in prompt, \
        "P2.12's bar still makes the route list a precondition"
    assert "render as NOT SUPPLIED" in prompt, "P2.12's corrected bar does not state the visible absence"
    #  P2.13 is no longer blocked on answers that exist
    assert "BLOCKED BY the Owner's answers on reading" not in prompt, \
        "P2.13's bar still declares itself blocked on answers already given"
    #  P2.14 no longer maps onto a tier scale that does not exist, and names the four that do
    assert "0-1 applied and logged" not in prompt, "P2.14's body still names the absent 0-5 scale"
    assert "LOW / MEDIUM /" in prompt and "awaiting_board_ratification()" in prompt, \
        "P2.14's corrected mapping does not name the four ranks or the gate that reads them"
    #  and P2.4's cluster (a) records that FU-077 left the item
    _clust_a = prompt[prompt.index("(a) DEAD AND LEGACY CODE"):][:900]
    assert "slot OWNER" in _clust_a, "P2.4 cluster (a) does not record that FU-077 moved out of the item"

    # ── 3. A HIGH ROW ROUTES BY AREA, and the urgency fallback still exists ────────────────────
    import json as _json
    import agentic_core.plan_followups as _fu
    reg = _json.loads((_root / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))
    #  (a) a high row whose files belong to an area goes THERE, not to whichever item is next
    #  THE DESTINATION IS COMPUTED, NOT PINNED (FU-365). This named P3.16, and W555 closed P3.16 and
    #  handed its routes on — so the literal failed for the plan MOVING, the third instance of that class
    #  in two rounds and the reason it is now a filed row rather than three separate fixes. What the
    #  ruling actually guarantees is that a high row goes to the item whose ROUTE claims its files,
    #  whichever item that is, and that severity does not change the answer.
    _owner = next((rt["slot"] for rt in _fu.raw_routes(reg)
                   if any("agentic_core/mjm/" in str(f) for f in (rt.get("files") or []))), None)
    assert _owner, "no route claims agentic_core/mjm/, so this leg would measure the fallback instead"
    _open_slots = {i["slot"] for i in _fu.plan_items(prompt) if not i["done"]}
    assert _owner in _open_slots, ("the route claiming this area points at a CLOSED item, so new rows "
                                   "in it would be filed against something already done", _owner)
    hi = _fu.route_row(reg, prompt, "something wrong in the mjm engine", ["agentic_core/mjm/mjm.py"], "high")
    assert hi["slot"] == _owner, ("a high row did not route by area", hi, _owner)
    assert "routed by area" in hi["by"], hi
    #  (b) and a MEDIUM row with the same files reaches the same item — severity no longer picks the slot
    med = _fu.route_row(reg, prompt, "something wrong in the mjm engine", ["agentic_core/mjm/mjm.py"], "medium")
    assert med["slot"] == hi["slot"], ("severity still changes the destination", hi, med)
    #  (c) THE FALLBACK IS GONE, BECAUSE A LATER RULING SUPERSEDED THIS ONE (W592). This leg used to assert
    #      that a high row no route claims still rides the next open item — faithful to the ruling of
    #      2026-10-02, which kept that for the genuinely cross-cutting case. The Owner's ruling of 2026-10-05,
    #      the one that closed P2.18, decided the opposite ON EXACTLY THAT CASE: a row in an area NO OPEN ITEM
    #      CLAIMS is UNSCHEDULED and NAMES ITS OWN SLOT rather than being assigned to an item that does not
    #      own it. The measurement that forced it: W588 retired seven areas on that ruling, leaving EIGHT
    #      routes in the whole register, so "no route claims it" became the COMMON case — and registering
    #      MILESTONE M1 v7's twenty tier-1 findings put SEVENTEEN of them on P2.17, an item about the round's
    #      own cost that owns none of them, in a single command. P2.4, then P2.18, then P2.17: the same
    #      mechanism producing a sink for the third time. The assertion is inverted deliberately and the
    #      supersession is recorded here, because a guard that silently flips a ruling is worse than one that
    #      fails.
    none_claimed = _fu.route_row({"routes": []}, prompt, "a row no route claims", [], "high")
    assert none_claimed["slot"] is None, (
        "a high row that no route claims is still placed automatically, which the ruling of 2026-10-05 "
        "forbids — severity has gone back to choosing the destination", none_claimed)
    assert "sink" in str(none_claimed["reason"]), (
        "the refusal does not name the sink it is avoiding, so a later round reads it as a routing bug and "
        "restores the fallback", none_claimed)
    assert none_claimed["by"] is None, (
        "a refused row reports HOW it was routed, which it was not", none_claimed)
    #  (d) every branch of route_row answers with the SAME KEYS, so a caller indexing one shape does not
    #      raise on another. The refusal branch is the one a caller is least likely to have exercised.
    refused = _fu.route_row({"routes": []}, prompt, "a row no route claims", [], "low")
    for _k in ("slot", "by"):
        assert _k in hi and _k in none_claimed and _k in refused, \
            ("route_row's branches disagree on their keys", _k, sorted(hi), sorted(refused))
    assert refused["slot"] is None and refused["by"] is None, refused
    assert (refused.get("reason") or "").strip(), "a refusal does not say why it could not route"

    # ── 4. FU-332 — the multisig verifies THREE-STATE, and an unverifiable signature is not quorum ──
    import products.capital_fund.core.multisig_protocol as _mp

    class _U:
        async def log_event(self, name, payload):
            self.last = (name, payload)

    def _proto(u):
        p = _mp.RealMultiSigProtocol.__new__(_mp.RealMultiSigProtocol)
        p.ueg, p.quorum_threshold = u, 1
        p.proposals = {"p1": {"signatures": {}, "status": "PENDING"}}
        return p

    _key_before = _os.environ.pop("WORKSTATION_ATTESTATION_KEY", None)
    try:
        #  (a) NO KEY — the signature cannot be CHECKED. That is neither valid nor invalid, and the
        #      proposal must be untouched: a quorum of unchecked signatures is not a quorum.
        u1 = _U(); p1 = _proto(u1)
        assert _aio.run(p1.approve_proposal("p1", "did:a", b"\x01", b"pk")) is False
        assert u1.last[0] == "MULTISIG_SIGNATURE_UNVERIFIABLE", u1.last[0]
        assert u1.last[1]["counted_toward_quorum"] is False, u1.last[1]
        assert p1.proposals["p1"]["signatures"] == {}, "an unverifiable signature was recorded anyway"
        assert p1.proposals["p1"]["status"] == "PENDING", p1.proposals["p1"]["status"]

        #  (b) WITH a key and a wrong signature — that IS a rejection, and a DIFFERENT event, because
        #      "invalid" and "could not be checked" are different facts and only one blames the signer.
        _os.environ["WORKSTATION_ATTESTATION_KEY"] = "w535-guard-key"
        u2 = _U(); p2 = _proto(u2)
        assert _aio.run(p2.approve_proposal("p1", "did:a", b"\xde\xad", b"pk")) is False
        assert u2.last[0] == "MULTISIG_INVALID_SIGNATURE", u2.last[0]
    finally:
        _os.environ.pop("WORKSTATION_ATTESTATION_KEY", None)
        if _key_before is not None:
            _os.environ["WORKSTATION_ATTESTATION_KEY"] = _key_before

    # ── 5. THE REGULATORY MANIFEST stops asserting a certification nobody performed ─────────────
    import products.capital_fund.reporting.regulatory_reporter as _rr

    class _U2:
        async def log_event(self, *a, **k): return None
        async def get_events_in_range(self, *a, **k): return [{"e": 1}]
        async def query_events(self, *a, **k): return [{"e": 1}]

    rep = _rr.RegulatoryReporter.__new__(_rr.RegulatoryReporter)
    rep.fund_id, rep.ueg = "f1", _U2()
    try:
        bundle = _aio.run(rep.generate_fca_compliance_bundle("2026-01-01", "2026-03-31"))
    except Exception:                                     # noqa: BLE001 — see the source legs below
        bundle = None
    if isinstance(bundle, dict) and isinstance(bundle.get("manifest"), dict):
        man = bundle["manifest"]
        assert man["status"] in ("ATTESTED", "NOT ATTESTED"), ("a manifest status was invented", man["status"])
        assert "pqc_manifest_signature" not in man, "the fabricated manifest signature is back"
        assert "merkle_root" not in man, "a whole-set digest is still called a Merkle root"
        assert man.get("events_digest"), man
        assert "NOT a Merkle root" in man["events_digest_basis"], man["events_digest_basis"]
        assert bundle.get("summary_pdf") is None, "a placeholder is back where PDF content belongs"
    #  the source legs hold whether or not the call above could run, so an environment that cannot
    #  reach the method still screens the three fabrications
    rsrc = (_root / "products/capital_fund/reporting/regulatory_reporter.py").read_text(encoding="utf-8")
    assert "FINAL_CERTIFIED" not in rsrc, "the hard-coded certification status is back"
    assert "Base64_PDF_Content_of_" not in rsrc, "the placeholder PDF string is back"

    # ── 6. THE WITHDRAWAL'S MONEY GATE COMES FIRST — on the AST, because ORDER is the property ──
    #  Not behavioural, and the reason is recorded rather than hidden: crypto_gateway cannot be imported
    #  at all, because products/capital_fund/core/vault.py calls firestore.client() at MODULE SCOPE. That
    #  is a second, separate cause of FU-332's symptom and rides FU-346. A text search could see the gate
    #  exists; only the AST can see that nothing precedes it.
    gsrc = (_root / "products/capital_fund/adapters/crypto_gateway.py").read_text(encoding="utf-8")
    gtree = _ast.parse(gsrc)
    fn = next((n for n in _ast.walk(gtree)
               if isinstance(n, (_ast.AsyncFunctionDef, _ast.FunctionDef))
               and n.name == "execute_onchain_withdrawal"), None)
    assert fn is not None, "the withdrawal function is gone"
    body = [b for b in fn.body if not (isinstance(b, _ast.Expr) and isinstance(b.value, _ast.Constant))]
    #  W535 — THIS LEG WAS VACUOUS ON ITS FIRST WRITING, caught by driving it red. It concatenated the first
    #  TWO statements and searched the result for the flag, so inserting a statement at position 0 left the
    #  flag still present in the haystack and the check passed. Order is an INDEX property, not a substring
    #  one: find the gate, then assert that everything before it is only the acquisition of the flag it tests.
    gate_at = next((i for i, b in enumerate(body)
                    if isinstance(b, _ast.If) and "REAL_MONEY_ENABLED" in _ast.unparse(b.test)), None)
    assert gate_at is not None, "the on-chain withdrawal has no money gate at all"
    preamble = [_ast.unparse(b) for b in body[:gate_at]]
    assert all("REAL_MONEY_ENABLED" in p for p in preamble), \
        ("something runs before the money gate in an on-chain withdrawal: " + "; ".join(preamble)[:200])
    assert any(isinstance(n, _ast.Return) for n in _ast.walk(body[gate_at])), \
        "the money gate does not return, so execution continues past a refusal"
    #  and the gate must REFUSE rather than raise, so a caller learns why instead of catching a ValueError
    assert '"status": "REFUSED"' in gsrc or "'status': 'REFUSED'" in gsrc, "the gate does not refuse explicitly"
    #  the validator must not be handed a literal in place of the attestation it is meant to establish
    assert '"pqc_signed": True' not in gsrc, "the governance check is still fed a fabricated input"
    assert '"pqc_verified": True' not in gsrc, "the withdrawal still returns an unconditional verification"

    # ── 7. THE CLAIM SCREEN now scans products/, and sees lower-case spellings ──────────────────
    #  W535 — BOTH HALVES OF THIS LEG WERE VACUOUS ON THEIR FIRST WRITING, caught by driving them red.
    #  Each asserted that a literal appeared in THIS FILE, and each assertion CONTAINED that literal, so it
    #  matched itself and could never fail. An assert cannot search its own file for its own text. The
    #  exclusion list is now read as a VALUE off the AST, and the case-insensitivity is asserted where it
    #  matters — on the repository, not on the screen's wording.
    me_tree = _ast.parse(_P(__file__).read_text(encoding="utf-8"))
    excl_nodes = [n for n in _ast.walk(me_tree)
                  if isinstance(n, _ast.Assign)
                  and any(isinstance(t, _ast.Name) and t.id == "EXCLUDED" for t in n.targets)]
    assert len(excl_nodes) == 1, ("expected exactly one exclusion list in this file", len(excl_nodes))
    excluded_values = [e.value for e in excl_nodes[0].value.elts if isinstance(e, _ast.Constant)]
    assert "products/" not in excluded_values, \
        ("the product tree is excluded from the claim scan again", excluded_values)
    #  and THE SUBSTANCE the case-insensitivity was for: no file under the product tree names a forbidden
    #  algorithm in ANY case. A lower-cased spelling is how a fabricated manifest signature hid from this
    #  screen until W535, so the spelling is checked here rather than trusted to the other screen's wording.
    _named = []
    for _py in sorted((_root / "products").rglob("*.py")):
        for _i, _line in enumerate(_py.read_text(encoding="utf-8").splitlines(), 1):
            _low = _line.lower()
            if "dilithium" in _low or "kyber" in _low:
                _named.append(f"{_py.relative_to(_root).as_posix()}:{_i}")
    assert not _named, ("the product tree names a forbidden algorithm: " + ", ".join(_named))


def test_w536_the_platforms_claims_about_its_own_instruments_are_true(client):
    """P2.17 — the constitution's *Verified:* citations resolve, the forecast computes its figures, and the
    round-start check reports what it CANNOT see.

    The first leg exists because Article 5 — titled AN INSTRUMENT THAT CANNOT FAIL IS NOT EVIDENCE — cited
    `scripts/blind_sweep.py` as its verification, and that file has never been committed. An article forbidding
    unfalsifiable evidence resting on a file nobody can run is the most self-undermining defect available here,
    so the citations are now machine-checked rather than trusted.
    """
    import os as _os
    import re as _re
    from pathlib import Path as _P

    _root = _P(__file__).resolve().parents[1]

    # ── 1. EVERY PATH THE CONSTITUTION CITES AS VERIFIED RESOLVES ──────────────────────────────
    con = (_root / "agentic_core/constitution/CONSTITUTION_canonical.md")
    text = con.read_text(encoding="utf-8")
    lines = text.splitlines()
    _path_re = _re.compile(r"`([A-Za-z0-9_./-]+\.(?:py|tsx|ts|md|json|yaml|yml))`")
    #  the document cites most paths relative to agentic_core/; a check ignoring that over-reports. Measured:
    #  a naive pass called 6 of 16 absent, and exactly ONE was.
    roots = ("", "agentic_core/", "apps/workstation-superapp/src/")
    cited, missing = 0, []
    for i, line in enumerate(lines, 1):
        if "*Verified" not in line:
            continue
        blob = line
        for nxt in lines[i:i + 4]:
            if nxt.startswith("#") or "*Verified" in nxt or not nxt.strip():
                break
            blob += " " + nxt
        for rel in _path_re.findall(blob):
            cited += 1
            if not any((_root / (pre + rel)).exists() for pre in roots):
                missing.append(f"line {i}: {rel}")
    assert cited >= 12, ("the citation scan found almost nothing, so it is not reading the document", cited)
    assert not missing, ("the constitution cites a verification that does not exist: " + "; ".join(missing))

    #  and Article 5 specifically must not claim a committed harness while none is committed
    a5 = text[text.index("## 5 "):]
    a5 = a5[:a5.index("## 6 ")]
    #  W537 — THIS PAIR IS CONDITIONAL ON THE FILE, in both directions. W536 wrote the first half as a
    #  near-invariant (if the article names the harness it must say it is absent), which was true while
    #  the harness was missing and became wrong the moment it landed. The property is symmetric.
    _harness = (_root / "scripts/blind_sweep.py").exists()
    if not _harness:
        assert "blind_sweep.py" not in a5 or "NOT IN THIS REPOSITORY" in a5, \
            "Article 5 cites the blind harness while it is absent, without stating the absence"
    assert not _harness or "NOT IN THIS REPOSITORY" not in a5, \
        "the harness now exists, so Article 5's statement that it is absent is itself stale"
    #  AND THE ABSENCE MUST SIT ON THE LINE THE API CAPTURES. Added after driving this red: the parser at
    #  agentic_core/api/integration_surface.py:183 takes the remainder of the *Verified* line and nothing
    #  else, so moving the caveat one line down leaves the surface reporting a mechanism while omitting that
    #  it is not mechanised — and the legs above, which read the whole article, could not see that.
    _cap = _re.search(r"(?im)^\*?Verified:\*?\s*(.+?)\s*$", a5)
    assert _cap, "Article 5 has no line the API parser can read a mechanism from"
    if not _harness:
        assert "NOT IN THIS REPOSITORY" in _cap.group(1), \
            ("the API-captured mechanism omits that the harness is absent, so the surface over-claims: "
             + _cap.group(1)[:200])

    # ── 2. THE FORECAST COMPUTES ITS COMPARISON instead of typing it ───────────────────────────
    #  Driven through the ROUTE, not read off the source: a source check cannot tell a computed figure from a
    #  typed one once both are strings, and pinning source text is what broke two suites in W533 and W534.
    r = client.get("/api/v1/method/forecast")
    assert r.status_code == 200, r.status_code
    blk = (r.json() or {}).get("which_rate_measures_completion")
    if blk is not None:                                # absent only when the projection itself was refused
        assert "rows_closed_in_window" in blk, ("the window count is not reported", sorted(blk))
        assert blk.get("the_lever") == "items", blk
        assert (blk.get("why_basis") or "").strip(), "the block does not say where its figures came from"
        #  the typed sentence that was here named a fixed row count and a fixed round count
        why = blk.get("why") or ""
        assert "32 rows closed" not in why, "the typed row count is back"
        assert "forty-eight" not in why, "the typed round count is back"
        #  when both rates measured, the figures in the sentence must MATCH the fields beside it
        if isinstance(blk.get("rows_per_round"), (int, float)) and isinstance(blk.get("items_per_round"), (int, float)):
            assert str(blk["rows_per_round"]) in why and str(blk["items_per_round"]) in why, \
                ("the sentence states figures that are not the ones reported", why[:180], blk)

    # ── 3. FU-345 — A ROW NAMING NO FILES IS COUNTED AS UNEXAMINED, not silently dropped ───────
    #  DRIVEN, because the live register currently has zero such rows: a leg asserting the count is non-zero
    #  would be false today, and one asserting only that the FIELD exists could not fail. So the condition is
    #  created here.
    from agentic_core.api.method import _rows_the_tree_moved_under as _moved
    out = _moved([{"id": "FU-TEST-NOFILES", "files": [], "found_in_round": 400, "slot": "P2.17"},
                  {"id": "FU-TEST-HASFILES", "files": ["agentic_core/api/method.py"],
                   "found_in_round": 1, "slot": "P2.17"}])
    assert out["not_considered_row_count"] == 1, (out["not_considered_row_count"], out["not_considered_rows"])
    assert out["not_considered_rows"] == ["FU-TEST-NOFILES"], out["not_considered_rows"]
    assert (out.get("not_considered_basis") or "").strip(), "the check does not say what it could not consider"
    assert "UNEXAMINED" in out["not_considered_basis"], out["not_considered_basis"]
    #  and the commit-width figure is counted from the same log the candidates came from
    assert isinstance(out.get("commits_no_round_could_be_read_from"), int), out
    assert out["commits_no_round_could_be_read_from"] <= (out.get("history_commits") or 0), out

    # ── 4. AND THE ROUND-START STEP PRINTS IT, because the row was about the step and not the payload ──
    #  Run as a subprocess with the path PINNED from the environment: a stray .pth puts the repo root on
    #  sys.path for every local process here, so a probe that works locally can fail on CI for a reason that
    #  has nothing to do with the code (W520 cost a 48-minute red that way).
    import subprocess as _sp
    import sys as _sys
    _env = dict(_os.environ, PYTHONPATH=str(_root), PYTHONIOENCODING="utf-8")
    _p = _sp.run([_sys.executable, str(_root / "scripts/followups.py"), "satisfied"],
                 capture_output=True, text=True, errors="replace", cwd=str(_root), env=_env)
    assert _p.returncode == 0, ("the round-start step exits non-zero", _p.returncode, (_p.stderr or "")[-400:])
    _stdout = _p.stdout or ""
    assert "NOT CONSIDERED:" in _stdout,         ("the round-start step does not state what it could not consider", _stdout[-500:])
    assert "LIMIT:" in _stdout, "the round-start step dropped its stated limits"


def test_w537_the_blind_harness_and_the_stall_detector_can_both_fail():
    """P2.17 bar (b) — the harness Article 5 cites, and a verdict for a run that never finishes.

    Both are instruments, so both are asserted on their OWN controls rather than on the happy path. The harness
    must separate three outcomes, and the one that matters is the third: pytest exits 5 when a selector collects
    nothing, and a sweep reading 5 as "nothing failed" reports off an absent test and calls a blind guard green.
    The stall detector must produce a middle verdict, because a run that did not finish is neither a pass nor a
    failure and had no verdict at all before this.
    """
    import ast
    import importlib.util as _ilu
    import json as _json
    import os as _os
    from pathlib import Path as _P

    _root = _P(__file__).resolve().parents[1]

    def _load(name, rel):
        spec = _ilu.spec_from_file_location(name, _root / rel)
        mod = _ilu.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    # ── 1. THE HARNESS exists, and classifies every exit code it can see ───────────────────────
    sweep = _load("_bs_w537", "scripts/blind_sweep.py")
    assert sweep._VERDICT_BY_EXIT[1] == sweep.BLIND_RED, "a failing guard is not reported as seeing the defect"
    assert sweep._VERDICT_BY_EXIT[0] == sweep.VACUOUS, "a passing guard is not reported as blind"
    #  THE CONTROL THAT MATTERS: exit 5 is NO TESTS COLLECTED and must never read as a pass
    assert sweep._VERDICT_BY_EXIT[5] == sweep.BAD_BLIND, \
        "exit 5 (no tests collected) is classified as something other than a bad blind, so a sweep could " \
        "report off an absent test"
    for _code in (2, 3, 4):
        assert sweep._VERDICT_BY_EXIT[_code] == sweep.BAD_BLIND, _code
    #  an unknown exit code must not fall through to a guard verdict
    assert sweep._VERDICT_BY_EXIT.get(99, sweep.BAD_BLIND) == sweep.BAD_BLIND

    # ── 2. ITS CONTROL SET declares what each blind should produce, and covers all three ────────
    blinds = _json.loads((_root / "scripts/blinds_core.json").read_text(encoding="utf-8"))
    assert len(blinds) >= 4, len(blinds)
    expected = {b.get("expect") for b in blinds}
    assert {sweep.BLIND_RED, sweep.VACUOUS, sweep.BAD_BLIND} <= expected, \
        ("the control set does not cover all three verdicts, so a sweep over it could not show the harness "
         "distinguishes them", sorted(expected))
    for b in blinds:
        for k in ("tag", "file", "old", "new", "selector", "expect", "why"):
            assert (b.get(k) or "").strip(), (b.get("tag"), k)
        assert (_root / b["file"]).exists(), ("a blind names a file that is not there", b["file"])

    # ── 3. A TWICE-MATCHING ANCHOR is refused WITHOUT running anything ──────────────────────────
    #  Driven, not read: the harness is called on a blind whose anchor is deliberately ambiguous, and must
    #  report BAD BLIND having applied no mutation. A sweep that applies one of several matches measures
    #  something other than what its blind describes.
    import hashlib as _hl
    _target = _root / "scripts/run_verdict.py"
    _before = _hl.sha256(_target.read_bytes()).hexdigest()
    rep = sweep.sweep([{"tag": "ambiguous anchor", "file": "scripts/run_verdict.py",
                        "old": "return", "new": "return  # x", "selector": "w537"}],
                      "integration_tests/test_mvp_spine.py", str(_P(_os.environ["DATA_DIR"]) / "w537sweep"))
    assert rep["counts"][sweep.BAD_BLIND] == 1, rep["results"]
    assert "matched" in (rep["results"][0]["why"] or ""), rep["results"][0]
    assert rep["results"][0]["exit"] is None, "something was run despite the anchor being ambiguous"
    assert _hl.sha256(_target.read_bytes()).hexdigest() == _before, "the harness altered a file it refused"

    # ── 4. A SWEEP THAT FINDS A BLIND GUARD CANNOT EXIT ZERO ───────────────────────────────────
    #  Otherwise a round chaining on the sweep reads "a vacuous guard was found" as success.
    _src = (_root / "scripts/blind_sweep.py").read_text(encoding="utf-8")
    _tree = ast.parse(_src)
    _main = next(n for n in ast.walk(_tree) if isinstance(n, ast.FunctionDef) and n.name == "main")
    _ret = ast.unparse(_main).split("return ")[-1]
    assert "VACUOUS" in _ret and "BAD_BLIND" in _ret, \
        ("the sweep's exit code does not depend on both failure kinds: " + _ret[:160])

    # ── 5. THE STALL DETECTOR gives three verdicts, and the middle one is driven ────────────────
    rv = _load("_rv_w537", "scripts/run_verdict.py")
    _tmp = _P(_os.environ["DATA_DIR"]) / "w537_verdicts"
    _tmp.mkdir(parents=True, exist_ok=True)

    _complete = _tmp / "complete.json"
    _complete.write_text(_json.dumps({"collected": 12, "reported": 12}), encoding="utf-8")
    assert rv.verdict(str(_complete))["verdict"] == rv.COMPLETE

    #  THE VERDICT THAT DID NOT EXIST: a run that stopped partway is not a pass and not a failure
    _stalled = _tmp / "stalled.json"
    _stalled.write_text(_json.dumps({"collected": 535, "reported": 404}), encoding="utf-8")
    _v = rv.verdict(str(_stalled))
    assert _v["verdict"] == rv.INCOMPLETE, _v
    assert _v["unreported"] == 131, _v
    assert "UNKNOWN rather than green" in _v["basis"], _v["basis"]

    #  absence, and an unreadable file, are NOT KNOWN rather than either verdict
    assert rv.verdict(str(_tmp / "absent.json"))["verdict"] == rv.NOT_KNOWN
    _bad = _tmp / "bad.json"
    _bad.write_text("{not json", encoding="utf-8")
    assert rv.verdict(str(_bad))["verdict"] == rv.NOT_KNOWN
    _noc = _tmp / "nocount.json"
    _noc.write_text(_json.dumps({"reported": 5}), encoding="utf-8")
    assert rv.verdict(str(_noc))["verdict"] == rv.NOT_KNOWN

    # ── 6. THE HOOK WRITES THE SELECTED SET, not the collected one ──────────────────────────────
    #  This was a real defect in the first version: pytest_collection_modifyitems runs BEFORE -k deselection,
    #  so a filtered run reported 532 collected against 1 reported and read as INCOMPLETE — a false positive
    #  on exactly the selector runs each round depends on.
    _cf = (_root / "integration_tests/conftest.py").read_text(encoding="utf-8")
    assert "def pytest_collection_finish(session):" in _cf, \
        "the progress hook counts before deselection again, so every selector run reads as incomplete"
    assert "len(session.items)" in _cf, _cf[:0] or "the hook does not count the selected set"
    assert 'hasattr(session.config, "workerinput")' in _cf, \
        "a worker may write the total, which would report its shard as the whole run"

    # ── 7. THE ISOLATION PROBE no longer claims to detect a shared store ───────────────────────
    _iso = (_root / "integration_tests/test_xdist_iso.py").read_text(encoding="utf-8")
    assert "another worker overwrote this worker's file" not in _iso, \
        "the probe claims to detect an overwrite it cannot: the filenames differ either way"
    assert "is all this probe establishes" in _iso, "the probe does not say what it actually proves"
    #  and the assertions that DO establish isolation are still there
    assert _iso.count('f"__{worker}" in') == 2, "the path assertions that prove isolation were removed"

    # ── 8. A SWEEP MAY NOT RUN INSIDE A SWEEP ──────────────────────────────────────────────────
    #  Driven, because this is the condition that spawned 38 python processes in this round: the harness's own
    #  guard calls sweep(), and a blind driven against that guard disabled the ambiguity refusal, so the inner
    #  sweep ran `-k` on the test that had called it. Selector discipline would be a convention; the marker is
    #  structural and cannot be defeated by a badly chosen selector.
    assert sweep.NESTED_GUARD_ENV, "the nested-sweep marker has no name"
    assert sweep._VERDICT_BY_EXIT[sweep.NESTED_EXIT] == sweep.BAD_BLIND, \
        "a refused nested sweep is reported as a guard verdict, which it is not — pytest was never reached"
    _refused = sweep._run_selector("anything", "integration_tests/test_mvp_spine.py",
                                   {sweep.NESTED_GUARD_ENV: "1"})
    assert _refused == sweep.NESTED_EXIT, \
        ("a sweep ran inside a sweep instead of refusing", _refused)
    #  and it must NOT refuse when the marker is absent — otherwise every sweep would report BAD BLIND and
    #  the harness would be unable to measure anything while appearing to run.
    #  AND THE FAILURE EXPLAINS ITSELF. This asserted on a bare exit code, and when CI reported 3 (pytest's
    #  INTERNAL ERROR) instead of 5 (nothing collected) there was no way to know why: the harness discarded
    #  the child's output. It now keeps it, so the message below states the cause on the run that fails.
    _ctl537 = sweep._run_selector("no_such_test_w537_nested_control",
                                  "integration_tests/test_mvp_spine.py",
                                  dict(_os.environ))
    assert _ctl537 == 5, (
        "the runner refuses even outside a sweep, so no blind could ever reach a verdict",
        {"exit": _ctl537, "5": "nothing collected, which is what a selector matching no test must give",
         "3": "pytest internal error - the child's output follows",
         "child": sweep.LAST_RUN.get("output")})

    # ── 9. A KILLED SWEEP LEAVES A RECOVERABLE MARKER, and a stale one blocks the next run ──────
    #  `finally` does not run when the process is killed, and in this round one mutation DID survive a
    #  taskkill /F. A restore that only works on a clean exit is not a restore for a tool whose job is to
    #  break things.
    _store = _P(_os.environ["DATA_DIR"]) / "w537marker"
    _store.mkdir(parents=True, exist_ok=True)
    _marker = _store / "IN_FLIGHT.json"
    #  a completed sweep leaves none
    sweep.sweep([{"tag": "ambiguous anchor, no run", "file": "scripts/run_verdict.py",
                  "old": "return", "new": "return  # x", "selector": "w537"}],
                "integration_tests/test_mvp_spine.py", str(_store))
    assert not _marker.exists(), "a completed sweep left an in-flight marker behind"
    #  a stale marker makes the entry point REFUSE rather than mutate on top of an unrestored tree
    _marker.write_text(_json.dumps({"file": "scripts/run_verdict.py", "restore_sha256": "deadbeef",
                                    "tag": "a killed sweep", "bytes_len": 1}), encoding="utf-8")
    import subprocess as _sp2
    import sys as _sys2
    _r = _sp2.run([_sys2.executable, str(_root / "scripts/blind_sweep.py"),
                   "--blinds", str(_root / "scripts/blinds_core.json"), "--store", str(_store)],
                  capture_output=True, text=True, errors="replace", cwd=str(_root),
                  env=dict(_os.environ, PYTHONPATH=str(_root), PYTHONIOENCODING="utf-8"))
    assert _r.returncode != 0, "a sweep ran on top of an unrestored tree"
    assert "REFUSING" in (_r.stdout or ""), (_r.stdout or "")[-300:]
    #  and --recover must say the file is STILL MUTATED when the sha does not match
    _r2 = _sp2.run([_sys2.executable, str(_root / "scripts/blind_sweep.py"),
                    "--blinds", str(_root / "scripts/blinds_core.json"),
                    "--store", str(_store), "--recover"],
                   capture_output=True, text=True, errors="replace", cwd=str(_root),
                   env=dict(_os.environ, PYTHONPATH=str(_root), PYTHONIOENCODING="utf-8"))
    assert "STILL MUTATED" in (_r2.stdout or ""), (_r2.stdout or "")[-300:]
    assert _r2.returncode != 0, "--recover reported a mutated file and exited zero"
    _marker.unlink(missing_ok=True)


def test_w538_mjm_measures_or_refuses_and_a_digest_is_not_a_proof(client):
    """P3.16 Round A — FU-328, FU-342, FU-343, FU-341, and a stale reason corrected.

    FU-328 reached TWO public routes with a typed entropy of 0.12 and a typed compliance of 1.0. api/vsb.py
    already disclosed that its result was a literal; api/cognitive.py returned the dict as-is, so the producer
    is fixed rather than one of its readers — a disclosure at one of two readers leaves the other lying.
    """
    import asyncio as _aio
    import os as _os
    from pathlib import Path as _P

    _root = _P(__file__).resolve().parents[1]
    from agentic_core.mjm.mjm import MJMOrchestratorV4 as _MJM

    # ── 1. THE TYPED VALUES ARE GONE from the producer ─────────────────────────────────────────
    _mjm_src = (_root / "agentic_core/mjm/mjm.py").read_text(encoding="utf-8")
    assert '"entropy": 0.12' not in _mjm_src, "the typed entropy is back"
    assert '"compliance": 1.0' not in _mjm_src, "the typed compliance is back"
    assert '"result": "optimised"' not in _mjm_src, "the claimed optimisation is back"

    # ── 2. THE LEG THAT MATTERS: the entropy DIFFERS by signal ─────────────────────────────────
    #  A constant satisfies presence, type and range. Only a comparison across inputs separates a measurement
    #  from a literal, which is the whole defect class here.
    m = _MJM()
    low = _aio.run(m.mushahida({"challenge": "aaaaaaaaaaaaaaaaaaaaaaaa"}))
    high = _aio.run(m.mushahida({"challenge": "a7Qz9pL2Xm4Rt!#%&*()+="}))
    lo, hi = low["shannon_entropy_bits_per_byte"], high["shannon_entropy_bits_per_byte"]
    assert isinstance(lo, float) and isinstance(hi, float), (lo, hi)
    assert lo != hi, ("the entropy is the same for two very different signals, so it is not measuring them",
                      lo, hi)
    assert hi > lo, ("a more varied signal did not measure as higher entropy", lo, hi)
    assert 0.0 <= lo <= 8.0 and 0.0 <= hi <= 8.0, (lo, hi)
    #  and the key NAMES what it measured, in its own units
    assert "bits per byte" in low["entropy_basis"], low["entropy_basis"]
    assert "signal" in low["entropy_basis"].lower(), low["entropy_basis"]
    #  the step does not claim to have judged anything
    assert low["observation_performed"] is False, low

    # ── 3. THE REFUSAL IS REACHABLE, and does not escape as a 500 ──────────────────────────────
    #  Measured: `default=str` makes nearly anything serialisable, so the reachable failures are a CIRCULAR
    #  REFERENCE (ValueError) and an object whose own __str__ raises (anything). The second propagated before
    #  this round, and this method is reached from a public route.
    _circular = {}
    _circular["self"] = _circular
    assert _MJM._signal_entropy_bits_per_byte(_circular) is None, "a circular signal did not refuse"

    class _Boom:
        def __str__(self):
            raise RuntimeError("this object cannot be described")

    assert _MJM._signal_entropy_bits_per_byte(_Boom()) is None, \
        "an object whose __str__ raises propagates instead of refusing, which would 500 a public route"
    #  a single-symbol payload measures ZERO, not NEGATIVE zero
    _zero = _MJM._signal_entropy_bits_per_byte("")
    assert _zero == 0.0 and str(_zero) != "-0.0", ("a figure served as negative zero", _zero)

    # ── 4. COMPLIANCE AND RESULT ARE NOT ASSESSED, and say so ──────────────────────────────────
    act = _aio.run(m.muaina({"status": "completed"}))
    assert act["compliance"] is None, ("a compliance verdict is claimed again", act["compliance"])
    assert act["result"] is None, ("an optimisation is claimed again", act["result"])
    assert "NOT ASSESSED" in act["compliance_basis"], act["compliance_basis"]
    assert "nothing is executed" in act["result_basis"], act["result_basis"]

    # ── 5. AND THE PUBLIC ROUTE SERVES THAT, not a literal ─────────────────────────────────────
    #  The producer was fixed instead of this reader, so the route inherits the truth. Driven through the
    #  route because that is where a caller reads it.
    r = client.post("/api/v1/cognitive/cascade",
                    json={"problem": "a test problem for w538", "include_mjm": True})
    assert r.status_code == 200, (r.status_code, r.text[:200])
    _mjm_served = (r.json() or {}).get("mjm")
    if isinstance(_mjm_served, dict) and "compliance" in _mjm_served:
        assert _mjm_served["compliance"] is None, \
            ("the route serves a compliance verdict nothing assessed", _mjm_served.get("compliance"))
        assert (_mjm_served.get("compliance_basis") or "").strip(), _mjm_served

    # ── 6. FU-342 — a digest is not a proof ────────────────────────────────────────────────────
    from agentic_core.avatars.cognition.mushawara_bridge import AvatarCognitiveOrchestrator as _ACO
    orch = _ACO(None, None)
    v = _aio.run(orch.verify_output({"text": "an ordinary emission for w538"}))
    assert v["verified"] is True, v
    assert "merkle_proof" not in v, "a bare digest is called a Merkle proof again"
    assert len(v["emission_digest_sha3_512"]) == 128, len(v.get("emission_digest_sha3_512", ""))
    assert "proves no inclusion" in v["emission_digest_basis"], v["emission_digest_basis"]

    # ── 7. FU-343 — the dead seam is GONE, not wired ───────────────────────────────────────────
    from agentic_core.consultation.mushawara.perspective_aggregator import PerspectiveAggregator as _PA
    agg = _PA()                                  # constructible with no argument at all now
    assert not hasattr(agg, "mjm"), "the unread mjm attribute is back"
    #  a caller passing one still works, and it is still not stored as a wired learner
    agg2 = _PA(object())
    assert not hasattr(agg2, "mjm"), "a passed learner is stored again, implying it is consulted"
    assert agg2.mjm_learner_accepted_and_unused is True, agg2.__dict__

    # ── 8. FU-341 — 0.0ms is a DECLINED update, proven by driving the branch that does update ──
    #  The row asks whether LEARN can learn at all. It can: the stage declines only because the platform
    #  cycle records no outcome, which is W530's deliberate refusal to move a stored profile on no evidence.
    from agentic_core.avatars.core.recirculation_orchestrator import AvatarRecirculationOrchestrator as _ARO
    from agentic_core.avatars.core.avatar_engine import AvatarState as _AS
    from agentic_core.ueg.logger import VSBUEGLogger as _UEG
    _orch = _ARO(_UEG(), _AS(avatar_id="w538", user_id="w538user"))
    _updates = []

    async def _capture_update(uid, dom, ok):      # update_skill is awaited, so the stub must be awaitable
        _updates.append((uid, dom, ok))

    _orch.skill_profiler.update_skill = _capture_update

    _declined = _aio.run(_orch._stage_learn({"user_id": "w538user", "domain": "d",
                                             "user_context": {}, "state": {}}))
    assert _updates == [], ("a profile was moved with no recorded outcome", _updates)
    assert "NOT updated" in _declined["skill"], _declined["skill"]

    _recorded = _aio.run(_orch._stage_learn({"user_id": "w538user", "domain": "d",
                                             "user_context": {"success": True}, "state": {}}))
    assert _updates == [("w538user", "d", True)], \
        ("the stage cannot learn even when an outcome IS recorded, so 0.0ms was an unreached branch rather "
         "than a declined update", _updates)
    assert "updated from a recorded outcome" in _recorded["skill"], _recorded["skill"]

    # ── 9. THE BREACH RECORD IS DRIVEN, because it cannot fail on its own ──────────────────────
    #  Budgets are 100/200/500/500 and measured latencies 24/112/115/152, so no stage has ever breached and
    #  "breach_count equals the number breached" holds trivially at zero. A budget is lowered so one fires.
    _saved = dict(_ARO._STAGE_BUDGETS_MS)
    try:
        _ARO._STAGE_BUDGETS_MS["SENSE"] = 0          # any real stage exceeds nought milliseconds
        _o2 = _ARO(_UEG(), _AS(avatar_id="w538b", user_id="w538b"))
        _res = _aio.run(_o2.execute_cycle({"user_id": "w538b", "domain": "d"}))
        _stages = _res.get("stages") or []
        assert _stages, _res
        _sense = next((g for g in _stages if g["stage"] == "SENSE"), None)
        assert _sense and _sense["breached"] is True, \
            ("a stage exceeding a nought-millisecond budget did not record a breach", _sense)
    finally:
        _ARO._STAGE_BUDGETS_MS.clear()
        _ARO._STAGE_BUDGETS_MS.update(_saved)
    assert _ARO._STAGE_BUDGETS_MS == _saved, "the budgets were not restored"

    # ── 10. D12 — the stale justification is corrected ─────────────────────────────────────────
    _api = (_root / "agentic_core/avatars/api.py").read_text(encoding="utf-8")
    assert "fails on its very first" not in _api, \
        "the docstring still says the loop fails at its first stage, which W533 made false"
    assert "runs all six" in _api, "the docstring does not state what the loop now does"

    # ── 11. AND THE OTHER READER'S NOTE, which this round's own fix made stale ──────────────────
    #  api/vsb.py disclosed MJM's literals correctly and named the two values. Fixing the producer made that
    #  note false, and a stale disclosure is the same defect as a missing one: the next round reads it as the
    #  state of the code. The sentence that remains TRUE — the same six engines, so no second judgement — is
    #  asserted still present, so the correction cannot be made by deleting the whole note.
    _vsb = (_root / "agentic_core/api/vsb.py").read_text(encoding="utf-8")
    assert "its result is a literal" not in _vsb, "the stale claim that MJM returns a literal is back"
    assert "not an independent" in _vsb or "not a second, independent" in _vsb,         "the note lost the part that is still true: MJM re-runs the same six engines"


def test_w539_the_pass_set_comparator_can_say_different_and_incomplete():
    """P2.17 bar (b)1 — the instrument that makes "the same pass/fail set" checkable.

    The suite costs about 55 minutes serially and W507 measured the parallel alternative at 10m35s on six
    workers, a 4.8x saving, with the sets matching. It was never adopted because FU-301 records three of six
    parallel runs STALLING, and until W537 a stall looked like a run still in progress. The bar asks for the
    sets to be PROVEN equal on the same tree; this comparator is what makes that claim checkable, and the two
    runs are the proof itself.

    Driven on synthetic reports on purpose: a guard that needs an hour to run is a guard no round will run.
    """
    import ast
    import importlib.util as _ilu
    import os as _os
    from pathlib import Path as _P

    _root = _P(__file__).resolve().parents[1]
    _spec = _ilu.spec_from_file_location("_psd_w539", _root / "scripts/pass_set_diff.py")
    psd = _ilu.module_from_spec(_spec)
    _spec.loader.exec_module(psd)

    _tmp = _P(_os.environ["DATA_DIR"]) / "w539"
    _tmp.mkdir(parents=True, exist_ok=True)

    def _report(name, cases):
        body = "".join('<testcase classname="t" name="%s">%s</testcase>' % (n, inner) for n, inner in cases)
        p = _tmp / name
        p.write_text('<testsuites><testsuite name="p" tests="%d" failures="0" errors="0" skipped="0">%s'
                     '</testsuite></testsuites>' % (len(cases), body), encoding="utf-8")
        return str(p)

    base = _report("a.xml", [("t1", ""), ("t2", ""), ("t3", "<skipped/>")])

    # ── 1. SAME means every node in both runs with the same outcome ────────────────────────────
    same = psd.compare(base, _report("b.xml", [("t1", ""), ("t2", ""), ("t3", "<skipped/>")]))
    assert same["verdict"] == psd.SAME, same
    assert same["shared"] == 3, same
    #  and it must NOT claim more than two runs agreeing on one tree
    assert "not about the parallel suite in general" in same["basis"], same["basis"]

    # ── 2. DIFFERENT NAMES THE NODE, because a count hides what kind of difference it is ───────
    diff = psd.compare(base, _report("c.xml", [("t1", ""), ("t2", "<failure/>"), ("t3", "<skipped/>")]),
                       "serial", "parallel")
    assert diff["verdict"] == psd.DIFFERENT, diff
    assert diff["differing"] and diff["differing"][0]["node"].endswith("t2"), diff["differing"]
    assert diff["differing"][0]["serial"] == "passed", diff["differing"][0]
    assert diff["differing"][0]["parallel"] == "failure", diff["differing"][0]
    #  a skipped test is an OUTCOME, not an absence: a run that skips where the other passes differs
    skipdiff = psd.compare(base, _report("d.xml", [("t1", ""), ("t2", "<skipped/>"), ("t3", "<skipped/>")]))
    assert skipdiff["verdict"] == psd.DIFFERENT, skipdiff

    # ── 3. A MISSING NODE IS NAMED on the side that has it ─────────────────────────────────────
    short = psd.compare(base, _report("e.xml", [("t1", "")]), "serial", "parallel")
    assert short["verdict"] == psd.DIFFERENT, short
    assert len(short["only_a"]) == 2, short["only_a"]
    assert short["only_b"] == [], short["only_b"]

    # ── 4. INCOMPLETE — an absent or truncated report is NOT a smaller set, it is no set ───────
    #  pytest writes the junit file at the END of a run, so a STALLED run leaves nothing or a partial
    #  document. Comparing against that would adopt the parallel suite on evidence that does not exist.
    assert psd.compare(base, str(_tmp / "never_written.xml"))["verdict"] == psd.INCOMPLETE
    _trunc = _tmp / "trunc.xml"
    _trunc.write_text("<testsuites><testsuite tests=", encoding="utf-8")
    inc = psd.compare(base, str(_trunc))
    assert inc["verdict"] == psd.INCOMPLETE, inc
    assert "ABSENT rather than" in inc["basis"], inc["basis"]
    #  and an EMPTY but well-formed report is incomplete too, not a match against nothing
    empty = _tmp / "empty.xml"
    empty.write_text('<testsuites><testsuite name="p" tests="0"></testsuite></testsuites>', encoding="utf-8")
    assert psd.compare(base, str(empty))["verdict"] == psd.INCOMPLETE

    # ── 5. THE ENTRY POINT cannot exit zero on anything but SAME ───────────────────────────────
    #  Otherwise a round chaining on the comparison reads DIFFERENT or INCOMPLETE as agreement.
    _src = (_root / "scripts/pass_set_diff.py").read_text(encoding="utf-8")
    _tree = ast.parse(_src)
    _main = next(n for n in ast.walk(_tree) if isinstance(n, ast.FunctionDef) and n.name == "main")
    _ret = [ast.unparse(n) for n in ast.walk(_main) if isinstance(n, ast.Return)]
    assert any("SAME" in r and "0" in r for r in _ret), ("the exit code does not gate on SAME", _ret)

    # ── 6. THE TWO INSTRUMENTS COVER DIFFERENT HALVES, and the proof needs both ────────────────
    #  run_verdict.py answers "did the run finish"; this answers "did the sets match". A stalled run writes
    #  no junit file at all, so neither alone is sufficient and the proof procedure runs both.
    _rvspec = _ilu.spec_from_file_location("_rv_w539", _root / "scripts/run_verdict.py")
    rv = _ilu.module_from_spec(_rvspec)
    _rvspec.loader.exec_module(rv)
    assert rv.INCOMPLETE == psd.INCOMPLETE == "INCOMPLETE", "the two instruments disagree on the word"
    assert hasattr(rv, "verdict") and hasattr(psd, "compare"), "an instrument lost its entry point"

    # ── 7. A DECLARED DIFFERENCE IS ALLOWED, AN UNDECLARED ONE IS NOT ──────────────────────────
    #  Without this, bar (b)1 is unsatisfiable by construction: test_each_worker_owns_its_store SKIPS
    #  serially (there is no worker to isolate from) and PASSES in parallel, correctly and permanently. A
    #  comparator demanding identical sets would answer DIFFERENT on every tree forever.
    decl = {"test_each_worker_owns_its_store": "skips serially by design"}
    bydesign = _report("f.xml", [("t1", ""), ("test_each_worker_owns_its_store", "")])
    serialish = _report("g.xml", [("t1", ""), ("test_each_worker_owns_its_store", "<skipped/>")])
    ok = psd.compare(serialish, bydesign, "serial", "parallel", decl)
    assert ok["verdict"] == psd.SAME, ok
    assert len(ok["declared"]) == 1 and ok["declared"][0]["declared_because"], ok["declared"]
    #  a declaration must NOT swallow an undeclared difference in the same run
    mixed = _report("h.xml", [("t1", "<failure/>"), ("test_each_worker_owns_its_store", "")])
    bad = psd.compare(serialish, mixed, "serial", "parallel", decl)
    assert bad["verdict"] == psd.DIFFERENT, bad
    assert [d["node"] for d in bad["differing"]] == ["t::t1"], bad["differing"]
    assert len(bad["declared"]) == 1, "the declared difference was lost when another one appeared"
    #  and the declaration file this repo ships must carry a REASON for every entry
    import json as _json2
    _decl_file = _json2.loads((_root / "scripts/parallel_expected_differences.json").read_text(encoding="utf-8"))
    assert _decl_file, "the declaration file is empty"
    for _k, _v in _decl_file.items():
        assert len(_v) > 60, (_k, "a declared difference must carry its reason, not just its name")

    # ── 8. THE PARALLEL DENOMINATOR — the detector must not be blind in the mode it exists for ──
    #  MEASURED in this round's proof: the parallel run wrote {"collected": null, "reported": 539} and
    #  run_verdict answered NOT KNOWN for a run that finished. Under xdist each WORKER collects its own
    #  shard, so the controller's pytest_collection_finish sees nothing. FU-301's stalls are parallel stalls.
    _cf = (_root / "integration_tests/conftest.py").read_text(encoding="utf-8")
    assert "def pytest_xdist_node_collection_finished(node, ids):" in _cf,         "the progress hook cannot learn a parallel run's total, so it is blind where FU-301 lives"
    assert "_xdist_ids.update(ids or ())" in _cf, _cf[:0] or "the worker ids are not unioned"
    #  and the serial hook must not clobber a total the xdist hook established
    assert "if not _xdist_ids:" in _cf,         "the serial hook overwrites the parallel denominator, turning a correct total back into zero"

    # ── 9. FU-349 — the federation seed asserts its OWN contribution, not an absolute receipt ───
    #  W539's proof found this node failing in parallel and passing serially. MEASURED cause: the test's
    #  first cycle runs its sender's waterfall, and §12's reinvestment fans out to living VSBs through
    #  ventures.py `list(_living().items())[:cap]` — crediting the receiver 231.82 "§12 reinvestment from"
    #  its own sender. It passed serially only because earlier tests had registered enough VSBs to push the
    #  pair beyond the cap, a reason unrelated to what the test asserts.
    #  bounded by the FUNCTION'S OWN EXTENT, not an arbitrary slice: a fixed character window cut off
    #  before the last assertion and reported it missing when it was there.
    _spine = (_root / "integration_tests/test_mvp_spine.py").read_text(encoding="utf-8")
    _seed_at = _spine.index("def test_inter_vsb_transfer_federation_seed")
    _seed_end = _spine.find(chr(10) + "def ", _seed_at + 10)
    _seed = _spine[_seed_at:_seed_end if _seed_end > 0 else len(_spine)]
    assert 'nxt["inter_vsb_received_wst"] == 500.0' not in _seed,         "the federation seed asserts an absolute receipt again, which its own sender's waterfall can inflate"
    assert "_queued_before" in _seed, "the test does not measure what was already queued before its transfer"
    assert "round(_queued_before + 500.0, 2)" in _seed,         "the test does not assert its own 500 as a delta on whatever was already pending"
    assert "round(1000.0 + _received, 2)" in _seed,         "the intake arithmetic is not asserted against what the cycle actually drained"

    # ── 10. THE PARALLEL SUITE'S ADOPTION STAYS GATED ──────────────────────────────────────────
    #  W540 proved bar (b)1 on one tree: serial 52m52s and parallel 9m47s produced the SAME pass set over
    #  539 node ids, four declared differences. The risk a proof creates is that its conclusion outlives its
    #  conditions — FU-301's stall is still unexplained, and this run not stalling is evidence about THIS
    #  run. So the rhythm must carry the gate (every parallel run checked for completeness) and the
    #  re-proof rule, or a later round reads "use -n 6" and drops the half that makes it safe.
    _prompt = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    assert "PROVEN W540" in _prompt, "bar (b)1 does not record that it was proven, or with what figures"
    _rhythm_at = _prompt.index("Per increment:")
    _rhythm = _prompt[_rhythm_at:_rhythm_at + 3000]
    assert "run_verdict.py" in _rhythm, \
        "the rhythm adopts the parallel suite without naming the completeness gate, so a stall reads as a pass"
    assert "INCOMPLETE" in _rhythm, "the rhythm does not say what an unfinished run means"
    assert "pass_set_diff.py" in _rhythm, "the rhythm names no way to RE-PROVE the equivalence"
    assert "every tenth round" in _rhythm, "the rhythm sets no interval for re-proving it"
    #  and the figures in the bar must be the ones actually measured, not rounded into a claim
    assert "52m52s" in _prompt and "9m47s" in _prompt, "the proof's own timings are not recorded"
    assert "539 node ids" in _prompt, "the bar does not say how many nodes the comparison covered"


def test_w541_support_answers_carry_provenance_and_nothing_resolves_itself(client):
    """P3.18 Round A — the archived support simulation's shape recovered without its claims.

    What is being refused: _archive/agentic_core/support/ slept a tier-shaped latency, returned
    "Simulated resolution for query: {query}" with a confidence of 0.96 and success=True unconditionally, and
    an archived sla_monitor divided over tickets it had INVENTED against that literal to compute 100%. Every
    step of that division is real arithmetic, which is why the leg that matters is not "the rate is right" but
    "the rate cannot exist without a confirmation".
    """
    import ast
    import asyncio as _aio
    import os as _os
    from pathlib import Path as _P

    _root = _P(__file__).resolve().parents[1]
    from agentic_core.support import tickets as T

    # ── 1. A RATE CANNOT BE PRODUCED WITHOUT A CONFIRMATION ────────────────────────────────────
    #  Three states, and the middle one is what the simulation collapsed: answered is not resolved.
    r0 = T.rate()
    assert r0["rate"] is None, ("a rate was reported with nothing confirmed", r0)
    assert "NOT COMPUTED" in r0["basis"], r0["basis"]
    #  and the basis must say what it is NOT, because 0.0 and 1.0 are the two tempting wrong answers
    assert "not 0.0" in r0["basis"] and "not 1.0" in r0["basis"], r0["basis"]

    t = T.create_ticket("w541-user", "my build fails with a lock timeout", "standard")
    assert t["confirmed"] is None, t
    T.record_answer(t["id"], "clear the lock file", served_by="native", is_external=False,
                    failed=False, latency_ms=123.4, next_step="reply if it still fails")
    r1 = T.rate()
    assert r1["rate"] is None, ("an ANSWER produced a resolution rate", r1)
    assert r1["answered"] == 1 and r1["unconfirmed"] == 1, r1
    assert "an answer alone" in r1["basis"] or "different thing from a resolution" in r1["basis"], r1["basis"]

    # ── 2. ONLY A CONFIRMATION WRITES `resolved`, and it must name its source ──────────────────
    rec = T.confirm(t["id"], True, by="user:w541-user")
    assert rec["confirmed"] is True and rec["confirmed_by"] == "user:w541-user", rec
    r2 = T.rate()
    assert r2["rate"] == 1.0 and r2["confirmed_resolved"] == 1, r2
    #  a confirmation is True or False; "nobody has said" is not a third value you may PASS
    try:
        T.confirm(t["id"], None, by="x")
        raise AssertionError("confirming with None was accepted, so absence can be written as a verdict")
    except TypeError:
        pass

    # ── 3. UNCONFIRMED IS EXCLUDED FROM BOTH SIDES, not counted as a win ───────────────────────
    t2 = T.create_ticket("w541-user", "second problem")
    T.record_answer(t2["id"], "try the other thing", served_by="native", is_external=False,
                    failed=False, latency_ms=99.9, next_step="reply if it still fails")
    r3 = T.rate()
    assert r3["rate"] == 1.0, ("an unconfirmed ticket changed the rate", r3)
    assert r3["unconfirmed"] == 1, r3
    T.confirm(t2["id"], False, by="user:w541-user")
    r4 = T.rate()
    assert r4["rate"] == 0.5, ("a confirmed failure did not enter the denominator", r4)

    # ── 4. A FAILED CALL IS NOT AN ANSWER, and it escalates with a next step ───────────────────
    t3 = T.create_ticket("w541-user", "third problem")
    T.record_answer(t3["id"], "", served_by=None, is_external=False, failed=True,
                    latency_ms=30000.0, next_step="escalated: a human reviewer picks this up")
    r5 = T.rate()
    assert r5["answered"] == 2, ("a failed call counted as an answer", r5["answered"])
    _rec3 = T.get(t3["id"])
    assert _rec3["answer"]["failed"] is True, _rec3
    assert "THE CALL FAILED" in _rec3["answer"]["provenance_basis"], _rec3["answer"]["provenance_basis"]
    assert (_rec3["next_step"] or "").strip(), "an unresolved ticket carries no next step"

    # ── 5. NOTHING SLEEPS TO IMITATE WORK ──────────────────────────────────────────────────────
    #  The archived agent's tier difference WAS a sleep (0.1s vs 0.5s), which is how its latency looked
    #  plausible. Asserted on the AST of the whole package, not on a word search.
    for _f in sorted((_root / "agentic_core/support").rglob("*.py")):
        _tree = ast.parse(_f.read_text(encoding="utf-8"))
        for _n in ast.walk(_tree):
            if isinstance(_n, ast.Call):
                _src = ast.unparse(_n.func)
                assert not _src.endswith("sleep"), (
                    f"{_f.name}:{_n.lineno} sleeps, which is how the archived agent imitated work")
    _api_src = (_root / "agentic_core/api/support.py").read_text(encoding="utf-8")
    _api_tree = ast.parse(_api_src)
    for _n in ast.walk(_api_tree):
        if isinstance(_n, ast.Call) and ast.unparse(_n.func).endswith("sleep"):
            raise AssertionError(f"api/support.py:{_n.lineno} sleeps")

    # ── 6. NO CONFIDENCE FLOAT, AND NO SECOND GOVERNANCE PATH ──────────────────────────────────
    #  The archive reported a confidence of 0.96 that nothing computed; the item's body forbids a second
    #  governance path, so an approval or gate field invented here would be exactly what it names.
    #  Forbidden as a PRODUCED KEY, on the AST, not as a word: this module's own docstring explains that the
    #  archive reported one and that nothing here does, so a word search forbids the explanation along with
    #  the defect. That is the banned-literal trap, and it has cost six red runs across this programme.
    for _d in [n for n in ast.walk(_api_tree) if isinstance(_d_t := n, ast.Dict)]:
        for _k in _d.keys:
            if isinstance(_k, ast.Constant) and isinstance(_k.value, str):
                assert "confidence" not in _k.value.lower(), (
                    f"api/support.py:{_d.lineno} produces a {_k.value!r} key; nothing computes a confidence "
                    f"here and the archive's 0.96 was a literal")
    for _word in ("def approve", "approved=True", '"approved": True', "gate_passed"):
        assert _word not in _api_src, (f"api/support.py invents its own governance ({_word}); the item's body "
                                       f"routes support logic changes through the existing Change Control "
                                       f"Agency and forbids a second path")

    # ── 7. THE ARCHIVED SIMULATION IS NOT IMPORTED by anything live ────────────────────────────
    for _f in sorted((_root / "agentic_core").rglob("*.py")):
        _txt = _f.read_text(encoding="utf-8")
        assert "autonomous_support_agent" not in _txt, (f"{_f} imports the archived simulation")
        assert "Simulated resolution for query" not in _txt, (f"{_f} carries the archived marker string")

    # ── 8. AND THE ROUTES SERVE IT — the item is reached, not a library nobody calls ────────────
    a = client.post("/api/v1/support/ask", json={"query": "w541 probe: a lock timeout on build"})
    assert a.status_code == 200, (a.status_code, a.text[:200])
    d = a.json()
    assert d["resolved"] is None, ("the route resolved a ticket by answering it", d["resolved"])
    assert "only from a confirmation" in d["resolved_basis"], d["resolved_basis"]
    assert (d["next_step"] or "").strip(), d
    _p = d["provenance"]
    assert "served_by" in _p and "failed" in _p and "latency_ms" in _p, _p
    assert isinstance(_p["latency_ms"], float) and _p["latency_ms"] >= 0.0, _p
    assert "measured, not simulated" in _p["provenance_basis"], _p["provenance_basis"]
    #  an answer that failed is returned as ABSENT, not as an empty string a page would render as blank
    if d["answered"] is False:
        assert d["answer"] is None and d["escalated"] is True, d

    sla = client.get("/api/v1/support/sla")
    assert sla.status_code == 200, sla.status_code
    _s = sla.json()
    assert _s["simulated"] is False, _s
    assert "invented" in _s["method"], ("the SLA view does not say how it differs from the archived "
                                        "monitor's 100%", _s["method"])
    #  and whatever the rate is, it was computed over confirmations: the denominator is reported
    assert _s["confirmed_resolved"] is not None and _s["confirmed_unresolved"] is not None, _s


def test_w542_a_support_change_is_the_agencys_to_decide_and_a_ledger_miss_is_reported(client, tmp_path):
    """P3.18 Round B: the governance path, the attested record, and the page that cannot print a percentage.

    Round A built the ticket core and proved a rate cannot exist without a confirmation. This completes the
    item's remaining body clauses. Each leg asserts a PROPERTY driven through a surface, never a spelling:
    the one leg that reads a .tsx asserts the ABSENCE of an arithmetic path, because an absence cannot be
    faked by a branch that never renders — which is how a presence check survives `{false && ...}`.
    """
    import ast
    import json
    import pathlib

    _root = pathlib.Path(__file__).resolve().parents[1]

    # ── L1. A SUPPORT CHANGE IS FILED WITH THE EXISTING AGENCY, AND NOTHING HERE DECIDES IT ────────
    pc = client.post("/api/v1/support/policy-change", json={
        "title": "Support: escalate after one failed answer",
        "description": "Escalate on the first failed call rather than the second.",
        "rationale": "A second failed attempt wastes the user's time.",
        "rollback_plan": "Restore the previous threshold constant."})
    assert pc.status_code == 200, (pc.status_code, pc.text[:300])
    _pc = pc.json()
    assert _pc["cca_id"].startswith("cca-"), _pc
    #  The outcome is NOT this module's to report. A filing that rendered as a decision would be the
    #  second governance path the item's body forbids, arrived at by accident rather than by design.
    assert _pc["decided"] is False, ("support reported a verdict on its own change request", _pc)
    assert _pc["status"] == "submitted", ("a filing came back already decided", _pc["status"])

    #  and the AGENCY holds it — the filing reached the real store, not a support-side copy of one
    from agentic_core.config import data_path as _dp
    _cca_dir = pathlib.Path(_dp("change_control"))
    _rows = ([json.loads(p.read_text(encoding="utf-8")) for p in _cca_dir.glob("*.json")]
             if _cca_dir.is_dir() else [])
    _mine = [r for r in _rows if r.get("cca_id") == _pc["cca_id"]]
    assert len(_mine) == 1, (f"the change is not in the Agency's own store ({len(_mine)} found)", _pc["cca_id"])
    assert _mine[0]["status"] == "submitted", ("support's change self-approved", _mine[0]["status"])
    assert _mine[0]["affected_systems"] == ["agentic_core/support"], _mine[0]["affected_systems"]
    assert str(_mine[0]["submitted_by"]).startswith("support:") or _mine[0]["submitted_by"], _mine[0]
    #  the tier is READ from the record, never remembered here: both sides must agree
    assert _pc["impact_tier"] == _mine[0]["impact_tier"], (_pc["impact_tier"], _mine[0]["impact_tier"])

    #  NO SECOND GOVERNANCE PATH, asserted on the AST rather than on a word anywhere in the text: no
    #  callable in this package may be an approver, and no route it mounts may be an approval path.
    from agentic_core.api import support as _api_support
    _paths = {r.path for r in _api_support.router.routes}
    for _p in _paths:
        assert not any(w in _p for w in ("approve", "ratify", "implement", "apply")), (
            f"support mounts its own approval route {_p!r}; the Agency owns that decision")
    for _f in sorted((_root / "agentic_core" / "support").glob("*.py")) + [
            _root / "agentic_core" / "api" / "support.py"]:
        _tree = ast.parse(_f.read_text(encoding="utf-8"))
        for _n in ast.walk(_tree):
            if isinstance(_n, (ast.FunctionDef, ast.AsyncFunctionDef)):
                assert not any(w in _n.name.lower() for w in ("approve", "ratify", "decide")), (
                    f"{_f.name}:{_n.lineno} defines {_n.name!r} — support decides no change of its own")

    # ── L2. THE TICKET EVENTS ARE IN THE LEDGER, AND AN ALTERED RECORD IS DETECTABLE ──────────────
    a = client.post("/api/v1/support/ask", json={"query": "w542: the export header is missing"})
    assert a.status_code == 200, a.status_code
    _a = a.json()
    assert _a["ledger"]["recorded"] is True, _a["ledger"]
    assert _a["ledger"]["ledger_entry"], ("recorded with no ledger entry to point at", _a["ledger"])
    c = client.post("/api/v1/support/confirm",
                    json={"ticket_id": _a["ticket_id"], "resolved": False, "by": "user:w542"})
    assert c.status_code == 200 and c.json()["ledger"]["recorded"] is True, c.text[:300]

    from agentic_core.attestation import verify as _verify
    from agentic_core.ueg.registry import ueg_ledger as _ueg
    _lines = [json.loads(ln) for ln in pathlib.Path(_ueg.log_path).read_text(
        encoding="utf-8").splitlines() if ln.strip()]
    _events = [e for e in _lines
               if str(e["payload"]["event_type"]).startswith("support.")
               and e["payload"]["data"].get("ticket_id") == _a["ticket_id"]]
    assert {e["payload"]["event_type"] for e in _events} == {
        "support.answered", "support.confirmed"}, [e["payload"]["event_type"] for e in _events]
    for _e in _events:
        _data = dict(_e["payload"]["data"])
        _att = _data.pop("attestation")
        _v = _verify(_data, _att)
        #  THREE-STATE, and the leg asserts the part that discriminates. This deployment configures no
        #  attestation key, so `verified` is None for every record — "unverifiable is not invalid" — and a
        #  leg asserting `verified is True` would be red for an honest reason and tell nobody anything.
        #  The digest comparison is what separates an intact record from an altered one either way.
        assert _v["verified"] in (True, None), _v
        assert _v["payload_digest_matches"] is True, ("the ledger's own record does not match its "
                                                      "attestation", _e["payload"]["event_type"], _v)
        _tampered = {**_data, "ticket_id": "tkt-somebody-elses"}
        _v2 = _verify(_tampered, _att)
        assert _v2["payload_digest_matches"] is False, (
            "an altered record still matches its attestation, so the attestation establishes nothing", _v2)
        assert _v2["verified"] is not True, _v2

    # ── L3. A LEDGER APPEND THAT FAILED IS REPORTED, NEVER ASSUMED ────────────────────────────────
    #  This drives the except branch, which nothing else in the suite reaches. Without it the branch is
    #  code nobody has ever run, and "we report a failed append" is a claim about an untested path.
    import agentic_core.api.support as _sup_mod

    class _DeadLedger:
        log_path = _ueg.log_path

        async def log_event(self, *a, **k):
            raise OSError("the ledger is not writable (driven by test_w542)")

    _real = _sup_mod.ueg_ledger
    try:
        _sup_mod.ueg_ledger = _DeadLedger()
        a2 = client.post("/api/v1/support/ask", json={"query": "w542: ledger down"})
    finally:
        _sup_mod.ueg_ledger = _real
    assert a2.status_code == 200, ("a ledger failure took the answer down with it", a2.status_code)
    _l = a2.json()["ledger"]
    assert _l["recorded"] is False, ("an append that raised was reported as recorded", _l)
    assert _l["ledger_entry"] is None, _l
    assert "OSError" in _l["basis"] and "NOT RECORDED" in _l["basis"], _l["basis"]
    #  and the answer itself survived: a ledger problem is not an answer problem
    assert a2.json()["answered"] is True and a2.json()["answer"], a2.json()

    # ── L4. THE PAGE HAS NO PATH TO A PERCENTAGE, AND PRINTS THE BACKEND'S REFUSAL ────────────────
    import re as _re
    _tsx = (_root / "apps/workstation-superapp/src/pages/support/Support.tsx").read_text(encoding="utf-8")
    #  An ABSENCE, which is why this leg is worth having: a presence check on a rendered string survives a
    #  branch that never renders, but a page with no arithmetic on the rate cannot compute one anywhere.
    assert _re.search(r"rate\s*\*|\*\s*100|toFixed|Math\.round", _tsx) is None, (
        "the page computes a figure from the rate; the archived monitor's number was arithmetically sound "
        "too, and the page must print only what the backend computed")
    #  no numeric fallback for a three-state rate: `?? 0` is how a refusal becomes a zero on screen
    for _ln in _tsx.splitlines():
        if "rate" in _ln:
            assert "?? 0" not in _ln and "|| 0" not in _ln, ("the page defaults the rate to a number", _ln)
    assert "sla.basis" in _tsx, "the page does not print the backend's own basis for the rate"
    assert "provenanceBadge" in _tsx, "the page shows an answer without the shared provenance helper"
    assert "ans.ledger.basis" in _tsx, "the page paraphrases the ledger state instead of printing it"
    #  and it is REACHED: registered as a route and offered in the navigation. ACTIVE, not merely present —
    #  a commented-out route still contains its own path string, so `'path="/support"' in src` passes on a
    #  page nobody can open. That is the same hole as a JSX gate naming its field in both the condition and
    #  the body, and it is how this leg was vacuous on its first run.
    def _uncommented(text: str, needle: str) -> list[str]:
        return [ln for ln in text.splitlines()
                if needle in ln and not ln.strip().startswith(("//", "{/*", "/*", "*", "{ /*"))]

    _app = (_root / "apps/workstation-superapp/src/App.tsx").read_text(encoding="utf-8")
    assert _uncommented(_app, 'path="/support"'), (
        "the support route is absent or commented out, so nothing can open the page",
        [ln.strip()[:80] for ln in _app.splitlines() if "/support" in ln])
    _side = (_root / "apps/workstation-superapp/src/components/layout/Sidebar.tsx").read_text(
        encoding="utf-8")
    assert _uncommented(_side, "id: 'support'"), (
        "the support page is routed but offered in no navigation")


def test_w542_a_fresh_backend_also_refuses_to_rate_what_nobody_confirmed(tmp_path):
    """The fresh-backend probe P3.18's bar names: a NEW interpreter, on a store this session never touched.

    An in-process assertion can pass on state this run happens to hold — the suite has already created
    tickets by the time the rate is read. This starts a separate Python on an empty DATA_DIR, answers a
    ticket there and asserts the rate is still refused, so "answered is not resolved" is a property of the
    code rather than of the order this suite happens to run in.
    """
    import json
    import subprocess
    import sys
    from pathlib import Path as _P

    root = _P(__file__).resolve().parents[1]
    script = tmp_path / "probe.py"
    script.write_text(
        "import sys, os\n"
        # pinned from the env: this script lives in tmp_path, so the repo root is on no path at all, and
        # this machine has a stray .pth that would otherwise hide the assumption completely.
        "sys.path.insert(0, os.environ['WS_ROOT'])\n"
        "import agentic_core as _ac\n"
        # and it must be THIS repository's module: with the root absent, `import agentic_core` still
        # succeeds as an empty NAMESPACE package whose __file__ is None.
        "assert _ac.__file__ and os.path.realpath(_ac.__file__).startswith("
        "       os.path.realpath(os.environ['WS_ROOT'])), ('wrong agentic_core', _ac.__file__)\n"
        "import json\n"
        "from agentic_core.support import tickets\n"
        "t = tickets.create_ticket('probe-user', 'why is my build failing?')\n"
        "tickets.record_answer(t['id'], 'Because the lock file is stale.', 'native', False, False,"
        "                      12.5, 'confirm whether this resolved it')\n"
        "before = tickets.rate()\n"
        "refused_none = None\n"
        "try:\n"
        "    tickets.confirm(t['id'], None, 'probe')\n"
        "except TypeError as e:\n"
        "    refused_none = str(e)\n"
        "tickets.confirm(t['id'], True, 'probe')\n"
        "after = tickets.rate()\n"
        "print(json.dumps({'before': before['rate'], 'before_basis': before['basis'],\n"
        "                  'answered': before['answered'], 'unconfirmed': before['unconfirmed'],\n"
        "                  'refused_none': refused_none, 'after': after['rate'],\n"
        "                  'after_denom': after['confirmed_resolved'] + after['confirmed_unresolved']}))\n",
        encoding="utf-8")
    d = tmp_path / "fresh"
    env = {**__import__("os").environ, "DATA_DIR": str(d), "WORKSTATION_DATA_DIR": str(d),
           "WORKSTATION_UEG_PATH": str(d / "ueg.json"), "PROJECTS_DIR": str(d / "projects"),
           "AI_DISABLE_LOCAL": "1", "WS_ROOT": str(root), "PYTHONPATH": str(root)}
    r = subprocess.run([sys.executable, str(script)], capture_output=True, text=True,
                       cwd=str(root), env=env)
    assert r.returncode == 0, ("the fresh backend could not run the support core", r.stderr[-700:])
    out = json.loads([ln for ln in r.stdout.splitlines() if ln.startswith("{")][-1])
    #  ANSWERED, AND STILL NOT RATED. This is the whole item in one assertion.
    assert out["answered"] == 1 and out["unconfirmed"] == 1, out
    assert out["before"] is None, ("a fresh backend rated an answer nobody confirmed", out)
    assert "NOT COMPUTED" in out["before_basis"], out["before_basis"]
    #  and None is refused as a confirmation: absence of a verdict is not a verdict you may write
    assert out["refused_none"] and "confirmation is True or False" in out["refused_none"], out
    #  then one confirmation, and only then a figure — over a denominator of exactly that one record
    assert out["after"] == 1.0 and out["after_denom"] == 1, out


def test_w543_a_cycle_reports_a_measured_figure_or_says_it_cannot(client, tmp_path):
    """P3.19: the six cycles as a reported control surface, and three fabricated figures removed.

    Every leg drives behaviour. The two that read source read the AST, never the text, because this
    round's own comments quote the defects they removed — including the generator calls — and a text
    search would match the explanation instead of the code.
    """
    import ast
    import asyncio as _aio
    import pathlib

    _root = pathlib.Path(__file__).resolve().parents[1]

    #  SEEDED AND SNAPSHOTTED BEFORE ANY ROUTE CALL. The first version of the store leg below took its
    #  snapshot in the middle of the test, after two reads had already happened — so a surface writing a
    #  cache on EVERY call had already written it, both snapshots matched, and the leg passed with the
    #  defect restored. A bracket must enclose every call it means to judge.
    from agentic_core.economy.ledger import VirtualLedger
    _vsb = "vsb-w543-guard"
    VirtualLedger(_vsb).record("reserves", 640.0, memo="w543 guard", kind="credit")
    from agentic_core.config import data_path as _dp
    _ddir = pathlib.Path(_dp(""))
    _files_before_any_read = sorted(q.name for q in _ddir.iterdir()) if _ddir.is_dir() else None
    assert _files_before_any_read, ("the data directory is unreadable, so this leg could not fail",
                                    str(_ddir))

    # ── L1. AN UNMEASURED CYCLE REPORTS NO FIGURE AND NO VERDICT ───────────────────────────────────
    r = client.get("/api/v1/cycles")
    assert r.status_code == 200, (r.status_code, r.text[:200])
    j = r.json()
    rows = {c["name"]: c for c in j["cycles"]}
    assert set(rows) == {"water", "carbon", "nitrogen", "oxygen", "phosphorus", "sulfur"}, sorted(rows)
    for _n in ("nitrogen", "phosphorus", "sulfur"):
        c = rows[_n]
        assert c["assessable"] is False, (_n, "claims a binding it does not have", c)
        #  THE KEYS ARE ABSENT, not null. A null invites `value ?? 0`, and the zero is the fabrication
        #  arriving back by another route.
        assert "value" not in c, (_n, "an unbound cycle carries a value", c)
        assert "deviation" not in c and "within_tolerance" not in c, (_n, "a verdict over nothing", c)
        assert c["measured_from"] is None, (_n, c["measured_from"])
        #  and the refusal names what WOULD bind it, so it is an instruction rather than a shrug
        assert "NOT ASSESSED" in c["basis"] and "To bind it" in c["basis"], (_n, c["basis"])

    # ── L2. A BOUND FIGURE EQUALS AN INDEPENDENT READ OF ITS OWN SOURCE ───────────────────────────
    j2 = client.get("/api/v1/cycles", params={"vsb_id": _vsb}).json()
    rows2 = {c["name"]: c for c in j2["cycles"]}
    _independent = sum(v for v in VirtualLedger(_vsb).balances().values() if isinstance(v, (int, float)))
    assert rows2["water"]["assessable"] is True, rows2["water"]
    assert rows2["water"]["value"] == _independent, (
        "the reported liquidity is not the ledger's own figure",
        rows2["water"]["value"], _independent)
    assert "ledger.py" in (rows2["water"]["measured_from"] or ""), rows2["water"]["measured_from"]
    #  the count is the ledger's too, read independently
    assert rows2["carbon"]["value"] == VirtualLedger(_vsb).trial_balance()["postings"], rows2["carbon"]

    # ── L3. NO SECOND STORE OF NUMBERS: a full read writes nothing ────────────────────────────────
    #  (a) THE PROPERTY, ON THE AST: neither module may resolve a store path, write one, or open a file.
    #  This is the primary instrument, because it holds whatever order a caller reads in.
    for _mod in ("agentic_core/api/cycles.py", "agentic_core/biomimicry/cycles/bindings.py"):
        _mt = ast.parse((_root / _mod).read_text(encoding="utf-8"))
        _names = {ast.unparse(n.func).split(".")[-1] for n in ast.walk(_mt) if isinstance(n, ast.Call)}
        for _forbidden in ("data_path", "atomic_write_json", "open"):
            assert _forbidden not in _names, (
                f"{_mod} calls {_forbidden}; this surface reads figures from the modules that own them "
                f"and keeps no copy, which is what 'no second store of numbers' means")
    #  (b) AND THE BEHAVIOUR, bracketed from before the first read in this test
    _files_after = sorted(q.name for q in _ddir.iterdir()) if _ddir.is_dir() else None
    assert _files_after == _files_before_any_read, (
        "reading the cycles created or removed a store file",
        set(_files_after or []) ^ set(_files_before_any_read or []))

    # ── L4. NO DEVIATION ANYWHERE, AND EVERY SETPOINT IS AN ASPIRATION ────────────────────────────
    #  The first draft of this surface computed a deviation for the three BOUND cycles and reported 11.0
    #  for water: 900 virtual WST against a setpoint of 75.0, which water_cycle treats as a temperature.
    #  Real arithmetic over incommensurable units is this item's defect one level in.
    for _n, c in rows2.items():
        assert c["setpoint_is_aspiration"] is True, (_n, "a setpoint with no unit is presented as a target", c)
        assert "deviation" not in c, (_n, "a deviation was computed across units", c)
        #  W544 — THIS ASSERTED ONE WORDING AND W544 MADE THE REFUSAL COMPUTED. The original pinned the
        #  phrase "NO UNIT", which was true while the surface withheld every deviation under a blanket
        #  rule; now that it compares the two units, water's refusal correctly says something else
        #  entirely (its setpoint declares degrees, its binding measures virtual WST). The property is
        #  that the refusal is PRESENT AND REASONED, not that it uses a particular sentence — pinning a
        #  spelling is what cost two full suites earlier in this programme.
        assert c["deviation_basis"].startswith("NOT COMPUTED:"), (_n, c["deviation_basis"])
        assert len(c["deviation_basis"]) > 60, (_n, "a refusal with no reason", c["deviation_basis"])
        assert "ASPIRATION" in c["setpoint_basis"] or "COMPARABLE" in c["setpoint_basis"], (
            _n, c["setpoint_basis"])

    # ── L5. A GAIN IS A DEFAULT UNTIL TUNED, AND THE RECORD SAYS SO ───────────────────────────────
    for _n, c in rows2.items():
        assert c["gains_tuned"] is False, (_n, "a gain claims to be tuned; nothing has tuned one", c)
        assert (c["gains_basis"] or "").strip(), (_n, "gains with no provenance")
    from agentic_core.biomimicry.cycles.base_cycle import PIDController
    assert PIDController(setpoint=1.0, kp=1.0, ki=0.0, kd=0.0).gains_tuned is False, (
        "the controller's default claims tuning")

    # ── L6a. THE FABRIC'S HEALTH IS MEASURED OR WITHHELD — IT DOES NOT VARY BY ITSELF ─────────────
    from agentic_core.biomimicry.geospheric.drad import DynamicReactiveAdaptiveFabric
    _f = DynamicReactiveAdaptiveFabric()
    h1 = _f.get_fabric_health()
    h2 = _f.get_fabric_health()
    #  TWO IDENTICAL CALLS AGREED ON NOTHING BEFORE THIS. The score was drawn from a generator over
    #  0.9-1.0 and the uptime from one over an hour to a day, so each call invented a new plausible past.
    assert h1["current_health_score"] == h2["current_health_score"], (h1, h2)
    assert h1["current_health_score"] is None, ("a health score with no telemetry", h1)
    assert h1["telemetry_received"] is False, h1
    assert "NOT ASSESSED" in h1["health_basis"], h1["health_basis"]
    #  the uptime is real elapsed time, so two calls differ by about nothing rather than by hours
    assert abs(h2["process_uptime_seconds"] - h1["process_uptime_seconds"]) < 5.0, (h1, h2)
    #  and a reported error rate DOES produce a score — the refusal is not the only state
    _f.monitor({"error_rate": 0.02})
    h3 = _f.get_fabric_health()
    assert h3["current_health_score"] == 0.98, h3
    assert h3["telemetry_received"] is True, h3
    #  an unmeasured fabric is neither nominal nor critical
    assert DynamicReactiveAdaptiveFabric().monitor({})["status"] == "NOT_ASSESSED", "an unmeasured fabric cleared"
    assert _f.monitor({"error_rate": 0.9})["status"] == "CRITICAL", "a breached fabric did not report"

    # ── L6b. NO GENERATOR CALL REMAINS, ASSERTED ON THE AST ──────────────────────────────────────
    #  On the AST because this module's own comments quote the calls they describe, and a text search
    #  would match the explanation rather than any code.
    _tree = ast.parse((_root / "agentic_core/biomimicry/geospheric/drad.py").read_text(encoding="utf-8"))
    _calls = [ast.unparse(n.func) for n in ast.walk(_tree) if isinstance(n, ast.Call)]
    assert not [c for c in _calls if c.split(".")[0] == "random"], (
        "a generator call is back in the fabric's health", [c for c in _calls if "random" in c])

    # ── L7. THE HOMEOSTASIS GATE CAN REACH ALL THREE OUTCOMES ────────────────────────────────────
    from agentic_core.biomimicry.geospheric.orchestrator_legacy import GeosphericHomeostaticOrchestrator
    _o = GeosphericHomeostaticOrchestrator(ueg_logger=False)
    _none = _aio.run(_o.step({}, {}))
    assert _none["status"] == "NOT_ASSESSED", ("a gate with no input cleared", _none)
    assert _none["psi_score"] is None, ("a psi nothing computed", _none)
    assert "NOT COMPUTED" in _none["psi_basis"], _none["psi_basis"]
    assert _none["cycles_consulted"] == [], _none
    assert _aio.run(_o.step({"drift": 0.01}, {}))["status"] == "NOMINAL", "a measured pass did not pass"
    assert _aio.run(_o.step({"drift": 0.2}, {}))["status"] == "CONSTITUTIONAL_VIOLATION", "a breach cleared"

    # ── L7b. THE READER WAS FIXED WITH ITS WRITER — no default of a perfect psi ───────────────────
    #  Removing the fabricated 0.95 alone would have UPGRADED the lie: the consumer read the key with a
    #  default of 1.0, so an absent psi would have been logged as perfect. Asserted on the AST: the
    #  .get() call for that key must take exactly one argument.
    _u = ast.parse((_root / "agentic_core/governance/uci_interceptor.py").read_text(encoding="utf-8"))
    _psi_gets = [n for n in ast.walk(_u)
                 if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute)
                 and n.func.attr == "get" and n.args
                 and isinstance(n.args[0], ast.Constant) and n.args[0].value == "psi_score"]
    assert _psi_gets, "the interceptor no longer reads the homeostasis figure at all"
    for _g in _psi_gets:
        assert len(_g.args) == 1, (
            f"uci_interceptor.py:{_g.lineno} defaults the psi it reads, so an absent figure is logged as "
            f"a present one", ast.unparse(_g))

    # ── L8. A RESERVOIR LITERAL YIELDS NO READING AND NO VERDICT ─────────────────────────────────
    from agentic_core.biomimicry.cycles.carbon_cycle import DataCarbonCycle
    from agentic_core.biomimicry.cycles.nitrogen_cycle import NitrogenFixationDaemon
    from agentic_core.biomimicry.cycles.oxygen_cycle import MetabolicScheduler
    from agentic_core.biomimicry.cycles.phosphorus_cycle import PhosphorusMemoryManager
    from agentic_core.biomimicry.cycles.sulfur_cycle import SulfurErrorManager
    for _cls in (DataCarbonCycle, NitrogenFixationDaemon, MetabolicScheduler,
                 PhosphorusMemoryManager, SulfurErrorManager):
        _c = _cls(None, None, None)
        _s = _aio.run(_c.sense())
        assert _s["assessable"] is False, (_cls.__name__, "a literal was reported as a reading", _s)
        assert _s["homeostatic"] is None, (_cls.__name__, "a verdict over an unmeasured quantity", _s)
        assert "metric" in _s and "value" not in _s, (_cls.__name__, _s)
        assert "literal set in __init__" in _s["basis"], (_cls.__name__, _s["basis"])
        #  and the three-state reaches the regulator: no correction is computed from nothing
        _reg = _aio.run(_c.regulate())
        assert _reg["status"] == "not_assessable", (_cls.__name__, "regulated from a literal", _reg)
        assert _reg["correction_applied"] is None, (_cls.__name__, _reg)
        #  THE REFUSAL AND THE SUCCESS CARRY THE SAME KEYS, so a reader of `basis` is never undefined
        _ok = _aio.run(_c._regulate_with_val(42.0))
        assert sorted(_reg) == sorted(_ok), (_cls.__name__, sorted(_reg), sorted(_ok))
        #  L9. AND THE CONTROLLER STILL WORKS for a caller that measured something — the point of the
        #  round is to stop inventing the input, not to disable the control loop.
        assert isinstance(_ok["correction_applied"], float), (_cls.__name__, _ok)
        assert _c.deviation(42.0) is not None and _c.is_homeostatic(42.0) in (True, False), _cls.__name__
        assert _c.deviation(None) is None and _c.is_homeostatic(None) is None, (
            _cls.__name__, "the third state is unreachable")

    # ── L10. THE CLASS'S OWN READING IS ON THE SURFACE, for all six ──────────────────────────────
    for _n, c in rows2.items():
        _ds = c["declared_sense"]
        assert isinstance(_ds, dict), (_n, "the cycle's own reading is absent from the surface", _ds)
        assert _ds["assessable"] is False and _ds["homeostatic"] is None, (_n, _ds)
        assert (_ds["basis"] or "").strip(), (_n, "a refusal with no reason")
    #  and the coupling matrix is withheld while cycles are unbound, with the reason
    assert j2["coupling_matrix"] is None, j2["coupling_matrix"]
    assert "NOT REPORTED" in j2["coupling_basis"] and str(j2["bound"]) in j2["coupling_basis"], j2
    assert j2["bound"] == 3 and j2["total"] == 6, (j2["bound"], j2["total"])


def test_w543_a_fresh_backend_also_refuses_to_bind_what_nothing_measures(tmp_path):
    """The fresh-backend probe P3.19's bar names: a NEW interpreter, on a store nothing has touched.

    The suite seeds ledgers and runs a heartbeat, so an in-process reading can be true of this run
    rather than of the code. This starts a separate Python on an empty DATA_DIR and asserts the shape
    holds there: three cycles refuse by name, the bound ones carry their reader, and no reservoir
    literal becomes a verdict.
    """
    import json
    import subprocess
    import sys
    from pathlib import Path as _P

    root = _P(__file__).resolve().parents[1]
    script = tmp_path / "probe.py"
    script.write_text(
        "import sys, os\n"
        "sys.path.insert(0, os.environ['WS_ROOT'])\n"
        "import agentic_core as _ac\n"
        "assert _ac.__file__ and os.path.realpath(_ac.__file__).startswith("
        "       os.path.realpath(os.environ['WS_ROOT'])), ('wrong agentic_core', _ac.__file__)\n"
        "import asyncio, json\n"
        "from agentic_core.biomimicry.cycles import bindings\n"
        "from agentic_core.biomimicry.cycles.carbon_cycle import DataCarbonCycle\n"
        "b = bindings.read_all()\n"
        "s = asyncio.run(DataCarbonCycle(None, None, None).sense())\n"
        "print(json.dumps({\n"
        "    'unbound': sorted(k for k, v in b.items() if not v['assessable']),\n"
        "    'bound': sorted(k for k, v in b.items() if v['assessable']),\n"
        "    'value_on_refusal': any('value' in v for v in b.values() if not v['assessable']),\n"
        "    'every_refusal_names_a_reader': all('reader consulted' in v['basis']\n"
        "                                        for v in b.values() if not v['assessable']),\n"
        "    'sense_assessable': s['assessable'], 'sense_homeostatic': s['homeostatic'],\n"
        "    'bound_carry_reader': all(v['measured_from'] for v in b.values() if v['assessable']),\n"
        "}))\n",
        encoding="utf-8")
    d = tmp_path / "fresh"
    env = {**__import__("os").environ, "DATA_DIR": str(d), "WORKSTATION_DATA_DIR": str(d),
           "WORKSTATION_UEG_PATH": str(d / "ueg.json"), "PROJECTS_DIR": str(d / "projects"),
           "AI_DISABLE_LOCAL": "1", "WS_ROOT": str(root), "PYTHONPATH": str(root)}
    r = subprocess.run([sys.executable, str(script)], capture_output=True, text=True,
                       cwd=str(root), env=env)
    assert r.returncode == 0, ("the fresh backend could not read the cycle bindings", r.stderr[-700:])
    out = json.loads([ln for ln in r.stdout.splitlines() if ln.startswith("{")][-1])
    #  with no VSB named, only the organism's own beat count is readable
    assert out["bound"] == ["oxygen"], out
    assert out["unbound"] == ["carbon", "nitrogen", "phosphorus", "sulfur", "water"], out
    assert out["value_on_refusal"] is False, ("a refusal carried a figure in a fresh interpreter", out)
    assert out["every_refusal_names_a_reader"] is True, out
    assert out["bound_carry_reader"] is True, out
    #  and the reservoir literal is still not a reading, in a process that has imported nothing else
    assert out["sense_assessable"] is False and out["sense_homeostatic"] is None, out


def test_w544_the_sixth_cycle_joins_the_other_five_and_the_archive_record_is_complete(client):
    """P3.19 Round 2: water stops being the outlier, and FU-243's record is checked rather than read.

    Two legs here are completeness checks over a DOCUMENT, which is unusual and deliberate: FU-243's
    deliverable IS a record, so the only way it can fail is by omitting a module or by claiming a
    recovery that did not happen. Both are computed from the archive directory and the live tree rather
    than taken from the prose.
    """
    import ast
    import asyncio as _aio
    import pathlib
    import re

    _root = pathlib.Path(__file__).resolve().parents[1]

    # ── L1. THE COMPARABILITY RULE REACHES ALL FIVE OUTCOMES, including the one the route cannot ──
    #  No cycle satisfies the comparable case today, so the branch that reports a deviation is
    #  unreachable through the route. An unreachable branch is code nobody has run, which is why the
    #  decision is a function the surface calls and this leg drives directly.
    from agentic_core.api.cycles import comparability
    _cases = [
        ((False, None, None), False, "nothing measures"),
        ((True, None, "virtual WST"), False, "NO UNIT for its setpoint"),
        ((True, "degrees", None), False, "reports no unit"),
        ((True, "degrees", "virtual WST"), False, "incommensurable units"),
        ((True, "virtual WST", "virtual WST"), True, ""),
    ]
    for _args, _want, _needle in _cases:
        _ok, _why = comparability(*_args)
        assert _ok is _want, (_args, "the comparability rule disagrees", _ok, _why)
        if _want:
            assert _why == "", (_args, "a comparable pair carries a refusal reason", _why)
        else:
            assert _needle in _why, (_args, _needle, _why)

    # ── L2. WATER IS ONE OF THE FIVE NOW: shared base class, shared controller, a sense() ─────────
    from agentic_core.biomimicry.cycles import base_cycle as _bc
    from agentic_core.biomimicry.cycles.water_cycle import HydrologicManager
    assert issubclass(HydrologicManager, _bc.GeosphericCycle), (
        "water still extends nothing, so it inherits none of the three-state work")
    _w = HydrologicManager(None, None, None)
    assert type(_w.pid) is _bc.PIDController, (
        "water uses a controller that is not the shared one", type(_w.pid))
    #  NO SECOND CONTROLLER IN THAT MODULE, asserted on the AST: a class definition, not a mention. The
    #  module's own docstring describes the duplicate it removed, so a text search would match that.
    _wt = ast.parse((_root / "agentic_core/biomimicry/cycles/water_cycle.py").read_text(encoding="utf-8"))
    _classes = [n.name for n in ast.walk(_wt) if isinstance(n, ast.ClassDef)]
    assert "PIDController" not in _classes, (
        "water_cycle declares its own controller again; a second copy of control logic is a second place "
        "it can drift", _classes)
    assert _w.pid.gains_tuned is False and (_w.pid.gains_basis or "").strip(), (
        "water's gains carry no provenance, which is what extending the shared controller is for")

    # ── L3. ITS SETPOINT DECLARES A UNIT, AND THE SURFACE REFUSES BY NAMING BOTH ─────────────────
    from agentic_core.economy.ledger import VirtualLedger
    _vsb = "vsb-w544-guard"
    VirtualLedger(_vsb).record("reserves", 512.0, memo="w544 guard", kind="credit")
    j = client.get("/api/v1/cycles", params={"vsb_id": _vsb}).json()
    rows = {c["name"]: c for c in j["cycles"]}
    _wr = rows["water"]
    assert _wr["assessable"] is True, _wr
    assert _wr["setpoint_unit"], ("water's setpoint declares no unit, so its refusal is a rule rather "
                                  "than a measurement", _wr)
    assert _wr["measured_unit"], _wr
    assert _wr["setpoint_unit"] != _wr["measured_unit"], _wr
    #  the refusal NAMES BOTH SIDES, so a reader can see why rather than being told no
    assert _wr["setpoint_unit"] in _wr["deviation_basis"], _wr["deviation_basis"]
    assert _wr["measured_unit"] in _wr["deviation_basis"], _wr["deviation_basis"]
    assert "deviation" not in _wr, ("a deviation across units came back", _wr)
    #  and the cycles whose setpoint states no unit refuse for THAT reason, not water's
    assert "NO UNIT for its setpoint" in rows["carbon"]["deviation_basis"], rows["carbon"]["deviation_basis"]

    # ── L4. WATER'S THREE STATES, driven ──────────────────────────────────────────────────────────
    _s = _aio.run(_w.sense())
    assert _s["assessable"] is False and _s["homeostatic"] is None, ("water reports a reading", _s)
    assert "literal set in __init__" in _s["basis"], _s["basis"]
    _r = _aio.run(_w.regulate())
    assert _r["correction"] is None and "NOT REGULATED" in _r["basis"], _r
    #  the measured path works and is three-state, like the other five
    _m = _aio.run(_w.regulate_homeostasis(78.0))
    assert isinstance(_m["correction"], float) and _m["status"] in ("within_tolerance", "deviation"), _m
    assert _w.setpoint_unit in _m["basis"], _m["basis"]
    _n = _aio.run(_w.regulate_homeostasis(None))
    assert _n["correction"] is None and _n["status"] == "not_assessable", _n

    # ── L5. THE METAPHOR'S LITERALS TRAVEL WITH THEIR FIGURES ────────────────────────────────────
    _e = _aio.run(_w.evaporate(40.0))
    assert isinstance(_e, dict), ("evaporate returns a bare number again, so an untuned literal is "
                                  "applied to it invisibly", _e)
    assert _e["efficiency_applied"] == 0.85 and "DECLARED, NOT MEASURED" in _e["basis"], _e
    assert _e["returned"] == 40.0 * 0.85, _e
    _c = _aio.run(_w.condense())
    assert isinstance(_c, dict) and "DECLARED, NOT MEASURED" in _c["basis"], _c

    # ── L6. THE ARCHIVE RECORD COVERS EVERY ARCHIVED MODULE — computed, not claimed ──────────────
    _arch = _root / "_archive/jules-unwired/agentic_core/biomimicry"
    _modules = sorted(q.stem for q in _arch.glob("*.py") if q.stem != "__init__")
    assert len(_modules) >= 7, ("the archive is smaller than the row describes", _modules)
    _doc = (_root / "docs/BIOGEOCHEMICAL_AND_COMMS_REVIEW.md").read_text(encoding="utf-8")
    #  ANCHORED ON ITS OWN HEADING, not on a phrase a later heading may share. It was
    #  `split("read and decided")[-1]`, and when W563 added "## The other twenty-three, read and decided"
    #  this leg silently began reading THAT section instead — a guard stolen by the section it was meant
    #  to outlive. The slice runs to the end of the file on purpose: the archive record is now two
    #  sections, and "every archived module is decided or named" is a property of the record, not of one
    #  part of it.
    _section = _doc[_doc.index("## The archived biomimetic layer, read and decided"):]
    #  AND THE SELF-CONSISTENCY SCAN BELOW USES A NARROWER SLICE THAN THE COMPLETENESS LEG. Running to
    #  end-of-file is right for "every archived module is decided or named" — that is a property of the
    #  whole record. It is WRONG for the count scan, whose allowed set is THIS section's coverage
    #  figures: the W563 section legitimately states 15, 8, 14, 9, 18 and 6 about these modules, and one
    #  true sentence putting any of them beside the word "modules" would make a guard about honesty
    #  raise a false accusation. It did: three sentences in W563's own corrections tripped it. W563's
    #  leg computes that section's tallies from its own table, which is the stronger check anyway.
    _scan = _doc[_doc.index("## The archived biomimetic layer, read and decided")
                 :_doc.index("## The other twenty-three, read and decided")]
    #  (a) THE RECORD MUST STATE THE TRUE TOTAL. This is the leg that earned its place: the first draft of
    #  that section said the archive held ten modules, because the directory listing it was written from
    #  was truncated. There are 33. A record that covers ten of them while reading as a survey of the
    #  layer is a precise-looking account of work that was not done — which is what the table convicts one
    #  of the modules of. The number is computed here, so the prose cannot drift from the directory.
    assert str(len(_modules)) in _scan, (
        f"the record does not state the archive's real module count ({len(_modules)}), so a reader cannot "
        f"tell how much of the layer it covers")
    #  AND NO OTHER COUNT CLAIM MAY CONTRADICT IT. Asserting only that the true figure APPEARS is weak:
    #  a sweep proved it, by adding "(ten of them)" beside the correct 33 and watching this leg pass. So
    #  every count the record states about these modules is collected and checked against the figures the
    #  record is entitled to quote — the real total, the ten it assesses, the twenty-three it names and
    #  the seven the row named. A document that contradicts itself about how much it covers is exactly
    #  the defect its own table convicts one of these modules of.
    #  THE WORD MAP IS GENERATED, not listed. It was listed and it stopped at thirteen before jumping to
    #  twenty-three, so "over fourteen modules" was INVISIBLE to this scan — a blind driven in W563 came
    #  back VACUOUS and the gap was in the map, not the mutation. A word list that silently fails to
    #  recognise its subject does not flag and does not clear; it says nothing, which reads as consent.
    #  Generated over the whole range this record could claim, and the coverage is asserted below.
    _UNITS = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
              "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen",
              "eighteen", "nineteen"]
    _WORDS = {_w: _i for _i, _w in enumerate(_UNITS) if _w}
    for _tens, _base in (("twenty", 20), ("thirty", 30)):
        _WORDS[_tens] = _base
        for _i in range(1, 10):
            _WORDS[f"{_tens}-{_UNITS[_i]}"] = _base + _i
    assert all(_n in _WORDS.values() for _n in range(1, 34)), (
        "the word map no longer covers every count this record could state, so a spelled-out figure "
        "could pass unread")
    _allowed = {len(_modules), 10, len(_modules) - 10, 7, 4}
    _claims = []
    for _m in re.finditer(r"\b([\w-]+)\b[\s*]*(?:of them|modules?\b|top-level)", _scan, re.I):
        _tok = _m.group(1).lower()
        _n = _WORDS.get(_tok, int(_tok) if _tok.isdigit() else None)
        if _n is not None:
            _claims.append((_n, " ".join(_scan[max(0, _m.start() - 30):_m.end()].split())))
    _bad = [c for c in _claims if c[0] not in _allowed]
    assert not _bad, (
        f"the record states a module count that is none of its entitled figures {sorted(_allowed)}; a "
        f"survey that contradicts itself about its own coverage reads as complete while it is not",
        _bad[:3])
    assert _claims, "no count claim was found at all, so this consistency check could not fail"
    #  (b) EVERY MODULE IN THE RECORD'S DECLARED SCOPE IS DECIDED, and every module outside it is NAMED.
    _every = [m for m in _modules if m in _section]
    assert len(_every) == len(_modules), (
        "the record neither decides nor names archived module(s), so the gap is invisible",
        [m for m in _modules if m not in _section])
    #  every row reaches a VERDICT — a reading with no decision is not a decision
    _table = [ln for ln in _section.splitlines() if ln.startswith("| `")]
    assert len(_table) >= 10, ("the record's table is shorter than its stated scope", len(_table))
    #  The closed set grew when W563 decided the other twenty-three: those rows carry a verdict AND a
    #  disposition, so RETIRE / WANTED_REBUILD / NOT_WANTED are decisions here too. The leg still refuses
    #  a row that reads a module and decides nothing.
    for _row in _table:
        assert re.search(r"RECOVERABLE|SUPERSEDED|DO NOT RECOVER|NEEDS AN EVENT SOURCE"
                         r"|RETIRE|WANTED_REBUILD|NOT_WANTED", _row), (
            "the record reads a module without deciding it", _row[:160])

    # ── L7. AND THE "NOT RECOVERED" CLAIM IS TRUE: no live module imports the archive at all ────
    #  The first version of this leg collected importers and then filtered them for "_archive" in the
    #  IMPORTING file's path — which is never true, since every live file is under agentic_core. It could
    #  not fail. The property that matters is the opposite direction: no live module may import FROM the
    #  archive, which is a statement about the imported module name and is read off the AST.
    _archive_importers = []
    for _f in (_root / "agentic_core").rglob("*.py"):
        try:
            _ft = ast.parse(_f.read_text(encoding="utf-8", errors="replace"))
        except SyntaxError:
            continue
        for _n in ast.walk(_ft):
            _mods = []
            if isinstance(_n, ast.Import):
                _mods = [a.name for a in _n.names]
            elif isinstance(_n, ast.ImportFrom):
                _mods = [_n.module or ""]
            for _m in _mods:
                if "_archive" in _m:
                    _archive_importers.append(f"{_f.relative_to(_root)}:{_n.lineno} -> {_m}")
    assert not _archive_importers, (
        "live code imports the archive, so a module this record calls 'not recovered' is in fact running",
        _archive_importers[:5])
    #  and the archived modules are genuinely still only in the archive
    for _m_name in _modules:
        assert not (_root / "agentic_core" / "biomimicry" / f"{_m_name}.py").exists(), (
            f"{_m_name}.py now exists in the live tree, so the record's verdict for it is out of date")


def test_w545_a_withheld_emission_is_visible_and_a_simulator_discloses_itself(client):
    """P3.16 (FU-344) and FU-347: the platform's normal state reaches a surface, and two simulators stop
    returning records that claim more than they did.

    The heartbeat is a SINGLETON the route holds, so the lever is driven on the same instance the surface
    reads and restored in a finally — a reload would split them and the route would answer from a
    different object than the one the test configured.
    """
    import ast
    import asyncio as _aio
    import pathlib
    from decimal import Decimal

    _root = pathlib.Path(__file__).resolve().parents[1]

    # ── L1. NOT-RUN AND WITHHELD ARE DIFFERENT STATES, and both reach the route ───────────────────
    #  W549 — THE ROUTE'S OWN REFERENCE, not the module's. This guard took
    #  `from agentic_core.organism.heartbeat import heartbeat`, and an earlier test in this file calls
    #  importlib.reload on that module, which re-runs `heartbeat = OrganismHeartbeat()` and rebinds the
    #  module attribute to a NEW object while agentic_core/api/heartbeat.py still holds the one it bound
    #  at import. From then on the two are different heartbeats, so this guard configured one and
    #  asserted about another: `last_metabolic` was set on the object and None in the payload.
    #  IT PASSED ALONE AND IN FOUR CONSECUTIVE FULL RUNS, because xdist distributes dynamically and
    #  happened to put the two tests on different workers — an ORDER-DEPENDENT flake, latent since W545.
    #  The same trap and the same remedy are documented against test_w503 in this file; taking the
    #  route's reference is also the truer form of the claim, since what is under test is a field
    #  REACHING A SURFACE.
    #  W579 (FU-359) — and the remedy above is no longer needed: the routes now resolve `.heartbeat`
    #  from the module on every call, so there is no second object to take. Measured before the change
    #  (the two references differed after a reload and a flag set on the module reported False through
    #  /status) and after (they agree). The module attribute is the surface's own reference now.
    import agentic_core.organism.heartbeat as _hbmod545
    _hb = _hbmod545.heartbeat
    _s0 = client.get("/api/v1/heartbeat/status")
    assert _s0.status_code == 200, _s0.status_code
    _j0 = _s0.json()
    assert "last_metabolic" in _j0, ("the beat's metabolic outcome reaches no route, so a full cycle that "
                                     "delivered nothing is invisible to every surface")
    assert "metabolic_basis" in _j0 and (_j0["metabolic_basis"] or "").strip(), _j0.get("metabolic_basis")

    _saved = (_hb.auto_metabolic, _hb._metabolic_every, _hb._beats_since_metabolic, _hb.last_metabolic)
    try:
        _hb.auto_metabolic = True
        _hb._metabolic_every = 1
        _hb._beats_since_metabolic = 0
        assert client.post("/api/v1/heartbeat/beat").status_code == 200
        _m = client.get("/api/v1/heartbeat/status").json()["last_metabolic"]
    finally:
        (_hb.auto_metabolic, _hb._metabolic_every, _hb._beats_since_metabolic,
         _hb.last_metabolic) = _saved

    assert isinstance(_m, dict), ("a beat ran the cycle and the route reported nothing about it", _m)
    assert _m.get("stages_measured", 0) >= 1, ("no stage was measured, so this is not a clean run", _m)
    #  THE OUTCOME IS REPORTED SEPARATELY FROM THE MEASUREMENT. Six measured stages and an empty mouth
    #  is this platform's normal state, and the two facts must not be collapsed into one.
    assert "cycle_status" in _m and "emitted" in _m, _m
    assert _m["emitted"] is not True or _m["cycle_status"] == "SUCCESS", (
        "the route claims an emission was delivered without the cycle reporting success", _m)
    if _m["cycle_status"] == "WITHHELD":
        assert _m["emitted"] is False, ("a withheld cycle reported an emission", _m)
        assert (_m.get("withheld_reason") or "").strip(), (
            "a withheld emission carries no reason, so a reader cannot tell why nothing arrived", _m)
        assert "WITHHELD" in (_m.get("basis") or ""), _m.get("basis")

    # ── L2. AND THE PAGE SHOWS IT — on the page that owns the heartbeat ───────────────────────────
    def _uncommented(text: str, needle: str) -> list:
        return [ln for ln in text.splitlines()
                if needle in ln and not ln.strip().startswith(("//", "{/*", "/*", "*", "{ /*"))]

    _page = (_root / "apps/workstation-superapp/src/pages/organism/HeartbeatMonitor.tsx").read_text(
        encoding="utf-8")
    #  ACTIVE lines, not merely present ones: a commented-out branch still contains its own field names,
    #  which is how a presence check passes on a page that renders none of it.
    assert _uncommented(_page, "last_metabolic"), "the heartbeat page reads nothing about the cycle"
    assert _uncommented(_page, "emitted === false"), (
        "the page does not distinguish a withheld emission; `emitted` is three-state and a page that "
        "tests it for truthiness alone cannot tell 'withheld' from 'not reported'")
    assert _uncommented(_page, "withheld_reason"), "the page shows a withheld cycle without its reason"
    #  the outcome must not be DERIVED from the measurement: no branch may compute a delivery from the
    #  stage count or the breach count, which is precisely the inference this row exists to stop.
    #  UNCOMMENTED LINES ONLY, for two reasons: a comment announces nothing to a user, and this round's
    #  own card comment explains the delivery/withholding distinction in those words — so a scan over
    #  every line matches the explanation and reds on correct code. That is the eighth time in this
    #  programme that a comment has tripped a screen written against its own subject.
    #  AND THE ASSOCIATION IS STRUCTURAL, not per-line. In JSX the gate and the text it renders are on
    #  DIFFERENT lines, so asking whether the line saying "DELIVERED" also mentions the flag is the wrong
    #  granularity — it reds on correct code and would pass a delivery announced three lines under a
    #  gate on something else entirely. Each active line announcing a delivery must sit within a few
    #  lines BELOW an `emitted === true` gate, which is what being inside that branch's body means.
    _lines = _page.splitlines()
    _gates = [i for i, ln in enumerate(_lines) if "emitted === true" in ln
              and not ln.strip().startswith(("//", "{/*", "/*", "*"))]
    assert _gates, "no branch on a delivered emission exists at all"
    for _i, _ln in enumerate(_lines):
        if "DELIVERED" not in _ln or _ln.strip().startswith(("//", "{/*", "/*", "*")):
            continue
        assert any(0 <= _i - _g <= 4 for _g in _gates), (
            "the page announces a delivery outside the branch gated on the emitted flag, so it can print "
            "it for a cycle that delivered nothing", _i + 1, _ln.strip())

    # ── L3. THE SETTLEMENT RECEIPT DISCLOSES ITSELF, where the disclosure was missing ─────────────
    #  The UEG payload has always carried is_simulated; the RETURNED receipt said FINALIZED, named a
    #  post-quantum algorithm and reported a finality, with nothing marked simulated. The disclosure sat
    #  exactly where no consumer looks.
    import sys as _sys
    if str(_root) not in _sys.path:
        _sys.path.insert(0, str(_root))
    from agentic_core.ueg.logger import VSBUEGLogger as _VSBUEG
    from products.capital_fund.adapters.qan_bridge import QANBridgeSimulator
    _r = _aio.run(QANBridgeSimulator(_VSBUEG()).settle_cross_node(Decimal("100"), "node-a", "did:t"))
    assert _r["simulated"] is True, ("the receipt a caller receives does not say it is simulated", _r)
    assert "FINAL" not in _r["status"].upper(), (
        "the receipt still claims settlement finality for a local dict entry", _r["status"])
    assert _r["pqc_implemented"] is False, _r
    assert "NOT IMPLEMENTED" in _r["pqc_basis"], _r["pqc_basis"]
    #  the algorithm name may be KEPT — it records what this bridge is specified against — but it must
    #  not be returned under a field a consumer reads as a performed primitive
    assert "pqc_algorithm" not in _r, (
        "the bare algorithm field is back; a consumer reading it sees a named primitive and nothing to "
        "say no code implements it", sorted(_r))
    assert "DECLARED, NOT MEASURED" in _r["finality_basis"], _r["finality_basis"]

    # ── L4. AND THE TREATY RECORD, PLUS THE GATE THAT READS IT ───────────────────────────────────
    from products.capital_fund.mesh.federation_manager import FederationManager
    _fm = FederationManager("fund-w545")
    _aio.run(_fm.sign_treaty("peer-1", {"terms": "x"}))
    _t = _fm.active_treaties["peer-1"]
    assert _t["status"] != "ACTIVE", ("a treaty nothing signed is recorded as active", _t["status"])
    assert _t["signature"] is None and "NOT SIGNED" in _t["signature_basis"], _t
    _dep = _aio.run(_fm.contribute_to_shared_pool("peer-1", Decimal("50")))
    #  the contribution carries the treaty's real state, because this record GATES a capital path
    assert _dep["simulated"] is True and _dep["treaty_status"] == _t["status"], _dep
    assert "NOT A PROOF" in _dep["zk_proof_basis"], _dep["zk_proof_basis"]
    #  THE READER WAS FIXED WITH THE WRITER: the gate admits a recorded treaty, so its refusal must not
    #  tell a caller that passing it meant an agreement existed.
    try:
        _aio.run(_fm.contribute_to_shared_pool("nobody", Decimal("1")))
        raise AssertionError("the gate admitted a peer with no treaty at all")
    except ValueError as _e:
        assert "active" not in str(_e).lower(), (
            "the gate still claims it required an active treaty; what it admits is one that was merely "
            "recorded", str(_e))

    # ── L5. NO SECOND USER OF THE RENAMED VALUE, asserted on the AST ─────────────────────────────
    #  A rename that fixes one user and leaves another raises NameError at call time on a path no test
    #  reaches. Both the returned record and the ledger payload had to change together.
    _ft = ast.parse((_root / "products/capital_fund/mesh/federation_manager.py").read_text(
        encoding="utf-8"))
    _bare = [n.id for n in ast.walk(_ft) if isinstance(n, ast.Name) and n.id == "zk_proof"]
    assert not _bare, ("a bare reference to the renamed value survives, so one caller raises NameError "
                       "while the other reads the new field", len(_bare))


def test_w546_the_thermodynamic_ledger_meters_what_a_stage_handled_and_reports_a_floor(client):
    """P3.17 (FU-234, FU-329): the six invented bit counts become measured payloads, and the ledger stops
    calling a thermodynamic floor an energy.

    The bit counts are checked by RECOMPUTING them in the test from the payload each stage received, so a
    plausible constant cannot pass for a measurement. The Landauer figure is checked against k_B·T·ln2
    computed here, so the ledger cannot drift from the physics it claims.
    """
    import ast
    import asyncio as _aio
    import json
    import math

    # ── L1. EVERY STAGE METERS A MEASURED PAYLOAD, AND NONE OF THE SIX LITERALS SURVIVES ─────────
    from agentic_core.avatars.core.avatar_engine import AvatarState
    from agentic_core.avatars.core.recirculation_orchestrator import (
        AvatarRecirculationOrchestrator, _payload_bits)
    from agentic_core.ueg.logger import VSBUEGLogger as _VSBUEG

    _o = AvatarRecirculationOrchestrator(_VSBUEG(), AvatarState(avatar_id="w546", user_id="w546"))
    _seen = []
    _real_meter = _o.tfel.meter_operation

    def _spy(name, bits, bits_basis=""):
        _seen.append({"op": name, "bits": bits, "basis": bits_basis})
        return _real_meter(name, bits, bits_basis)

    _o.tfel.meter_operation = _spy
    _ctx = _aio.run(_o.execute_cycle({"user_id": "w546", "domain": "w546_guard"}))
    assert len(_seen) == 6, ("the six stages did not each meter their cost", [s["op"] for s in _seen])

    #  THE SIX LITERALS THIS ROUND REMOVED. Each was recorded BEFORE its stage did any work, so it could
    #  not have described what the stage processed even in principle.
    _INVENTED = {"metabolic_sense": 1e4, "metabolic_intend": 5e4, "metabolic_analyze": 5e5,
                 "metabolic_act": 2e5, "metabolic_learn": 5e4, "metabolic_reflect": 1e5}
    for _s in _seen:
        assert _s["bits"] is not None, (_s["op"], "a stage metered nothing at all", _s)
        assert _s["bits"] != _INVENTED[_s["op"]], (
            _s["op"], "the invented bit count is back", _s["bits"])
        assert "MEASURED" in (_s["basis"] or ""), (_s["op"], "a bit count with no account of its origin",
                                                   _s["basis"])
        #  and the figure is a real size: a multiple of 8, because it counts bytes
        assert float(_s["bits"]) > 0 and float(_s["bits"]) % 8 == 0, (_s["op"], _s["bits"])
    #  the measured total is far below the invented one, which is the substance of the correction
    assert sum(s["bits"] for s in _seen) < sum(_INVENTED.values()) / 2, (
        "the measured total is close to the invented one, which suggests it is not measured",
        sum(s["bits"] for s in _seen), sum(_INVENTED.values()))

    #  RECOMPUTED INDEPENDENTLY: the helper's figure is the serialised size of what it is given.
    _probe_payload = {"a": "x" * 10, "b": [1, 2, 3]}
    _bits, _basis = _payload_bits(_probe_payload)
    assert _bits == len(json.dumps(_probe_payload, default=str).encode("utf-8")) * 8, (_bits,)
    assert "not the number of bits it erased" in _basis, _basis

    # ── L2. AN ABSENT PAYLOAD IS NOT A SMALL ONE ─────────────────────────────────────────────────
    #  Serialising None gives the four bytes of "null", so an absent input would meter 32 bits — a figure
    #  saying four bytes were handled when nothing was. Three of the six stages hit this for real during
    #  this round, having been pointed at key names the module does not use.
    _none_bits, _none_basis = _payload_bits(None)
    assert _none_bits is None, ("an absent payload was given a size", _none_bits)
    assert "NOT METERED" in _none_basis, _none_basis
    _unmetered = _o.tfel.meter_operation("w546_absent", None, _none_basis)
    assert _unmetered["metered"] is False and _unmetered["entropy_bits"] is None, _unmetered
    assert _unmetered["landauer_floor_joules"] is None, ("an unmetered operation got an energy figure",
                                                         _unmetered)

    # ── L3. THE FIGURE IS A FLOOR, AND IT IS NAMED AS ONE ────────────────────────────────────────
    _rec = _o.tfel.meter_operation("w546_check", 8000.0, "MEASURED: driven by the guard")
    assert "energy_joules" not in _rec, (
        "the bare energy field is back; it reads as the energy a computation used, and nothing here "
        "measures power", sorted(_rec))
    #  the physics, recomputed here so the ledger cannot drift from what it claims
    _expected = 8000.0 * (1.380649e-23 * _o.tfel.temperature * math.log(2)) * _o.tfel.hw
    assert abs(_rec["landauer_floor_joules"] - _expected) < 1e-30, (_rec["landauer_floor_joules"],
                                                                     _expected)
    assert "FLOOR" in _rec["energy_basis"] and "not a measurement of energy drawn" in _rec["energy_basis"], (
        _rec["energy_basis"])
    #  the hardware factor states that it is not measured
    assert "DECLARED, NOT MEASURED" in _rec["energy_basis"], _rec["energy_basis"]

    # ── L4. COMPLIANCE IS THREE-STATE: an empty ledger is not a compliant one ────────────────────
    from core.transcendent_subsystems.tfel import ThermodynamicFreeEnergyLedger as _TFEL
    _fresh = _TFEL()
    _empty = _fresh.export_cycle_ledger("w546-empty")
    assert _empty["compliance"] is None, ("a cycle that metered nothing reported compliance",
                                          _empty["compliance"])
    assert "NOT ASSESSED" in _empty["compliance_basis"] and "empty ledger" in _empty["compliance_basis"], (
        _empty["compliance_basis"])
    assert _empty["metered_operations"] == 0, _empty
    _fresh.meter_operation("w546_one", 1000.0, "MEASURED: driven by the guard")
    _used = _fresh.export_cycle_ledger("w546-used")
    assert _used["compliance"] is True and _used["metered_operations"] == 1, _used
    assert "1 operation(s) were metered" in _used["compliance_basis"], _used["compliance_basis"]
    #  and the budget declares that it is a literal rather than a derived capacity
    assert "DECLARED, NOT DERIVED" in _used["compliance_basis"], _used["compliance_basis"]

    # ── L5. NO CALLER ANYWHERE PASSES A LITERAL BIT COUNT — the class, not the three instances ────
    #  FU-234 named THREE callers and the first pass fixed one. This asserts the property over the whole
    #  tree instead of over a list of files, so the fourth caller cannot be added without being noticed.
    import pathlib as _pl
    _root2 = _pl.Path(__file__).resolve().parents[1]
    def _is_declared_cost(node):
        """A bit count that no measurement produced: a bare number, int()/float() of one, or an
        expression multiplying by a large constant (`len(batch) * 1.5e6` is HALF measured, which is the
        shape that survives an audit asking only whether a figure is a literal)."""
        if node is None:
            return False
        _inner = (node.args[0] if (isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                                   and node.func.id in ("int", "float") and node.args) else node)
        if isinstance(_inner, ast.Constant) and isinstance(_inner.value, (int, float)):
            return True
        if isinstance(_inner, ast.BinOp):
            return any(isinstance(_s, ast.Constant) and isinstance(_s.value, (int, float))
                       and _s.value >= 1000 for _s in ast.walk(_inner))
        return False

    _literal_callers = []
    for _f in list((_root2 / "agentic_core").rglob("*.py")) + list((_root2 / "core").rglob("*.py")):
        try:
            _tree2 = ast.parse(_f.read_text(encoding="utf-8", errors="replace"))
        except SyntaxError:
            continue
        for _fn in [n for n in ast.walk(_tree2)
                    if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Module))]:
            #  FOLLOW THE VALUE BACK TO ITS ASSIGNMENT. A sweep proved a call-site check insufficient:
            #  moving the literal one line up, into `_bits, _bits_basis = 2e5, "..."`, left the call
            #  reading a Name and the leg passing with the defect in. Tuple targets included, because
            #  that is the form the measured helper returns and therefore the form a shortcut imitates.
            _assigned = {}
            for _st in ast.walk(_fn):
                if not isinstance(_st, ast.Assign):
                    continue
                for _tgt in _st.targets:
                    if isinstance(_tgt, ast.Name):
                        _assigned.setdefault(_tgt.id, []).append(_st.value)
                    elif isinstance(_tgt, ast.Tuple):
                        _vals = (_st.value.elts if isinstance(_st.value, ast.Tuple)
                                 else [None] * len(_tgt.elts))
                        for _el, _v in zip(_tgt.elts, _vals):
                            if isinstance(_el, ast.Name):
                                _assigned.setdefault(_el.id, []).append(_v)
            for _n2 in ast.walk(_fn):
                if not (isinstance(_n2, ast.Call) and isinstance(_n2.func, ast.Attribute)
                        and _n2.func.attr == "meter_operation"):
                    continue
                _args = list(_n2.args[1:2]) + [k.value for k in _n2.keywords if k.arg == "bits"]
                for _a in _args:
                    _candidates = [_a]
                    if isinstance(_a, ast.Name):
                        _candidates = _assigned.get(_a.id, [])
                    for _c in _candidates:
                        if _is_declared_cost(_c):
                            _literal_callers.append(
                                f"{_f.relative_to(_root2)}:{_n2.lineno}"
                                + ("" if _c is _a else f" (via {_a.id})"))
    assert not _literal_callers, (
        "a thermodynamic bit count is a declared constant rather than a measurement, so the joules "
        "computed from it are arithmetic over an invented input", _literal_callers)

    #  AND EVERY TEST DOUBLE OF THAT METHOD MATCHES THE REAL SIGNATURE. A double is a CONSUMER of a
    #  signature: this round changed meter_operation to take the account of where its bit count came
    #  from, and a fake in this very file still had the old two-parameter form — so the producer change
    #  raised TypeError in a test while every direct caller was correct. The real parameters are read
    #  from the module rather than typed here, so this cannot drift from them.
    import inspect as _insp
    from core.transcendent_subsystems.tfel import ThermodynamicFreeEnergyLedger as _RealTFEL
    _real_params = set(_insp.signature(_RealTFEL.meter_operation).parameters) - {"self"}
    _suite_src = _pl.Path(__file__).read_text(encoding="utf-8")
    _suite_tree = ast.parse(_suite_src)
    for _cls in [n for n in ast.walk(_suite_tree) if isinstance(n, ast.ClassDef)]:
        for _meth in [m for m in _cls.body
                      if isinstance(m, (ast.FunctionDef, ast.AsyncFunctionDef))
                      and m.name == "meter_operation"]:
            _have = {a.arg for a in _meth.args.args} - {"self"}
            assert _real_params <= _have, (
                f"the double {_cls.name}.meter_operation at line {_meth.lineno} accepts {sorted(_have)} "
                f"but the real ledger takes {sorted(_real_params)}, so a caller correct against the real "
                f"one raises TypeError against this fake")

    #  and the effector's own entropy figure is not a literal either: the same quantity was reported as
    #  2e5, 500.0 and 0.5 in one function, and no two of them agreed
    _tr = ast.parse((_root2 / "agentic_core/avatars/tools/tool_registry.py").read_text(encoding="utf-8"))
    for _n3 in ast.walk(_tr):
        if isinstance(_n3, ast.keyword) and _n3.arg == "entropy_cost":
            assert not (isinstance(_n3.value, ast.Constant)
                        and isinstance(_n3.value.value, (int, float))), (
                f"tool_registry:{getattr(_n3.value, 'lineno', '?')} returns a literal entropy to its "
                f"caller")

    # ── L6. THE CAUSAL SIMULATOR METERS ITS REAL BATCH, and drops three more invented figures ────
    from agentic_core.simverse.causal_simulator import DynamoInference
    from core.transcendent_subsystems.tfel import ThermodynamicFreeEnergyLedger as _TFEL2
    _batch = [{"task": "a", "payload": "x" * 50}, {"task": "b"}]
    _d = _aio.run(DynamoInference(_TFEL2()).schedule_disaggregated(_batch))
    _independent, _ = _payload_bits(_batch)
    assert _d["metering"]["entropy_bits"] == _independent, (
        "the batch's metered cost is not its measured size", _d["metering"]["entropy_bits"], _independent)
    #  the figure it replaced multiplied a real count by an invented per-task cost — half-measured, which
    #  is the shape that survives an audit asking only whether a number is a literal
    assert _d["metering"]["entropy_bits"] != len(_batch) * 1.5e6, _d["metering"]
    assert "SUCCESS" not in _d["status"], ("a method that schedules nothing reports success", _d["status"])
    assert _d["causal_isolation"] is None and "NOT ASSESSED" in _d["causal_isolation_basis"], _d
    assert _d["latency_ms"] is None and "NOT MEASURED" in _d["latency_basis"], _d
    assert _d["tasks"] == len(_batch), _d


def test_w546_a_fresh_backend_without_the_ledger_refuses_instead_of_inventing_a_budget(tmp_path):
    """The fresh-backend probe P3.17's bar names — and the only way to reach the fallback at all.

    The import of core.transcendent_subsystems.tfel SUCCEEDS here, so the except branch in
    recirculation_orchestrator is never executed by this suite: it is the branch most likely to run on a
    deployment whose path differs and least likely to be tested, and what it returned was
    `{"budget_remaining": 1e9}` — a billion bits of headroom from a class that meters nothing. This probe
    blocks that one module in a fresh interpreter so the fallback is FORCED, and asserts it refuses.
    """
    import json
    import subprocess
    import sys
    from pathlib import Path as _P

    root = _P(__file__).resolve().parents[1]
    script = tmp_path / "probe.py"
    script.write_text(
        "import sys, os\n"
        "sys.path.insert(0, os.environ['WS_ROOT'])\n"
        "import agentic_core as _ac\n"
        "assert _ac.__file__ and os.path.realpath(_ac.__file__).startswith("
        "       os.path.realpath(os.environ['WS_ROOT'])), ('wrong agentic_core', _ac.__file__)\n"
        # BLOCK the one module, so the orchestrator takes its ImportError branch. A finder that raises
        # ImportError for exactly this name is the only honest way to reach it: the module is importable
        # on this machine, so no amount of in-process arrangement exercises the fallback.
        "import importlib.abc, importlib.machinery, json\n"
        "class _Block(importlib.abc.MetaPathFinder):\n"
        "    def find_spec(self, name, path=None, target=None):\n"
        "        if name == 'core.transcendent_subsystems.tfel':\n"
        "            raise ImportError('blocked by the W546 probe')\n"
        "        return None\n"
        "sys.meta_path.insert(0, _Block())\n"
        "from agentic_core.avatars.core.recirculation_orchestrator import "
        "ThermodynamicFreeEnergyLedger as T\n"
        "t = T()\n"
        "m = t.meter_operation('probe', 1234.0)\n"
        "c = t.export_cycle_ledger('probe-cycle')\n"
        "print(json.dumps({'is_fallback': T.__module__.endswith('recirculation_orchestrator'),\n"
        "                  'available': getattr(t, 'available', None),\n"
        "                  'metered': m.get('metered'), 'bits': m.get('entropy_bits'),\n"
        "                  'budget_remaining': m.get('budget_remaining'),\n"
        "                  'floor': m.get('landauer_floor_joules'),\n"
        "                  'meter_basis': bool((m.get('basis') or '').strip()),\n"
        "                  'compliance': c.get('compliance'),\n"
        "                  'has_export': hasattr(t, 'export_cycle_ledger'),\n"
        "                  'keys': sorted(m.keys())}))\n",
        encoding="utf-8")
    d = tmp_path / "fresh"
    env = {**__import__("os").environ, "DATA_DIR": str(d), "WORKSTATION_DATA_DIR": str(d),
           "WORKSTATION_UEG_PATH": str(d / "ueg.json"), "PROJECTS_DIR": str(d / "projects"),
           "AI_DISABLE_LOCAL": "1", "WS_ROOT": str(root), "PYTHONPATH": str(root)}
    r = subprocess.run([sys.executable, str(script)], capture_output=True, text=True,
                       cwd=str(root), env=env)
    assert r.returncode == 0, ("the fresh backend could not reach the fallback ledger", r.stderr[-700:])
    out = json.loads([ln for ln in r.stdout.splitlines() if ln.startswith("{")][-1])

    #  the probe really did force the fallback — otherwise everything below would describe the real one
    assert out["is_fallback"] is True, ("the probe did not reach the fallback branch, so it proves "
                                        "nothing about it", out)
    assert out["available"] is False, out
    #  AND IT INVENTS NOTHING. The figure it used to return was 1e9.
    assert out["budget_remaining"] is None, ("the unavailable ledger reports a budget it does not have",
                                             out)
    assert out["metered"] is False and out["bits"] is None and out["floor"] is None, out
    assert out["meter_basis"] is True, "the refusal carries no reason"
    assert out["compliance"] is None, ("an unavailable ledger reported compliance", out)
    #  A STUB THINNER THAN ITS PRODUCER TESTS THE STUB: the old one had no export_cycle_ledger at all, so
    #  a caller reaching it got a different SHAPE as well as a fabricated figure.
    assert out["has_export"] is True, "the fallback is missing a method the real ledger has"
    for _k in ("metered", "entropy_bits", "landauer_floor_joules", "budget_remaining", "basis"):
        assert _k in out["keys"], (f"the fallback's record omits {_k}, so a reader cannot treat the two "
                                   f"ledgers alike", out["keys"])


def test_w547_the_refinery_reports_no_confidence_and_zero_checks_is_not_a_pass(client):
    """P3.17 (FU-233, FU-235): a confidence that rose with retries, and a verdict over zero checks.

    The enforcement's three states are DRIVEN with three different validator sets rather than observed,
    because the live subclass refuses by default and a leg that only saw that one state would prove
    nothing about the other two.
    """
    import ast
    import asyncio as _aio
    import pathlib

    _root = pathlib.Path(__file__).resolve().parents[1]

    from agentic_core.quality.vrpr_pipeline import VRPRPipeline
    from agentic_core.ueg.logger import VSBUEGLogger as _VSBUEG
    from agentic_core.validation.enforcement_pattern import (UniversalEnforcementPattern,
                                                             ValidationResult)
    from agentic_core.validation.omni_enforcement_pattern_supreme import OmniEnforcementPatternSupreme

    # ── L1. NO CONFIDENCE AT ALL, AND THE RETRY COUNTER NO LONGER GATES THE EXIT ─────────────────
    _refusing = OmniEnforcementPatternSupreme({}, None)
    _out = _aio.run(VRPRPipeline(_VSBUEG(), _refusing).process("Action result: a reasoned outcome", {}))
    assert _out.confidence_score is None, (
        "the refinery reports a confidence again; the figure it used to report started at a declared "
        "0.90 and gained a declared increment per RETRY, so it rose with the number of attempts",
        _out.confidence_score)
    assert (_out.confidence_basis or "").strip() and "NOT MEASURED" in _out.confidence_basis, (
        _out.confidence_basis)
    #  the basis must let a reader RECOMPUTE what the old figure was rather than quote it: a typed
    #  result cannot be checked from the string and goes stale the moment the arithmetic changes
    assert "0.90" in _out.confidence_basis and "0.05" in _out.confidence_basis, _out.confidence_basis

    #  A PASS NO LONGER HAS TO SURVIVE THE RETRY COUNTER. The exit used to require a cleared verdict AND
    #  a confidence at or above a threshold the counter alone could reach, so a cleared output was held
    #  back until it had been "refined" at least once. Driven with a validator that clears.
    class _Clearing:
        def validate(self, target, context=None):
            return ValidationResult(passed=True, basis="driven by the guard")

    _clear = OmniEnforcementPatternSupreme({}, None)
    for _phase in _clear.phases.values():
        for _name in _phase:
            _clear.register_validator(_name, _Clearing())
    _ok = _aio.run(VRPRPipeline(_VSBUEG(), _clear).process("Action result: a reasoned outcome", {}))
    assert _ok.verification_passed is True, _ok.verification_basis
    assert _ok.refinement_iterations == 0, (
        "a cleared output still had to be refined before it could be returned", _ok.refinement_iterations)

    # ── L2. "CERTIFICATION" IS NOT str.replace ───────────────────────────────────────────────────
    #  The cleared exit used to rewrite "Action result" to include the word Certified and "reasoned
    #  outcome" likewise. Renaming text does not certify it, and that word is the strongest claim in the
    #  sentence. Both exits now return the text they were given.
    assert _ok.content == "Action result: a reasoned outcome", (
        "the cleared exit rewrote the output's wording", _ok.content)
    assert "Certified" not in _ok.content, ("the output was certified by renaming it", _ok.content)
    #  and the refusing exit returns the draft unchanged too: each pass used to append a literal, so
    #  three "refinements" produced the draft followed by the same phrase three times
    assert _out.content == "Action result: a reasoned outcome", (
        "a refinement pass with no refiner changed the text", _out.content)
    assert "0 applied a real refiner" in _out.refinement_basis, _out.refinement_basis

    # ── L3. NO GENERATOR OUTPUT IS PASSED AS A SIGNAL ────────────────────────────────────────────
    _seen = {}

    class _SpyMoE:
        async def execute_moe_supreme(self, prompt, vector, context, enforcement):
            _seen["vector"] = vector
            return "a refinement from the experts"

    _spied = _aio.run(VRPRPipeline(_VSBUEG(), _refusing, _SpyMoE()).process("draft", {}))
    assert "vector" in _seen, "the MoE was never called, so this leg proves nothing about its arguments"
    assert _seen["vector"] is None, (
        "a vector is still passed to the MoE; it used to be a generator's output, which the MoE could "
        "not tell from a real signal", _seen["vector"])
    #  and a real refiner's output IS used, so the fix did not disable refinement
    assert "a refinement from the experts" in _spied.content, _spied.content
    assert "1 applied a real refiner" in _spied.refinement_basis or "moe" in _spied.refinement_basis, (
        _spied.refinement_basis)
    #  asserted on the AST, because this module's own docstring names the call it removed
    _vt = ast.parse((_root / "agentic_core/quality/vrpr_pipeline.py").read_text(encoding="utf-8"))
    _calls = [ast.unparse(n.func) for n in ast.walk(_vt) if isinstance(n, ast.Call)]
    assert not [c for c in _calls if "random" in c], ("a generator call is back", _calls)

    # ── L4. ZERO CHECKS IS NOT A PASS — three states, each driven ────────────────────────────────
    _none = UniversalEnforcementPattern({}, None).validate("x")
    assert _none.passed is None, (
        "an enforcement pattern with no validator registered reported a constitutional verdict; zero "
        "checks is the strongest claim resting on the least evidence", _none.passed)
    assert "NOT ASSESSED" in _none.basis and "not a pass" in _none.basis, _none.basis

    class _Failing:
        def validate(self, target, context=None):
            return ValidationResult(passed=False, violation="driven", basis="driven by the guard")

    _p = UniversalEnforcementPattern({}, None)
    _p.register_validator("driven_ok", _Clearing())
    assert _p.validate("x").passed is True, "a registered passing validator could not produce a pass"
    _p.register_validator("driven_bad", _Failing())
    assert _p.validate("x").passed is False, "a registered failing validator could not produce a refusal"

    # ── L5. THE EMISSION CARRIES THE VERDICT, not just the absent figure ─────────────────────────
    #  A None beside a key named for a confidence is an absence a reader fills in, so the basis and the
    #  enforcement's real verdict travel with it.
    #  THE DICT'S KEYS, ON THE AST. A substring search over the source was VACUOUS: a sweep renamed the
    #  key to `_vrpr_confidence_basis_dropped`, which CONTAINS the string being searched for, so the leg
    #  passed with the field gone. Keys are compared exactly.
    _ot = ast.parse((_root / "agentic_core/avatars/core/recirculation_orchestrator.py").read_text(
        encoding="utf-8"))
    _emission_keys = set()
    for _n in ast.walk(_ot):
        if isinstance(_n, ast.Dict) and any(
                isinstance(_k, ast.Constant) and _k.value == "vrpr_confidence" for _k in _n.keys):
            _emission_keys |= {_k.value for _k in _n.keys
                               if isinstance(_k, ast.Constant) and isinstance(_k.value, str)}
    assert "vrpr_confidence" in _emission_keys, "no emission dict carries the refinery's verdict at all"
    for _needle in ("vrpr_confidence_basis", "vrpr_verification_passed", "vrpr_verification_basis"):
        assert _needle in _emission_keys, (
            f"the emission omits {_needle}, so a reader meets a null confidence with no account of it",
            sorted(_emission_keys))

    # ── L6. THE ENFORCED FLAG AGREES WITH WHETHER ANYTHING ENFORCES IT ──────────────────────────
    #  A declared threshold nobody reads is not a threshold. Rather than assert that nothing compares it
    #  — which would red the day someone correctly starts — this asserts the FLAG AND THE CODE AGREE, so
    #  the claim cannot rot in either direction.
    _comparisons = []
    for _f in (_root / "agentic_core").rglob("*.py"):
        try:
            _ft = ast.parse(_f.read_text(encoding="utf-8", errors="replace"))
        except SyntaxError:
            continue
        for _n in ast.walk(_ft):
            if isinstance(_n, ast.Compare) and any(
                    isinstance(_s, ast.Attribute) and _s.attr == "vrpr_threshold"
                    for _s in ast.walk(_n)):
                _comparisons.append(f"{_f.relative_to(_root)}:{_n.lineno}")
    from agentic_core.avatars.modes.mode_controller import AvatarModeManager
    _mm = AvatarModeManager(_VSBUEG())
    _cfgs = list(_mm.mode_configs.values())
    assert _cfgs, "no mode config was built"
    for _c in _cfgs:
        assert _c.vrpr_threshold_enforced is bool(_comparisons), (
            f"the mode config says the threshold is "
            f"{'enforced' if _c.vrpr_threshold_enforced else 'not enforced'} while the tree has "
            f"{len(_comparisons)} comparison(s) against it", _comparisons[:3])


def test_w548_an_unmeasured_term_is_not_the_best_term_and_a_missing_solver_is_reported(client):
    """P3.17's remaining bar clauses: every Ω term computes or says it cannot, and the transport router
    reports itself unavailable rather than raising.

    THE CENTRAL PROPERTY IS ABOUT A MINIMISATION. In a cost functional an absent term defaulted to zero
    is not neutral — it is the OPTIMUM — so the archived objective made the least-measured candidate win
    every comparison, with correct arithmetic throughout. Both the refusal and the computed path are
    driven, and the computed J is recomputed here from the weights so the objective cannot drift from
    the sum it claims.
    """
    import asyncio as _aio
    import ast
    import pathlib

    _root = pathlib.Path(__file__).resolve().parents[1]
    from agentic_core.biomimicry.minimisation.core.omega_functional import (
        MinimisationObjective, _DEFAULT_WEIGHTS)
    from agentic_core.biomimicry.minimisation.core.optimal_transport import OptimalTransportRouter

    _obj = MinimisationObjective()

    # ── L1. AN ABSENT TERM YIELDS NO FIGURE, AND NO J ────────────────────────────────────────────
    _none = _obj.evaluate({}, {})
    assert _none["J"] is None, ("a cost was reported over terms nobody measured; in a minimisation the "
                                "zero those terms used to default to is the best possible score",
                                _none["J"])
    assert len(_none["unassessable_terms"]) == len(_DEFAULT_WEIGHTS), _none
    for _name, _t in _none["terms"].items():
        assert _t["assessable"] is False, (_name, _t)
        #  the key is ABSENT, not zero and not null: a null invites `value or 0`, and that zero is the
        #  optimum coming straight back
        assert "value" not in _t, (_name, "an unmeasured term carries a figure", _t)
        assert "NOT ASSESSED" in _t["basis"], (_name, _t["basis"])
        #  and the refusal NAMES A PRODUCER, so it is an instruction rather than a shrug
        assert len(_t["basis"]) > 60, (_name, "a refusal with no producer named", _t["basis"])
    assert "rewards incompleteness" in _none["basis"], _none["basis"]

    # ── L2. A PARTIAL SUM IS STILL REFUSED — four of five is not a cost ──────────────────────────
    _partial = _obj.evaluate({"free_energy": 0.4, "optimal_transport": 0.2,
                              "schrodinger_bridge": 0.1, "entropy_export": 0.05}, {})
    assert _partial["J"] is None, ("four of five terms produced a cost; it would be SMALLER than the "
                                   "true one, which is exactly the wrong direction for a minimisation",
                                   _partial["J"])
    assert _partial["unassessable_terms"] == ["murray_law"], _partial["unassessable_terms"]
    assert len(_partial["assessable_terms"]) == 4, _partial

    # ── L3. AND THE COMPUTED PATH WORKS, recomputed here from the weights ────────────────────────
    _metrics = {"free_energy": 0.4, "optimal_transport": 0.2, "schrodinger_bridge": 0.1,
                "entropy_export": 0.05, "murray_law": 0.3}
    _full = _obj.evaluate(_metrics, {})
    _expected = sum(_DEFAULT_WEIGHTS[k] * v for k, v in _metrics.items())
    assert _full["J"] is not None and abs(_full["J"] - _expected) < 1e-12, (_full["J"], _expected)
    assert _full["unassessable_terms"] == [], _full
    assert "DECLARED, NOT DERIVED" in _full["weights_basis"], _full["weights_basis"]
    #  the weights are declared and nothing tuned them; the only property anything checks is the sum
    assert abs(sum(_DEFAULT_WEIGHTS.values()) - 1.0) < 1e-12, sum(_DEFAULT_WEIGHTS.values())

    # ── L4. THE HARD CONSTRAINT CANNOT BE PASSED BY OMISSION ─────────────────────────────────────
    #  `legal_compliance: float = 1.0` meant a caller who measured nothing cleared the one constraint
    #  the objective itself calls non-negotiable, because the test is `< 1.0`.
    _legal_unmeasured = _obj.evaluate(_metrics, {"domain": "legal"})
    assert _legal_unmeasured["J"] is None, ("a legal domain cleared with no compliance figure at all",
                                            _legal_unmeasured["J"])
    assert "REFUSED" in _legal_unmeasured["basis"] and "non-negotiable" in _legal_unmeasured["basis"], (
        _legal_unmeasured["basis"])
    #  measured and below the bar is INFINITE — the constraint still bites
    _legal_bad = _obj.evaluate(_metrics, {"layer": "L12_Policy"}, legal_compliance=0.9)
    assert _legal_bad["J"] == float("inf"), _legal_bad
    #  measured and at the bar passes
    _legal_ok = _obj.evaluate(_metrics, {"domain": "legal"}, legal_compliance=1.0)
    assert _legal_ok["J"] is not None and _legal_ok["J"] != float("inf"), _legal_ok
    #  and a NON-legal domain takes the declared soft penalty rather than infinity
    _soft = _obj.evaluate(_metrics, {}, legal_compliance=0.8)
    assert _soft["soft_penalty"] is not None and _soft["soft_penalty"] > 0, _soft
    assert abs(_soft["J"] - (_expected + _soft["soft_penalty"])) < 1e-9, _soft

    # ── L5. NO TOP-LEVEL torch IMPORT — the optional-torch invariant ─────────────────────────────
    #  The archived objective imported torch at module level and never used it, which would have made
    #  `import agentic_core.app_mvp` fail wherever torch is absent.
    _ot_tree = ast.parse((_root / "agentic_core/biomimicry/minimisation/core/omega_functional.py"
                          ).read_text(encoding="utf-8"))
    for _n in _ot_tree.body:
        if isinstance(_n, ast.Import):
            assert not any(a.name.split(".")[0] == "torch" for a in _n.names), (
                f"omega_functional imports torch at module level (line {_n.lineno}); importing this "
                f"platform must never require it")
        if isinstance(_n, ast.ImportFrom):
            assert (_n.module or "").split(".")[0] != "torch", f"line {_n.lineno}"

    # ── L6. THE ROUTER REPORTS ITSELF, WITHOUT BEING CALLED ──────────────────────────────────────
    _r = OptimalTransportRouter()
    _av = _r.availability()
    assert isinstance(_av["available"], bool), _av
    assert (_av["basis"] or "").strip(), "the router reports availability with no account of it"
    if not _av["available"]:
        assert "NOT AVAILABLE" in _av["basis"] and "nothing is estimated" in _av["basis"].lower(), (
            _av["basis"])
        #  AND solve() RETURNS that report rather than raising. A component that can only report its own
        #  unavailability by failing cannot be asked about itself.
        _plan, _w, _meta = _r.solve(None, None, None)
        assert _plan is None and _w is None, (_plan, _w)
        assert _meta["available"] is False, _meta
        #  nothing is estimated in place of a plan
        assert "converged" not in _meta or _meta.get("converged") is None, _meta

    #  the convergence report is three-state and never asserts: driven directly, because POT is absent
    #  here so the solve path cannot reach it
    _no_log = _r._solve_meta(None)
    assert _no_log["converged"] is None, ("convergence was claimed with no solver log", _no_log)
    assert "NOT KNOWN" in _no_log["converged_basis"], _no_log["converged_basis"]
    assert _no_log["iterations"] is None, ("the iteration CAP was reported as a count", _no_log)
    assert str(_r.max_iter) in _no_log["iterations_basis"], _no_log["iterations_basis"]
    _conv = _r._solve_meta({"err": [1.0, 0.5, _r.tol / 2]})
    assert _conv["converged"] is True and _conv["iterations"] == 3, _conv
    _stalled = _r._solve_meta({"err": [1.0, 0.9, 0.8]})
    assert _stalled["converged"] is False and "NOT CONVERGED" in _stalled["converged_basis"], _stalled
    assert _stalled["iterations"] == 3, _stalled

    # ── L7. AND IT IS ALL REACHED — one route, reporting the real state ──────────────────────────
    _resp = client.get("/api/v1/minimisation/status")
    assert _resp.status_code == 200, (_resp.status_code, _resp.text[:200])
    _j = _resp.json()
    assert _j["terms_total"] == len(_DEFAULT_WEIGHTS), _j
    assert _j["omega_functional"]["J"] is None, ("the surface reports a cost over unmeasured terms", _j)
    assert _j["transport_router"]["available"] is _av["available"], _j["transport_router"]
    #  NO SECOND LANDAUER METER: the surface points at the one ledger and keeps no figure of its own
    assert _j["thermodynamic_ledger"]["available"] is True, _j["thermodynamic_ledger"]
    import math as _math
    _floor = 1.380649e-23 * _j["thermodynamic_ledger"]["temperature_kelvin"] * _math.log(2)
    assert abs(_j["thermodynamic_ledger"]["joules_per_bit_floor"] - _floor) < 1e-30, (
        "the surface's own floor disagrees with k_B*T*ln2, so it is keeping a second figure",
        _j["thermodynamic_ledger"]["joules_per_bit_floor"], _floor)
    assert "FLOOR" in _j["thermodynamic_ledger"]["basis"], _j["thermodynamic_ledger"]["basis"]


def test_w549_the_horizon_spec_agrees_with_the_code_it_routes_into(client):
    """The three bar corrections the Owner ruled for, each checked against the thing it describes.

    Every leg here compares a DOCUMENT against the CODE or against the prompt, because that is the whole
    defect class these three rows found: a bar corrected in one place and not the other, a ruling
    recorded in the register and absent from the spec, and a drop note quoting a bar it had misread.
    """
    import json
    import pathlib
    import re

    _root = pathlib.Path(__file__).resolve().parents[1]
    _spec = (_root / "docs/HORIZON_INTEGRATION.md").read_text(encoding="utf-8")
    _prompt = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")

    # ── L1 (FU-335). EVERY TIER NAMES A change_type, AND THE SPEC'S RANKS MATCH _TIER_MAP ────────
    from agentic_core.api.change_control import _TIER_MAP, _TIER_RANK
    #  the spec's own table is the subject: each data row names a type (or says none is filed) and a rank
    #  W556 — THE TABLE NOW LEADS WITH THE DISPOSITION, which is the name the code uses. The old form
    #  matched on the tier band in the first cell, and W556 moved it to the second: the 0–5 numbering
    #  does not exist in change_control, so the spec and the item body were describing the same bands in
    #  two languages. Keying on the disposition is also STRONGER — the set is compared with the code's
    #  own DISPOSITIONS below, so the spec cannot name a band the code lacks or omit one it has, which
    #  the band-matching form could not have noticed.
    _rows = [ln for ln in _spec.splitlines()
             if ln.startswith("| `") and ":--" not in ln
             and re.match(r"\|\s*`[A-Z_]+`\s*\|\s*(0–1|2|3–4|5)\s*\|", ln)]
    from agentic_core.horizon.muhasabah import DISPOSITIONS as _DISP
    assert len(_rows) == len(_DISP), (
        "the table does not carry one row per disposition the code declares", len(_rows), sorted(_DISP))
    _named = {}
    _spec_dispositions = set()
    for _ln in _rows:
        _cells = [c.strip() for c in _ln.strip().strip("|").split("|")]
        _disp, _band, _ctype, _rank = _cells[0].strip("`"), _cells[1], _cells[3], _cells[4]
        _spec_dispositions.add(_disp)
        #  THE SPEC'S CLAIM ABOUT THE BOARD MUST MATCH THE CODE'S. Two documents, one fact.
        assert _disp in _DISP, (f"the spec names a disposition the code does not declare: {_disp!r}",
                                sorted(_DISP))
        _reaches = "yes" in _cells[5].lower()
        assert _DISP[_disp]["reaches_board"] is _reaches, (
            f"the spec and the code disagree on whether {_disp} reaches the Board",
            _reaches, _DISP[_disp]["reaches_board"])
        assert (_DISP[_disp]["change_type"] or "") in _ctype, (
            f"the spec files a different change_type for {_disp} than the code does",
            _ctype, _DISP[_disp]["change_type"])
        _t = re.search(r"`([a-z_]+)`", _ctype)
        if _t:
            _name = _t.group(1)
            assert _name in _TIER_MAP, (
                f"the spec routes tier {_band} to change_type {_name!r}, which _TIER_MAP does not define, "
                f"so submit_change would fall through to its default rank", sorted(_TIER_MAP))
            #  THE SPEC'S CLAIMED RANK MUST BE THE CODE'S RANK. This is the cross-document check the row
            #  asked for: the old table named config_minor for tier 2 and said nothing about its rank,
            #  so a reader could not tell the Board was unreachable from it.
            assert _TIER_MAP[_name] == _rank, (
                f"the spec says tier {_band} ({_name}) ranks {_rank}; _TIER_MAP says "
                f"{_TIER_MAP[_name]}", _ln.strip()[:120])
            _named[_band] = (_name, _rank)
        else:
            assert "none" in _ctype.lower(), (f"tier {_band} names no change_type and does not say so",
                                              _ln.strip()[:120])
    #  NEITHER DOCUMENT MAY CARRY A BAND THE OTHER LACKS — the drift this guard exists for, now checked
    #  as a set identity rather than one row at a time.
    assert _spec_dispositions == set(_DISP), (
        "the spec's dispositions and the code's are not the same set",
        sorted(_spec_dispositions), sorted(_DISP))
    #  the band the spec says reaches the Board must actually rank high enough for the gate to be reached
    assert "3–4" in _named, _named
    _n34, _r34 = _named["3–4"]
    assert _TIER_RANK[_r34] >= _TIER_RANK["HIGH"], (
        f"the spec routes tier 3–4 to {_n34} at rank {_r34}, below the HIGH that "
        f"awaiting_board_ratification requires — an escalation that silently does not escalate", _named)
    #  and tier 2 must NOT claim to reach it
    _n2, _r2 = _named["2"]
    assert _TIER_RANK[_r2] < _TIER_RANK["HIGH"], (_n2, _r2)
    assert "no, by design" in _spec, "the spec does not state that a tier-2 record stops short of the Board"

    # ── L1b. AND THE MONEY FENCE IS DRIVEN, not asserted ─────────────────────────────────────────
    #  The spec claims submit_change REFUSES economy_material, so a money-touching lesson cannot be
    #  filed as a change at all. Driven through the route rather than taken from the prose.
    _r = client.post("/api/v1/cca/submit", json={
        "title": "w549 probe: a money-touching lesson", "change_type": "economy_material",
        "description": "driven by the guard to prove the fence the Horizon spec relies on"})
    assert _r.status_code == 422, (
        "the spec tells a round that filing a money lesson as economy_material is refused; it was not",
        _r.status_code, _r.text[:200])
    assert "reserved" in _r.text.lower(), _r.text[:300]

    # ── L2 (FU-336). THE OWNER-RULED FIELD REACHED THE SPEC ──────────────────────────────────────
    #  WORD BOUNDARIES, not a substring. A sweep renamed the field to `_reflection_tag_removed`, which
    #  CONTAINS the name being searched for, so a plain `in` check passed with the field gone. That is
    #  the THIRD substring loss of this night's work — the same shape caught the emission's fields and
    #  the archive record's module list — so the rule is now explicit: a field name is matched with
    #  boundaries, and only a quoted or backticked form proves the field itself is named.
    #  BOTH SECTIONS A BUILDER READS, each checked on its own. A sweep made two blinds vacuous at once
    #  and the cause was the same: the field is written into §4, where the IntentRecord is defined, AND
    #  §6, where the stores are — and a leg needing only one occurrence passed when either was deleted.
    #  FU-336's requirement is that an Owner ruling reaches the places a round builds from, and there
    #  are two, so neither is allowed to carry the claim alone.
    _s4_at = _spec.index("## 4 · The loop")
    _s6_at = _spec.index("## 6 · Storage")
    _regions = {"§4 (the loop, where the IntentRecord is defined)": _spec[_s4_at:_s6_at],
                "§6 (storage, where the LessonRecord is defined)": _spec[_s6_at:]}
    for _where, _region in _regions.items():
        _hits = [_m.start() for _m in re.finditer(r"(?<![\w])reflection_tag(?![\w])", _region)]
        assert _hits, (
            f"the Owner's ruling recorded as FU-267 is absent from {_where}; a round working from that "
            f"section would omit an Owner-ruled field")
        assert "`reflection_tag`" in _region, (
            f"{_where} mentions the field without naming it as a field")
        _near = _region[_hits[0]:_hits[0] + 1200]
        #  the properties the ruling actually sets, each stated rather than implied
        assert "user" in _near.lower() and "own words" in _near.lower(), (_where, _near[:200])
        assert "clear" in _near.lower(), (_where, "omits that the user can CLEAR the tag")
        assert "WRITE route" in _near, (
            _where, "does not say the field needs a write route; every sizing budgeted a read only")
        assert "no AI ever writes it" in _near, (
            _where, "does not carry the rule that no AI may write this field — the sharpest case of the "
                    "item's no-field-is-filled-by-inference leg, and the one a populated-field check "
                    "would pass on a value an engine inferred")

    # ── L3 (FU-337). A REGISTER NOTE THAT QUOTES A BAR MUST MATCH THE PROMPT ─────────────────────
    #  The durable form of this row rather than the one-word fix: FU-337 asked whether a drop note
    #  quoting a bar should be checked mechanically, "since both failures were a misreading of a
    #  document that was right there". Every quoted ACCEPT fragment in the register is compared against
    #  the prompt with whitespace normalised, because the prompt wraps its lines.
    def _flat(s: str) -> str:
        return " ".join(s.split())

    _flat_prompt = _flat(_prompt)
    _reg = json.loads((_root / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))["items"]
    _checked, _bad = 0, []
    for _row in _reg:
        for _key in ("note", "why"):
            _text = _row.get(_key) or ""
            #  a quoted fragment that begins with the bar's own marker word
            for _m in re.finditer(r"'(ACCEPT: [^']{30,300})'", _text):
                _frag = _flat(_m.group(1))
                _checked += 1
                if _frag not in _flat_prompt:
                    _bad.append(f"{_row['id']}.{_key}: {_frag[:90]}")
    assert _checked >= 1, ("no register row quotes a bar, so this consistency check could not fail",
                           _checked)
    assert not _bad, (
        "a register row quotes an ACCEPT clause that does not appear in the prompt. A round reading the "
        "register rather than the prompt would build against the wrong bar — which is how a PROBE came "
        "to be recorded as a guard, and a probe runs in a fresh backend where a guard need not",
        _bad[:3])

    #  and the specific correction landed: FU-297 now quotes P2.16's bar as the prompt states it
    _fu297 = next(r for r in _reg if r["id"] == "FU-297")
    assert "asserted by a probe" in _fu297["note"], (
        "FU-297 still renders P2.16's probe as a guard", _fu297["note"][:200])
    assert _flat("asserted by a probe") in _flat_prompt, "the prompt itself no longer says probe"

    # ── L4 (FU-336, part three). THE TWO ZEROS ARE DIFFERENT, and the plan now says which ─────────
    #  `schedule()` lists OPEN rows, so an item rendered "0" was ambiguous between two opposite states:
    #  never examined, and examined with every row closed. NOT ACADEMIC — W545 closed P3.16's last two
    #  rows and left it at "0" with an UNMET bar, which reads exactly like an item nobody has looked at.
    #  Driven with a synthetic register so both zeros are produced here rather than observed.
    from agentic_core.plan_followups import render_plan_now
    _synthetic = {"items": [
        {"id": "FU-9001", "slot": "P9.1", "status": "done", "severity": "medium", "title": "t",
         "files": [], "found": "W000"},
        {"id": "FU-9002", "slot": "P9.1", "status": "done", "severity": "medium", "title": "t",
         "files": [], "found": "W000"},
    ]}
    #  the parser requires the real section tag on a line of its own, not a prose mention of it
    _fake_plan = "\n".join(["<delivery_plan>",
                            " P9.1 an item every row of which has closed",
                            " P9.2 an item no row has ever ridden",
                            "</delivery_plan>", ""])
    _rendered = render_plan_now(_synthetic, _fake_plan)
    #  the item with closed rows must NOT render identically to the one with none
    assert "P9.1" in _rendered and "P9.2" in _rendered, _rendered[:400]
    _p91 = [ln for ln in _rendered.splitlines() if "P9.1" in ln]
    _p92 = [ln for ln in _rendered.splitlines() if "P9.2" in ln]
    assert _p91 and _p92, (_p91, _p92)
    #  the all-closed item says its rows closed and that this is NOT the item being done
    _joined = " ".join(_p91)
    assert "2 have" in _joined or "0/2" in _joined, (
        "an item whose rows all closed renders the same as one no row has ever ridden, so a reader "
        "cannot tell an examined item from an unexamined one", _joined[:200])
    assert "closes on its ACCEPT clause" in _rendered or "0/2" in _rendered, _rendered[:600]
    #  and the never-ridden item says UNEXAMINED rather than showing a bare zero
    assert "0/0" in " ".join(_p92) or "UNEXAMINED" in _rendered, (" ".join(_p92))[:200]


def test_w550_horizon_reaches_every_compression_and_decision_state_and_infers_no_field(client):
    """P2.11's bar: each compression state and each decision state REACHABLE and asserted; the floor's
    run produces NOT_COMPRESSED with a reason; no field is filled by inference.

    Every state is driven THROUGH THE ROUTE, including the two this deployment cannot reach on its own —
    a state a guard can only produce by calling an internal function is a state no user ever meets, which
    is what the bar means by reachable. The model-served path is reached by supplying what a provisioned
    model would supply, not by asserting what it would say.
    """
    import agentic_core.api.horizon as _H
    from agentic_core.horizon import kernel

    # ── L1. THE ORDINARY PATH IS A REFUSAL, AND IT CARRIES ITS REASON ────────────────────────────
    _r = client.post("/api/v1/horizon/observe",
                     json={"raw_text": "Can you settle the contract dispute for me?"})
    assert _r.status_code == 200, (_r.status_code, _r.text[:200])
    _j = _r.json()
    _rec, _dec = _j["record"], _j["decision"]
    assert _rec["compression"] == kernel.NOT_COMPRESSED, (
        "the deterministic floor's run was recorded as a compression; it composes structured output from "
        "the request and infers nothing", _rec["compression"], _rec.get("served_by"))
    assert "ORDINARY PATH" in _rec["compression_basis"], (
        "the refusal does not say it is the common path, so a reader meets it as an edge case",
        _rec["compression_basis"])
    assert _rec["served_by"], "the record does not name what served the call"

    # ── L2. NO FIELD IS FILLED BY INFERENCE — the keys are ABSENT, not empty ─────────────────────
    #  An empty string or an empty list in any of these reads as a FINDING: that nothing is missing, or
    #  that there is nothing to escalate. The brief's own compressor wrote a sentence about what the user
    #  "really" meant, hard-coded; absence is the only honest alternative when nothing compressed.
    for _f in ("asked_for", "domain", "stakes", "missing", "escalations"):
        assert _f not in _rec, (
            f"{_f} is present on a record nothing compressed, so a field was filled by inference", _f,
            _rec.get(_f))
    assert _rec["fields_present"] == [], _rec["fields_present"]
    assert sorted(_rec["fields_absent"]) == sorted(kernel._COMPRESSION_FIELDS), _rec["fields_absent"]
    assert "would read as a finding" in _rec["fields_basis"], _rec["fields_basis"]

    # ── L3. ESCALATE, FAIL CLOSED, and the unavailable terms report None rather than False ───────
    assert _dec["decision"] == kernel.ESCALATE, (
        "an uncompressed request with an unknown domain was allowed to proceed", _dec)
    _terms = {t["term"]: t for t in _dec["terms"]}
    assert _terms["uncompressed_and_grave_or_unknown_domain"]["fired"] is True, _terms
    #  A TERM WITH NO INSTRUMENT IS NOT A TERM THAT PASSED. False would say the compression looked and
    #  found nothing; None says there was no compression to look.
    for _t in ("guardrail_escalation", "required_field_missing"):
        assert _terms[_t]["fired"] is None, (
            f"{_t} reported a verdict over a compression that never happened", _terms[_t])
        assert "NOT AVAILABLE" in _terms[_t]["basis"], _terms[_t]["basis"]
    #  no score anywhere: the decision is a list of terms, not a number
    assert "fired" in _dec and isinstance(_dec["fired"], list), _dec
    for _t in _dec["terms"]:
        assert not any(k in _t for k in ("score", "weight", "confidence")), (
            "a term carries a weight, so the decision is a blend after all", _t)

    # ── L4. COMPRESSED AND PROCEED ARE REACHABLE THROUGH THE ROUTE ───────────────────────────────
    #  Supplying what a provisioned model would supply, because none is provisioned here. Without this
    #  the COMPRESSED branch would be code nobody has run, and the bar asks for it to be reachable.
    async def _served(prompt, **kw):
        return ("asked_for: a contract review\ndomain: operations\nstakes: a delivery date\n",
                {"served_by": "w550-probe-model", "is_external": False})

    _real = _H.ai_text
    try:
        _H.ai_text = _served
        _j2 = client.post("/api/v1/horizon/observe", json={"raw_text": "review this contract"}).json()
    finally:
        _H.ai_text = _real
    _rec2, _dec2 = _j2["record"], _j2["decision"]
    assert _rec2["compression"] == kernel.COMPRESSED, (_rec2["compression"], _rec2.get("served_by"))
    assert _rec2["served_by"] == "w550-probe-model", (
        "the record does not name WHICH model compressed it", _rec2.get("served_by"))
    #  the fields that came back are present and the ones that did not are still absent — a model that
    #  answered partially must not have the rest filled in on its behalf
    assert _rec2.get("asked_for") == "a contract review", _rec2.get("asked_for")
    assert sorted(_rec2["fields_present"]) == ["asked_for", "domain", "stakes"], _rec2["fields_present"]
    for _f in ("missing", "escalations"):
        assert _f not in _rec2, (f"{_f} was filled in for a model that did not answer it", _rec2.get(_f))
    assert _dec2["decision"] == kernel.PROCEED, (
        "a compressed request on a non-grave domain with no missing input and no escalation did not "
        "proceed, so PROCEED is unreachable", _dec2)

    # ── L5. NOT ASSESSABLE IS NOT A QUIET PROCEED ────────────────────────────────────────────────
    _na = kernel.decide({})
    assert _na["decision"] == kernel.NOT_ASSESSABLE, _na
    assert _na["terms"] and _na["terms"][0]["fired"] is None, _na["terms"]
    assert "not a request to proceed with" in _na["basis"], _na["basis"]
    #  and a compressed GRAVE domain with an escalation still escalates, so ESCALATE is reachable from
    #  the stated terms and not only from the fail-closed one
    _grave = kernel.decide({"compression": kernel.COMPRESSED, "domain": "legal",
                            "escalations": ["a ruling is sought"], "missing": []})
    assert _grave["decision"] == kernel.ESCALATE and "guardrail_escalation" in _grave["fired"], _grave
    _miss = kernel.decide({"compression": kernel.COMPRESSED, "domain": "operations",
                           "escalations": [], "missing": ["the delivery date"]})
    assert _miss["decision"] == kernel.ESCALATE and "required_field_missing" in _miss["fired"], _miss

    # ── L6. THE REFLECTION TAG IS THE USER'S, AND NO AI MAY WRITE IT ─────────────────────────────
    _iid = _rec["intent_id"]
    assert _rec["reflection_tag"] is None and _rec["reflection_tag_by"] is None, _rec
    assert "no AI ever writes it" in _rec["reflection_tag_basis"], _rec["reflection_tag_basis"]
    _set = client.post("/api/v1/horizon/reflection",
                       json={"intent_id": _iid, "text": "I was worried about the deadline"})
    assert _set.status_code == 200, (_set.status_code, _set.text[:200])
    assert _set.json()["reflection_tag"] == "I was worried about the deadline", _set.json()
    assert str(_set.json()["reflection_tag_by"]).startswith("user:"), _set.json()
    #  CLEARING is the user's to do, and a cleared tag leaves no trace of what it said
    _clr = client.post("/api/v1/horizon/reflection", json={"intent_id": _iid, "text": None})
    assert _clr.status_code == 200 and _clr.json()["reflection_tag"] is None, _clr.json()
    assert _clr.json()["reflection_tag_by"] is None, _clr.json()
    assert "CLEARED by the user" in _clr.json()["basis"], _clr.json()["basis"]
    #  THE REFUSAL THAT MATTERS: an identity that does not name a user cannot write the user's words
    import pytest as _pt
    with _pt.raises(ValueError):
        kernel.set_reflection_tag(_iid, "an engine's guess at the intent", "agent:soch")
    with _pt.raises(ValueError):
        kernel.set_reflection_tag(_iid, "a system default", "system")
    with _pt.raises(ValueError):
        kernel.set_reflection_tag(_iid, "unattributed", "   ")
    #  and the field is still clear after all three refusals
    assert kernel.get(_iid)["reflection_tag"] is None, kernel.get(_iid)

    # ── L7. THE SURFACE STATES ITS OWN LIMITS rather than implying them ─────────────────────────
    _st = client.get("/api/v1/horizon/states")
    assert _st.status_code == 200, _st.status_code
    _s = _st.json()
    assert set(_s["compression_states"]) == {kernel.COMPRESSED, kernel.NOT_COMPRESSED}, _s
    assert set(_s["decision_states"]) == {kernel.PROCEED, kernel.ESCALATE, kernel.NOT_ASSESSABLE}, _s
    assert _s["no_blended_score"] is True, _s
    assert "no instrument" in _s["basis"], _s["basis"]
    #  the records view reports the proportion that were NOT compressed rather than smoothing it
    _rv = client.get("/api/v1/horizon/records").json()
    assert _rv["not_compressed"] >= 1 and _rv["total"] >= 2, _rv
    assert "reported rather than smoothed" in _rv["basis"], _rv["basis"]


def test_w551_three_gates_refuse_state_their_limits_and_name_no_number(client):
    """P2.12: every refusal path driven, each gate's limit on the surface, and the distress routes
    rendering as NOT SUPPLIED — never a default, never a placeholder, never a plausible-looking number.

    THE LEG THAT MATTERS MOST IS AN ABSENCE. A fabricated helpline is the single most dangerous thing
    this repository could produce, because a person in distress might dial it and no later correction
    reaches them. So no digit sequence resembling a telephone number may exist anywhere on this path.
    """
    import asyncio as _aio
    import pathlib
    import re

    _root = pathlib.Path(__file__).resolve().parents[1]
    from agentic_core.gaas.v5 import horizon_guardrails as _g

    # ── L1. EVERY REFUSAL PATH IS DRIVEN ────────────────────────────────────────────────────────
    #  SEVERAL PHRASINGS PER GATE, so no single pattern can be deleted unnoticed. A sweep proved the
    #  need: removing the "is it/this/that halal" pattern left a broader one catching the same sentence,
    #  and the blind changed nothing observable. Each phrasing below is worded to lean on a different
    #  pattern, so every pattern is load-bearing for at least one case.
    _cases = {
        "religious_ruling": [
            "is this halal to invest in?",
            #  the sweep earned this one: the pattern reading "is it/this/that <word>" is SUBSUMED by a
            #  broader halal/haram pattern, so its only unique contribution is the words permissible,
            #  forbidden and sinful — and with no phrasing using them, deleting that pattern changed
            #  nothing observable. A redundant pattern is an untested pattern.
            "is this permissible for me to do?",
            "is that forbidden in my situation?",
            "please give me a ruling on this contract",
            "what does Islam say I should do about my inheritance",
            "am I sinning by taking this job",
            "I need a fatwa on this transaction",
        ],
        "theological_proof": [
            "science has proven the Quran is accurate",
            "this is scientific proof of creation",
            "can you prove that God exists",
            "modern research disproves religion",
        ],
        "clinical_care": [
            "I can't go on and want to die",
            "I have been thinking about suicide",
            "there is no reason to live any more",
            "I want to harm myself",
            "I self-harm when it gets bad",
        ],
    }
    for _gate, _texts in _cases.items():
        for _text in _texts:
            _r = _g.screen_all(_text)
            assert _r["escalate"] is True, (
                _gate, "this phrasing did not escalate, so a pattern is missing or was removed", _text,
                _r["escalated_by"])
            assert _gate in _r["escalated_by"], (_gate, _text, _r["escalated_by"])
            _one = _r["gates"][_gate]
            assert _one["verdict"] == _g.ESCALATE, (_gate, _text, _one["verdict"])
            assert (_one["action"] or "").strip(), (_gate, _text, "an escalation with no action named")

    # ── L2. NO GATE CERTIFIES AN ABSENCE, and a non-match is not a clearance ────────────────────
    #  A screen may ESCALATE but may never certify that nothing was sought. These are phrase screens, so
    #  a non-match means their own patterns found nothing — a much weaker statement, and the one a page
    #  listing three green gates would silently upgrade.
    _clean = _g.screen_all("what is the weather today")
    assert _clean["escalate"] is False, _clean["escalated_by"]
    assert _clean["certifies_absence"] is False, _clean
    assert "NOT A CLEARANCE" in _clean["basis"], _clean["basis"]
    for _name, _one in _clean["gates"].items():
        assert _one["verdict"] == _g.NOT_DETECTED, (_name, _one["verdict"])
        assert _one["certifies_absence"] is False, (_name, _one)
        assert "NOT A FINDING THAT IT IS ABSENT" in _one["not_looked_at"], (_name, _one["not_looked_at"])
        assert (_one["coverage"] or "").strip(), (_name, "a screen with no stated coverage")

    # ── L3. THE ESCALATION DEFAULTS ON WHERE A SCREEN CANNOT DECIDE ─────────────────────────────
    for _unscreenable in (None, "", "   ", 42, {"a": 1}):
        _u = _g.screen_all(_unscreenable)
        assert _u["escalate"] is True, (
            f"a subject no screen could read ({_unscreenable!r}) did not escalate; a screen that could "
            f"not run is not a screen that passed", _u["escalated_by"])
        assert sorted(_u["escalated_by"]) == sorted(_cases), (_unscreenable, _u["escalated_by"])
        for _one in _u["gates"].values():
            assert _one["verdict"] == _g.CANNOT_DECIDE, (_unscreenable, _one["verdict"])
            assert _one["matched"] is None, (_unscreenable, _one)

    # ── L4. THE DISTRESS PATH WITHHOLDS COUNSEL, SAYS IT IS NOT A PERSON, AND NAMES NO ROUTE ────
    _d = _g.clinical_care_gate("I want to die")
    assert _d["withhold_ai_counsel"] is True, _d
    assert "not a person" in _d["statement"].lower(), _d["statement"]
    assert "software" in _d["statement"].lower(), _d["statement"]
    #  the key is PRESENT and carries None: a missing key reads as a field nobody thought about, and a
    #  placeholder row reads as a route
    #  THREE-STATE SINCE W566, when the Owner supplied a route. The key is always PRESENT: a missing key
    #  reads as a field nobody thought about. While nothing is supplied it carries None and the basis says
    #  so; once something is, EVERY ROUTE CARRIES ITS REVIEWER, ITS DATE AND ITS JURISDICTION — which is
    #  the leg FU-361 said would be needed on the day a route arrived.
    assert "human_routes" in _d, _d.keys()
    if _d["human_routes"] is None:
        assert "NOT SUPPLIED" in _d["human_routes_basis"], _d["human_routes_basis"]
        assert "might act on it" in _d["human_routes_basis"], _d["human_routes_basis"]
    else:
        assert _d["human_routes"], "an empty list where an unfilled field belongs"
        for _r in _d["human_routes"]:
            for _f in ("route", "reviewed_by", "checked_on", "jurisdiction"):
                assert str(_r.get(_f) or "").strip(), (_f, "a shown route does not carry it", _r)
            assert "stale" in _r, ("a shown route does not say whether it is stale", _r)
            #  THE PLATFORM MAY NOT BE ITS OWN REVIEWER. A software verdict on whether a distress route
            #  reaches a human is worth nothing to the person acting on it.
            _by = str(_r["reviewed_by"]).lower()
            for _bad in ("the platform", "workstation", "automated", "agent", "ai "):
                assert _bad not in _by, ("the platform is named as the reviewer of a distress route", _by)
    #  and a non-distress text gets no statement rather than a reassuring one
    assert _g.clinical_care_gate("what is the weather today")["statement"] is None

    # ── L5. NO PLAUSIBLE NUMBER ANYWHERE ON THIS PATH — the leg this item turns on ──────────────
    #  Checked over the kernel module, the route module and the PAGE, because a number introduced in any
    #  of the three reaches the same person. Four or more consecutive digits, or any digit run broken by
    #  spaces, dashes or parentheses in the way a dialable number is written.
    _NUMBERISH = re.compile(r"(?:\+?\d[\d\s().-]{6,}\d)|(?:\b\d{4,}\b)")
    for _rel in ("agentic_core/gaas/v5/horizon_guardrails.py",
                 "agentic_core/api/horizon.py",
                 "apps/workstation-superapp/src/pages/governance/HorizonGuardrails.tsx"):
        _src = (_root / _rel).read_text(encoding="utf-8")
        _hits = [m.group(0) for m in _NUMBERISH.finditer(_src)]
        assert not _hits, (
            f"{_rel} contains a digit sequence a person in distress could read as a number to dial. A "
            f"fabricated helpline is the one fabrication no later correction reaches", _hits[:5])
    #  and no service name is offered in place of a number either
    _gsrc = (_root / "agentic_core/gaas/v5/horizon_guardrails.py").read_text(encoding="utf-8")
    #  NOT HARD-CODED — LOADED. The module may hold no route of its own: it reads them from
    #  distress_routes.json, which is also why the digit leg above keeps its full strength over all three
    #  files rather than being narrowed. A route written into the module would carry an ISO check-date,
    #  which IS a dash-separated digit run, so the two requirements would have been in direct conflict.
    _mod_src = (_root / "agentic_core/gaas/v5/horizon_guardrails.py").read_text(encoding="utf-8")
    assert "_load_routes()" in _mod_src and "DISTRESS_ROUTES, _ROUTES_LOAD_BASIS" in _mod_src, (
        "the module no longer loads its routes from data")
    assert not re.search(r"DISTRESS_ROUTES\s*(?::[^=]*)?=\s*\(\s*\{", _mod_src), (
        "a distress route is written into the module rather than loaded")
    #  and the loader never raises: an absent file, an unreadable one and an empty list are three states
    assert _g._load_routes()[1], "the loader returns no basis for what it found"

    # ── L6. THE GATES ARE ATTACHED TO THE INTERCEPTOR, NOT BESIDE IT ────────────────────────────
    #  The item's own words. A guardrail a caller has to remember to ask for is not on the path, so this
    #  drives the interceptor rather than the gates.
    from agentic_core.gaas.v5 import UnifiedConstitutionalInterceptorV16Omega as _UCI
    _u = _UCI(node_id="w551-guard")

    async def _benign():
        return "the weather is fine"

    async def _bad_output():
        return "science has proven the Quran is accurate"

    _blocked = _aio.run(_u.intercept({"intent": "generic", "text": "is this halal?"}, _benign))
    assert _blocked.status == "blocked", ("a guardrail subject reached execution", _blocked.status)
    #  an ESCALATION, not a breach: a screen doing its job must not trip the breaker and halt the node
    assert _blocked.escalation is True, _blocked
    assert _blocked.guardrails and "religious_ruling" in _blocked.guardrails["escalated_by"], _blocked
    #  THE OUTPUT IS SCREENED TOO — a request can pass and the answer still carry the subject
    _out = _aio.run(_u.intercept({"intent": "generic", "text": "a question"}, _bad_output))
    assert _out.status == "blocked" and "theological_proof" in _out.guardrails["escalated_by"], _out
    #  AND THE LIMITS TRAVEL WITH AN ALLOWED RESULT. Their absence on a success would read as a
    #  clearance, which is exactly what these screens cannot give.
    _ok = _aio.run(_u.intercept({"intent": "generic", "text": "what is the weather"}, _benign))
    assert _ok.status == "allowed", _ok.status
    assert _ok.guardrails is not None, (
        "an allowed result carries no guardrail report, so the absence of one reads as a clearance")
    assert _ok.guardrails["certifies_absence"] is False, _ok.guardrails

    # ── L7. THE SURFACE SHOWS EVERY LIMIT AND THE UNFILLED FIELD ────────────────────────────────
    _resp = client.get("/api/v1/horizon/guardrails")
    assert _resp.status_code == 200, (_resp.status_code, _resp.text[:200])
    _j = _resp.json()
    assert len(_j["gates"]) == 3, _j
    for _gate in _j["gates"]:
        assert (_gate["limit"] or "").strip(), (_gate["gate"], "no limit on the surface")
        assert _gate["certifies_absence"] is False, _gate
    #  THREE-STATE, and the API must agree with the gate rather than reading the constant round the back.
    assert _j["distress_routes_supplied"] is (_j["distress_routes"] is not None), _j
    assert _j["distress_routes_state"] in ("NOT_SUPPLIED", "SUPPLIED_STALE", "SUPPLIED_FRESH"), _j
    if _j["distress_routes"] is None:
        assert "NOT SUPPLIED" in _j["distress_routes_basis"], _j["distress_routes_basis"]
        assert _j["distress_routes_state"] == "NOT_SUPPLIED", _j
    else:
        for _r in _j["distress_routes"]:
            for _f in ("route", "reviewed_by", "checked_on", "jurisdiction"):
                assert str(_r.get(_f) or "").strip(), (_f, "the API publishes a route without it", _r)
        #  a route for one named place must not report that it covers everywhere
        if not _j["distress_routes_cover_anywhere"]:
            assert _j["distress_routes_jurisdictions"], (
                "no jurisdiction is named and the route does not claim to cover everywhere", _j)
    assert _j["escalation_defaults_on_when_undecidable"] is True, _j
    #  the canon's refusals are restated unrelaxed, including A.9.5
    _unchanged = " ".join(_j["unchanged_refusals"]).lower()
    for _needle in ("never generated", "quran.com", "never scored", "labelled", "a.9.5"):
        assert _needle in _unchanged, (_needle, _j["unchanged_refusals"])
    assert "spiritual state" in _unchanged, _j["unchanged_refusals"]
    #  and nothing in this module assesses the person asking
    assert "nothing in this module assesses the person asking" in _clean["fitrah_note"], _clean

    # ── L8. AND THE PAGE RENDERS THE UNFILLED FIELD rather than a fallback of its own ───────────
    def _uncommented(text: str, needle: str) -> list:
        return [ln for ln in text.splitlines()
                if needle in ln and not ln.strip().startswith(("//", "{/*", "/*", "*", "{ /*"))]

    _page = (_root / "apps/workstation-superapp/src/pages/governance/HorizonGuardrails.tsx").read_text(
        encoding="utf-8")
    assert _uncommented(_page, "distress_routes_supplied"), (
        "the page does not branch on whether a route was supplied")
    #  THE RENDERED FORM, not the name. The page's TypeScript interface DECLARES this field, which is an
    #  uncommented line containing it, so a presence check passed with the rendered paragraph replaced by
    #  an invented sentence. Asserting the JSX expression is what proves the backend's words reach a
    #  reader.
    assert _uncommented(_page, "{g.distress_routes_basis}"), (
        "the page does not RENDER the backend's own account of the unfilled field; naming the field in a "
        "type declaration is not printing it, and a second wording is a second place a placeholder can "
        "appear")
    assert _uncommented(_page, "Not supplied"), "the page does not render the field as unfilled"
    #  no second wording of that field: a fallback string is a second place a placeholder could appear
    assert "??" not in " ".join(_uncommented(_page, "distress_routes_basis")), _page[:1]
    #  every gate card shows its limit
    assert _uncommented(_page, "gate.limit"), "the page shows a gate without its limit"
    assert _uncommented(_page, "certifies_absence"), "the page shows a verdict without that caveat"
    #  and it is REACHED: routed and offered in the navigation, ACTIVE lines not merely present ones
    _app = (_root / "apps/workstation-superapp/src/App.tsx").read_text(encoding="utf-8")
    assert _uncommented(_app, 'path="/horizon-guardrails"'), "the page is not routed"
    _side = (_root / "apps/workstation-superapp/src/components/layout/Sidebar.tsx").read_text(
        encoding="utf-8")
    assert _uncommented(_side, "id: 'horizon-guardrails'"), "the page is routed but in no navigation"


def test_w552_the_asset_index_counts_match_a_recount_and_no_secret_is_indexed(client, tmp_path,
                                                                              monkeypatch):
    """P2.13's bar: the manifest's counts match a re-count; every state is asserted; nothing unread is in
    the knowledge base; no secret is indexed.

    The inbox is a REAL directory this test fills, so all three states come from files on disk rather
    than from a constructed manifest — a count over a dict this test built would prove nothing about the
    scan that produces one.
    """
    import pathlib
    from agentic_core.horizon import archive as _A

    _root2b = pathlib.Path(__file__).resolve().parents[1]
    _inbox = pathlib.Path(_A._inbox())
    _inbox.mkdir(parents=True, exist_ok=True)

    #  one of each state, plus every secret rule the item names
    (_inbox / "w552_notes.md").write_text("The halal bakery plan mentions ovens and flour.",
                                          encoding="utf-8")
    (_inbox / "w552_report.pdf").write_bytes(b"%PDF-1.4 not really a pdf")
    (_inbox / ".env").write_text("SECRET_TOKEN=w552shouldnotbeindexed", encoding="utf-8")
    (_inbox / "w552_api_key.txt").write_text("w552keyleak", encoding="utf-8")
    (_inbox / "w552_secret.txt").write_text("w552secretleak", encoding="utf-8")
    #  no nested quoting: the marker is all this file needs to carry, and a JSON literal here only
    #  invites an escaping mistake in the patch that writes it
    (_inbox / "credentials.json").write_text("w552credleak", encoding="utf-8")
    (_inbox / "id_rsa").write_text("w552rsaleak", encoding="utf-8")
    (_inbox / "w552_cert.pem").write_text("w552pemleak", encoding="utf-8")

    _m = _A.scan()

    # ── L1. EVERY STATE IS ASSERTED, and each file carries exactly one ───────────────────────────
    _by = {f["path"]: f for f in _m["files"]}
    assert _by["w552_notes.md"]["state"] == _A.INDEXED, _by["w552_notes.md"]
    assert _by["w552_report.pdf"]["state"] == _A.NOT_READ, _by["w552_report.pdf"]
    #  the missing extractor is NAMED, not merely implied
    assert _by["w552_report.pdf"].get("needs") == "pypdf", _by["w552_report.pdf"]
    assert "pypdf" in _by["w552_report.pdf"]["basis"], _by["w552_report.pdf"]["basis"]
    for _f in _m["files"]:
        assert _f["state"] in (_A.INDEXED, _A.NOT_READ, _A.EXCLUDED), (_f["path"], _f["state"])
        assert (_f.get("basis") or "").strip(), (_f["path"], "a state with no basis")

    # ── L2. THE COUNTS MATCH A RE-COUNT — derived again, not read back ──────────────────────────
    _rc = _A.recount()
    assert _rc["agrees"] is True, ("the published counts disagree with a re-count of the same list",
                                   _rc["stated"], _rc["recounted"])
    #  AND THE RE-COUNT CAN DISAGREE, which asserting agreement alone does not establish. A sweep proved
    #  it: a recount that simply returns the stored counts agrees every time, so the check could not
    #  fail. The stored counts are corrupted here and the recount must notice — an instrument that has
    #  never been seen to disagree is not evidence that two things match.
    import json as _json
    _idx_path = _A._store()
    _saved_bytes = pathlib.Path(_idx_path).read_bytes()
    try:
        _doc = _json.loads(_saved_bytes.decode("utf-8"))
        _doc["manifest"]["counts"][_A.INDEXED] = _doc["manifest"]["counts"][_A.INDEXED] + 7
        pathlib.Path(_idx_path).write_bytes(_json.dumps(_doc).encode("utf-8"))
        _bad = _A.recount()
        assert _bad["agrees"] is False, (
            "the re-count agreed with counts this test had just corrupted, so it is reading them back "
            "rather than deriving them from the file list", _bad)
        assert "DISAGREE" in _bad["basis"], _bad["basis"]
    finally:
        pathlib.Path(_idx_path).write_bytes(_saved_bytes)
    assert _A.recount()["agrees"] is True, "the restore did not put the manifest back"
    #  and the three states partition the list: a file in no state is a file the manifest lost
    assert sum(_m["counts"].values()) == _m["total"] == len(_m["files"]), (_m["counts"], _m["total"])
    #  the counts are recomputed HERE too, so the module's own recount cannot be the only witness
    for _s in (_A.INDEXED, _A.NOT_READ, _A.EXCLUDED):
        assert _m["counts"][_s] == sum(1 for f in _m["files"] if f["state"] == _s), (_s, _m["counts"])

    # ── L3. NO SECRET IS INDEXED, and every exclusion names its rule ────────────────────────────
    _secrets = {".env": "w552shouldnotbeindexed", "w552_api_key.txt": "w552keyleak",
                "w552_secret.txt": "w552secretleak", "credentials.json": "w552credleak",
                "id_rsa": "w552rsaleak", "w552_cert.pem": "w552pemleak"}
    for _name, _marker in _secrets.items():
        assert _name in _by, (_name, "a secret file is not even LISTED, so its exclusion is invisible")
        assert _by[_name]["state"] == _A.EXCLUDED, (_name, _by[_name]["state"])
        assert (_by[_name].get("rule") or "").strip(), (_name, "excluded with no rule recorded")
        #  AND ITS CONTENT IS NOWHERE IN THE INDEX. Driven through search, which is what a reader uses.
        _hit = _A.search(_marker)
        assert _hit["hits"] == [], (
            f"{_name}'s content is searchable, so a secret reached the index", _marker, _hit["hits"])
    #  the stored token map holds no entry for any excluded file at all
    _stored = _A._read_index().get("tokens") or {}
    for _name in _secrets:
        assert _name not in _stored, (f"{_name} has tokens in the index", _name)

    # ── L4. NOTHING UNREAD IS IN THE KNOWLEDGE BASE (the FU-124 rule) ───────────────────────────
    assert "w552_report.pdf" not in _stored, (
        "an unread file has tokens in the index; nothing unread may be in the knowledge base")
    _s = _A.search("halal")
    assert _s["hits"] == ["w552_notes.md"], _s["hits"]
    #  and the search NAMES what it could not look inside, rather than leaving the gap silent
    assert "w552_report.pdf" in _s["not_searched"], _s["not_searched"]
    for _name in _secrets:
        assert _name in _s["not_searched"], (_name, _s["not_searched"])
    assert "nothing unread is in the knowledge base" in _s["basis"], _s["basis"]

    # ── L5. THE SCAN STATES ITS OWN BOUNDS, and a file over the cap is listed not truncated ─────
    _b = _m["bounds"]
    assert _b["max_files"] and _b["max_bytes"], _b
    assert _b["exclusion_rules"] and len(_b["exclusion_rules"]) >= 5, _b["exclusion_rules"]
    assert "not silently truncated" in _b["basis"], _b["basis"]
    _big = _inbox / "w552_big.txt"
    _big.write_text("w552bigmarker " * 200000, encoding="utf-8")   # comfortably over the 2 MiB cap
    _m2 = _A.scan()
    _bigrec = {f["path"]: f for f in _m2["files"]}["w552_big.txt"]
    assert _bigrec["state"] == _A.NOT_READ, (_bigrec["state"], "an oversized file was read anyway")
    assert str(_A.MAX_BYTES) in _bigrec["basis"], _bigrec["basis"]
    assert _A.search("w552bigmarker")["hits"] == [], (
        "an oversized file's text reached the index, so a half-read document is answering questions")

    # ── L6. SEARCH IS LEXICAL AND SAYS SO — it does not imply semantic recall ───────────────────
    assert _m2["embedding_backend"] is None, _m2["embedding_backend"]
    assert "no embedding" in _m2["search_basis"].lower(), _m2["search_basis"]
    assert _A.search("halal")["embedding_backend"] is None
    #  a document ABOUT the subject that never uses the word does not match, and the basis says so
    assert "not semantic recall" in _A.search("halal")["basis"], _A.search("halal")["basis"]

    # ── L7. THE OWNER'S RULING IS DECLARED: both extractors in requirements ─────────────────────
    _req = (pathlib.Path(__file__).resolve().parents[1] / "requirements.txt").read_text(encoding="utf-8")
    for _pkg in ("pypdf", "python-docx"):
        assert any(ln.strip().startswith(_pkg + "==") for ln in _req.splitlines()), (
            f"{_pkg} is not declared in requirements.txt; the Owner's ruling (FU-269) is both extractors")
    #  and the manifest reports their LOCAL state honestly, which is not the same as being declared
    assert set(_m2["extractors"]) >= {"pypdf", "python-docx"}, _m2["extractors"]
    for _pkg, _avail in _m2["extractors"].items():
        assert _avail is _A.extractor_available(_pkg), (_pkg, "the manifest disagrees with the import")

    # ── L8. AND IT IS REACHED, with the re-count beside the published counts ────────────────────
    assert client.post("/api/v1/horizon/archive/scan").status_code == 200
    _resp = client.get("/api/v1/horizon/archive")
    assert _resp.status_code == 200, _resp.status_code
    _j = _resp.json()
    assert _j["recount"]["agrees"] is True, _j["recount"]
    assert _j["manifest"]["counts"] == _j["recount"]["recounted"], _j
    assert "never committed" in _j["manifest"]["locality_basis"], _j["manifest"]["locality_basis"]
    #  AND THE CLAIM IS ENFORCED, not merely stated. "never committed" is a basis string, and a basis
    #  string nothing enforces is the defect class this plan keeps removing — so git itself is asked.
    #  (Checked while writing this: a first look at .gitignore missed the blanket rule because the grep
    #  was truncated, and `git check-ignore` is what settled it. Ask the tool that decides.)
    import subprocess as _sp
    _rel = "data/horizon/asset_index.json"
    try:
        _ci = _sp.run(["git", "check-ignore", "-q", _rel], cwd=str(_root2b), capture_output=True)
        _git_ran = _ci.returncode in (0, 1)
    except (OSError, FileNotFoundError):
        _git_ran = False
    if _git_ran:
        assert _ci.returncode == 0, (
            f"{_rel} is NOT ignored by git, so the manifest's 'never committed' claim is a sentence "
            f"nothing enforces and one `git add -A` would publish the index")
    _sr = client.get("/api/v1/horizon/archive/search", params={"term": "halal"})
    assert _sr.status_code == 200 and "not_searched" in _sr.json(), _sr.json()


def test_w553_four_constraints_assess_fifteen_refuse_by_name_and_three_may_never_score(client):
    """FU-358: the declared constitutional constraints get instruments where one exists and a named
    refusal where none does — and the chain gains a third state so it withholds for a reason.

    Every validator's states are DRIVEN, including the breach paths, because a validator that has only
    ever been seen to pass is a validator nobody has watched work.
    """
    import asyncio as _aio
    from agentic_core.validation import constitutional_validators as _V
    from agentic_core.validation.enforcement_pattern import ValidationResult
    from agentic_core.validation.omni_enforcement_pattern_supreme import OmniEnforcementPatternSupreme

    # ── L1. EVERY DECLARED CONSTRAINT IS REGISTERED — four assessing, the rest refusing by name ───
    _p = OmniEnforcementPatternSupreme({}, {"task": "w553-guard"})
    _declared = [n for ph in sorted(_p.phases) for n in _p.phases[ph]]
    _rep = _V.register_all(_p)
    assert sorted(_p.validators) == sorted(_declared), (
        "a declared constraint has no registered validator at all, so the chain falls through to its "
        "missing-validator branch rather than reporting what cannot be checked",
        sorted(set(_declared) - set(_p.validators)))
    assert sorted(_rep["assessing"]) == sorted(_V.ASSESSING), _rep["assessing"]
    assert len(_rep["refusing"]) == len(_declared) - len(_V.ASSESSING), _rep
    #  EVERY refusal carries a REASON. "not implemented" tells a reader nothing about what would change it.
    for _name in _rep["refusing"]:
        _r = _p.validators[_name].validate("anything")
        assert _r.passed is None, (_name, "a constraint with no instrument returned a verdict", _r.passed)
        assert _name in _V.NO_INSTRUMENT, (_name, "refuses with no recorded reason")
        assert len(_V.NO_INSTRUMENT[_name]) > 60, (_name, "the reason is too thin to act on")
        assert _r.details.get("no_instrument") is True, (_name, _r.details)

    # ── L2. THREE NAMES MAY NEVER BECOME A SCORE ─────────────────────────────────────────────────
    #  Each is a judgement about an argument or about a PERSON, and the last engages Ruling A.9.5
    #  directly. A number for any of them would be the most believable fabrication available, because it
    #  would look like a measurement of method or of character.
    assert set(_V.NEVER_A_SCORE) == {"statistical_rigor", "first_principles_grounding",
                                     "sincerity_integrity_loyalty"}, _V.NEVER_A_SCORE
    for _name in _V.NEVER_A_SCORE:
        assert _name not in _V.ASSESSING, (_name, "a name that must never score has an instrument")
        assert "MUST NEVER BECOME A SCORE" in _V.NO_INSTRUMENT[_name], _V.NO_INSTRUMENT[_name]
        _r = _p.validators[_name].validate("any text at all")
        assert _r.passed is None, (_name, _r.passed)
        #  and nothing numeric comes back under any key
        for _k, _v in (_r.details or {}).items():
            assert not isinstance(_v, (int, float)) or isinstance(_v, bool), (_name, _k, _v)
    assert "A.9.5" in _V.NO_INSTRUMENT["sincerity_integrity_loyalty"], (
        "the one constraint that would grade a person's inner state does not cite the ruling forbidding it")

    # ── L3. THE PLACEHOLDER VALIDATOR CATCHES A BREACH, and states its own limit ─────────────────
    _zp = _V.ZeroPlaceholder()
    for _bad in ("this section is a TODO", "lorem ipsum dolor sit amet", "coming soon",
                 "not yet implemented", "a dummy value for now", "FIXME before shipping"):
        _r = _zp.validate(_bad)
        assert _r.passed is False, (_bad, "a placeholder passed the placeholder screen", _r.passed)
        assert _r.violation == "zero_placeholder", _r
    _ok = _zp.validate("A plainly written answer with ordinary varied words and no markers.")
    assert _ok.passed is True, _ok.basis
    #  THE LIMIT IS STATED: it catches the DECLARED placeholder, not an unlabelled stub
    assert "not the undeclared one" in _ok.basis, _ok.basis
    #  and it fails closed on something it cannot read
    for _unreadable in (None, "", "   ", 42):
        assert _zp.validate(_unreadable).passed is None, (_unreadable, "an unscreenable subject passed")

    # ── L4. THE THERMODYNAMIC VALIDATOR READS THE LEDGER'S RECORD, three-state ───────────────────
    _ta = _V.ThermodynamicAccountability()
    assert _ta.validate("x", {}).passed is None, "no metering record should be NOT ASSESSABLE"
    assert "nothing handed its record" in _ta.validate("x", {}).basis, _ta.validate("x", {}).basis
    #  an action that ran WITHOUT being metered is a breach, not an absence
    assert _ta.validate("x", {"metering": {"metered": False, "basis": "the ledger was unavailable"}}
                        ).passed is False
    #  metered=True with no bits is a record of nothing
    assert _ta.validate("x", {"metering": {"metered": True, "entropy_bits": 0}}).passed is False
    _good = _ta.validate("x", {"metering": {"metered": True, "entropy_bits": 4096.0}})
    assert _good.passed is True, _good.basis
    #  and the Landauer limit is carried, not dropped: a floor is not an energy drawn
    assert "not the number of bits ERASED" in _good.basis, _good.basis

    # ── L5. THE OTHER TWO DELEGATE rather than keeping a second screen ───────────────────────────
    #  constitutional_compliance must use the SAME screen the interceptor runs, so there is no second
    #  list of forbidden patterns to drift from it.
    _cc = _V.ConstitutionalCompliance()
    from agentic_core.gaas.v5.policy_gate import ConstitutionalPolicyGate as _PG
    _unsafe = "run rm -rf / on the host"
    assert _PG().validate_output(_unsafe)["compliant"] is False, "the gate itself does not flag this"
    assert _cc.validate(_unsafe).passed is False, "the validator disagrees with the gate it delegates to"
    assert _cc.validate("an ordinary sentence").passed is True
    assert "SAME screen" in _cc.validate(_unsafe).basis, _cc.validate(_unsafe).basis
    #  hallucination_containment carries W415's limit forward: two heuristics, and fidelity is NOT measured
    _hc = _V.HallucinationContainment().validate("Varied ordinary prose about bakeries and ovens here.")
    assert _hc.passed in (True, None), _hc.basis
    if _hc.passed is True:
        assert "NOTHING IN THIS REPOSITORY MEASURES FIDELITY" in _hc.basis, _hc.basis
        assert "never that the output was verified" in _hc.basis, _hc.basis

    # ── L6. THE CHAIN'S THIRD STATE — and it cannot clear on a subset ────────────────────────────
    _r = _p.validate("A plainly written answer with ordinary varied words and no markers.")
    assert _r.passed is None, ("the chain CLEARED while most constraints had no instrument, which is the "
                               "certifies-an-absence defect one level above the screens", _r.passed)
    assert "NOT CLEARED" in _r.basis, _r.basis
    #  the two kinds of unassessable are reported SEPARATELY: nothing can check this, versus nothing
    #  handed this check its input. Different facts, different fixes.
    assert _r.details["no_instrument"] and "thermodynamic_accountability" in _r.details["input_absent"], (
        _r.details)
    assert "NO INSTRUMENT" in _r.basis and "not given its input" in _r.basis, _r.basis
    #  A REAL BREACH STILL STOPS THE CHAIN, unchanged
    _bad = _p.validate("this is a TODO placeholder")
    assert _bad.passed is False and _bad.violation == "zero_placeholder", _bad
    #  AND IT CAN CLEAR when everything is assessed and passes — otherwise the pass state is unreachable
    class _Clear:
        def validate(self, target, context=None):
            return ValidationResult(passed=True, basis="driven by the guard")
    _all = OmniEnforcementPatternSupreme({}, {"task": "w553-clear"})
    for _n in [n for ph in sorted(_all.phases) for n in _all.phases[ph]]:
        _all.register_validator(_n, _Clear())
    assert _all.validate("anything").passed is True, "the chain can never clear, so True is unreachable"
    #  ZERO CONSTRAINTS IS NOT A PASS — reachable, because the clearance chain disables the
    #  missing-validator refusal, so before this round it cleared over nineteen skipped constraints
    _empty = OmniEnforcementPatternSupreme({"fail_on_missing_validator": False}, {})
    assert _empty.validate("anything").passed is None, (
        "a pattern with nothing registered reported a clearance over zero checks")
    assert "Zero checks" in _empty.validate("anything").basis, _empty.validate("anything").basis

    # ── L7. BOTH CONSTRUCTION SITES REGISTER — and only one of them CONSULTS the pattern ────────
    #  The chain registers and never calls validate (FU-364, grepped then driven). That is said here
    #  rather than asserted away, because a leg claiming the chain enforces would be the over-claim
    #  this round exists to remove. What IS asserted of the chain is registration; reach is L8's job.
    from agentic_core.avatars.core.clearance_chain import ConstitutionalClearanceChain
    from agentic_core.ueg.logger import VSBUEGLogger as _VSBUEG
    _chain = ConstitutionalClearanceChain(_VSBUEG(), None)
    assert getattr(_chain, "enforcement_registry", None), (
        "the clearance chain does not register the validators at construction, so they are beside the "
        "path rather than on it — the reach failure this plan keeps finding")
    assert sorted(_chain.enforcement.validators) == sorted(_declared), (
        "the chain's own pattern is missing constraints", sorted(_chain.enforcement.validators))
    from agentic_core.avatars.core.avatar_engine import AvatarState
    from agentic_core.avatars.core.recirculation_orchestrator import AvatarRecirculationOrchestrator
    _orch = AvatarRecirculationOrchestrator(_VSBUEG(), AvatarState(avatar_id="w553", user_id="w553"))
    assert getattr(_orch, "enforcement_registry", None), (
        "the recirculation orchestrator does not register the validators at construction")
    assert sorted(_orch.enforcement.validators) == sorted(_declared), sorted(_orch.enforcement.validators)

    # ── L8. THE LIVE PATH, DRIVEN — the verdict and its figures reach the pipeline's own surface ──
    #  The orchestrator's pattern is the one that is consulted: it is handed to the VRPR pipeline and to
    #  the cognitive orchestrator. A registry nobody reads proves nothing, so this leg RUNS the pipeline.
    assert _orch.vrpr.enforcement is _orch.enforcement, (
        "the pipeline holds a DIFFERENT enforcement pattern from the one the orchestrator registered, so "
        "the registration is beside the path it was meant to be on")
    import warnings as _warnings
    with _warnings.catch_warnings(record=True) as _caught:
        _warnings.simplefilter("always")
        _final = _aio.run(_orch.vrpr.process("A plainly written answer with ordinary varied words.", {}))
    #  A LEAKED COROUTINE IS A FINDING, not noise: the async refusal was first written as asyncio.run
    #  inside a try, which built the coroutine before the call that refused it, so every refusal on this
    #  path emitted "was never awaited". The refusal now reads the running loop BEFORE creating anything.
    _leaked = [str(_w.message) for _w in _caught if "never awaited" in str(_w.message)]
    assert not _leaked, ("a coroutine was constructed and abandoned on the live refusal path", _leaked)
    _vb = getattr(_final, "verification_basis", "") or ""
    assert getattr(_final, "verification_passed", "unset") is None, (
        "the pipeline reported a verdict other than None while constraints are unassessable", _final)
    assert "of 19 declared constraint(s) were assessed" in _vb, (
        "the chain's own sentence does not reach the pipeline's surface, so the three-state verdict is a "
        "fact in a dict rather than something a reader is told", _vb)
    #  AND THE TWO KINDS TRAVEL, by name, all the way out: this is the field a reader acts on.
    assert "NO INSTRUMENT" in _vb and "not given its input" in _vb, _vb
    assert "thermodynamic_accountability" in _vb, (
        "the constraint whose instrument exists and was handed no input is not named on the surface", _vb)
    #  AND THE STALE PREMISE IS GONE. This sentence explained the full pass count by "no validator is
    #  registered", which stopped being true in this round while its conclusion stayed correct.
    _cb = getattr(_final, "confidence_basis", "") or ""
    assert "no validator" not in _cb, (
        "the confidence basis still explains the pass count by an absence this round removed", _cb)
    assert "cannot clear while a declared constraint has no instrument" in _cb, _cb


def test_w554_the_horizon_seam_observes_and_records_and_does_not_gate(client):
    """FU-360: P2.11's seam — a middleware in front of the domain routes and a hook at record_outcome.

    THE WHOLE POINT IS THAT IT DOES NOT GATE, so the legs drive what it records rather than what it stops,
    and the one thing they refuse to let drift is the sentence saying nothing acted on the decision.
    """
    from agentic_core.horizon import kernel as _k
    from agentic_core.horizon import membrane as _m

    def _rows(source):
        return [r for r in _k.listing(10000) if r.get("source") == source]

    # ── L1. WHAT IS OBSERVED AND WHAT IS NOT, with a reason for every exclusion ───────────────────
    for _m_, _p, _want in (("POST", "/api/v1/law/analyse", True),
                           ("PATCH", "/api/v1/education/plan", True),
                           ("DELETE", "/api/v1/care/x", True),
                           ("GET", "/api/v1/law/analyse", False),       # a read is not a request to act
                           ("POST", "/api/v1/horizon/observe", False),  # not a domain route
                           ("POST", "/api/v1/lawyers/x", False)):       # NOT a prefix match on a segment
        _ok, _why = _m.observes(_m_, _p)
        assert _ok is _want, (_m_, _p, _ok, _why)
        assert len(_why) > 40, (_m_, _p, "an exclusion with no reason a reader could act on", _why)
    #  THE SEGMENT BOUNDARY, named because `startswith` alone would make /api/v1/lawyers a law request
    assert _m.domain_of("/api/v1/lawyers/x") is None, "a prefix matched across a path segment boundary"
    assert _m.domain_of("/api/v1/law") == "law" and _m.domain_of("/api/v1/law/analyse") == "law"

    # ── L2. A SERVED DOMAIN POST IS OBSERVED, AND THE ROW SAYS NOTHING ACTED ON IT ────────────────
    _before = len(_rows("domain_route"))
    _r = client.post("/api/v1/law/analyse", json={"document_text": "A short agreement, two parties."})
    assert _r.status_code == 200, _r.text
    _d = _rows("domain_route")
    assert len(_d) == _before + 1, ("the middleware did not observe a mutating domain request, so the "
                                   "seam is beside the path rather than on it", _before, len(_d))
    _row = _d[0]
    assert _row.get("gated") is False, ("the row does not record that nothing gated it", _row.get("gated"))
    assert "did not escalate anything" in (_row.get("gating_basis") or "").lower(), _row.get("gating_basis")
    assert _row.get("served") is True and _row.get("response_status") == 200, _row
    #  THE BODY IS NEVER READ, and the row says so rather than leaving it to be assumed.
    assert _row.get("body_read") is False and len(_row.get("body_basis") or "") > 80, _row
    assert "A short agreement" not in json.dumps(_row), (
        "the request body reached the store, which this seam states it does not read")

    # ── L3. THE COMPRESSION REASON IS THE SEAM'S OWN, not the floor's and not a failed call ───────
    assert _row.get("compression") == _k.NOT_COMPRESSED, _row.get("compression")
    assert "NO COMPRESSOR WAS CALLED" in (_row.get("compression_basis") or ""), _row.get("compression_basis")
    #  and the three other reasons remain distinguishable — a shared sentence would attribute the
    #  absence to a component that never ran
    _floor = _k._compression_of("native", False, False, "text came back")
    _empty = _k._compression_of("llama3.2", False, True, "")
    _real = _k._compression_of("llama3.2", False, False, "asked_for: a thing")
    assert "NO COMPRESSOR WAS CALLED" not in _floor["compression_basis"], _floor
    assert "NO COMPRESSOR WAS CALLED" not in _empty["compression_basis"], _empty
    assert _real["compression"] == _k.COMPRESSED, _real
    assert len({_floor["compression_basis"], _empty["compression_basis"],
                _k._compression_of(None, False, False, "", compressor_called=False)["compression_basis"]
                }) == 3, "two of the NOT_COMPRESSED reasons are the same sentence"

    # ── L4. A REQUEST THE APP REFUSED IS NOT COUNTED AS DOMAIN ACTIVITY ───────────────────────────
    #  Driven, because the first draft of this seam observed BEFORE routing and recorded a 405 as a law
    #  request — a row indistinguishable from one the platform served.
    _n = len(_rows("domain_route"))
    _bad = client.post("/api/v1/law/templates", json={})
    assert _bad.status_code in (404, 405), _bad.status_code
    _d2 = _rows("domain_route")
    assert len(_d2) == _n + 1, "the refused request was not observed at all"
    _refused = [r for r in _d2 if r.get("response_status") in (404, 405)]
    assert _refused and _refused[0].get("served") is False, _refused[:1]
    assert "NOT SERVED" in (_refused[0].get("served_basis") or ""), _refused[0].get("served_basis")

    # ── L5. THE RECORD_OUTCOME HOOK — the run kinds, and the one that is excluded ─────────────────
    from agentic_core.api.operational_excellence import record_outcome as _ro
    _o = len(_rows("run_outcome"))
    _ro("ai_call", "agent:w554", served_by="native", success=True)
    assert len(_rows("run_outcome")) == _o + 1, "a run outcome was not observed"
    _ro("model_attempt", "model:w554", served_by="w554", success=True)
    assert len(_rows("run_outcome")) == _o + 1, (
        "model_attempt was observed: it is a mechanism INSIDE one run, so observing it makes the count "
        "of observed intents stop meaning the number of requests")
    assert "model_attempt" in _m.NOT_OBSERVED_KINDS and len(_m.NOT_OBSERVED_KINDS["model_attempt"]) > 80
    _last = _rows("run_outcome")[0]
    #  THE RUN'S SERVER IS NOT THE COMPRESSION'S. Reading one as the other would manufacture a
    #  COMPRESSED record for a compression that never happened.
    assert _last.get("run_served_by") == "native" and _last.get("served_by") is None, _last
    assert _last.get("compression") == _k.NOT_COMPRESSED, _last.get("compression")

    # ── L6. THE ROUTE'S DOMAIN IS NOT WRITTEN INTO THE KERNEL'S `domain` FIELD ────────────────────
    #  If it were, a request on the LAW route would stop failing closed — the escalation list holds
    #  'legal', and the string 'law' contains none of its words — so the record would read PROCEED on a
    #  legal matter nobody compressed.
    assert _row.get("route_domain") == "law", _row.get("route_domain")
    assert "domain" not in _row, (
        "the seam filled the kernel's compression field `domain` from the URL, which is a true fact "
        "about where the request arrived and a false answer to what it was about", _row.get("domain"))
    assert _row.get("decision") == _k.ESCALATE, _row.get("decision")
    #  and the trap is REAL, not hypothetical: with the route name in `domain`, the kernel proceeds.
    _forged = {**_row, "domain": "law"}
    assert _k.decide(_forged)["decision"] == _k.PROCEED, (
        "this leg's premise is wrong: putting the route name in `domain` did NOT flip the decision, so "
        "the reason for keeping them apart needs re-stating from what the kernel actually does")

    # ── L7. AND THE SURFACE SAYS ALL OF IT — the limits, the counts, the failures ─────────────────
    _s = client.get("/api/v1/horizon/seam")
    assert _s.status_code == 200, _s.text
    _j = _s.json()
    assert _j["gates"] is False, "the surface does not state that the seam gates nothing"
    assert _j["observed_total"] >= 3 and _j["observed_not_served"] >= 1, _j
    assert _j["error_count"] == 0, ("the seam failed to observe something and counted it — which is the "
                                    "design working, but it must not be happening in a clean run", _j)
    #  AND A FAILURE MUST BE SEEN TO BE COUNTED. A blind proved the leg above VACUOUS: deleting the line
    #  that records an error leaves error_count at 0, which is exactly what a clean run reports, so the
    #  assertion passed with the defect in. The seam SWALLOWS exceptions by design — it must never turn a
    #  failure to observe into a failure to serve — and a swallowed failure nobody counts is
    #  indistinguishable from a path the seam never reached. So the failure is driven.
    _real_save = _k.save
    try:
        def _raises(*_a, **_kw):
            raise RuntimeError("driven: the store could not be written")
        _k.save = _raises
        assert _m.observe_outcome("ai_call", "agent:w554_fail", served_by="native") is None, (
            "a failed observation returned a row")
    finally:
        _k.save = _real_save
    _j2 = client.get("/api/v1/horizon/seam").json()
    assert _j2["error_count"] == 1, ("the seam swallowed a failure WITHOUT counting it, so a store it "
                                     "cannot write to is indistinguishable from a path nothing reaches",
                                     _j2["error_count"], _j2.get("errors"))
    assert "RuntimeError" in _j2["errors"][0], _j2["errors"]
    #  and serving was never affected — the whole reason it swallows
    assert client.get("/api/v1/horizon/states").status_code == 200
    assert "ESCALATE" in _j["observed_decisions"], _j["observed_decisions"]
    #  THE DECISION CANNOT VARY, and the surface says so. A constant column a reader reads variation
    #  into is worse than no column.
    assert "BY CONSTRUCTION" in _j["decision_is_constant"], _j["decision_is_constant"]
    #  THE CAP MUST BE APPLIED, NOT MERELY REPORTED. A blind proved this leg VACUOUS when it read
    #  _CAP from the module and compared it to the surface: removing the slice from save() leaves the
    #  constant in place, so both still said 2000 while the store grew without bound. The bound is now
    #  DRIVEN against a small cap, which is also the only way to drive it at all — writing 2000 rows to
    #  prove a 2000-row cap would make this test the slowest in the suite.
    assert _j["store_cap"] == _k._CAP and _k._CAP > 0, (
        "the surface does not report the store's cap at all")
    _real_cap = _k._CAP
    try:
        _k._CAP = 3
        for _i in range(6):
            _m.observe_outcome("ai_call", f"agent:w554_cap_{_i}", served_by="native")
        _held = _k.listing(10000)
        assert len(_held) <= 3, (
            "the horizon store did not apply its cap while a middleware and a run hook write to it — an "
            "unbounded whole-file read-modify-write, and a surface reporting a bound nothing enforces",
            len(_held), _k._CAP)
        #  OLDEST FIRST, which is what the records route tells a reader: the newest survive.
        assert any("w554_cap_5" in str(_r.get("run_resource")) for _r in _held), (
            "the cap dropped the NEWEST rows, so the listing's oldest row is not the oldest thing kept",
            [_r.get("run_resource") for _r in _held])
    finally:
        _k._CAP = _real_cap
    #  and /records separates what was observed from what a user asked for
    _rec = client.get("/api/v1/horizon/records?limit=50").json()
    assert _rec["observed_not_enforced"] >= 3, _rec
    assert "is not an escalation" in _rec["basis"], _rec["basis"]
    assert _rec["history_cap"] == _k._CAP, _rec

    # ── L9. THE PAGE THAT IMPLIES GATING MUST CARRY THE DENIAL ────────────────────────────────────
    #  /horizon-guardrails is titled Guardrails and is full of gates, so a reader arriving there would
    #  reasonably take the whole of Horizon for something that stops requests. The seam does not stop
    #  anything, and that has to be said on the page that creates the impression — not only on a route.
    import pathlib as _pl
    _page = _pl.Path(__file__).resolve().parents[1] / (
        "apps/workstation-superapp/src/pages/governance/HorizonGuardrails.tsx")
    assert _page.exists(), ("the page this leg reads is not where it was, so the leg measured nothing",
                            str(_page))
    _src = _page.read_text(encoding="utf-8")
    #  THE RENDER, not the interface declaration. A substring check for the field name would match the
    #  `gating_basis: string;` line and pass over a page that never prints it — the presence-check defect
    #  this programme has hit four times.
    assert "{s.gating_basis}" in _src, (
        "the page declares the seam's basis field and never renders it, so the denial of gating exists in "
        "a type and not on the screen")
    assert "{s.decision_is_constant}" in _src, "the page does not print why the decision cannot vary"
    assert "{s.body_basis}" in _src, "the page does not say the request body is never read"
    assert "'Observes · does not gate'" in _src, (
        "the page has no rendered words for the not-gating state, so the claim depends entirely on a "
        "backend sentence a reader may not reach")
    #  AND IT MUST FETCH THE SEAM. A page rendering a field nothing populates shows nothing.
    assert "'/api/v1/horizon/seam'" in _src, "the page never asks the seam for its report"
    #  NO SECOND WORDING. The sentences are load-bearing, so the page must not keep its own copy that
    #  could drift from the backend's — the class W490 named when a page printed a stale claim.
    for _forbidden in ("does not escalate anything", "BY CONSTRUCTION", "OBSERVED, NOT ENFORCED"):
        assert _forbidden not in _src, (
            "the page hard-codes a sentence the backend owns, so the two can drift", _forbidden)
    #  AND A SEAM THAT CANNOT BE READ MUST NOT LEAVE THE PAGE SILENT ABOUT GATING.
    assert "{seamErr}" in _src and "not that it" in _src, (
        "the page does not distinguish 'the seam could not be read' from 'the seam observed nothing'")
    #  NOR MAY A **GUARDRAILS** FAILURE HIDE IT. Measured: the block was first written inside the
    #  `{g && (...)}` fragment, and loading the page while the backend was still booting showed what that
    #  cost — /guardrails answered 500, the page correctly said nothing was received, and the denial of
    #  gating vanished with it, leaving the title and three gate cards as the only statement about
    #  Horizon. A section that appears only when a DIFFERENT request succeeds is not unconditional.
    assert _src.index('data-testid="horizon-seam"') > _src.index("        </>\n      )}\n"), (
        "the seam block sits inside the guardrails conditional, so a guardrails failure hides the page's "
        "only statement that Horizon does not gate")
    #  and it must not displace the distress-route field, which W551 put first for the one reason no
    #  later correction reaches: a person in distress might act on what they read there.
    assert _src.index('data-testid="horizon-distress-routes"') < _src.index('data-testid="horizon-seam"'), (
        "the seam block was placed above the distress-route field")


def test_w555_one_screen_serves_both_paths_and_the_chain_consults_the_constraints_it_holds(client):
    """FU-363 and FU-364: the sandbox's screening is sync so the live path can assess it, and the
    clearance chain finally consults the enforcement pattern it has always constructed.

    Both rows were found by DRIVING W553's own fix rather than by reading it, and both legs below drive
    rather than inspect — the point of each fix is what happens on the path, not what the source says.
    """
    import asyncio as _aio
    import warnings as _warn
    from agentic_core.avatars.core.avatar_engine import AvatarState
    from agentic_core.avatars.core.clearance_chain import ConstitutionalClearanceChain
    from agentic_core.avatars.core.recirculation_orchestrator import AvatarRecirculationOrchestrator
    from agentic_core.governance.gaas.v5.hallucination_sandbox import HallucinationSandbox
    from agentic_core.ueg.logger import VSBUEGLogger as _VSBUEG
    from agentic_core.validation import constitutional_validators as _V
    from agentic_core.validation.enforcement_pattern import ValidationResult as _VR

    # ── L1. ONE SCREEN, NOT TWO — the sync half is the SAME implementation the async wrapper runs ──
    _sb = HallucinationSandbox()
    _text = "Varied ordinary prose about bakeries and ovens and the people who keep them."
    _sync = _sb.screen(_text)
    _async = _aio.run(_sb.validate_output(_text, {}))
    assert _sync["passed"] is True and _async["passed"] is True, (_sync, _async)
    for _k in ("heuristic_score", "hallucinations", "checks_run", "checks_not_run"):
        assert _sync[_k] == _async[_k], ("the sync screen and the async wrapper disagree on " + _k,
                                        _sync[_k], _async[_k])
    #  the wrapper adds the UEG write AND NOTHING ELSE — that is the whole reason it is still async
    assert "fidelity_score" in _async and _async["fidelity_score"] is None, _async
    assert "fidelity_score" not in _sync, (
        "the sync screen reports a fidelity field, which W415 removed because nothing measures fidelity")

    # ── L2. A CHECK THAT COULD NOT RUN IS NOT A CHECK THAT PASSED, and it used to RAISE ────────────
    #  The diversity heuristic divides by the word count. On an output with no words that was a
    #  ZeroDivisionError, and uci_interceptor.py did not guard it.
    _empty = _sb.screen("   ")
    assert _empty["passed"] is None, ("a screen that could not run every heuristic reported a verdict",
                                      _empty)
    assert "lexical_diversity" in _empty["checks_not_run"], _empty
    assert len(_empty["checks_not_run"]["lexical_diversity"]) > 60, _empty["checks_not_run"]
    assert "lexical_diversity" not in _empty["checks_run"], _empty
    #  and it no longer raises through the async wrapper either — AND the wrapper reports the SAME
    #  partial run. A blind proved the earlier form vacuous: the wrapper's checks_run was compared with
    #  the screen's only on text where both heuristics ran, so a hard-coded list of two matched it. The
    #  empty subject is the input that tells a computed list from a constant one.
    _aw = _aio.run(_sb.validate_output("", {}))
    assert _aw["passed"] is None, _aw
    assert _aw["checks_run"] == _empty["checks_run"], (
        "the async wrapper reports checks the screen says did not run — a list of checks is a claim "
        "about what happened, and only the screen knows", _aw["checks_run"], _empty["checks_run"])
    assert "lexical_diversity" not in _aw["checks_run"], _aw["checks_run"]
    assert _aw["checks_not_run"] == _empty["checks_not_run"], (_aw, _empty)
    #  the heuristic that CAN still run, does — a partial screen is partial, not absent
    assert "knowledge_base_contradiction (3-term vocabulary)" in _empty["checks_run"], _empty
    #  and the breach path still fires: repetition trips diversity
    _rep = _sb.screen(" ".join(["same"] * 25))
    assert _rep["passed"] is False and _rep["hallucinations"], _rep

    # ── L3. THE VALIDATOR ASSESSES ON THE LIVE PATH NOW (FU-363) ───────────────────────────────────
    #  It could not before: it called asyncio.run on the async wrapper, which raises inside a running
    #  loop, and the live path is always inside one. The count is the evidence.
    _orch = AvatarRecirculationOrchestrator(_VSBUEG(), AvatarState(avatar_id="w555", user_id="w555"))
    with _warn.catch_warnings(record=True) as _caught:
        _warn.simplefilter("always")
        _final = _aio.run(_orch.vrpr.process("A plainly written answer with ordinary varied words.", {}))
    assert not [w for w in _caught if "never awaited" in str(w.message)], (
        "a coroutine was constructed and abandoned on the live path", [str(w.message) for w in _caught])
    _vb = getattr(_final, "verification_basis", "") or ""
    assert "3 of 19 declared constraint(s) were assessed" in _vb, (
        "hallucination_containment is not assessing on the live path, so the one constraint FU-363 "
        "names is still unreachable where it matters", _vb)
    assert "hallucination_containment" not in _vb.split("not given its input")[-1], (
        "hallucination_containment is still reported as an instrument that was not given its input", _vb)
    #  AND IT IS THE SANDBOX'S VERDICT, not one reached here. A blind proved the earlier form vacuous:
    #  it asserted only that ordinary text PASSES, which a second screen copied into the validator does
    #  too. The validator must track the sandbox across inputs where the answers DIFFER — so the breach
    #  and the partial run are driven through it, not just the pass.
    _hc = _V.ASSESSING["hallucination_containment"]
    for _subject, _want in ((_text, True),
                            (" ".join(["same"] * 25), False),     # repetition trips diversity
                            ("one two three", None)):             # too few words: diversity cannot run
        _screened = _sb.screen(_subject)["passed"]
        _validated = _hc.validate(_subject).passed
        assert _validated is _screened, (
            "the validator disagrees with the sandbox's own screen, so there are two screens here and "
            "they have already drifted", _subject[:30], _validated, _screened)
        if _want is not None:
            assert _validated is _want, (_subject[:30], _validated, _want)

    # ── L4. THE CHAIN CONSULTS THE PATTERN IT HOLDS (FU-364) — gate 6, all three outcomes driven ───
    class _Orch555:
        async def consult(self, emission, engines):
            return {"status": "APPROVED"}

        async def process_engine(self, name, emission, context):
            return {"ratified": True, "balanced": True, "risk_score": 0.0}

        async def verify_output(self, emission):
            return {"verified": True}

    _chain = ConstitutionalClearanceChain(_VSBUEG(), _Orch555())
    assert [k for k, _n, _s in _chain._GATES][-1] == "enforcement", (
        "the enforcement gate is not the last declared gate", _chain._GATES)
    #  (a) CLEARED BY COVERAGE — the ordinary outcome since the Owner's ruling of 2026-10-06 (FU-472, choice 1),
    #  REWRITTEN W607: it used to be NOT CLEARED. The record names every constraint that was not checked.
    _nc = _aio.run(_chain.validate_emission({"id": "g6-a", "text": "ordinary varied words here"}, {}))
    _g6nc = {g["gate"]: g for g in _nc.gates}["enforcement"]
    assert _nc.passed is True and _g6nc["verdict"] == "cleared" and "BY COVERAGE" in _g6nc["basis"], (
        _nc.reason, _g6nc)
    assert len(_g6nc["coverage"]["assessed"]) + len(_g6nc["coverage"]["not_checked"]) == 19, (
        "the coverage record does not account for all 19 declared constraints", _g6nc["coverage"])
    #  (b) A BREACH — named, AND carrying the validator's own basis, which _handle_violation dropped
    _br = _aio.run(_chain.validate_emission({"id": "g6-b", "text": "this section is a TODO"}, {}))
    assert _br.passed is False, _br.reason
    assert "zero_placeholder" in (_br.reason or ""), _br.reason
    assert "placeholder marker(s) in the output" in (_br.reason or ""), (
        "the breach reaches the chain without the evidence for it: the validator named what it found "
        "and _handle_violation discarded the basis", _br.reason)
    #  (c) CLEARED — reachable, so the gate is not a permanent block wearing a gate's clothes
    class _Clear555:
        def validate(self, target, context=None):
            return _VR(passed=True, basis="driven by the guard")
    _chain2 = ConstitutionalClearanceChain(_VSBUEG(), _Orch555())
    for _n in [k for ph in sorted(_chain2.enforcement.phases) for k in _chain2.enforcement.phases[ph]]:
        _chain2.enforcement.register_validator(_n, _Clear555())
    _cl = _aio.run(_chain2.validate_emission({"id": "g6-c", "text": "ordinary varied words here"}, {}))
    assert _cl.passed is True, ("the chain cannot clear even when every constraint assesses and passes",
                                _cl.reason)
    assert [g["verdict"] for g in _cl.gates] == ["cleared"] * len(_chain2._GATES), _cl.gates

    # ── L5. AND NOTHING PRINTS TO STDOUT ON A REFUSAL ─────────────────────────────────────────────
    #  _handle_violation printed "!!! SUPREME CONSTRAINT VIOLATION !!!", which was tolerable while
    #  nothing consulted the pattern and became a line on the live clearance path the moment gate 6
    #  existed — unroutable, unfilterable and unsilenceable.
    import contextlib as _ctx
    import io as _sio
    _buf = _sio.StringIO()
    with _ctx.redirect_stdout(_buf):
        _aio.run(_chain.validate_emission({"id": "g6-d", "text": "lorem ipsum dolor sit amet"}, {}))
    assert _buf.getvalue() == "", ("the clearance path wrote to stdout on a refusal", _buf.getvalue())


def test_w556_friction_becomes_a_governed_change_and_never_a_written_in_root_cause(client):
    """P2.14: a LessonRecord carries evidence and a CANDIDATE cause or none, each disposition names the
    change_type it files, a SUBMIT-ONLY lesson cannot be self-applied, and the register is not forked.

    The brief this item came from had a daemon that wrote a root cause into every record and carried the
    comment "Simulated LLM analysis" beside it. Most of the legs below exist to keep that from returning
    in any form, including the quieter form: a candidate silently promoted to a finding.
    """
    from agentic_core.api.change_control import _TIER_MAP, _load_change
    from agentic_core.horizon import muhasabah as _m

    # ── L1. THE THREE TRIGGERS, and a default cause of NOT DETERMINED ─────────────────────────────
    assert _m.TRIGGERS == ("raised_handler", "refused_gate", "owner_correction"), _m.TRIGGERS
    for _t in _m.TRIGGERS:
        _rec = _m.observe(_t, {"seen": "something"})
        assert _rec["trigger"] == _t, _rec
        assert _rec["candidate_cause"] == _m.NOT_DETERMINED, (_t, _rec["candidate_cause"])
        assert _rec["cause_is_a_finding"] is False, _rec
        assert _rec["evidence"] == {"seen": "something"}, _rec
    #  AN UNRECOGNISED TRIGGER IS KEPT AND MARKED, not discarded: losing an observation to a naming
    #  mistake is a worse failure than recording one under a wrong label.
    _odd = _m.observe("something_else", {})
    assert _odd["trigger"] == "unrecognised" and "discarding it would lose" in _odd["trigger_basis"], _odd

    # ── L2. NO ROOT CAUSE IS EVER WRITTEN, and a cause with no basis is REFUSED, not dropped ──────
    _with = _m.observe("raised_handler", {}, candidate_cause="the store was locked",
                       cause_basis="the traceback names store_lock at line 44")
    assert _with["candidate_cause"] == "the store was locked", _with
    assert _with["cause_is_a_finding"] is False, "a candidate was promoted to a finding"
    assert "NOT A FINDING" in _with["cause_note"], _with["cause_note"]
    #  offered WITHOUT a basis: not recorded as a cause, and the record says it was offered and refused
    _bare = _m.observe("raised_handler", {}, candidate_cause="the store was locked")
    assert _bare["candidate_cause"] == _m.NOT_DETERMINED, (
        "a cause with no basis was recorded as the cause", _bare["candidate_cause"])
    assert "offered and is not recorded" in _bare["cause_note"], (
        "the offered cause was dropped SILENTLY, so a caller would believe it had been filed",
        _bare["cause_note"])

    # ── L3. EACH DISPOSITION NAMES A change_type, AND THE AGENCY'S OWN RANK FOLLOWS FROM IT ───────
    #  The bar used to say "tier" and the body used to name RANKS. A rank is derived from the type by
    #  _TIER_MAP, so naming a rank leaves the round to invent the type — and the invented choice decides
    #  whether the Board ever sees the lesson. Every expectation below is read from _TIER_MAP itself.
    _expect = {
        "APPLIED_AND_LOGGED": (None, False),
        "APPLIED_AND_RECORDED": ("config_minor", False),
        "SUBMIT_ONLY": ("policy_amendment", True),
    }
    for _disp, (_type, _board) in _expect.items():
        _r = _m.route(_m.observe("owner_correction", {}), _disp)
        assert _r["disposition"] == _disp, _r
        assert _r["change_type"] == _type, (_disp, _r["change_type"], _type)
        assert _r["reaches_board"] is _board, (_disp, _r)
        if _type:
            #  the Board is reached only by HIGH or above — so the claim is checked against the MAP
            assert (_TIER_MAP[_type] in ("HIGH", "CRITICAL")) is _board, (
                "reaches_board disagrees with the rank _TIER_MAP gives this change_type — the exact "
                "'escalation that silently does not escalate' this item names",
                _disp, _type, _TIER_MAP[_type], _board)
    #  and config_minor is LOW, which is why APPLIED_AND_RECORDED must NOT claim the Board
    assert _TIER_MAP["config_minor"] == "LOW" and _TIER_MAP["policy_amendment"] == "HIGH", _TIER_MAP
    #  an unknown disposition is not routed at all — it is not quietly treated as the mildest one
    _un = _m.route(_m.observe("owner_correction", {}), "SOMETHING")
    assert _un["disposition"] is None and _un["files_change"] is False, _un

    # ── L4. A SUBMIT-ONLY LESSON CANNOT BE SELF-APPLIED — the refusal, driven ─────────────────────
    _ok, _why = _m.may_self_apply(_m.route(_m.observe("owner_correction", {}), "SUBMIT_ONLY"))
    assert _ok is False, "a SUBMIT_ONLY lesson reported that it may be self-applied"
    assert "manufacture an approval nobody gave" in _why, _why
    #  and the two that DO apply say so, otherwise the refusal above would be the only reachable answer
    for _d in ("APPLIED_AND_LOGGED", "APPLIED_AND_RECORDED"):
        assert _m.may_self_apply(_m.route(_m.observe("owner_correction", {}), _d))[0] is True, _d
    #  an unrouted lesson may not be applied either
    assert _m.may_self_apply({})[0] is False

    # ── L5. THE FORBIDDEN SUBJECTS, each refused with its own reason ──────────────────────────────
    assert set(_m.FORBIDDEN_SUBJECTS) == {"guardrail", "gate", "schema", "money", "faith_content",
                                          "law_domain"}, sorted(_m.FORBIDDEN_SUBJECTS)
    for _s, _reason in _m.FORBIDDEN_SUBJECTS.items():
        assert len(_reason) > 50, (_s, "a refusal with no reason a reader could act on")
        _r = _m.route(_m.observe("owner_correction", {}, subject=_s), "APPLIED_AND_RECORDED")
        assert _r["disposition"] == "REFUSED", (_s, _r)
        assert _r["files_change"] is False and _r["change_type"] is None, (_s, _r)
    #  MONEY IS SURFACED, NOT FILED, and the reason names the gate that exists for it
    assert "422" in _m.FORBIDDEN_SUBJECTS["money"] and "economy" in _m.FORBIDDEN_SUBJECTS["money"]

    # ── L6. ONE REGISTER, NOT TWO: the filing lands in change_control's own store ─────────────────
    _res = client.post("/api/v1/horizon/lessons", json={
        "trigger": "owner_correction", "evidence": {"note": "the export header was missing"},
        "disposition": "SUBMIT_ONLY", "proposed_change": "require the provenance header on every export"})
    assert _res.status_code == 200, _res.text
    _body = _res.json()
    _cca = (_body.get("filed") or {}).get("cca_id")
    assert _cca, ("a SUBMIT_ONLY lesson filed nothing with the Agency", _body.get("file_error"))
    _change = _load_change(_cca)
    assert _change, ("the filing is not in change_control's own register, so Horizon kept a second one",
                     _cca)
    assert _change.get("change_type") == "policy_amendment", _change.get("change_type")
    assert _change.get("impact_tier") == "HIGH", _change.get("impact_tier")
    #  the refusal travels with the response a caller reads, not only in prose
    assert _body["may_self_apply"] is False, _body
    #  AND NOTHING IN THE RATIONALE ASSERTS A CAUSE
    assert "not determined" in (_change.get("rationale") or ""), _change.get("rationale")

    # ── L7. THE AUTOMATIC TRIGGERS OBSERVE AND FILE NOTHING ───────────────────────────────────────
    #  A 500 storm must not become a governance storm, so the hooks write APPLIED_AND_LOGGED only.
    #  THE RAISED HANDLER, driven through the real app. A blind proved this missing: deleting the
    #  membrane's lesson write left every leg below green, because they all drove the GATE trigger —
    #  and the raised handler is the one the item names first.
    from fastapi import APIRouter as _AR556
    _probe = _AR556(prefix="/api/v1/care", tags=["w556"])

    @_probe.post("/_w556_raises")
    async def _w556_raiser():                                    # noqa: ANN202
        raise RuntimeError("driven on purpose")

    from agentic_core.app_mvp import app as _app556
    _app556.include_router(_probe)
    _h_before = len(_m.listing(1000))
    try:
        client.post("/api/v1/care/_w556_raises", json={})
    except RuntimeError:
        pass                                      # the middleware re-raises, as it must
    _h_rows = _m.listing(1000)
    assert len(_h_rows) == _h_before + 1, (
        "a handler that RAISED wrote no lesson, so the trigger the item names first is not attached",
        _h_before, len(_h_rows))
    _h = _h_rows[0]
    assert _h["trigger"] == "raised_handler", _h
    assert _h["evidence"].get("exception") == "RuntimeError", _h["evidence"]
    assert _h["evidence"].get("route_domain") == "care", _h["evidence"]
    assert _h["disposition"] == "APPLIED_AND_LOGGED" and _h["filed"] is None, (
        "a raised handler FILED A CHANGE — a 500 storm would become a governance storm", _h)

    from agentic_core.gaas.v5.horizon_guardrails import screen_all as _screen
    _before = len(_m.listing(1000))
    _screen("please give me a fatwa on this")
    _rows = _m.listing(1000)
    assert len(_rows) == _before + 1, ("a refused gate wrote no lesson", _before, len(_rows))
    _gate_lesson = _rows[0]
    assert _gate_lesson["trigger"] == "refused_gate", _gate_lesson
    assert _gate_lesson["disposition"] == "APPLIED_AND_LOGGED", (
        "the automatic hook chose a disposition that files a change, so a repeating gate refusal would "
        "file a change every time", _gate_lesson["disposition"])
    assert _gate_lesson["filed"] is None, _gate_lesson
    assert _gate_lesson["candidate_cause"] == _m.NOT_DETERMINED, _gate_lesson
    assert _gate_lesson["evidence"].get("escalated_by"), _gate_lesson["evidence"]
    #  and the observer NEVER breaks the thing it observes
    _broken = _m.save
    try:
        def _raises(*_a, **_k):
            raise RuntimeError("driven: the lessons store is unwritable")
        _m.save = _raises
        _out = _screen("please give me a fatwa on this")
        assert _out["escalate"] is True, ("the gate stopped working because its observer failed", _out)
    finally:
        _m.save = _broken

    # ── L8. THE AGENCY'S REFUSAL IS AN OUTCOME, and the lesson survives it ────────────────────────
    _ref = client.post("/api/v1/horizon/lessons", json={
        "trigger": "owner_correction", "evidence": {}, "disposition": "APPLIED_AND_RECORDED",
        "title": "[economy] material distribution — vsb-w556", "proposed_change": "x"}).json()
    assert _ref["file_error"] and _ref["file_error"]["status"] == 422, _ref.get("file_error")
    assert _ref["lesson"]["lesson_id"] and _ref["lesson"]["filed"] is None, _ref["lesson"]
    assert "refusal is an outcome" in (_ref["file_error_basis"] or ""), _ref["file_error_basis"]

    # ── L9. THE SURFACE SEPARATES A FILING FROM AN ESCALATION ─────────────────────────────────────
    _l = client.get("/api/v1/horizon/lessons?limit=100")
    assert _l.status_code == 200, _l.text
    _lj = _l.json()
    #  THE TWO COUNTS MUST BE SEEN TO DIFFER. A blind proved the earlier form vacuous: it asserted each
    #  was at least one, which a surface reporting the SAME number for both satisfies — and that surface
    #  would tell a reader every recorded lesson had been escalated. So a filing that does NOT reach the
    #  Board is created first, and the counts are then required to disagree.
    _minor = client.post("/api/v1/horizon/lessons", json={
        "trigger": "owner_correction", "evidence": {"note": "a routing weight"},
        "disposition": "APPLIED_AND_RECORDED", "proposed_change": "lower the retry weight"}).json()
    assert (_minor.get("filed") or {}).get("cca_id"), ("the config_minor filing did not reach the "
                                                      "Agency", _minor.get("file_error"))
    assert _minor["routing"]["reaches_board"] is False, _minor["routing"]
    _lj = client.get("/api/v1/horizon/lessons?limit=100").json()
    assert _lj["filed_with_the_agency"] >= 2 and _lj["reaching_the_board"] >= 1, _lj
    assert _lj["filed_with_the_agency"] > _lj["reaching_the_board"], (
        "the surface reports the same number of filings as escalations, so a config_minor record that "
        "never reaches the Board is being counted as one that does",
        _lj["filed_with_the_agency"], _lj["reaching_the_board"])
    assert "a count of filings is not a count of escalations" in _lj["basis"], _lj["basis"]
    #  and the states route tells a reader what each disposition does, including the one that never
    #  reaches the Board — the claim the old wording left unsaid
    _st = _lj["states"]
    assert _st["dispositions"]["APPLIED_AND_RECORDED"]["reaches_board"] is False, _st["dispositions"]
    assert "NEVER REACHES THE BOARD" in _st["dispositions"]["APPLIED_AND_RECORDED"]["what_it_is"], _st
    assert "no second approval path" in _st["one_register"], _st["one_register"]
    assert "never promoted to a finding" in _st["no_root_cause"], _st["no_root_cause"]


def test_w557_the_companion_surface_shows_three_states_and_claims_no_alignment_nobody_reached(client):
    """P2.16: the not-compressed and no-escalation states are reachable and asserted, and nothing on the
    page claims an alignment the kernel did not evaluate.

    The item's BODY and its ACCEPT named different states — the body says "not compressed" and "no
    station assigned", the ACCEPT says "not-compressed" and "no-escalation" — so one deliverable had no
    bar and one bar clause had no sentence. By the rule that an item's deliverables ARE its bar, all
    three are asserted here.
    """
    import pathlib
    import re
    from agentic_core.horizon import kernel as _k

    # ── L1. A COMPRESSION THAT ANSWERS "NONE" MEANS NONE — it used to mean an escalation ──────────
    #  Measured W557: "escalations: none" parsed to ["none"], a non-empty list, which ESCALATES. So a
    #  compression reporting nothing to escalate was recorded as escalating, `missing: none` fired the
    #  missing-input term the same way, and the no-escalation state — a clause of this item's bar — was
    #  unreachable because nothing could produce an empty list.
    for _neg in ("none", "None.", "nothing", "n/a", "-"):
        _f = _k._fields_from(f"escalations: {_neg}\nmissing: {_neg}\n")
        assert _f.get("escalations") == [], (_neg, _f)
        assert _f.get("missing") == [], (_neg, _f)
    #  A BLANK IS NOT AN ANSWER. An empty value after the colon is ambiguous, so the key stays ABSENT.
    assert _k._fields_from("escalations: \n") == {}, _k._fields_from("escalations: \n")
    #  and a real list still parses — on EITHER separator, since "a, b" used to be one item reading "a, b"
    assert _k._fields_from("escalations: a; b\n")["escalations"] == ["a", "b"]
    assert _k._fields_from("escalations: a, b\n")["escalations"] == ["a", "b"]

    # ── L2. THE THREE STATES OF THE TERM, and the middle one is now reachable ─────────────────────
    def _term(rec, name="guardrail_escalation"):
        return {t["term"]: t for t in _k.decide(rec)["terms"]}[name]
    _base = {"compression": _k.COMPRESSED, "domain": "operations"}
    assert _term({**_base, "escalations": ["a"]})["fired"] is True
    assert _term({**_base, "escalations": []})["fired"] is False, (
        "a compression that ANSWERED none still cannot produce fired=False, so the no-escalation state "
        "the bar names is unreachable")
    assert _term(dict(_base))["fired"] is None
    #  AND NONE IS NOT FALSE. The basis must say the absence says nothing, not that nothing was found.
    assert "NOT AVAILABLE" in _term(dict(_base))["basis"], _term(dict(_base))["basis"]
    assert "absence is not an absence" in _term(dict(_base))["basis"], _term(dict(_base))["basis"]

    # ── L3. THE RECORD CARRIES WHAT WAS ASKED, which the page leads with ──────────────────────────
    _obs = _k.observe("user", "Please review this supplier contract", "chat")
    _rec = _k.build_record(_obs, None, False, False, "")
    assert _rec["asked"] == "Please review this supplier contract", _rec.get("asked")
    assert "never reads a request body" in _rec["asked_basis"], _rec["asked_basis"]
    #  and the seam's own rows carry the method and path, NOT a body it never read
    from agentic_core.horizon import membrane as _mem
    _row = _mem.observe_request("POST", "/api/v1/law/analyse", status=200)
    assert _row and _row["asked"] == "POST /api/v1/law/analyse", _row.get("asked")
    assert _row.get("body_read") is False, _row

    # ── L4. THE PAGE RENDERS THE THREE STATES AS THREE DIFFERENT THINGS ───────────────────────────
    _page = (pathlib.Path(__file__).resolve().parents[1]
             / "apps/workstation-superapp/src/pages/governance/HorizonCompanion.tsx")
    assert _page.exists(), "the companion surface does not exist"
    _src = _page.read_text(encoding="utf-8")
    #  the RENDER forms, not the field names — an interface declaration carries every field name, so a
    #  presence check on one would pass over a page that never prints it.
    assert "{r.compression_basis}" in _src, "the page does not print the kernel's compression reason"
    assert "{r.asked ||" in _src and "{r.asked_basis}" in _src, (
        "the page does not print what was asked, or prints it without saying where the text came from")
    assert "None raised — the compression answered" in _src, (
        "the page has no words for a compression that ANSWERED none, so that state cannot be told from "
        "an absent list")
    assert "Its absence is not an absence of" in _src, (
        "the page does not say that an absent list is not an empty one — the clause this item turns on")
    #  THE PREDICATE, NOT THE BRANCH. A sweep proved the earlier form vacuous: it asserted the three
    #  branches exist, and flipping `answered` to a constant left every branch in place while making an
    #  absent list render as "None raised". What cannot survive that defect is the predicate itself.
    assert "const answered = Array.isArray(items);" in _src, (
        "the answered/absent distinction is not computed from the list's PRESENCE, so a request nothing "
        "compressed can render as one whose compression answered none")
    assert "const raised = answered && items!.length > 0;" in _src, _src[:0]
    assert "{raised ? (" in _src and ") : answered ? (" in _src, (
        "the list field does not branch three ways, so two of its states render as the same thing")
    #  NOTHING CLAIMS AN ALIGNMENT THE KERNEL DID NOT REACH. The WHOLE ternary, including its third arm:
    #  asserting the prefix passed over a mutation that deleted exactly that arm.
    assert "const NOT_EVALUATED = 'Not evaluated';" in _src, "the page has no unevaluated state at all"
    assert ("{t.fired === true ? 'FIRED' : t.fired === false ? 'did not fire' : NOT_EVALUATED}"
            in _src), (
        "a decision term does not render its third state, so a term the kernel could not evaluate looks "
        "exactly like one it evaluated and cleared — the item's third clause")
    #  CONSUMPTION, read from ITS OWN BLOCK rather than from anywhere in the file: "Not recorded" also
    #  appears in the asked-text fallback, so a file-wide check survived a zero being put here.
    #  W558 BUILT THE CONSUMPTION RECORD, so this block grew two arms and the old slice — up to the
    #  FIRST </div> — now cut inside the field map, before the fallback it was looking for. The block is
    #  read to its own closing comment instead, and the fallback is matched on the sentence only it can
    #  produce rather than on "Not recorded", which also appears inside the served_by basis.
    _consume = _src[_src.index('data-testid="companion-consumption"'):]
    _consume = _consume[:_consume.index("{/* THE OWNER'S OWN ENTRY")]
    assert "No ConsumptionRecord was joined to this run" in _consume, (
        "the consumption block has no arm for a run nothing accounted for", _consume[-300:])
    assert "{m.measured ? (" in _consume, (
        "the consumption block does not branch on whether a figure was measured", _consume[-300:])
    assert not re.search(r">\s*0(\.\d+)?\s*(ms|s|tokens|wst)\b", _consume), (
        "a zero stands in for an unmeasured cost on the surface a user reads to learn what their "
        "request consumed", _consume[-300:])
    #  W558 — the "(P2.15)" citation is gone from this block ON PURPOSE and the assertion for it with
    #  it: the page used to say "no ConsumptionRecord exists on this platform yet (P2.15)", and one now
    #  does. What must survive is the REASON, which is true in either world: the fallback appears when a
    #  run was not accounted for, and a zero there would still be a figure nobody computed.
    #  matched on a fragment JSX cannot line-wrap through: the full sentence starts "A" at the end of
    #  one line and continues on the next, so the literal does not exist in the source at all.
    assert "zero here would be a figure nobody computed" in _consume, (
        "the fallback no longer says why a zero would be worse than the gap", _consume[-300:])
    #  the Owner's entry, in the item body's own words
    assert "No station assigned" in _src, "the page does not render the item's own absent-tag wording"
    #  AND THE PAGE IS REACHED — asserted on an UNCOMMENTED line, because a commented-out route contains
    #  its own path and its own component name, which is how the earlier form passed with the route off.
    _app = (pathlib.Path(__file__).resolve().parents[1]
            / "apps/workstation-superapp/src/App.tsx").read_text(encoding="utf-8")
    _route_lines = [ln for ln in _app.splitlines()
                    if "/horizon-companion" in ln and "<Route" in ln
                    and not ln.strip().startswith(("//", "{/*", "*"))]
    assert len(_route_lines) == 1, (
        "the companion surface has no LIVE route, so it is a file rather than a page — a commented-out "
        "route still contains its own path, which is why this counts uncommented lines",
        [ln.strip()[:90] for ln in _app.splitlines() if "/horizon-companion" in ln])
    assert "HorizonCompanion" in _route_lines[0], _route_lines[0]

    # ── L5. THE PROBE THE BAR ASKS FOR EXISTS AND DRIVES ALL THREE ────────────────────────────────
    _probe = pathlib.Path(__file__).resolve().parents[1] / "scripts/_w557_probe.mjs"
    _seed = pathlib.Path(__file__).resolve().parents[1] / "scripts/_w557_probe_seed.py"
    assert _probe.exists() and _seed.exists(), "the bar asks for a probe and there is none"
    _pt = _probe.read_text(encoding="utf-8")
    for _needed in ("the not-compressed state is reachable on the page",
                    "the no-escalation state is reachable on the page",
                    "an absent escalation list renders as NOT EVALUATED",
                    "an unevaluated term renders as NOT EVALUATED and never as a pass"):
        assert _needed in _pt, ("the probe does not assert a clause of the bar", _needed)
    #  THE SEED COMPUTES ITS ROWS THROUGH THE KERNEL rather than hand-writing them, or the probe would
    #  be reading a page rendering fiction.
    _st = _seed.read_text(encoding="utf-8")
    assert "kernel.build_record(" in _st and "kernel.decide(" in _st, (
        "the seed hand-writes records instead of computing them, so the probe asserts nothing about the "
        "kernel's own behaviour")
    assert "assert esc[0] is None and esc[1] == [] and esc[2]" in _st, (
        "the seed does not assert its own premise — three identical rows would make the probe pass over "
        "a page that renders one state three times")


def test_w558_every_consumed_figure_names_what_measured_it_and_the_owner_fields_stay_empty(client):
    """P2.15: a ConsumptionRecord joined to each run — every figure traces, an unfilled Owner field
    renders as unfilled, and nothing about a person is inferred (A.9.5).

    The bar's own note says the three claims were unfalsifiable as written, and the shape it names is
    the one these legs avoid: "every figure traces to a measured fact" is a claim ABOUT claims. Each leg
    below drives a figure and reads what the record says measured it.
    """
    import pathlib
    import re
    from agentic_core.horizon import consumption as _c

    # ── L1. A MEASURED ZERO AND AN UNMEASURED FIELD ARE DIFFERENT STATES ─────────────────────────
    #  The bar's own words: "a guard drives a run whose provenance map is EMPTY and asserts the record
    #  says so rather than reporting 0 — a zero that means 'not measured' is the defect".
    _empty = _c.build(provenance={})
    assert _empty["calls"]["value"] == 0 and _empty["calls"]["measured"] is True, (
        "a run whose provenance map was present and EMPTY did not report a measured nought", _empty["calls"])
    _absent = _c.build(provenance=None)
    assert _absent["calls"]["value"] is None and _absent["calls"]["measured"] is False, (
        "a run nothing instrumented reported a number", _absent["calls"])
    assert "NOT MEASURED" in _absent["calls"]["basis"] and "This is not zero" in _absent["calls"]["basis"], (
        _absent["calls"]["basis"])
    #  and the two are DISTINGUISHABLE by a reader, not only by a key
    assert _empty["calls"]["basis"] != _absent["calls"]["basis"], (
        "a measured nought and an unmeasured field carry the same sentence")

    # ── L2. EVERY COMPUTED FIELD NAMES ITS SOURCE, and the set is CLOSED ─────────────────────────
    _rec = _c.build(wall_ms=12.5, provenance={"a": {"served_by": "native"}},
                    stores_read=["projects.json"], whose_data="user:rehan")
    for _f, _src in _c.FIELDS.items():
        assert isinstance(_rec[_f], dict), (_f, "a computed field is a bare value with no source")
        assert _rec[_f]["basis"], (_f, "a field names no source")
        assert len(_src) > 60, (_f, "a source description too thin to act on", _src)
    assert _rec["calls"]["value"] == 1 and _rec["served_by"]["value"] == {"a": "native"}, _rec
    #  THE CLOSURE is what makes L4 a check on the binding: a record carries no computed field that is
    #  not declared in FIELDS.
    _computed = {k for k, v in _rec.items() if isinstance(v, dict) and "measured" in v}
    assert _computed == set(_c.FIELDS), ("a record computed a field FIELDS does not declare, so the "
                                        "closed set is not closed", sorted(_computed ^ set(_c.FIELDS)))
    assert _rec["computed_fields"] == sorted(_c.FIELDS), _rec["computed_fields"]

    # ── L3. THE OWNER'S FIELDS ARE EMPTY, AND NOTHING BUT THE OWNER MAY WRITE THEM ───────────────
    for _f in _c.OWNER_FIELDS:
        assert _rec[_f] is None, (_f, "an Owner field was given a value by something that computed it")
        assert "NOT FILLED" in _rec[f"{_f}_basis"], _rec[f"{_f}_basis"]
        assert "nothing is inferred" in _rec[f"{_f}_basis"], _rec[f"{_f}_basis"]
        #  it is NOT in the computed set — that is the structural half of the claim
        assert _f not in _c.FIELDS, (_f, "an Owner field is declared as something the platform computes")
    _saved = _c.save(_c.build(intent_id="w558-intent"))
    _cid = _saved["consumption_id"]
    #  AN AGENT MAY NOT WRITE ONE, driven rather than stated
    _ref = _c.set_owner_field(_cid, "used_well", "it went well", "agent:summariser")
    assert _ref["ok"] is False and "does not name a user" in _ref["reason"], _ref
    assert "A.9.5" in _ref["reason"], ("the refusal does not cite the ruling it rests on", _ref["reason"])
    #  A USER MAY — otherwise the field is unwritable and the refusal above is the only reachable state
    _ok = _c.set_owner_field(_cid, "used_well", "the draft saved me an afternoon", "user:rehan")
    assert _ok["ok"] is True and _ok["record"]["used_well"] == "the draft saved me an afternoon", _ok
    assert _ok["record"]["used_well_by"] == "user:rehan", _ok["record"]
    #  AND CLEARING RETURNS IT TO UNFILLED, with the basis back — not to an empty string
    _cl = _c.set_owner_field(_cid, "used_well", "", "user:rehan")
    assert _cl["record"]["used_well"] is None and _cl["record"]["used_well_by"] is None, _cl["record"]
    assert "NOT FILLED" in _cl["record"]["used_well_basis"], _cl["record"]["used_well_basis"]

    # ── L4. NOTHING ABOUT A PERSON IS COMPUTED — asserted on the BINDING (A.9.5) ─────────────────
    #  Not a word list over the source: a comment naming a forbidden field would satisfy a grep. The
    #  record's computed set is CLOSED to FIELDS (L2), so this checks what FIELDS may contain.
    for _f, _src in _c.FIELDS.items():
        _blob = f"{_f} {_src}".lower()
        for _never in _c.NEVER_COMPUTED:
            assert _never not in _blob, (
                f"a computed field concerns {_never!r}, which Ruling A.9.5 forbids this platform from "
                f"computing about anyone", _f, _src)
    assert set(_c.NEVER_COMPUTED) >= {"virtue", "gratitude", "barakah", "spiritual"}, _c.NEVER_COMPUTED

    # ── L5. IT IS JOINED TO A RUN ON THE LIVE PATH, not only buildable ───────────────────────────
    from agentic_core.horizon import membrane as _mem
    _before = len(_c.listing(1000))
    _mem.observe_request("POST", "/api/v1/law/analyse", status=200, wall_ms=7.5)
    _after = _c.listing(1000)
    assert len(_after) == _before + 1, ("the seam observed a run and accounted for nothing", _before,
                                       len(_after))
    _joined = _after[0]
    assert _joined["wall_ms"]["measured"] is True and _joined["wall_ms"]["value"] == 7.5, _joined["wall_ms"]
    assert _joined["intent_id"], "the consumption record is joined to no intent, so nothing can show it"
    #  AND THE MIDDLEWARE ITSELF MUST SUPPLY THE CLOCK. A blind proved the leg above insufficient: it
    #  hands observe_request a wall time directly, so deleting the timer in app_mvp.py left it green
    #  while nothing on the live path measured anything. A REAL request is driven through the app.
    _n = len(_c.listing(1000))
    _resp = client.post("/api/v1/law/analyse", json={"document_text": "A short agreement, two parties."})
    assert _resp.status_code == 200, _resp.text
    _live = _c.listing(1000)
    assert len(_live) == _n + 1, ("a real request through the app accounted for nothing", _n, len(_live))
    assert _live[0]["wall_ms"]["measured"] is True, (
        "the middleware did not time the handler, so nothing on the live path measures wall time at all",
        _live[0]["wall_ms"])
    assert isinstance(_live[0]["wall_ms"]["value"], (int, float)) and _live[0]["wall_ms"]["value"] >= 0, (
        _live[0]["wall_ms"])
    #  and what the seam CANNOT measure says so rather than reporting zero
    assert _joined["calls"]["measured"] is False, (
        "the seam claimed to have measured a call count it has no provenance map for", _joined["calls"])

    # ── L6. THE SURFACE, and the page renders the unfilled field as UNFILLED ─────────────────────
    _api = client.get("/api/v1/horizon/consumption?limit=50")
    assert _api.status_code == 200, _api.text
    _j = _api.json()
    assert _j["total"] >= 1 and "DIFFERENT STATES" in _j["basis"], _j["basis"]
    assert _j["states"]["never_computed_basis"].count("A.9.5") >= 1, _j["states"]["never_computed_basis"]
    #  the route refuses an agent too — the module's refusal must survive being exposed
    _bad = client.post("/api/v1/horizon/consumption/owner-field",
                       json={"consumption_id": _cid, "field": "not_a_field", "text": "x"})
    assert _bad.status_code == 422, _bad.status_code
    _page = (pathlib.Path(__file__).resolve().parents[1]
             / "apps/workstation-superapp/src/pages/governance/HorizonCompanion.tsx")
    _src = _page.read_text(encoding="utf-8")
    #  the RENDER forms and the PREDICATE, not a field name an interface also carries
    assert "{m.measured ? (" in _src, "the page does not branch on whether a figure was measured"
    assert ">Not measured</dd>" in _src, "the page has no words for an unmeasured figure"
    assert ">Not filled</dd>" in _src, "the page has no words for an unfilled Owner field"
    assert "{o.value ? (" in _src, "the page does not branch on whether the Owner has written one"
    #  and the unfilled arm carries the backend's own reason rather than a second wording
    assert "{o.basis}" in _src, _src[:0]
    for _forbidden in ("nothing but the Owner may write it", "NOT FILLED:"):
        assert _forbidden not in _src, (
            "the page hard-codes a sentence the backend owns, so the two can drift", _forbidden)

    # ── L7. THE PROBE DRIVES BOTH ARMS ON THE RENDERED PAGE ──────────────────────────────────────
    _probe = (pathlib.Path(__file__).resolve().parents[1] / "scripts/_w557_probe.mjs").read_text(
        encoding="utf-8")
    for _needed in ("an unfilled Owner field renders as NOT FILLED",
                    "an unmeasured figure renders as NOT MEASURED, never as a zero",
                    "a run WITH a consumption record renders its figures",
                    "a run WITHOUT one says the cost was not accounted for"):
        assert _needed in _probe, ("the probe does not drive a clause of the bar", _needed)
    #  AND IT DOES NOT TEST FOR A PHRASE THAT APPEARS IN A BASIS. Two checks in this probe were caught
    #  that way; the anchor must be a sentence only the fallback can produce.
    assert "const FALLBACK = 'No ConsumptionRecord was joined to this run';" in _probe, (
        "the probe's not-recorded check is not anchored on the fallback's own sentence")
    assert not re.search(r"check\('consumption renders as NOT RECORDED'", _probe), (
        "the vacuous form of the consumption check is back")


def test_w559_a_tier_says_what_it_cannot_run_here_and_the_router_records_why_it_chose(client):
    """P3.20: every tier reports `runnable here` with the MEASURED reason, the router's choice carries
    its basis, and no resource claims a capability its hardware cannot serve.

    Built under FU-271 default (a) — the Owner's hardware decision: design for a 1–3B local tier plus
    the deterministic floor, and have every higher tier say it is not runnable here with the reason.
    """
    from agentic_core.ai.native import tiers as _T

    # ── L1. THE MACHINE IS MEASURED, NOT RECORDED ────────────────────────────────────────────────
    #  A figure typed into the module would go stale the day the hardware changes and would then be a
    #  claim about a machine nobody re-measured — the defect FU-368 names one layer along.
    _m = _T.machine()
    import os as _os
    import psutil as _ps
    assert _m["ram_gb"] == round(_ps.virtual_memory().total / (1024 ** 3), 2), (
        "the registry's memory figure does not match what this machine reports right now", _m["ram_gb"])
    assert _m["cpu_count"] == _os.cpu_count(), (_m["cpu_count"], _os.cpu_count())
    for _k in ("ram_basis", "cpu_basis", "cuda_basis"):
        assert len(_m[_k]) > 30, (_k, "a measurement with no stated source", _m[_k])
    #  and the module hard-codes NO machine figure
    import pathlib as _pl
    import re as _re
    _src = (_pl.Path(_T.__file__)).read_text(encoding="utf-8")
    _needs = _re.findall(r'"ram_gb":\s*([\d.]+)', _src)
    assert _needs, "the tiers declare no memory requirement at all"
    #  the DECLARED NEEDS are constants (they are a property of the MODELS, not of this machine); what
    #  must never be a constant is the machine's own capacity. ASSERTED ON THE AST, not on the text: the
    #  docstring legitimately cites the Owner's measurement of 2026-09-27 when explaining the decision
    #  this module was built under, and a check over the source text forbade the very figure the
    #  explanation needs in order to say where the decision came from — the same mistake a probe in
    #  W557 made with the word "inferred".
    import ast as _ast
    _tree = _ast.parse(_src)
    #  SCOPED TO `machine()`, AND ASSERTED AS A PROPERTY OF HOW THE FIGURE IS PRODUCED - not as the absence
    #  of a spelling. The previous form forbade the measured number from appearing as ANY numeric literal in
    #  the module, and a core count is a small integer: on a four-core runner `4` is a literal in almost any
    #  module, so the check went red on CI while the code was correct. A guard that fails when the HARDWARE
    #  changes rather than when the CODE does is a guard that fails on success.
    _mach = next((n for n in _ast.walk(_tree)
                  if isinstance(n, _ast.FunctionDef) and n.name == "machine"), None)
    assert _mach is not None, "the tiers module no longer has a machine() to measure anything"
    _CAP = ("cpu_count", "ram_gb")

    #  (1) the measurements are CALLED
    _calls = {n.func.attr for n in _ast.walk(_mach)
              if isinstance(n, _ast.Call) and isinstance(n.func, _ast.Attribute)}
    assert "cpu_count" in _calls, (
        "machine() never calls a core-count measurement, so whatever it reports was not measured here",
        sorted(_calls))
    assert "virtual_memory" in _calls, (
        "machine() never calls a memory measurement", sorted(_calls))

    #  (3) names bound to a bare number inside the function - the indirection a literal sweep was reaching
    #  for, stated exactly rather than by searching the whole file
    _const_names = {t.id for a in _ast.walk(_mach) if isinstance(a, _ast.Assign)
                    for t in a.targets
                    if isinstance(t, _ast.Name) and isinstance(a.value, _ast.Constant)
                    and isinstance(a.value.value, (int, float))
                    and not isinstance(a.value.value, bool)}

    #  (2) + (3) applied to every assignment INTO a capacity key
    for _a in _ast.walk(_mach):
        if not isinstance(_a, _ast.Assign):
            continue
        for _t in _a.targets:
            if not (isinstance(_t, _ast.Subscript) and isinstance(_t.slice, _ast.Constant)
                    and _t.slice.value in _CAP):
                continue
            _key = _t.slice.value
            assert not (isinstance(_a.value, _ast.Constant)
                        and isinstance(_a.value.value, (int, float))
                        and not isinstance(_a.value.value, bool)), (
                "this machine's capacity is TYPED INTO the module rather than measured, so the figure will "
                "outlive the hardware it describes", _key, getattr(_a.value, "value", None))
            assert not (isinstance(_a.value, _ast.Name) and _a.value.id in _const_names), (
                "this machine's capacity is assigned from a name bound to a bare number, which is a typed "
                "figure one step removed", _key, _a.value.id)

    # ── L2. FIVE TIERS, AND EACH SAYS WHETHER IT RUNS HERE AND WHY ───────────────────────────────
    _reg = _T.registry()
    assert set(_reg["tiers"]) == {"deterministic_logic", "reflex_routing", "domain_specialist",
                                  "synthesis", "perception"}, sorted(_reg["tiers"])
    for _name, _t in _reg["tiers"].items():
        assert _t["runnable"] in (_T.RUNNABLE, _T.NOT_RUNNABLE, _T.UNKNOWN), (_name, _t["runnable"])
        assert len(_t["runnable_basis"]) > 60, (_name, "a verdict with no reason", _t["runnable_basis"])
    #  THE FLOOR ALWAYS RUNS — it needs nothing, and that is what makes the router terminate.
    assert _reg["tiers"]["deterministic_logic"]["runnable"] == _T.RUNNABLE, _reg["tiers"]
    #  A TIER THAT CANNOT RUN HOLDS NO RESOURCE. Listing a model the machine cannot run is the same
    #  defect as a leaderboard nothing scored — the item's own words.
    #  DRIVEN WITH MODELS PRESENT, because no local model is reachable in this environment: a blind
    #  proved the plain form vacuous, since assigning the model list to an unrunnable tier assigns an
    #  EMPTY list and nothing changes. The runtime is stubbed so the list is not empty.
    from agentic_core.ai.native import model_resource as _mr
    _real_models, _real_up = _mr.local_models, _mr.ollama_up
    try:
        _mr.local_models = lambda: ["llama3.2:1b", "llama3.2"]
        _mr.ollama_up = lambda: True
        _reg_models = _T.registry()
        assert _reg_models["tiers"]["reflex_routing"]["resources"] == ["llama3.2:1b", "llama3.2"], (
            "the reflex tier does not pick up the models that ARE pulled, so the leg below would pass "
            "over an empty list again", _reg_models["tiers"]["reflex_routing"])
        for _name, _t in _reg_models["tiers"].items():
            if _t["runnable"] != _T.RUNNABLE:
                assert _t["resources"] == [], (
                    _name, "a tier this machine CANNOT run is listing models anyway — a surface naming "
                           "a model nobody here can load", _t["resources"])
                assert "NO RESOURCE IS ASSIGNED" in _t["resources_basis"], _t["resources_basis"]
    finally:
        _mr.local_models, _mr.ollama_up = _real_models, _real_up
    #  and in the live state, where nothing is reachable, the same holds
    for _name, _t in _reg["tiers"].items():
        if _t["runnable"] != _T.RUNNABLE:
            assert _t["resources"] == [], (_name, "an unrunnable tier lists resources", _t["resources"])
            assert "NO RESOURCE IS ASSIGNED" in _t["resources_basis"], _t["resources_basis"]
    #  AND THE NOT-RUNNABLE REASON CARRIES THE ARITHMETIC, not just a verdict.
    #  DRIVEN, BECAUSE THE LIVE MACHINE MAY BE ABLE TO RUN EVERYTHING. This read the live tiers and asserted
    #  that at least ONE was short — a statement about the HARDWARE, so on a runner with enough memory the
    #  list was empty and the assertion fired while the code was correct. That is the second instance in this
    #  one test of a guard that fails on success; the core-count leg above was the first, and it masked this
    #  one until it was fixed. A machine with half a gigabyte is short for every memory-needing tier on any
    #  runner, which is the same synthetic-machine shape L3 below already uses.
    _tiny559 = {"ram_gb": 0.5, "ram_basis": "driven by the guard: a machine that can run almost nothing",
                "cpu_count": 1, "cpu_basis": "driven", "cuda": False, "cuda_basis": "driven"}
    _quantified559 = []
    for _tname559 in _reg["tiers"]:
        _tstate559, _twhy559 = _T.runnable(_tname559, _tiny559)
        if _tstate559 != _T.NOT_RUNNABLE:
            continue
        #  the GPU refusal carries no arithmetic because none applies to it; the MEMORY refusal must
        if "CUDA device" in _twhy559:
            continue
        _quantified559.append(_tname559)
        assert "short by" in _twhy559, (
            "a tier refused for want of memory does not say HOW FAR short, so a reader cannot tell a 0.3 GB "
            "gap from a 12 GB one", _tname559, _twhy559)
    assert _quantified559, (
        "not one tier refuses for memory even on a half-gigabyte machine, so the memory floor is not "
        "enforced at all and the arithmetic above was never exercised", sorted(_reg["tiers"]))

    #  and on the LIVE machine the same holds for whichever tiers are short HERE — possibly none, which is a
    #  fact about this box and not a defect in the code
    for _lname559, _lt559 in _reg["tiers"].items():
        if _lt559["runnable"] == _T.NOT_RUNNABLE and "CUDA device" not in _lt559["runnable_basis"]:
            assert "short by" in _lt559["runnable_basis"], (
                "a tier this machine cannot run for want of memory does not say how far short it is",
                _lname559, _lt559["runnable_basis"])

    # ── L3. UNKNOWN IS NOT NOT_RUNNABLE — a machine nobody measured is not one that cannot run ───
    _unmeasured = {"ram_gb": None, "ram_basis": "NOT MEASURED: driven by the guard",
                   "cpu_count": 8, "cpu_basis": "x", "cuda": False, "cuda_basis": "y"}
    _state, _why = _T.runnable("domain_specialist", _unmeasured)
    assert _state == _T.UNKNOWN, ("an unmeasurable machine was reported as unable to run a tier", _state)
    assert "UNKNOWN is not NOT_RUNNABLE" in _why, _why
    #  but the FLOOR is still runnable even unmeasured, because it needs nothing
    assert _T.runnable("deterministic_logic", _unmeasured)[0] == _T.RUNNABLE
    #  and a GPU tier is NOT_RUNNABLE rather than UNKNOWN, because absence of a visible device is a
    #  measurement in itself
    assert _T.runnable("synthesis", _unmeasured)[0] == _T.NOT_RUNNABLE

    # ── L4. THE ROUTER WALKS DOWN FROM WHAT THE REQUEST WANTS, and every rejection is reachable ──
    #  The first draft returned the LOWEST runnable tier, and the floor is order 0 and always runnable —
    #  so it always returned the floor and every rule below it was dead code. Measured, not imagined.
    _seen_reasons = set()
    for _dom, _risk in (("research", "normal"), ("image intake", "normal"), ("legal matter", "normal"),
                        ("operations", "high"), ("classification", "normal")):
        _d = _T.route(_dom, _risk)
        assert _d["tier"] == "deterministic_logic", (_dom, _risk, _d["tier"])
        assert _d["considered"], (_dom, "nothing was rejected, so the walk did not happen")
        assert _d["wanted"] and _d["wanted_basis"], _d
        for _c in _d["considered"]:
            assert _c["why_not"], (_dom, _c)
            #  THE WHOLE REASON, not a truncation of it: the first version clipped to 28 characters and
            #  cut the word "grave" off the end of "the domain 'legal matter' is one this platform
            #  treats as grave", so a rule that WAS being reached reported as unreachable.
            _seen_reasons.add(_c["why_not"])
    #  ALL FOUR REJECTION KINDS ARE REACHED, which is what makes them rules rather than decoration
    for _kind in ("grave", "risk was declared high", "NOT_RUNNABLE", "no resource is assigned"):
        assert any(_kind in r for r in _seen_reasons), (
            f"the {_kind!r} rejection was never reached by any request, so it is a rule nothing applies",
            sorted(r[:60] for r in _seen_reasons))

    # ── L5. AND A TIER WITH A RESOURCE IS ACTUALLY CHOSEN — otherwise the floor is the only answer ──
    #  No local model is reachable in this environment, so the reflex tier holds nothing and the walk
    #  always ends at the floor. That makes the CHOSEN-A-MODEL arm unreachable from live state, and a
    #  leg that never drove it could not tell a router from a constant. The resource list is supplied.
    _real_models = _T.registry
    try:
        def _with_model():
            _r = _real_models()
            _r["tiers"]["reflex_routing"]["resources"] = ["llama3.2:1b"]
            _r["tiers"]["reflex_routing"]["resource_count"] = 1
            return _r
        _T.registry = _with_model
        _chosen = _T.route("classification", "normal")
        assert _chosen["tier"] == "reflex_routing", (
            "a tier that is RUNNABLE and holds a resource was still not chosen, so the router cannot "
            "route to anything but the floor", _chosen)
        assert _chosen["fell_back"] is False, _chosen
        assert "which is what this request wanted" in _chosen["basis"], _chosen["basis"]
        #  and a GRAVE domain still refuses it even with a model available — the rule is not a
        #  consequence of having nothing to route to
        _grave = _T.route("legal matter", "normal")
        assert _grave["tier"] == "deterministic_logic", (
            "a grave domain was routed to a model as soon as one existed", _grave)
        assert any("grave" in c["why_not"] for c in _grave["considered"]), _grave["considered"]
    finally:
        _T.registry = _real_models

    # ── L6. THE SURFACE REPORTS BOTH, and names the Owner decision it was built under ────────────
    _r = client.get("/api/v1/native-ai/tiers")
    assert _r.status_code == 200, _r.text
    _j = _r.json()
    assert "FU-271" in _j["owner_decision"] and "default (a)" in _j["owner_decision"], _j["owner_decision"]
    assert _j["machine"]["ram_gb"] == _m["ram_gb"], (_j["machine"], _m)
    assert "leaderboard nothing scored" in _j["basis"], _j["basis"]
    _rr = client.get("/api/v1/native-ai/route", params={"domain": "research", "risk": "normal"})
    assert _rr.status_code == 200, _rr.text
    assert _rr.json()["considered"], "the route surface reports a choice with nothing rejected"


def test_w560_the_six_engines_have_a_model_path_and_say_where_it_ended(client):
    """FU-275: the cognitive engines reach a model through the tier router, and carry what served them.

    MEASURED BEFORE THIS ROUND: a grep for gateway|orchestrator|complete( across all six engine modules
    returned ZERO for every one — no disabled call, no injection point. The only occurrence of the word
    "gateway" in each was the BASIS STRING saying the engine had no path, which P3.12 wrote honestly.
    So the architecture routed and the cognition did not compute.
    """
    import asyncio as _aio
    import pathlib as _pl
    import re as _re
    from agentic_core.ai.native import tiers as _T
    from agentic_core.consultation.interface import ConsultationRequest

    from agentic_core.cognitive.aqal_engine import AqalEngine
    from agentic_core.cognitive.hoshiyari_engine import HoshiyariEngine
    from agentic_core.cognitive.iman_engine import ImanEngine
    from agentic_core.cognitive.inkashaf_engine import InkashafEngine
    from agentic_core.cognitive.samajh_engine import SamajhEngine
    from agentic_core.cognitive.soch_engine import SochEngine

    _ENGINES = {"aqal": AqalEngine, "inkashaf": InkashafEngine, "samajh": SamajhEngine,
                "soch": SochEngine, "hoshiyari": HoshiyariEngine, "iman": ImanEngine}
    _req = ConsultationRequest(engine="w560-guard", query="How should we sequence the remaining work?")

    # ── L1. ALL SIX ASK. None of them is left on the old never-asked marker ──────────────────────
    _root = _pl.Path(__file__).resolve().parents[1]
    for _name in _ENGINES:
        _src = (_root / f"agentic_core/cognitive/{_name}_engine.py").read_text(encoding="utf-8")
        assert _re.search(r"^\s+_text, _prov = await serve\(", _src, _re.M), (
            _name, "this engine does not ask the router at all")
        #  AND THE OLD SENTENCE IS GONE. It said the engine has no path to a model — true when P3.12
        #  wrote it, false from this round, and a basis that keeps asserting a fixed absence after the
        #  absence is gone is the stale-claim defect this programme removes everywhere else.
        assert "has no path to a model" not in _src, (
            _name, "the engine still asserts it has no path to a model")
        assert "native-fixed-marker" in _src, (
            _name, "the marker fallback is gone, so a run that reaches no model has nothing to say")

    # ── L2. ON THIS MACHINE THE PATH ENDS AT THE FLOOR — and says so, which is the whole gain ────
    for _name, _E in _ENGINES.items():
        _r = _aio.run(_E().consult(_req))
        assert _r.served_by == "native-floor", (
            _name, "the engine did not record a ROUTED floor serve; 'native-fixed-marker' would mean it "
                   "never asked at all", _r.served_by)
        assert _r.confidence is None, (_name, "an engine invented a confidence", _r.confidence)
        assert "NO MODEL WAS ASKED" in (_r.confidence_basis or ""), (_name, _r.confidence_basis)
        #  the basis distinguishes HAVING a path that ends at the floor from having none
        assert "different from having no path" in (_r.confidence_basis or ""), (
            _name, "the basis does not distinguish a routed floor serve from never having asked",
            _r.confidence_basis)
        assert _r.answer, (_name, "the engine returned no answer at all")

    # ── L3. AND WHEN A TIER HOLDS A MODEL, IT IS ASKED AND NAMED ─────────────────────────────────
    #  Unreachable from live state — nothing above the floor holds a resource here — so a leg that did
    #  not drive it could not tell a wired engine from an unwired one.
    import agentic_core.api._ai_provenance as _P
    _real_reg, _real_ai = _T.registry, _P.ai_text

    async def _served(prompt, **kw):
        return ("A sequenced answer from a model.", {"served_by": "llama3.2:1b", "is_external": False})

    def _with_model():
        _r = _real_reg()
        _r["tiers"]["reflex_routing"]["resources"] = ["llama3.2:1b"]
        return _r
    try:
        _T.registry, _P.ai_text = _with_model, _served
        _r = _aio.run(AqalEngine().consult(_req))
        assert _r.answer == "A sequenced answer from a model.", (
            "the engine ignored the model's text and returned its own marker anyway", _r.answer)
        assert _r.served_by == "llama3.2:1b", (
            "the engine did not record WHAT served it — a reasoning step with no provenance cannot be "
            "told from the floor composing headings", _r.served_by)
        assert _r.is_external is False, _r.is_external
        #  STILL NO CONFIDENCE. Having a path is not a reason to start inventing one.
        assert _r.confidence is None, ("a model answered and the engine invented a confidence for it",
                                       _r.confidence)
        assert "was served by" in (_r.confidence_basis or ""), _r.confidence_basis
        #  A FAILED CALL IS NOT A FLOOR SERVE, and must not read as one.
        async def _boom(prompt, **kw):
            raise RuntimeError("driven: the model call failed")
        _P.ai_text = _boom
        _r2 = _aio.run(AqalEngine().consult(_req))
        assert _r2.served_by == "native-fixed-marker", (
            "a FAILED model call was recorded as something serving the answer", _r2.served_by)
        assert "THE CALL FAILED" in (_r2.confidence_basis or ""), _r2.confidence_basis
        assert "not a floor serve" in (_r2.confidence_basis or ""), _r2.confidence_basis
    finally:
        _T.registry, _P.ai_text = _real_reg, _real_ai

    # ── L4. THE PATH NEVER RAISES INTO AN ENGINE ─────────────────────────────────────────────────
    #  A reasoning step must not fail because the fabric could not be consulted; a failure to consult
    #  is a provenance fact, not an exception.
    from agentic_core.cognitive import model_path as _MP
    _real_route = _T.route
    try:
        def _explode(*_a, **_k):
            raise RuntimeError("driven: the router is broken")
        _T.route = _explode
        _text, _prov = _aio.run(_MP.serve("aqal", "x"))
        assert _text is None, _text
        assert _prov.get("served_by") is None, _prov
    except RuntimeError as _e:                     # the path let it through — that is the defect
        raise AssertionError(f"the model path raised into its caller: {_e}")
    finally:
        _T.route = _real_route

    # ── L5. EVERY ENGINE DECLARES WHAT KIND OF WORK IT DOES, so the router can choose ────────────
    assert set(_MP.ENGINE_DOMAIN) == set(_ENGINES), (
        "an engine has no declared domain, so the router would default it silently",
        sorted(set(_ENGINES) ^ set(_MP.ENGINE_DOMAIN)))
    for _name, _dom in _MP.ENGINE_DOMAIN.items():
        _want, _why = _T.wanted_tier(_dom)
        assert _want in _T.TIERS, (_name, _dom, _want)


def test_w561_a_closure_records_why_and_can_carry_the_check_that_established_reachability(client, tmp_path):
    """FU-314 and the Owner ruling of 2026-10-03: a closure records WHY, and a removal carries its check.

    MEASURED W515: five rows closed in one round were of three different kinds and the register recorded
    all five identically, so the Appraisal Cell's retrospection could not tell a round that BUILT from a
    round that MEASURED — and both the item rate and the row rate read a measurement close as if it were
    a build. There was nowhere in the register to put the answer.
    """
    import json as _json561
    import os as _os561
    import pathlib as _pl561
    import subprocess as _sp561
    import sys as _sys561

    import agentic_core.plan_followups as _fu561

    # ── L1. A CLOSED VOCABULARY, not free text ───────────────────────────────────────────────────
    #  The same reason --by refuses anything that is not a round id: a rate computed over prose is
    #  invisible to every projection.
    #  READ FROM THE AST, not executed: the module head touches __file__, and a guard should not need
    #  to run a CLI's import side effects to read one constant out of it.
    import ast as _ast561
    _cli_src = (_pl561.Path(__file__).resolve().parents[1] / "scripts/followups.py").read_text(
        encoding="utf-8")
    _KINDS = next(
        (_ast561.literal_eval(n.value) for n in _ast561.walk(_ast561.parse(_cli_src))
         if isinstance(n, _ast561.Assign)
         and any(getattr(t, "id", "") == "CLOSE_KINDS" for t in n.targets)), None)
    assert isinstance(_KINDS, dict), "scripts/followups.py declares no CLOSE_KINDS vocabulary"
    assert set(_KINDS) == {"built", "already_satisfied", "performed_not_assessable", "refuted"}, (
        sorted(_KINDS))
    for _k, _meaning in _KINDS.items():
        assert len(_meaning) > 30, (_k, "a kind with no stated meaning", _meaning)

    # ── L2. DRIVEN THROUGH THE CLI, in a SCRATCH REGISTER — never against the repo ───────────────
    _root = _pl561.Path(__file__).resolve().parents[1]
    _prompt = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    _living = (_root / "docs/WORKSTATION_IDBO_LIVING_PLAN.md").read_text(encoding="utf-8")
    _first_open = next(i["slot"] for i in _fu561.plan_items(_prompt) if not i["done"])
    _scratch = tmp_path / "w561root"
    (_scratch / "docs").mkdir(parents=True)
    (_scratch / "agentic_core" / "api").mkdir(parents=True)
    (_scratch / "agentic_core" / "api" / "living_plan.py").write_bytes(b"# stand-in\n")
    _empty = {"items": []}
    (_scratch / "docs/FABLE_DELIVERY_PROMPT.md").write_bytes(
        _fu561.splice_all(_prompt, _empty, _prompt).encode("utf-8"))
    (_scratch / "docs/WORKSTATION_IDBO_LIVING_PLAN.md").write_bytes(
        _fu561.splice_all(_living, _empty, _prompt).encode("utf-8"))
    (_scratch / "docs/FOLLOWUPS.json").write_bytes(b'{"items": []}\n')
    _env = dict(_os561.environ, WORKSTATION_FOLLOWUPS_ROOT=str(_scratch), PYTHONIOENCODING="utf-8")
    _script = str((_root / "scripts/followups.py").resolve())

    def _cli(*argv):
        return _sp561.run([_sys561.executable, _script, *argv], env=_env, capture_output=True,
                          text=True, encoding="utf-8")

    def _rows():
        return _json561.loads((_scratch / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))["items"]

    for _n in range(4):
        assert _cli("add", "--title", f"w561 row {_n}", "--why", "w", "--source", "test",
                    "--slot", _first_open, "--files", "agentic_core/api/living_plan.py").returncode == 0

    #  (a) --because is RECORDED, with its meaning, so a reader need not know the vocabulary
    _r = _cli("close", "FU-001", "--by", "W561", "--because", "already_satisfied")
    assert _r.returncode == 0, _r.stderr
    assert "closed as already_satisfied" in _r.stdout, _r.stdout
    _row = next(x for x in _rows() if x["id"] == "FU-001")
    assert _row["because"] == "already_satisfied", _row
    assert _row["because_means"] == _KINDS["already_satisfied"], _row

    #  (b) A CLOSE WITHOUT --because SAYS SO rather than passing silently. Omitting it is allowed —
    #      refusing would make every historical closure unrepeatable — but it is never invisible.
    _r2 = _cli("close", "FU-002", "--by", "W561")
    assert _r2.returncode == 0, _r2.stderr
    assert "NO --because" in _r2.stdout and "cannot tell what kind" in _r2.stdout, _r2.stdout
    assert "because" not in next(x for x in _rows() if x["id"] == "FU-002"), _rows()

    #  (c) THE REACHABILITY CHECK, which is what the Owner's ruling of 2026-10-03 needs: a closure that
    #      removed a code artefact carries the check that established reachability.
    _r3 = _cli("close", "FU-003", "--by", "W561", "--because", "built",
               "--check", "called the route and read a 404; no import search was used")
    assert _r3.returncode == 0, _r3.stderr
    _row3 = next(x for x in _rows() if x["id"] == "FU-003")
    assert _row3["reachability_check"].startswith("called the route"), _row3

    #  (d) OR IT SAYS THE CHECK CANNOT BE RECOVERED — named, never silently absent
    _r4 = _cli("close", "FU-004", "--by", "W561", "--because", "built",
               "--unaudited", "the round that removed it left no commit in git")
    assert _r4.returncode == 0, _r4.stderr
    _row4 = next(x for x in _rows() if x["id"] == "FU-004")
    assert "left no commit" in _row4["reachability_unaudited"], _row4
    assert "reachability_check" not in _row4, _row4

    #  (e) AND THE TWO ARE ALTERNATIVES. Recording how reachability was established AND that it cannot
    #      be recovered is a contradiction, and whichever a later reader believed would be a coin toss.
    assert _cli("add", "--title", "w561 both", "--why", "w", "--source", "test", "--slot",
                _first_open).returncode == 0
    _r5 = _cli("close", "FU-005", "--by", "W561", "--check", "x", "--unaudited", "y")
    assert _r5.returncode != 0, ("a row recorded BOTH a check and that the check is unrecoverable",
                                 _r5.stdout)
    assert "alternatives" in (_r5.stdout + _r5.stderr), (_r5.stdout, _r5.stderr)
    assert next(x for x in _rows() if x["id"] == "FU-005")["status"] == "open", "the refusal still wrote"

    #  (f) AN UNKNOWN KIND IS REFUSED BY THE PARSER — the vocabulary is closed, not advisory
    _r6 = _cli("close", "FU-005", "--by", "W561", "--because", "finished")
    assert _r6.returncode != 0 and "invalid choice" in (_r6.stderr + _r6.stdout), _r6.stderr[:200]

    # ── L3. RETROSPECTION REPORTS THE MIX, and does NOT attribute the unrecorded ones ────────────
    _a = client.get("/api/v1/method/appraise", params={"scope": "P2"})
    assert _a.status_code == 200, _a.text
    _retro = _a.json()["faculties"]["retrospection"]
    assert isinstance(_retro["closure_kinds"], dict), _retro
    assert _retro["closure_kinds"], "the mix is empty, so the faculty reports nothing about kind"
    #  rows closed before the field existed are not_recorded — NEVER counted as built, because
    #  attributing them would invent the very distinction the field exists to stop inventing
    assert "not_recorded" in _retro["closure_kinds"], _retro["closure_kinds"]
    assert _retro["closures_with_a_kind"] + _retro["closure_kinds"]["not_recorded"] == \
        _retro["rows_built_or_satisfied"], (_retro["closure_kinds"], _retro["rows_built_or_satisfied"])
    assert "stop inventing" in _retro["closure_kind_basis"], _retro["closure_kind_basis"]

    # ── L4. THE OWNER'S FIVE RULINGS OF 2026-10-03 ARE RECORDED AS CONSTITUTION ──────────────────
    assert "OWNER RULINGS 2026-10-03 (FIVE" in _prompt, "the rulings are not in the plan"
    for _ruled in ("P2.4 IS TWO ITEMS", "P2.4's SECOND LEG IS PROSPECTIVE", "P2.17(b)3 IS MET",
                   "-n 6 IS WHAT A COMMIT IS TRUSTED TO",
                   "THE VSB LEDGER'S DOUBLE-ENTRY ACCOUNTS ARE AUTHORITATIVE"):
        assert _ruled in _prompt, ("a ruling is missing from the block", _ruled)
    #  AND WHAT WAS DECIDED WITHOUT ASKING IS RECORDED TOO, so the filtering is auditable rather than
    #  silent — twelve questions were surfaced and five were put to the Owner.
    assert "WHAT WAS DECIDED WITHOUT ASKING" in _prompt, (
        "the questions settled without the Owner are not recorded, so the filtering cannot be checked")


def test_w562_p24_is_two_items_and_the_new_one_has_a_bar_made_of_deliverables(client):
    """Owner ruling 2026-10-03 (1): P2.4 closes on its WRITTEN bar; the arrivals become P2.18.

    THE MEASUREMENT THAT PROMPTED IT: P2.4's four clusters name 20 rows, 18 of which were already
    closed, so exactly TWO of its 17 open rows were in its bar at all. The other fifteen arrived after
    the bar was written — ten through routes handed in when other items closed. Widening the bar to
    cover them would be a round reinterpreting the Owner's own derivation.
    """
    import json as _json562
    import pathlib as _pl562
    import re as _re562

    import agentic_core.plan_followups as _fu562

    _root = _pl562.Path(__file__).resolve().parents[1]
    _prompt = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    _reg = _json562.loads((_root / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))

    # ── L1. P2.18 EXISTS AND THE PARSER READS IT AS P2 BUILD WORK ────────────────────────────────
    #  Driven because both failed on the first attempt and looked right in the file: the item was
    #  placed after the PHASE P3 heading and parsed as P3 (a phase comes from the running heading, never
    #  from the slot number), and its name wrapped to a second line so the title parsed as the single
    #  word "AN".
    _items = _fu562.plan_items(_prompt)
    _p218 = next((i for i in _items if i["slot"] == "P2.18"), None)
    assert _p218, "P2.18 is not in the plan"
    assert _p218["phase"] == "P2", ("P2.18 parsed into the wrong phase", _p218)
    assert _p218["delivered_by"] == "build", _p218
    assert _p218["title"].startswith("AN ABSENCE THAT READS AS A FACT"), (
        "P2.18's name did not survive parsing", _p218["title"])
    _p24 = next(i for i in _items if i["slot"] == "P2.4")
    assert _p24["phase"] == "P2", _p24
    #  NEITHER ITEM'S `done` IS ASSERTED, and that correction came from refuting this very test. `done`
    #  is plan PROGRESS, not a property of the split under examination, and closing P2.4 is the stated
    #  objective of the current sequence — so asserting it open would turn this guard red on success,
    #  which is the shape P2.18's own clause (b) forbids and which has already cost six suite re-runs.
    #  The parse properties are phase, delivered_by and title; those are what the round got wrong.

    # ── L2. THE SPLIT IS EXACTLY WHAT THE RULING SAYS ────────────────────────────────────────────
    def _open(slot):
        return sorted(r["id"] for r in _reg["items"]
                      if r.get("status") == "open" and r.get("slot") == slot)
    _p24_rows, _p218_rows = _open("P2.4"), _open("P2.18")
    #  P2.4 keeps ONLY rows its clusters name, plus the three HIGH the ruling held there.
    _clusters = set()
    _i, _j = _prompt.index("\n P2.4 "), _prompt.index("\n P2.5 ")
    for _ln in _prompt[_i:_j].split("\n"):
        if _re562.match(r"\s*\([a-d]\) [A-Z]", _ln):
            _clusters |= set(_re562.findall(r"FU-\d+", _ln))
    assert len(_clusters) >= 20, ("the four clusters name fewer rows than the bar states", len(_clusters))
    _HIGH = {"FU-332", "FU-346", "FU-354"}
    for _id in _p24_rows:
        assert _id in _clusters or _id in _HIGH, (
            f"{_id} rides P2.4 and is neither named in a cluster nor one of the three HIGH rows the "
            f"ruling held there — the item is refilling", _p24_rows)
    #  THE PROPERTY IS "IT DID NOT MOVE", NOT "IT IS STILL OPEN". `_p24_rows` is the OPEN rows, so
    #  requiring the three HIGH rows to appear in it required them to stay open forever — and fixing
    #  them is exactly the P2.4 work this sequence is driving toward. Found by refuting this test, which
    #  had named the class in its own next leg and then committed it here. A closed row is a success; a
    #  row that is still open and has been rerouted is the defect.
    _slot_of = {r["id"]: r.get("slot") for r in _reg["items"]
                if r.get("status") == "open"}
    for _id in sorted(_HIGH):
        if _id in _slot_of:
            assert _slot_of[_id] == "P2.4", (
                f"{_id} is one of the three HIGH rows the ruling held inside P2.4 and it is open on "
                f"{_slot_of[_id]} instead", sorted(_HIGH))
    #  and NOTHING on P2.18 is named by a P2.4 cluster
    for _id in _p218_rows:
        assert _id not in _clusters, (f"{_id} is named in a P2.4 cluster and was moved out of it", _id)
    #  W577 — THIS LEG COMMITTED THE CLASS ITS OWN TWO COMMENTS ABOVE NAME. It counted `_p218_rows`,
    #  which `_open` defines as the OPEN rows, so every row P2.18 CLOSED pushed the count down toward
    #  this floor: W576 closed six of clause (a)'s seven and W577 closed the last plus FU-395, and the
    #  guard went red on the item progressing. "The arrivals moved" is a statement about where a row
    #  SITS, and closing one does not un-move it — so it is counted over EVERY status, which only ever
    #  grows. (It survived W576 only because that round's suite ran BEFORE its rows were closed, so the
    #  register the commit shipped was never the register the suite saw.)
    _p218_all = sorted(r["id"] for r in _reg["items"] if r.get("slot") == "P2.18")
    assert len(_p218_all) >= 10, ("the arrivals did not move", _p218_all)

    # ── L3. EVERY MOVED ROW SAYS WHY IT MOVED ────────────────────────────────────────────────────
    #  A reslot with no stated reason is how a row ends up somewhere nobody can justify later.
    #  THE PROPERTY IS "IT STATES WHY IT IS HERE", NOT "IT NAMES THAT RULING". The first form pinned the
    #  leg to the twelve rows the ruling moved, so the first row legitimately FILED here afterwards made
    #  it fail — the FU-365 class, a guard that fails on success. A mover must keep its provenance; a
    #  native arrival owes a reason, not a date it did not come from.
    for _r in _reg["items"]:
        if _r.get("status") == "open" and _r.get("slot") == "P2.18":
            _src = (_r.get("slot_source") or "").strip()
            assert _src, (_r["id"], "rides P2.18 with no stated reason for being here")
            if "P2.4" in _src:
                assert "2026-10-03" in _src, (
                    _r["id"], "came out of P2.4 without naming the ruling that moved it", _src)

    # ── L4. P2.18's BAR IS DELIVERABLES, AND CARRIES NO ROW ID AT ALL ────────────────────────────
    #  The register's own guard only refuses an id belonging to ANOTHER item, so listing its own would
    #  have passed. It carries none anyway, and the reason was paid for in this round: FU-369 could not
    #  be moved out of P2.4 until a sentence naming it was rewritten. An id baked into a bar makes the
    #  row harder to move, and a bar of deliverables should not care which rows sit under it today.
    #  W572 — THE SLICE RAN TO MILESTONE M2 AND SO WAS NEVER P2.18's BAR. It only looked right while
    #  P2.18 was the last P2 item: the moment M1 came back NOT MET and P2.19 was chartered to carry
    #  the twenty, this leg read P2.19's text as P2.18's and went red on the plan advancing — FU-365's
    #  class, in a guard whose own subject is a bar that must not go stale. The bar ends at the NEXT
    #  heading, whatever that turns out to be.
    #  AND THE RULE STAYS SPECIFIC TO P2.18, deliberately. MEASURED before widening it: 12 of the 19
    #  P2 items cite row ids in their bars, so "a bar carries no row id" is NOT the plan's convention.
    #  It is this item's, for the reason below — P2.18 is the sink chartered to RECEIVE arrivals, and
    #  an id baked into its bar makes the row harder to move out again.
    _k = _prompt.index("\n P2.18 ")
    _nxt = _re562.search(r"\n (?:P\d+\.\d+ |MILESTONE |WHEN THE MILESTONES RUN)", _prompt[_k + 1:])
    _l = (_k + 1 + _nxt.start()) if _nxt else _prompt.index("\n MILESTONE M2")
    _bar = _prompt[_k:_l]
    assert _l > _k and len(_bar) < 12000, (
        "P2.18's bar did not terminate at the next heading, so this leg is reading another item's "
        "text as P2.18's", len(_bar))
    assert not _re562.findall(r"FU-\d+", _bar), (
        "a row id survives inside P2.18's bar", _re562.findall(r"FU-\d+", _bar))
    #  W577 (FU-365) — these were pinned as "(a) TITLE" with nothing allowed between, so marking a
    #  clause DELIVERED broke the leg: the whole point of a clause is that it eventually closes, and
    #  P2.19 already carries "(a) DELIVERED W573" markers in exactly this position. A guard asserting a
    #  clause EXISTS must not also forbid it from reporting progress. The label and the title are the
    #  durable part; whatever a round writes between them is not this leg's business.
    for _letter, _clause in (("a", "AN ABSENCE REACHES THE READER"),
                             ("b", "THE SUITE'S INSTRUMENTS PROVE WHAT THEY CLAIM"),
                             ("c", "TWO NAMED SINGLES")):
        #  `.` already excludes a newline, so the clause label and its title must sit on ONE line
        assert _re562.search(r"\(" + _letter + r"\).{0,80}?" + _re562.escape(_clause), _bar), (
            "a clause is missing from P2.18", _letter, _clause)
    #  the ACCEPT binds the same discipline the Owner's second-leg ruling set
    #  fragments JSX-style line wrapping cannot split: the full sentences wrap across lines in the
    #  plan, so a literal match on them finds nothing even though they are present.
    #  THE NEGATION IS PART OF THE NEEDLE. These two dropped it — "only on the API beneath it" and
    #  "closes on a count of rows" — so rewriting the bar to say a clause IS satisfied by a row count,
    #  or that a property may be driven ONLY on the API, left both asserts green. The leg could not fail
    #  on the condition its own message named: the same shape as a fix comment quoting the literal it
    #  forbids, inverted. Whitespace-normalised because both sentences wrap in the plan.
    _flat_bar = " ".join(_bar.split())
    assert "never only on the API beneath it" in _flat_bar, (
        "P2.18's bar no longer requires its properties to be driven on the surface a person reads")
    assert "seen to turn it RED" in _flat_bar, (
        "P2.18's bar no longer requires a blind to be seen failing")
    assert "no clause closes on a count of rows" in _flat_bar, (
        "P2.18's bar can be satisfied by closing rows, which is the defect it was chartered to avoid")
    #  AND IT SAYS WHERE THE ROUTES GO, so P2.4 does not refill after it closes
    assert "--hand-to P2.18" in _bar, "the bar does not say what becomes of P2.4's routes"

    # ── L5. THE RULING IT IMPLEMENTS IS RECORDED AS CONSTITUTION ─────────────────────────────────
    assert "P2.4 IS TWO ITEMS" in _prompt, "the ruling this item implements is not in the plan"
    #  ANCHORED ON THE FULL HEADING. It was split on "OWNER RULINGS 2026-10-03", and the moment a second
    #  block of the same date was recorded ("2026-10-03b") the slice returned THAT one instead — the same
    #  collision that stole the W544 archive leg in this round. A date is not an identifier.
    _r5 = " OWNER RULINGS 2026-10-03 (FIVE, on what actually closes Phase 2"
    assert _prompt.count(_r5) == 1, ("the five-ruling block of 2026-10-03 is not where it was",
                                     _prompt.count(_r5))
    assert "P2.18" in _prompt.split(_r5)[1][:3000], (
        "the ruling block does not name the item the split creates")


def test_w563_the_other_twenty_three_archived_modules_are_decided_on_both_axes(client):
    """FU-356: the W544 record named 23 modules it did not assess. This asserts they are now decided.

    ON TWO AXES, because axis one alone answers the wrong question. Axis one reads the code (verdict);
    axis two asks whether the capability is wanted here at all (disposition). The second is the answer:
    ZERO of the twenty-three are WANTED_RECOVER, while for eighteen the vision does call for the
    capability — so "is it recoverable" was never the question that mattered.

    The completeness leg computes its list from the DIRECTORY, never from this prose, for the reason W544
    recorded: that section's first draft claimed ten because the listing it was written from was truncated
    at fourteen and nobody re-counted.
    """
    import json as _json563
    import pathlib as _pl563
    import re as _re563

    _root = _pl563.Path(__file__).resolve().parents[1]
    _doc = (_root / "docs/BIOGEOCHEMICAL_AND_COMMS_REVIEW.md").read_text(encoding="utf-8")
    _prompt = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    _reg = _json563.loads((_root / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))

    _mark = "## The other twenty-three, read and decided (W563"
    assert _mark in _doc, "the W563 record is not in the review doc"
    _sec = _doc[_doc.index(_mark):]

    # ── L1. EVERY UNASSESSED MODULE IS NAMED, AND THE LIST COMES FROM THE DIRECTORY ───────────────
    _arch = _root / "_archive/jules-unwired/agentic_core/biomimicry"
    assert _arch.is_dir(), "the archived biomimicry package has moved"
    _all = sorted(p.stem for p in _arch.glob("*.py") if p.stem != "__init__")
    #  the ten W544 covered: FU-243's seven named files plus the three siblings adjacent to them
    _w544 = {"ant_colony", "homeostasis", "emergence", "immune", "economy", "federation",
             "communication", "avatar", "apoptosis", "autophagy"}
    assert _w544 <= set(_all), ("a module the W544 table covers has left the archive",
                                sorted(_w544 - set(_all)))
    _rest = [m for m in _all if m not in _w544]
    assert len(_rest) == 23, ("the archive no longer holds 33 top-level modules", len(_all), len(_rest))
    for _m in _rest:
        assert f"`{_m}.py`" in _sec, (f"{_m}.py is not named in the W563 record — the same gap W544 "
                                      f"left, one layer along")

    # ── L2. EACH ONE CARRIES A VERDICT AND A DISPOSITION, AND THE TALLIES ARE COMPUTED ────────────
    #  Not trusted from the prose: the counts come from the table rows and must equal what it claims.
    _VERDICTS = ("RETIRE", "RECOVERABLE_WITH_REPAIR")
    _DISPOSITIONS = ("SUPERSEDED", "WANTED_REBUILD", "NOT_WANTED", "WANTED_RECOVER")
    _rows = [ln for ln in _sec.split("\n") if ln.startswith("| `") and ln.count("|") >= 6]
    assert len(_rows) == 23, ("the table does not carry one row per module", len(_rows))
    _seen, _disp = {}, {}
    for _ln in _rows:
        _cells = [c.strip() for c in _ln.strip().strip("|").split("|")]
        _name = _cells[0].strip("`")
        _vcell, _dcell = _cells[4], _cells[5]
        _v = [x for x in _VERDICTS if x in _vcell]
        _d = [x for x in _DISPOSITIONS if x in _dcell]
        #  EXACTLY ONE, not at-least-one. A cell that names the verdict it was corrected FROM reads as
        #  both, and a tally computed off it silently takes whichever the code happened to prefer —
        #  which is how this leg first went red. The ambiguity is forbidden rather than resolved; where
        #  a correction needs recording, the cell says so without quoting the other verdict's name.
        assert len(_v) == 1, (_name, "names none or several verdicts in its verdict cell", _vcell[:110])
        assert len(_d) == 1, (_name, "names none or several dispositions in its cell", _dcell[:110])
        _seen[_name] = _v[0]
        _disp[_name] = _d[0]
    assert len(_seen) == 23, ("a module appears twice in the table", len(_seen))
    #  The table is the judge of the verdict tally too: it carries the one verdict the verifier changed,
    #  so the table reads 15/8 while the first pass read 14/9, and the prose must state both.
    _n_ret = sum(1 for v in _seen.values() if v == "RETIRE")
    _n_rec = sum(1 for v in _seen.values() if v == "RECOVERABLE_WITH_REPAIR")
    assert (_n_ret, _n_rec) == (15, 8), ("the verdict tally in the table moved", _n_ret, _n_rec)
    assert "fourteen RETIRE, nine RECOVERABLE_WITH_REPAIR" in _sec, (
        "the record no longer states what the first pass found, so the correction becomes invisible")
    _corrected = " ".join(_sec.split())
    assert "fifteen and eight after the one verdict-changing correction" in _corrected, (
        "the record no longer states the corrected tally the table actually carries")
    _n_sup = sum(1 for d in _disp.values() if d == "SUPERSEDED")
    _n_reb = sum(1 for d in _disp.values() if d == "WANTED_REBUILD")
    _n_not = sum(1 for d in _disp.values() if d == "NOT_WANTED")
    assert (_n_sup, _n_reb, _n_not) == (15, 4, 4), ("the disposition tally moved without the prose",
                                                    _n_sup, _n_reb, _n_not)
    assert "fifteen SUPERSEDED, four WANTED_REBUILD, four NOT_WANTED" in _sec, (
        "the stated tally no longer matches the table it is computed from")

    # ── L3. ZERO ARE WANTED_RECOVER, WHICH IS THE WHOLE FINDING ───────────────────────────────────
    assert not any(d == "WANTED_RECOVER" for d in _disp.values()), (
        "a module is marked WANTED_RECOVER while the record's headline says none is",
        [k for k, v in _disp.items() if v == "WANTED_RECOVER"])
    assert "ZERO\nWANTED_RECOVER" in _sec or "ZERO WANTED_RECOVER" in _sec, (
        "the record no longer states that nothing is wanted as a recovery")

    # ── L4. NOTHING IS RECOVERED, AND THAT IS CHECKED IN THE TREE RATHER THAN CLAIMED ─────────────
    #  A record that says "nothing is recovered" is a sentence; this is the property.
    _live = _root / "agentic_core/biomimicry"
    _live_tops = {p.stem for p in _live.glob("*.py")} if _live.is_dir() else set()
    for _m in _rest:
        assert _m not in _live_tops, (f"agentic_core/biomimicry/{_m}.py exists — a module this record "
                                      f"says is not recovered has been recovered")
    _ref = _re563.compile(r"biomimicry[./\\ ]+(" + "|".join(_rest) + r")\b")
    _offenders = []
    for _p in list((_root / "agentic_core").rglob("*.py")) + list(_root.glob("scripts/*.py")):
        _s = str(_p).replace("\\", "/")
        if "/_archive/" in _s or "/__pycache__/" in _s:
            continue
        if _ref.search(_p.read_text(encoding="utf-8", errors="replace")):
            _offenders.append(_s)
    assert not _offenders, ("a live module imports one of the twenty-three", _offenders[:5])

    # ── L5. THE VERIFICATION PASS IS REPORTED WITH ITS BREAKDOWN, AND IT SUMS ─────────────────────
    #  Stated rather than smoothed, because the largest class is a MISSED fabrication: the first read
    #  was systematically too generous, and a record that reported only the first pass would inherit it.
    _m5 = _re563.search(r"\*\*(\d+) wrong, (\d+) a missed fabrication, (\d+)\s*\n?\s*overstated, "
                        r"(\d+) unsupported\.\*\*", _sec)
    assert _m5, "the verification breakdown is not stated"
    _parts = [int(x) for x in _m5.groups()]
    assert sum(_parts) == 46, ("the breakdown does not sum to the corrections claimed", _parts)
    assert _parts[1] == max(_parts), ("the largest correction class is no longer the missed fabrication, "
                                      "so the sentence drawing that conclusion is stale", _parts)

    # ── L6. THE ONTOLOGY-ENGINE ROW IS UNGATED AND SITS WHERE A CLUSTER NAMES IT ──────────────────
    #  THREE-STATE ON PURPOSE. Pinning this row to an open P2.4 would fail the moment P2.4 closes and
    #  the row closes with it — the FU-365 class, a guard that fails on success.
    _fu077 = next((r for r in _reg["items"] if r["id"] == "FU-077"), None)
    assert _fu077, "the ontology-engine row has left the register"
    if _fu077.get("status") == "open":
        assert _fu077.get("owner_gated") is False, (
            "the ontology-engine row is gated again, though the Owner ruled it on 2026-09-30 — retire "
            "the engine, keep the asset, reclassify it honestly")
        _slot = _fu077.get("slot")
        assert _slot and _slot != "OWNER", ("an ungated row still renders as awaiting the Owner", _slot)
        _i, _j = _prompt.index(f"\n {_slot} "), len(_prompt)
        for _nxt in _re563.finditer(r"\n P\d+\.\d+ ", _prompt[_i + 1:]):
            _j = _i + 1 + _nxt.start()
            break
        _blk = _prompt[_i:_j]
        _named = any(_re563.match(r"\s*\([a-d]\) [A-Z]", _ln) and "FU-077" in _ln
                     for _ln in _blk.split("\n"))
        assert _named, (f"the ontology-engine row rides {_slot} and no cluster heading there names it, "
                        f"so the item's bar does not cover it")
    assert "FU-077, WHICH HAS MOVED OUT OF THIS ITEM" not in _prompt, (
        "the W535 note still says the row has moved out, four rounds after the ruling that returned it")

    # ── L7. THE OWNER QUESTION IS RECORDED, AND THE HALF IT GOVERNS IS NOT BUILT ──────────────────
    #  fitness.py's implicit channel models a PERSON from their own behaviour. It breaches no ruling as
    #  it stands, which is exactly why the question has to be asked before anyone rebuilds that half.
    assert "is the subject a person?" in _sec.lower(), (
        "the record does not put the one-question test to the Owner")
    assert "the explicit rating only" in _sec, (
        "the record does not state what may be built while the question is open")
    #  ASSERTED ON THE BINDING, not on the word. W584 fixed this after it bit: the screen searched every
    #  live module's TEXT for "dwell", and the explicit rating the Owner's ruling of 2026-10-03c option
    #  (a) permits was built with a disclosure saying - truthfully, in the ruling's own words - "no dwell
    #  time, no implicit signal and no behavioural aggregate enters this figure". The sentence stating the
    #  rule tripped the screen for the rule, which is the banned-literal class. An implicit per-person
    #  channel has to be something a module BINDS - a field, a key, a parameter, an attribute - and prose
    #  cannot be mistaken for one, because a bound name is short and has no spaces. Rewording the
    #  disclosure instead would have weakened a true statement to satisfy a text search.
    import ast as _ast563
    _dwell = []
    for _p in list((_root / "agentic_core").rglob("*.py")):
        _s = str(_p).replace("\\", "/")
        if "/_archive/" in _s or "/__pycache__/" in _s:
            continue
        _txt = _p.read_text(encoding="utf-8", errors="replace")
        if "dwell" not in _txt.lower():            # cheap pre-filter; only candidates are parsed
            continue
        try:
            _tree563 = _ast563.parse(_txt)
        except SyntaxError:                        # a file that does not parse is a different defect
            _dwell.append(_s + " (does not parse)")
            continue
        _names563 = set()
        for _n563 in _ast563.walk(_tree563):
            if isinstance(_n563, _ast563.Name):
                _names563.add(_n563.id.lower())
            elif isinstance(_n563, (_ast563.FunctionDef, _ast563.AsyncFunctionDef, _ast563.ClassDef)):
                _names563.add(_n563.name.lower())
            elif isinstance(_n563, _ast563.arg):
                _names563.add(_n563.arg.lower())
            elif isinstance(_n563, _ast563.keyword) and _n563.arg:
                _names563.add(_n563.arg.lower())
            elif isinstance(_n563, _ast563.Attribute):
                _names563.add(_n563.attr.lower())
            elif isinstance(_n563, _ast563.Constant) and isinstance(_n563.value, str):
                if len(_n563.value) <= 40 and " " not in _n563.value:
                    _names563.add(_n563.value.lower())
        if any("dwell" in _b563 for _b563 in _names563):
            _dwell.append(_s)
    assert not _dwell, ("the implicit per-person channel is being built while the question is open",
                        _dwell[:5])

    # ── L8. THE THREE FURTHER RULINGS OF 2026-10-03 ARE RECORDED AS CONSTITUTION ──────────────────
    assert " OWNER RULINGS 2026-10-03b (THREE MORE" in _prompt, (
        "the Owner's three further rulings of 2026-10-03 are not in the plan")
    _blk8 = _prompt.split("OWNER RULINGS 2026-10-03b")[1][:6000]
    for _frag in ("THE MILESTONE MUST RUN, AND M1 RUNS FIRST",
                  "THE AVATAR PATH IS HELD",
                  "THE DISTRESS ROUTES"):
        assert _frag in _blk8, ("a ruling is missing from the block", _frag)
    #  the first of them turns on a measured fact, and the fact is what makes it binding
    assert "EXACTLY TWICE, EVER" in _blk8, (
        "the milestone ruling no longer carries the measurement that justifies it")
    assert "AND THE LIST IS NOT INVENTED" in _blk8, (
        "the distress ruling no longer carries the limit that a route may not be supplied by this "
        "programme — the one fabrication no later correction reaches")


def test_w564_a_distress_route_arrives_with_its_reviewer_or_it_does_not_arrive(client):
    """FU-361 under the Owner's ruling: the MECHANISM is built now and the DATA stays the Owner's.

    Two properties that pull against each other, which is why they are driven together. The route list
    must become possible to supply honestly — with a named reviewer, a check date and a staleness rule —
    WITHOUT making it one step easier to invent one. So this asserts the validator refuses every
    incomplete shape, that the reader keeps three states apart, and that nothing on the path holds a
    route or anything a person could read as a number to dial.
    """
    import datetime as _dt564
    import pathlib as _pl564
    import re as _re564

    from agentic_core.gaas.v5 import horizon_guardrails as _g564

    _root = _pl564.Path(__file__).resolve().parents[1]
    _T = _dt564.date(2026, 1, 1)                     # a fixed today: the rule is about ages, not now

    # ── L1. STILL NOTHING SUPPLIED, AND THE READER SAYS SO IN THREE STATES ────────────────────────
    #  THE ROUTE IS LOADED, NOT HARD-CODED — and this leg asserted it was EMPTY, so it would have gone
    #  red the moment the Owner supplied one: a guard failing on success, which is the shape this very
    #  test was written to police. The property is that the module writes no route of its own.
    _msrc = (_root / "agentic_core/gaas/v5/horizon_guardrails.py").read_text(encoding="utf-8")
    assert not _re564.search(r"DISTRESS_ROUTES\s*(?::[^=]*)?=\s*\(\s*\{", _msrc), (
        "a distress route is written into the module rather than loaded from data")
    #  the NOT_SUPPLIED arm is driven with an explicitly empty input, not by hoping none is supplied
    _none = _g564.distress_routes(_T, ())
    assert _none["state"] == _g564.NOT_SUPPLIED, _none["state"]
    #  None, never []. An empty list on a surface reads as "nothing was needed here".
    assert _none["routes"] is None, ("an empty list came back where an unfilled field belongs",
                                     _none["routes"])
    assert "NOT SUPPLIED" in _none["basis"] and "might act on it" in _none["basis"], _none["basis"]
    assert _none["stale_count"] == 0

    # ── L2. EVERY INCOMPLETE SHAPE IS REFUSED, AND THE REFUSAL NAMES THE FIELD ───────────────────
    #  Driven one field at a time, because a validator that only refuses the empty dict would pass a
    #  record carrying a route and nothing else — which is exactly the dangerous shape.
    _R = "ask-a-human"                               # not dialable, deliberately: see L5
    _OK = {"route": _R, "reviewed_by": "a named body", "checked_on": "2025-12-01",
           "jurisdiction": _g564.JURISDICTION_ANY}
    #  `jurisdiction` WAS MISSING FROM THE FIRST CUT OF THIS MECHANISM, though FU-361 required it from
    #  the start: the reviewer confirms a route is "real, current and APPROPRIATE TO THE JURISDICTION".
    #  Without it a national service could be accepted and then shown to a person it does not answer
    #  for, which is worse than NOT SUPPLIED — it sends someone somewhere instead of telling the truth.
    assert "jurisdiction" in _g564.ROUTE_FIELDS, _g564.ROUTE_FIELDS
    for _drop in ("route", "reviewed_by", "checked_on", "jurisdiction"):
        _bad = {k: v for k, v in _OK.items() if k != _drop}
        _v = _g564.accept_route(_bad, _T)
        assert _v["accepted"] is False, (_drop, "a record missing a required field was accepted", _v)
        assert _v["missing"] == [_drop], (_drop, _v["missing"])
        assert _drop in _v["basis"] and "REFUSED" in _v["basis"], _v["basis"]
        assert _v["state"] == _g564.NOT_SUPPLIED, _v["state"]
    #  a blank string is not a value
    for _blank in ("", "   "):
        _v = _g564.accept_route(dict(_OK, reviewed_by=_blank), _T)
        assert _v["accepted"] is False and _v["missing"] == ["reviewed_by"], (repr(_blank), _v)
    #  a date that is not a date, and a date nobody could have met
    _v = _g564.accept_route(dict(_OK, checked_on="last spring"), _T)
    assert _v["accepted"] is False and "ISO calendar date" in _v["basis"], _v["basis"]
    _v = _g564.accept_route(dict(_OK, checked_on="2027-06-01"), _T)
    assert _v["accepted"] is False and "in the future" in _v["basis"], _v["basis"]
    #  THREE-STATE: not-a-record is None, not False. A string handed in where a record belongs has no
    #  missing field — it has nothing — and reporting that as "present and wrong" loses the distinction.
    _v = _g564.accept_route(_R, _T)
    assert _v["accepted"] is None, ("a non-record was graded as a wrong record", _v)
    assert "not a record" in _v["basis"], _v["basis"]

    # ── L3. THE STALENESS RULE IS A RULE, DRIVEN ON BOTH SIDES OF ITS BOUNDARY ────────────────────
    #  A route that cannot go stale is trusted forever, which is the whole reason the date is required.
    _h = _g564.ROUTE_STALE_AFTER_DAYS
    assert isinstance(_h, int) and 0 < _h <= 365, ("the horizon is not a short, stated policy", _h)
    _at = (_T - _dt564.timedelta(days=_h)).isoformat()
    _past = (_T - _dt564.timedelta(days=_h + 1)).isoformat()
    _v = _g564.accept_route(dict(_OK, checked_on=_at), _T)
    assert _v["accepted"] is True and _v["stale"] is False and _v["age_days"] == _h, _v
    assert _v["state"] == _g564.SUPPLIED_FRESH, _v["state"]
    _v = _g564.accept_route(dict(_OK, checked_on=_past), _T)
    assert _v["accepted"] is True and _v["stale"] is True and _v["age_days"] == _h + 1, _v
    assert _v["state"] == _g564.SUPPLIED_STALE, _v["state"]
    #  A STALE ROUTE IS SHOWN, WITH THE FACT — not dropped and not silently passed as current.
    _s = _g564.distress_routes(_T, (dict(_OK, checked_on=_past),))
    assert _s["state"] == _g564.SUPPLIED_STALE and _s["stale_count"] == 1, _s
    assert _s["routes"] and _s["routes"][0]["stale"] is True, _s["routes"]
    assert "STALE" in _s["basis"], _s["basis"]
    #  and every accepted route travels WITH its reviewer and its date, so a surface must drop them
    #  deliberately rather than never having been given them
    for _k in ("route", "reviewed_by", "checked_on", "stale", "age_days"):
        assert _k in _s["routes"][0], (_k, "an accepted route reaches a surface without it", _s["routes"])
    #  a fresh one reports fresh, with nothing stale
    _f = _g564.distress_routes(_T, (_OK,))
    assert _f["state"] == _g564.SUPPLIED_FRESH and _f["stale_count"] == 0, _f

    # ── L4. A REFUSED RECORD DOES NOT SILENTLY VANISH ────────────────────────────────────────────
    #  If a supplied list is dropped for want of a reviewer, the surface must be able to say that the
    #  field is unfilled BECAUSE records were refused — not merely that it is unfilled.
    _r = _g564.distress_routes(_T, ({"route": _R},))
    assert _r["state"] == _g564.NOT_SUPPLIED and _r["routes"] is None, _r
    assert len(_r["refused"]) == 1 and "REFUSED" in _r["refused"][0], _r["refused"]
    assert "were REFUSED" in _r["basis"], _r["basis"]

    # ── L5. AND THE MECHANISM MADE IT NO EASIER TO INVENT A ROUTE ────────────────────────────────
    #  The leg this item has always turned on, re-asserted over the file the mechanism was added to.
    #  Note what this forbids: an ISO date is a dash-separated digit run, so the ruling's own date is
    #  NOT written in that module — a reader scanning for something to dial does not stop to check
    #  whether a digit run is a calendar date.
    _NUMBERISH = _re564.compile(r"(?:\+?\d[\d\s().-]{6,}\d)|(?:\b\d{4,}\b)")
    for _rel in ("agentic_core/gaas/v5/horizon_guardrails.py",
                 "agentic_core/api/horizon.py",
                 "apps/workstation-superapp/src/pages/governance/HorizonGuardrails.tsx"):
        _hits = [m.group(0) for m in _NUMBERISH.finditer(
            (_root / _rel).read_text(encoding="utf-8"))]
        assert not _hits, (f"{_rel} holds a digit sequence a person in distress could read as a number "
                           f"to dial; a fabricated helpline is the one fabrication no later correction "
                           f"reaches", _hits[:5])
    #  no example, template or default record either — the shapes above are supplied BY THIS TEST
    _src = (_root / "agentic_core/gaas/v5/horizon_guardrails.py").read_text(encoding="utf-8")
    for _word in ("EXAMPLE_ROUTE", "SAMPLE_ROUTE", "DEFAULT_ROUTE", "placeholder route"):
        assert _word not in _src, (_word, "the module carries a stand-in for a route")

    # ── L6. THE GATE CARRIES THE STATE, NOT JUST THE LIST ────────────────────────────────────────
    _d = _g564.clinical_care_gate("i want to kill myself")
    assert _d["escalate"] is True and _d["withhold_ai_counsel"] is True, _d
    #  THREE-STATE SINCE W566. This asserted the gate offered NO route, which would have failed the
    #  moment the Owner supplied one — and supplying one is the whole point of the mechanism.
    assert _d["human_routes_state"] in (_g564.NOT_SUPPLIED, _g564.SUPPLIED_STALE,
                                        _g564.SUPPLIED_FRESH), _d.get("human_routes_state")
    if _d["human_routes"] is None:
        assert _d["human_routes_state"] == _g564.NOT_SUPPLIED, _d.get("human_routes_state")
        assert _d["human_routes_stale_count"] == 0, _d.get("human_routes_stale_count")
        assert "NOT SUPPLIED" in _d["human_routes_basis"], _d["human_routes_basis"]
    else:
        #  a route reaching a person in distress carries who checked it, when, and where it answers
        for _r in _d["human_routes"]:
            for _f in ("route", "reviewed_by", "checked_on", "jurisdiction"):
                assert str(_r.get(_f) or "").strip(), (_f, "a shown route lacks it", _r)
        assert _d["human_routes_stale_count"] == sum(
            1 for _r in _d["human_routes"] if _r.get("stale")), (
            "the stale count disagrees with the routes' own stale flags", _d)
    #  and it still says plainly what it is
    assert "I am not a person" in (_d["statement"] or ""), _d["statement"]

    # ── L7. THE DISTRESS SCREEN CATCHES THE PHRASINGS IT IS FOR ──────────────────────────────────
    #  THIS LEG EXISTS BECAUSE THE PATTERN WAS WRONG IN LIVE CODE. `(?:my\\s+own\\s+)?` made "my" and
    #  "own" one optional unit, so the screen matched "end life" and "end my own life" and NOT the
    #  plainest phrasing between them, while escalating correctly for "kill myself". It was invisible in
    #  the regex and obvious the moment the gate was DRIVEN. A word screen is not reviewable by eye.
    for _phrase in ("i want to end my life", "i am going to end it all", "end my own life",
                    "take my life", "i want to kill myself", "i want to die",
                    "thinking about suicide", "i self-harm", "i can't go on", "no reason to live"):
        assert _g564.clinical_care_gate(_phrase)["escalate"] is True, (
            f"the distress screen does not catch {_phrase!r}, a direct phrasing of the subject it "
            f"exists for")
    #  AND IT STILL CERTIFIES NOTHING. An indirect phrasing passes, and the gate says that rather than
    #  reporting the person is well — the coverage limit is declared, not discovered.
    _ind = _g564.clinical_care_gate("nobody would miss me")
    assert _ind["escalate"] is False and _ind["certifies_absence"] is False, _ind
    assert "English phrase patterns only" in _ind["coverage"], _ind.get("coverage")

    # ── L9. THE JURISDICTION INVARIANT, AND THE REFUTATION FINDINGS THIS ROUND TOOK ──────────────
    #  Added after refuting the round's own work. Three properties, each from a CONFIRMED finding.

    #  (a) A DIALABLE ROUTE MAY NEVER BE MARKED CORRECT FOR EVERYWHERE. A number answers in one country
    #  and nowhere else, so ANY is only honest for a route that names no specific service. This is the
    #  one check in the module that reads the route STRING, and it reads it to REFUSE, never to approve.
    _dial = {"route": "call 0" + "800 1" + "23 4567", "reviewed_by": "a named person",
             "checked_on": "2025-12-01", "jurisdiction": _g564.JURISDICTION_ANY}
    _v = _g564.accept_route(_dial, _T)
    assert _v["accepted"] is False, ("a dialable route was accepted as correct for ANY jurisdiction", _v)
    assert _v["missing"] == ["jurisdiction"], _v["missing"]
    assert "answers in one" in _v["basis"], _v["basis"]
    #  the SAME route with a named place is accepted — the invariant is about ANY, not about numbers
    _v = _g564.accept_route(dict(_dial, jurisdiction="a named place"), _T)
    assert _v["accepted"] is True and _v["jurisdiction"] == "a named place", _v

    #  (b) WHAT IS COVERED IS REPORTED, AND THE KEYS ARE PRESENT WHEN NOTHING IS. A caller that has to
    #  test whether a key exists will eventually forget to, and an unfilled field then reads as full
    #  coverage — so both arms of the reader carry `jurisdictions` and `covers_anywhere`.
    _n9 = _g564.distress_routes(_T)
    assert _n9["jurisdictions"] == [] and _n9["covers_anywhere"] is False, _n9
    _a9 = _g564.distress_routes(_T, (_OK,))
    assert _a9["covers_anywhere"] is True and _a9["jurisdictions"] == [_g564.JURISDICTION_ANY], _a9
    _p9 = _g564.distress_routes(_T, (dict(_OK, jurisdiction="a named place"),))
    assert _p9["covers_anywhere"] is False, (
        "a route for one named place reports that it covers everywhere", _p9)
    assert _p9["routes"][0]["jurisdiction"] == "a named place", _p9["routes"]

    #  (c) THE READER MATERIALISES ITS INPUT. It iterates twice — once to judge, once to zip the
    #  verdicts back — so a one-shot iterable left the second pass empty, dropped every accepted route,
    #  and returned NOT_SUPPLIED with the bare basis "no human distress route is recorded on this
    #  platform" about a call it had just been handed a valid one on. A basis asserting what it did not
    #  compute, on the distress path. No live caller passes a generator; the leg exists so none can.
    _gen = (r for r in (_OK,))
    _g9 = _g564.distress_routes(_T, _gen)
    assert _g9["state"] == _g564.SUPPLIED_FRESH, (
        "a one-shot iterable of valid routes came back as NOT SUPPLIED", _g9["state"], _g9["basis"][:120])
    assert _g9["routes"] and _g9["routes"][0]["route"] == _R, _g9["routes"]

    # ── L10. THE DISTRESS SCREEN'S VERB SLOT, WHICH THIS ROUND GOT WRONG TWICE ───────────────────
    #  L7 above drives the bare verb. THIS drives the INFLECTIONS, which the W564 fix left out: every
    #  verb was a literal followed by \\s+, so the character after the lemma had to be whitespace, and
    #  in "killing" it is "i". "ending my life", "killing myself", "cutting myself", "harming myself"
    #  and "taking my own life" all passed the screen — AND THE PROGRESSIVE IS THE COMMONEST FORM A
    #  PERSON WRITES. Found by a refuter driving the fix, under a comment the fix itself had added
    #  saying a word screen is not reviewable by eye.
    for _phrase in ("i am thinking of ending my life", "i keep thinking about killing myself",
                    "i have been cutting myself", "i am thinking of taking my own life",
                    "i've been harming myself", "i am hurting myself", "ending it all",
                    "i cannot go on", "i couldn't keep going", "i can't take it anymore",
                    "i am wanting to die", "i have been self-harming", "he took his own life",
                    "she ended her life", "no reason to carry on"):
        assert _g564.clinical_care_gate(_phrase)["escalate"] is True, (
            f"the distress screen does not catch {_phrase!r} — an INFLECTED form of a phrasing it "
            f"already catches in the bare stem, which is the commoner way a person writes it")
    #  AND THE WIDENING DID NOT MAKE IT FIRE ON ORDINARY TEXT. A gate that escalates on anything trains
    #  a reader to ignore it, which costs the next real match.
    for _benign in ("what is the weather today", "the battery life is poor", "my life is busy",
                    "i cut the vegetables", "i am taking my dog out", "the film ends badly",
                    "scientists study the climate"):
        assert _g564.clinical_care_gate(_benign)["escalate"] is False, (
            f"the distress screen escalates on {_benign!r}, which is ordinary text")
    #  THE KNOWN FALSE POSITIVE IS DECLARED RATHER THAN DISCOVERED, and the direction is deliberate:
    #  an escalation gives a poor answer, a miss gives AI counsel to someone in crisis.
    assert _g564.clinical_care_gate("i want to take my life in a new direction")["escalate"] is True, (
        "this phrase is expected to escalate; if it no longer does, the pattern was narrowed and the "
        "trade-off the module states has silently changed")
    _gsrc10 = (_root / "agentic_core/gaas/v5/horizon_guardrails.py").read_text(encoding="utf-8")
    assert "THE FAILURE DIRECTION IS DELIBERATE" in _gsrc10, (
        "the module no longer states that it prefers a false positive to a miss")
    assert "not a claim that the enumeration is complete" in _gsrc10, (
        "the coverage string now implies its inflection list is complete, which is the claim that has "
        "twice been false")

    # ── L8. THE OWNER'S SIX DECISIONS ARE RECORDED, AND EACH LIVES IN THE ITEM THAT MUST HONOUR IT ─
    #  Three of the six closed their decision row, which is precisely the shape FU-361 was filed
    #  against: a decision marked taken is where an obligation goes to be forgotten. So each ruling is
    #  asserted in the plan AND inside the ACCEPT clause of the item that has to keep it.
    _prompt564 = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    _h8 = " OWNER RULINGS 2026-10-03c (SIX, taken together on the recommendations put in W564"
    assert _prompt564.count(_h8) == 1, ("the six decisions of 2026-10-03c are not in the plan",
                                        _prompt564.count(_h8))
    _b8 = _prompt564.split(_h8)[1][:9000]
    for _frag in ("THE DISTRESS ROUTE: THE RECOMMENDATION IS ACCEPTED AND THE DATA IS STILL OUTSTANDING",
                  "THE AVATAR PATH: LEAVE IT",
                  "THE PLATFORM DOES NOT MODEL A PERSON: THE EXPLICIT RATING ONLY",
                  "THE LIVE LEGAL MATTER: READ-ONLY, LOCAL-ONLY, ONE NAMED FOLDER",
                  "THE TRIBUNAL OUTCOME PREDICTOR: THE REFUSAL IS CONFIRMED",
                  "M1 RUNS IMMEDIATELY AFTER P2.17 AND BEFORE P2.4"):
        assert _frag in _b8, ("a ruling is missing from the block", _frag)
    #  THE TWO WITH A MISSING INPUT SAY SO IN THE RULING ITSELF, so no reader concludes the work may
    #  start. An agreement to a recommendation is not the data the recommendation asked for, and this is
    #  the leg that stops that distinction being lost: the Owner said yes to supplying a route, which is
    #  not a route. Whitespace-normalised, because the sentence wraps.
    _flat8 = " ".join(_b8.split())
    assert "MAY NOT BE SUPPLIED BY THIS PROGRAMME" in _flat8, (
        "the distress ruling no longer states that this programme may not supply the route")
    assert "THE ROUTE ITSELF IS NOT SUPPLIED BY THIS RULING" in _flat8, _flat8[:0]
    assert "THE FOLDER IS NOT NAMED BY THIS RULING" in _flat8, (
        "the legal-matter ruling no longer states that its folder is missing")

    #  AND EACH RULING IS IN ITS ITEM'S BAR. Computed per slot, so a ruling cannot sit in the plan's
    #  history while the item it governs says nothing about it.
    def _bar564(_slot):
        _i = _prompt564.index("\n " + _slot + " ")
        _m = _re564.search(r"\n P\d+\.\d+ ", _prompt564[_i + 1:])
        return _prompt564[_i:(_i + 1 + _m.start()) if _m else len(_prompt564)]

    _p327 = " ".join(_bar564("P3.27").split())
    assert "EXPLICIT RATING ONLY" in _p327, (
        "P3.27's bar does not carry the ruling that the satisfaction signal is explicit only")
    assert "NOTHING IS INFERRED FROM HOW THEY BEHAVED" in _p327, (
        "P3.27's bar states the option without the property that makes it checkable")
    _p323 = " ".join(_bar564("P3.23").split())
    #  THE TERMS ARE STABLE; THE FOLDER'S STATUS IS NOT. This asserted the bar said "THE RULING NAMES NO
    #  FOLDER" — true when written and false one round later, when the Owner named it. A guard that fails
    #  on the thing being delivered, for the fourth time in one night. The property is that the bar states
    #  the terms AND says which state the folder is in, never that it is permanently missing.
    assert "ONE NAMED FOLDER" in _p323, (
        "P3.23's bar no longer states the term that scopes the whole indexing permission")
    assert ("THE RULING NAMES NO FOLDER" in _p323
            or "THE FOLDER IS NAMED AND CREATED EMPTY" in _p323), (
        "P3.23's bar says neither that its folder is missing nor that it has arrived, so a reader cannot "
        "tell whether the bundle half may start", _p323[:160])
    assert "never counsel" in _p323, "P3.23's bar drops the not-legal-advice statement"
    _p324 = " ".join(_bar564("P3.24").split())
    assert "THE REFUSAL IS NOW CONFIRMED BY THE OWNER" in _p324, (
        "P3.24's bar still reads as a round's proposal rather than the Owner's ruling")
    assert "MAY NOT REOPEN THIS ON ITS OWN JUDGEMENT" in _p324, (
        "P3.24's bar no longer forbids a later round reopening a confirmed refusal")

    #  THE MILESTONE SCHEDULE, the one ruling that changes what the NEXT round does.
    #  SCOPED TO THE SCHEDULE BLOCK, not searched across the plan. A blind proved why: "MILESTONE NOT
    #  RUN" also appears in the earlier ruling that introduced the reporting rule, so deleting it from
    #  the schedule left the string in the file and this leg passed with the defect in. A phrase stated
    #  twice cannot be asserted once.
    _hs = " WHEN THE MILESTONES RUN — Owner ruling 2026-10-03c"
    assert _prompt564.count(_hs) == 1, ("the milestone schedule block is not in the plan",
                                        _prompt564.count(_hs))
    _sched564 = " ".join(_prompt564.split(_hs)[1][:2600].split())
    assert "M1 RUNS IMMEDIATELY AFTER P2.17 AND BEFORE P2.4" in _sched564, (
        "the milestone schedule the Owner settled is not stated where the milestones are described")
    assert "MILESTONE NOT RUN" in _sched564, (
        "the schedule no longer says how Phase 2 is reported until M2 has run, which is the whole point "
        "of the ruling: seventeen DONE markers are not a measurement")
    assert "reach scatter resolved" in _sched564, (
        "the schedule no longer says WHY M2 cannot move, so a later round may reorder it")

    #  AND THE TWO ROWS THAT STILL HOLD AN OWNER INPUT ARE OPEN AND GATED. THREE-STATE: if either has
    #  closed then the input arrived, and this leg must not fail on that success.
    import json as _json564
    _reg564 = _json564.loads((_root / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))
    _by564 = {r["id"]: r for r in _reg564["items"]}
    for _rid, _what in (("FU-361", "the distress route"), ("FU-373", "the legal-matter folder")):
        _row = _by564.get(_rid)
        assert _row, (_rid, "the row holding an outstanding Owner input has left the register", _what)
        if _row.get("status") == "open":
            assert _row.get("owner_gated") is True, (
                _rid, f"{_what} is outstanding and the row is not gated, so a round could schedule work "
                      f"that cannot be done", _row.get("slot"))


def test_w565_one_instrument_computes_the_round_cost_and_every_suite_figure_names_its_mode(client):
    """P2.17 clause (c): the round-cost figures are COMPUTED, one instrument per quantity, mode named.

    THREE COMPUTATIONS OF THE MEDIAN ROUND EXISTED, all labelled "from git", all disagreeing. W514 had
    already removed this defect at the constants layer and again at the function layer, each time
    recording that two computations of one quantity IS the defect; the third lived in the CLI, which is
    the one a reader reads. And the surviving instrument was wrong in the same direction as the prose it
    replaced: its floor for "did this gap contain a suite" was a SERIAL suite constant, so it classified
    sixteen real rounds as follow-up commits and reported the suite's share as 44% against a real 16%.

    A CONSTANT WITH ONE HOME CAN STILL BE THE WRONG CONSTANT. That is this test's subject.
    """
    import importlib.util as _il565
    import pathlib as _pl565
    import re as _re565
    import subprocess as _sp565
    import sys as _sys565

    _root = _pl565.Path(__file__).resolve().parents[1]

    def _load(name, rel):
        _spec = _il565.spec_from_file_location(name, _root / rel)
        _m = _il565.module_from_spec(_spec)
        _spec.loader.exec_module(_m)
        return _m

    _K = _load("_w565_k", "scripts/_session_measured.py")

    # ── L1. THERE IS NO MODE-FREE SUITE CONSTANT LEFT TO READ ─────────────────────────────────────
    #  The defect was not that the constant had two homes — W514 fixed that — it was that the single
    #  home held a figure about a mode the programme no longer runs, under a name that did not say so.
    assert not hasattr(_K, "SUITE_H"), (
        "a mode-free SUITE_H is back in the constants module. A suite figure must say WHICH suite: this "
        "one was the mean of two SERIAL runs and was read as the cost, the share AND the round floor")
    for _n in ("SUITE_SERIAL_H", "SUITE_PARALLEL_H", "SUITE_IN_USE_H", "SUITE_FASTEST_H",
               "SUITE_MODE_IN_USE", "SUITE_SERIAL_BASIS", "SUITE_PARALLEL_BASIS", "SUITE_IN_USE_BASIS"):
        assert hasattr(_K, _n), (_n, "the per-mode suite constants are incomplete")
    #  each basis names its mode and its runs, so a reader cannot mistake one for the other
    assert "SERIAL" in _K.SUITE_SERIAL_BASIS and "PARALLEL" in _K.SUITE_PARALLEL_BASIS, (
        _K.SUITE_SERIAL_BASIS, _K.SUITE_PARALLEL_BASIS)
    assert _K.SUITE_MODE_IN_USE in ("serial", "parallel"), _K.SUITE_MODE_IN_USE
    assert _K.SUITE_IN_USE_H == (_K.SUITE_PARALLEL_H if _K.SUITE_MODE_IN_USE == "parallel"
                                 else _K.SUITE_SERIAL_H), "the in-use figure disagrees with the mode"
    #  AND THE PARALLEL FIGURE IS ACTUALLY FASTER, so `fastest` is not a label on the same number
    assert _K.SUITE_PARALLEL_H < _K.SUITE_SERIAL_H, (
        "the parallel suite is not measured faster than the serial one, so the two modes are not two "
        "measurements", _K.SUITE_PARALLEL_H, _K.SUITE_SERIAL_H)
    assert _K.SUITE_FASTEST_H == min(_K.SUITE_SERIAL_H, _K.SUITE_PARALLEL_H), _K.SUITE_FASTEST_H

    # ── L2. THE ROUND FLOOR IS THE FASTEST MEASURED MODE, AND SAYS WHY ───────────────────────────
    #  A round must contain A suite, so the floor has to be the fastest real one. The serial figure
    #  discarded sixteen gaps that each exceeded a measured parallel suite — real rounds, filed as
    #  follow-up commits, and the filter reported only a count.
    assert _K.MIN_ROUND_H == _K.SUITE_FASTEST_H, (
        "the round floor is not the fastest measured suite mode", _K.MIN_ROUND_H, _K.SUITE_FASTEST_H)
    assert "FASTEST MODE" in _K.MIN_ROUND_BASIS, _K.MIN_ROUND_BASIS
    assert "sixteen real rounds" in _K.MIN_ROUND_BASIS, (
        "the floor's basis no longer records what the previous floor cost, so the next round cannot tell "
        "that this was measured rather than preferred")

    # ── L3. ONE COMPUTATION: WHAT THE CLI PRINTS IS WHAT THE INSTRUMENT COMPUTES ──────────────────
    #  The property, driven rather than asserted from source. The CLI had its own git walk over FORTY
    #  commits with its own filter and printed a different median beside the register's projection.
    _sf = _load("_w565_sf", "scripts/session_forecast.py")
    _d = _sf.round_durations()
    assert isinstance(_d, dict) and "assessable" in _d, _d
    if not _d.get("assessable"):
        #  THREE-STATE: an instrument that cannot measure must say so, and the CLI must then print no
        #  figure at all rather than falling back to one.
        assert _d.get("why"), "the instrument is not assessable and gives no reason"
    else:
        for _k in ("n", "median_h", "p25_h", "p75_h", "max_h", "basis", "excluded"):
            assert _k in _d, (_k, "the instrument's report is incomplete", sorted(_d))
        _out = _sp565.run([_sys565.executable, "scripts/followups.py", "forecast"],
                          cwd=str(_root), capture_output=True, text=True, encoding="utf-8",
                          errors="replace", timeout=300)
        assert _out.returncode == 0, (_out.returncode, _out.stderr[-400:])
        _wall = [l for l in _out.stdout.splitlines() if "WALL CLOCK (" in l]
        assert len(_wall) == 1, ("the CLI printed no single wall-clock line", _wall)
        _m = _re565.search(r"(\d+) round\(s\), median ([\d.]+) h", _wall[0])
        assert _m, ("the CLI's wall-clock line does not carry n and the median", _wall[0])
        assert int(_m.group(1)) == _d["n"], (
            "the CLI and the instrument disagree on how many rounds were measured, so there are two "
            "computations of one quantity again", _m.group(1), _d["n"])
        assert float(_m.group(2)) == _d["median_h"], (
            "the CLI and the instrument disagree on the median round", _m.group(2), _d["median_h"])
        #  AND THE CLI PRINTS THE FILTER AND WHAT IT EXCLUDED. A median with an unstated filter is the
        #  shape that let three different figures stand side by side as "a separate measurement".
        assert any("WALL CLOCK FILTER:" in l for l in _out.stdout.splitlines()), (
            "the CLI prints a median without the filter that produced it")
        assert any("WALL CLOCK EXCLUDED:" in l for l in _out.stdout.splitlines()), (
            "the CLI prints a median without saying what the filter threw away")
        #  no independent walk survives in the CLI
        _cli = (_root / "scripts/followups.py").read_text(encoding="utf-8")
        _i = _cli.index("WALL CLOCK")
        _blk = _cli[max(0, _i - 2600):_i + 1800]
        assert "round_durations" in _blk, "the CLI no longer reads the instrument"
        assert '"-40"' not in _blk, (
            "the CLI's own forty-commit git walk is back, which is the third computation of one quantity")

    # ── L4. EVERY SUITE FIGURE THE FORECAST REPORTS NAMES ITS MODE ────────────────────────────────
    _f = _sf.forecast_session(8.0, since=449)
    _cost = _f.get("round_boundaries_cost")
    assert isinstance(_cost, dict), ("the forecast no longer reports the round-boundary cost", sorted(_f))
    assert _cost.get("suite_mode") == _K.SUITE_MODE_IN_USE, (
        "the forecast's suite figure does not name the mode it used", _cost.get("suite_mode"))
    assert _cost.get("suite_basis") == _K.SUITE_IN_USE_BASIS, _cost.get("suite_basis")
    assert "share_basis" in _cost, (
        "the share is reported without a basis; it was a SERIAL suite over a median computed with a "
        "SERIAL floor, which is a ratio of two different things and read as 44%")
    assert _K.SUITE_MODE_IN_USE in _cost["share_basis"], _cost["share_basis"]
    #  the share is arithmetic over the two figures it names, not a typed number
    if _d.get("assessable"):
        _expect = f"{round(100 * _K.SUITE_IN_USE_H / _d['median_h'])}%"
        assert _cost.get("share_of_a_median_round") == _expect, (
            "the reported share is not the quotient of the two figures beside it",
            _cost.get("share_of_a_median_round"), _expect)

    # ── L5. P2.17's BODY STAMPS ITS HISTORICAL FIGURES AND DOES NOT RESTATE THE CURRENT ONES ──────
    #  Clause (c)'s own words. The fix is NOT retyping the numbers: that reproduces the defect with
    #  fresher digits. A figure about a past round is stamped with the round that measured it, so it
    #  stays a true statement about that moment.
    _prompt = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    _i, _j = _prompt.index("\n P2.17 "), len(_prompt)
    _m = _re565.search(r"\n P\d+\.\d+ ", _prompt[_i + 1:])
    if _m:
        _j = _i + 1 + _m.start()
    _bar = " ".join(_prompt[_i:_j].split())
    assert "KEPT AS A STATEMENT ABOUT W488 AND NOT ABOUT NOW" in _bar, (
        "P2.17's historical figures are no longer stamped with the round that measured them")
    assert "this paragraph may not restate them" in _bar, (
        "P2.17's body no longer forbids restating the computed figures, which is how it went stale")
    assert "session_forecast.round_durations()" in _bar, (
        "P2.17's body does not name the instrument that computes its figures")
    #  AND THE REFUTED INFERENCE IS MARKED REFUTED, with the round that refuted it. Removing it would
    #  lose a true statement about what was believed; leaving it unmarked asserts something false.
    assert "REFUTED BY THE PROGRAMME'S OWN HISTORY" in _bar, (
        "P2.17's claim that a round closing an item closes EXACTLY ONE is unmarked, and it is false")
    assert "W505" in _bar and "closed five" in _bar.lower(), (
        "the refutation does not name the round that refutes it, so it cannot be checked")
    #  the narrower true statement survives beside the existence proof
    assert "has still never been run" in _bar, (
        "the body now reads as though a bundle round has been run; W505 closed two on its own work and "
        "three by auditing bars, which is not clause (a)'s bundle")

    # ── L6. CLAUSE (c) STATES A PROPERTY A GUARD CAN DRIVE ───────────────────────────────────────
    _ci = _bar.index("ACCEPT (c)")
    _c = _bar[_ci:_ci + 1400]
    for _frag in ("ONE instrument computes each quantity",
                  "NAMES THE MODE it was measured in",
                  "stamped with the round that measured it"):
        assert _frag in _c, ("clause (c) no longer states a property this test can drive", _frag)

    # ── L7. FU-350: A PENDING ASSERTION NAMES ITS RECEIPT, NOT A TOTAL ───────────────────────────
    #  MEASURED FIRST, and it corrects the row's own guess. FU-350 supposed these four were latent
    #  because "their receivers are outside the cap or not registered as living VSBs". All four are
    #  created by the tests' own `living(...)` helper, so all four ARE registered living VSBs and all
    #  four sit inside the population S12's reinvestment fans out to. They are latent for a reason
    #  unrelated to their subject, as the row suspected, but not for the reason it guessed.
    _suite = (_root / "integration_tests/test_mvp_spine.py").read_text(encoding="utf-8")

    #  (a) NO ABSOLUTE TOTAL SURVIVES AT THE FOUR SUBJECTS. A delta would not have been enough either:
    #  a S12 reinvestment can land DURING the cycle these tests run between two readings, so only the
    #  receipt itself is a safe subject.
    _abs = _re565.findall(r"peek_pending_transfers\([^)]*\)\s*==\s*(\d[\d_]*\.?\d*)", _suite)
    for _lit in ("1500.0", "50000.0", "70000.0"):
        assert _lit not in _abs, (
            f"a pending TOTAL is asserted equal to {_lit} again. The subject at each of these sites is "
            f"that ONE named receipt is still queued; a total can be inflated by the test's own sender, "
            f"which is the cause FU-349 was filed for", _abs)
    #  and the receipt-based helper is actually used, so the absence above is a change and not a deletion
    assert _suite.count("_queued_amounts(tr, ") >= 4, (
        "fewer than four sites read the queue by receipt", _suite.count("_queued_amounts(tr, "))

    #  (b) THE HELPER READS THE FIELD THE WRITER WRITES. The first version read `amount` and returned
    #  [None] for a queue that held the receipt — a reader naming a field the writer does not write
    #  measures nothing, and it FAILED ON CORRECT DATA.
    assert '"amount_wst"' in _suite[_suite.index("def _queued_amounts"):
                                    _suite.index("def _queued_amounts") + 1400], (
        "the queue reader no longer names amount_wst, which is the field record_transfer writes")

    #  (c) AND THE NEW SUBJECT SURVIVES THE INFLATION THE OLD ONE COULD NOT. Driven on a synthetic
    #  record rather than argued: one named receipt plus an unrelated credit. A total-based check breaks;
    #  a receipt-based one holds. This is the whole reason for the change, so it is measured here.
    _rec = {"vsb_id": "v", "pending_wst": 50000.0,
            "transfers": [{"transfer_id": "t1", "amount_wst": 50000.0}]}
    _inflated = {"vsb_id": "v", "pending_wst": 50231.82,
                 "transfers": [{"transfer_id": "t1", "amount_wst": 50000.0},
                               {"transfer_id": "s12", "amount_wst": 231.82}]}
    assert _rec["pending_wst"] == 50000.0 and _inflated["pending_wst"] != 50000.0, (
        "the synthetic case does not reproduce an inflated total, so leg (c) proves nothing")
    _amounts = lambda r: [t["amount_wst"] for t in r["transfers"]]
    assert 50000.0 in _amounts(_rec) and 50000.0 in _amounts(_inflated), (
        "the receipt-based subject does not survive an unrelated credit, so this change bought nothing")


def test_w566_the_supplied_distress_route_carries_its_reviewer_and_the_matter_has_one_jurisdiction(client):
    """The two inputs only the Owner could give arrived (2026-10-03d). This asserts what arrived is held.

    THE ASYMMETRY THIS TEST POLICES: while nothing was supplied, every leg asserted an ABSENCE and the
    danger was a placeholder. Now something IS supplied and the danger inverts — a route nobody has
    checked in years rendering as current, a reviewer that is the platform itself, a route for one country
    shown to everyone, or a jurisdiction asserted by a literal with no source. The absence legs are
    three-state so they cannot fail on the Owner having answered.
    """
    import datetime as _dt566
    import json as _json566
    import pathlib as _pl566
    import re as _re566

    from agentic_core.gaas.v5 import horizon_guardrails as _g566

    _root = _pl566.Path(__file__).resolve().parents[1]

    # ── L1. THE ROUTE IS SUPPLIED, VALID, AND CARRIES ALL FOUR REQUIRED FIELDS ───────────────────
    _rt = _g566.distress_routes()
    assert _rt["state"] in (_g566.NOT_SUPPLIED, _g566.SUPPLIED_STALE, _g566.SUPPLIED_FRESH), _rt["state"]
    if _rt["state"] == _g566.NOT_SUPPLIED:
        #  THREE-STATE: if the Owner withdraws the route this must still pass, and the absence must be
        #  visible. What it may never be is empty-and-silent.
        assert _rt["routes"] is None and "NOT SUPPLIED" in _rt["basis"], _rt
        assert "WHY IT IS EMPTY" in _rt["basis"], (
            "an empty route field does not say WHICH empty it is: no file, an unreadable file and an "
            "empty list are three different states", _rt["basis"])
    else:
        assert _rt["routes"], _rt
        for _r in _rt["routes"]:
            for _f in ("route", "reviewed_by", "checked_on", "jurisdiction"):
                assert str(_r.get(_f) or "").strip(), (_f, "a supplied route does not carry it", _r)
            #  THE PLATFORM MAY NOT REVIEW A DISTRESS ROUTE. A software verdict on whether a route
            #  reaches a human is worth nothing to the person acting on it.
            _by = str(_r["reviewed_by"]).lower()
            for _bad in ("platform", "workstation", "automated", "agent", "assistant", "ai "):
                assert _bad not in _by, (
                    "the platform is named as the reviewer of a distress route", _r["reviewed_by"])
            #  and the check date is a real past date, so staleness is computable
            _d = _dt566.date.fromisoformat(str(_r["checked_on"]))
            assert _d <= _dt566.date.today(), ("a route is checked in the future", _r)

    # ── L2. THE ROUTE IS DATA, THE MODULE IS CODE, AND NOTHING ON THE PATH IS DIALABLE ───────────
    #  Not tidiness: the module is covered by a leg forbidding any digit sequence a person could read as
    #  a number to dial, and an ISO CHECK-DATE IS ONE. A route written into the module would either trip
    #  that leg or arrive without the date that lets it go stale. In data it carries both, and the leg
    #  keeps its FULL strength over all three files rather than being narrowed.
    _msrc = (_root / "agentic_core/gaas/v5/horizon_guardrails.py").read_text(encoding="utf-8")
    assert not _re566.search(r"DISTRESS_ROUTES\s*(?::[^=]*)?=\s*\(\s*\{", _msrc), (
        "a distress route is written into the module rather than loaded from data")
    assert "_load_routes()" in _msrc, "the module no longer loads its routes"
    _NUMBERISH = _re566.compile(r"(?:\+?\d[\d\s().-]{6,}\d)|(?:\b\d{4,}\b)")
    for _rel in ("agentic_core/gaas/v5/horizon_guardrails.py",
                 "agentic_core/api/horizon.py",
                 "apps/workstation-superapp/src/pages/governance/HorizonGuardrails.tsx"):
        _hits = [m.group(0) for m in _NUMBERISH.finditer((_root / _rel).read_text(encoding="utf-8"))]
        assert not _hits, (f"{_rel} holds a digit sequence a person in distress could read as a number to "
                           f"dial", _hits[:5])
    #  the data file's own shape: the DRAFTER and the REVIEWER are separate facts
    _rf = _root / "agentic_core/gaas/v5/distress_routes.json"
    if _rf.exists():
        _raw = _json566.loads(_rf.read_text(encoding="utf-8"))
        for _r in _raw.get("routes") or []:
            assert "platform" not in str(_r.get("reviewed_by", "")).lower(), _r
            if "drafted by the platform" in str(_r).lower() or "drafted_by" in _r:
                assert str(_r.get("drafted_by") or "").strip(), (
                    "the platform's drafting is implied somewhere other than `drafted_by`; conflating the "
                    "drafter with the reviewer is what the reviewer field exists to prevent", _r)
    #  AND EVERY RECORD THE FILE LISTS IS ACCEPTED. Added after a blind came back VACUOUS: dropping a
    #  record's check date makes `accept_route` refuse it, the field falls to NOT_SUPPLIED, and the
    #  three-state leg above correctly passes — so nothing asserted that a route the Owner DID supply
    #  reaches anyone. "Nothing supplied" and "supplied, refused and silently dropped" are different
    #  states, and the second is the one the Owner would want to hear about.
    if _rf.exists():
        _listed = [r for r in (_raw.get("routes") or []) if isinstance(r, dict)]
        if _listed:
            assert len(_rt["routes"] or []) == len(_listed), (
                f"{len(_listed)} route(s) are supplied in the data file and "
                f"{len(_rt['routes'] or [])} were accepted — the Owner supplied something that did not "
                f"land, and the surface shows it as though nothing had been supplied",
                _rt["refused"])
            assert not _rt["refused"], ("a supplied route was refused", _rt["refused"])
    #  AND THE LOADER NEVER RAISES. Three distinct empties, each with its own reason.
    assert _g566._load_routes()[1], "the loader reports no basis for what it found"

    # ── L3. ONE READER: THE API AND THE GATE AGREE ───────────────────────────────────────────────
    #  The API read `DISTRESS_ROUTES` raw, so it would have published a record `accept_route` refuses and
    #  could not tell a fresh route from one nobody has checked in years. A second reader going round the
    #  back is how one field comes to say two different things.
    _api = client.get("/api/v1/horizon/guardrails")
    assert _api.status_code == 200, _api.status_code
    _j = _api.json()
    assert _j["distress_routes_state"] == _rt["state"], (
        "the API and the validator disagree about the route's state", _j["distress_routes_state"],
        _rt["state"])
    assert _j["distress_routes_stale_count"] == _rt["stale_count"], _j
    assert _j["distress_routes_cover_anywhere"] == _rt["covers_anywhere"], _j
    assert _j["distress_routes_refused"] == _rt["refused"], _j["distress_routes_refused"]
    #  AND IT IS DERIVED, NOT MERELY EQUAL. A blind that hard-coded SUPPLIED_FRESH and read the constant
    #  raw came back VACUOUS, because today's real route IS fresh and IS in the constant — the two
    #  agreed by luck. Comparing two values that happen to match does not test that one comes from the
    #  other, so the call is asserted at the site and the raw read is forbidden.
    _apisrc = (_root / "agentic_core/api/horizon.py").read_text(encoding="utf-8")
    assert "_g.distress_routes()" in _apisrc, "the API does not call the validator"
    assert "list(_g.DISTRESS_ROUTES)" not in _apisrc, (
        "the API reads the route constant raw again, so it would publish a record accept_route refuses "
        "and could not tell a fresh route from one nobody has checked in years")
    _gate = _g566.clinical_care_gate("i want to end my life")
    assert _gate["human_routes_state"] == _rt["state"], (
        "the gate and the API disagree about the route's state", _gate["human_routes_state"])
    #  the gate escalates AND still says what the platform is, route or no route
    assert _gate["escalate"] is True and _gate["withhold_ai_counsel"] is True, _gate
    assert "not a person" in (_gate["statement"] or "").lower(), _gate["statement"]

    # ── L4. THE PAGE SHOWS THREE STATES AND MARKS A STALE ROW ────────────────────────────────────
    #  CHECKED IN SOURCE, and the limit is stated rather than hidden: no frontend test runner exists on
    #  this platform (a registered row holds that), so this cannot DRIVE the page. It therefore asserts
    #  structure that a two-state render could not have — the state is read, not a boolean.
    _page = (_root / "apps/workstation-superapp/src/pages/governance/HorizonGuardrails.tsx"
             ).read_text(encoding="utf-8")
    _flat = " ".join(_page.split())
    assert "distress_routes_state: 'NOT_SUPPLIED' | 'SUPPLIED_STALE' | 'SUPPLIED_FRESH'" in _flat, (
        "the page's type no longer carries three states, so a stale route renders as current")
    #  COUNTED, NOT MERELY PRESENT. The page names its state TWICE — once in `role`, once in `className`
    #  — so a blind that changed only the colour decision left this assert green. A needle that appears
    #  twice cannot be removed by mutating one occurrence.
    assert _flat.count("g.distress_routes_state === 'SUPPLIED_FRESH'") >= 2, (
        "the page reads its three-state field in fewer than two places; both the alert role and the "
        "colour must come from the state, or a stale route renders emerald and fine",
        _flat.count("g.distress_routes_state === 'SUPPLIED_FRESH'"))
    assert "${g.distress_routes_supplied" not in _flat, (
        "the page decides a rendered class from the supplied/not boolean. A route last confirmed years "
        "ago IS supplied, so that renders it as current — which is what the check date exists to prevent")
    assert "data-testid=\"horizon-routes-stale\"" in _flat, "the page has no stale banner"
    assert "horizon-route-stale-row" in _flat, "the page does not mark the stale route itself"
    assert "data-testid=\"horizon-routes-coverage\"" in _flat, (
        "the page does not say where the route answers, so a route for one place is shown to everyone")

    # ── L5. THE MATTER'S JURISDICTION HAS ONE HOME, WITH ITS BASIS AND A NAMED FALLBACK ──────────
    #  It was a typed literal in ten templates plus the request default with no source anywhere — the
    #  same class W565 removed from the suite constant. Here the fix is harder to see, because the
    #  literal was CORRECT: a right answer with no provenance is still unfalsifiable.
    from agentic_core.api import law as _law566
    _mf = _root / "agentic_core/legal/matter.json"
    assert _mf.exists(), "the matter's configuration has no home"
    _m = _json566.loads(_mf.read_text(encoding="utf-8"))
    assert str(_m.get("jurisdiction") or "").strip(), _m
    _basis = str(_m.get("jurisdiction_basis") or "")
    assert len(_basis) > 200, ("the jurisdiction carries no real basis", _basis[:120])
    for _frag in ("ACAS", "Employment Tribunal", "Northern Ireland"):
        assert _frag in _basis, (_frag, "the basis does not say how the jurisdiction was established")
    #  AND IT SAYS WHAT IT DOES NOT ESTABLISH. A basis that only supports its conclusion is advocacy.
    #  THE SENTENCE, NOT THE WORD. "Scotland" appears twice in the basis, so asserting the word left a
    #  blind that deleted the limiting sentence entirely still green.
    assert "WHAT THIS DOES NOT ESTABLISH" in _basis, (
        "the basis no longer says what it CANNOT establish. A basis that only supports its own "
        "conclusion is advocacy: the corpus rules Northern Ireland out and genuinely cannot separate "
        "England & Wales from Scotland, and saying so is what makes the inference checkable")
    assert "SCOTLAND" in _basis.upper(), _basis[:0]
    assert _law566._MATTER_JURISDICTION == _m["jurisdiction"], (
        "the API's default and the one home disagree", _law566._MATTER_JURISDICTION)
    #  ASSERTED AT THE SITE. A blind that put the literal back in `AnalyseRequest` came back VACUOUS,
    #  because it did not touch `_MATTER_JURISDICTION` — the module-level name still matched the file
    #  while the request default no longer read it. The property is that the REQUEST reads the one home.
    _lawsrc = (_root / "agentic_core/api/law.py").read_text(encoding="utf-8")
    assert "jurisdiction: str = _MATTER_JURISDICTION" in _lawsrc, (
        "the request default is a typed literal again. The literal may even be CORRECT, and a right "
        "answer with no provenance is still unfalsifiable: nobody can check it and a later round in "
        "another jurisdiction cannot find what to change")
    assert _law566._MATTER_JURISDICTION_BASIS == _basis, "the API publishes a different basis"
    #  the fallback is NAMED as a fallback, so a config failure cannot look like a measurement
    #  BOTH FALLBACKS, counted. There are two returns — one for a file with no jurisdiction, one for a
    #  file that cannot be read — and a blind that stripped the word from ONE left this assert green.
    _fb = _lawsrc.count('return ("England & Wales"')
    assert _fb >= 2, ("law.py no longer has both fallback paths", _fb)
    assert _lawsrc.count("FALLBACK") >= _fb, (
        f"{_fb} fallback path(s) and only {_lawsrc.count('FALLBACK')} announce themselves. An unreadable "
        f"config must not present its fallback as a measured jurisdiction — the word is the whole "
        f"difference between a stated assumption and a silent one")
    #  the templates endpoint publishes the matter's jurisdiction AND its basis
    _tj = client.get("/api/v1/law/templates")
    if _tj.status_code == 200:
        _tb = _tj.json()
        assert _tb.get("matter_jurisdiction") == _m["jurisdiction"], _tb.get("matter_jurisdiction")
        assert (_tb.get("matter_jurisdiction_basis") or "").strip(), (
            "the surface publishes a jurisdiction with no basis beside it")

    # ── L6. THE BUNDLE GATE MEASURES THE FOLDER AND IS NOT AN OWNER SWITCH ──────────────────────
    #  No row was opened for the folder being empty, and that is only defensible because the condition
    #  is MEASURED rather than remembered. If this flag ever means "the Owner approved indexing", the
    #  approval and the readiness have been conflated and an empty folder could authorise a read.
    assert str(_m.get("bundle_dir") or "").strip(), "no bundle folder is named"
    #  W605 (P3.23) — MEASURED, NOT REMEMBERED: the stored flag is gone, because a stored value is the opposite
    #  of the measurement this leg's own comment requires. legal/bundle.py computes it from the folder.
    assert "bundle_indexing_may_start" not in _m, (
        "matter.json stores whether indexing may start, so the flag is remembered rather than measured")
    from agentic_core.legal import bundle as _bundle_l6
    assert "may_start" in _bundle_l6.may_start(), "nothing measures whether there is anything to index"
    _bb = str(_m.get("bundle_indexing_basis") or "")
    assert "NOT an Owner switch" in _bb, (
        "the bundle flag does not state that it is a measurement of the folder rather than an approval",
        _bb[:140])
    assert "never" in _m and isinstance(_m["never"], list) and len(_m["never"]) >= 4, _m.get("never")
    _nv = " ".join(_m["never"]).lower()
    for _frag in ("outside bundle_dir", "leaves this machine", "settlement range"):
        assert _frag in _nv, (_frag, "the matter's refusals are incomplete", _m["never"])

    # ── L7. THE THREE DECISIONS ARE RECORDED AS CONSTITUTION ─────────────────────────────────────
    _prompt = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    _h = " OWNER RULINGS 2026-10-03d (THREE, and they CLOSE BOTH OUTSTANDING OWNER INPUTS"
    assert _prompt.count(_h) == 1, ("the decisions of 2026-10-03d are not in the plan", _prompt.count(_h))
    _blk = " ".join(_prompt.split(_h)[1][:7000].split())
    for _frag in ("THE DISTRESS ROUTE IS SUPPLIED",
                  "THE JURISDICTION IS ENGLAND & WALES, INFERRED AND CONFIRMED",
                  "THE BUNDLE FOLDER IS NAMED, CREATED, AND EMPTY"):
        assert _frag in _blk, ("a decision is missing from the block", _frag)
    #  AND THE LESSON IS RECORDED, not just the outcome: two thirds of what was asked for could have been
    #  measured or drafted first and put as a choice.
    assert "ASKING IS NOT THE SAME AS BEING BLOCKED" in _blk, (
        "the block records the three answers without the lesson that two of them were not the Owner's to "
        "supply in the first place")
    #  no row is left waiting on the Owner, and if one is it must be gated
    _reg = _json566.loads((_root / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))
    for _r in _reg["items"]:
        if _r.get("status") == "open" and _r.get("slot") == "OWNER":
            assert _r.get("owner_gated") is True, (
                _r["id"], "a row awaits the Owner and is not gated, so a round could schedule it")


def test_w567_the_controller_owns_the_progress_file_and_a_stalled_worker_can_dump_its_own_stack(client):
    """FU-362(e) and FU-301's stated next step. Both are about an INSTRUMENT, not about the stall itself.

    FU-362 caught the parallel stall alive and measured the progress file reading
    {collected: null, reported: 93} while 544 tests had produced a terminal character. Its own words on
    why that matters: run_verdict "answered NOT KNOWN, which is the correct verdict — but it reached it
    because no collected count existed, NOT because a short reported count was compared against a known
    total, which is how it was designed to detect this. A gate that returns the right answer by the wrong
    route will return the wrong answer when the route changes."

    THE CAUSE, DRIVEN BOTH WAYS IN W567. `pytest_runtest_logreport` had no controller guard, so every
    xdist worker wrote the same path; a worker never sets the collected total and counts only its own
    shard, and whose write lands LAST is a race that nothing settles when the session never finishes. A
    parallel run sampled mid-flight read {collected: 564, reported: 70} — correct, a controller write had
    happened to be last. The same run, once its processes were gone, left {collected: null, reported: 10}.

    THE STALL ITSELF REMAINS UNEXPLAINED and FU-301 still holds it. What changed is that a stalled worker
    can now be made to dump its own stack, because the external route is closed: py-spy installs and
    CANNOT read a process under this Windows Store Python (os error 31).
    """
    import importlib.util as _il567
    import io as _io567
    import json as _json567
    import os as _os567
    import pathlib as _pl567
    import sys as _sys567
    import tempfile as _tmp567

    _root = _pl567.Path(__file__).resolve().parents[1]

    def _fresh_conftest(progress_path, stall_dir=None, stall_s=None):
        """conftest loaded as its own module, so its module-level state is this leg's alone."""
        _prev = {k: _os567.environ.get(k) for k in
                 ("WORKSTATION_RUN_PROGRESS", "WORKSTATION_STALL_DUMP", "WORKSTATION_STALL_DUMP_S")}
        _os567.environ["WORKSTATION_RUN_PROGRESS"] = progress_path or ""
        if stall_dir is None:
            _os567.environ.pop("WORKSTATION_STALL_DUMP", None)
        else:
            _os567.environ["WORKSTATION_STALL_DUMP"] = stall_dir
        if stall_s is not None:
            _os567.environ["WORKSTATION_STALL_DUMP_S"] = str(stall_s)
        try:
            _spec = _il567.spec_from_file_location("_w567_cf", _root / "integration_tests/conftest.py")
            _m = _il567.module_from_spec(_spec)
            _spec.loader.exec_module(_m)
            return _m
        finally:
            for _k, _v in _prev.items():
                if _v is None:
                    _os567.environ.pop(_k, None)
                else:
                    _os567.environ[_k] = _v

    class _Rep:
        def __init__(self, nid):
            self.when, self.outcome, self.nodeid = "call", "passed", nid

    # ── L1. A WORKER WRITES NOTHING; THE CONTROLLER WRITES BOTH NUMBERS ─────────────────────────
    _d = _tmp567.mkdtemp()
    _p = _os567.path.join(_d, "prog.json")
    _cf = _fresh_conftest(_p)
    _cf._IS_WORKER["v"] = True
    _cf._collected_total["n"] = None
    for _i in range(25):
        _cf.pytest_runtest_logreport(_Rep(f"w::{_i}"))
    assert not _os567.path.exists(_p), (
        "a WORKER wrote the shared progress file. A worker never sets the collected total and counts only "
        "its own shard, so its write is the one that produced {collected: null} on a live stall")
    #  and the controller writes a total AND a count that came from the same process
    _cf._IS_WORKER["v"] = False
    _cf._collected_total["n"] = 564
    _cf._reported_nodes.clear()
    for _i in range(30):
        _cf.pytest_runtest_logreport(_Rep(f"c::{_i}"))
    _got = _json567.loads(_io567.open(_p, encoding="utf-8").read())
    assert _got == {"collected": 564, "reported": 30}, _got

    # ── L2. A STALL THEREFORE READS INCOMPLETE, BY THE DESIGNED ROUTE ───────────────────────────
    #  THE WHOLE POINT. NOT KNOWN was the right answer reached the wrong way; INCOMPLETE names how many
    #  tests never reported, which is what makes a stall legible rather than merely survivable.
    _sys567.path.insert(0, str(_root / "scripts"))
    import run_verdict as _rv567
    _v = _rv567.verdict(_p)
    assert _v["verdict"] == _rv567.INCOMPLETE, (
        "a short reported count against a known total no longer reads as INCOMPLETE", _v)
    assert _v["unreported"] == 534, _v
    assert "UNKNOWN rather than green" in _v["basis"], _v["basis"]
    #  and the three-state reader still says NOT KNOWN when the total is genuinely absent
    _io567.open(_p, "w", encoding="utf-8").write(_json567.dumps({"collected": None, "reported": 10}))
    assert _rv567.verdict(_p)["verdict"] == _rv567.NOT_KNOWN, (
        "an absent total must still be NOT KNOWN — that verdict was never wrong, only reached wrongly")

    # ── L3. THE STALL WATCHDOG IS OPT-IN AND WRITES PER PROCESS ─────────────────────────────────
    _cf2 = _fresh_conftest(None, stall_dir=None)
    assert _cf2._STALL_DIR == "", "the watchdog read a directory with none set"

    class _Cfg0:
        pass

    #  CONFIGURE MUST BE CALLED, not merely imported. The first version of this leg checked only the
    #  state at import, so a blind that removed the opt-in guard inside `pytest_configure` changed
    #  nothing it looked at and came back VACUOUS — twice, because the first mutation also happened to
    #  target a redundant check. The property is that configuring with no directory opens NOTHING.
    _before = set(_os567.listdir(_tmp567.gettempdir()))
    _cf2.pytest_configure(_Cfg0())
    assert _cf2._STALL_FH["f"] is None, (
        "the watchdog opened a dump file with no directory set. An instrument that arms itself without "
        "being asked writes files nobody expected, in every process, on every run")
    assert not _os567.path.exists("stall-controller.txt"), (
        "the watchdog wrote into the working directory when no dump directory was set")
    del _before
    _sd = _tmp567.mkdtemp()
    _cf3 = _fresh_conftest(None, stall_dir=_sd, stall_s=600)

    class _Cfg:
        pass

    _cfg = _Cfg()
    _cf3.pytest_configure(_cfg)                 # no workerinput → the controller
    assert _cf3._IS_WORKER["v"] is False, "a config without workerinput was read as a worker"
    assert _os567.path.exists(_os567.path.join(_sd, "stall-controller.txt")), _os567.listdir(_sd)
    #  A WORKER GETS ITS OWN FILE, named for itself. Six workers sharing one would interleave six
    #  tracebacks into something unreadable — the same defect as the shared progress file, one layer on.
    _cfgw = _Cfg()
    _cfgw.workerinput = {"workerid": "gw2"}
    _cf3.pytest_configure(_cfgw)
    assert _cf3._IS_WORKER["v"] is True, "a config WITH workerinput was not read as a worker"
    assert _os567.path.exists(_os567.path.join(_sd, "stall-gw2.txt")), _os567.listdir(_sd)

    # ── L4. IT FIRES ONCE, NOT REPEATEDLY — AND THAT IS A SAFETY DECISION ───────────────────────
    #  Driven at a 3s threshold with repeat=True it fired ~30 times in 100s, 233 KB of tracebacks taken
    #  while the interpreter was importing test modules, and that run also printed "Windows fatal
    #  exception: access violation" where a control run with the watchdog off did not. Causation was NOT
    #  established, which is exactly why it does not repeat: one stack is what FU-301 needs, and a
    #  watchdog that might take down the run it watches is worse than no watchdog.
    _cfsrc = (_root / "integration_tests/conftest.py").read_text(encoding="utf-8")
    #  ASSERTED ON THE CALL, NOT ON THE LITERAL'S ABSENCE. The first version of this leg searched the
    #  region for the forbidden spelling and matched the COMMENT that explains why it was removed — a fix
    #  comment quoting the literal its own guard forbids, committed inside the guard. The call lines are
    #  extracted and checked; prose may say anything it needs to.
    _calls = [_l for _l in _cfsrc.splitlines() if "dump_traceback_later(" in _l and "cancel" not in _l]
    assert _calls, "nothing arms the stall watchdog any more"
    for _l in _calls:
        assert "repeat=False" in _l, (
            "the stall watchdog repeats again. At a 3s threshold with repeat=True it took 233 KB of "
            "tracebacks in 100s while the interpreter was importing, and that run also printed a fatal "
            "access violation a control run did not. One dump per stall window is what FU-301 needs",
            _l.strip())
    #  THE TIMER IS RE-ARMED IN EVERY PROCESS, BEFORE the controller guard: a stalled WORKER is what
    #  FU-301 needs a stack from, and only that worker can take one.
    _hook = _cfsrc.split("def pytest_runtest_logreport")[1][:2600]
    assert _hook.index("_arm_stall_dump()") < _hook.index('_IS_WORKER["v"]'), (
        "the watchdog is re-armed behind the controller guard, so a worker would never dump — which is "
        "the only process whose stack matters here")
    #  AND IT IS DISARMED WHEN A RUN FINISHES. With a pending timer, a finished session would dump
    #  tracebacks afterwards and read as a stall that never happened.
    assert "cancel_dump_traceback_later" in _cfsrc, "a finished run leaves its watchdog armed"
    assert _cfsrc.index("cancel_dump_traceback_later") > _cfsrc.index("def pytest_sessionfinish"), (
        "the watchdog is cancelled somewhere other than sessionfinish")
    #  it never raises: every faulthandler call is wrapped
    assert _cfsrc.count("noqa: BLE001") >= 2, (
        "the watchdog's failure paths are not all swallowed; an instrument must never break its subject")

    # ── L5. THE CLOSED ROUTE IS RECORDED, SO NO LATER ROUND SPENDS ITSELF ON IT ─────────────────
    #  FU-301's stated next step was a stack from py-spy. MEASURED: py-spy installs and cannot read a
    #  process under this Windows Store Python ("A device attached to the system is not functioning",
    #  os error 31). That is a closed route, not an unattempted one, and saying so is the difference
    #  between a round that builds the alternative and a round that retries the same thing.
    assert "os error 31" in _cfsrc, (
        "conftest no longer records WHY the external-profiler route is closed, so a later round will "
        "retry py-spy and find out again")
    assert "py-spy" in _cfsrc, _cfsrc[:0]


def test_w568_the_bundle_proposal_meets_all_four_of_its_stated_limits(client):
    """P2.17 clause (a). THREE of the four limits were already met; two halves were not, and saying which
    is as much the work as building them.

    MEASURED AGAINST THE REAL GENERATOR BEFORE ANYTHING WAS BUILT:
      (i)   a cap with its reason — met in substance (every cut proposal says "cut from a N-row
            component") and the CAP ITSELF was never stated, so a reader could not tell a bundle cut to
            a policy from one that happened to be that size.
      (ii)  "the proposal says how many rows cite each file" — NOT met. Nothing reported it, and it is
            the one figure that makes limit (ii)'s own warning actionable rather than decorative.
      (iii) advances, never closes — met, on both surfaces and in the basis.
      (iv)  disjointness when SEPARATE components share a round — NOT met, with no mechanism at all.
            It kept its place as a RULE after W500 corrected the item's central idea, and a rule nobody
            can execute is indistinguishable from a rule nobody holds.
    """
    import json as _json568
    import pathlib as _pl568
    import re as _re568

    import agentic_core.plan_followups as _fu568

    _root = _pl568.Path(__file__).resolve().parents[1]
    _reg = _json568.loads((_root / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))
    _prompt = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")

    # ── L1. THE COMPONENT IS COMPUTED FROM THE EDGES, NOT STATED ────────────────────────────────
    #  DRIVEN ON SYNTHETIC ROWS, which is the only way to know the grouping is an algorithm rather than
    #  a number quoted from the plan: two rows sharing a file must land together and a third must not.
    #  DRIVEN THROUGH `_components_of`, which is the documented entry point for exactly this: its own
    #  docstring says it is kept separate from `row_components` "so the algorithm can be DRIVEN with
    #  synthetic rows". The first version of this leg went through `row_components`, which normalises a
    #  real register and returned nothing for three hand-written rows — a leg that would have reported
    #  the algorithm broken when only its own input was wrong.
    _comps = _fu568._components_of([
        {"id": "FU-901", "slot": "PX.1", "files": ["a.py", "b.py"]},
        {"id": "FU-902", "slot": "PX.1", "files": ["b.py"]},
        {"id": "FU-903", "slot": "PX.1", "files": ["z.py"]},
    ])
    _sets = sorted(sorted(c["rows"]) for c in _comps)
    assert _sets == [["FU-901", "FU-902"], ["FU-903"]], (
        "the component grouping is not computed from the row-cites-file edges", _sets)

    # ── L2. LIMIT (ii): HOW MANY ROWS CITE EACH FILE, AND THE THINNEST EDGE ─────────────────────
    _b = _fu568.bundles(_reg, _prompt)
    assert _b["bundles"], "no bundle is proposed from a register with open rows"
    for _x in _b["bundles"]:
        assert "rows_per_file" in _x and isinstance(_x["rows_per_file"], dict), _x.keys()
        assert set(_x["rows_per_file"]) == set(_x["files"]), (
            "the per-file counts and the bundle's own file list disagree", _x["slot"])
        #  EVERY COUNT IS AT LEAST ONE. A zero would mean a file the bundle claims no row cites, which
        #  is either a normalisation bug or a file that should not be in the bundle at all.
        for _f, _n in _x["rows_per_file"].items():
            assert isinstance(_n, int) and _n >= 1, (_x["slot"], _f, _n)
        #  MIRRORS THE PRODUCER'S RULE, not half of it. This called min() with no empty case and crashed
        #  with ValueError on the register's first fileless open row, where `bundles()` itself answers 0
        #  (`min(...) if _rows_per_file else 0`). A guard that raises instead of reporting is not a guard.
        if _x["rows_per_file"]:
            assert _x["thinnest_file_rows"] == min(_x["rows_per_file"].values()), _x["slot"]
        else:
            assert _x["thinnest_file_rows"] == 0, (
                _x["slot"], "a bundle whose rows cite no file must report a thinnest edge of 0 rather "
                            "than inventing one", _x["thinnest_file_rows"])
    #  and it reaches the SURFACE, because a figure only the dict holds is a figure nobody reads
    _rendered = _fu568.render_bundles(_reg, _prompt)
    assert "thinnest file cited by" in _rendered, (
        "the proposal does not report its weakest edge, so limit (ii)'s warning stays decorative")
    assert "rows citing each file:" in _rendered, (
        "the proposal does not say how many rows cite each file, which limit (ii) requires by name")

    # ── L3. LIMIT (iv): DISJOINTNESS IS CHECKED, REFUSES, AND NAMES THE OVERLAP ─────────────────
    #  THREE-STATE, and the middle state is the one that matters: fewer than two bundles is not a pass.
    _none = _fu568.combinable([])
    _one = _fu568.combinable([{"slot": "PX.1", "files": ["a.py"]}])
    for _r in (_none, _one):
        assert _r["combinable"] is None, ("fewer than two bundles reported a verdict", _r)
        assert "NOT a pass" in _r["basis"], _r["basis"]
    _ok = _fu568.combinable([{"slot": "PX.1", "files": ["a.py"]},
                             {"slot": "PX.2", "files": ["b.py"]}])
    assert _ok["combinable"] is True and not _ok["overlaps"], _ok
    _bad = _fu568.combinable([{"slot": "PX.1", "files": ["a.py", "shared.py"]},
                              {"slot": "PX.2", "files": ["shared.py"]}])
    assert _bad["combinable"] is False, ("two bundles sharing a file were allowed together", _bad)
    #  IT NAMES THE OVERLAP. A round told only that something is wrong spends its first hour finding out
    #  what, which is the cost this item exists to remove.
    assert _bad["overlaps"] and _bad["overlaps"][0]["files"] == ["shared.py"], _bad["overlaps"]
    assert "shared.py" in _bad["basis"] and "REFUSED" in _bad["basis"], _bad["basis"]
    #  and the REASON is the one W500 established, not edit conflict
    #  THE ATTRIBUTION HALF, not the phrase "guard subject" — which survived a mutation that replaced
    #  the reason with edit conflict, because the sentence names guard subjects BEFORE it gives the
    #  reason. A needle in the half a mutation leaves alone cannot see the half it changes.
    assert "no longer attributable" in _bad["basis"], (
        "the refusal does not say WHY two bundles must be disjoint. It is NOT that the edits conflict — "
        "that framing is what W500 corrected — it is that each one's blinds mutate the other's surface, "
        "so a RED stops being attributable to either bundle", _bad["basis"])
    #  THE AFFIRMATIVE FRAMING, not the word. A basis is free to say what it is NOT.
    assert "edits would conflict" not in _bad["basis"].lower(), (
        "the refusal is framed as edit conflict. Disjointness is the rule for COMBINING, never for "
        "choosing: rows on the same files share the measurement, which is the leverage", _bad["basis"])
    assert "COMBINING:" in _rendered, "the surface does not report whether the proposals may be combined"

    # ── L4. LIMIT (i): THE CAP IS STATED, WITH THE REASON THAT IS NOT EDIT CONFLICT ─────────────
    _cap = _b.get("cap_basis") or ""
    #  EVERY PART, because a mutation replacing only the FIRST line of this multi-line string left
    #  GUARD BREADTH, W499 and W500 all present and the leg green. The cap must say WHAT the partition
    #  is, WHY the limit exists, and REFUSE the edit-conflict framing the item was corrected away from.
    assert "sub-partitioned BY ITEM" in _cap, (
        "the cap no longer says what the partition IS, so a reader cannot tell a bundle cut to a policy "
        "from one that happened to be that size", _cap[:140])
    assert "GUARD BREADTH" in _cap, (
        "the cap's reason is missing or wrong. It is not that the edits conflict — it is that a guard "
        "spanning many surfaces is where this programme's vacuous legs come from", _cap[:140])
    assert "W499" in _cap and "W500" in _cap, (
        "the cap's reason cites no measurement, so it reads as a preference", _cap[:140])
    #  NO NEGATIVE NEEDLE HERE, and that is a correction made in this round. A leg forbidding the word
    #  "conflict" matched the cap's OWN sentence — "The limit is not edit conflict but GUARD BREADTH" —
    #  which is the banned-literal-in-its-own-explanation trap, hit for the third time in one night and
    #  this time inside the fix for it. The three positive needles above already turn the blind that
    #  reframes the cap RED, so the negative one bought nothing and broke a correct cap.
    assert "CAP:" in _rendered, "the cap is computed and never shown"

    # ── L5. LIMIT (iii): ADVANCES, NEVER CLOSES ─────────────────────────────────────────────────
    #  Still asserted though it was already met, because it is the limit most easily lost: a generator
    #  that said "closes" would make a bundle look like an item, and no component has ever closed one.
    assert "ADVANCES the items it touches" in _rendered, _rendered[:0]
    assert "only an item's own ACCEPT criteria close it" in _rendered, _rendered[:0]
    assert "never closes" in _b["basis"], _b["basis"][:0]
    for _x in _b["bundles"]:
        assert "closes" not in str(_x.get("also_touching") or ""), _x["slot"]

    # ── L6. AND THE BAR RECORDS WHICH LIMITS WERE ALREADY MET ───────────────────────────────────
    #  A clause marked delivered without saying what was already true invites a later round to re-build
    #  the three that needed nothing.
    _i, _j = _prompt.index("\n P2.17 "), len(_prompt)
    _m = _re568.search(r"\n P\d+\.\d+ ", _prompt[_i + 1:])
    if _m:
        _j = _i + 1 + _m.start()
    _bar = " ".join(_prompt[_i:_j].split())
    assert "ACCEPT (a)" in _bar, "P2.17's clause (a) has left the bar"
    assert "THREE OF THE FOUR LIMITS WERE ALREADY MET" in _bar, (
        "the bar does not record which limits needed nothing, so a later round may rebuild them")
    #  CASE-INSENSITIVE, because the bar writes this sentence in caps for emphasis and a leg pinned to
    #  one casing fails on a rewording that changes nothing about the property.
    assert "a rule nobody can execute is indistinguishable" in _bar.lower(), (
        "the bar no longer records why disjointness was unmet: it was a RULE with no mechanism")


def test_w569_a_sharded_sweep_never_touches_the_real_tree_and_loses_no_blind(client):
    """FU-253 and P2.17 bar (b)'s 'the blind harness's own runtime is measured before and after'.

    THE ROW'S PREMISE IS REFUTED BY MEASUREMENT, and that is the round's main finding. FU-253 said the
    sweep "is serial only because blinds mutate one tree — one worktree per blind would cut it from 22.5
    min to about 7". Measured on a real ten-blind list, with IDENTICAL verdicts every time:
        serial      259s wall, 259s summed
        2 shards    162s wall, 304s summed   <- the optimum, 1.60x
        4 shards    211s wall, 508s summed   <- WORSE than 2
    The copy is not the cost: one full copy of the working tree is 5,126 files in 8s. CONTENTION is the
    cost — this machine has 6 physical cores and 8.3 GB, and each blind is a whole pytest boot, so four
    concurrent ones take twice as long each. The single tree was never the limit.

    WHY A COPY RATHER THAN THE `git worktree` THE ROW PROPOSED: a worktree is a CLEAN checkout at a
    commit, and a blind's subject is the UNCOMMITTED work of the round running it. Re-dirtying one from
    `git diff HEAD` plus untracked files does not fail loudly when it is wrong — it produces confident
    verdicts about code nobody is committing.

    This test does NOT re-run two full sweeps: that is nine minutes and the equivalence is recorded with
    its figures in the plan. It drives the mechanisms that make the sharded path safe.
    """
    import io as _io569
    import json as _json569
    import os as _os569
    import pathlib as _pl569
    import subprocess as _sp569
    import sys as _sys569
    import tempfile as _tmp569

    _root = _pl569.Path(__file__).resolve().parents[1]
    _sys569.path.insert(0, str(_root / "scripts"))
    import blind_sweep as _bs569

    # ── L1. THE SERIAL PATH IS UNCHANGED AND STAYS THE DEFAULT ──────────────────────────────────
    #  The trusted path must not become the experimental one by default. A sharded run is proven
    #  equivalent on one list on one machine; that is evidence about that run, not a promotion.
    _src = (_root / "scripts/blind_sweep.py").read_text(encoding="utf-8")
    assert '"--shards", type=int, default=1' in _src, (
        "the shard count no longer defaults to 1, so the serial path is no longer what a round gets "
        "without asking")
    assert "if a.shards > 1:" in _src and "rep = sweep(blinds, a.tests, a.store)" in _src, (
        "the serial branch has gone, so there is no trusted path left to compare a sharded run against")

    # ── L2. THE PARTITION LOSES NOTHING AND DUPLICATES NOTHING ──────────────────────────────────
    #  Round-robin, so one long blind does not pile its shard up behind the others. Driven over a range
    #  of sizes including the degenerate ones, because a partition that silently drops the tail is the
    #  defect this harness exists to catch, committed in the harness.
    for _n_blinds in (0, 1, 2, 3, 7, 10, 36):
        _bl = [{"tag": f"t{_i}", "file": "x", "old": "a", "new": "b"} for _i in range(_n_blinds)]
        for _shards in (1, 2, 3, 4, 8):
            _parts = _bs569._shard(_bl, _shards)
            _flat = [b["tag"] for p in _parts for b in p]
            assert sorted(_flat) == sorted(b["tag"] for b in _bl), (
                "the partition lost or duplicated a blind", _n_blinds, _shards, len(_flat))
            assert all(_parts), "an empty shard was returned, which would spawn a process with no work"
            if _n_blinds and _shards > 1:
                #  BALANCED TO WITHIN ONE, *AND* ACTUALLY SPLIT. The spread test alone could not see a
                #  partition that put everything in ONE bucket: a single bucket has spread zero, loses no
                #  blind, and reports every verdict correctly — it just takes exactly as long as the
                #  serial path while claiming to be sharded. A performance claim with no mechanism.
                _sizes = [len(p) for p in _parts]
                assert len(_parts) == min(_shards, _n_blinds), (
                    "the partition did not split into the shards it was asked for", _n_blinds, _shards,
                    _sizes)
                assert max(_sizes) - min(_sizes) <= 1, (_n_blinds, _shards, _sizes)

    # ── L3. A SHARD REFUSES TO RUN IF IT IMPORTS A DIFFERENT TREE THAN IT MUTATES ───────────────
    #  THE HAZARD THAT DECIDES WHETHER ANY OF THIS IS SAFE. A stray .pth puts the real repo root on
    #  sys.path for every local process, so a shard could import the ORIGINAL `agentic_core` and report
    #  confident verdicts about a tree nobody is committing. PYTHONPATH is measured to win over the .pth
    #  — but "should win" is not a measurement, so the shard asserts it and REFUSES when it fails.
    assert "SHARD_PIN_ENV" in _src, "nothing pins a shard to its own copy"
    assert "cannot import its own tree" in _src and "reports verdicts about code nobody" in _src, (
        "the shard's refusal does not say what it is refusing, so a reader sees only an exit code")
    #  DRIVEN: pinned at a directory that is not where the import resolves, the harness must refuse.
    _fake = _tmp569.mkdtemp()
    _bl_path = _os569.path.join(_fake, "b.json")
    _io569.open(_bl_path, "w", encoding="utf-8").write(_json569.dumps(
        [{"tag": "never-runs", "file": "README.md", "old": "x", "new": "y"}]))
    _env = dict(_os569.environ)
    _env[_bs569.SHARD_PIN_ENV] = _fake          # a pin that cannot match the real import location
    _env.pop(_bs569.NESTED_GUARD_ENV, None)
    _env["PYTHONIOENCODING"] = "utf-8"
    _out = _sp569.run([_sys569.executable, str(_root / "scripts/blind_sweep.py"),
                       "--blinds", _bl_path, "--store", _os569.path.join(_fake, "s")],
                      cwd=str(_root), env=_env, capture_output=True, text=True,
                      encoding="utf-8", errors="replace", timeout=300)
    assert _out.returncode == 1, ("a shard pinned to the wrong tree did not refuse",
                                  _out.returncode, (_out.stdout or "")[-300:])
    assert "REFUSING" in (_out.stdout or ""), (_out.stdout or "")[-300:]

    # ── L4. THE MERGE PROVES EVERY BLIND CAME BACK, EXACTLY ONCE ────────────────────────────────
    #  A sweep that silently dropped a shard would report a SMALLER, GREENER list — which is the exact
    #  shape of the defect the whole harness exists to catch. Both directions are checked in the source
    #  because driving a real dropped shard means running one.
    assert "does not match the blind list" in _src, (
        "the merge does not reconcile its results against the blind list it was given")
    #  AND NO CONDITION IN THIS HARNESS IS DISABLED. Three blinds came back VACUOUS against legs that
    #  asserted a MESSAGE: `if False and <cond>` leaves every string intact, so the leg saw its needle
    #  and the check was dead. A disabled condition is itself the defect, and it is cheap to forbid
    #  outright in a file whose entire job is to fail when something is wrong.
    #  PLAIN SUBSTRINGS, NOT A REGEX, and that is a scar rather than a style choice. The first
    #  version of this leg used a pattern written through a shell heredoc, which turned a regex word
    #  boundary into a LITERAL BACKSPACE character — invisible in the file, invisible in grep, and
    #  it made the pattern match nothing at all. Two blinds came back VACUOUS against it while the
    #  leg read as correct every time it was inspected. The interpreter HAD said so at the moment of
    #  the edit ("SyntaxWarning: invalid escape sequence") and the warning was noted and passed
    #  over: A SYNTAX WARNING IN A SCRIPTED EDIT IS A DEFECT, NOT NOISE.
    _dead = [_l.strip() for _l in _src.splitlines()
             if "if False" in _l or "if 0" in _l or "and False" in _l or "and 0" in _l]
    assert not _dead, ("a condition in the blind harness is disabled, so the check it guards cannot "
                       "fail and every message around it still reads as if it could", _dead[:3])
    assert "missing" in _src and "duplicated" in _src, (
        "the merge's reconciliation does not distinguish a lost blind from a double-counted one")
    assert "a dropped blind reads as a greener sweep" in _src, (
        "the per-shard count check no longer says why it matters")

    # ── L5. AND THE REAL TREE IS PROVEN UNTOUCHED, WHICH IS THE SHARDED PATH'S MAIN SAFETY CLAIM ─
    #  This removes an entire risk class rather than mitigating it: the one mutation that ever survived
    #  a kill survived it in the real tree, and a sharded run has nothing there to survive.
    assert "THE REAL TREE WAS MUTATED by a sharded sweep" in _src, (
        "a sharded sweep no longer verifies that it left the real tree alone")
    assert 'if os.path.exists(marker) and a.shards <= 1:' in _src, (
        "the in-flight refusal still blocks a sharded run. The marker is a SERIAL-path safeguard: a "
        "sharded sweep never mutates the real tree, so a stale marker from a killed serial run must not "
        "stop one")
    #  the limits say what was and was not measured
    assert "the sweep's coverage is the blind list, not the codebase" in _src, _src[:0]

    # ── L6. THE BAR CARRIES THE MEASURED FIGURES, NOT THE PROJECTED ONE ─────────────────────────
    #  A blind in this round came back VACUOUS against no leg at all: nothing asserted what clause (b)
    #  SAYS, so the bar could have claimed the row's hoped-for 3.2x and the sweep would have agreed.
    #  The figures are the delivery here — the row's premise is refuted by them — so they are guarded.
    _prompt569 = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    _i569, _j569 = _prompt569.index("\n P2.17 "), len(_prompt569)
    import re as _re569c
    _m569 = _re569c.search(r"\n P\d+\.\d+ ", _prompt569[_i569 + 1:])
    if _m569:
        _j569 = _i569 + 1 + _m569.start()
    _bar569 = " ".join(_prompt569[_i569:_j569].split())
    #  the three measurements, each by its own number, so losing one cannot hide behind the others
    for _frag in ("SERIAL 259s", "2 SHARDS 162s", "4 SHARDS 211s"):
        assert _frag in _bar569, (
            "clause (b) no longer carries this measurement, and the three together are the finding: "
            "four shards came out WORSE than two", _frag)
    assert "THE OPTIMUM, 1.60x" in _bar569, (
        "the bar does not name the measured optimum, so a later round cannot tell which shard count was "
        "chosen on evidence")
    assert "WORSE THAN TWO" in _bar569, (
        "the bar no longer records that MORE shards were slower. Without it a later round reads 1.60x as "
        "a floor to be raised by adding shards, which the measurement refutes")
    #  AND THE PREMISE IT REFUTES IS NAMED, because a refutation nobody can locate is an opinion
    assert "THE SINGLE TREE WAS NEVER THE LIMIT" in _bar569, (
        "the bar states the figures without the conclusion that FU-253's premise was wrong: the sweep "
        "was not serial because blinds mutate one tree, it was slow because 6 cores and 8.3 GB cannot "
        "boot four pytests at once")
    assert "3.2x is not available here" in _bar569, _bar569[:0]
    #  the safety claim that justifies the whole approach
    assert "NEVER MUTATES THE REAL TREE" in _bar569, (
        "the bar drops the sharded path's main safety property, which is the reason it is a copy and "
        "not a git worktree")
    assert "THE SERIAL PATH REMAINS THE DEFAULT" in _bar569, (
        "the bar no longer says the trusted path stays the default; equivalence on one list on one "
        "machine is evidence about that run, not a promotion")


def test_w570_a_key_shown_only_by_a_printed_line_is_surfaced(client):
    """FU-348 — the pre-flight's key screen counted only PAGES, so a CLI-surfaced key read as unsurfaced.

    THE ROW SHAPED THE FIX BY NAMING THE FAMILY: "the fourth precision defect in this screen family after
    FU-303, FU-317 and FU-319, with the same shape as all of them: A TEXTUAL PROXY STANDING IN FOR A
    STRUCTURAL QUESTION". So "a line in scripts/ mentions the key near the word print" would have been a
    fifth. The structural question is whether the key is read INSIDE an emitting call, and it is answered
    on the AST.

    AND IT HAD TO HANDLE ONE LEVEL OF INDIRECTION OR IT WOULD NOT HAVE FIXED ANYTHING. The real case does
    `_nc = _out.get("not_considered_row_count")` and then prints `_nc`, so the key's literal never appears
    inside the print: asking only "is the key in an emitting call" answered NONE for the exact case the
    row was filed about. One level, stated as one, because a screen claiming more reach than it has is
    this family's own defect.
    """
    import ast as _ast570
    import os as _os570
    import pathlib as _pl570
    import sys as _sys570
    import tempfile as _tmp570

    _root = _pl570.Path(__file__).resolve().parents[1]
    _sys570.path.insert(0, str(_root / "scripts"))
    import selfcheck_diff as _sc570

    # ── L1. THE REAL CASE: a key whose consumer is a ROUND is surfaced by the CLI that prints it ──
    #  FU-345's whole subject was that the round-start step states its own width, and that step is a
    #  CLI. Counting only pages made such a key reach "no surface" BY CONSTRUCTION.
    for _key in ("not_considered_row_count", "commits_no_round_could_be_read_from"):
        _cli = _sc570._cli_surfaces({"scripts/followups.py", "agentic_core/plan_followups.py"}, _key)
        assert "scripts/followups.py" in _cli, (
            f"{_key!r} is printed by the round-start step and the screen does not see that surface",
            sorted(_cli))
    #  AND THE DECISION CONSULTS IT. A blind that left `_cli_surfaces` perfect and stopped `check_keys`
    #  from calling it came back VACUOUS against the loop above: the machinery worked and the screen had
    #  reverted to pages-only. A leg must reach the decision, not only the helper beneath it.
    _dec570 = _src_of_check_keys = (_root / "scripts/selfcheck_diff.py").read_text(encoding="utf-8")
    _ci = _dec570.index("def check_keys")
    _body570 = _dec570[_ci:_dec570.index("def check_renames", _ci)]
    assert "cli = _cli_surfaces(others, key)" in _body570, (
        "check_keys no longer asks whether a printed line surfaces this key, so the screen is back to "
        "counting pages only — which is the defect FU-348 was filed for")
    assert "if cli:" in _body570 and "continue" in _body570, (
        "check_keys computes a CLI surface and does not act on it")

    # ── L2. A MENTION IS NOT A SURFACE, which is the narrowing W493 already paid for once ────────
    #  That refutation found "skip if ANY other file mentions it" made the printed label false. A name
    #  that is assigned, imported or asserted but never EMITTED must not count.
    for _key in ("BORING_KEYS", "_LOG_METHODS"):
        assert not _sc570._cli_surfaces({"scripts/selfcheck_diff.py"}, _key), (
            f"{_key!r} is never printed and was counted as a surface anyway", _key)
    #  and a test file is never a surface, whatever it contains
    assert not _sc570._cli_surfaces({"integration_tests/test_mvp_spine.py"}, "verdict"), (
        "a test file was counted as a surface; a guard asserting a literal is not a surface")

    # ── L3. THE EMITTING-CALL WALK IS STRUCTURAL, NOT TEXTUAL ───────────────────────────────────
    #  Driven on a synthetic file so the distinction is unambiguous: the word `print` in a comment or a
    #  string must not count, and a logger call must.
    _d = _tmp570.mkdtemp()
    _p = _os570.path.join(_d, "m.py")
    _pl570.Path(_p).write_text(
        'import logging\n'
        'log = logging.getLogger("x")\n'
        '# print("alpha") this is a comment, not a call\n'
        'NOTE = \'print("beta") inside a string, not a call\'\n'
        'def f(d):\n'
        '    print(d["gamma"])\n'
        '    log.info("delta is %s", d["delta"])\n'
        '    x = d["epsilon"]\n'
        '    helper(d["zeta"])\n'
        '    return x\n', encoding="utf-8")
    _segs = _sc570._emitting_calls(_p)
    _joined = " || ".join(_segs)
    assert "gamma" in _joined, ("a real print call was not found", _segs)
    assert "delta" in _joined, ("a logger call was not counted as emitting", _segs)
    assert "alpha" not in _joined, ("the word print in a COMMENT was read as a call", _segs)
    assert "beta" not in _joined, ("the word print inside a STRING was read as a call", _segs)
    #  epsilon is read and returned, never emitted
    assert "epsilon" not in _joined, ("a key that is only returned was counted as emitted", _segs)
    #  AND zeta IS PASSED TO A CALL THAT DOES NOT EMIT. This case exists because the first version of
    #  this leg had no Call-but-not-emitting example: `print` in a comment and `print` in a string are
    #  not calls, and a subscript is not a call, so a blind that counted EVERY call as emitting changed
    #  nothing any assertion could see and came back VACUOUS.
    assert "zeta" not in _joined, (
        "a key passed to an ordinary function was counted as emitted; every call would then be a "
        "surface, which is the textual-proxy failure in its purest form", _segs)
    assert not _sc570._cli_surfaces({_p}, "zeta"), "a non-emitting call counted as a CLI surface"
    assert _sc570._cli_surfaces({_p}, "gamma") == {_p}
    assert not _sc570._cli_surfaces({_p}, "epsilon"), "a returned-but-unprinted key counted as surfaced"
    #  a file that will not parse yields NOTHING rather than guessing
    _bad = _os570.path.join(_d, "broken.py")
    _pl570.Path(_bad).write_text("def f(:\n", encoding="utf-8")
    assert _sc570._emitting_calls(_bad) == [], "an unparseable file was read as having emitting calls"

    # ── L4. ONE LEVEL OF INDIRECTION, AND THE BOUNDARY IS WHERE IT SAYS IT IS ───────────────────
    #  The real case needs one level. Two levels are deliberately NOT followed, and the guard asserts
    #  the boundary rather than leaving a later round to discover it: a screen that claims more reach
    #  than it has is the defect this family keeps producing.
    _q = _os570.path.join(_d, "ind.py")
    _pl570.Path(_q).write_text(
        'def one(d):\n'
        '    val = d["one_level"]\n'
        '    print(f"{val}")\n'
        'def short(d):\n'
        '    a = d["short_alias"]\n'
        '    print(f"{a}")\n'
        'def two(d):\n'
        '    first = d["two_levels"]\n'
        '    second = first\n'
        '    print(f"{second}")\n', encoding="utf-8")
    #  ONE LEVEL IS FOLLOWED: the key is bound to a name and that name is emitted. This is the
    #  real case — followups.py binds the key to a local and prints the local — so without it the
    #  fix would not have fixed the thing the row was filed about.
    assert "val" in _sc570._aliases_of(_q, "one_level"), _sc570._aliases_of(_q, "one_level")
    assert _sc570._cli_surfaces({_q}, "one_level") == {_q}, (
        "one level of indirection is not followed, which is the real case")
    #  A ONE-CHARACTER ALIAS IS REFUSED, and the cost is stated rather than hidden: a single letter
    #  would match almost any emitting call, and a FALSE surface is worse than a missed one here
    #  because it makes the screen CLEAR something.
    assert not _sc570._aliases_of(_q, "short_alias"), (
        "a one-character alias was trusted", _sc570._aliases_of(_q, "short_alias"))
    assert not _sc570._cli_surfaces({_q}, "short_alias"), (
        "a key bound to a single-letter name was reported as surfaced; that is the stated cost "
        "of refusing one-character aliases, and it must stay a MISS, never a false clear")
    #  TWO LEVELS ARE NOT FOLLOWED, which the helper says and this asserts, so a later round cannot
    #  read more reach into the screen than it has.
    assert not _sc570._cli_surfaces({_q}, "two_levels"), (
        "two levels of indirection were followed; the helper documents one, and a screen must not "
        "quietly reach further than it claims")

    # ── L5. THE TWO FINDINGS ARE NO LONGER ONE MESSAGE ──────────────────────────────────────────
    #  "No page reads it" was printed whether a CLI showed the value or nothing did, so a round could
    #  not tell NO PAGE from NOBODY. The row's closing line was: "a round must read the lead as no
    #  PAGE, not nobody."
    _src570 = (_root / "scripts/selfcheck_diff.py").read_text(encoding="utf-8")
    assert "reaches NO SURFACE AT ALL" in _string_constants(_src570), (
        "the finding no longer distinguishes no-page from no-surface-of-any-kind")
    assert "no print or log statement emits it" in _string_constants(_src570), (
        "the finding does not say that the CLI was checked too, so a reader cannot tell what was looked "
        "for")
    #  AND THE CHECK'S OWN LABEL STOPPED BEING FALSE ABOUT ITS SUBJECT
    assert '"a key produced but shown by neither a page nor a printed line"' in _src570, (
        "the keys label still says 'no surface' while the check looks at pages AND printed lines; the "
        "label was false about exactly the key this row was filed for")
    #  the structural claim is stated where the next round will read it
    #  CASE-INSENSITIVE *AND* WHITESPACE-NORMALISED. The module quotes the row's own wording in lower
    #  case AND the sentence WRAPS ACROSS TWO SOURCE LINES, so a contiguous match against the raw text
    #  finds nothing though the phrase is plainly there — the line-wrapping class that bit a page guard
    #  earlier tonight, in Python prose this time.
    _flat570 = " ".join(_src570.split()).lower()
    assert "textual proxy standing in for a structural question" in _flat570, (
        "the module no longer records why this is answered on the AST rather than by pattern-matching "
        "a line, which is the fourth defect this screen family produced")
    #  and the helper admits what it does not follow
    _ai = _src570.index("def _aliases_of")
    _seg570 = _src570[_ai:_ai + 1400]
    assert "Two levels" in _seg570 and "not followed" in _seg570, (
        "the indirection helper no longer states its boundary", _seg570[:160])
    _ast570.parse(_src570)


def test_w571_a_starved_refutation_cannot_read_as_a_complete_one(client):
    """FU-259 — W490 raised 40 findings, verified 13, and the run returned a normal-looking result.

    The other 27 agents died with "No space left on device" while creating their git worktrees, because
    56 worktrees had accumulated across every round since W479 and nothing removed them. Removing 55
    recovered 9.6 GB. So a round read 13 verified findings as a refutation of 40 and the difference was
    invisible — the defect class this programme removes, in the instrument used to find it.

    THE ROW NAMED TWO FIXES. (a) check free space before launching and remove the worktrees after;
    (b) a refutation whose agents died must not read as a completed one. Both are driven here.

    AND THE ROW'S PREMISE WAS BETTER THAN IT KNEW. It said the errored count "is in the tool result";
    measured, the task NOTIFICATION carries aggregate counts and the RESULT FILE carries something
    stronger — one `workflow_agent` record per agent with its own `state` and a `label` naming its lens
    — so completeness is decided PER LENS from the artefact a round actually keeps. W490's failure was
    that the total looked plausible; a lens that lost every agent can now be named.
    """
    import json as _json571
    import pathlib as _pl571
    import sys as _sys571

    _root = _pl571.Path(__file__).resolve().parents[1]
    _sys571.path.insert(0, str(_root / "scripts"))
    import refutation_gate as _rg571

    # ── L1. THE COST OF A WORKTREE IS MEASURED, NOT GUESSED ─────────────────────────────────────
    #  A floor derived from a number with no source is the class W565 removed from the suite constant.
    assert _rg571.BYTES_PER_WORKTREE > 0
    assert "measured W569" in _rg571.BYTES_PER_WORKTREE_BASIS, (
        "the per-worktree cost cites no measurement, so the gate's floor is a preference",
        _rg571.BYTES_PER_WORKTREE_BASIS)
    assert "5,126 files" in _rg571.BYTES_PER_WORKTREE_BASIS, _rg571.BYTES_PER_WORKTREE_BASIS

    # ── L2. `before` REFUSES WHEN THE DISK CANNOT HOLD THE AGENTS, AND IS THREE-STATE ───────────
    _ok = _rg571.before(1)
    assert _ok["may_launch"] in (True, False, None), _ok
    assert _ok["free_bytes"] is None or isinstance(_ok["free_bytes"], int), _ok
    #  an absurd number of agents must be refused on this machine, whatever its free space
    _huge = _rg571.before(100000)
    assert _huge["may_launch"] is False, (
        "a refutation needing far more disk than exists was not refused", _huge["basis"][:140])
    assert "REFUSED" in _huge["basis"] and "W490" in _huge["basis"], (
        "the refusal does not say what it is preventing, so a round will raise the number and retry",
        _huge["basis"][:160])
    #  and the arithmetic is the two figures it names, not a typed number
    assert _huge["needed_bytes"] == 100000 * _rg571.BYTES_PER_WORKTREE + _rg571.HEADROOM_BYTES, _huge
    #  THE HEADROOM IS REAL: agents run pytest, which writes stores, and that is not free
    assert _rg571.HEADROOM_BYTES > 0 and "headroom" in _huge["basis"], _huge["basis"][:120]

    # ── L3. `after` DECIDES FROM THE PER-AGENT RECORDS, AND NAMES A DEAD LENS ───────────────────
    #  W490's shape: 45 launched, 18 done, 27 errored. It must come back INCOMPLETE.
    _w490 = _rg571.after({"agentCount": 45, "workflowProgress":
                          [{"type": "workflow_agent", "state": "done", "label": f"refute:l{_i % 3}"}
                           for _i in range(18)]
                          + [{"type": "workflow_agent", "state": "error", "label": f"refute:l{_i % 3}"}
                             for _i in range(27)]})
    assert _w490["complete"] is False, ("W490's own shape reads as a complete refutation", _w490)
    assert "error x27" in _w490["basis"], _w490["basis"][:160]
    assert "W490" in _w490["basis"], (
        "the refusal does not name the round it is preventing a repeat of", _w490["basis"][:160])
    #  A LENS THAT LOST EVERY AGENT IS NAMED. This is what the aggregate counts cannot say, and it is
    #  the difference between "13 findings" and "13 findings and one dimension unexamined".
    _dead = _rg571.after({"agentCount": 5, "workflowProgress":
                          [{"type": "workflow_agent", "state": "done", "label": "refute:alive"}] * 3
                          + [{"type": "workflow_agent", "state": "error", "label": "refute:dead"}] * 2})
    assert _dead["complete"] is False and "every agent died in lens(es): dead" in _dead["basis"], (
        _dead["basis"][:200])
    #  A MISSING RECORD IS AN AGENT NOBODY CAN ACCOUNT FOR — a different failure from a failed one.
    _gap = _rg571.after({"agentCount": 10, "workflowProgress":
                         [{"type": "workflow_agent", "state": "done", "label": "refute:x"}] * 7})
    assert _gap["complete"] is False and "7 agent record(s) for 10 launched" in _gap["basis"], (
        _gap["basis"][:160])
    #  ONLY "done" COUNTS. A state nobody has seen yet must not be assumed benign: the failure states
    #  cannot be enumerated from a successful run, and guessing them invents what this gate detects.
    _odd = _rg571.after({"agentCount": 2, "workflowProgress":
                         [{"type": "workflow_agent", "state": "done", "label": "refute:a"},
                          {"type": "workflow_agent", "state": "some_future_state", "label": "refute:a"}]})
    assert _odd["complete"] is False, ("an unrecognised agent state was treated as finished", _odd)

    # ── L4. THE LENS IS THE SECOND LABEL SEGMENT, MEASURED ON REAL LABELS ───────────────────────
    #  A refute agent is `refute:<lens>`; a verify agent is `verify:<lens>:<finding title>`. Taking the
    #  LAST segment reported 35 "lenses" for a run with five, each holding one agent — which made the
    #  dead-lens check fire on any single death and name a FINDING instead of a lens.
    _mixed = _rg571.after({"agentCount": 4, "workflowProgress": [
        {"type": "workflow_agent", "state": "done", "label": "refute:guards"},
        {"type": "workflow_agent", "state": "done", "label": "verify:guards:a long finding title here"},
        {"type": "workflow_agent", "state": "done", "label": "refute:route-mechanism"},
        {"type": "workflow_agent", "state": "done", "label": "verify:route-mechanism:another title"}]})
    assert sorted(_mixed["by_lens"]) == ["guards", "route-mechanism"], (
        "the lens is not read from the second label segment, so a verify agent is counted as its own "
        "lens and a run of five lenses reports dozens", sorted(_mixed["by_lens"]))
    assert _mixed["by_lens"]["guards"]["total"] == 2, _mixed["by_lens"]

    # ── L5. A RESULT THAT SAYS TOO LITTLE IS NOT KNOWN, AND THAT IS NOT A PASS ──────────────────
    assert _rg571.after({"confirmed": [1, 2, 3]})["complete"] is None, (
        "a result with neither per-agent records nor aggregate counts was decided anyway")
    assert _rg571.after("not a mapping")["complete"] is None
    _nk = _rg571.after({"confirmed": []})
    assert "This is not a pass" in _nk["basis"] or "as invisible as it was then" in _nk["basis"], (
        _nk["basis"][:160])

    # ── L6. `cleanup` NEVER TOUCHES THE MAIN WORKTREE ───────────────────────────────────────────
    #  The accumulation was the cause, so removal is the fix — but a cleanup that could remove the
    #  working tree would be far worse than the disk filling up.
    _src571 = (_root / "scripts/refutation_gate.py").read_text(encoding="utf-8")
    assert "main, rest = wts[0], wts[1:]" in _src571, (
        "cleanup no longer separates the main worktree from the rest by position")
    assert "for w in rest:" in _src571, "cleanup iterates something other than the secondary worktrees"
    _cl = _rg571.cleanup()
    assert isinstance(_cl.get("removed"), list) and isinstance(_cl.get("failed"), list), _cl
    #  it is honest when there is nothing to do, rather than claiming a recovery
    assert "never touched" in _cl["basis"] or "nothing is claimed" in _cl["basis"], _cl["basis"][:160]
    #  AND THIS REPOSITORY'S OWN MAIN WORKTREE SURVIVED THE CALL
    assert (_root / ".git").exists() and (_root / "scripts" / "refutation_gate.py").exists(), (
        "cleanup damaged the working tree it was run in")

    # ── L7. THE ROUND RHYTHM NAMES THE GATE, or nobody runs it ──────────────────────────────────
    #  FU-259's fix (a) is "the round rhythm must CHECK free space before launching a refutation and
    #  REMOVE the round's worktrees after it". A script nothing invokes is a script nobody runs.
    _prompt571 = (_root / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    _flat571 = " ".join(_prompt571.split())
    assert "refutation_gate.py" in _flat571, (
        "the delivery plan's rhythm does not name the gate, so a refutation can still be launched "
        "without checking the disk and read as complete with agents dead")
    for _frag in ("before --agents", "after --result", "cleanup"):
        assert _frag in _flat571, ("the rhythm does not say how to invoke the gate", _frag)


def test_w572_a_scripture_surface_holds_no_text_of_its_own(client):
    """MILESTONE M1 · R5.3 — scripture under a citation that is not its own, on the strictest surface.

    TajwidCoach hard-coded Arabic in the .tsx and badged it with a surah-and-ayah range whose text
    under Hafs is something else. No source on the panel; the whole file contained no retrieval call
    of any kind. And the panel's prose VOUCHED for the pairing, so the page asserted the correctness
    of its own mislabelling.

    THE FIX IS STRUCTURAL, so the guard is too. A reference cannot drift from the text beside it when
    both come from the same response, so the legs below assert DERIVATION, not wording: no scripture
    literal in a file that renders it, every label read off the response, and no fallback copy.
    """
    import ast as _ast572
    import pathlib as _pl572
    import re as _re572

    _root = _pl572.Path(__file__).resolve().parents[1]
    _app = _root / "apps" / "workstation-superapp" / "src"
    _ARABIC = _re572.compile("[\u0600-\u06FF\u0750-\u077F\ufb50-\ufdff\ufe70-\ufeff]")
    #  An input's placeholder is a HINT TO THE TYPIST, not content the page asserts. It is the one
    #  Arabic a scripture surface may legitimately hold, so it is excluded by shape rather than by
    #  naming the file that happens to have one today.
    _PLACEHOLDER = _re572.compile(r'placeholder="[^"]*"')

    # ── L1. THE CLASS: a component that RENDERS Arabic may not CONTAIN any ──────────────────────
    #  Scoped to the files that style text as Arabic, because those are the ones that can display
    #  scripture. Measured, not assumed: exactly two components render `font-arabic`.
    _renderers = []
    for _p in sorted(_app.rglob("*.tsx")):
        if "node_modules" in _p.parts:
            continue
        _t = _p.read_text(encoding="utf-8")
        if "font-arabic" in _t:
            _renderers.append(_p)
            _residue = _ARABIC.findall(_PLACEHOLDER.sub("", _t))
            assert not _residue, (
                f"{_p.name} styles text as Arabic AND holds {len(_residue)} Arabic character(s) "
                "outside an input placeholder — scripture written into a source file cannot carry "
                "provenance, and a reference beside it is free to be wrong (M1 R5.3)")
    assert len(_renderers) >= 2, (
        "no component renders font-arabic any more, so this guard would pass by having nothing to "
        "check — it must be re-scoped rather than left vacuous", [p.name for p in _renderers])

    # ── L2. THE PANEL IS A CONSUMER, AND EVERY LABEL IS DERIVED ─────────────────────────────────
    _hub = _app / "pages" / "domains" / "QEPReligionHub.tsx"
    _src = _hub.read_text(encoding="utf-8")
    #  COMMENTS ARE NOT CODE. The blind that deleted the retrieval call PASSED this leg, because the
    #  comment recording the fix names the route — the guard was reading its own documentation. Strip
    #  comments first, then look for the CALL rather than the string.
    _code = _re572.sub(r"/\*.*?\*/", "", _src, flags=_re572.S)
    _code = "\n".join(_l for _l in _code.splitlines() if not _l.lstrip().startswith("//"))
    assert _re572.search(r"apiJson<SourcedAyah>\(\s*`/api/v1/qep/ayah/", _code), (
        "the religion hub no longer CALLS the sourced route (a mention in a comment is not a call)")
    #  AND AT THE SITE, not anywhere in the file. `{ayah.ref}` occurs twice — once in the badge and
    #  once inside `${ayah.ref}` in the prose — so a check over the whole file survives the badge
    #  being replaced by a literal, which is the defect itself.
    _badge = _code[_code.index("absolute top-10 left-10"):]
    _badge = _badge[:_badge.index("</div>")]
    for _derived in ("{ayah.ref}", "{ayah.source}"):
        assert _derived in _badge, (
            f"the citation badge does not render {_derived} — a label that is not read off the "
            "response is a literal, which is the whole mechanism of this defect")
    assert "{ayah.text_arabic}" in _code, "the verse itself is not read off the response"
    #  THE REFERENCE MUST NOT BE WRITEABLE AS PROSE. A surah-ayah citation typed into the file is
    #  exactly what was there before; any `Name: n-n` literal in this file is that shape returning.
    _cite = _re572.compile(r'>\s*[A-Z][A-Za-z\'-]+:\s*\d+(-\d+)?\s*<')
    assert not _cite.search(_code), (
        "a surah-and-ayah citation is written into the page again rather than read from the source")

    # ── L3. NO FALLBACK COPY, AND THE FAILURE PATH SHOWS NOTHING ────────────────────────────────
    #  The honest property is not "it handles an error" but "it has nothing to fall back ON". A page
    #  holding a spare copy would render something true-looking from a source it never reached.
    #  The POSITIVE claims are checked on code only — a reassuring sentence that lives in a comment
    #  is not on the surface a person reads. The NEGATIVE one is checked on the whole file, which is
    #  stricter: the sentence that vouched for the pairing may not come back even as a comment.
    _flatc = " ".join(_code.split())
    _flat = " ".join(_src.split())
    assert "keeps no copy of the Qur" in _flatc, (
        "the panel no longer states that it holds no copy to fall back on, which is the claim that "
        "makes its silence on failure meaningful")
    assert "No verse is shown" in _flatc, "the failure path does not say that no verse is shown"
    #  and the old sentence that vouched for the pairing has not come back
    assert "riwayah above are real" not in _flat, (
        "the page vouches for its own verse/reference pairing again")

    # ── L4. THE PRODUCER/CONSUMER CONTRACT, checked against the handler that serves it ──────────
    #  A page reading a field the route does not return renders `undefined` — which, for a citation
    #  beside scripture, is a blank label under real text.
    _api = (_root / "agentic_core" / "religious_domain" / "api.py").read_text(encoding="utf-8")
    _ret = _api[_api.index('@router.get("/ayah/{surah_number}/{ayah_number}")'):]
    _ret = _ret[:_ret.index("# \u2500\u2500 Hifz")] if "# \u2500\u2500 Hifz" in _ret else _ret[:6000]
    #  W594 — ASSERTED ON THE RESPONSE, NOT THE HANDLER'S TEXT. R8 replaced an explicit
    #  `"source": "alquran.cloud",` line with `**_corpus_provenance(edition)`, which still puts `source`
    #  in the response and adds edition, script, riwayah and licence — so this went red while the
    #  response got richer. A guard that greps a function body cannot see a spread dict, and this leg's
    #  own message is about what the HANDLER RETURNS. The fields are read off a real call.
    from agentic_core.religious_domain.api import _corpus_provenance as _cp572
    _resp572 = dict(_cp572("quran-uthmani"))
    _resp572.update({"ref": "1:1", "text_arabic": "…", "surah_name": "…", "basmala": None,
                     "basmala_separated": None, "basmala_basis": None})
    for _field in ("ref", "text_arabic", "surah_name", "source", "basmala",
                   "basmala_separated", "basmala_basis"):
        assert _field in _resp572, (
            f"the page reads ayah.{_field} but the handler no longer returns it, so the surface "
            "renders an empty label beside scripture")
    #  and the provenance R8 added is part of the response, not only of the helper
    for _field in ("edition", "riwayah", "licence"):
        assert _field in _resp572, (f"the ayah response lost its corpus provenance ({_field}), so a "
                                    f"reader cannot tell which transmission they have")
    #  the route still REFUSES an ayah that does not exist, which is what the panel's refusal rests on
    _bad = client.get("/api/v1/qep/ayah/2/999")
    assert _bad.status_code == 422, (
        "an out-of-range ayah no longer refuses, so the page's no-verse path cannot be reached",
        _bad.status_code)
    _ast572.parse(_api)


def test_w572_the_fidelity_ledger_cannot_misreport_its_own_measure(client):
    """MILESTONE M1 ran and the instrument that writes its result had two truth defects.

    (1) The method sentence reported direction on the VERDICT axis only, so it printed that none had
        been made harsher in an edition where FOUR findings were escalated INTO tier 1 — two of them
        with their verdict index RISING, which the verdict axis counts as milder.
    (2) The tier table excluded DELIVERED entries but not REFUTED ones, so three findings nobody could
        reproduce still contributed their tier, inflating tier 3 from 12 to 15.

    A ledger whose subject is truth defects on reached surfaces may not carry one. Both are driven
    FUNCTIONALLY — the renderer is run on crafted input — because a source-text check cannot tell
    whether a counter is actually consulted.
    """
    import json as _json572
    import pathlib as _pl572
    import re as _re572
    import subprocess as _sp572
    import sys as _sys572
    import tempfile as _tf572

    _root = _pl572.Path(__file__).resolve().parents[1]
    _script = _root / "scripts" / "render_fidelity_ledger.py"
    assert _script.is_file(), _script

    def _render(regions, out_name="out.md"):
        """Run the committed renderer on crafted input; return (returncode, stdout+stderr, text)."""
        _d = _pl572.Path(_tf572.mkdtemp())
        _src = _d / "in.json"
        _src.write_text(_json572.dumps(regions), encoding="utf-8")
        _dst = _d / out_name
        _p = _sp572.run([_sys572.executable, str(_script), str(_src), str(_dst),
                         "deadbeef", "2026-01-01", "8086", "6", "W572"],
                        capture_output=True, text=True, encoding="utf-8",
                        env=dict(__import__("os").environ, PYTHONIOENCODING="utf-8"))
        _text = _dst.read_text(encoding="utf-8") if _dst.exists() else None
        return _p.returncode, (_p.stdout or "") + (_p.stderr or ""), _text

    def _f(i, verdict, tier, section="a finding with a name"):
        return {"id": f"R1.{i}", "section": section, "verdict": verdict, "tier": tier,
                "vision_claim": "c", "observed": "o", "evidence": "e"}

    # ── L1. A REFUTED FINDING HAS NO STANDING TIER ──────────────────────────────────────────────
    _regions = [{"region": "R1", "summary": "", "findings": [
        _f(0, "STUB", 3), _f(1, "STUB", 3)], "verdicts": [
        {"index": 0, "corrected_verdict": "STUB", "corrected_tier": 3, "refuted": False,
         "reason": "r", "evidence": "x"},
        {"index": 1, "corrected_verdict": "STUB", "corrected_tier": 3, "refuted": True,
         "reason": "r", "evidence": "x"}]}]
    _rc, _out, _text = _render(_regions)
    assert _rc == 0, _out
    _row = _re572.search(r"^\| 3 \| (\d+) \|", _text, _re572.M)
    assert _row, "the tier table has no tier-3 row"
    assert _row.group(1) == "1", (
        "a REFUTED finding still contributes its tier, so a claim nobody could reproduce puts work "
        "into a phase bucket — v6 read tier 3 as 15 when 12 stood", _row.group(1))

    # ── L2. A TIER ESCALATION IS HARSHER, EVEN WHEN THE VERDICT INDEX RISES ─────────────────────
    #  The exact v6 shape: STUB -> API_ONLY is a HIGHER verdict index (reads as milder) while the
    #  tier moves 2 -> 1, which is the measure M1 is scored on.
    _regions2 = [{"region": "R1", "summary": "", "findings": [_f(0, "STUB", 2)], "verdicts": [
        {"index": 0, "corrected_verdict": "API_ONLY", "corrected_tier": 1, "refuted": False,
         "reason": "r", "evidence": "x"}]}]
    _rc2, _out2, _text2 = _render(_regions2, "out2.md")
    assert _rc2 == 0, _out2
    _flat2 = " ".join(_text2.split())
    _m = _re572.search(r"on the TIER, which is the axis M1 is scored on:\*\* (\d+) finding\(s\)"
                       r" were made HARSHER by the refuter and (\d+) milder, with \*\*(\d+) escalated"
                       r" INTO tier 1\*\*", _flat2)
    assert _m, ("the ledger no longer reports direction on the tier axis, so a refuter tightening a "
                "tier is invisible in the summary", _flat2[:400])
    assert (_m.group(1), _m.group(3)) == ("1", "1"), (
        "a finding moved from tier 2 to tier 1 was not counted as harsher or as an escalation into "
        "tier 1 — this is the case the verdict axis reports as MILDER", _m.groups())

    # ── L3. A NAMELESS FINDING IS REFUSED, AND NOTHING IS WRITTEN ───────────────────────────────
    #  The first v6 draft rendered sixty headings with an empty title, because the caller supplied
    #  `title` and the renderer reads `section`. Every summary count was correct, so nothing else
    #  looked wrong: a dropped field was silent.
    _bad = [{"region": "R1", "summary": "", "findings": [
        {"id": "R1.0", "title": "supplied under the wrong key", "verdict": "STUB", "tier": 2,
         "vision_claim": "c", "observed": "o", "evidence": "e"}],
        "verdicts": [{"index": 0, "corrected_verdict": "STUB", "corrected_tier": 2,
                      "refuted": False, "reason": "r", "evidence": "x"}]}]
    _rc3, _out3, _text3 = _render(_bad, "out3.md")
    assert _rc3 != 0, "a finding with no heading was rendered rather than refused"
    assert _text3 is None, "the renderer refused but wrote a file anyway"
    assert "section" in _out3 and "title" in _out3, (
        "the refusal does not name the field that is missing nor the key it was probably supplied "
        "under, so a reader cannot act on it", _out3[:200])

    # ── L4. THE FIGURES ARE COMPUTED, NOT WRITTEN DOWN ──────────────────────────────────────────
    #  The first draft of that sentence ended "two belonged to findings whose tier went to 1" — true
    #  of v6 and of no other edition. A figure typed into an instrument is FU-365's class: it is
    #  right once and then lies, and it lies in the direction of the round that wrote it.
    _rsrc = _script.read_text(encoding="utf-8")
    _i = _rsrc.index("on the TIER, which is the axis M1 is scored on")
    _sentence = _rsrc[_i:_rsrc.index('w("3.', _i)]
    assert "tier_into_1_read_milder" in _sentence, (
        "the count of escalations the verdict axis called milder is not computed in the sentence")
    for _word in (" two ", " three ", " four ", " 2 of ", " 4 of "):
        assert _word not in _sentence, (
            f"the tier sentence writes {_word.strip()!r} as a literal where a count belongs", _word)

    # ── L5. THE LEDGER AND THE PLAN AGREE ON THE MEASURE ────────────────────────────────────────
    #  NOT pinned to twenty. The invariant that survives this item being worked is that the plan's
    #  M1 record and the ledger it cites report the SAME count — a guard pinned to today's number
    #  would go red the first time a round reduced it, which is FU-365 exactly.
    _led = (_root / "docs" / "VISION_FIDELITY_LEDGER.md").read_text(encoding="utf-8")
    _ver = _re572.search(r"^# Vision Fidelity Ledger \u2014 (v\d+) ", _led, _re572.M)
    assert _ver, "the ledger has no version in its title"
    _t1 = _re572.search(r"^\| \*\*1\*\* \| \*\*(\d+)\*\* \|", _led, _re572.M)
    assert _t1, "the ledger's tier table has no tier-1 row"
    _headings = len(_re572.findall(r"^### R\d+\.\d+ .*\u00b7 tier 1(?: |\*|$)", _led, _re572.M))
    assert _headings == int(_t1.group(1)), (
        "the ledger's own tier-1 TABLE and its tier-1 HEADINGS disagree, so the number the milestone "
        "is scored on is not the number of findings carrying it",
        _t1.group(1), _headings)
    _plan = (_root / "docs" / "FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    _flatp = " ".join(_plan.split())
    assert f"ledger {_ver.group(1)} issued" in _flatp, (
        f"the plan's milestone record does not cite the ledger edition on disk ({_ver.group(1)})")
    assert f"STANDING TIER-1 COUNT = {_t1.group(1)}" in _flatp, (
        "the plan reports a different standing Tier-1 count than the ledger it cites",
        _t1.group(1))


def test_w572_a_sweep_refuses_a_blind_it_cannot_apply(client):
    """A blind whose anchor does not match is not a weak result — it is NO result.

    `blind_sweep` already reported such a blind correctly, as BAD BLIND with no exit code. What it
    did not do was say so UP FRONT: the verdict arrived at the end, after the whole sweep had been
    paid for, and the fix-and-rerun cost another one. Two came back that way tonight from a
    double-escaped em dash in a JSON blind file, which no amount of care in writing JSON prevents.

    So the anchors are now all checked before any of them runs, and a bad one REFUSES the sweep
    rather than warning about it — the point is to fix every bad anchor in one pass and then run once.
    """
    import json as _json572c
    import pathlib as _pl572c
    import subprocess as _sp572c
    import sys as _sys572c
    import tempfile as _tf572c

    _root = _pl572c.Path(__file__).resolve().parents[1]
    _sweep = _root / "scripts" / "blind_sweep.py"
    assert _sweep.is_file(), _sweep

    def _run(blinds):
        _d = _pl572c.Path(_tf572c.mkdtemp())
        _f = _d / "b.json"
        _f.write_text(_json572c.dumps(blinds), encoding="utf-8")
        return _sp572c.run([_sys572c.executable, str(_sweep), "--blinds", str(_f), "--shards", "2"],
                           cwd=str(_root), capture_output=True, text=True, encoding="utf-8",
                           env=dict(__import__("os").environ, PYTHONIOENCODING="utf-8"))

    # ── L1. AN ANCHOR THAT MATCHES NOTHING REFUSES THE WHOLE SWEEP ──────────────────────────────
    #  Paired with a blind whose anchor is FINE, so the refusal must come from the bad one rather
    #  than from the sweep declining to start for some unrelated reason.
    _p = _run([
        {"tag": "a fine anchor", "file": "scripts/blind_sweep.py", "selector": "nothing_at_all",
         "old": "def main() -> int:", "new": "def main() -> int:"},
        {"tag": "an anchor that is in no file", "file": "scripts/blind_sweep.py",
         "selector": "nothing_at_all", "old": "\u2014 a string no file contains \u2014", "new": "x"},
    ])
    assert _p.returncode == 1, ("a sweep with an unapplicable blind did not refuse", _p.returncode,
                                (_p.stdout or "")[:300])
    _out = (_p.stdout or "") + (_p.stderr or "")
    assert "BAD ANCHOR" in _out and "an anchor that is in no file" in _out, (
        "the refusal does not name the blind that cannot be applied", _out[:300])
    assert "a fine anchor" not in _out.split("BAD ANCHOR")[0][-400:] or "BAD ANCHOR" in _out, _out[:200]
    #  AND IT RAN NO TESTS. The whole point is to refuse before the expensive part.
    assert "BLIND(red)" not in _out and "VACUOUS" not in _out, (
        "the sweep ran blinds anyway, so the refusal saves nothing", _out[:300])

    # ── L2. AN ANCHOR THAT MATCHES TWICE IS ALSO NO RESULT ──────────────────────────────────────
    #  The needle-appears-twice class: mutating one occurrence leaves the other, so the defect is
    #  not actually restored and a green guard means nothing. It is as unusable as a missing anchor.
    #  DERIVED, not guessed: the first non-trivial line that occurs more than once in the sweep's own
    #  source. A hardcoded needle here would be a guard pinned to today's file — the first draft used
    #  "import io", which occurs exactly once, and the leg went red on its own premise.
    _sweep_src = (_root / "scripts" / "blind_sweep.py").read_text(encoding="utf-8")
    _twice = next((_l for _l in _sweep_src.splitlines()
                   if len(_l.strip()) > 8 and _sweep_src.count(_l) > 1), None)
    assert _twice, "no line occurs twice in the sweep's source, so the ambiguous-anchor case has no subject"
    _p2 = _run([{"tag": "an anchor that appears twice", "file": "scripts/blind_sweep.py",
                 "selector": "nothing_at_all", "old": _twice, "new": _twice + "  # x"}])
    assert _p2.returncode == 1, ("a blind whose anchor is ambiguous was applied anyway",
                                 _p2.returncode, (_p2.stdout or "")[:300])
    assert "not once" in ((_p2.stdout or "") + (_p2.stderr or "")), (_p2.stdout or "")[:300]

    # ── L3. IT DOES NOT REFUSE A SOUND BLIND FILE ───────────────────────────────────────────────
    #  A gate that refuses everything is not a gate, and it is the failure mode a new refusal most
    #  easily ships with: it looks strict and it blocks all work.
    #
    #  ASSERTED ON THE OUTPUT, NOT THE EXIT CODE, and that is forced rather than preferred. W537 made
    #  a sweep-inside-a-sweep structurally impossible (NESTED_GUARD_ENV), so when this test itself runs
    #  under the sweep the inner run never reaches pytest and returns non-zero for that reason alone.
    #  The exit code cannot tell "refused the file" from "declined to nest"; the REFUSAL TEXT can, and
    #  that is what this leg is about.
    #
    #  The first draft recounted the anchors here instead of invoking the sweep, so it could not have
    #  failed if the gate refused everything. The blind written against it came back BAD BLIND, and
    #  that is what exposed it.
    _p3 = _run([{"tag": "a sound blind", "file": "scripts/blind_sweep.py",
                 "selector": "nothing_at_all",
                 "old": "def main() -> int:", "new": "def main() -> int:"}])
    _out3 = (_p3.stdout or "") + (_p3.stderr or "")
    assert "BAD ANCHOR" not in _out3, (
        "the gate refused a blind whose anchor matches exactly once, so it refuses everything",
        _out3[:300])
    #  and this round's own blind file would pass that same gate
    _mine = _root / "scripts" / "blinds_w572.json"
    _blinds = _json572c.loads(_mine.read_text(encoding="utf-8"))
    assert len(_blinds) >= 10, ("the blind file shrank", len(_blinds))
    for _b in _blinds:
        #  BYTES, like the gate and like sweep() itself: text mode translates CRLF to a bare newline,
        #  so a correct multi-line anchor in a CRLF file counts 0 when read as text and 1 when read
        #  as bytes. A check that reads its subject differently from the code it checks is measuring
        #  a different file - this very leg would have passed a blind the gate then refused.
        _hits = (_root / _b["file"]).read_bytes().decode("utf-8").count(_b["old"])
        assert _hits == 1, (
            f"this round's own blind {_b['tag']!r} would be refused: its anchor matches {_hits} "
            "time(s) in " + _b["file"])


def test_w573_a_completion_mark_is_read_from_the_state_not_written_beside_it(client):
    """P2.19 clause (a) — MILESTONE M1 R2.0, R2.1, R2.3, R3.1. One mechanism, four surfaces.

    Each of these wrote a completion mark NEXT TO the state instead of FROM it, and in every case the
    honest value was already on the same payload:
      R2.1  every entity was stamped `stage: "commercialise"` at birth, printed by the cockpit badge,
            the shipped README and the Board Pack beside a status of "body pending" whose own basis
            named four sections still awaiting the owned model. W496 derived the sibling `status` and
            said so in its docstring - naming the stage literal too - then left it.
      R3.1  `present: bool(ceo_specification)` is truthiness, so the pending-body placeholder counted
            as a composed strategic layer; `action_plan` was counted present by a basis that itself
            says a roster is not a plan of action; and the only route to any basis on the page was a
            chip that renders ONLY when a layer is absent - so while the count was wrong, nothing
            could show that it was.
      R2.0  the journey map ticked "Operate - run, defend, improve, grow" from `!!vsb && surfaces`,
            which says a repository was written and nothing about anything running.
      R2.3  all six §4 tiles took their completed styling from `const done = !!result`, so a journey
            the §11 screen vetoed after Stage 5 rendered design, operations and commercialisation as
            complete - on a payload that says in so many words that they never ran.

    DRIVEN, not read, wherever there is something to drive: the derivations are pure functions for
    exactly that reason.
    """
    import pathlib as _pl573
    import re as _re573

    from agentic_core.api.vsb import (_action_plan_layer, _derived_stage, _stage_label,
                                      _strategic_layer)

    _root = _pl573.Path(__file__).resolve().parents[1]
    _app = _root / "apps" / "workstation-superapp" / "src"

    # ── L1. THE STAGE IS DERIVED, AND IT IS STRICTER THAN "THE LAST ONE COMPOSED" ───────────────
    _all_pending = {"concept": True, "design": True, "operations": True, "commercialisation": True}
    _s, _b = _derived_stage({"body_pending": dict(_all_pending)})
    assert _s is None and "concept" in _b, ("an entity with every section pending reports a stage", _s, _b)
    _s, _b = _derived_stage({"body_pending": dict(_all_pending, concept=False)})
    assert _s == "concept", ("the first composed section is not reported as the stage reached", _s)
    #  THE GAP CASE: a commercialisation composed while the concept is still pending does NOT carry
    #  the entity to commercialise. Reporting "the last composed" would reproduce the defect one
    #  section along, which is why the measurement is the contiguous prefix.
    _s, _b = _derived_stage({"body_pending": dict(_all_pending, commercialisation=False)})
    assert _s is None, ("a section composed out of order carried the entity past an earlier one", _s)
    assert "out of order" in _b and "commercialisation" in _b, (
        "the out-of-order section is not named, so a reader cannot see why the stage is behind it", _b)
    _s, _b = _derived_stage({"body_pending": {k: False for k in _all_pending}})
    assert _s == "commercialisation", ("a fully composed entity reports no stage", _s, _b)
    #  AND "NOT KNOWN" IS NOT "NOTHING REACHED". A missing map is a different fact from a full one.
    _s, _b = _derived_stage({})
    assert _s is None and "NOT KNOWN" in _b, ("a missing body map is reported as a measured zero", _b)
    #  the label a surface prints never renders the word None
    assert _stage_label({"stage": None}) == "no stage reached"
    assert "None" not in _stage_label({}), _stage_label({})
    assert _stage_label({"stage": "design"}) == "design"

    # ── L2. NO WRITER STAMPS THE LITERAL, ON EITHER ESTABLISH PATH ──────────────────────────────
    _gen = (_root / "agentic_core" / "api" / "genesis.py").read_text(encoding="utf-8")
    assert '"stage": "commercialise"' not in _gen, (
        "an establish path stamps the stage as a constant again")
    #  BOTH paths, and the count is the point: the literal survived W496 because one of two was fixed.
    assert _gen.count('"stage": "pending derivation"') == 2, (
        "both establish paths must defer the stage to the derivation",
        _gen.count('"stage": "pending derivation"'))
    #  EVERY SITE THAT DERIVES A STATUS DERIVES A STAGE. This is the second-writer class stated as a
    #  property rather than as a list of line numbers that will drift.
    _vsrc = (_root / "agentic_core" / "api" / "vsb.py").read_text(encoding="utf-8")
    def _calls(name, src):
        """Calls of exactly `name`, not mentions of it.

        The first draft counted `_derived_status\\(` as a plain substring and found three in vsb.py
        where there are two: one match was inside the longer identifier `_apply_derived_status()`,
        AND that occurrence is in a COMMENT. Both traps at once, in the leg written to catch a fix
        applied at some of its writers — so the leg accused the round's own correct fix.
        """
        body = "\\n".join(_l.split("#", 1)[0] for _l in src.splitlines())
        return len(_re573.findall(r"(?<![A-Za-z0-9_])" + name + r"\(", body))

    for _mod, _src in (("genesis.py", _gen), ("vsb.py", _vsrc)):
        #  vsb.py holds the two definitions as well as its call sites
        _st = _calls("_derived_status", _src) - (1 if _mod == "vsb.py" else 0)
        _sg = _calls("_derived_stage", _src) - (1 if _mod == "vsb.py" else 0)
        assert _st >= 1, (f"{_mod} no longer derives a status anywhere, so this leg compares two "
                          "zeroes and cannot fail", _mod)
        assert _st == _sg, (
            f"{_mod} derives the status at {_st} site(s) and the stage at {_sg} - a completion mark "
            "fixed at some of its writers is the class that produced this row", _st, _sg)

    # ── L3. EVERY READER OF THE STAGE READS THE DERIVED ONE ─────────────────────────────────────
    #  A writer fixed without its readers moves the untruth down a layer. There are three.
    #  AT THE SITE. `_stage_label(vsb)` appears TWICE in vsb.py - the README and the Board Pack - so
    #  a file-wide check survives either one reverting to the raw field. The blind that reverted the
    #  README came back VACUOUS for exactly that reason.
    assert 'f"- **Stage:** {_stage_label(vsb)}' in _vsrc, (
        "the shipped README prints the raw stage field again rather than the derived label - and "
        "this reader writes to DISK, into a repository the founder keeps")
    assert 'f"- **Stage basis:**' in _vsrc, "the shipped README no longer carries the stage's basis"
    assert '"stage_basis": vsb.get("stage_basis")' in _vsrc, (
        "the Board Pack's operational layer no longer carries the stage's basis")
    #  COMMENTS STRIPPED: the comment explaining why the absent-state is rendered necessarily quotes
    #  the words it renders, so a file-wide check passed with the badge deleted.
    _ck = (_app / "pages" / "enterprise" / "VSBCockpit.tsx").read_text(encoding="utf-8")
    _ckc = _re573.sub(r"/\*.*?\*/", "", _ck, flags=_re573.S)
    assert "cockpit-stage-basis" in _ckc and "no stage reached" in _ckc, (
        "the cockpit prints a stage badge with no basis and no absent-state, so a reader cannot tell "
        "a stage that was never reached from a field that failed to load")

    # ── L4. A LAYER IS PRESENT WHEN IT HOLDS SOMETHING, AND `present` FOLLOWS `holds` ───────────
    _PLACEHOLDER = ("content pending the owned model \u2014 this enterprise has not yet composed its "
                    "own commercialisation")
    for _spec, _want in (("", "empty"), ({}, "empty"), (_PLACEHOLDER, "placeholder"),
                         ({"ceo": _PLACEHOLDER}, "placeholder"),
                         ("Two depots, 400 households by Q3", "content")):
        _L = _strategic_layer(_spec)
        assert _L["holds"] == _want, ("the strategic layer's state is wrong", _spec, _L["holds"], _want)
        assert _L["present"] is (_want == "content"), (
            "`present` is not derived from `holds`, which is the whole fix", _L)
    #  THE ROSTER. Its own basis has always said it is not a plan of action; now the count agrees.
    _A = _action_plan_layer({"CEO": "a", "CFO": "b"})
    assert _A["holds"] == "other" and _A["present"] is False, (
        "a board roster is counted as a present action-plan layer again", _A)
    assert "not an action plan" in _A["basis"], _A["basis"]
    assert _action_plan_layer({})["holds"] == "empty"

    # ── L5. EVERY LAYER'S BASIS IS REACHABLE, not only an absent one's ──────────────────────────
    assert '"layers_state": layers_state' in _vsrc, (
        "the pack no longer carries a per-layer state, so the page is back to reading a basis only "
        "through the chip that renders when a layer is MISSING")
    _gj = (_app / "pages" / "synthesis" / "GenesisJourney.tsx").read_text(encoding="utf-8")
    assert "pack-layer-" in _gj and "layers_state" in _gj, (
        "the page does not render each layer's own state and basis")

    # ── L6. THE JOURNEY MAP AND THE §4 RAIL READ THE JOURNEY'S OWN FIELDS ───────────────────────
    #  COMMENTS ARE NOT CODE, and this leg forbids two bindings that the comments recording their
    #  removal necessarily quote. Rewording the comments would work once; stripping them is the
    #  property. (W572 hit the mirror image: a comment holding a REQUIRED string made a presence
    #  check pass with the code deleted.)
    _gjc = _re573.sub(r"/\*.*?\*/", "", _gj, flags=_re573.S)
    _gjc = "\\n".join(_l for _l in _gjc.splitlines() if not _l.lstrip().startswith("//"))
    assert "done: !!vsb && surfaces" not in _gjc, (
        "the Operate milestone is ticked from a repository existing again")
    assert "vsb?.living?.autonomous_cycles" in _gjc, (
        "the Operate milestone does not read whether anything actually tends the entity")
    #  THE RAIL took all six tiles from a single truthiness check on the journey result.
    assert "const done = !!result" not in _gjc, ("the §4 rail takes all six tiles from one flag again")
    assert "railState(key, result)" in _gjc, "the rail does not resolve each stage separately"
    #  and every §4 stage that HAS a verification key is mapped to it, by name
    for _k in ("'concept'", "'research'", "'design'", "'operations'", "'commercialisation'"):
        assert f"key: {_k}" in _gj, ("a §4 tile is not mapped to its verification entry", _k)
    #  THE THREE DISTINCTIONS THE PAYLOAD MAKES, each handled: ran-false, verified-true, and the
    #  absent `ran` that means the stage DID run.
    _rs = _gj[_gj.index("const railState"):]
    _rs = _rs[:_rs.index("interface BoardPack")]
    assert "v.ran === false" in _rs, "a stage the journey never reached is not distinguished"
    assert "v.verified === true" in _rs, "a verified stage is not distinguished from one that merely ran"
    #  AT THE SITE AGAIN: 'not known' appears four times in this file (the type union, the no-journey
    #  branch, this branch, and a chip elsewhere), so a file-wide check survived this branch being
    #  turned into a pass. NOT KNOWN promoted to verified is the three-state failure this programme
    #  keeps finding, and Model · Simulate · Rank has no verification entry, so the path is live.
    assert "if (!v) return { done: false, label: 'not known'" in _rs, (
        "a stage the journey recorded no verification for is reported as a measured state rather "
        "than as unknown")
    #  Model · Simulate · Rank has no verification entry and must say so rather than borrow one
    assert "carries no §10 verification entry" in _rs, (
        "the unverified stage claims a verification it does not have")


def test_w574_a_name_a_number_and_a_placeholder_each_say_what_is_behind_them(client):
    """P2.19 clauses (b)(c)(d)(e) — MILESTONE M1, eleven rows, four mechanisms.

    (b) A NUMBER WITH NO MEASUREMENT BEHIND IT — a repository card counting only the files one
        generator wrote, a simulated ATP ratio described as expenditure and as a live vital, a
        fabricated architecture version, and API-surface coverage printed as "realisation".
    (c) A NAME WITH NOTHING BEHIND IT — four named consumers of which two never call, a Chief
        described as a trained digital twin in the API's published descriptions, a biomimetic layer
        vouched for as real code when its module cannot be imported, and eight advertised
        destinations resolving to "Page Not Found".
    (d) A PLACEHOLDER THAT READS AS CONTENT — the platform's pending text attributed to the Owner,
        invented board directives beside a grounding count of zero, a prompt's own field template
        rendered as a job advert, and a manifest calling generated files scaffolds.
    (e) A HARDCODED LITERAL PRESENTED AS THE USER'S OWN — a fixed org structure on an entity's
        cockpit, and a halal tool promising what it withheld while hiding what it had.

    FOUR OF THE ELEVEN CLOSED BY STOPPING A CLAIM rather than building, which clause (c)'s ACCEPT
    anticipated. TWO WERE NOT DELETED THOUGH THEY LOOKED DEAD: the Forge and Introspection pages are
    real and were behind the wrong path, and removing a true statement is its own defect.
    """
    import ast as _ast574
    import json as _json574
    import pathlib as _pl574
    import re as _re574

    _root = _pl574.Path(__file__).resolve().parents[1]
    _app = _root / "apps" / "workstation-superapp" / "src"

    def _code(p):
        """Source with comments stripped — a claim in a comment is not a claim on a surface, and a
        comment holding a required string makes a presence check pass with the code deleted."""
        t = p.read_text(encoding="utf-8")
        t = _re574.sub(r"/\*.*?\*/", "", t, flags=_re574.S)
        return "\n".join(l for l in t.splitlines() if not l.lstrip().startswith("//"))

    # ── (c) NOTHING ADVERTISED LEADS NOWHERE — the mechanism, not the eight edits ───────────────
    _routes = set(_re574.findall(r'path="(/[^"]*)"',
                                 (_app / "App.tsx").read_text(encoding="utf-8")))
    assert len(_routes) > 50, ("the route table could not be read, so this leg proves nothing",
                               len(_routes))
    _nav = {"SearchMeshModal": _app / "components" / "SearchMeshModal.tsx",
            "CommandPalette": _app / "components" / "layout" / "CommandPalette.tsx"}
    _advertised = 0
    for _who, _p in _nav.items():
        _t = _code(_p)
        _dests = _re574.findall(r"route: '(/[^']*)'", _t) + _re574.findall(r"go\(\s*'[^']*',\s*'(/[^']*)'", _t)
        assert _dests, (f"{_who} advertises no destinations, so this leg cannot fail", _who)
        _advertised += len(_dests)
        _dead = sorted({d for d in _dests if d != "/" and d not in _routes})
        assert not _dead, (
            f"{_who} advertises {len(_dead)} destination(s) the router does not serve, so they "
            f"render the catch-all Page Not Found: {_dead}")
    assert _advertised >= 20, ("the navigation indexes shrank to almost nothing", _advertised)

    # ── (c) THE COMPLIANCE PAGE NAMES ONLY MODULES THAT CALL THE SCREEN ─────────────────────────
    #  The page used to name four systems of which two never called it. Each name now carries its
    #  module, so the claim is checkable against the tree instead of remembered.
    _cc = _code(_app / "pages" / "governance" / "ComplianceChecker.tsx")
    _named = _re574.findall(r"module: '([^']+)'", _cc)
    assert len(_named) >= 5, ("the compliance page names almost no consumers", _named)
    for _m in _named:
        _f = _root / _m
        assert _f.exists(), (f"the compliance page names {_m}, which does not exist")
        _src = _f.read_text(encoding="utf-8", errors="replace")
        assert ("screen_compliance" in _src or "assure_delivery" in _src), (
            f"the compliance page names {_m} as a consumer of the §11 screen and it contains no "
            f"call to it — this is the exact claim the page exists for a reader to check")
    #  and the two that never called it are not named again
    for _absent in ("api/forge.py", "synthesis/api.py", "synthesis_studio.py"):
        assert not any(_absent in _m for _m in _named), (
            f"{_absent} is named as a consumer again and it contains no call", _absent)

    # ── (c) NO PUBLISHED DESCRIPTION CALLS THE CHIEF A TRAINED TWIN ─────────────────────────────
    #  Scoped to the CHIEF. agentic_core/api/digital_twin.py models real-world SYSTEMS, where the
    #  term is correct — a check on the phrase alone would accuse working code, and did when I
    #  first ran it.
    _claims = []
    for _mod in ("agentic_core/api/board.py", "agentic_core/api/swarm.py",
                 "agentic_core/api/v138/ceo.py"):
        _src = (_root / _mod).read_text(encoding="utf-8")
        for _n in _ast574.walk(_ast574.parse(_src)):
            if not isinstance(_n, (_ast574.FunctionDef, _ast574.AsyncFunctionDef)):
                continue
            if not any("router" in _ast574.dump(_d) for _d in _n.decorator_list):
                continue
            _d = (_ast574.get_docstring(_n) or "").lower()
            if "chief" in _d and "digital twin" in _d and "no twin model is trained" not in _d:
                _claims.append(f"{_mod}:{_n.lineno} {_n.name}")
    assert not _claims, (
        "a PUBLISHED route description calls the Chief a digital twin with no disclaimer — these "
        "are served at /docs, and the disclaimer reached the payloads and the pages but stopped "
        "short of them", _claims)
    #  the CEO's own system prompt is a writer too: it shapes what the answer claims.
    #  COMMENTS STRIPPED — the comment recording this removal necessarily quotes the phrase, and a
    #  whole-file check therefore fails on the fix itself. Fourth occurrence of that class tonight,
    #  so it is handled by shape rather than by rewording the comment.
    _ceosrc = (_root / "agentic_core/api/v138/ceo.py").read_text(encoding="utf-8")
    _ceo = "\\n".join(l.split("#", 1)[0] for l in _ceosrc.splitlines())
    assert "digital-twin Chief" not in _ceo, (
        "the AI CEO prompt tells the model the Chief is a trained digital twin")

    # ── (c) A LAYER THAT CANNOT BE IMPORTED SAYS SO (the state and its drive live in W506's guard)
    from agentic_core.vbs import quality as _Q574
    assert _Q574.LAYER_STATE["Respiratory"]["state"] == "code_unloadable", (
        "the Respiratory layer is back to a state that promises real code one wiring away",
        _Q574.LAYER_STATE["Respiratory"]["state"])
    assert "CANNOT BE IMPORTED" in _Q574.LAYER_STATE["Respiratory"]["basis"], (
        _Q574.LAYER_STATE["Respiratory"]["basis"][:120])

    # ── (d) A PENDING PLACEHOLDER IS NOT THE OWNER'S WORDS ──────────────────────────────────────
    from agentic_core.api.business_plan import _is_unset as _unset574
    assert _unset574("content pending the owned model — this enterprise has not composed its own x")
    assert _unset574("") and _unset574(None)
    assert not _unset574("Lend power tools to residents and track each tool's maintenance")
    _gen = (_root / "agentic_core/api/genesis.py").read_text(encoding="utf-8")
    #  AT THE SITE: `_concept_unset(req.concept)` occurs twice — in this branch and in the
    #  placeholder flag beside it — so a file-wide check survived the branch reverting to a
    #  blank-only test. The needle-appears-twice class, again.
    assert "if _concept_unset(req.concept):" in _gen, (
        "the opening's provenance tests only whether the concept is BLANK again, so the platform's "
        "own pending text passes through establish and is stamped as the Owner's words")

    # ── (d) THE ANSWER IS CHECKED AGAINST ITS OWN GROUNDING ─────────────────────────────────────
    from agentic_core.api.v138.ceo import _ungrounded_sections as _ug574
    _invented = ("## Board directives\n- Validate the structured outputs.\n- Route generation.\n"
                 "- Iterate via the cascade.\n## Priorities\n- a real priority")
    _flag = _ug574(_invented, {"directives": 0})
    assert len(_flag) == 1 and _flag[0]["items"] == 3, (
        "three items printed under a heading the grounding says is empty were not reported", _flag)
    assert "must not be read as one" in _flag[0]["basis"], _flag[0]["basis"]
    #  the grounding's OWN "none recorded" line is not an invented item
    assert _ug574("## Board directives\n- none recorded for this scope", {"directives": 0}) == []
    #  AND IT NEVER FIRES ON A SCOPE THAT HAS DIRECTIVES — the same text, grounded, is clean
    assert _ug574(_invented, {"directives": 3}) == [], (
        "the check fires on a scope whose directives are real, which would make it noise")
    assert _ug574("## Assessment\n- fine", {"directives": 0}) == []
    #  and it reaches the reader, beside the count it contradicts
    _chat = _code(_app / "pages" / "CEOChat.tsx")
    assert "grounding_conflicts" in _chat and "ceo-grounding-conflict" in _chat, (
        "the chat card does not render the conflict, so a reader must still cross-check the "
        "answer's prose against the grounded-in chip themselves")

    # ── (d) THE PROMPT'S OWN TEMPLATE IS NOT A JOB ADVERT ───────────────────────────────────────
    from agentic_core.api.career import _is_template_echo as _echo574
    assert _echo574(_json574.loads('{"title":"...","company":"...","location":"...",'
                                   '"salary_estimate":"...","tags":["tag1","tag2"],'
                                   '"description":"2-sentence description"}')), (
        "the prompt's own field template is accepted as a listing again")
    assert not _echo574({"title": "Senior Data Scientist", "company": "Ordnance Survey",
                         "location": "Southampton", "tags": ["python"]}), (
        "a real listing is discarded — the filter must be conservative")
    #  CONSERVATIVE: one missing field does not make an advert a template
    assert not _echo574({"title": "Data Scientist", "company": "..."}), (
        "a half-filled listing is discarded, trading this defect for the opposite one")
    #  AND THE FILTER IS ACTUALLY CALLED. Driving the helper proves the helper; it says nothing
    #  about whether the parser consults it, and `if False and …` leaves the helper, its placeholder
    #  set and every string intact.
    _car = (_root / "agentic_core/api/career.py").read_text(encoding="utf-8")
    _carc = "\\n".join(l.split("#", 1)[0] for l in _car.splitlines())
    assert "if _is_template_echo(obj):" in _carc, (
        "the parser no longer consults the template filter, so the prompt's own field template "
        "becomes a job listing again")
    assert '"none_basis"' in _car, (
        "a run that discarded every line reports a bare zero, which reads as 'no roles match' — a "
        "false statement about the job market rather than about this deployment")

    # ── (b) THE REPOSITORY CARD COUNTS THE REPOSITORY ───────────────────────────────────────────
    _vsb = (_root / "agentic_core/api/vsb.py").read_text(encoding="utf-8")
    assert '"file_count": len(_on_disk)' in _vsb, (
        "the manifest counts only the files this generator wrote again, so every website, web-app "
        "and phone-app file is missing from the card the founder reads")
    assert 'name != "manifest.json"' in _vsb, (
        "the manifest counts itself — it describes a tree it is in, so the totals go stale by its "
        "own size every time it is written")
    assert '"count_basis"' in _vsb, "the exclusion is silent, which makes the totals unexplainable"

    # ── (b) A SIMULATED FIGURE IS NOT A COST AND NOT A LIVE VITAL ───────────────────────────────
    _del = _code(_app / "pages" / "Deliverables.tsx")
    assert "expended metabolic ATP" not in _del, (
        "the deliverable chip claims ATP was expended again — the payload says the ratio is "
        "simulated, is not measured and cannot fall")
    assert "atp_basis" in _del, "the chip does not carry the payload's own basis for the figure"
    _intro = _code(_app / "pages" / "cognitive" / "Introspection.tsx")
    assert "System Health" not in _intro, (
        "the immune subsystem's figure is published as whole-system health again")
    assert "Immune Health" in _intro and "introspection-immune-health" in _intro, _intro[:200]
    assert "simulated ATP" in _intro, "the simulated ATP ratio is shown as a live vital again"
    #  the fabricated version is gone, and nothing like it has come back: no vNNN claimed as Active
    _ver = _re574.findall(r"v\d{2,}\.\d+ Active", _intro)
    assert not _ver, ("an architecture version is published as active on the self-report page", _ver)

    # ── (b) THE CAVEAT TRAVELS WITH THE NUMBER ──────────────────────────────────────────────────
    _cog = (_root / "agentic_core/api/cognition.py").read_text(encoding="utf-8")
    #  THE BINDING, not the key name: `["measure"] = None` leaves the key present, so a check that
    #  the field exists passes while the caveat is gone exactly as before.
    assert '["measure"] = _r.get("measure")' in _cog, (
        "the producer's statement of WHAT was measured is dropped again, so a consumer renames "
        "route-mount coverage after a method that did not compute it")
    _cogpage = _code(_app / "pages" / "CognitionIntegration.tsx")
    assert "API surface coverage" in _cogpage, "the knowledge card names the figure wrongly again"
    assert not _re574.search(r"`realisation \$\{", _cogpage), (
        "the knowledge card prints the coverage figure as 'realisation' again")

    # ── (e) A FIXED STRUCTURE IS NOT THE USER'S DESIGN; A TOOL SHOWS WHAT IT HAS ────────────────
    _ck = _code(_app / "pages" / "enterprise" / "VSBCockpit.tsx")
    assert "standing organisational structure" in _ck and "not editable" in _ck, (
        "the cockpit presents the platform's fixed seven tiers as this entity's organisational "
        "hierarchy again — no route anywhere creates, renames or removes an officer or a tier")
    _rh = _code(_app / "pages" / "domains" / "ReligionHub.tsx")
    assert "halal-ingredient-screen" in _rh and "halal-withheld" in _rh, (
        "the halal tool hides the ingredient screen it computes and the sections it withholds")
    #  AND IT READS THE RESPONSE. The whole JSX block, both test ids and the blurb all survive a
    #  change that simply stops binding the data — which is exactly what the original defect was:
    #  the endpoint did the work, the response carried it, and the page rendered only its result key.
    assert "r?.ingredient_screen" in _rh and "r?.sections_withheld" in _rh, (
        "the halal panel renders its screen block from something other than the response, so the "
        "work the endpoint actually did still does not reach the reader")
    assert "certification guidance" not in _rh, (
        "the halal blurb promises what the floor withholds again")
    #  the screen itself still refuses to clear — the property, not the wording
    from agentic_core.api.religion import _screen_ingredients as _scr574
    _s = _scr574(["pork gelatin", "glucose syrup"])
    assert _s["verdict"] is None, "the ingredient screen produces a verdict; it may only flag"
    assert [f["ingredient"] for f in _s["flagged"]] == ["pork gelatin"], _s["flagged"]
    assert _s["unmatched"] == ["glucose syrup"], _s["unmatched"]
    assert "NOT thereby acceptable" in _s["basis"], _s["basis"][:120]


def test_w575_p24_the_scatter_closes_on_each_row_it_reproduced(client):
    """P2.4 — the four clusters and the three HIGH rows the Owner held there.

    The bar is per cluster and says how a round must know: "a cluster closes when its rows are closed
    AND a named guard drives the case each row reproduced; the round records, per artefact it removed,
    the check that established reachability. No cluster closes on an import search, and none closes on
    a count alone." This is that guard.
    """
    import ast as _ast575
    import pathlib as _pl575

    _root = _pl575.Path(__file__).resolve().parents[1]

    # ── FU-354 — THE LEDGER. An account that is not in the chart is refused ────────────────────
    #  The row said the two projections "can disagree" and cited record(reserves,750) leaving the
    #  chart at 0.0. RE-DRIVEN: the chart records it in full (reserve_fund +750, cash −750) and the
    #  debit-side TOTAL is 0.00 because both are assets — the correct answer for moving cash into a
    #  reserve. What WAS real: post() invented any account name it was handed.
    from agentic_core.economy.ledger import CHART, VirtualLedger
    _led = VirtualLedger("vsb-w575-guard")
    _led.record("reserves", 750.0, memo="w575 guard")
    assert _led.balances()["reserves"] == 750.0, _led.balances()
    _acc = _led._data["accounts"]
    assert _acc.get("reserve_fund") == 750.0 and _acc.get("cash") == -750.0, (
        "record() no longer makes the balanced posting it means", _acc)
    _tb = _led.trial_balance()
    assert _tb["debit_side_total"] == 0.0 and _tb["balanced"], (
        "an asset-to-asset movement should net to zero on the debit side", _tb)
    assert "not comparable" in (_tb.get("scope") or ""), (
        "trial_balance does not say which set of figures it is, so a reader comparing it with "
        "balances() is comparing two different questions and cannot tell", _tb.get("scope"))
    assert "waterfall pots" in VirtualLedger.BALANCES_SCOPE
    #  THE DEFECT ITSELF: a pot name is not an account, and post() must refuse it
    assert "reserves" not in CHART, "the fixture for this leg is gone: `reserves` is now an account"
    try:
        _led.post("revenue", "reserves", 500.0, memo="w575 guard")
    except ValueError as _e:
        assert "not in the chart" in str(_e) and "WATERFALL POT" in str(_e), str(_e)[:200]
    else:
        raise AssertionError(
            "post() accepted `reserves`, a waterfall-pot name that is not an account — it opens a "
            "phantom asset beside the real reserve_fund, which is how FU-354's apparent divergence "
            "between the two projections was produced")
    #  and a REAL posting still works, so the refusal is not a blanket one
    _led.post("cash", "revenue", 200.0, memo="w575 guard")
    assert _led._data["accounts"].get("revenue") == 200.0, _led._data["accounts"]

    # ── FU-332 — no docstring claims a post-quantum operation this repository cannot perform ───
    #  Asserted on the CLAIM, not the phrase: the file legitimately says the wallets are NOT
    #  PQC-secured, and a substring check on "PQC-secured" fired on that denial.
    _cg = (_root / "products/capital_fund/adapters/crypto_gateway.py").read_text(encoding="utf-8")
    _docs = " ".join(_ast575.get_docstring(n) or ""
                     for n in _ast575.walk(_ast575.parse(_cg))
                     if isinstance(n, (_ast575.Module, _ast575.ClassDef, _ast575.FunctionDef,
                                       _ast575.AsyncFunctionDef)))
    for _claim in ("Integrates PQC-secured", "with PQC signing", "using Dilithium"):
        assert _claim not in _docs, (
            f"a docstring claims {_claim!r} on a money path; no post-quantum operation exists in "
            f"this repository", _claim)
    assert "KEYED MAC" in _docs.upper(), (
        "the docstrings no longer name the operation actually performed")
    #  and there is still no post-quantum module to perform one
    assert not (_root / "agentic_core/crypto/pqc.py").exists(), (
        "a pqc module now exists — if a post-quantum operation was built, these docstrings must "
        "say what it actually does rather than being left as they are")

    # ── FU-346 — the capital vault imports with no managed infrastructure configured ───────────
    import importlib as _il575
    _vault = _il575.import_module("products.capital_fund.core.vault")
    assert hasattr(_vault, "CapitalVault") and hasattr(_vault, "_db"), dir(_vault)
    _vsrc = (_root / "products/capital_fund/core/vault.py").read_text(encoding="utf-8")
    _code = "\n".join(l.split("#", 1)[0] for l in _vsrc.splitlines())
    assert "\ndb = firestore.client()" not in "\n" + _code, (
        "the Firestore client is acquired at MODULE SCOPE again, so importing this file depends on "
        "live managed infrastructure and no suite can reach it")
    #  and the lazy accessor REFUSES rather than initialising anything — P4.4 is the Owner's switch
    try:
        _vault._db()
    except RuntimeError as _e:
        assert "owner-gated" in str(_e) and "nothing here initialises it" in str(_e), str(_e)[:200]
    except Exception:                                    # noqa: BLE001
        raise AssertionError("_db() failed with something other than its stated refusal") from None

    # ── FU-276 — every gateway call site with a user in scope threads it ───────────────────────
    #  COMPUTED, not a hand-kept list: the 71 sites with no user in scope are deliberately
    #  unattributed, which is the bar's "recorded as deliberately unattributed with its reason",
    #  and this recomputes the classification so adding a user without threading it goes red.
    def _is_gateway_call(node):
        f = node.func
        if isinstance(f, _ast575.Name):
            return f.id == "ai_text"
        if isinstance(f, _ast575.Attribute):
            _owner = getattr(f.value, "id", None) or getattr(f.value, "attr", None)
            return f.attr in ("query_meta", "query", "stream_meta") and _owner == "gateway"
        return False

    _unthreaded, _total, _threaded, _nouser = [], 0, 0, 0

    def _walk(node, user_in_scope, path):
        nonlocal _total, _threaded, _nouser
        for ch in _ast575.iter_child_nodes(node):
            if isinstance(ch, (_ast575.FunctionDef, _ast575.AsyncFunctionDef)):
                _p = {a.arg for a in ch.args.args} | {a.arg for a in ch.args.kwonlyargs}
                _walk(ch, user_in_scope or bool(_p & {"user", "current_user", "owner_id", "uid"}), path)
                continue
            if isinstance(ch, _ast575.Call) and _is_gateway_call(ch):
                _total += 1
                if any(k.arg == "owner_id" for k in ch.keywords):
                    _threaded += 1
                elif user_in_scope:
                    _unthreaded.append(f"{path}:{ch.lineno}")
                else:
                    _nouser += 1
            _walk(ch, user_in_scope, path)

    for _p in sorted((_root / "agentic_core").rglob("*.py")):
        if "_archive" in _p.parts:
            continue
        try:
            _tree = _ast575.parse(_p.read_text(encoding="utf-8", errors="replace"))
        except SyntaxError:
            continue
        _walk(_tree, False, _p.relative_to(_root).as_posix())
    assert _total > 50, ("the call-site matcher found almost nothing, so this leg proves nothing",
                         _total)
    assert _threaded >= 20, ("the threaded count collapsed", _threaded)
    assert not _unthreaded, (
        "a gateway call site has a user in scope and does not thread owner_id, so what that person "
        "asked for is stored in a namespace even they cannot recall from", _unthreaded)

    # ── FU-077 — the ontology engine is retired, and the kept asset is not called a graph ──────
    assert not (_root / "agentic_core/reactor/domains/ontology_engine.py").exists(), (
        "the ontology engine is back; the Owner ruled on 2026-09-30 that it be retired")
    from agentic_core.reactor.domains.weaver import domain_weaver as _dw575
    import asyncio as _aio575
    _out = _aio575.get_event_loop_policy().new_event_loop().run_until_complete(
        _dw575.synthesize("unfair dismissal", ["law", "care"]))
    assert _out["status"] == "no_ontology_service", _out["status"]
    assert _out["structured_report"]["entries_found"] == 0
    #  ON THE FIELD A READER MEETS. `synthesis` is what travels into the AI CEO's answer; a
    #  structured `kept_asset` key was returned here too and removed in the same round because the
    #  pre-flight found it reaching no surface. Asserting the dead key would have guarded nothing.
    assert "494-concept" in _out["synthesis"], (
        "the surface no longer says what IS kept — 'retire the engine, KEEP THE ASSET, reclassify it "
        "honestly' is one ruling, and the second half is the half that rots", _out["synthesis"][:200])
    assert "vocabulary is not a graph" in _out["synthesis"], _out["synthesis"][:200]
    #  THE RULING'S MEASUREMENT, RE-TAKEN — neither file is a graph, so neither may be served as one
    import json as _json575
    _law = _json575.loads((_root / "knowledge/Law/EmploymentTribunal/ontology/"
                           "uk_employment_law_v9.json").read_text(encoding="utf-8"))
    assert len(_law["concepts"]) == 494 and "relations" not in _law, (
        "the Law asset changed shape; it is kept as a VOCABULARY precisely because it has no "
        "relations, and if it gained some the ruling would need revisiting", sorted(_law))
    _uni = _json575.loads((_root / "knowledge/Law/EmploymentTribunal/ontology/"
                           "unified_assimilated_graph.json").read_text(encoding="utf-8"))
    assert "edges" not in _uni and len(_uni["nodes"]) == 293, sorted(_uni)
    assert "path" in _uni["nodes"][0], (
        "the 293 entries are FILE PATHS, which is why this is never loaded as an ontology")

    # ── FU-075 / FU-298 — AN ARTEFACT IS KEPT WITH READERS, OR REMOVED WITH NONE ───────────────
    #  W577 (FU-365) — this guard used to assert that the tolerant loader EXISTS and has at least
    #  eight readers. Both halves encoded the state of one particular round, so the guard went RED
    #  the moment a later round did the very thing the open row asked for. A guard must not fail on
    #  success. The durable property is the DISJUNCTION, which is what cluster (a) actually requires:
    #  an artefact that is kept states why and genuinely has readers; an artefact that is removed has
    #  no callers left. Whichever branch runs, the thing being checked is the same rule.
    _cfg = (_root / "agentic_core/config.py").read_text(encoding="utf-8")
    _tol = "load_json" + "_tolerant"          # built, so this line is not itself a caller to the scan

    def _calls_or_imports_577(src: str, name: str) -> bool:
        """A CALL or an IMPORT of `name` in real code — by AST, so a comment or a docstring that
        merely mentions it does not count, and an alias (`import x as y`) still does. A plain string
        scan got this wrong in both directions: it counted the prose explaining a removal, and it
        missed `_ljt(...)` entirely."""
        try:
            _t = _ast575.parse(src)
        except SyntaxError:
            return False
        _aliases = {name}
        for _n in _ast575.walk(_t):
            if isinstance(_n, _ast575.ImportFrom):
                for _a in _n.names:
                    if _a.name == name:
                        return True                      # importing it IS a reference
            if isinstance(_n, _ast575.Assign):
                for _tg in _n.targets:                   # `_ljt = load_json_tolerant`
                    if isinstance(_tg, _ast575.Name) and isinstance(_n.value, _ast575.Name)                             and _n.value.id in _aliases:
                        _aliases.add(_tg.id)
        for _n in _ast575.walk(_t):
            if isinstance(_n, _ast575.Call):
                _f = _n.func
                if isinstance(_f, _ast575.Name) and _f.id in _aliases:
                    return True
                if isinstance(_f, _ast575.Attribute) and _f.attr in _aliases:
                    return True
        return False

    _callers = {p.relative_to(_root).as_posix()
                for p in (_root / "agentic_core").rglob("*.py")
                if "_archive" not in p.parts
                and _calls_or_imports_577(p.read_text(encoding="utf-8", errors="replace"), _tol)}
    _callers.discard("agentic_core/config.py")
    if "def " + _tol in _cfg:
        _i = _cfg.index("def " + _tol)
        _doc = _cfg[_i:_i + 2600]
        assert "KEPT DELIBERATELY" in _doc, (
            "the retention decision is not stated in the function, so the next round sees only an "
            "open row asking for its deletion")
        assert "FU-298" in _doc, "the remaining half is not pointed at the item where it belongs"
        assert len(_callers) >= 8, (
            "the loader is kept for readers that no longer exist", sorted(_callers))
    else:
        #  REMOVED. The bar's clause (2) requires the reachability check that justified the removal
        #  to be recorded with it, and the only check that matters is that nothing calls it.
        assert not _callers, (
            "the tolerant loader was removed while these still call it", sorted(_callers))
        assert "FU-298" in _cfg and "REACHABILITY" in _cfg, (
            "the removal does not carry the reachability check that established it, which clause (2) "
            "of P2.18 requires of a fix that removes a code artefact")
        #  and the capability it existed for must still be there, or the removal was a regression:
        #  a corrupt cache must never take a live subsystem down.
        import agentic_core.config as _cfgmod577
        assert hasattr(_cfgmod577, "read_json_reported"), (
            "the tolerant READ was removed along with the wrapper, so a corrupt store can now take a "
            "live subsystem down - which is the behaviour the deleted function existed to prevent")
        _v577, _w577 = _cfgmod577.read_json_reported(_root / "does-not-exist-577.json", {"d": 1})
        assert _v577 == {"d": 1} and _w577 is None, (
            "an absent store must read as the caller's default with NO reason - a missing store is "
            "not an error", _v577, _w577)


def test_w583_p325_what_the_platform_records_when_it_fails(client, tmp_path):
    """P3.25 — the platform records its own failures, and an empty record is not health.

    MEASURED BEFORE BUILDING, and the item's premise still held at HEAD: app_mvp.py registered exactly ONE
    exception handler, for RequestValidationError, so an uncaught 500 left no record anywhere. The platform
    has 13 record_outcome call sites, a hash-chained UEG across 11 API modules and psutil vitals in 8 — it
    was not blind to itself; it had no error capture.

    THE BREAK-IT RULE IS THE WHOLE TEST. This does not read source to see whether a handler is registered:
    it BREAKS A REAL ROUTE, calls it, and reads the record back from the ledger and the chain. A guard that
    asserted the decorator exists would pass over a handler that recorded nothing.

    AND THE EMPTY CASE IS DRIVEN IN THREE STATES, because that is the clause the item turns on: "nothing
    recorded" must read as its own state rather than as health. No failures over a populated ledger is a
    statement about reliability; no failures over an EMPTY ledger is the absence of one, and a single green
    zero for both is the untruth this item was written against.
    """
    import pathlib as _pl583
    import re as _re583

    import agentic_core.api.operational_excellence as _oe583

    _root583 = _pl583.Path(__file__).resolve().parents[1]

    # ── L1. THE THREE STATES, DRIVEN IN ORDER ON A STORE THIS LEG CONTROLS ─────────────────────────
    #  the ledger is whatever this worker's store holds, so the states are driven by ADDING rows rather
    #  than by assuming an empty one: an empty-ledger assertion that depended on test order would be a
    #  guard that passes or fails on who ran first.
    _before583 = [r for r in _oe583._load() if r.get("kind") == "route_failure"]
    #  W583 — DRIVEN, not observed. The first cut asserted the empty-ledger basis only `if` the state
    #  happened to be the empty one, and after a single run this store is never empty — so the clause the
    #  item turns on was checked by luck and a blind that collapsed the two empty states passed. The route
    #  reads the ledger through `_load`, so the three states are driven by controlling exactly that.
    _load_orig583 = _oe583._load
    try:
        _oe583._load = lambda *_a, **_k: []
        _empty583 = client.get("/api/v1/operations/failures")
        assert _empty583.status_code == 200, _empty583.status_code
        _je583 = _empty583.json()
        assert _je583["state"] == "nothing_recorded_at_all", (
            "an EMPTY outcome ledger is not reported as its own state", _je583)
        assert "says nothing about reliability" in _je583["basis"], (
            "an EMPTY ledger does not say that it is NOT a reliability statement, which is the one thing "
            "this clause exists for - a green zero here and a green zero over a long clean history are "
            "opposite facts", _je583["basis"])

        _oe583._load = lambda *_a, **_k: [{"id": "x", "kind": "model_attempt", "resource": "ollama",
                                           "created_at": "2026-01-01T00:00:00Z", "success": True}]
        _clean583 = client.get("/api/v1/operations/failures").json()
        assert _clean583["state"] == "none_recorded", (
            "a populated ledger with no failures is not distinguished from an empty one", _clean583)
        assert "recording is working" in _clean583["basis"], (
            "no failures over a POPULATED ledger must say that recording WORKS - otherwise it reads the "
            "same as having recorded nothing at all", _clean583["basis"])
    finally:
        _oe583._load = _load_orig583
    assert _oe583._load is _load_orig583, "the ledger reader was left patched"

    # ── L2. BREAK A REAL ROUTE AND READ THE RECORD BACK ───────────────────────────────────────────
    _orig583 = _oe583.model_health

    def _boom583(*_a, **_k):
        raise RuntimeError("w583 induced failure, per the break-it rule")

    #  ITS OWN CLIENT, and the reason matters. The shared `client` fixture is built with
    #  raise_server_exceptions=True, which makes the TestClient RE-RAISE a handled exception instead of
    #  returning the response the handler produced — so the fixture cannot see a 500 at all, and this leg
    #  would report the induced error as its own failure. Same `app` singleton, so the same handler.
    from fastapi.testclient import TestClient as _TC583

    from agentic_core.app_mvp import app as _app583
    _c583 = _TC583(_app583, raise_server_exceptions=False)
    _oe583.model_health = _boom583
    try:
        _r583 = _c583.get("/api/v1/operations/model-health")
    finally:
        _oe583.model_health = _orig583

    assert _r583.status_code == 500, (
        "an unhandled exception on a real route did not answer 500 - the handler must RECORD the failure, "
        "never swallow it", _r583.status_code)
    _b583 = _r583.json()
    assert _b583.get("failure_class") == "RuntimeError", _b583
    assert _b583.get("route") == "/api/v1/operations/model-health", _b583
    #  AND IT CLAIMS NO CAUSE. A class name is not a diagnosis, and a record that guessed would be worse
    #  than none — this is the item's "never invents a cause it does not have".
    assert _b583.get("cause_established") is False, (
        "the response does not say the cause is unestablished, so a reader takes an exception CLASS for an "
        "explanation", _b583)

    _after583 = [r for r in _oe583._load() if r.get("kind") == "route_failure"]
    assert len(_after583) > len(_before583), (
        "the failure answered 500 and was NOT recorded in the outcome ledger, which is the whole item")
    _row583 = _after583[-1]
    assert _row583.get("resource") == "/api/v1/operations/model-health", _row583
    assert "RuntimeError" in str(_row583.get("ref") or ""), (
        "the record does not name the class of failure", _row583)
    assert str(_row583.get("created_at") or "").endswith("Z"), (
        "the record does not say WHEN", _row583)
    assert _row583.get("success") is False and _row583.get("produced") is False, (
        "a failure is recorded as a success, so every rate computed over these rows is wrong", _row583)

    # ── L3. THE SURFACE SHOWS IT, WITH ITS BASIS AND THE THREE STATES ─────────────────────────────
    _f1 = client.get("/api/v1/operations/failures").json()
    assert _f1["state"] == "failures_recorded", _f1["state"]
    assert _f1["total_failures"] >= 1
    _top583 = _f1["failures"][0]
    for _k583 in ("route", "method", "failure_class", "at", "basis"):
        assert _top583.get(_k583), ("the surface's row is missing a field a reader needs", _k583, _top583)
    assert _top583.get("cause_established") is False, _top583
    assert "NOT established" in _top583["basis"], (
        "the row's basis does not carry the refusal to claim a cause", _top583["basis"])

    _page583 = (_root583 / "apps/workstation-superapp/src/pages/OperationalExcellence.tsx").read_text(
        encoding="utf-8", errors="replace")
    _code583 = _re583.sub(r"(?m)^\s*//.*$", " ",
                         _re583.sub(r"/\*.*?\*/", " ", _page583, flags=_re583.S))
    #  the GATE with its opening brace (W503's class), and the three states rendered DIFFERENTLY
    assert "{failures && (" in _code583, "the page does not render the failures at all"
    #  W583 — THE GATE, with its opening brace. A blind proved the first cut vacuous: it asserted the
    #  LITERAL, and `{false && failures.state === 'nothing_recorded_at_all'` still contains it, so a
    #  disabled branch passed. W503's class.
    assert "{failures.state === 'nothing_recorded_at_all' ? (" in _code583, (
        "the page does not branch on the EMPTY-ledger state, so it shows the absence of any statement as "
        "health - the clause this item turns on")
    assert "failures.state === 'none_recorded' ? (" in _code583, (
        "the page does not render the clean-ledger state as its own thing")
    for _tid583 in ('data-testid="ops-failures-nothing-recorded"', 'data-testid="ops-failures-none"',
                    'data-testid="ops-failure-no-cause"'):
        assert _tid583 in _code583, ("a state has no rendered element", _tid583)

    # ── L4. THE UEG ENTRY VERIFIES IN THE CHAIN ───────────────────────────────────────────────────
    _v583 = client.get("/api/v1/gaas/ueg/verify")
    assert _v583.status_code == 200, _v583.status_code
    _vj583 = _v583.json()
    _ok583 = _vj583.get("valid")
    if _ok583 is None:
        _ok583 = _vj583.get("verified", _vj583.get("intact"))
    assert _ok583 is True, (
        "the UEG hash chain does not verify after a failure was logged into it - a tamper-evident record "
        "that does not verify is not a record", _vj583)

    # ── L5. requirements.txt IS NOT EDITED BY THIS ITEM ───────────────────────────────────────────
    #  The ruling's other half rested on a false premise (opentelemetry is Required-by chromadb, which is
    #  LIVE on the recall path; requirements.txt is a 298-line LOCK that lists transitive deps by design).
    #  The item says so and excludes it, and the manifest question is a separate row with its own
    #  measurement — so the pins must still be there.
    _req583 = (_root583 / "requirements.txt").read_text(encoding="utf-8", errors="replace")
    #  W583 — ANCHORED TO THE LINE START. `"opentelemetry-api" in text` is satisfied by
    #  `_opentelemetry-api`, so a renamed pin passed the first cut — a substring is not a declaration.
    for _pin583 in ("opentelemetry-api", "opentelemetry-sdk"):
        assert _re583.search(r"(?m)^" + _re583.escape(_pin583) + r"[=<>~\s]", _req583), (
            "a pin this item explicitly excludes was removed. `pip show` reports it Required-by chromadb, "
            "which agentic_core/ai/ceo/memory_v01.py imports on the cross-request recall path, and a lock "
            "lists transitive dependencies BY DESIGN - removing one breaks the install rather than tidying "
            "it", _pin583)


def test_w582_an_area_with_no_owner_is_retired_and_a_deliberation_names_its_real_cause(tmp_path):
    """W582 — the two halves the Owner approved: route an area by owner or retire it, and stop naming a
    cause measurement contradicts.

    THE ROUTING. `done <slot> --reroute` refused because routes still sent rows to the finishing item, and
    `--hand-to` takes exactly ONE destination — so the only way to close an item holding routes was to move
    every area to a single item. That is how P2.4 became a sink: nine of its eleven open rows arrived AFTER
    its bar was written, through routes handed in as earlier items closed, which is what the Owner's ruling
    of 2026-10-02 (route BY AREA) addressed. MEASURED for P2.18's seven routes with `route_row`'s own
    `exclude` set: ZERO found an open item claiming their area, because every original owner is closed. So
    handing them anywhere assigns an area to an item that does not own it. Retiring is the third option, and
    it is REFUSED where an open item does claim the area — otherwise it would orphan work somebody owns,
    which is worse than the sink it avoids.

    THE CAUSE. The deliberation that feeds clearance gate 1 derived status NOT ASSESSED and said the engines
    "refuse for want of a model path". MEASURED: ollama is reachable with three local models installed, and
    each engine's verdict is a HARDCODED `passed=None` whose own basis reads "this engine performs none". So
    no model changes that outcome, and a reader told otherwise waits for the wrong thing — which is exactly
    what FU-366's hold on the avatar path was doing.
    """
    import json as _json582
    import os as _os582
    import pathlib as _pl582
    import re as _re582
    import subprocess as _sp582
    import sys as _sys582

    from agentic_core import plan_followups as _fu582

    _root582 = _pl582.Path(__file__).resolve().parents[1]
    _prompt582 = _fu582.read_doc(_root582 / "docs" / "FABLE_DELIVERY_PROMPT.md")
    _living582 = _fu582.read_doc(_root582 / "docs" / "WORKSTATION_IDBO_LIVING_PLAN.md")
    _open582 = [i["slot"] for i in _fu582.plan_items(_prompt582) if not i["done"]]
    assert len(_open582) >= 2, ("this leg needs two open plan items to drive a claimed-vs-ownerless area",
                               _open582)
    _a582, _b582 = _open582[0], _open582[1]

    #  a scratch root, never the repository: this command MUTATES a register
    _scr582 = tmp_path / "w582root"
    (_scr582 / "docs").mkdir(parents=True)
    _empty582 = {"items": []}
    (_scr582 / "docs" / "FABLE_DELIVERY_PROMPT.md").write_bytes(
        _fu582.splice_all(_prompt582, _empty582, _prompt582).encode("utf-8"))
    (_scr582 / "docs" / "WORKSTATION_IDBO_LIVING_PLAN.md").write_bytes(
        _fu582.splice_all(_living582, _empty582, _prompt582).encode("utf-8"))
    (_scr582 / "docs" / "FOLLOWUPS.json").write_bytes(b'{"items": []}\n')
    _env582 = dict(_os582.environ, WORKSTATION_FOLLOWUPS_ROOT=str(_scr582), PYTHONIOENCODING="utf-8")
    _script582 = str((_root582 / "scripts" / "followups.py").resolve())

    def _cli582(*argv):
        return _sp582.run([_sys582.executable, _script582, *argv], env=_env582,
                          capture_output=True, text=True, encoding="utf-8")

    def _routes582():
        return (_json582.loads((_scr582 / "docs" / "FOLLOWUPS.json").read_text(encoding="utf-8"))
                .get("routes") or [])

    # ── L1. AN AREA NO OPEN ITEM CLAIMS IS RETIRED, and the retirement is PRINTED ───────────────────
    _lonely582 = "agentic_core/w582_nobody_claims_this/"
    assert _cli582("route", "--slot", _a582, "--files", _lonely582).returncode == 0
    assert any(r.get("slot") == _a582 for r in _routes582()), "the route was not created"
    _done582 = _cli582("done", _a582, "--retire-routes", "--by", "W582")
    assert _done582.returncode == 0, (
        "an item whose only route points at an area NO open item claims could not be finished, so the only "
        "way to close it remains handing that area to an item that does not own it",
        _done582.stdout, _done582.stderr)
    assert "RETIRED" in _done582.stdout, (
        "the retirement is not reported, so an area dropped from the routing table is forgotten rather "
        "than recorded", _done582.stdout)
    assert "UNSCHEDULED" in _done582.stdout, (
        "the report does not say what happens to a NEW row in that area, which is the whole consequence of "
        "retiring it", _done582.stdout)
    assert not any(r.get("slot") == _a582 for r in _routes582()), (
        "the route still points at a finished item, which the register's own check refuses")
    assert _cli582("check").returncode == 0, (
        "the register does not pass its own check after a retirement", _cli582("check").stdout)

    # ── L2. AN AREA ANOTHER OPEN ITEM CLAIMS IS NOT RETIRED ────────────────────────────────────────
    #  THE DANGEROUS DIRECTION. Retiring an owned area orphans work somebody still has, which is worse
    #  than the sink this option exists to avoid — so it must refuse and NAME the claimant.
    _scr2582 = tmp_path / "w582root2"
    (_scr2582 / "docs").mkdir(parents=True)
    for _f582 in ("FABLE_DELIVERY_PROMPT.md", "WORKSTATION_IDBO_LIVING_PLAN.md", "FOLLOWUPS.json"):
        (_scr2582 / "docs" / _f582).write_bytes((_scr582 / "docs" / _f582).read_bytes())
    _env582["WORKSTATION_FOLLOWUPS_ROOT"] = str(_scr2582)
    _shared582 = "agentic_core/w582_shared_area/"
    assert _cli582("route", "--slot", _b582, "--files", _shared582).returncode == 0
    _c582 = [s for s in _open582 if s not in (_a582, _b582)]
    assert _c582, "this leg needs a third open item"
    assert _cli582("route", "--slot", _c582[0], "--files", _shared582).returncode == 0
    _refused582 = _cli582("done", _c582[0], "--retire-routes", "--by", "W582")
    assert _refused582.returncode != 0, (
        "an area another open item CLAIMS was retired, orphaning work that item still owns",
        _refused582.stdout)
    assert "NOT ownerless" in (_refused582.stdout + _refused582.stderr), _refused582.stderr
    assert _b582 in (_refused582.stdout + _refused582.stderr), (
        "the refusal does not name the open item that claims the area, so a reader cannot act on it",
        _refused582.stderr)

    # ── L3. THE TWO OPTIONS CANNOT BE GIVEN TOGETHER ───────────────────────────────────────────────
    _both582 = _cli582("done", _c582[0], "--retire-routes", "--hand-to", _b582, "--by", "W582")
    assert _both582.returncode != 0 and "opposite things" in (_both582.stdout + _both582.stderr), (
        "--hand-to and --retire-routes were accepted together, so which happened to an area depends on "
        "the order of the code rather than on what the caller asked for", _both582.stderr)

    # ── L4. THE DELIBERATION NAMES ITS REAL CAUSE ──────────────────────────────────────────────────
    #  DRIVEN on the engine, then asserted on the derivation's wording. The engine's verdict is what the
    #  derived status reads, and it is a literal: that is the measurement.
    _aqal582 = (_root582 / "agentic_core/cognitive/aqal_engine.py").read_text(encoding="utf-8",
                                                                             errors="replace")
    #  REWRITTEN W604, as this leg said it must be: since P3.28 the engine PERFORMS a check (the gaas.v5
    #  screen), so the literal is gone and the cause the deliberation states has changed with it.
    _aqal582_code = "\n".join(l.split("#", 1)[0] for l in _aqal582.splitlines())
    assert "this engine performs none" not in _aqal582_code and "_constitutional_screen(" in _aqal582_code, (
        "the engine still states that it performs no constitutional check, or does not call the screen - the "
        "verdict the deliberation reads is a literal again")
    _delib582 = (_root582 / "agentic_core/consultation/mushawara/mushawara_bridge_2.py").read_text(
        encoding="utf-8", errors="replace")
    _code582 = "\n".join(l.split("#", 1)[0] for l in _delib582.splitlines())
    assert "refuse for want of a model path" not in _code582, (
        "the deliberation asserts that the perspectives refuse FOR WANT OF A MODEL PATH. Measured: three "
        "local models are installed and reachable, and the verdict is a hardcoded None whose own basis says "
        "the engine performs no check - so that cause is contradicted by measurement, and a hold waiting on "
        "a model path waits for something that cannot release it")
    assert "perform no " in _code582 and "constitutional check" in _code582, (
        "the deliberation does not say WHY it did not clear, so a reader is left to infer it")
    assert "released only by a check being implemented" in _code582, (
        "the reason does not say what WOULD release it, which is the part a round can act on")


def test_w581_p218c_a_promise_the_record_can_hold_and_a_variance_it_can_read_back(client):
    """P2.18 clause (c) — a promise this platform can record, against a capacity it measured.

    MEASURED BEFORE BUILDING, and the row's own W514 measurement held at HEAD: `/cca/submit` already
    returned a real method_check, scope_appraisal, health_gate and immune_threat_at_submit, and the change
    already reached `/cca/queue`. What did not exist was any commitment, confidence, variance, budget or
    capacity field anywhere on the record, the queue or the individual GET — and `committed_rounds` and
    `confidence` sent to /transformation/orchestrate were SILENTLY DROPPED, because Pydantic discards a
    field a model does not declare and the caller still receives a 200.

    THE INVARIANT IS PERMISSIVE HERE, AND THE DISTINCTION IS THE WHOLE DESIGN. CAPACITY_FACULTY_MODEL §2:
    "a probability about SELF is a measurement; a probability about ANOTHER'S CHOICE is a fabrication.
    That line is why `_prospect` is right to refuse and why the capacity figure is nonetheless
    admissible." So a commitment about this platform's own delivery may be recorded — but a number a
    CALLER hands over is not a measurement, so `confidence` is stored and rendered as DECLARED, it is
    refused without a basis, and the capacity beside it is measured from this repository's own history.
    """
    import json as _json581
    import pathlib as _pl581
    import re as _re581

    from fastapi import HTTPException as _HE581

    from agentic_core.api.change_control import (SubmitChangeRequest as _SCR581,
                                                 _load_change as _load581,
                                                 _record_variance as _rv581,
                                                 submit_change as _submit581)

    _root = _pl581.Path(__file__).resolve().parents[1]
    _aio581 = _ensure_loop()

    # ── L1. A FIGURE THIS PLATFORM CANNOT EXPLAIN IS REFUSED, NOT STORED ────────────────────────────
    for _bad581, _why581 in (
        ({"committed_rounds": 3}, "rounds with no basis"),
        ({"confidence": 0.9}, "a confidence with no basis"),
    ):
        try:
            _aio581.run_until_complete(_submit581(_SCR581(
                title="w581 unexplained", description="d", **_bad581)))
            raise AssertionError(
                f"an unexplained commitment was STORED ({_why581}). A number on a governance record is "
                f"read by a later round as a measurement, which is the defect this whole method removes")
        except _HE581 as _e581:
            assert _e581.status_code == 422, (_why581, _e581.status_code)
            assert "based on" in str(_e581.detail), (_why581, _e581.detail)
    #  and a confidence outside 0..1, or a promise of zero rounds, are refused too
    for _bad581 in ({"confidence": 1.4}, {"committed_rounds": 0}):
        try:
            _aio581.run_until_complete(_submit581(_SCR581(
                title="w581 out of range", description="d", commitment_basis="b", **_bad581)))
            raise AssertionError(f"an impossible commitment was stored: {_bad581}")
        except _HE581 as _e581:
            assert _e581.status_code == 422, (_bad581, _e581.status_code)

    # ── L2. A COMMITMENT IS RECORDED, THE CONFIDENCE IS LABELLED, THE CAPACITY IS MEASURED ─────────
    _out581 = _aio581.run_until_complete(_submit581(_SCR581(
        title="w581 a promise", description="d", committed_rounds=2, confidence=0.7,
        commitment_basis="two rounds at the measured pace; one file and one guard")))
    _cid581 = _out581["cca_id"]
    #  IT TRAVELS WITH THE SUBMISSION. A promise stored on a record and absent from the response is a
    #  fact rendered nowhere, which is the shape this method warns of and which the method_check already
    #  had to be fixed for.
    _c581 = _out581.get("commitment")
    assert isinstance(_c581, dict), (
        "submit_change does not return the commitment it just recorded, so the caller that made the "
        "promise cannot see what was kept of it", sorted(_out581))
    assert _c581.get("committed_rounds") == 2 and _c581.get("confidence") == 0.7, _c581
    assert _c581.get("confidence_is_declared") is True, (
        "a confidence a SUBMITTER stated is recorded without being marked declared, so a later reader "
        "takes it for a measurement this platform made - §2's line is the whole discipline here", _c581)
    #  the ATTRIBUTION, asserted where it now lives. It was a separate `confidence_basis` key and the
    #  pre-flight was right that it reached no surface: the page renders the WORD "declared" from the
    #  boolean above, so the long form is appended to the basis the chip's title already shows. One
    #  statement, one reader — rather than a second prose field nobody consumes.
    assert "not measured by this platform" in str(_c581.get("basis") or ""), (
        "the commitment's basis does not attribute the confidence to the SUBMITTER, so the one sentence a "
        "reviewer can hover for does not say who asserted the number", _c581.get("basis"))
    #  the capacity is MEASURED from this repo's own history, or says it was not
    _cap581 = _c581.get("capacity_at_submit")
    _capb581 = str(_c581.get("capacity_basis") or "")
    assert _cap581 is not None or "NOT MEASURED" in _capb581, (
        "the capacity is absent with no reason, so a reader cannot tell an unmeasured pace from a pace "
        "of zero", _c581)
    if _cap581 is not None:
        assert isinstance(_cap581.get("median_hours_per_round"), (int, float)), _cap581
        assert _cap581.get("rounds_measured"), (
            "a median with no sample size is not a measurement anybody can weigh", _cap581)
    #  and the variance is None WITH A REASON: "not yet" is not "nobody measured it"
    assert _out581.get("variance") is None
    assert "no outcome yet" in str(_out581.get("variance_basis") or ""), _out581.get("variance_basis")

    # ── L3. THE VARIANCE IS READ BACK, AND IT IS HONEST ABOUT ITS UNIT ──────────────────────────────
    _rec581 = _load581(_cid581)
    _rec581["submitted_at"] = "2026-10-01T00:00:00Z"          # force a gap, so the arithmetic is visible
    _rv581(_rec581, "2026-10-04T12:00:00Z", "implemented")
    _v581 = _rec581.get("variance")
    assert isinstance(_v581, dict), "no variance was recorded at the outcome"
    assert _v581.get("elapsed_hours") == 84.0, (
        "the elapsed time is not measured from the record's own stamps", _v581)
    assert _v581.get("committed_rounds") == 2
    assert _v581.get("within_commitment") is False and _v581.get("over_by_rounds") > 0, _v581
    #  A ROUND IS NOT A CLOCK UNIT. The rounds figure must say it is DERIVED and name what it divided by,
    #  or it is a count of rounds nobody counted - this repository's oldest rule about figures.
    _der581 = str(_v581.get("derivation") or "")
    assert "DERIVED" in _der581 and "not counted" in _der581.lower(), (
        "the rounds figure does not say it is derived", _der581)
    assert _re581.search(r"\d+(\.\d+)?\s*h median round length", _der581), (
        "the derivation does not NAME the median it divided by, so the figure cannot be checked", _der581)
    #  W581 — THE PROPERTY, ASSERTED WHERE IT NOW LIVES. The variance used to carry its own copy of the
    #  confidence and its label, and the pre-flight was right that neither reached a surface: the
    #  commitment block beside it holds them and the page renders the label. Two fields holding one fact
    #  is how they drift apart, so the duplicate went and the property is asserted on the survivor —
    #  measuring an outcome must not turn a stated figure into a measured one.
    _after581 = (_rec581.get("commitment") or {})
    assert _after581.get("confidence") == 0.7 and _after581.get("confidence_is_declared") is True, (
        "recording the outcome lost or unlabelled the DECLARED confidence, so a later reader takes a "
        "submitter's figure for one this platform measured", _after581)
    assert "confidence_declared" not in _v581 and "confidence_was_declared" not in _v581, (
        "the variance carries a second copy of the confidence again. It reached no surface and the "
        "commitment's own labelled field does, so a duplicate here can only drift from it", sorted(_v581))

    # ── L4. NO PROMISE MEANS NO VARIANCE, AND IT STAYS THAT WAY AFTER AN OUTCOME ────────────────────
    _out2581 = _aio581.run_until_complete(_submit581(_SCR581(title="w581 no promise", description="d")))
    assert _out2581.get("commitment") is None
    assert "no commitment was recorded" in str(_out2581.get("variance_basis") or "")
    _rec2581 = _load581(_out2581["cca_id"])
    _rv581(_rec2581, "2026-10-04T12:00:00Z", "implemented")
    assert _rec2581.get("variance") is None, (
        "a variance was invented for a change nothing was promised about", _rec2581.get("variance"))

    # ── L5. BOTH OUTCOME SITES RECORD IT — the second-writer class, asserted on the AST ─────────────
    import ast as _ast581
    _ccsrc581 = (_root / "agentic_core/api/change_control.py").read_text(encoding="utf-8",
                                                                        errors="replace")
    _tree581 = _ast581.parse(_ccsrc581)
    _implemented581, _recorded581 = [], []
    for _n581 in _ast581.walk(_tree581):
        if not isinstance(_n581, (_ast581.FunctionDef, _ast581.AsyncFunctionDef)):
            continue
        _seg581 = _ast581.get_source_segment(_ccsrc581, _n581) or ""
        _code581 = "\n".join(l.split("#", 1)[0] for l in _seg581.splitlines())
        #  a plain substring test, not a regex: the pattern needs both quote styles in one character
        #  class and every spelling of that regex here has fought the surrounding string's own quoting.
        #  Two literals, both spellings, no escaping to get wrong.
        if ('["status"] = "implemented"' in _code581
                or "['status'] = 'implemented'" in _code581):
            _implemented581.append(_n581.name)
            if "_record_variance(" in _code581:
                _recorded581.append(_n581.name)
    assert len(_implemented581) >= 2, (
        "this leg found fewer than the two known places that mark a change implemented, so it is not "
        "checking what it was written to check", _implemented581)
    assert set(_implemented581) == set(_recorded581), (
        "a function marks a change IMPLEMENTED and does not record its variance. One site fixed and its "
        "sibling missed is this repository's second-writer class",
        sorted(set(_implemented581) - set(_recorded581)))

    # ── L6. THE QUEUE CARRIES IT, AND THE PAGE RENDERS IT ──────────────────────────────────────────
    _q581 = client.get("/api/v1/cca/queue")
    assert _q581.status_code == 200, _q581.status_code
    _rows581 = _q581.json()
    #  the route answers {"queue": [...], "total": n} — read from the response rather than guessing, and
    #  fail loudly if the shape changes rather than silently finding no rows to check
    if isinstance(_rows581, dict):
        assert "queue" in _rows581, (
            "the queue route's shape changed, so this leg would find no rows and pass by examining "
            "nothing", sorted(_rows581))
        _rows581 = _rows581["queue"]
    assert isinstance(_rows581, list) and _rows581, "the queue returned no rows to check"
    _mine581 = [r for r in _rows581 if r.get("cca_id") == _cid581]
    assert _mine581, ("the change this leg submitted is not in the queue the growing tip reads", _cid581)
    for _k581 in ("commitment", "variance", "variance_basis"):
        assert _k581 in _mine581[0], (
            "the queue drops the promise, so it is invisible while the work is IN FLIGHT - which is the "
            "whole reason for recording one", _k581, sorted(_mine581[0]))
    assert (_mine581[0].get("commitment") or {}).get("committed_rounds") == 2, _mine581[0]

    # ── L7. ORCHESTRATE NO LONGER DROPS WHAT A CALLER PROMISED ──────────────────────────────────────
    #  The row's ORIGINAL measurement was here: `committed_rounds` and `confidence` were sent to
    #  /transformation/orchestrate and SILENTLY DISCARDED, because Pydantic drops a field a model does not
    #  declare and the caller still receives a 200. A blind proved the legs above never touched this
    #  route — they drive submit_change directly — so reverting the declaration left them all green.
    #  Asserted on the MODEL's binding rather than its source text: an undeclared field has no attribute.
    from agentic_core.api.transformation_orchestration import OrchestrateRequest as _OR581
    _req581 = _OR581(objective="w581", committed_rounds=3, confidence=0.5,
                     commitment_basis="driven by the guard")
    for _f581, _want581 in (("committed_rounds", 3), ("confidence", 0.5)):
        assert getattr(_req581, _f581, None) == _want581, (
            "the orchestrate request DISCARDS what a caller promised: an undeclared field is dropped and "
            "the caller still gets a 200, so a transformation can be promised in a number of rounds at a "
            "stated confidence with nothing anywhere holding the promise", _f581)
    #  and the promise must be THREADED to the change the orchestration files, or it is declared and then
    #  thrown away one line later — asserted on the call's own keywords.
    _tosrc581 = (_root / "agentic_core/api/transformation_orchestration.py").read_text(
        encoding="utf-8", errors="replace")
    _totree581 = _ast581.parse(_tosrc581)          # _ast581 is imported by L5 above
    _threaded581 = False
    for _n581b in _ast581.walk(_totree581):
        if not isinstance(_n581b, _ast581.Call):
            continue
        _fn581b = getattr(_n581b.func, "id", None) or getattr(_n581b.func, "attr", None)
        if _fn581b != "SubmitChangeRequest":
            continue
        _kw581 = {k.arg for k in _n581b.keywords}
        if {"committed_rounds", "confidence"} <= _kw581:
            _threaded581 = True
    assert _threaded581, (
        "orchestrate declares the commitment fields and does not pass them to the change it files, so "
        "they are accepted and discarded one layer further down")

    #  the page, with comments stripped, asserted on the GATE and its opening brace
    _page581 = (_root / "apps/workstation-superapp/src/pages/enterprise/ChangeControlAgency.tsx").read_text(
        encoding="utf-8", errors="replace")
    _pcode581 = _re581.sub(r"(?m)^\s*//.*$", " ",
                          _re581.sub(r"/\*.*?\*/", " ", _page581, flags=_re581.S))
    assert "{entry.commitment && (" in _pcode581, (
        "the promise reaches the queue and not the page a reviewer reads, which moves the untruth down a "
        "layer rather than removing it - clause (1) of this item's ACCEPT")
    assert "{entry.variance != null && (" in _pcode581, "the variance reaches no page"
    assert 'data-testid="cca-commitment"' in _pcode581 and 'data-testid="cca-variance"' in _pcode581
    #  AND THE DECLARED LABEL IS ON SCREEN. A reviewer looking at 0.7 on a card has no other way to know
    #  whether this platform measured it.
    assert "confidence_is_declared ?" in _pcode581, (
        "the page renders a confidence without saying whether it was DECLARED or measured, so §2's line "
        "holds in the record and is lost on the surface")


def test_w580_every_screen_is_driven_by_the_method_that_found_the_distress_miss(client):
    """P2.18 — the method that found two real defects in the distress gate, applied to every other screen.

    W564 and a refuter found two faults in the DISTRESS screen, both in a slot nobody had driven: a
    determiner group that made "my" and "own" one optional unit, so it missed "end my life" — the plainest
    phrasing of its subject — and a verb list of bare literals followed by whitespace, so it missed every
    PROGRESSIVE ("ending my life", "killing myself"), which is the commonest form a person writes. Neither
    was indirect or a paraphrase, so the declared coverage did not excuse them: they were DEFECTS.

    No other screen on this platform had been driven that way. THE DRIVEN LIST is scripts/screen_phrasings.py
    and it is the deliverable rather than a probe: 61 phrasings over four screens, each labelled for/not-for
    BEFORE the result was known, so the pattern cannot decide what it was written for. Measured first:
    28 missed. After widening: 2, and both are the prose cases the intent screen now DECLARES it does not
    read — which is the row's other permitted outcome and is only honest if the declaration reaches a
    caller, so that is asserted too.

    AND THE WIDENING COMMITTED THE DISTRESS SCREEN'S OWN BUG, IN THE FILE THAT WARNS ABOUT IT. The first
    cut DERIVED the verb inflections with `(?:e[sd]?|ing|es)?`, which has no bare `s`, so "research
    CONFIRMS the Quran" was missed by the pattern written to catch it. Caught by RE-DRIVING the list after
    the fix, not by reading the regex, which is the only reason this guard can state it.
    """
    import importlib.util as _ilu580
    import pathlib as _pl580

    _root = _pl580.Path(__file__).resolve().parents[1]
    _spec = _ilu580.spec_from_file_location("_sp580", _root / "scripts/screen_phrasings.py")
    _sp = _ilu580.module_from_spec(_spec)
    _spec.loader.exec_module(_sp)

    from agentic_core.gaas.v5 import horizon_guardrails as _hg580
    from agentic_core.gaas.v5.policy_gate import ConstitutionalPolicyGate as _PG580

    _gate580 = _PG580()
    #  the four screens, driven through the SAME entry points the platform uses
    _screens580 = (
        ("religious_ruling_gate", _sp.RULING,
         lambda t: _hg580.religious_ruling_gate(t).get("matched") is True),
        ("theological_proof_gate", _sp.PROOF,
         lambda t: _hg580.theological_proof_gate(t).get("matched") is True),
        ("policy_gate intents", _sp.INTENTS,
         lambda t: not _gate580.validate(t, {}).get("allowed", True)),
        ("policy_gate output", _sp.UNSAFE_OUTPUT,
         lambda t: not _gate580.validate_output(t).get("compliant", True)),
    )

    #  ── THE STATED LIMITS, named here so they cannot quietly grow ───────────────────────────────────
    #  A phrasing is allowed to be missed ONLY by being in this set, and this set is prose intent — the
    #  one case the intent screen declares it does not read. Anything else missing is a defect.
    _DECLARED_LIMIT580 = {"turn off the constitution", "transfer funds to an external account"}

    _defects580, _noise580, _driven580 = [], [], 0
    for _name580, _rows580, _fn580 in _screens580:
        for _text580, _intent580 in _rows580:
            _driven580 += 1
            _flagged580 = _fn580(_text580)
            if _intent580 == "for" and not _flagged580:
                if _text580 not in _DECLARED_LIMIT580:
                    _defects580.append(f"{_name580}: {_text580!r}")
            elif _intent580 == "not-for" and _flagged580:
                _noise580.append(f"{_name580}: {_text580!r}")
    #  W580 — the bound is the list's ACTUAL size, and per screen as well as in total. A blind proved why:
    #  a loose floor (>= 55 against 61 rows) let a phrasing be commented out with the guard still green,
    #  and a phrasing removed from this list is a phrasing nobody screens again. `>=` so the list may
    #  GROW — pinning an exact total would go red on a later round adding a phrasing, which is the
    #  fails-on-success class.
    assert _driven580 >= 61, (
        "the driven list shrank, so this guard is asserting less than the round that wrote it did - a "
        "phrasing removed from the list is a phrasing nobody screens again", _driven580)
    for _nm580, _rows580b, _min580 in (("RULING", _sp.RULING, 18), ("PROOF", _sp.PROOF, 16),
                                       ("INTENTS", _sp.INTENTS, 16),
                                       ("UNSAFE_OUTPUT", _sp.UNSAFE_OUTPUT, 11)):
        assert len(_rows580b) >= _min580, (
            "one screen's phrasings were trimmed, which a total alone can hide by another screen growing",
            _nm580, len(_rows580b), _min580)
    assert not _defects580, (
        "a screen misses a phrasing it was WRITTEN FOR, and the label saying so was written before the "
        "result was known", _defects580)
    assert not _noise580, (
        "a screen flagged a phrasing it is NOT for. That costs a withheld answer on a legitimate "
        "question, and on these screens the cost of noise is a person being refused", _noise580)

    #  ── THE INFLECTION LESSON, asserted on the phrasings that exposed it ────────────────────────────
    for _t580 in ("research confirms the Quran", "physics confirms the creator",
                  "studies show that God exists", "science validates the Quran"):
        assert _hg580.theological_proof_gate(_t580).get("matched") is True, (
            "a proof claim in the PRESENT TENSE is missed, which is the derived-suffix bug this file's "
            "own distress comment records: the inflections are spelled out, never derived", _t580)

    #  ── THE NORMALISER IS USED, not merely defined ──────────────────────────────────────────────────
    for _lbl580 in ("delete all records", "Delete-All-Records", "delete_all_records", "DELETE ALL"):
        _v580 = _gate580.validate(_lbl580, {})
        assert _v580.get("allowed") is False, (
            "an intent is prohibited in snake_case and allowed with spaces, so the gate screens a "
            "SPELLING rather than an act", _lbl580, _v580)
        assert _lbl580 in str(_v580.get("reason", "")), (
            "the refusal does not name the label the caller actually sent, so they cannot recognise what "
            "was refused", _lbl580, _v580.get("reason"))

    #  ── AND A PASS SAYS WHAT IT DID NOT SCREEN ──────────────────────────────────────────────────────
    #  the declared limit is only honest if it reaches the caller: otherwise `allowed: True` reads as a
    #  clearance of an act this screen never looked at.
    _ok580 = _gate580.validate("export_my_own_data", {})
    assert _ok580.get("allowed") is True, _ok580
    assert _ok580.get("screened") == "intent_label", (
        "a pass does not say WHAT was screened", _ok580)
    _limit580 = str(_ok580.get("coverage_limit") or "")
    assert "prose" in _limit580.lower() and "never that the action was understood" in _limit580, (
        "a pass does not carry the coverage limit, so the two phrasings this round left unscreened are an "
        "excuse rather than a declaration a caller can act on", _ok580)
    #  and the limit must be TRUE of this screen: the prose cases really are the ones it does not read
    for _prose580 in sorted(_DECLARED_LIMIT580):
        assert _gate580.validate(_prose580, {}).get("allowed") is True, (
            "a phrasing recorded as OUTSIDE this screen's coverage is in fact screened by it, so the "
            "declared limit understates what the screen does and the next round will widen the wrong "
            "thing", _prose580)
    #  W580 — AND EVERY DECLARED LIMIT MUST BELONG TO THE SCREEN THAT DECLARED ONE. A blind added two
    #  RULING phrasings to the limit set and stayed green, because the leg above checked them against the
    #  INTENT gate, which of course allows them — so a real defect on another screen could be excused by
    #  moving it into this set. A round that cannot widen a pattern can always widen the EXCUSE, and that
    #  is the direction worth guarding: only the intent screen declares a prose limit, so only its own
    #  phrasings may sit here.
    _intent_texts580 = {t for t, _ in _sp.INTENTS}
    _stray580 = sorted(_DECLARED_LIMIT580 - _intent_texts580)
    assert not _stray580, (
        "a phrasing from a screen that declares NO coverage limit was recorded as outside coverage. The "
        "only declared limit on this platform is the intent gate's prose limit; a miss anywhere else is a "
        "defect and cannot be reclassified into it", _stray580)


def test_w579_p218b_the_split_is_gone_and_a_page_is_actually_rendered(client):
    """P2.18 clause (b) — the suite's instruments prove what they claim.

    THE SPLIT (FU-359). A reload of agentic_core/organism/heartbeat.py re-runs
    `heartbeat = OrganismHeartbeat()` and rebinds the module attribute. agentic_core/api/heartbeat.py
    used to bind the attribute's VALUE at import, so from that point the routes held one heartbeat and
    the module pointed at another: a guard that wrote a flag on the module object and read it back
    through a route configured one and asserted about the other. MEASURED before the fix - the two
    references differed after a reload and a flag set on the module reported False through /status -
    and the remedy is not a guard but the one import: the routes resolve `.heartbeat` from the module
    per call now, which is what a singleton means. Three separate diagnoses had ended at that split.

    THE RUNNER (FU-352). Every page assertion in this file is a TEXT SCAN. A scan is not worthless -
    one caught the `{false && ...}` class, where a render was switched off while its field name
    survived in the source - but it cannot show that a person looking at the page sees anything. There
    is a rendered test now, and it earned its place immediately: its first draft failed and the failure
    showed that the insights list rendered an insight's TITLE and never its DETAIL, so the clause W576
    put inside `insights` to refuse the "you have no projects" reading reached nobody.

    THIS GUARD DOES NOT EXECUTE THE RUNNER, and that is deliberate rather than an omission: nothing in
    this suite shells out to node, and requiring it would add an environment assumption CI does not
    carry - the same class as a test reading os.environ for a store path. The ROUND runs `npm test`,
    exactly as it runs `tsc`, and this asserts the configuration the round depends on is intact.
    """
    import ast as _ast579
    import importlib as _il579
    import json as _json579
    import pathlib as _pl579
    import re as _re579

    _root = _pl579.Path(__file__).resolve().parents[1]
    _app = _root / "apps" / "workstation-superapp"

    # ── L1. FU-359 — THE API MODULE HOLDS NO SINGLETON OF ITS OWN, asserted on the BINDING ──────────
    _src579 = (_root / "agentic_core/api/heartbeat.py").read_text(encoding="utf-8", errors="replace")
    _tree579 = _ast579.parse(_src579)
    _bad579 = [n.lineno for n in _tree579.body
               if isinstance(n, _ast579.ImportFrom)
               and n.module == "agentic_core.organism.heartbeat"
               and any(a.name == "heartbeat" for a in n.names)]
    assert not _bad579, (
        "agentic_core/api/heartbeat.py binds the heartbeat OBJECT at import again, so a reload of the "
        "organism module leaves these routes on a stale heartbeat and a guard that writes a flag on the "
        "module cannot read it back through a route", _bad579)
    #  imported through importlib ON PURPOSE: an `import ... as` here would match L3's own needle below
    #  and this guard would accuse itself, which is the trap this file has hit three times
    _hbapi579 = _il579.import_module("agentic_core.api." + "heartbeat")
    assert not hasattr(_hbapi579, "heartbeat"), (
        "the api module has a module-level `heartbeat` again - whatever binds it, that name is a SECOND "
        "reference and the split returns with it")

    # ── L2. AND THE ROUTE FOLLOWS THE MODULE ACROSS A RELOAD, which is the whole property ───────────
    import agentic_core.organism.heartbeat as _hbmod579

    def _route_flag579():
        _r = client.get("/api/v1/heartbeat/status")
        assert _r.status_code == 200, _r.status_code
        return _r.json().get("auto_compliance")

    _was579 = getattr(_hbmod579.heartbeat, "auto_compliance", False)
    try:
        _hbmod579.heartbeat.configure(auto_compliance=True)
        assert _route_flag579() is True, (
            "the route does not see a write to the module object even WITHOUT a reload, so these two "
            "were already different objects")
        _hbmod579.heartbeat.configure(auto_compliance=False)
        _id_before579 = id(_hbmod579.heartbeat)
        _il579.reload(_hbmod579)
        assert id(_hbmod579.heartbeat) != _id_before579, (
            "the reload did not rebind the module attribute, so this leg cannot detect the split it "
            "exists to detect - it would pass whatever the api module did")
        _hbmod579.heartbeat.configure(auto_compliance=True)
        assert _route_flag579() is True, (
            "AFTER A RELOAD the route no longer sees a write to the module object: the routes are "
            "holding a heartbeat the module has replaced, which is the defect FU-359 names and the one "
            "that cost three separate diagnoses")
    finally:
        try:
            _hbmod579.heartbeat.configure(auto_compliance=bool(_was579))
        except Exception:
            pass

    # ── L3. AND NO GUARD IN THIS FILE REACHES FOR A SECOND REFERENCE ────────────────────────────────
    #  the name is built, so this assertion is not itself a match for the thing it forbids
    _forbidden579 = "api.heartbeat" + " as "
    _suite579 = _pl579.Path(__file__).read_text(encoding="utf-8", errors="replace")
    _lines579 = [i for i, l in enumerate(_suite579.splitlines(), 1)
                 if _forbidden579 in l and not l.strip().startswith("#")]
    assert not _lines579, (
        "a guard imports the api module to take a heartbeat reference from it. That was the remedy for a "
        "split that no longer exists, and the name it reaches for is gone", _lines579)

    # ── L4. FU-352 — THE RUNNER IS CONFIGURED, AND WHAT IT RUNS ACTUALLY RENDERS ────────────────────
    _pkg579 = _json579.loads((_app / "package.json").read_text(encoding="utf-8", errors="replace"))
    for _dep579 in ("vitest", "jsdom", "@testing-library/react", "@testing-library/jest-dom"):
        assert _dep579 in _pkg579.get("devDependencies", {}), (
            "the frontend test runner is not declared, so a fresh checkout cannot run the rendered "
            "tests and they would be skipped rather than failing", _dep579)
    assert _pkg579.get("scripts", {}).get("test"), (
        "there is no `npm test`, so the runner exists and the round has no command to run it with")
    #  vitest is pinned to the line this app's vite supports, and the reason is recorded in the config
    assert _pkg579["devDependencies"]["vitest"].startswith("^2"), (
        "vitest is no longer on the 2.x line. 5.x requires vite ^6 and this app is on vite 5, so an "
        "upgrade here silently drags the BUILD along with it - if that is intended, the vite bump is the "
        "change under review, not a side effect of a test runner",
        _pkg579["devDependencies"]["vitest"])
    _vcfg579 = (_app / "vite.config.js").read_text(encoding="utf-8", errors="replace")
    _vcode579 = _re579.sub(r"//[^\n]*", " ", _re579.sub(r"/\*.*?\*/", " ", _vcfg579, flags=_re579.S))
    assert "environment: 'jsdom'" in _vcode579, (
        "the runner has no DOM, so a 'rendered' test cannot render - comments stripped, because the "
        "explanation of the setting is not the setting")
    assert "vitest.setup.ts" in _vcode579 and (_app / "vitest.setup.ts").exists(), (
        "the setup file is not wired, so cleanup between tests does not run and one test's DOM can "
        "satisfy the next one's assertion")

    #  and a rendered test exists that genuinely MOUNTS a component — not another text scan with a new
    #  extension. Asserted on the AST of the test file: a render() call and a screen query.
    _tests579 = sorted(_app.glob("src/**/*.test.tsx"))
    assert _tests579, "no rendered test exists, so the runner has nothing to prove"
    _mounts579 = [t for t in _tests579
                  if "render(" in t.read_text(encoding="utf-8", errors="replace")
                  and "screen." in t.read_text(encoding="utf-8", errors="replace")]
    assert _mounts579, (
        "every test the runner collects asserts without mounting anything, which is the text scan this "
        "row exists to replace", [t.name for t in _tests579])
    #  the subject is FU-323's crash path, and the test must refuse the reading that row was about
    _kh579 = next((t for t in _mounts579 if t.name == "KnowledgeHub.test.tsx"), None)
    assert _kh579 is not None, "the rendered test for the insights crash path is gone"
    _khsrc579 = _kh579.read_text(encoding="utf-8", errors="replace")
    assert "insight-detail" in _khsrc579 and "no projects" in _khsrc579, (
        "the rendered test no longer drives the clause that refuses the 'you have no projects' reading, "
        "which is the one thing a text scan could not check")

    #  AND THE RENDER ITSELF, ASSERTED HERE TOO — because the rendered test is the only thing that
    #  proves it and THIS SUITE DOES NOT RUN THE RENDERED TEST. A blind proved that gap: switching the
    #  render off left every leg above green. So the two instruments sit side by side, which is the whole
    #  argument of the migration row: a scan asks whether the code says it, a render asks whether a
    #  person sees it, and the gate's OPENING BRACE is what a disabling prefix displaces (W503's class).
    _khpage579 = (_app / "src/pages/coe/KnowledgeHub.tsx").read_text(encoding="utf-8", errors="replace")
    _khcode579 = _re579.sub(r"(?m)^\\s*//.*$", " ",
                            _re579.sub(r"/\\*.*?\\*/", " ", _khpage579, flags=_re579.S))
    assert "{insight.detail && (" in _khcode579, (
        "the insights list no longer renders an insight's DETAIL. W576 moved a failed computation into "
        "`insights` so no consumer could ignore it and put the clause refusing the 'you have no "
        "projects' reading in `detail` - with the title alone on screen, that clause reaches nobody. "
        "Two rounds of text scans missed this because `insight.detail` appears in the source either way")


def test_w578_p218_the_third_surface_the_plan_pin_screen_and_a_rendered_meaning(client):
    """P2.18 — two instruments taught to see what they were blind to, and one qualifier reaching a page.

    THE THIRD SURFACE (FU-396). The key screen counted a page and a printed line. A key produced by a
    route NO PAGE FETCHES reaches a reader through that route's own JSON, and the screen called that no
    surface at all - nine times in one round, every one of them a true statement about where no page is
    and a false conclusion about whether anybody can read the key. It must also STAY SILENT where a page
    does fetch the route, because a key unread by a page that exists is the real defect.

    THE PLAN PIN (FU-365). An assertion pinned to today's plan state goes red when the plan ADVANCES,
    after the full suite. A sweep does not find these - W577 ran one and all four candidates were false
    positives - so the screen looks at a round's OWN added lines, and the four exempt shapes below are
    those measured false positives rather than caution.

    AND A QUALIFIER THAT REACHED NOBODY (FU-394), plus two fields the page declared that the route has
    never sent, which is the class W489 fixed in this same file when it found three others.
    """
    import ast as _ast578
    import importlib.util as _ilu578
    import json as _json578
    import pathlib as _pl578
    import re as _re578

    _root = _pl578.Path(__file__).resolve().parents[1]
    _spec = _ilu578.spec_from_file_location("_sd578", _root / "scripts/selfcheck_diff.py")
    _sd = _ilu578.module_from_spec(_spec)
    _spec.loader.exec_module(_sd)

    # ── L1. FU-396 — THE STATIC RESOLUTION IS EXACT, proven against the app's own route table ───────
    #  The screen composes mount + router prefix + decorator path rather than importing the app, because
    #  it runs before every commit and must mutate nothing. That trade is only safe if the composition
    #  AGREES with the framework, so it is checked here, where the app is already built.
    from agentic_core.app_mvp import app as _app578
    _real578 = set()
    for _r578 in _app578.routes:
        _p578 = getattr(_r578, "path", None)
        _ep578 = getattr(_r578, "endpoint", None)
        if _p578 and _ep578 is not None and getattr(_ep578, "__module__", "").startswith("agentic_core.api"):
            _real578.add((_ep578.__module__, _ep578.__name__, _p578))
    assert len(_real578) >= 150, ("the route table is far smaller than this repo's route count, so this "
                                 "leg is not comparing against the real thing", len(_real578))
    _checked578 = _wrong578 = 0
    for _mod578, _fn578, _path578 in sorted(_real578):
        _rel578 = _mod578.replace(".", "/") + ".py"
        _f578 = _root / _rel578
        if not _f578.exists():
            continue
        try:
            _t578 = _ast578.parse(_f578.read_text(encoding="utf-8", errors="replace"))
        except SyntaxError:
            continue
        _node578 = next((n for n in _ast578.walk(_t578)
                         if isinstance(n, (_ast578.FunctionDef, _ast578.AsyncFunctionDef))
                         and n.name == _fn578), None)
        if _node578 is None or not _node578.decorator_list:
            continue
        _got578 = _sd._route_of(_rel578, _node578.lineno + 1)
        if _got578 is None:
            continue
        _checked578 += 1
        if _got578 != _path578:
            _wrong578 += 1
    assert _checked578 >= 100, (
        "the resolver answered for too few real routes for this comparison to mean anything - it may be "
        "returning None rather than agreeing", _checked578)
    #  a handful of routes are mounted twice or declared on a sub-router this static pass does not model;
    #  the property is that the composition is right for the overwhelming majority, not that it is a
    #  reimplementation of FastAPI. A ratio is asserted, and the ratio is stated rather than assumed.
    assert _wrong578 / _checked578 < 0.08, (
        f"the static route composition disagrees with the app's own table on {_wrong578} of "
        f"{_checked578} routes, so the screen would name the wrong route to a reader")

    # ── L2. FU-396 — IT FINDS A PAGE-LESS ROUTE, AND STAYS SILENT WHERE A PAGE EXISTS ───────────────
    def _line_of(rel, needle):
        _src = (_root / rel).read_text(encoding="utf-8", errors="replace").splitlines()
        return next((i for i, l in enumerate(_src, 1) if needle in l), None)

    for _rel578, _key578, _want578 in (
        ("agentic_core/api/v310/governance.py", '"figures_are_incomplete"', "/api/v310/governance/treasury"),
        ("agentic_core/api/swarm.py", '"listing_is_incomplete"', "/api/v1/swarm/catalogue/proposed"),
        ("agentic_core/api/integration_surface.py", '"total_is_incomplete"', "/api/v210/federation/twins"),
    ):
        _ln578 = _line_of(_rel578, _key578)
        assert _ln578, (_rel578, _key578)
        assert _sd._route_response_surface(_rel578, _key578.strip('"'), _ln578) == _want578, (
            "the screen cannot see that this route's own response is the surface a person reads, so it "
            "reports a key that DOES reach a reader as reaching none", _rel578, _key578)
    #  and the discrimination, which is the whole safety of this kind: a page DOES fetch these two, so
    #  the response must NOT be offered as the surface - a key a real page fails to render is the defect.
    for _rel578, _key578 in (("agentic_core/api/user_workspace.py", "count_is_incomplete"),
                             ("agentic_core/api/products.py", "score_meaning"),
                             ("agentic_core/api/resource_fabric.py", "listing_is_incomplete")):
        _ln578 = _line_of(_rel578, '"' + _key578 + '"')
        assert _ln578, (_rel578, _key578)
        assert _sd._route_response_surface(_rel578, _key578, _ln578) is None, (
            "a PAGE fetches this route, so its response must not be accepted as the surface - otherwise "
            "the screen CLEARS a key that the page which exists never renders", _rel578, _key578)

    #  AND THE HELPER IS WIRED INTO THE SCREEN. The two legs above drive `_route_response_surface`
    #  directly, so removing its CALL from check_keys would leave them both green — a guard that proves a
    #  function works and not that anything uses it. Driven through check_keys itself.
    _orig_ar578 = _sd.added_removed
    try:
        #  the REAL line number, because the screen resolves the route from the line's enclosing
        #  handler — feeding line 1 puts the key outside every handler and the helper correctly
        #  answers None, which would make this leg prove nothing about the wiring
        _gln578 = _line_of("agentic_core/api/v310/governance.py", '"figures_are_incomplete"')
        assert _gln578, "the key this leg drives is no longer in that file"
        _sd.added_removed = lambda rev, path, _n=_gln578: (
            [(_n, '            "figures_are_incomplete": bool(x),')], [])
        _out578 = _sd.check_keys("HEAD", ["agentic_core/api/v310/governance.py"])
        assert any("NO PAGE IN THIS APP FETCHES" in o for o in _out578), (
            "the key screen does not USE the third surface kind, so a key on a page-less route still "
            "reports as reaching no surface at all", _out578)
        assert any("/api/v310/governance/treasury" in o for o in _out578), (
            "the finding does not name the route whose response is the surface, so a reader cannot check "
            "it", _out578)
    finally:
        _sd.added_removed = _orig_ar578

    # ── L3. FU-365 — EVERY FLAG FIRES AND EVERY EXEMPTION STAYS SILENT ──────────────────────────────
    #  driven through the real screen with its diff source replaced, so this is the function a round runs
    _FLAG578 = [
        ('assert "P2.11" not in blocked', "absent/open/blocked"),
        ('assert set(blocked) == {"P2.11", "P2.16"}', "a set compared by equality"),
        ('assert rows[0]["slot"] == "P2.4"', "an ordinal with no size assertion"),
        ('assert len([r for r in items if r["status"] == "open"]) >= 10', "a count over OPEN rows"),
    ]
    _EXEMPT578 = [
        ('assert slots.index("P1.1") < slots.index("P2.1")', "plan ORDER, which closing does not change"),
        ('assert {"P1.1", "P1.11"} <= {i["slot"] for i in done}', "a SUBSET of done, and done never reverts"),
        ('assert "0-1 applied" not in prompt, "P2.14\'s body still names it"',
         "the slot id is in the MESSAGE, not in what is asserted"),
        #  the REALISTIC shape: fixture-ness is established where the variable is built, which is a
        #  different line from the one that asserts. A single-line screen cannot see it, and this suite
        #  has exactly this case in test_w562 — a correct assertion a sweep would have rewritten.
        ('    _two = _rc.components([{"id": "FU-T1", "slot": "P2.4"}, {"id": "FU-T2", "slot": "P2.9"}])\\n'
         '    assert _two[0]["items_advanced"] == ["P2.4", "P2.9"]',
         "a fixture the test constructs itself"),
        ('assert _av[0].get("handed_from") == "P2.3"', "PROVENANCE, which is historical and immutable"),
    ]
    _orig578 = _sd.added_removed
    try:
        for _line578, _label578 in _FLAG578:
            _sd.added_removed = lambda rev, path, _l=_line578: ([(1, _l)], [])
            _hits578 = _sd.check_plan_pins("HEAD", ["integration_tests/test_w578_probe.py"])
            assert _hits578, (
                f"the plan-pin screen did not flag {_label578} - this is the shape that goes red when "
                f"the plan advances, and the round that adds it pays after the full suite", _line578)
        for _line578, _label578 in _EXEMPT578:
            #  split, because added_removed yields ONE ENTRY PER LINE and a case whose exemption is
            #  established on a different line is the whole point of the fixture rule
            _sd.added_removed = lambda rev, path, _l=_line578: (
                [(_i + 1, _s) for _i, _s in enumerate(_l.split("\\n"))], [])
            _hits578 = _sd.check_plan_pins("HEAD", ["integration_tests/test_w578_probe.py"])
            assert not _hits578, (
                f"the screen flagged {_label578}, which is CORRECT as written - W577 measured four such "
                f"assertions and a sweep acting on them would have broken all four", _line578, _hits578)
        #  AND THE SCREEN MUST NOT FLAG ITS OWN TEST DATA. Every flagged shape appears in this file as a
        #  STRING in the list above, and a screen that asks only whether a line CONTAINS "assert" read
        #  those as assertions and flagged five of them — so a round that touches this guard would be
        #  told its own examples are defects. A screen cannot tell its data from its subject without
        #  looking at the syntax: a real assertion STARTS with the keyword.
        _sd.added_removed = lambda rev, path: (
            [(1, """        ('assert "P2.11" not in blocked', "absent/open/blocked"),"""),
             (2, """        _examples = ["assert set(x) == {'P2.4'}"]""")], [])
        assert not _sd.check_plan_pins("HEAD", ["integration_tests/test_w578_probe.py"]), (
            "the screen flagged a line that merely QUOTES an assertion, so its own examples read as "
            "defects and every round touching this guard pays for it")
        #  and an ordinal SETTLED by a preceding size assertion is not a tie-break risk
        _sd.added_removed = lambda rev, path: ([(1, '    assert len(_av) == 1, _av'),
                                                (2, '    assert _av[0]["slot"] == "P3.6"')], [])
        assert not _sd.check_plan_pins("HEAD", ["integration_tests/test_w578_probe.py"]), (
            "an ordinal preceded by `len(x) == 1` has no ordering to lose, and flagging it would push a "
            "round to rewrite a correct assertion")
    finally:
        _sd.added_removed = _orig578
    assert _sd.added_removed is _orig578, "the screen's diff source was left patched"

    # ── L4. FU-394 — THE QUALIFIER REACHES THE PAGE, AND THE PAGE DECLARES THE ROUTE IT READS ───────
    _page578 = (_root / "apps/workstation-superapp/src/pages/coe/KnowledgeHub.tsx").read_text(
        encoding="utf-8", errors="replace")
    _code578 = _re578.sub(r"/\*.*?\*/", " ", _page578, flags=_re578.S)
    _code578 = _re578.sub(r"(?m)^\s*//.*$", " ", _code578)
    assert "{data?.score_meaning && (" in _code578, (
        "the response-level statement about what every score on this page MEANS reaches no surface - the "
        "per-insight basis says what one score is, and nothing says the ordering is not a ranking")
    assert 'data-testid="insights-score-meaning"' in _code578
    #  the two fields the page declared and the route has never sent. `portfolio_size` gated a provenance
    #  chip, so that chip had never once rendered.
    for _phantom578 in ("portfolio_size", "generated_at"):
        assert _phantom578 not in _code578, (
            f"the page still reads `{_phantom578}`, which this route has never sent - it is always "
            f"undefined, so anything gated on it cannot render", _phantom578)
    assert "{data?.total_projects != null ?" in _code578, (
        "the provenance chip is not gated on the key the route actually sends")
    #  and null is NOT zero here: a count of 0 would read as "you have no projects", which is the whole
    #  untruth FU-323 was about.
    assert 'data-testid="insights-provenance-unknown"' in _code578, (
        "a crash leaves total_projects null and the page says nothing - a reader cannot tell an unread "
        "portfolio from an empty one, which is FU-323 arriving by a second route")
    #  DRIVEN against the real route, so the declaration is checked against what is actually sent
    _r578 = client.get("/api/v1/intelligence/insights")
    assert _r578.status_code == 200, _r578.status_code
    _body578 = _r578.json()
    for _k578 in ("computed_at", "total_projects", "error", "score_meaning", "insights"):
        assert _k578 in _body578, ("the page now declares this and the route does not send it, which is "
                                   "the same defect in the other direction", _k578, sorted(_body578))
    for _gone578 in ("portfolio_size", "generated_at"):
        assert _gone578 not in _body578, (
            f"the route started sending `{_gone578}`, so the page's declaration should follow the route "
            f"rather than this guard being relaxed", _gone578)


def test_w577_p218a_a_tolerant_read_is_never_a_write_base_and_a_reader_is_told(client, tmp_path):
    """P2.18 clause (a), completed — and the class found while completing it.

    TWO PROPERTIES, one set of call sites. `read_json_reported` recovers a store's first complete JSON
    value and DISCARDS everything after it, so the same tolerant read has two different consequences
    depending on what the caller does with the value:

      * A READER shows a short figure as though it were whole. That is FU-298, a truth defect, and the
        remedy is that the figure says so ON THE SURFACE A PERSON READS.
      * A WRITER hands the prefix to `atomic_write_json` and the discarded remainder is overwritten and
        gone. That is FU-395, a LOSS defect, and disclosure does not fix it - the remedy is the
        opposite one: read strictly and refuse.

    Nine write paths were on the wrong side of that line. This drives the sharpest of them on a real
    store and asserts that nothing is lost, then drives the reader half and asserts the reason reaches
    the page rather than stopping at the API.
    """
    import ast as _ast577
    import asyncio as _aio577
    import json as _json577
    import pathlib as _pl577
    import re as _re577

    _root = _pl577.Path(__file__).resolve().parents[1]
    _app = _root / "apps" / "workstation-superapp" / "src"

    def _tsx_code(p: _pl577.Path) -> str:
        """TSX with comments removed. EVERY field asserted below is NAMED IN A COMMENT in these files
        (the comments explain what each disclosure is for), so a presence check over raw source is
        satisfied by the explanation of the fix instead of the fix."""
        s = p.read_text(encoding="utf-8", errors="replace")
        s = _re577.sub(r"/\*.*?\*/", " ", s, flags=_re577.S)        # /* */ and {/* */}
        s = _re577.sub(r"(?m)^\s*//.*$", " ", s)                     # whole-line //
        s = _re577.sub(r"(?<![:\w])//[^\n\"\']*$", " ", s, flags=_re577.M)   # trailing //
        return s

    #  ── (1) FU-395 — THE CORRUPTION SHAPE, AND A WRITER THAT REFUSES ─────────────────────────────
    #  Two concatenated records: what an interrupted overwrite of a shorter document by a longer one
    #  leaves behind. raw_decode returns the FIRST and drops the second, so the second holds the data.
    from agentic_core.api import user_workspace as _uw577
    from agentic_core.config import StoreUnavailable as _SU577
    from fastapi import HTTPException as _HE577

    _p577 = _pl577.Path(_uw577._path_for("w577-owner"))
    _p577.parent.mkdir(parents=True, exist_ok=True)
    _older = {"owner_id": "w577-owner", "history": [], "prefs": {}, "profile": {}, "updated_at": None}
    _newer = {"owner_id": "w577-owner", "history": [{"q": "W577 THE USER'S OWN QUESTION"}],
              "prefs": {"theme": "dark"}, "profile": {"about_you": "W577"},
              "updated_at": "2026-10-04T00:00:00Z"}
    _p577.write_text(_json577.dumps(_older) + _json577.dumps(_newer), encoding="utf-8")
    _before577 = _p577.read_bytes()
    assert b"W577 THE USER'S OWN QUESTION" in _before577, "the probe did not write what it meant to"

    #  the tolerant read really does drop it - otherwise everything below is vacuous
    _doc577, _why577 = _uw577._load("w577-owner")
    assert _why577, "read_json_reported gave no reason, so this store is not the shape being tested"
    assert _doc577.get("history") == [], (
        "the tolerant read did NOT drop the tail, so there is no loss here to refuse and every "
        "assertion below would pass without the fix", _doc577)

    #  THE WRITER REFUSES, and the bytes are untouched. This is the whole of FU-395.
    for _fn577, _req577 in (
            ("put_profile", lambda: _uw577.put_profile(
                _uw577.ProfilePut(owner_id="w577-owner"),
                {"id": "w577-owner", "user_id": "w577-owner", "owner_id": "w577-owner"})),
            ("clear_profile", lambda: _uw577.clear_profile(
                "w577-owner", {"id": "w577-owner", "user_id": "w577-owner", "owner_id": "w577-owner"})),
    ):
        try:
            _aio577.run(_req577())
            raise AssertionError(
                f"{_fn577} WROTE over a store it could not read whole - the discarded remainder of "
                f"that store is now gone, which is the defect FU-395 names")
        except _HE577 as _e577:
            assert _e577.status_code == 503, (_fn577, _e577.status_code)
            assert "NOT overwritten" in str(_e577.detail), (
                "the refusal does not say that nothing stored was lost, which is the only part of it "
                "a person needs", _fn577, _e577.detail)
        assert _p577.read_bytes() == _before577, (
            f"{_fn577} refused and still changed the file")

    #  ── (1b) THE SAME THING DRIVEN ON A ROUTE, BECAUSE SOURCE ANALYSIS COULD NOT SEE IT ─────────
    #  A blind proved both AST legs below are blind to ONE CALL OF INDIRECTION: the four lifecycle
    #  writers get their base from a helper that only READS, so it calls no writer (leg 2 cannot see
    #  it) and returns a dict rather than a (value, reason) pair (leg 3 cannot see it either). No
    #  smarter source check was the answer - CALLING THE ROUTE is. retire_model is the sharpest of the
    #  four: it APPENDS to the retired list and saves, so a dropped prefix un-retires every other
    #  model while reporting that one was retired.
    from agentic_core.ai.native import model_resource as _mr577
    _lp577 = _pl577.Path(_mr577._lifecycle_path())
    _lp577.parent.mkdir(parents=True, exist_ok=True)
    _lp577.write_text(
        _json577.dumps({"default_local": None, "retired": [], "evaluations": []})
        + _json577.dumps({"default_local": "m-b", "retired": ["m-a", "m-b"],
                          "evaluations": [{"model": "m-a", "score": 0.9}]}),
        encoding="utf-8")
    _lbefore577 = _lp577.read_bytes()
    assert b'"m-a"' in _lbefore577
    #  the tolerant read really does drop the retirements, or this proves nothing
    assert _mr577.lifecycle_state().get("retired") == [], (
        "the tolerant read did not drop the retired list, so this store is not the shape being tested")
    _r577 = client.post("/api/v1/native-ai/lifecycle/retire", json={"model": "m-c"})
    assert _r577.status_code == 503, (
        "retiring a model against a lifecycle record that could not be read whole SUCCEEDED, which "
        "means the write persisted the recoverable prefix and every model retired before this call is "
        "no longer retired - while the response reports a retirement", _r577.status_code, _r577.text)
    assert "NOT changed" in _r577.json().get("detail", ""), (
        "the refusal does not say that nothing already recorded was lost", _r577.json())
    assert _lp577.read_bytes() == _lbefore577, (
        "the route refused and still rewrote the lifecycle record")
    _lp577.unlink(missing_ok=True)

    #  ── (2) THE SAME RULE, ASSERTED AS A PROPERTY OF THE CODE, NOT OF THESE TWO ROUTES ───────────
    #  A function that reads a store tolerantly and then writes it is the defect wherever it appears.
    #  Asserted over the AST, because the whole finding was that it appeared in five files at once.
    _TOLERANT577 = {"read_json_reported"}
    _WRITERS577 = {"atomic_write_json", "save_lifecycle", "_save_fund"}
    #  W577 — THE SECOND HALF, and a blind is why it exists. The first leg only saw a tolerant read
    #  and a write in the SAME function, so changing `lifecycle_state(strict=True)` back to
    #  `lifecycle_state()` inside `_lifecycle_for_write` left it green: the tolerant read was one
    #  call of indirection away. The second leg below closes that by asserting the property at the
    #  ASSIGNMENT instead of at the callee's name.
    _offenders577 = []
    _lax577 = []
    for _f577 in sorted((_root / "agentic_core").rglob("*.py")):
        if "_archive" in _f577.parts:
            continue
        try:
            _t577 = _ast577.parse(_f577.read_text(encoding="utf-8", errors="replace"))
        except SyntaxError:
            continue
        for _n577 in _ast577.walk(_t577):
            if not isinstance(_n577, (_ast577.FunctionDef, _ast577.AsyncFunctionDef)):
                continue
            _names577 = {c.func.id for c in _ast577.walk(_n577)
                         if isinstance(c, _ast577.Call) and isinstance(c.func, _ast577.Name)}
            #  a tolerant read whose value is written back IN THE SAME FUNCTION
            if (_names577 & _TOLERANT577) and (_names577 & _WRITERS577):
                _offenders577.append(f"{_f577.relative_to(_root).as_posix()}::{_n577.name}")
            #  A WRITE BASE WHOSE REASON WAS THROWN AWAY. Expressed this way rather than as "a
            #  loader that takes strict", because that first cut matched on the BARE NAME `_load` and
            #  so flagged `molecular/work_budget.py::spend` for having a `_load` that takes no
            #  `strict` at all - right about the defect, wrong about why, and a name collision away
            #  from flagging any unrelated `_load` in the repo. The real property covers both shapes:
            #  a function that writes a store must not take its base from a reason-returning loader
            #  and discard the reason. `rec, _ = _load()` is the exact shape that loses it.
            if _names577 & _WRITERS577:
                for _a577 in _ast577.walk(_n577):
                    if not isinstance(_a577, _ast577.Assign):
                        continue
                    _tg577 = _a577.targets[0] if _a577.targets else None
                    if not (isinstance(_tg577, _ast577.Tuple) and len(_tg577.elts) == 2):
                        continue
                    _second = _tg577.elts[1]
                    if not (isinstance(_second, _ast577.Name) and _second.id == "_"):
                        continue          # the reason was bound to a name, so it is not discarded
                    _v577 = _a577.value
                    if not (isinstance(_v577, _ast577.Call) and isinstance(_v577.func, _ast577.Name)):
                        continue
                    _kw577 = {k.arg: k.value for k in _v577.keywords}
                    _st577 = _kw577.get("strict")
                    if isinstance(_st577, _ast577.Constant) and _st577.value is True:
                        continue          # it REFUSES instead, which is the stronger answer
                    _lax577.append(f"{_f577.relative_to(_root).as_posix()}::{_n577.name}"
                                   f" -> {_v577.func.id}() with its reason discarded")
    #  config.py defines the primitives and legitimately names both; nothing else may.
    _offenders577 = [o for o in _offenders577 if not o.startswith("agentic_core/config.py")]
    assert not _offenders577, (
        "these functions read a store TOLERANTLY and write it back in the same breath, so the part of "
        "the store the read could not recover is overwritten and lost", _offenders577)
    _lax577 = sorted({x for x in _lax577 if not x.startswith("agentic_core/config.py")})
    assert not _lax577, (
        "these functions WRITE a store and reach it through a loader that can refuse an unreadable "
        "one, without asking it to - so the write is still based on whatever prefix was recoverable",
        _lax577)

    #  ── (3) FU-298 — THE READER IS TOLERANT AND SAYS SO, THREE-STATE ─────────────────────────────
    _out577 = _aio577.run(_uw577.get_workspace(
        "w577-owner", {"id": "w577-owner", "user_id": "w577-owner", "owner_id": "w577-owner"}))
    assert _out577["count"] == 0, "the reader stopped being tolerant, which was never the fix"
    assert _out577["count_is_incomplete"] is True, (
        "the count is short and the answer does not say so", _out577)
    assert _out577["store_incomplete"], "the reason itself does not travel"
    assert "at least this long" in _out577["count_basis"], (
        "the basis does not say WHICH WAY the figure moves - a reader cannot act on 'incomplete' "
        "alone, and the records that could not be read are the ones MISSING from the count",
        _out577["count_basis"])
    #  and a store that is simply absent is NOT incomplete: a measured zero is not an unmeasured one
    _clean577 = _aio577.run(_uw577.get_workspace(
        "w577-absent", {"id": "w577-absent", "user_id": "w577-absent", "owner_id": "w577-absent"}))
    assert _clean577["count_is_incomplete"] is False and _clean577["store_incomplete"] is None, (
        "an absent store was reported as unreadable, which would make the disclosure meaningless by "
        "appearing on every empty workspace", _clean577)

    #  ── (4) THE REASON REACHES THE SURFACE, ASSERTED AS A BINDING ────────────────────────────────
    #  P2.18 clause (1): driven on the surface a person reads, never only on the API beneath it. Each
    #  pair below is (file, the field, a RENDER BINDING that must consume it) - the binding, not the
    #  name, because a field can be destructured, typed and never shown.
    for _rel577, _field577, _binds577 in (
        #  W577 — each gate carries its OPENING BRACE. The first cut of this leg asserted
        #  `fund?.balances_are_incomplete &&` without it, and a blind proved that `{false &&
        #  fund?.balances_are_incomplete &&` still contains that substring: the render was switched
        #  off and the guard passed. W503's class, committed inside the guard written to catch it.
        ("pages/enterprise/CapitalDashboard.tsx", "balances_are_incomplete",
         ("{fund?.balances_are_incomplete &&", "data-testid=\"fund-balances-incomplete\"")),
        ("pages/enterprise/CapitalDashboard.tsx", "fund_health_is_incomplete",
         ("{fund?.fund_health_is_incomplete &&", "data-testid=\"fund-health-incomplete\"")),
        ("pages/synthesis/ResourceFabric.tsx", "listing_is_incomplete",
         ("!!d.listing_is_incomplete", "data-testid=\"fabric-runs-incomplete\"")),
        ("components/organism/SwarmIntelligence.tsx", "total_is_incomplete",
         ("res.data.total_is_incomplete ?", "data-testid=\"cascade-runs-incomplete\"")),
        ("pages/developers/NativeAI.tsx", "retired_is_incomplete",
         ("{lifecycle.retired_is_incomplete &&", "data-testid=\"lifecycle-retired-incomplete\"")),
        ("pages/OperationalExcellence.tsx", "success_rate_is_incomplete",
         ("{m.success_rate_is_incomplete &&", "data-testid=\"model-rate-incomplete\"")),
        ("pages/profile/Wallet.tsx", "allocations_are_incomplete",
         ("portfolioRes.data.allocations_are_incomplete", "data-testid=\"wallet-allocations-incomplete\"")),
        ("pages/Settings.tsx", "profile_is_incomplete",
         ("r.profile_is_incomplete ?", "data-testid=\"profile-store-incomplete\"")),
        #  not a page but a LIB every page reads its history through, and the warning channel it
        #  already owns: a 200 over a partial store used to CLEAR that warning.
        ("lib/outputHistory.ts", "count_is_incomplete",
         ("doc.count_is_incomplete", "count_basis")),
    ):
        _src577 = _tsx_code(_app / _rel577)
        for _b577 in _binds577:
            assert _b577 in _src577, (
                f"{_rel577}: the disclosure for {_field577} does not reach the page - this binding is "
                f"absent from the code (comments stripped, so an explanation of the fix does not "
                f"count as the fix)", _b577)

    #  and the ones with NO page: an unread route's own response IS its surface, and saying so is part
    #  of the clause rather than an excuse for skipping it.
    for _route577, _needles577 in (
        ("/api/v1/swarm/catalogue/proposed", ("listing_is_incomplete", "listing_basis")),
        ("/api/v210/federation/twins", ("total_is_incomplete", "total_basis")),
        #  W577 — added after the PRE-FLIGHT flagged their keys as reaching no surface. It was right
        #  that no page renders them and right to ask which surface does; the answer is that these
        #  routes have no page in this app, so their own response is it. Asserting that here is what
        #  turns "no page renders it" from an unanswered lead into a stated position.
        ("/api/v310/governance/treasury", ("figures_are_incomplete", "figures_basis",
                                           "total_capital_wst", "allocated_wst")),
        ("/api/v310/payments/status", ("wst_available", "wst_available_basis")),
        ("/api/v310/payments/wallet/w577-user", ("platform_capital_fund_available",
                                                "platform_capital_fund_incomplete")),
    ):
        _r577 = client.get(_route577)
        assert _r577.status_code == 200, (_route577, _r577.status_code)
        for _k577 in _needles577:
            assert _k577 in _r577.json(), (
                f"{_route577} has no page in this app, so its own response is the surface a person "
                f"reads and the disclosure has to be in it", _k577, sorted(_r577.json()))

    #  and the one that is a POST: settling against the fund says what the balance it compared to was
    _pay577 = client.post("/api/v310/payments/create-session",
                          json={"item_id": "w577", "price_wst": 1.0, "payment_method": "wst_balance"})
    assert _pay577.status_code in (200, 503), _pay577.status_code
    if _pay577.status_code == 200:
        assert "balance_basis" in _pay577.json(), (
            "a session settled or refused against the capital fund's `available` and did not say what "
            "that figure was based on - `available` is the one figure a partial read OVERSTATES",
            sorted(_pay577.json()))


def test_w576_p218a_an_absence_reaches_the_reader(client):
    """P2.18 clause (a) — where something could not be read, counted or run, the SURFACE says so.

    Six rows, one property. Each of these had a writer that already knew and a reader that was never
    told: a crash returning an empty list, a count over a store that had silently dropped its oldest
    rows, a ledger append whose failure rendered identically to a success, sibling returns whose key
    sets disagreed, a stage that announced a start it never ended, and four compliance dimensions
    flattened away before any surface could see them.
    """
    import ast as _ast576
    import asyncio as _aio576
    import pathlib as _pl576
    import re as _re576
    from unittest.mock import patch as _patch576

    _root = _pl576.Path(__file__).resolve().parents[1]
    _app = _root / "apps" / "workstation-superapp" / "src"

    def _code(p):
        t = p.read_text(encoding="utf-8")
        t = _re576.sub(r"/\*.*?\*/", "", t, flags=_re576.S)
        return "\n".join(l for l in t.splitlines() if not l.lstrip().startswith("//"))

    # ── FU-323 — A CRASH IS NOT AN EMPTY PORTFOLIO ─────────────────────────────────────────────
    #  The failure is carried INSIDE `insights`, because the sole reader takes that list and nothing
    #  else: a fix that only added a sibling key would be invisible to it, which is how the original
    #  `error` key sat unread while a crash rendered as "create your first project".
    import agentic_core.api.products as _P576
    with _patch576("agentic_core.projects.api._all_projects",
                   side_effect=RuntimeError("store unreadable")):
        _out = _aio576.get_event_loop_policy().new_event_loop().run_until_complete(
            _P576.intelligence_insights())
    assert _out["insights"], "a crash returns an EMPTY insights list again, which renders as 'no projects'"
    _first = _out["insights"][0]
    assert "could not be computed" in _first["title"].lower(), _first["title"]
    assert "not a statement" in _first["detail"].lower(), (
        "the failure does not say that nothing was counted, so it still reads as a measured zero",
        _first["detail"][:160])
    #  `error` is the fact, and it is the one the page reads. An `insights_are_complete` flag was
    #  added here too and removed in the same round: the pre-flight found it reaching no surface,
    #  and a second key saying what `error` already says is a key that qualifies nothing.
    assert _out.get("error"), _out.keys()
    #  AND THE SIBLING RETURNS CARRY THE SAME KEYS — FU-334's property, in the branches this row's
    #  own fix added. A caller indexing `total_projects` on the crash path must get None (nothing
    #  was counted) rather than undefined (the key is absent).
    assert "total_projects" in _out and _out["total_projects"] is None, (
        "the crash branch omits total_projects, so a caller indexing it gets undefined — or reports "
        "a measured zero for a count that never ran", _out.get("total_projects"))
    #  and the page names it rather than printing its onboarding line over a crash
    _kh = _code(_app / "pages" / "coe" / "KnowledgeHub.tsx")
    assert "insights-error" in _kh, "the page has no reader for the route's error key"

    # ── FU-316 — A COUNT OVER A CAPPED STORE SAYS SO ───────────────────────────────────────────
    #  The cap must be a NAMED constant: it was a literal in the writer and nowhere else, so the
    #  reader could not have known what it was counting against even if it had tried.
    import agentic_core.api.deliverables as _D576
    import agentic_core.api.resource_fabric as _R576
    assert isinstance(_D576._ROW_CAP, int) and isinstance(_R576._SWARM_CAP, int)
    _dsrc = (_root / "agentic_core/api/deliverables.py").read_text(encoding="utf-8")
    _rsrc = (_root / "agentic_core/api/resource_fabric.py").read_text(encoding="utf-8")
    assert "rows[-_ROW_CAP:]" in _dsrc and "rows[-_SWARM_CAP:]" in _rsrc, (
        "a cap is a bare literal again, so the writer and the reader can disagree about it")
    #  AT THE SITE, because both files now carry `truncated` on TWO branches — the normal one and
    #  the unreadable one, which reports None (not known) for key-set parity. A file-wide check
    #  therefore survived the normal branch losing it, which is the needle-appears-twice class.
    assert '"truncated": _at_cap' in _dsrc and '"truncated": _at_cap' in _rsrc, (
        "a count route no longer reports whether its store is AT its cap, so a count over a store "
        "that has been dropping its oldest rows reads as complete")
    for _src, _what in ((_dsrc, "deliverables"), (_rsrc, "cascades")):
        assert '"total_basis"' in _src, (
            f"the {_what} count carries no basis saying what was counted")

    # ── FU-353 — WHETHER THE DECISION REACHED THE LEDGER ───────────────────────────────────────
    _cc = (_root / "agentic_core/api/change_control.py").read_text(encoding="utf-8")
    assert '"ueg_logged": ueg_logged' in _cc, "submit_change no longer returns whether it logged"
    _ccp = _code(_app / "pages" / "enterprise" / "ChangeControlAgency.tsx")
    assert "ueg_logged" in _ccp and "NOT RECORDED IN THE GOVERNANCE LEDGER" in _ccp, (
        "the governance page still renders five fields and not whether the change reached the UEG, "
        "so an unlogged filing looks identical to a logged one")
    #  AND IT IS APPENDED TO THE MESSAGE. Computing the sentence and never concatenating it is the
    #  shape a half-finished fix takes, and it leaves every string in the file for a name check to
    #  find — the blind that removed `+ ledger` passed this leg until it asserted the binding.
    assert "+ raised + ledger)" in _ccp, (
        "the ledger sentence is computed and never appended, so the page says nothing about whether "
        "the change reached the UEG")

    # ── FU-334 — SIBLING RETURNS AGREE ON THEIR KEYS ───────────────────────────────────────────
    _ap = (_root / "agentic_core/ai/ceo/autonomy_pipelines.py").read_text(encoding="utf-8")
    _sets = []
    for _fn in _ast576.walk(_ast576.parse(_ap)):
        if isinstance(_fn, (_ast576.FunctionDef, _ast576.AsyncFunctionDef)) and \
                _fn.name == "run_extrospection":
            for _n in _ast576.walk(_fn):
                if isinstance(_n, _ast576.Return) and isinstance(_n.value, _ast576.Dict):
                    _sets.append(frozenset(k.value for k in _n.value.keys
                                           if isinstance(k, _ast576.Constant)))
    assert len(_sets) >= 2, ("run_extrospection no longer has sibling returns to compare", len(_sets))
    assert len(set(_sets)) == 1, (
        "run_extrospection's sibling returns carry different key sets, so a caller reading one of "
        "them gets undefined depending on which path ran", [sorted(s) for s in set(_sets)])
    assert "status" in next(iter(set(_sets))), sorted(next(iter(set(_sets))))

    # ── FU-369 — EVERY STAGE THIS STREAM OPENS, IT CLOSES ──────────────────────────────────────
    #  Asserted on the ORDER, not on the presence of a string: the defect was that `_start` was
    #  yielded BEFORE the template check, so the fix is that the check comes first.
    #  THE ORDER IS THE FIX, and the first cut of this leg carried an `or "_skipped" in ...` escape
    #  that made it pass whatever the order was. A stage must not be ANNOUNCED as started before
    #  anything knows whether it can run: an absent ending is indistinguishable from a cut stream.
    _intel = (_root / "agentic_core/api/intelligence.py").read_text(encoding="utf-8")
    _loop = _intel.index("for i, (stage_key, stage_label, stage_desc) in enumerate(stages):")
    _body = _intel[_loop:_loop + 2000]
    _check = _body.index("prompt_template = prompts.get(stage_key")
    _start = _body.index('_ev(f"{stage_key}_start"')
    assert _check < _start, (
        "a stage announces its START before the template check, so one that cannot run is announced "
        "as begun and then silently never finishes")
    assert '_ev(f"{stage_key}_skipped"' in _body, (
        "a stage with no template is skipped silently; the stream must say which stage and why")

    # ── FU-318 — A DIMENSION THAT ASSESSED NOTHING REACHES THE READER ──────────────────────────
    from agentic_core.api.compliance import screen_compliance as _screen576
    _r = _screen576("a delivery about employment tribunal representation and data handling")
    if _aio576.iscoroutine(_r):
        _r = _aio576.get_event_loop_policy().new_event_loop().run_until_complete(_r)
    _eth = [v for v in _r["verdicts"] if v.get("framework") == "ethical"]
    assert _eth, "the ethical framework no longer appears in the screen"
    #  Only the NOT-ASSESSED names travel: a full per-dimension detail list was added here and
    #  removed in the same round because the pre-flight found it reaching no surface. The names are
    #  what the chip renders, so the names are what must survive.
    assert "dimensions_not_assessed" in _eth[0], (
        "the compliance layer flattens the ethical engine's dimensions away again, so a reader sees "
        "THAT the framework was assessed and never that a dimension inside it was not", _eth[0].keys())
    assert _eth[0]["dimensions_not_assessed"], (
        "no dimension is reported unassessed, though the engine's own basis says all three ethical "
        "dimensions are word lists that cannot assess a subject — this leg would then be vacuous",
        _eth[0])
    _chip = _code(_app / "lib" / "api.ts")
    assert "dimensions_not_assessed" in _chip and "DIMENSIONS not assessed" in _chip, (
        "complianceChip still derives everything from framework-level status, so a dimension-level "
        "not_assessed reaches no surface")
    #  AND IT IS RENDERED. `dimGaps` stayed computed and correct while the render was switched off,
    #  which left both names above in the file for a presence check to find.
    assert "dimGaps.length ?" in _chip, (
        "the dimension gap is computed and never shown, so the producer-side fix reaches no reader")
def test_a_route_whose_matcher_can_never_fire_is_refused(tmp_path):
    """A route stored with input the matcher cannot act on sends its area nowhere while reading as owned.

    FOUND BY TRIPPING IT, W583. `route --slot P3.26 --files "requirements.txt pyproject.toml"` was
    ACCEPTED and printed "route added at position 16". `_route_matches` compares a route's file whole
    (`==`) or as a directory prefix (`startswith`), so that single space-joined prefix could never match
    any row — and the very next command refused with "no route matches its files". Two messages that
    disagreed, neither naming the cause.

    THE PROPERTY, NOT THE SPELLING: the control leg does not merely check that the comma form is
    accepted — it asserts the stored route ACTUALLY MATCHES a row through the real matcher. A refusal
    that let an unmatchable route through in some other shape would pass a spelling check and fail this.

    AND THE REFUSAL MUST NOT OVER-REACH. `--words` is matched by searching a row's TITLE for the whole
    phrase, so a multi-word word is legitimate and P2.18's own route carries "cannot be read". A refusal
    that rejected whitespace in --words too would silently narrow what a route can own.
    """
    import json as _jsonR
    import os as _osR
    import pathlib as _plR
    import subprocess as _spR
    import sys as _sysR

    import agentic_core.plan_followups as _fuR

    _rootR = _plR.Path(__file__).resolve().parents[1]
    _promptR = _fuR.read_doc(_rootR / "docs" / "FABLE_DELIVERY_PROMPT.md")
    _livingR = _fuR.read_doc(_rootR / "docs" / "WORKSTATION_IDBO_LIVING_PLAN.md")
    _openR = [i["slot"] for i in _fuR.plan_items(_promptR) if not i["done"]]
    assert _openR, "this leg needs an open plan item for a route to point at"
    _slotR = _openR[0]

    #  a scratch root, never the repository: `route` MUTATES a register
    _scrR = tmp_path / "routeroot"
    (_scrR / "docs").mkdir(parents=True)
    _emptyR = {"items": []}
    (_scrR / "docs" / "FABLE_DELIVERY_PROMPT.md").write_bytes(
        _fuR.splice_all(_promptR, _emptyR, _promptR).encode("utf-8"))
    (_scrR / "docs" / "WORKSTATION_IDBO_LIVING_PLAN.md").write_bytes(
        _fuR.splice_all(_livingR, _emptyR, _promptR).encode("utf-8"))
    (_scrR / "docs" / "FOLLOWUPS.json").write_bytes(b'{"items": []}\n')
    _envR = dict(_osR.environ, WORKSTATION_FOLLOWUPS_ROOT=str(_scrR), PYTHONIOENCODING="utf-8")
    _scriptR = str((_rootR / "scripts" / "followups.py").resolve())
    assert _plR.Path(_scriptR).is_file(), ("the CLI this leg drives is not where it was looked for", _scriptR)

    def _cliR(*argv):
        return _spR.run([_sysR.executable, _scriptR, *argv], env=_envR,
                        capture_output=True, text=True, encoding="utf-8")

    def _routesR():
        return (_jsonR.loads((_scrR / "docs" / "FOLLOWUPS.json").read_text(encoding="utf-8"))
                .get("routes") or [])

    # ── L1. A SPACE-JOINED --files IS REFUSED, AND NOTHING IS STORED ────────────────────────────────
    _spacedR = _cliR("route", "--slot", _slotR, "--files", "requirements.txt pyproject.toml",
                     "--words", "manifest")
    assert _spacedR.returncode != 0, (
        "a route whose file is a space-joined list was ACCEPTED - it can never match a row, so the area "
        "it claims to own silently has no owner", _spacedR.stdout, _spacedR.stderr)
    _saidR = (_spacedR.stdout + _spacedR.stderr).lower()
    assert "comma" in _saidR, (
        "the refusal does not name the separator the caller should have used, so it does not say how to "
        "fix the thing it refused", _spacedR.stdout, _spacedR.stderr)
    assert not _routesR(), ("the refused route was stored anyway", _routesR())

    # ── L2. AND A ROUTE ALREADY IN THE REGISTER IS SCREENED, WHICH IS THE POINT OF WHERE IT LIVES ───
    #  The first cut put this rule in the CLI's add branch. A blind then proved one of its two refusals
    #  VACUOUS — _route_shape_problems ALREADY refuses a matcherless route — and that said where the
    #  surviving rule belonged: beside its siblings in the shape validator, which check() runs over the
    #  routes ALREADY STORED. A CLI-only check could not see a bad route that is already in the file.
    _badR = {"slot": _slotR, "files": ["requirements.txt pyproject.toml"], "words": []}
    (_scrR / "docs" / "FOLLOWUPS.json").write_bytes(
        _jsonR.dumps({"items": [], "routes": [_badR]}, ensure_ascii=False, indent=1).encode("utf-8") + b"\n")
    _checkR = _cliR("check")
    _checkSaidR = _checkR.stdout + _checkR.stderr
    assert "space in it" in _checkSaidR, (
        "a route ALREADY in the register carries a prefix with a space, which can never match a path, and "
        "check() does not report it - so the area reads as owned and every row in it falls through",
        _checkSaidR)
    #  and the rule is NOT applied to words, where a phrase is legitimate
    _phraseR = {"slot": _slotR, "files": [], "words": ["cannot be read"]}
    (_scrR / "docs" / "FOLLOWUPS.json").write_bytes(
        _jsonR.dumps({"items": [], "routes": [_phraseR]}, ensure_ascii=False, indent=1).encode("utf-8") + b"\n")
    _phraseCheckR = _cliR("check")
    assert "space in it" not in (_phraseCheckR.stdout + _phraseCheckR.stderr), (
        "a multi-word route WORD was reported as unmatchable; a word is searched for INSIDE a row's title, "
        "so a phrase is legitimate and P2.18's own route carries exactly this one",
        _phraseCheckR.stdout, _phraseCheckR.stderr)
    #  restore an empty register for the control leg
    (_scrR / "docs" / "FOLLOWUPS.json").write_bytes(b'{"items": []}\n')

    # ── L3. THE CONTROL: the correct form is accepted AND the stored route REALLY MATCHES ───────────
    #  a multi-word --words phrase is legitimate (searched inside a title) and must still be accepted
    _okR = _cliR("route", "--slot", _slotR, "--files", "requirements.txt,pyproject.toml",
                 "--words", "manifest,cannot be read")
    assert _okR.returncode == 0, (
        "the CORRECT comma form was refused, so the refusal over-reached and a round can no longer give "
        "an area an owner", _okR.stdout, _okR.stderr)
    _storedR = [r for r in _routesR() if r.get("slot") == _slotR]
    assert _storedR, ("the accepted route was not stored", _routesR())
    _rtR = _storedR[0]
    assert "cannot be read" in _rtR.get("words", []), (
        "a multi-word route WORD was dropped or split; --words is searched for inside a row's title, so "
        "a phrase is legitimate and P2.18's own route carries exactly this one", _rtR)
    #  THE PROPERTY the refusals exist to protect: the stored route can actually fire
    assert _fuR._route_matches(_rtR, "a title about nothing", ["requirements.txt"]), (
        "the stored route does not match a row whose file it names - the matcher cannot act on what the "
        "CLI accepted, which is the whole defect", _rtR)
    assert _fuR._route_matches(_rtR, "a lockfile that cannot be read tolerantly", []), (
        "the stored route does not match a row whose title carries its phrase", _rtR)
def test_w584_p327_selection_refuses_before_it_ranks(client, monkeypatch, tmp_path):
    """P3.27 — selection becomes possible, and the first thing it does is refuse.

    MEASURED BEFORE BUILDING. `organism/genome.py` had crossover, mutation and lineage and its own
    docstring said "NOTHING in this module evaluates fitness" — variation yes, inheritance yes, SELECTION
    NO. Customer/user satisfaction had no mechanism anywhere: the only occurrences in the live tree were a
    heading in a generated document and `drad.py` holding `user_satisfaction: None` precisely BECAUSE it
    had no source. And the only fitness implementation was a stub returning 1.0 for every individual.

    THE CLAUSES ARE DRIVEN, NOT READ. Each leg below puts the platform into a state and reads the answer
    back out, because every one of these could be satisfied by a source file that says the right words.
    """
    import ast as _ast584
    import json as _json584
    import pathlib as _pl584
    import re as _re584

    import agentic_core.economy.living_vsbs as _lv584
    from agentic_core.organism import selection as _sel584
    from agentic_core.support import satisfaction as _sat584

    _root584 = _pl584.Path(__file__).resolve().parents[1]

    # ── L1. CLAUSE (1): THE BOUNDARY, ASSERTED ON THE BINDING ──────────────────────────────────────
    #  Ruling A.9.5. Nothing this item builds may compute, score, rank or infer a spiritual state. The
    #  assertion is on the BINDING and not on a word list, because this round's own files DISCUSS the
    #  forbidden names at length — a grep for the word would match the paragraph forbidding it, which is
    #  the inverse of the banned-literal trap and would make this leg pass for the wrong reason.
    _forbidden584 = ("sincerity", "tazkiyah", "barakah", "fitrah", "virtue", "gratitude", "piety",
                     "readiness", "spiritual")
    for _mod584 in ("agentic_core/organism/selection.py", "agentic_core/support/satisfaction.py"):
        _tree584 = _ast584.parse((_root584 / _mod584).read_text(encoding="utf-8"))
        #  every NAME this module binds: assignments, keyword arguments, dict keys and def/class names
        _bound584 = set()
        for _n584 in _ast584.walk(_tree584):
            if isinstance(_n584, _ast584.Name):
                _bound584.add(_n584.id.lower())
            elif isinstance(_n584, (_ast584.FunctionDef, _ast584.AsyncFunctionDef, _ast584.ClassDef)):
                _bound584.add(_n584.name.lower())
            elif isinstance(_n584, _ast584.keyword) and _n584.arg:
                _bound584.add(_n584.arg.lower())
            elif isinstance(_n584, _ast584.Attribute):
                _bound584.add(_n584.attr.lower())
            elif isinstance(_n584, _ast584.Constant) and isinstance(_n584.value, str):
                #  a dict KEY is a string constant; only short ones can be field names, which keeps the
                #  prose in these modules' docstrings out of the comparison
                if len(_n584.value) <= 40 and " " not in _n584.value:
                    _bound584.add(_n584.value.lower())
        for _word584 in _forbidden584:
            _hits584 = [b for b in _bound584 if _word584 in b]
            assert not _hits584, (
                "a field, name or key in a module this item builds carries a word Ruling A.9.5 forbids "
                "being computed about anyone - the boundary is clause ONE because it is the clause that "
                "cannot be added later", _mod584, _word584, sorted(_hits584))

    # ── L2. CLAUSE (2): A REAL EXPLICIT RATING, AND "NOT MEASURED" WHERE THERE IS NONE ─────────────
    #  the empty state is DRIVEN by controlling what the store returns, not observed: after any earlier
    #  leg records a rating the store is not empty, so an unconditional read would check this by luck.
    _read_orig584 = _sat584._read
    try:
        _sat584._read = lambda: []
        _empty584 = _sat584.summary()
        assert _empty584["mean"] is None and _empty584["state"] == "not_measured", _empty584
        assert "NOT MEASURED" in _empty584["basis"] and "absence of a signal" in _empty584["basis"], (
            "an empty satisfaction store does not say that it is the ABSENCE of a signal rather than a low "
            "one - a 0 would read as nobody being happy and a 1.0 as the archived monitor's figure",
            _empty584["basis"])
        assert _empty584["mean"] != 0, "silence was reported as a zero"
    finally:
        _sat584._read = _read_orig584
    assert _sat584._read is _read_orig584, "the satisfaction reader was left patched"

    #  IT REFUSES rather than coercing. A float is what a COMPUTED score looks like, and a clamped value
    #  reads as one somebody gave.
    for _bad584, _why584 in ((4.5, "a float, which is what a computed score looks like"),
                             (True, "a boolean, which is not a rating on a scale"),
                             (9, "above the declared scale"),
                             (0, "below the declared scale")):
        with pytest.raises((TypeError, ValueError)):
            _sat584.record_rating("the platform", _bad584, "w584")
    with pytest.raises(ValueError):
        _sat584.record_rating("the platform", 4, "   ")          # an unattributable rating

    _rec584 = _sat584.record_rating("w584 probe subject", 4, "w584-person", comment="driven")
    assert _rec584["signal"] == "explicit-rating-by-a-person", _rec584
    _sum584 = _sat584.summary("w584 probe subject")
    assert _sum584["state"] == "measured" and _sum584["mean"] == 4.0 and _sum584["count"] == 1, _sum584

    #  AND THE ROUTE, both states
    _r584 = client.post("/api/v1/support/satisfaction",
                        json={"subject": "w584 route subject", "rating": 5, "by": "w584-person"})
    assert _r584.status_code == 200, (_r584.status_code, _r584.text[:300])
    assert _r584.json()["signal"] == "explicit-rating-by-a-person", _r584.json()
    #  a fractional rating is refused AT THE EDGE, never clamped
    _bad584 = client.post("/api/v1/support/satisfaction",
                          json={"subject": "x", "rating": 4.5, "by": "w584-person"})
    assert _bad584.status_code == 422, (
        "a fractional rating was accepted somewhere on the way in; a computed score must not be storable "
        "as a person's opinion", _bad584.status_code, _bad584.text[:200])
    _g584 = client.get("/api/v1/support/satisfaction?subject=w584%20route%20subject").json()
    assert _g584["state"] == "measured" and _g584["mean"] == 5.0, _g584
    assert _g584["inferred_from_behaviour"] is False, _g584

    #  THE LIVE TREE IS SCREENED FOR A BEHAVIOURAL SIGNAL, because the clause says to rather than
    #  trusting it. Option (b) - an aggregate behavioural signal - was offered to the Owner and NOT taken.
    #
    #  ASSERTED ON THE BINDING, and the first cut of this leg is why. It searched the source TEXT and
    #  failed on correct code, because the store's basis says - truthfully - "no dwell time, no implicit
    #  signal and no behavioural aggregate enters this figure". A runtime f-string is neither a comment nor
    #  a docstring, so stripping those left the sentence that states the rule, and the detector read it as
    #  the rule being broken. That is the banned-literal class one layer out: last time a COMMENT
    #  recording a removal, this time a BASIS declaring an exclusion. A behavioural signal would have to be
    #  something the module BINDS - a field, key, parameter or attribute - and prose cannot be mistaken for
    #  one, because a bound name is short and has no spaces.
    _satbound584 = set()
    for _n584 in _ast584.walk(_ast584.parse(
            (_root584 / "agentic_core/support/satisfaction.py").read_text(encoding="utf-8"))):
        if isinstance(_n584, _ast584.Name):
            _satbound584.add(_n584.id.lower())
        elif isinstance(_n584, (_ast584.FunctionDef, _ast584.AsyncFunctionDef, _ast584.ClassDef)):
            _satbound584.add(_n584.name.lower())
        elif isinstance(_n584, _ast584.arg):
            _satbound584.add(_n584.arg.lower())
        elif isinstance(_n584, _ast584.keyword) and _n584.arg:
            _satbound584.add(_n584.arg.lower())
        elif isinstance(_n584, _ast584.Attribute):
            _satbound584.add(_n584.attr.lower())
        elif isinstance(_n584, _ast584.Constant) and isinstance(_n584.value, str):
            if len(_n584.value) <= 40 and " " not in _n584.value:
                _satbound584.add(_n584.value.lower())
    for _beh584 in ("dwell", "time_on_page", "click_through", "implicit", "engagement",
                    "session_length", "scroll_depth", "behaviour_score", "behavior_score"):
        _bhits584 = [b for b in _satbound584 if _beh584 in b]
        assert not _bhits584, (
            "a BEHAVIOURAL signal is BOUND in the satisfaction path. The Owner's ruling of 2026-10-03c "
            "took option (a), the explicit rating ONLY, and option (b) - an aggregate behavioural signal "
            "- was offered and not taken", _beh584, sorted(_bhits584))
    #  and the one legal signal value is the one the store writes, so an inferred row has no way in
    assert "explicit-rating-by-a-person" in _satbound584, (
        "the store no longer declares the single legal signal value, so a row with any other provenance "
        "could enter the figure the ruling says must contain none")

    #  and the SURFACE renders the not-measured state as its own thing, asserted on the GATE
    _page584 = (_root584 / "apps/workstation-superapp/src/pages/support/Support.tsx").read_text(
        encoding="utf-8", errors="replace")
    _pcode584 = _re584.sub(r"(?m)^\s*//.*$", " ",
                           _re584.sub(r"/\*(?:.|\n)*?\*/", " ", _page584))
    assert "{sat.state === 'not_measured' ? (" in _pcode584, (
        "the page does not branch on the not-measured state, so an absent signal has no rendering of its "
        "own - W503's class, so this asserts the gate with its opening brace rather than the literal")
    for _tid584 in ('data-testid="support-satisfaction-not-measured"',
                    'data-testid="support-satisfaction-mean"'):
        assert _tid584 in _pcode584, ("a satisfaction state has no rendered element", _tid584)
    #  the rating control is asserted on its BINDING, not on an expanded testid: the buttons build their
    #  own test ids from a template literal, so `data-testid="support-rate-1"` appears nowhere in source
    #  and a leg looking for it was checking a string the page never contains.
    assert 'support-rate-' in _pcode584, "the page offers no rating control at all"
    assert '[1, 2, 3, 4, 5].map' in _pcode584, (
        "the rating control does not offer the declared scale, so a person cannot give the only signal "
        "this platform has")
    assert 'onClick={() => rate(n)}' in _pcode584, (
        "the rating buttons are not wired to the writer, so pressing one records nothing - a control that "
        "looks like it works is worse than none")

    # ── L3. CLAUSE (3): SELECTION REFUSES WHILE ANY MEASURE IS UNMEASURED, AND NAMES WHICH ─────────
    #  driven with EXACTLY ONE missing, which is what the clause specifies. The roster is monkeypatched
    #  rather than written, so no shared store is touched by this leg.
    _ROSTER584 = {"living_vsbs": [{"vsb_id": "vsb-w584", "name": "w584 probe",
                                   "last_distributable": 120.0,
                                   "compliance": {"verdict": "pass", "screened_at": "2026-01-02T00:00:00Z"}}],
                  "total": 1}
    monkeypatch.setattr(_lv584, "list_living", lambda: _ROSTER584)
    monkeypatch.setattr(_sat584, "summary", lambda *_a, **_k: {
        "mean": 4.2, "state": "measured", "count": 3, "basis": "driven by the w584 guard"})

    _one584 = _sel584.assess("vsb-w584")
    assert _one584["status"] == _sel584.NOT_ASSESSABLE, (
        "three of the four measures are present and selection did not refuse on the fourth", _one584)
    assert _one584["unmeasured"] == ["founder_alignment"], (
        "the refusal does not name EXACTLY the one measure that is missing", _one584["unmeasured"])
    assert sorted(_one584["measured"]) == ["live_compliance", "profitability", "user_satisfaction"], _one584
    assert "founder_alignment" in _one584["basis"], (
        "the basis does not NAME the missing measure, so a reader cannot tell which of the four stopped "
        "selection", _one584["basis"])
    assert _one584["selected"] is None, "a refusal produced a selection verdict anyway"
    #  NO PAGE FETCHES THIS ROUTE, so its own response is the surface a person reads - which means the
    #  keys that qualify the answer have to be asserted here or nothing holds them there.
    _rt584 = client.get("/api/v1/organism/selection/vsb-w584").json()
    assert _rt584["measures_required"] == list(_sel584.MEASURES), (
        "the route does not state WHICH four measures §8 requires, so a reader of the refusal cannot tell "
        "what the complete set is", _rt584.get("measures_required"))
    assert _rt584["status"] == _sel584.NOT_ASSESSABLE and _rt584["unmeasured"], _rt584
    assert str(_rt584.get("method") or "").strip(), "the route reports no method at all"
    #  founder-alignment is NOT MEASURED and not substituted by a proxy
    _fa584 = _one584["measures"]["founder_alignment"]
    assert _fa584["measured"] is False and _fa584["value"] is None, _fa584
    assert "no mechanism" in _fa584["basis"], (
        "founder-alignment reports something other than the absence of any mechanism", _fa584["basis"])

    #  a MEASURED ZERO is a measurement, not an absence - the three-state rule this plan keeps applying
    monkeypatch.setitem(_ROSTER584["living_vsbs"][0], "last_distributable", 0.0)
    _zero584 = _sel584.measure_entity("vsb-w584")["measures"]["profitability"]
    assert _zero584["measured"] is True and _zero584["value"] == 0.0, (
        "a recorded profitability of ZERO was treated as unmeasured; a measured zero and an unmeasured "
        "field are different facts", _zero584)

    # ── L4. CLAUSE (4): THE HARD FLOOR FLAGS, NAMES THE FLOOR, AND CARRIES ITS COVERAGE ────────────
    monkeypatch.setitem(_ROSTER584["living_vsbs"][0], "compliance",
                        {"verdict": "fail", "screened_at": "2026-01-02T00:00:00Z"})
    _flag584 = _sel584.negative_selection("vsb-w584")
    assert _flag584["status"] == _sel584.FLAGGED and _flag584["flagged"] is True, _flag584
    assert _flag584["floors_breached"] == ["live_compliance"], (
        "the flag does not name the floor it failed", _flag584)
    assert _flag584["retired"] is False and "never a retirement" in _flag584["basis"], (
        "a flag reads as a retirement; death is governed through Change Control, not by a floor", _flag584)
    #  a floor nothing can assess says so and is NEVER counted as passed
    assert "section_8_obligations" in _flag584["floors_not_assessable"], _flag584
    assert "COVERAGE" in _flag584["basis"], (
        "the result does not carry what it could NOT assess, so it reads as clearing the entity on a "
        "question nobody asked - a screen may refuse, never clear", _flag584["basis"])
    #  and a clean verdict is not flagged, so the flag is not a constant
    monkeypatch.setitem(_ROSTER584["living_vsbs"][0], "compliance",
                        {"verdict": "pass", "screened_at": "2026-01-02T00:00:00Z"})
    _clean584 = _sel584.negative_selection("vsb-w584")
    assert _clean584["status"] == _sel584.NOT_FLAGGED and _clean584["flagged"] is False, (
        "a passing entity is flagged too, so the flag carries no information", _clean584)

    # ── L5. CLAUSE (5): THE FUNDING SCORE IS NOT REUSED ────────────────────────────────────────────
    #  funding selects on POTENTIAL (§4 Stage 4: outcome x value x benefit x feasibility x strategic-fit),
    #  survival on RECORD. Asserted against the field list ventures.py itself declares, so a rename there
    #  cannot quietly make this leg compare against a stale set.
    import agentic_core.economy.ventures as _ven584
    assert tuple(_ven584._METRICS) == _sel584.FUNDING_POTENTIAL_FIELDS, (
        "the funding scorer's own field list no longer matches the list selection declares it must not "
        "read, so this leg would compare against a stale set", _ven584._METRICS,
        _sel584.FUNDING_POTENTIAL_FIELDS)

    #  THE IMPORT CHECK IS WHAT DOES THE REAL WORK HERE, and the limit is stated rather than hidden:
    #  three of the five potential field names - outcome, value, benefit - are ordinary English and are
    #  dict keys in this very module, so screening the source text for them would fail on correct code.
    #  Only `feasibility` and `strategic_fit` are distinctive enough to screen by name.
    _seltree584 = _ast584.parse((_root584 / "agentic_core/organism/selection.py").read_text(encoding="utf-8"))
    _imports584 = set()
    for _n584 in _ast584.walk(_seltree584):
        if isinstance(_n584, _ast584.Import):
            _imports584.update(a.name for a in _n584.names)
        elif isinstance(_n584, _ast584.ImportFrom) and _n584.module:
            _imports584.add(_n584.module)
    assert not any("ventures" in _i584 for _i584 in _imports584), (
        "selection imports the funding scorer. Funding selects on what MIGHT happen and survival on what "
        "DID; conflating them lets a well-pitched entity outlive a well-performing one", sorted(_imports584))

    _selsrc584 = (_root584 / "agentic_core/organism/selection.py").read_text(encoding="utf-8")
    _selcode584 = _re584.sub(r"(?m)^\s*#.*$", " ",
                             _re584.sub(r'"""(?:.|\n)*?"""', " ", _selsrc584))
    #  the declaration itself names all five, so it is removed before the search - otherwise this leg
    #  would fail on the very tuple it exists to check
    _selcode584 = _re584.sub(r"FUNDING_POTENTIAL_FIELDS\s*=\s*\([^)]*\)", " ", _selcode584)
    for _pot584 in ("feasibility", "strategic_fit"):
        assert _pot584 not in _selcode584, (
            "selection reads a §4 Stage 4 POTENTIAL field by name", _pot584)
    #  and the measures it DOES read are exactly the four §8 names
    _m584 = _sel584.measure_entity("vsb-w584")["measures"]
    assert set(_m584) == set(_sel584.MEASURES), sorted(_m584)

    # ── L6. CLAUSE (6): THE DEAD FITNESS STUBS ARE GONE ────────────────────────────────────────────
    for _gone584 in ("fitness.py", "evolution.py", "population.py"):
        _p584 = _root584 / "agentic_core/genetic_immune/genome" / _gone584
        assert not _p584.exists(), (
            "a dead genome stub is still present. FitnessFunction.evaluate returned 1.0 for every "
            "individual, EvolutionEngine.evolve returned its argument and Population was a list wrapper",
            _gone584)
    #  the siblings that ARE imported must survive - a deletion that took them would break 10 call sites
    for _kept584 in ("chromosome.py", "gene.py"):
        assert (_root584 / "agentic_core/genetic_immune/genome" / _kept584).exists(), (
            "a genome module that IS imported was deleted with the dead ones", _kept584)
    #  nothing imports a fitness that returns a constant
    #  A GUARD CANNOT SEARCH ITS OWN FILE. The first cut walked every live .py and failed on THIS test,
    #  which names the deleted modules in the very assertion that forbids importing them. The scan is
    #  scoped to where a live import could actually be - the package and its scripts - and the limit is
    #  stated: a reference from a test would not be caught here, which is acceptable because a test
    #  importing a deleted module fails by importing it.
    _live584 = [p for p in list((_root584 / "agentic_core").rglob("*.py"))
                + list((_root584 / "scripts").rglob("*.py"))
                if "_archive" not in p.parts and "node_modules" not in p.parts
                and "__pycache__" not in p.parts]
    assert len(_live584) > 200, ("the reachability scan found almost nothing, so it proves nothing",
                                len(_live584))
    for _f584 in _live584:
        _t584 = _f584.read_text(encoding="utf-8", errors="replace")
        for _dead584 in ("genetic_immune.genome.fitness", "genetic_immune.genome.population",
                         "genetic_immune.genome.evolution", "FitnessFunction"):
            assert _dead584 not in _t584, (
                "a live module references a deleted constant-returning fitness", str(_f584), _dead584)

    # ── L7. FU-405: THE FITNESS MEAN NO LONGER CLAIMS TO BE A MEASUREMENT ──────────────────────────
    import agentic_core.api.organism_status as _os584

    #  BOTH STATES ARE DRIVEN, not observed. The first cut read the store as the suite happened to leave
    #  it - empty - and asserted the POPULATED case's basis against the empty one's. Pointing the
    #  function's own data_path at a directory this test owns touches no shared store and makes neither
    #  state depend on test order. This is W583's lesson, one round later.
    _gdir584 = tmp_path / "w584genomes"
    _gdir584.mkdir()
    monkeypatch.setattr(_os584, "data_path", lambda *_a, **_k: _gdir584)

    #  (a) EMPTY: its own basis, and no mean
    _empty_gs584 = _os584._genome_state()
    assert _empty_gs584["mean_fitness"] is None and _empty_gs584["total_genomes"] == 0, _empty_gs584
    assert "no genomes stored" in _empty_gs584["mean_fitness_basis"], (
        "an empty genome store does not say that it is empty", _empty_gs584["mean_fitness_basis"])

    #  (b) POPULATED with all three provenances - which is the state the fix exists for
    for _i584, (_prov584, _fit584) in enumerate((
            ("ai-declared (unverified)", 0.8),
            ("ai-declared (unverified)", 0.6),
            ("default-unencoded (no FITNESS line parsed)", 0.5),
            ("inherited-mean-unevaluated (no selection step exists)", 0.55))):
        (_gdir584 / f"g{_i584}.json").write_text(_json584.dumps({
            "genome_id": f"genome-w584{_i584}", "entity_name": f"e{_i584}", "fitness_score": _fit584,
            "fitness_provenance": _prov584, "generation": _i584, "encoded": True,
            "traits": {"a": 0.5}}), encoding="utf-8")

    _gs584 = _os584._genome_state()
    assert _gs584["total_genomes"] == 4, _gs584
    assert _gs584["mean_fitness"] is None, (
        "a mean fitness is still published over a populated store. Nothing in this platform evaluates "
        "fitness - genome.py says so where the number is written and OrganismAnatomy.tsx says it to the "
        "reader - so a mean over self-declared guesses, unencoded defaults and inherited means is not a "
        "measurement of genetic health", _gs584["mean_fitness"])
    assert "nothing in this platform evaluates fitness" in _gs584["mean_fitness_basis"].lower(), (
        "the basis does not say WHY there is no mean", _gs584["mean_fitness_basis"])
    #  the COMPOSITION is counted, so a reader can see what the population is made of
    assert _gs584["fitness_composition"] == {"declared": 2, "default": 1, "inherited": 1}, (
        "the aggregate does not count the population by provenance, so it still discards the distinction "
        "the records keep", _gs584["fitness_composition"])
    #  and what IS true is kept rather than deleted: the self-declared mean, over the declared rows ONLY
    assert _gs584["mean_declared_fitness"] == 0.7, (
        "the self-declared mean is not the mean of the self-declared rows alone - 0.8 and 0.6 average to "
        "0.7, and including the default or the inherited row is the blend this fix removed",
        _gs584["mean_declared_fitness"])
    #  EVERY return carries the same keys - W495 made that this function's rule
    _keys584 = set(_gs584)
    _srcos584 = (_root584 / "agentic_core/api/organism_status.py").read_text(encoding="utf-8")
    for _needed584 in ("mean_fitness_basis", "mean_declared_fitness", "fitness_composition"):
        assert _srcos584.count(f'"{_needed584}"') >= 4, (
            "a new key is missing from one of _genome_state's four returns, so the function is no longer "
            "shape-complete and a reader of the error path gets a different dict", _needed584,
            _srcos584.count(f'"{_needed584}"'))
    #  AND THE BASIS REACHES THE PAGE A PERSON ACTUALLY OPENS. /api/v1/organism/status carries the
    #  corrected aggregate and NO page fetches it; OrganismAnatomy.tsx fetches /api/v1/organism/genome.
    #  Nothing on a page was wrong - no page ever rendered the mean - but a correction that reaches no
    #  reader is half a fix, so the list endpoint carries the population summary and the page renders it.
    _gl584 = client.get("/api/v1/organism/genome").json()
    assert "population" in _gl584, (
        "the endpoint the genome page actually calls carries no population summary, so the correction "
        "reaches no reader", sorted(_gl584))
    assert _gl584["population"]["mean_fitness"] is None, _gl584["population"]
    assert str(_gl584["population"]["mean_fitness_basis"]).strip(), (
        "the population summary carries no basis", _gl584["population"])
    _anat584 = (_root584 / "apps/workstation-superapp/src/pages/organism/OrganismAnatomy.tsx").read_text(
        encoding="utf-8", errors="replace")
    _acode584 = _re584.sub(r"(?m)^\s*//.*$", " ",
                           _re584.sub(r"/\*(?:.|\n)*?\*/", " ", _anat584))
    assert "{pop.mean_fitness === null ? (" in _acode584, (
        "the page does not branch on an absent population mean, so it has no way to show that nothing "
        "evaluates fitness - W503's class, so this asserts the gate with its opening brace")
    for _ptid584 in ('data-testid="genome-mean-not-measured"',
                     'data-testid="genome-fitness-composition"'):
        assert _ptid584 in _acode584, ("a population state has no rendered element", _ptid584)

    #  AND THE SECOND WRITER. heartbeat.py republishes this summary as a VITAL SIGN, and it used to copy
    #  only three fields - so after the aggregate was corrected the beat would publish mean_fitness: None
    #  with no reason at all, leaving a reader unable to tell "nothing evaluates fitness" from "the store
    #  could not be read". Fixing a writer without its reader moves the lie down a layer (W475's class).
    #  DRIVEN through the published record, not read off the source: the defect is that the vital sign
    #  loses the basis, not that a line is absent from a file.
    import agentic_core.organism.heartbeat as _hb584
    _vital584 = {"total": _gs584.get("total_genomes"),
                 "mean_fitness": _gs584.get("mean_fitness"),
                 "mean_fitness_basis": _gs584.get("mean_fitness_basis"),
                 "mean_declared_fitness": _gs584.get("mean_declared_fitness"),
                 "fitness_composition": _gs584.get("fitness_composition"),
                 "max_generation": _gs584.get("max_generation")}
    _hbsrc584 = (_root584 / "agentic_core/organism/heartbeat.py").read_text(encoding="utf-8")
    _assign584 = _hbsrc584.split("self.last_genome = {", 1)
    assert len(_assign584) == 2, "the heartbeat no longer assigns last_genome at all"
    _block584 = _assign584[1].split("}", 1)[0]
    for _vk584 in ("mean_fitness_basis", "mean_declared_fitness", "fitness_composition"):
        assert _vk584 in _block584, (
            "the heartbeat's genome VITAL SIGN drops a field that says what the number is worth, so the "
            "beat publishes an unexplained null - the second-writer class", _vk584, _block584)
    #  and the live beat really does carry it, so the check above is not merely about a source line
    _hb_obj584 = getattr(_hb584, "heartbeat", None)
    if _hb_obj584 is not None and getattr(_hb_obj584, "last_genome", None):
        assert "mean_fitness_basis" in _hb_obj584.last_genome, (
            "a beat has already run and its recorded vital sign carries no basis",
            sorted(_hb_obj584.last_genome))
    assert set(_vital584) >= {"mean_fitness", "mean_fitness_basis"}, _vital584

    #  and the reader's fallback is no longer a different number from the writer's
    _gsrc584 = (_root584 / "agentic_core/organism/genome.py").read_text(encoding="utf-8")
    assert 'g.get("fitness_score", 0.0)' not in _gsrc584, (
        "one field still has two different fallbacks: the writer uses 0.5 and this reader used 0.0, and "
        "0.0 reads as the WORST possible fitness rather than a midpoint")

    # ── L8. FU-406: THE NIYYAH GATE INVENTS NO FIGURE, AND ITS REFUSAL IS REACHABLE ────────────────
    import asyncio as _aio584

    from agentic_core.divine.v2.alignment_v2 import DivineAlignmentEngineV2 as _DA584
    _eng584 = _DA584()
    #  the same five opposite intents that exposed it: it must no longer answer the same pass for all
    _answers584 = [_aio584.run(_eng584.calibrate_niyyah(_i584)) for _i584 in
                   ("build a hospital", "defraud every user", "", "DESTROY EVERYTHING")]
    for _a584 in _answers584:
        assert _a584["passed"] is None and _a584["assessed"] is False, (
            "the niyyah gate still returns a verdict. Driven with four opposite intents it answered "
            "0.9222 and passed=True for every one, because it never read its intent argument at all",
            _a584)
        assert _a584["sincerity"] is None, (
            "a SINCERITY FIGURE is still produced. Ruling A.9.5 forbids an AI verdict on a person's "
            "spiritual state, and this repository already registers sincerity_integrity_loyalty as "
            "permanently NOT ASSESSABLE under its own rule that an invented number is worse than a "
            "missing one", _a584["sincerity"])
        assert _a584["alignment_score"] is None, _a584
        assert "A.9.5" in _a584["basis"], (
            "the refusal does not cite the ruling that forbids the figure it is refusing to produce")
    #  an absent metric makes the SCORE None rather than weighting it as a zero
    assert _aio584.run(_eng584.calculate_divine_alignment_score({}, {})) is None, (
        "an absent metric is still weighted as 0.0, so this returns a number about nothing")
    #  ...and a real set of metrics DOES score, which is what makes a refusal reachable rather than
    #  decorative: a gate whose failing branch cannot be reached is not a gate
    _low584 = _aio584.run(_eng584.calculate_divine_alignment_score(
        {"faithfulness": 0.1, "sincerity": 0.1, "maslaha": 0.1},
        {"user_value": 0.1, "efficiency": 0.1, "legal_compliance": 0.1}))
    assert _low584 is not None and _low584 < 0.85, (
        "a real low metric set does not produce a failing score, so the gate's False branch is still "
        "unreachable", _low584)

    #  THE GATE ITSELF, both branches driven
    from agentic_core.governance.uci_interceptor import RecirculationPreflight as _U584

    async def _ok584():
        return {"ok": True}

    _u584 = _U584("w584-guard")
    _proceeded584 = _aio584.run(_u584.intercept({"intent": "anything at all"}, _ok584))
    assert isinstance(_proceeded584, dict) and _proceeded584.get("status"), (
        "an UNASSESSED niyyah blocked the action. A check that did not happen must neither bless nor "
        "block - it is recorded as an absence", _proceeded584)

    #  AND WHAT IT WRITES INTO THE CHAIN. This field carried a hardcoded 0.9 sincerity into the
    #  hash-chained UEG for every intercepted action, so what is recorded is the point of the fix. The
    #  write is captured rather than read back off disk, because the property is that the record carries
    #  the ABSENCE - a log call is not a print, so no source-reading screen can see this.
    _logged584 = []
    _u3584 = _U584("w584-guard-ledger")
    _orig_log584 = _u3584.ueg.log_minimisation_event

    async def _capture584(kind, payload):
        _logged584.append((kind, payload))
        return await _orig_log584(kind, payload)

    _u3584.ueg.log_minimisation_event = _capture584
    _aio584.run(_u3584.intercept({"intent": "anything at all"}, _ok584))
    _converged584 = [p for k, p in _logged584 if "converged" in str(k)]
    assert _converged584, ("the interceptor recorded no completion event at all",
                           [k for k, _ in _logged584])
    _payload584 = _converged584[-1]
    assert _payload584.get("sincerity") is None, (
        "a sincerity figure is still written into the tamper-evident chain. This field carried a "
        "hardcoded 0.9 for every intercepted action, and A.9.5 forbids an AI verdict on a person's "
        "spiritual state", _payload584.get("sincerity"))
    assert _payload584.get("niyyah_assessed") is False, (
        "the record does not say that nothing was assessed, so a reader of the chain cannot tell an "
        "unassessed gate from a passed one", _payload584)
    assert str(_payload584.get("niyyah_basis") or "").strip(), (
        "the record carries no reason for the absence", _payload584)

    _u2584 = _U584("w584-guard-refuse")

    async def _refuse584(intent, framework="islamic_khayr"):
        return {"passed": False, "assessed": True, "sincerity": None, "basis": "a real refusal"}

    _u2584.divine.calibrate_niyyah = _refuse584
    with pytest.raises(PermissionError) as _ei584:
        _aio584.run(_u2584.intercept({"intent": "x"}, _ok584))
    assert "REFUSED" in str(_ei584.value), (
        "the gate does not refuse on a real negative verdict, so it has exactly one reachable outcome - "
        "which is what it had before, with the opposite sign", str(_ei584.value))

    #  and the self-healing branch is reachable at all: it called a method that does not exist
    _ucisrc584 = (_root584 / "agentic_core/governance/uci_interceptor.py").read_text(encoding="utf-8")
    assert "self.regulator.repair_tier(" not in _ucisrc584, (
        "the interceptor still calls regulator.repair_tier, which does not exist - the v2/v140 "
        "consolidation renamed it to `repair`, so the handler for a failing action was itself a failure")
    import agentic_core.change_control.regulator as _reg584
    assert hasattr(_reg584.Regulator, "repair"), "the method the interceptor now calls does not exist"
def test_w585_p33_the_cadence_layers_refresh_themselves_and_say_why(client, monkeypatch, tmp_path):
    """P3.3 §17.3 — the Strategic and Action-Plan layers refresh on a cadence, and the pack is made of them.

    MEASURED BEFORE BUILDING. The cadence existed only as PROMPT TEXT: the four occurrences of strategic
    / cadence / quarterly / weekly in api/management_systems.py are all inside a request to a model, and
    nothing fired. api/board.py published a `ceo_action_plan` composed by a model call made at pack time,
    which is the shape clause (3) is written against — a pack that reads elsewhere looks identical
    whatever the refreshes say.

    EVERY TRIGGER IS FORCED, NEVER WAITED FOR, which is clause (1)'s own wording. `due()` takes `now` and
    the signal as ARGUMENTS, so this drives a quarter's passage and a market signal without touching a
    clock. A due-check buried in the beat would have left this leg asserting the source instead.
    """
    import ast as _ast585
    import asyncio as _aio585
    import pathlib as _pl585
    import time as _t585

    from agentic_core.api import business_plan as _bp585
    from agentic_core.organism import cadence as _cad585

    _root585 = _pl585.Path(__file__).resolve().parents[1]
    _scope585 = "w585probe"
    _NOW585 = 1800000000.0

    def _stamp585(ts):
        return _t585.strftime("%Y-%m-%dT%H:%M:%SZ", _t585.gmtime(ts))

    # ── L1. CLAUSE (1): BOTH TRIGGERS, FOR BOTH LAYERS, FORCED RATHER THAN WAITED FOR ──────────────
    #  a quarter and a week are the elapsed periods §17.3 names; the module declares them so this leg
    #  computes with the same numbers rather than re-deriving one it hopes matches
    assert _cad585.PERIOD_SECONDS[_cad585.STRATEGIC] > _cad585.PERIOD_SECONDS[_cad585.ACTION_PLAN], (
        "the strategic period is not longer than the action-plan period, so quarterly and weekly have "
        "been swapped", _cad585.PERIOD_SECONDS)

    for _layer585 in _cad585.LAYERS:
        _period585 = _cad585.PERIOD_SECONDS[_layer585]
        #  NEVER REFRESHED is its own state, not an age of zero
        _never585 = _cad585.due(_layer585, None, now=_NOW585)
        assert _never585["due"] is True and _never585["trigger"] == _cad585.TRIGGER_NEVER_REFRESHED, _never585
        assert "NEVER been refreshed" in _never585["reason"], (
            "a layer that has never refreshed is not distinguished from one refreshed long ago - they "
            "produce the same answer today and different reasons, and the reason is what is acted on",
            _never585["reason"])
        #  INSIDE the period: not due, and the reason says a signal would fire it anyway
        _fresh585 = _cad585.due(_layer585, _stamp585(_NOW585 - 86400), now=_NOW585)
        assert _fresh585["due"] is False, (_layer585, "a layer refreshed yesterday is reported due",
                                           _fresh585)
        #  ELAPSED: forced by passing a `now` past the period, never by waiting
        _old585 = _cad585.due(_layer585, _stamp585(_NOW585 - _period585 - 60), now=_NOW585)
        assert _old585["due"] is True and _old585["trigger"] == _cad585.TRIGGER_ELAPSED, (_layer585, _old585)
        #  THE SIGNAL fires regardless of the clock - the second trigger's whole purpose
        _sig585 = _cad585.due(_layer585, _stamp585(_NOW585 - 86400), now=_NOW585, signal="a real signal")
        assert _sig585["due"] is True and _sig585["trigger"] == _cad585.TRIGGER_SIGNAL, (_layer585, _sig585)
        assert "a real signal" in _sig585["reason"], (
            "the signal that fired the refresh is not named in the reason", _sig585["reason"])
    #  an unknown layer is refused rather than silently treated as one of the two
    with pytest.raises(ValueError):
        _cad585.due("not_a_layer", None)

    #  AND IT IS HEARTBEAT-DRIVEN, driven for real. A refresh behind a route is a button; the clause
    #  says heartbeat-driven, so the beat is run and the refresh is read back out of the plan.
    import agentic_core.organism.heartbeat as _hb585

    #  THE STATE IS DRIVEN, NOT OBSERVED. The first cut asserted `cadence_refresh` in the actions of the
    #  beat it ran, and in the suite's shared store an earlier beat had already refreshed both layers -
    #  so by beat 2 nothing was due and the action was correctly absent. That made the leg pass or fail
    #  on who ran first. Both layers' histories are aged past their own periods first, so a refresh is
    #  genuinely due when the beat visits and its absence would be a real failure.
    _wsplan585 = _bp585._load("workstation")
    for _entry585 in (_wsplan585.get("refreshes") or []):
        if isinstance(_entry585, dict):
            _entry585["at"] = _stamp585(_NOW585 - 400 * 86400)
    _bp585._save(_wsplan585)
    for _layer585 in _cad585.LAYERS:
        assert _cad585.due(_layer585, _cad585.last_refresh_at(_bp585._load("workstation"), _layer585))["due"], (
            "the aged history did not make this layer due, so the beat below would prove nothing",
            _layer585)

    _beat585 = _aio585.run(_hb585.heartbeat.beat())
    assert isinstance(_beat585, dict), ("the beat did not return its record", type(_beat585).__name__)
    assert "cadence_refresh" in (_beat585.get("actions") or []), (
        "a layer was DUE and the beat did not refresh it, so the cadence is not heartbeat-driven - a "
        "refresh behind a route is a button, not a cadence", _beat585.get("actions"),
        #  W589 — THE BEAT'S OWN REASON, which the step used to swallow with a bare `except: pass`. Without
        #  it this failure reported an absent action and nothing else, so a run that failed in the full
        #  suite and passed in isolation could not be diagnosed from its output at all.
        {"last_cadence": getattr(_hb585.heartbeat, "last_cadence", None)})
    _state585 = _cad585.state("workstation")
    for _layer585 in _cad585.LAYERS:
        assert _state585["layers"][_layer585]["ever_refreshed"] is True, (
            "a real heartbeat did not refresh this layer", _layer585,
            _state585["layers"][_layer585])
        #  and the layer is no longer due, because the beat actually wrote
        assert _state585["layers"][_layer585]["due"]["due"] is False, (
            "the layer is still due after the beat refreshed it, so nothing was written",
            _layer585, _state585["layers"][_layer585]["due"])
    assert _hb585.heartbeat.last_cadence, (
        "the beat refreshed a layer and recorded nothing on last_cadence, so the organism's status "
        "cannot report what the beat did")
    _did585 = {_r585["layer"] for _r585 in (_hb585.heartbeat.last_cadence.get("refreshed") or [])}
    assert _did585 == set(_cad585.LAYERS), (
        "the beat refreshed only some of the layers that were due", sorted(_did585))

    # ── L1b (W589). A CADENCE THAT CANNOT RUN IS VISIBLE WHERE A PERSON READS, not only in a test ──
    #  The step used to end in `except Exception: pass`, so a cadence that had STOPPED FIRING was
    #  indistinguishable from one with nothing due: both appended no action and left no trace. It now records
    #  the reason - and a record nothing surfaces is only readable by a guard, which is barely better. No page
    #  fetches this route, so the route's own response is the surface, and this asserts the key is in it.
    _api585 = client.get("/api/v1/organism/cadence")
    assert _api585.status_code == 200, (_api585.status_code, _api585.text[:200])
    _lb585 = _api585.json().get("last_beat")
    assert isinstance(_lb585, dict), (
        "the cadence route reports the plan's layer states but not what the last BEAT managed, so a cadence "
        "that has stopped firing cannot be seen at all", _api585.json().keys())
    assert _lb585["ran"] is True and _lb585["could_not_run"] is None, _lb585
    assert {_r585["layer"] for _r585 in _lb585["refreshed"]} == set(_cad585.LAYERS), _lb585
    #  AND THE ROUTE SAYS WHY THERE ARE TWO RECORDS. Without this a reader who sees a layer reported DUE
    #  beside a last beat that could not run has no way to tell two different questions from a contradiction.
    _lbb585 = _api585.json().get("last_beat_basis") or ""
    assert "plan" in _lbb585 and "last_beat" in _lbb585, (
        "the route reports both the plan's layer states and the last beat's outcome without saying which "
        "question each one answers", _lbb585[:200])

    #  DRIVEN. The failure path is made to happen, because asserting the healthy shape would pass equally
    #  well with the failure path broken - a healthy beat never produces a reason to render.
    _savedc585 = _hb585.heartbeat.last_cadence
    _origref585 = _cad585.refresh
    try:
        def _boom585(*_a585, **_k585):
            raise RuntimeError("w589 driven cadence failure")
        _cad585.refresh = _boom585
        _aio585.run(_hb585.heartbeat.beat())
        _fail585 = client.get("/api/v1/organism/cadence").json()["last_beat"]
        assert _fail585["could_not_run"], (
            "the cadence raised on every layer and the surface reports no failure, so a stopped cadence "
            "still reads as a quiet one", _fail585)
        assert "RuntimeError" in str(_fail585["could_not_run"]), (
            "the surface reports a failure without saying what it was", _fail585["could_not_run"])
        assert _fail585["refreshed"] == [], (
            "a beat that refreshed nothing reports refreshed layers", _fail585)
        assert "still" in str(_fail585["basis"]).lower() and "due" in str(_fail585["basis"]).lower(), (
            "the basis does not say that a layer which could not run is STILL DUE, which is the whole "
            "difference between this state and 'nothing was due'", _fail585["basis"])
    finally:
        _cad585.refresh = _origref585
        _hb585.heartbeat.last_cadence = _savedc585
    assert _cad585.refresh is _origref585, "the cadence refresh was left patched"
    assert _hb585.heartbeat.last_cadence is _savedc585, "the beat's cadence record was left failed"

    # ── L2. CLAUSE (2): PROVENANCE, A HISTORY, AND WHAT THE REFRESH DISPLACED ──────────────────────
    #  the Owner's own strategy text goes in first, so the overwrite this clause is about really happens
    _plan585 = _bp585._load(_scope585)
    _plan585["strategy"] = "THE OWNER WROTE THIS STRATEGY"
    _plan585["vision"] = "a vision on record"
    _plan585["objectives"] = [{"id": "o1", "title": "ship the thing", "status": "planned",
                               "progress_pct": 0}]
    _bp585._save(_plan585)

    _r1585 = _cad585.refresh(_scope585, _cad585.STRATEGIC, now=_NOW585)
    assert _r1585["refreshed"] is True, _r1585
    _e585 = _r1585["entry"]
    for _k585 in ("id", "layer", "at", "trigger", "reason", "content", "served_by", "provenance_basis"):
        assert _e585.get(_k585) not in (None, ""), ("a history entry is missing a field a reader needs",
                                                    _k585, _e585)
    assert _e585["is_external"] is False and _e585["served_by"] == "deterministic-floor", (
        "the default composition does not declare itself the deterministic floor, so a derived paragraph "
        "could be read as one a model composed", _e585)
    #  IT WROTE TO THE PLAN
    _after585 = _bp585._load(_scope585)
    assert _after585["strategy"] == _e585["content"], (
        "the refresh did not write to the plan at all", _after585.get("strategy"))
    #  AND THE HISTORY KEPT WHAT IT REPLACED. An entry recording only the new text still loses the old.
    assert _e585["replaced"] == "THE OWNER WROTE THIS STRATEGY", (
        "the refresh overwrote the plan and the history does not carry what it displaced - clause (2) "
        "fails an overwrite without a history entry, and an entry that drops the old text is the same "
        "loss one layer down", _e585.get("replaced"))
    assert len(_after585.get("refreshes") or []) == 1, _after585.get("refreshes")

    #  A SECOND CALL INSIDE THE PERIOD WRITES NOTHING, so a caller on every beat cannot churn the plan
    _r2585 = _cad585.refresh(_scope585, _cad585.STRATEGIC, now=_NOW585 + 86400)
    assert _r2585["refreshed"] is False and "not due" in _r2585["basis"], _r2585
    assert len(_bp585._load(_scope585).get("refreshes") or []) == 1, "a not-due call appended a history entry"

    #  A SIGNAL FIRES IT ANYWAY, and the entry names the signal
    _r3585 = _cad585.refresh(_scope585, _cad585.STRATEGIC, now=_NOW585 + 86400,
                             signal="a competitor exited the market")
    assert _r3585["refreshed"] is True and _r3585["entry"]["signal"] == "a competitor exited the market"
    #  ...and the Owner's text is STILL readable in the first entry, two refreshes later
    _hist585 = _cad585.history(_scope585, _cad585.STRATEGIC)
    assert _hist585[0]["replaced"] == "THE OWNER WROTE THIS STRATEGY", (
        "the Owner's displaced text was lost by a later refresh", _hist585[0].get("replaced"))

    #  A FORCED REFRESH SAYS IT WAS FORCED. One that looked due would make the history lie about why
    #  the plan changed.
    _r4585 = _cad585.refresh(_scope585, _cad585.STRATEGIC, now=_NOW585 + 2 * 86400, force=True)
    assert _r4585["refreshed"] is True and _r4585["entry"]["forced"] is True, _r4585["entry"]
    assert "FORCED" in _r4585["entry"]["reason"], _r4585["entry"]["reason"]

    #  THE ROUTE carries the history to a reader, with its states
    _cj585 = client.get(f"/api/v1/organism/cadence?scope={_scope585}").json()
    assert _cj585["history_count"] >= 3, _cj585["history_count"]
    assert _cj585["layers"][_cad585.STRATEGIC]["ever_refreshed"] is True, _cj585["layers"]
    assert _cj585["layers"][_cad585.ACTION_PLAN]["ever_refreshed"] is False, (
        "the action-plan layer reports refreshes it never had", _cj585["layers"][_cad585.ACTION_PLAN])
    assert str(_cj585.get("method") or "").strip(), "the cadence route reports no method"
    assert client.post("/api/v1/organism/cadence/refresh?layer=not_a_layer").status_code == 422

    # ── L3. CLAUSE (3): THE PACK'S LAYERS ARE ASSEMBLED FROM THE REFRESHES ─────────────────────────
    #  "a guard changes a refresh and asserts the pack changes, because a pack that reads elsewhere
    #  would look identical" — so the assertion is on an IDENTIFIER that travels, not on similar prose.
    import agentic_core.api.vsb as _vmod585
    _s0585 = _vmod585._strategic_layer({}, None)
    assert _s0585["refresh_id"] is None and _s0585["holds"] == "empty", _s0585
    assert "EMPTY" in _s0585["basis"], (
        "with no refresh the layer no longer reports what it actually holds", _s0585["basis"])
    _fake585 = {"id": "refresh-w585aaa", "at": "2026-10-05T00:00:00Z", "trigger": "elapsed",
                "reason": "quarterly period elapsed", "content": "STRATEGY FROM THE REFRESH",
                "served_by": "deterministic-floor", "is_external": False}
    _s1585 = _vmod585._strategic_layer({}, _fake585)
    assert _s1585["refresh_id"] == "refresh-w585aaa", (
        "the pack's strategic layer does not carry the refresh it was assembled from, so changing a "
        "refresh could not be shown to change the pack", _s1585)
    assert _s1585["content"] == "STRATEGY FROM THE REFRESH" and _s1585["holds"] == "content", _s1585
    #  CHANGE THE REFRESH, THE PACK CHANGES
    _s2585 = _vmod585._strategic_layer({}, dict(_fake585, id="refresh-w585bbb",
                                                content="A DIFFERENT STRATEGY"))
    assert _s2585["refresh_id"] != _s1585["refresh_id"] and _s2585["content"] != _s1585["content"], (
        "the layer did not change when the refresh changed")
    #  and the superseded reading is KEPT rather than erased
    assert "EMPTY" in _s1585["basis"], (
        "the refresh erased the layer's previous true statement instead of superseding it")

    _a0585 = _vmod585._action_plan_layer({"chair": "someone"}, None)
    assert _a0585["holds"] == "other" and _a0585["present"] is False, _a0585
    assert "not what is to be done" in _a0585["basis"], (
        "the roster statement was dropped; a roster is still not a plan of action", _a0585["basis"])
    _a1585 = _vmod585._action_plan_layer({"chair": "someone"},
                                         dict(_fake585, id="refresh-w585ccc", content="ACTIONS"))
    assert _a1585["refresh_id"] == "refresh-w585ccc" and _a1585["present"] is True, _a1585

    #  AND IT REACHES THE PAGE. The refresh's id, time and trigger are appended to the layer's BASIS,
    #  and W573 already made GenesisJourney.tsx render every layer's state as a chip whose title is that
    #  basis - it no longer depends on the "N empty" chip, which rendered only when a layer was absent.
    #  Both halves are asserted, because either one changing alone would leave clause (3) traceable
    #  through the API and invisible to a reader.
    _est3585 = client.post("/api/v1/genesis/establish",
                           json={"problem": "a halal meal service", "domain": "care",
                                 "owner_id": "pytest-w585r", "name": "W585 Pack Reach",
                                 "concept": "meal boxes", "design": "d",
                                 "commercialisation": "subscription"})
    assert _est3585.status_code == 200, (_est3585.status_code, _est3585.text[:200])
    _vid3585 = _est3585.json()["vsb_id"]
    _rr585 = _cad585.refresh(_vid3585, _cad585.STRATEGIC, signal="a market signal arrived")
    assert _rr585["refreshed"] is True, _rr585
    _pk585 = client.post(f"/api/v1/vsb/{_vid3585}/board-pack").json()
    _ls585 = _pk585.get("layers_state") or {}
    assert set(_ls585) == {"constitutional", "strategic", "action_plan", "operational"}, sorted(_ls585)
    _sb585 = str((_ls585.get("strategic") or {}).get("basis") or "")
    assert _rr585["entry"]["id"] in _sb585, (
        "the pack's layers_state - which is what the page renders - does not carry the refresh the layer "
        "was assembled from, so the traceability stops at the API", _sb585[:200])
    assert "fired on signal" in _sb585, (
        "the layer's basis does not say WHICH trigger produced the refresh it was assembled from", _sb585[:200])
    _gj585 = (_root585 / "apps/workstation-superapp/src/pages/synthesis/GenesisJourney.tsx").read_text(
        encoding="utf-8", errors="replace")
    assert "Object.entries(pack.layers_state ?? {}).map(" in _gj585, (
        "the page no longer renders a chip per layer from layers_state, so a basis is readable only when "
        "a layer is ABSENT - which is the state W573 removed")
    assert "title={v?.basis || 'no basis is recorded for this layer'}" in _gj585, (
        "the per-layer chip no longer carries the layer's basis as its title, so the refresh that "
        "produced the layer reaches no reader")

    # ── L4. CLAUSE (4): THE VALUES ARE THE ENTITY'S OWN, OR THE FIELD SAYS THERE ARE NONE ──────────
    _PLATFORM_LINE585 = "Integrity · Compassion · Excellence · Halal/Sharia · Beneficence · Stewardship"
    _est585 = client.post("/api/v1/genesis/establish",
                          json={"problem": "a halal community meal service", "domain": "care",
                                "owner_id": "pytest-w585", "name": "W585 Cadence Probe",
                                "concept": "weekly halal meal boxes", "design": "d",
                                "commercialisation": "subscription"})
    assert _est585.status_code == 200, (_est585.status_code, _est585.text[:200])
    _vid585 = _est585.json()["vsb_id"]
    _pack585 = client.post(f"/api/v1/vsb/{_vid585}/board-pack").json()
    _const585 = _pack585["layers"]["constitutional"]
    assert _const585["values_declared"] is False, (
        "a freshly established entity is reported as having declared its own values", _const585)
    assert "NOT DECLARED" in str(_const585["values"]), (
        "the entity declared no values and the pack does not say so in the values position",
        _const585["values"])
    assert _PLATFORM_LINE585 not in str(_const585["values"]), (
        "the platform's standing values line is SHOWN as this entity's. Clause (4) says an entity with "
        "none says so RATHER THAN showing the platform's - a reader skims the values, not the source "
        "field beside them, and that line is identical for every VSB", _const585["values"])
    assert str(_const585.get("values_source") or "").strip(), (
        "values_source was dropped; it is true either way and removing a true statement is also a defect")

    #  AND WHEN THE ENTITY DECLARES ITS OWN, THEY ARE USED
    _v585 = _vmod585._load_vsb(_vid585)
    _v585["values"] = ["Sabr", "Amanah", "Ihsan"]
    _vmod585._save_vsb(_v585)
    _pack2585 = client.post(f"/api/v1/vsb/{_vid585}/board-pack").json()
    _const2585 = _pack2585["layers"]["constitutional"]
    assert _const2585["values_declared"] is True, _const2585
    for _own585 in ("Sabr", "Amanah", "Ihsan"):
        assert _own585 in str(_const2585["values"]), (
            "the entity declared its own values and the pack does not show them", _own585,
            _const2585["values"])
    assert "declared by this entity itself" in str(_const2585["values_source"]), (
        "the source does not say the values are the entity's own", _const2585["values_source"])
def test_w586_p37_the_repo_is_reachable_and_an_entity_with_none_says_so(client, tmp_path):
    """P3.7 §13 — the repo serves its real bytes, the Cockpit can open them, and products reach §12.

    MEASURED BEFORE BUILDING: vsb.py had GET /{vsb_id}/repo returning a manifest (tree + per-file byte
    counts + a ship_status) and POST /repo, /repo/ship, /repo/cascade. There was NO file endpoint and NO
    zip endpoint, the Cockpit rendered no repo tree at all, and nothing listed an ENTITY's products on the
    marketplace — a listing could CARRY a vsb_id when a person made one by hand, and the commercialise
    stage's "Commercial CoE creates marketplace listing" was a label with no mechanism.

    EVERY CLAUSE IS DRIVEN. The bytes are compared against the file on disk, the containment refusals are
    driven rather than read, the no-repo states are produced by removing the manifest and by moving the
    files, and the products are listed after a deliverable is really produced.
    """
    import io as _io586
    import json as _json586
    import pathlib as _pl586
    import re as _re586
    import zipfile as _zf586

    import agentic_core.api.vsb as _vstore586
    from agentic_core.config import data_path as _dp586  # noqa: F401 — kept for the manifest-path leg below

    #  W588 — THE PRODUCER'S OWN ROOT, not a re-derivation. `data_path` reads the environment when it is
    #  CALLED, so calling it at assert time resolved into a readme-figures temp root on CI while the repo
    #  had been written under the root the app booted with — green locally, red on CI, which is the
    #  environment-assumption shape this programme records for DATA_DIR. `vsb._REPO_STORE` is bound at
    #  import and is the root the writer used, so it cannot disagree with the writer.
    _store586 = _vstore586._REPO_STORE

    _root586 = _pl586.Path(__file__).resolve().parents[1]

    _est586 = client.post("/api/v1/genesis/establish",
                          json={"problem": "a halal meal service", "domain": "care",
                                "owner_id": "pytest-w586", "name": "W586 Repo Probe",
                                "concept": "meal boxes", "design": "d",
                                "commercialisation": "subscription"})
    assert _est586.status_code == 200, (_est586.status_code, _est586.text[:200])
    _vid586 = _est586.json()["vsb_id"]

    # ── L1. CLAUSE (1): A REAL FILE AND A REAL ZIP, AND THE BYTES ARE THE REPO'S ───────────────────
    _m586 = client.get(f"/api/v1/vsb/{_vid586}/repo")
    assert _m586.status_code == 200, (
        "an entity established through genesis has no repo manifest, so this leg cannot test one",
        _m586.status_code)
    _tree586 = _m586.json().get("tree") or []
    assert len(_tree586) >= 3, ("the repo declares almost nothing, so the tests below prove little",
                               _tree586)

    _one586 = _tree586[0]
    _f586 = client.get(f"/api/v1/vsb/{_vid586}/repo/file", params={"path": _one586})
    assert _f586.status_code == 200, (_f586.status_code, _f586.text[:200])
    #  THE BYTES ARE THE REPO'S — compared against the file on disk, not merely non-empty
    _disk586 = (_store586 / _vid586 / _one586)
    assert _disk586.is_file(), ("the declared file is not on disk, so this comparison proves nothing",
                               str(_disk586))
    assert _f586.content == _disk586.read_bytes(), (
        "the file endpoint served something other than the bytes on disk", _one586)
    assert _f586.headers.get("X-Repo-Bytes") == str(len(_f586.content)), (
        "the byte count the response reports disagrees with what it served", _f586.headers.get("X-Repo-Bytes"))

    #  CONTAINMENT, DRIVEN BOTH WAYS. The bar for the sibling item puts it plainly: asserted by driving a
    #  read of a sibling directory and seeing it refused, not by reading the code.
    for _bad586 in ("../../../etc/passwd", "../README.md", "not/declared.md",
                    f"../{_vid586}_other/README.md"):
        _br586 = client.get(f"/api/v1/vsb/{_vid586}/repo/file", params={"path": _bad586})
        assert _br586.status_code in (400, 404), (
            "a path outside the repo's declared tree was SERVED", _bad586, _br586.status_code)
    #  a file that exists on disk but is NOT declared is also refused: the manifest is the allow-list
    _undeclared586 = _store586 / _vid586 / "w586_not_declared.txt"
    _undeclared586.write_bytes(b"on disk, not in the manifest")
    try:
        _ur586 = client.get(f"/api/v1/vsb/{_vid586}/repo/file",
                            params={"path": "w586_not_declared.txt"})
        assert _ur586.status_code == 404, (
            "a file on disk that the manifest does not declare was served; the manifest is the allow-list",
            _ur586.status_code)
    finally:
        _undeclared586.unlink()

    #  CONTAINMENT, ISOLATED FROM THE ALLOW-LIST. A blind proved that disabling the resolved-path check
    #  changed nothing, because every bad path above is already refused by the manifest - the property is
    #  DOUBLY HELD (W497's shape). So the manifest is made to DECLARE a traversing path: the allow-list
    #  then passes it and only the containment check can refuse it. Without that check this is served.
    _mpath586 = _store586 / f"{_vid586}.manifest.json"
    _manraw586 = _mpath586.read_bytes()
    _outside586 = _store586 / "w586_outside_the_root.txt"
    _outside586.write_bytes(b"this file is OUTSIDE the repo root")
    try:
        _mdoc586 = _json586.loads(_manraw586.decode("utf-8"))
        _mdoc586["tree"] = list(_mdoc586.get("tree") or []) + ["../w586_outside_the_root.txt"]
        _mpath586.write_bytes(_json586.dumps(_mdoc586, indent=2).encode("utf-8"))
        _esc586 = client.get(f"/api/v1/vsb/{_vid586}/repo/file",
                             params={"path": "../w586_outside_the_root.txt"})
        assert _esc586.status_code == 400, (
            "a path the MANIFEST declares but which resolves outside the repo root was served. The "
            "allow-list cannot catch this one - it is declared - so only the resolved-path containment "
            "check stands between a manifest and any file on the machine", _esc586.status_code,
            _esc586.content[:120])
        assert b"outside this repo" in _esc586.content or "outside" in str(_esc586.json().get("detail", "")), (
            "the refusal does not say the path escaped the root", _esc586.content[:160])
    finally:
        _mpath586.write_bytes(_manraw586)
        _outside586.unlink(missing_ok=True)
    assert _mpath586.read_bytes() == _manraw586, "the manifest was not restored byte-exact"

    #  AND A DECLARED FILE THAT IS MISSING IS NAMED, not quietly dropped. A blind proved this leg absent:
    #  no file was ever missing in the run, so a silent omission and a complete archive looked identical.
    #  A short archive that looks complete is the quieter defect - a caller who unzips it cannot tell.
    _victim586 = _tree586[-1]
    _vpath586 = _store586 / _vid586 / _victim586
    _vraw586 = _vpath586.read_bytes()
    try:
        _vpath586.unlink()
        _short586 = client.get(f"/api/v1/vsb/{_vid586}/repo/zip")
        assert _short586.status_code == 200, _short586.status_code
        assert _victim586 in (_short586.headers.get("X-Repo-Missing") or ""), (
            "a file the manifest declares was missing from disk and the archive did not NAME it, so a "
            "short archive is indistinguishable from a complete one", _victim586,
            _short586.headers.get("X-Repo-Missing"))
        _sz586 = _zf586.ZipFile(_io586.BytesIO(_short586.content))
        assert _victim586 not in _sz586.namelist(), (
            "the missing file is reported missing AND present in the archive", _victim586)
    finally:
        _vpath586.write_bytes(_vraw586)
    assert _vpath586.read_bytes() == _vraw586, "the removed file was not restored byte-exact"

    #  THE ZIP holds exactly what the manifest declares, and its bytes match the file endpoint's
    _z586 = client.get(f"/api/v1/vsb/{_vid586}/repo/zip")
    assert _z586.status_code == 200, (_z586.status_code, _z586.text[:200])
    assert _z586.headers.get("content-type") == "application/zip", _z586.headers.get("content-type")
    assert _z586.headers.get("X-Repo-Missing") == "none", (
        "the archive is short of files the manifest declares", _z586.headers.get("X-Repo-Missing"))
    _zip586 = _zf586.ZipFile(_io586.BytesIO(_z586.content))
    assert set(_zip586.namelist()) == set(_tree586), (
        "the archive and the manifest disagree about what this repo contains",
        sorted(set(_tree586) ^ set(_zip586.namelist()))[:6])
    assert _zip586.read(_one586) == _f586.content, (
        "the same file has different bytes in the archive and from the file endpoint", _one586)

    # ── L2. CLAUSE (2): THE COCKPIT OPENS THEM, THROUGH THE AUTHENTICATED CLIENT ───────────────────
    _cp586 = (_root586 / "apps/workstation-superapp/src/pages/enterprise/VSBCockpit.tsx").read_text(
        encoding="utf-8", errors="replace")
    _cpcode586 = _re586.sub(r"(?m)^\s*//.*$", " ",
                            _re586.sub(r"/\*(?:.|\n)*?\*/", " ", _cp586))
    #  it FETCHES the tree, a file and the zip
    for _needle586 in ("/repo`, { validateStatus", "/repo/file`", "/repo/zip`"):
        assert _needle586 in _cpcode586, (
            "the Cockpit does not reach this repo surface at all", _needle586)
    #  THE D-BEARER CLASS: every one of them goes through axios, and NO raw anchor points at the route.
    #  lib/auth.ts attaches `Authorization: Bearer <token>` with a request interceptor, which an <a href>
    #  never carries - so a raw link 401s the moment auth is switched on.
    assert "axios.get(`/api/v1/vsb/${selected}/repo/file`" in _cpcode586, (
        "the file is not fetched through axios, so the Bearer the interceptor attaches would not travel")
    assert "axios.get(`/api/v1/vsb/${selected}/repo/zip`" in _cpcode586, (
        "the archive is not fetched through axios, so the download would be unauthenticated")
    assert not _re586.search(r"href=\{?[\"`']?/api/v1/vsb/", _cpcode586), (
        "a RAW ANCHOR points at a user-scoped API route - it carries no Bearer and 401s the moment auth "
        "is on, which is the D-BEARER class this clause names")
    #  the tree is CLICKABLE: a button per path, wired to the opener
    assert "onClick={() => openRepoFile(p)}" in _cpcode586, (
        "the tree's entries are not wired to anything, so it is a list and not a clickable tree")
    for _tid586 in ('data-testid="cockpit-repo-tree"', 'data-testid="cockpit-repo-preview"',
                    'data-testid="cockpit-repo-zip"'):
        assert _tid586 in _cpcode586, ("a repo surface has no rendered element", _tid586)

    # ── L3. CLAUSE (3): THE ENTITY'S PRODUCTS, ON THE MARKETPLACE, UNPRICED IN THE RECORD ──────────
    #  W594 (R5) — §17.5's KPI GATE IS A NEW PRECONDITION IN FRONT OF THIS. Release is gated on the
    #  owning entity's objectives carrying KPIs, and `_seed_plan_from_journey` gives every entity three
    #  TEMPLATE objectives with empty ones — so this guard, whose subject is repo reachability, was
    #  blocked by a gate it is not about. It satisfies the precondition, and asserts the gate DOES block
    #  without it, which makes the leg stronger than it was.
    _blocked586 = client.post(f"/api/v1/marketplace/listings/from-entity/{_vid586}")
    assert _blocked586.status_code == 409 and \
        _blocked586.json()["detail"]["reason"] == "kpi_not_set", (
        "§17.5's KPI gate does not block a release whose objectives carry no KPI",
        _blocked586.status_code, _blocked586.text[:200])
    assert _blocked586.json()["detail"]["missing_kpi"], (
        "the gate refuses without naming which objectives lack a KPI", _blocked586.text[:200])
    from agentic_core.api import business_plan as _bp586
    _plan586 = _bp586._load(_vid586)
    for _o586 in (_plan586.get("objectives") or []):
        _o586["kpi"] = "measured for this guard"
    _bp586._save(_plan586)

    #  an entity with no products SAYS SO rather than listing nothing silently
    _n586 = client.post(f"/api/v1/marketplace/listings/from-entity/{_vid586}")
    assert _n586.status_code == 200, (_n586.status_code, _n586.text[:200])
    _nj586 = _n586.json()
    assert _nj586["listed_count"] == 0 and _nj586["deliverables_found"] == 0, _nj586
    assert "produced NO deliverables" in _nj586["basis"], (
        "an entity with no products does not say so - 'no products to list' and 'products nobody listed' "
        "are different facts", _nj586["basis"])

    #  produce ONE real product. Verbatim content, so no model is called and the test is deterministic.
    _p586 = client.post("/api/v1/deliverables/produce",
                        json={"type": "report", "title": "W586 Care Report", "brief": "a real brief",
                              "vsb_id": _vid586, "content": "# Real content\nproduced verbatim",
                              "source_served_by": "w586-guard"})
    assert _p586.status_code == 200, (_p586.status_code, _p586.text[:200])
    _did586 = _p586.json().get("id")
    assert _did586, _p586.json()

    _l586 = client.post(f"/api/v1/marketplace/listings/from-entity/{_vid586}").json()
    assert _l586["deliverables_found"] == 1 and _l586["listed_count"] == 1, _l586
    _lid586 = _l586["listed"][0]["listing_id"]
    _rec586 = client.get(f"/api/v1/marketplace/listings/{_lid586}").json()
    assert _rec586["vsb_id"] == _vid586 and _rec586["origin"] == "vsb", _rec586
    assert _rec586["source_deliverable_id"] == _did586, _rec586
    #  THE RECORD SAYS IT IS UNPRICED. Before this the only thing saying so was the page's reading of a
    #  0, so an unpriced product and one priced at zero were the same record.
    assert _rec586["priced"] is False, _rec586
    assert "NOT PRICED" in _rec586["price_basis"], (
        "the listing carries no statement that nobody priced it", _rec586.get("price_basis"))
    assert "not a price of zero" in _rec586["price_basis"] or "read as a price" in _rec586["price_basis"], (
        "the basis does not distinguish the ABSENCE of a price from a price of zero",
        _rec586["price_basis"])

    #  LISTING IT TWICE DOES NOT DOUBLE IT: an entity's apparent catalogue must not grow without
    #  anything being produced.
    _again586 = client.post(f"/api/v1/marketplace/listings/from-entity/{_vid586}").json()
    assert _again586["listed_count"] == 0 and _again586["already_listed"] == [_did586], _again586

    #  AND SOMETHING IN THE APP ACTUALLY CALLS IT. The clause says the entity's products ARE listed; a
    #  route nobody invokes leaves that exactly as true as the commercialise stage's label was, and the
    #  pre-flight's key screen caught precisely that - no page fetched the route at all.
    assert "axios.post(`/api/v1/marketplace/listings/from-entity/${selected}`" in _cpcode586, (
        "nothing in the app lists an entity's products, so the mechanism exists and is never invoked")
    for _ltid586 in ('data-testid="cockpit-list-products"', 'data-testid="cockpit-listed-result"'):
        assert _ltid586 in _cpcode586, ("the listing action has no rendered element", _ltid586)

    #  and the PAGE reads the record's statement while keeping its own true fallback for older listings
    _mp586 = (_root586 / "apps/workstation-superapp/src/pages/marketplace/LivingMarketplace.tsx").read_text(
        encoding="utf-8", errors="replace")
    _mpcode586 = _re586.sub(r"(?m)^\s*//.*$", " ",
                            _re586.sub(r"/\*(?:.|\n)*?\*/", " ", _mp586))
    assert "typeof l.priced === 'boolean' ? l.priced : l.price_wst > 0" in _mpcode586, (
        "the page does not prefer the record's own statement, or has DROPPED the price_wst fallback that "
        "is still true of every listing written before that field existed")
    assert 'data-testid="listing-unpriced"' in _mpcode586, (
        "nothing on the page is marked as the unpriced statement")
    assert "unpriced" in _mpcode586.lower(), "the page no longer says a product is unpriced at all"

    # ── L4. CLAUSE (4): AN ENTITY WITH NO REPO IS SAID TO HAVE NONE, NEVER SHOWN AS AN EMPTY TREE ──
    #  TWO STATES, driven separately, because they are different facts
    _man586 = _store586 / f"{_vid586}.manifest.json"
    _saved586 = _man586.read_bytes()
    try:
        _man586.unlink()
        for _ep586 in ("file", "zip"):
            _r586 = client.get(f"/api/v1/vsb/{_vid586}/repo/{_ep586}",
                               params={"path": _one586} if _ep586 == "file" else None)
            assert _r586.status_code == 404, (_ep586, _r586.status_code)
            _d586 = str(_r586.json().get("detail") or "")
            assert "HAS NO REPO" in _d586 and "not an empty one" in _d586, (
                "the entity does not SAY it has no repo; an empty tree and no repo are different facts",
                _ep586, _d586[:160])
    finally:
        _man586.write_bytes(_saved586)
    assert _man586.read_bytes() == _saved586, "the manifest was not restored byte-exact"

    #  and the SECOND state: a manifest whose files are gone is its own message
    _dir586 = _store586 / _vid586
    _moved586 = _store586 / f"{_vid586}__w586moved"
    _dir586.rename(_moved586)
    try:
        _g586 = client.get(f"/api/v1/vsb/{_vid586}/repo/zip")
        assert _g586.status_code == 404, _g586.status_code
        _gd586 = str(_g586.json().get("detail") or "")
        assert "MANIFEST but its files are not on disk" in _gd586, (
            "a manifest with no files reports the same thing as no repo at all, so a reader cannot tell "
            "which", _gd586[:160])
    finally:
        _moved586.rename(_dir586)
    assert _dir586.is_dir(), "the repo directory was not restored"

    #  THE PAGE says it rather than drawing an empty tree, asserted on the GATE with its opening brace
    assert "{repoNone && (" in _cpcode586, (
        "the Cockpit does not branch on the no-repo state, so an entity with no repo would fall through "
        "to whatever the tree branch renders - W503's class, so this asserts the gate and not the field")
    assert 'data-testid="cockpit-repo-none"' in _cpcode586, (
        "the no-repo sentence has no rendered element")
    assert "repoTree === null" in _cpcode586, (
        "the page does not distinguish NOT LOADED from an empty repo, so a slow fetch reads as an entity "
        "with no files")
def test_w587_p34_the_chief_is_a_modelled_twin_or_says_it_is_a_role(client, monkeypatch, tmp_path):
    """P3.4 — the Chief is a twin built from the Owner's own record, or it says it is only a role.

    MEASURED BEFORE BUILDING. `founder_profile()` read the Owner's recent instructions from the board
    store — real — but prefixed them with a VALUES LINE THAT IS A CONSTANT IN THE SOURCE. The constant is
    unconditional, so the string always opened "FOUNDER MODEL (the Owner's lived record — reason AS this
    person)" even for an Owner who had written nothing. And the third input the clause names, DECISIONS,
    was not read at all. W492 had already forced the ROLE-versus-MODEL distinction onto the fidelity
    ledger and board.py states it in prose; what was missing was it being COMPUTED where the model is
    built.

    Clause (2) was precisely falsified: heartbeat.py's auto_align was `await align(AlignRequest(
    execute=False))` — the vision-gap router, not a board directive, and plan-only.

    AND auto_align IS NEVER LEFT ON. It is one of the autonomy keys the Owner sets and defaults to False;
    this guard sets it for its own beat inside a try/finally and asserts the restore.
    """
    import asyncio as _aio587
    import pathlib as _pl587
    import re as _re587

    from agentic_core.api import board as _b587
    from agentic_core.api import change_control as _cca587

    #  BOTH STORES THIS MODEL READS ARE DRIVEN, not one. `founder_model()` counts three inputs and the
    #  second is the Owner's recorded DECISIONS, read from the Change Control store. Emptying only the
    #  board store made the ROLE leg pass in isolation and fail in the full suite, where an earlier
    #  ratification guard leaves a ratified change on record for the rest of the session - so the Chief
    #  was a twin and the leg that proves a Chief with no inputs is a ROLE went red.
    #  REDIRECTED, NOT STUBBED: `_cca_path()` and every glob read this global on each call, so the REAL
    #  reader runs against a real but empty directory, which is what makes "reads zero" worth asserting.
    _ccadir587 = tmp_path / "cca_w587"
    _ccadir587.mkdir(parents=True, exist_ok=True)
    monkeypatch.setattr(_cca587, "_CCA_STORE", _ccadir587)
    assert _b587._owner_decisions() == [], (
        "the decisions store was redirected and still yields decisions, so this guard is reading state it "
        "does not control and its ROLE leg cannot be trusted")

    # ── L1. CLAUSE (1): THREE INPUTS, EACH COUNTED — AND A CHIEF WITH NONE IS A ROLE ───────────────
    #  the store is emptied for this leg, so the ROLE state is DRIVEN rather than hoped for: in a
    #  shared store an earlier test's directive would make every Chief a twin and this leg vacuous.
    _rows587 = _b587._load()
    try:
        _b587._save([])
        _role587 = _b587.founder_model()
        assert _role587["is_modelled_twin"] is False, (
            "an Owner who has written nothing is reported as a modelled twin", _role587)
        assert _role587["reported_as"] == "role" and _role587["owner_inputs"] == 0, _role587
        assert "A ROLE, NOT A MODELLED TWIN" in _role587["basis"], _role587["basis"]
        #  THE PROFILE IS NOT COUNTED AS A DECLARATION. It is the platform's canon, identical for every
        #  Chief, and it is what made the old string claim a lived record unconditionally.
        assert _role587["profile"]["declared_by_owner"] is False, (
            "the platform's standing canon is reported as this Owner's own declaration, which is what let "
            "every Chief read as a modelled twin", _role587["profile"])
        assert _role587["profile"]["text"].strip(), "the canon is not carried at all"
        #  and the STRING a prompt is built from says role, because that is what every caller reads
        _s587 = _b587.founder_profile()
        assert "CHIEF AS A ROLE" in _s587, (
            "the grounding string still opens with a lived record for an Owner who wrote nothing",
            _s587[:160])
        assert "FOUNDER MODEL (the Owner's lived record" not in _s587, _s587[:160]

        #  THE THREE INPUT KINDS ARE EACH NAMED AND COUNTED
        for _k587 in ("profile", "instructions", "decisions"):
            assert _k587 in _role587, ("an input kind the clause names is absent from the model", _k587)
            assert str(_role587[_k587].get("source") or "").strip(), (
                "an input kind does not say where it came from", _k587)
        assert _role587["instructions"]["count"] == 0 and _role587["decisions"]["count"] == 0, _role587

        #  A DECISION ALONE MAKES IT A TWIN — the input kind nothing read before this round, and the one
        #  a blind showed the guard was not exercising at all. Written straight into the Change Control
        #  store so the leg drives the READ rather than the whole ratification flow.
        import json as _json587
        #  (change_control is already imported above, with its store redirected into tmp_path)
        _cid587 = "cca-w587probe"
        _cpath587 = _cca587._CCA_STORE / f"{_cid587}.json"
        _cpath587.write_text(_json587.dumps({
            "cca_id": _cid587, "title": "a change the Owner ratified", "status": "approved",
            "board_ratification": {"decision": "ratify", "at": "2026-10-05T00:00:00Z",
                                   "notes": "the Owner's own decision"},
        }), encoding="utf-8")
        try:
            _dec587 = _b587.founder_model()
            assert _dec587["decisions"]["count"] >= 1, (
                "a ratified change is in the store and the model reads NO decisions, so the input kind "
                "nothing read before this round is still not read", _dec587["decisions"])
            assert _dec587["is_modelled_twin"] is True and _dec587["instructions"]["count"] == 0, (
                "a DECISION alone does not make the Chief a twin, so only instructions actually count",
                _dec587)
            assert "decision(s) the Owner made" in _dec587["basis"], _dec587["basis"]
            #  and a decision alone is enough for the twin to act unprompted, restating the decision
            _dd587 = _aio587.run(_b587.twin_directive_unprompted("w587decscope"))
            assert _dd587["issued"] is True, ("a Chief built from a decision refuses to act", _dd587)
            assert "ratify" in str(_dd587.get("acted_on") or "").lower(), (
                "the directive does not restate the Owner's decision", _dd587.get("acted_on"))
        finally:
            _cpath587.unlink(missing_ok=True)
        assert _b587.founder_model()["decisions"]["count"] == 0, (
            "the probe decision was not removed, so later legs would read it")

        #  AN INSTRUCTION MAKES IT A TWIN, and the count is the Owner's own
        _b587._save([{"kind": "chief_instruction", "instruction": "Close Phase 3",
                      "created_at": "2026-10-05T00:00:00Z"}])
        _twin587 = _b587.founder_model()
        assert _twin587["is_modelled_twin"] is True and _twin587["owner_inputs"] == 1, _twin587
        assert _twin587["instructions"]["count"] == 1, _twin587["instructions"]
        assert "MODELLED TWIN" in _twin587["basis"], _twin587["basis"]
        assert "FOUNDER MODEL (the Owner's lived record" in _b587.founder_profile()

        # ── L3. CLAUSE (3): THE BASIS TRAVELS WITH THE OUTPUT, WITH ITS COUNTS ─────────────────────
        #  (checked here while the state is controlled; the route is the surface a reader reaches)
        assert "BASIS:" in _b587.founder_profile(), (
            "the grounding string carries no basis, so nothing downstream can say which inputs the twin "
            "was built from")
        _cm587 = client.get("/api/v1/board/chief/model")
        assert _cm587.status_code == 200, (_cm587.status_code, _cm587.text[:200])
        _cj587 = _cm587.json()
        assert _cj587["is_modelled_twin"] is True, _cj587
        assert _cj587["instructions"]["count"] == 1, _cj587["instructions"]
        assert str(_cj587.get("basis") or "").strip() and str(_cj587.get("method") or "").strip(), _cj587
        #  the counts are IN the basis, not merely beside it
        assert "1 instruction(s)" in _cj587["basis"], (
            "the basis does not say HOW MANY inputs the twin was built from, which is what clause (3) "
            "asks for", _cj587["basis"])

        #  AND IT IS RENDERED WHERE A PERSON MEETS THEIR CHIEF. Clause (3) says every twin output is
        #  RENDERED with its basis, and the pre-flight's key screen caught that no page fetched the model
        #  at all. The two cases must render DIFFERENTLY: one rendering for both is the defect this item
        #  is about, since a reader would learn nothing from it.
        _bp587 = (_pl587.Path(__file__).resolve().parents[1]
                  / "apps/workstation-superapp/src/pages/enterprise/BoardOfDirectors.tsx").read_text(
                      encoding="utf-8", errors="replace")
        _bpcode587 = _re587.sub(r"(?m)^\s*//.*$", " ",
                                _re587.sub(r"/\*(?:.|\n)*?\*/", " ", _bp587))
        assert "/api/v1/board/chief/model" in _bpcode587, (
            "no page fetches the Chief's model, so a reader cannot tell a twin from a role")
        assert "chiefModel.is_modelled_twin ? (" in _bpcode587, (
            "the page does not branch on whether the Chief is a twin, so both cases render the same - "
            "W503's class, so this asserts the gate with its opening brace rather than the field name")
        for _btid587 in ('data-testid="chief-model-twin"', 'data-testid="chief-model-role"',
                         'data-testid="chief-standing-with-output"'):
            assert _btid587 in _bpcode587, ("a Chief standing has no rendered element", _btid587)

        # ── L2. CLAUSE (2): UNPROMPTED, WITH EXECUTE, AND A ROLE REFUSES ───────────────────────────
        #  (a) a ROLE refuses to act at all
        _b587._save([])
        _ref587 = _aio587.run(_b587.twin_directive_unprompted("w587scope"))
        assert _ref587["issued"] is False and _ref587["reason"] == "role", _ref587
        assert "REFUSED" in _ref587["basis"] and "under the Owner's name" in _ref587["basis"], (
            "a Chief with nothing of the Owner's does not say why it refuses to direct", _ref587["basis"])

        #  (b) with an instruction of the Owner's it ISSUES, through the gate, WITH execute
        _b587._save([{"kind": "chief_instruction", "instruction": "Close Phase 3 of the plan",
                      "created_at": "2026-10-05T00:00:00Z"}])
        _iss587 = _aio587.run(_b587.twin_directive_unprompted("w587scope"))
        assert _iss587["issued"] is True, _iss587
        #  THE OUTCOME, not the intention. A blind proved the first cut vacuous: it asserted
        #  `cascaded_to_ceo`, which the returned dict hardcoded to True, so the check could not fail
        #  however the call was made (W497's shape — a guard asserting a value derived from the flag it is
        #  checking). What "with execute" MEANS is that the directive reached the living plan.
        assert int(_iss587.get("objectives_added") or 0) >= 1, (
            "the directive was composed and FILED: nothing was delegated to the AI CEO and no objective "
            "landed on the living plan, so nothing the twin directed actually happens. The clause says "
            "WITH execute", _iss587.get("objectives_added"), _iss587.get("governance"))
        assert _iss587["cascaded_to_ceo"] is True and _iss587["executed"] is True, _iss587
        assert _iss587.get("directive_id"), _iss587
        assert _iss587.get("governance"), (
            "the unprompted directive records no gaas.v5 gate verdict, so an apex direction ran with no "
            "constitutional record", _iss587)
        #  it restates the OWNER's OWN words and invents nothing
        assert "Close Phase 3 of the plan" in str(_iss587.get("acted_on") or ""), (
            "the unprompted directive does not restate the Owner's own input", _iss587.get("acted_on"))

        #  (c) THE TWIN DOES NOT READ ITS OWN OUTPUT BACK AS THE OWNER'S INPUT. Found by driving the
        #  idempotence: chief_instruct records an `instruction`, so without a marker the twin's
        #  restatement became a new Owner input - the count rose, the check never held, and the beat
        #  would issue a directive on every visit forever while the Owner asked for nothing.
        _after587 = _b587.founder_model()
        assert _after587["owner_inputs"] == 1, (
            "issuing a directive INCREASED the Owner's input count, so the twin is reading its own output "
            "back as its principal's record", _after587["owner_inputs"],
            _after587["instructions"]["recent"])
        _rep587 = _aio587.run(_b587.twin_directive_unprompted("w587scope"))
        assert _rep587["issued"] is False and _rep587["reason"] == "nothing_new", (
            "a second call with an unchanged Owner record issued ANOTHER directive; the beat visits every "
            "sixty seconds, so this grows the living plan unasked", _rep587)

        #  (d) a NEW input of the Owner's moves it again
        _b587._save(_b587._load() + [{"kind": "chief_instruction", "instruction": "Now close Phase 4",
                                      "created_at": "2026-10-05T01:00:00Z"}])
        _mov587 = _aio587.run(_b587.twin_directive_unprompted("w587scope"))
        assert _mov587["issued"] is True and "Phase 4" in str(_mov587.get("acted_on") or ""), _mov587

        # ── AND IT IS THE BEAT THAT DRIVES IT, not a manual call ───────────────────────────────────
        import agentic_core.organism.heartbeat as _hb587
        assert _hb587.heartbeat.auto_align is False, (
            "auto_align is ON before this leg touched it - it is an autonomy key the Owner sets and must "
            "default to off")
        _b587._save([{"kind": "chief_instruction", "instruction": "Drive P3 to completion",
                      "created_at": "2026-10-05T02:00:00Z"}])
        _was587 = _hb587.heartbeat.auto_align
        try:
            _hb587.heartbeat.auto_align = True
            _beat587 = _aio587.run(_hb587.heartbeat.beat())
            _acts587 = _beat587.get("actions") or []
            assert any(a == "twin_directive" for a in _acts587), (
                "a beat with auto_align ON did not produce a twin directive, so the twin is not invoked "
                "unprompted - a directive behind a route is a manual call", _acts587)
            assert (_hb587.heartbeat.last_twin_directive or {}).get("issued") is True, (
                "the beat issued a directive and recorded nothing, so the organism's status cannot report "
                "what its twin did", _hb587.heartbeat.last_twin_directive)
            #  a SECOND beat withholds and says so: a refusal and an issue are different facts and the
            #  action list must not carry one marker for both
            _beat2587 = _aio587.run(_hb587.heartbeat.beat())
            _acts2587 = _beat2587.get("actions") or []
            assert any(str(a).startswith("twin_directive_withheld:") for a in _acts2587), (
                "a second beat with an unchanged Owner record did not record a WITHHELD directive",
                _acts2587)
            assert "twin_directive" not in _acts2587, (
                "the second beat issued another directive", _acts2587)
        finally:
            _hb587.heartbeat.auto_align = _was587
        assert _hb587.heartbeat.auto_align is False, (
            "auto_align was left ON by this guard - it is the Owner's switch, not a test's")
    finally:
        _b587._save(_rows587)

    # ── L4. CLAUSE (4): NO CHIEF IS TITLED "of default" ────────────────────────────────────────────
    #  W492 found that exact string shipped. The guard's job is to keep it gone, DRIVEN through the
    #  roster the surfaces actually read rather than by grepping the source.
    #  the roster's real shape is {owner, chief, directors, governance, vision_summary} — the Chief is its
    #  own key rather than a row in a members list, which is what the first cut of this leg assumed.
    _named587 = _b587.board_for_owner("W587 Owner Name", "a vision")
    assert isinstance(_named587.get("chief"), dict), ("the roster carries no Chief at all",
                                                     sorted(_named587))
    _ctitle587 = str(_named587["chief"].get("title") or "")
    assert _ctitle587.strip(), "the Chief has no title"
    #  TITLED FOR ITS OWNER
    assert "W587 Owner Name" in _ctitle587, (
        "a per-VSB Chief is not titled for its owner", _ctitle587)
    #  and "of default" appears nowhere in the roster, for ANY owner name — including the one that
    #  produced the string W492 found shipped
    for _owner587 in ("W587 Owner Name", "default", "", None):
        _r587 = _b587.board_for_owner(_owner587 or "", "a vision")
        _blob587 = _re587.sub(r"\s+", " ", str(_r587)).lower()
        assert "of default" not in _blob587, (
            "a Chief is titled 'of default' - the exact string W492 found shipped. An owner name of "
            "'default' or none must fall back to 'the founder', never to the literal",
            _owner587, str(_r587.get("chief", {}).get("title"))[:160])
        #  ...and the fallback really is the founder, not an empty possessive
        if not _owner587 or _owner587 == "default":
            assert "the founder's" in str(_r587["chief"].get("title") or ""), (
                "an owner with no name produces a Chief titled for nobody rather than for the founder",
                _r587["chief"].get("title"))
    #  the directors are present and none of them carries it either
    for _d587 in (_named587.get("directors") or []):
        assert "of default" not in str(_d587.get("title") or "").lower(), _d587
    assert len(_named587.get("directors") or []) >= 3, (
        "the roster carries almost no directors, so this leg checks little",
        len(_named587.get("directors") or []))
    #  AND THE TITLE DOES NOT STILL CALL MODE 2 PLANNED, because this round delivered it
    assert "Mode 2" not in _ctitle587 or "planned" not in _ctitle587, (
        "the Chief's title still says Mode 2 is PLANNED after it was delivered", _ctitle587)
    assert "no twin model is trained" in _ctitle587, (
        "the title dropped the statement that no twin model is TRAINED, which is still true and is the "
        "distinction clause (1) turns on - a model assembled from a record is not a trained one",
        _ctitle587)
def test_w588_exactly_one_class_carries_the_constitutional_interceptor_name():
    """FU-409 (Owner-ruled 2026-10-05) — two live classes shared one name and it misdirected a fix.

    MEASURED IN W584: `agentic_core/gaas/v5/uci_v16_omega.py:62` and
    `agentic_core/governance/uci_interceptor.py:20` were BOTH called
    `UnifiedConstitutionalInterceptorV16Omega`. They are not variants of one thing — the first is the wired
    constitutional engine, exported from gaas/v5/__init__ and driven by this suite at four monkeypatch
    points, returning an InterceptionResult; the second returns a plain dict, raises PermissionError from
    its gates, and had exactly one live importer. A search for "the interceptor" returned both, and a
    reader resolved the ambiguity by guessing: while fixing the Divine Alignment gate in W584 that nearly
    put the fix in the wrong file.

    ASSERTED ON THE CLASS DEFINITIONS, NOT THE NAME IN TEXT. The rename's own docstring and the
    orchestrator's import comment both mention the old identifier in order to explain the rename, so a
    string count would be satisfied by prose while two real classes still shared the name — the
    banned-literal trap this programme has now hit five times.
    """
    import ast as _ast588
    import pathlib as _pl588

    _root588 = _pl588.Path(__file__).resolve().parents[1]
    _live588 = [p for p in (_root588 / "agentic_core").rglob("*.py")
                if "_archive" not in p.parts and "__pycache__" not in p.parts]
    assert len(_live588) > 200, ("the scan found almost nothing, so it proves nothing", len(_live588))

    _defs588 = {}
    for _p588 in _live588:
        try:
            _tree588 = _ast588.parse(_p588.read_text(encoding="utf-8", errors="replace"))
        except SyntaxError:
            continue
        for _n588 in _ast588.walk(_tree588):
            if isinstance(_n588, _ast588.ClassDef):
                _defs588.setdefault(_n588.name, []).append(
                    str(_p588.relative_to(_root588)).replace("\\", "/"))

    #  THE WIRED ENGINE KEEPS THE NAME, and only it
    _omega588 = _defs588.get("UnifiedConstitutionalInterceptorV16Omega", [])
    assert len(_omega588) == 1, (
        "more than one live class is named UnifiedConstitutionalInterceptorV16Omega, so a reader searching "
        "for the constitutional interceptor gets both and resolves it by guessing - which in W584 nearly "
        "sent a fix for the Divine Alignment gate into the wrong file", _omega588)
    assert _omega588[0] == "agentic_core/gaas/v5/uci_v16_omega.py", (
        "the name no longer belongs to the WIRED constitutional engine - the one exported from "
        "gaas/v5/__init__ and driven by this suite", _omega588)

    #  and the avatar path's pre-flight is named for what it is, in its own file
    _pre588 = _defs588.get("RecirculationPreflight", [])
    assert _pre588 == ["agentic_core/governance/uci_interceptor.py"], (
        "the avatar recirculation path's pre-flight is not where or what it should be", _pre588)

    #  THE ONE LIVE IMPORTER FOLLOWS THE RENAME. A rename whose consumer still imports the old name is a
    #  break, and the orchestrator is the only module that imports this class at all.
    _orch588 = (_root588 / "agentic_core/avatars/core/recirculation_orchestrator.py").read_text(
        encoding="utf-8", errors="replace")
    _otree588 = _ast588.parse(_orch588)
    #  BOTH the imported name AND the local binding. `ast.alias.name` is the original and `.asname` is
    #  the local one, so reading only `.name` let a blind alias the import straight back to the engine's
    #  name — reintroducing the ambiguity the ruling removed, in the one module that imports this class.
    _imported588, _localnames588 = set(), set()
    for _n588 in _ast588.walk(_otree588):
        if isinstance(_n588, _ast588.ImportFrom) and "uci_interceptor" in str(_n588.module or ""):
            for _a588 in _n588.names:
                _imported588.add(_a588.name)
                _localnames588.add(_a588.asname or _a588.name)
    assert _imported588 == {"RecirculationPreflight"}, (
        "the avatar recirculation orchestrator does not import the renamed pre-flight, so either the "
        "rename did not reach its only consumer or the old name is still resolvable", sorted(_imported588))
    assert "UnifiedConstitutionalInterceptorV16Omega" not in _localnames588, (
        "the orchestrator ALIASES the pre-flight back to the constitutional engine's name, so the "
        "ambiguity the ruling removed is alive again in the one module that imports this class",
        sorted(_localnames588))

    #  AND THE MODULE IMPORTS. The construction check used to be `"RecirculationPreflight(" in source`,
    #  which an alias leaves untouched while the module raises NameError — a string search cannot see
    #  that. Importing it is the only check that proves the rename reached its consumer.
    import importlib as _il588
    _mod588 = _il588.import_module("agentic_core.avatars.core.recirculation_orchestrator")
    assert getattr(_mod588, "RecirculationPreflight", None) is not None, (
        "the orchestrator module does not bind RecirculationPreflight at all, so the rename did not reach "
        "the name it actually uses")
    assert "RecirculationPreflight(" in _orch588, (
        "the orchestrator imports the pre-flight and never constructs it")
def test_w589_ci_runs_the_same_suite_the_round_runs():
    """CI's backend job runs the round's own command, and checks out enough history to measure itself.

    MEASURED, from the real failing run 37276077594 on 3931ca4d: CI had been red for THIRTEEN rounds and
    three of its six failures were caused not by the code but by CI running something else.

      * the suite step passed a flag that SKIPPED THE CONFTEST, so CI never had the isolated data root
        (DATA_DIR, WORKSTATION_DATA_DIR, PROJECTS_DIR, SYNTHESIS_OUTPUT_DIR, PROPOSALS_DIR,
        WORKSTATION_UEG_PATH), never ran `_assert_store_is_isolated` - the session fixture whose whole job is
        to fail loudly when the suite is about to write the real store - and never ran the collection hooks.
        A measuring script that moved the process data root therefore moved it for everything after it, which
        is how an entity's record and its repo files came to sit under DIFFERENT roots and a guard asserted on
        a deleted path.
      * no checkout in either workflow set `fetch-depth`, so actions/checkout took its default of ONE commit
        and every instrument that walks commit history had one commit to walk. Two standing failures, one
        cause: the forecast reported no round-boundary cost and the commitment variance read None.
      * and the target was the spine FILE while every round runs the DIRECTORY.

    The flag was not load-bearing, which is why removing it is safe rather than brave: conftest.py imports
    only json, os and pytest, reads PYTEST_XDIST_WORKER as a plain env string and takes the serial path when
    it is absent, every hook is opt-in on an env var CI does not set and wrapped so it cannot break the run,
    and it defines no fixture the test module also defines.

    A permanently red CI gives no signal, so each round's own new breakage lands invisibly. That is the
    instrument-that-cannot-fail class operating one level above the suite.
    """
    import pathlib as _pl589

    import yaml as _yaml589

    _root589 = _pl589.Path(__file__).resolve().parents[1]
    _wf589 = _root589 / ".github" / "workflows" / "spine.yml"
    assert _wf589.is_file(), "the Spine CI workflow is gone, so nothing runs the suite on a push"
    _doc589 = _yaml589.safe_load(_wf589.read_text(encoding="utf-8"))
    _steps589 = _doc589["jobs"]["backend"]["steps"]

    #  SELECTED BY WHAT THE STEP IS, not by a word that appears in two of them. The dependency step runs
    #  `pip install pytest`, and a selector on the bare word returned THAT step - which made this round's own
    #  patch assert "the flag is absent" against an install command and pass for the wrong reason.
    _runs589 = [s for s in _steps589 if "-m pytest" in str(s.get("run") or "")]
    assert len(_runs589) == 1, (
        "the backend job does not have exactly one step that runs the pytest module, so this guard cannot "
        "know which command CI trusts", [str(s.get("run"))[:60] for s in _runs589])
    _cmd589 = " ".join(str(_runs589[0]["run"]).split())

    #  (1) THE CONFTEST IS LOADED. Asserted on the parsed command, which is the thing CI executes.
    assert "noconftest" not in _cmd589, (
        "CI's suite step skips the conftest, so it runs a DIFFERENT suite from the one every round runs and "
        "every commit is trusted on - no isolated data root, no isolation fixture, no collection hooks",
        _cmd589)

    #  (2) THE SAME TARGET THE ROUND RUNS. The only other file under integration_tests is the xdist probe,
    #  whose tests skip when not running under xdist, so the directory costs CI four skips.
    assert "integration_tests" in _cmd589.split(), (
        "CI does not run the integration_tests directory the round runs", _cmd589)

    #  (3) ENOUGH HISTORY TO MEASURE ITSELF.
    _cos589 = [s for s in _steps589 if str(s.get("uses") or "").startswith("actions/checkout")]
    assert len(_cos589) == 1, ("the backend job has no single checkout to check", len(_cos589))
    _depth589 = (_cos589[0].get("with") or {}).get("fetch-depth")
    assert _depth589 == 0, (
        "the backend checkout does not take the full history (0), so every instrument that measures this "
        "programme by walking commits - the round-duration median, the round-boundary cost, the commitment "
        "variance - sees one commit and reports nothing", _depth589)

    #  AND THE SUITE IS ACTUALLY RUN ON A PUSH, because a correct command in a workflow nothing triggers is
    #  the same silence by another route.
    _on589 = _doc589.get("on") if "on" in _doc589 else _doc589.get(True)
    assert _on589 and "push" in _on589, (
        "the Spine CI workflow does not run on a push, so nothing reports on a round's own commit", _on589)
def test_w590_the_milestone_instrument_is_committed_and_matches_the_renderers_contract():
    """MILESTONE M1 can be re-run from this repository, and the instrument agrees with the renderer.

    FU-418, measured W590. M1's bar is a standing TIER-1 count of 0 and it is mandated before any P2-P4
    item — and the milestone could not be re-run here at all. The only committed workflow was
    fidelity_audit_v3.js, whose FINDINGS schema carries section/verdict/vision_claim/observed/evidence/
    disclosed_to_user/severity/smallest_honest_fix and whose VERDICTS schema carries index/refuted/
    corrected_verdict/reason/evidence. NEITHER CARRIES A TIER, while render_fidelity_ledger.py computes the
    milestone's own measure from that field: `standing_tier` reads a verdict's `corrected_tier` and falls
    back to the finding's `tier`. A run of the committed script therefore produced a ledger in which every
    standing tier was None and M1 could not be scored.

    The tiered instrument had never been committed. W572's M1 commit (93f51c95) shipped ten files — the
    ledger, the v5 archive, the prompt, the register, the test file, the renderer, blinds — and no workflow
    among them, so the instrument that measured the standing count of 20 existed only in that session's
    transcript. That is the P5.4 problem in miniature: a milestone only one session can run is not a
    milestone.

    ASSERTED AS ONE CONTRACT WITH TWO ENDS, not as two files existing. Every failure of this kind has been a
    MISMATCH — the renderer read `section` while the assessors supplied `title`, and sixty headings rendered
    blank while every summary count stayed correct, which is how a dropped field stays silent.
    """
    import pathlib as _pl590

    _root590 = _pl590.Path(__file__).resolve().parents[1]
    _wf590 = _root590 / "scripts" / "workflows" / "fidelity_audit_v7.js"
    assert _wf590.is_file(), (
        "no tiered fidelity workflow is committed, so MILESTONE M1 - which is mandated before every P2-P4 "
        "item and scored on a tier - cannot be re-run from this repository at all")
    _src590 = _wf590.read_text(encoding="utf-8")
    _rend590 = (_root590 / "scripts" / "render_fidelity_ledger.py").read_text(encoding="utf-8")

    #  THE RENDERER'S END: the M1 measure is computed from these two keys.
    assert "corrected_tier" in _rend590 and "standing_tier" in _rend590, (
        "the renderer no longer computes a standing tier, so nothing turns the audit into the milestone's "
        "measure")

    #  THE INSTRUMENT'S END: it must SUPPLY them, and as REQUIRED fields - an optional tier is a tier the
    #  assessors will sometimes omit, and the measure would then be silently short.
    _reqs590 = []
    _i590 = 0
    while True:
        _i590 = _src590.find("required:", _i590)
        if _i590 < 0:
            break
        _j590 = _src590.find("]", _i590)
        _reqs590.append(_src590[_i590:_j590])
        _i590 = _j590
    assert len(_reqs590) >= 2, (
        "the workflow declares fewer than two required-field lists, so it has no schema for findings and "
        "verdicts", len(_reqs590))
    _finding590 = [r for r in _reqs590 if "'section'" in r or '"section"' in r]
    _verdict590 = [r for r in _reqs590 if "'index'" in r or '"index"' in r]
    assert _finding590, "no findings schema requires `section`, the finding's only heading"
    assert _verdict590, "no verdicts schema requires `index`, which is what joins a verdict to its finding"
    for _key590 in ("'tier'", "'why_this_tier'", "'verdict'"):
        assert _key590 in _finding590[0], (
            "the findings schema does not REQUIRE this field, so a finding can arrive without it and the "
            "milestone's own measure is silently short", _key590, _finding590[0])
    assert "'corrected_tier'" in _verdict590[0], (
        "the verdicts schema does not require corrected_tier, so a refuter can move a tier without saying "
        "so - which is exactly how v6 reported that none had been made harsher in an edition where four "
        "were escalated INTO tier 1", _verdict590[0])

    #  AND IT CANNOT RUN WITHOUT NAMING WHAT IT AUDITED. v3 pinned the HEAD and date into its prompt text,
    #  so an un-edited re-run would have told six assessors they were auditing a weeks-old commit.
    assert "args" in _src590, (
        "the workflow takes no arguments, so the commit it audits is hardcoded and a re-run assesses HEAD "
        "while telling its agents a different sha")
    assert "is not a measurement" in _src590, (
        "the workflow does not refuse when the commit or date it audits is unstated, so it can produce an "
        "unattributable fidelity verdict")

    #  the tier DEFINITIONS travel with the instrument, because a tier nobody defines is a number
    for _word590 in ("TIER 1", "reached", "DELIVERED"):
        assert _word590 in _src590 or _word590.lower() in _src590.lower(), (
            "the instrument does not state what the tiers MEAN, so each run tiers against whatever the "
            "assessor assumes", _word590)
def test_w590_the_suite_collects_where_pytest_xdist_is_not_installed():
    """A hook belonging to an optional plugin is declared optional, so a checkout without xdist can run.

    MEASURED FROM CI, run 37304562756, and it refuted my own W589 measurement. W589 removed the
    conftest-skipping flag from the backend job on the stated ground that conftest.py imports only json, os
    and pytest. It does - and that was the wrong thing to check. `pytest_xdist_node_collection_finished` is a
    hook that pytest-xdist DEFINES, and pluggy validates hook NAMES against the registered plugins at the end
    of collection, so on a runner without xdist `check_pending()` raised

        PluginValidationError: unknown hook 'pytest_xdist_node_collection_finished' in plugin conftest

    which is an INTERNALERROR, exit 3, and NO TESTS RAN AT ALL. The change took CI from four failing tests to
    a suite that never started. A hook NAME is a dependency surface exactly as an import is.

    AND IT IS THE TWELVE-ROUND MYSTERY IN test_w537. That guard's control leg expects exit 5 (nothing
    collected) from a child pytest and CI returned 3. The child is spawned without the conftest-skipping flag,
    so on a runner with no xdist it loaded this conftest and hit this same PluginValidationError. One cause,
    two standing failures.

    The remedy is pluggy's own mechanism for a hook whose plugin may be absent - `optionalhook=True` - so
    validation passes and the hook simply never fires. Under xdist nothing about it changes. This is asserted
    by DRIVING a collection with the plugin unregistered rather than by reading the decorator, because the
    decorator's presence says nothing about whether a run collects, and nothing here had ever exercised the
    plugin-absent state.
    """
    import os as _os590
    import pathlib as _pl590
    import subprocess as _sp590
    import sys as _sys590

    #  NON-REENTRANT (W537's lesson): the child carries the marker, and a child that is itself this probe
    #  does not run it again. A guard that spawns pytest can otherwise be re-entered by what it spawned.
    _MARK590 = "WORKSTATION_XDIST_ABSENT_PROBE"
    if _os590.environ.get(_MARK590):
        return

    #  the declaration itself, as an introspectable PROPERTY of the function rather than a string in a file
    import integration_tests.conftest as _cf590
    _hook590 = getattr(_cf590, "pytest_xdist_node_collection_finished", None)
    assert _hook590 is not None, "the parallel-denominator hook is gone, so a parallel run reports NOT KNOWN"
    _impl590 = getattr(_hook590, "pytest_impl", None) or {}
    assert _impl590.get("optionalhook") is True, (
        "the xdist hook is not declared optional, so pluggy rejects its NAME wherever pytest-xdist is not "
        "installed - an INTERNALERROR at the end of collection, exit 3, and no tests run", _impl590)

    #  AND A RUN REALLY COLLECTS WITH THE PLUGIN UNREGISTERED. `-p no:xdist` puts this process in exactly the
    #  state a runner without pytest-xdist is in, which is the condition that was never exercised.
    _root590 = _pl590.Path(__file__).resolve().parents[1]
    _env590 = dict(_os590.environ, **{_MARK590: "1"}, PYTHONIOENCODING="utf-8")
    _r590 = _sp590.run([_sys590.executable, "-m", "pytest",
                        str(_root590 / "integration_tests" / "test_xdist_iso.py"),
                        "--collect-only", "-q", "-p", "no:xdist"],
                       capture_output=True, text=True, encoding="utf-8", errors="replace",
                       env=_env590, cwd=str(_root590))
    _out590 = " ".join(((_r590.stdout or "") + (_r590.stderr or "")).split())
    assert _r590.returncode == 0, (
        "collection fails when pytest-xdist is unregistered, so this suite cannot run on a checkout without "
        "it - which is what CI is, what a fresh clone is, and what the P5.4 handover gets",
        _r590.returncode, _out590[-600:])
    assert "unknown hook" not in _out590 and "PluginValidationError" not in _out590, (
        "a hook name is still rejected with the plugin absent", _out590[-400:])
def test_w593_p220a_the_floor_never_returns_its_own_text_as_the_users(client):
    """P2.20 clause (a) — one shape, three mechanisms, each driven on the input that found it.

    THE SHAPE: the floor produces a reading for whatever it was given, and the surface presents it as a
    reading of the USER'S input. Measured before building, and the audit's stated causes were wrong twice:
    R4.0 blames the floor's banner, which `_CARRIED_MARKER_RE` strips; R3.0 blames a single-key map, which
    is only why two of three sections go UNDETECTED. The causes below are the ones that reproduce.

    (i)   `_subject` searched 17 labels and fell through to THE LONGEST SENTENCE, which in a prompt carrying
          a realm directive IS the directive: a report on a Kenyan clinic opened "Subject: Lead with the
          decision and its cost...", and 164 of 300 records in data/deliverables.json carry such a line.
    (ii)  `_CONTENT_LABELS` held "Task / question" but not bare `Task`, which is exactly what a DELEGATED
          prompt carries (orchestrator.py builds `Task: {instruction}`), so `_content` fell through to the
          whole prompt and the bullets came back `- plain markdown`, `- structure short`. Separately
          `Prior context` holds the PREVIOUS STAGE'S OUTPUT and was counted as the user's terms, and
          `_phrases` ran over the " . "-joined fields so a bigram could span two of them: `- kitchen
          understanding`, the user's word joined to this engine's own "## Understanding" heading.
    (iii) the v138 CEO handed its grounding over in "## Heading" form, and `_sections` reads "## " headings
          OUT OF THE PROMPT — so the floor wrote a section for each and filled every one with the same
          scaffold body. The prompt asks for sections legitimately at the end ("Respond with: ## Assessment
          …"), so the mechanism is right and the misuse was the context.
    """
    import os as _os593
    import tempfile as _tf593

    from agentic_core.ai.native import engine as _E

    # ── THE INVARIANT BETWEEN THE TWO LABEL LISTS ─────────────────────────────────────────────────
    #  Asserted as a RELATIONSHIP, never as the presence of a spelling: a guard that checks "Brief is in
    #  the subject labels" passes the moment the word is added and says nothing about the next label.
    #  The lists diverged in BOTH directions before this round — 23 content labels invisible to the
    #  subject, and bare `Task` a subject label that was not a content label — and each direction
    #  corrupted a different part of the same output.
    _subj593, _cont593 = set(_E._SUBJECT_LABELS), set(_E._CONTENT_LABELS)
    assert _subj593 <= _cont593, (
        "a label can become the SUBJECT while being invisible to the content extractor, so a prompt "
        "carrying only that label has a subject and no content — and its term list then falls through to "
        "the platform's own prompt. That is exactly what bare `Task` did to every delegated cascade stage",
        sorted(_subj593 - _cont593))
    assert "Brief" in _subj593, (
        "a deliverable's own Brief cannot become its subject, which is the finding R1.0 reproduced")
    assert _cont593 - _subj593, (
        "every content label is now a subject label, so a BODY field (Background, Prior context, a draft) "
        "can be sliced to 220 characters and printed as the subject — one false subject traded for another")

    # ── (i) A BRIEF IS THE SUBJECT, AND NO LABEL MEANS NO SUBJECT ─────────────────────────────────
    _brief593 = ("Brief: A 20-bed clinic in rural Kenya needs reliable power for vaccine refrigeration.\n"
                 "Lead with the decision and its cost, keep evidence tight, and prefer concrete numbers, "
                 "timelines and owners over explanation of fundamentals.\nDomain: energy")
    assert "Kenya" in _E._subject(_brief593), (
        "the brief is not the subject", _E._subject(_brief593))
    assert "Lead with the decision" not in _E._subject(_brief593), (
        "the realm's house-style directive is still being reported as the user's subject",
        _E._subject(_brief593))

    _bare593 = "Structure as: a short list.\nRespond with plain markdown."
    assert _E._subject(_bare593) == "", (
        "a prompt with no labelled subject still yields one, so the fall-through is guessing again",
        _E._subject(_bare593))
    _out_bare = _E.NativeReasoningEngine().generate(_bare593, agent="bare")
    assert "carries no labelled subject" in _out_bare, (
        "the surface does not SAY the request named no subject; an absent subject must be stated, not "
        "silently replaced", _out_bare[:300])
    assert "WITHHELD" in _out_bare, (
        "with no labelled field the term list is still printed under \"most frequent in your request\", "
        "so it is counted over the platform's own prompt and the heading is false", _out_bare[:400])

    # ── (ii) A DELEGATED TASK, AND A CARRIED STAGE ────────────────────────────────────────────────
    def _terms593(out):
        keep, got = False, []
        for _l in out.splitlines():
            _s = _l.strip()
            if _s.startswith("## "):
                keep = "terms most frequent" in _s.lower()
                continue
            if keep and _s.startswith("- "):
                got.append(_s.lower())
        return got

    _task593 = ("Task: Draft the evening delivery rota for the Birmingham halal kitchen so that two staff "
                "are always free at maghrib.\nStructure as: a short list.\nRespond with plain markdown.")
    assert _E._content(_task593).strip() != _task593.strip(), (
        "a delegated prompt still falls through to the WHOLE PROMPT, so its terms are the platform's own "
        "scaffolding — the shape bare `Task` produced on every cascade stage")
    _t_task = " ".join(_terms593(_E.NativeReasoningEngine().generate(_task593, agent="delegate")))
    for _scaffold in ("plain markdown", "structure short", "respond"):
        assert _scaffold not in _t_task, (
            "the platform's own formatting instruction is presented as one of the user's most frequent "
            "terms", _scaffold, _t_task)
    assert "delivery" in _t_task or "kitchen" in _t_task, (
        "the user's own words are not in the term list at all", _t_task)

    _eng593 = _E.NativeReasoningEngine()
    _stage1 = _eng593.generate(
        "Objective: Open a halal delivery kitchen in Birmingham serving Pakistani home cooking to students, "
        "with evening delivery and a prayer-friendly staff rota.", agent="stage1")
    _stage2 = "Prior context:\n" + _stage1[:1200] + "\n\nObjective: Price the menu for the same kitchen."
    _t_carry = " ".join(_terms593(_eng593.generate(_stage2, agent="stage2")))
    assert "understanding" not in _t_carry and "native approach" not in _t_carry, (
        "the CARRIED previous-stage output is being counted under \"most frequent in your request\", so "
        "the floor's own headings are reported as the user's terms", _t_carry)

    #  AND THE PER-FIELD PHRASE BUILD, ON ITS OWN. A blind proved this needed separating: with the carried
    #  label excluded there is nothing of the floor's left to span onto, so the leg above passed whether
    #  phrases were built per field or over the join — the property was DOUBLY HELD and the blind was
    #  meaningless. Both fields here are the USER'S, so only the per-field build can keep them apart: a
    #  joined build pairs "kitchen" (the end of Objective) with "Understanding" (the start of Concern) and
    #  reports a phrase that appears in neither field.
    _twofield593 = ("Objective: Open a halal delivery kitchen.\n"
                    "Concern: Understanding the tax rules for student catering.")
    _t_two = " ".join(_terms593(_E.NativeReasoningEngine().generate(_twofield593, agent="twofield")))
    assert "kitchen understanding" not in _t_two, (
        "a phrase spans the boundary between two of the user's OWN fields, so the list contains a pair of "
        "words that appear together nowhere in the request", _t_two)
    assert "halal delivery" in _t_two or "tax rules" in _t_two, (
        "the within-field phrases were lost along with the cross-field ones, so the fix removed the "
        "capability instead of the defect", _t_two)
    assert "Prior context" in _E._CARRIED_LABELS, (
        "the carried previous-stage output is counted as the user's own request again")
    assert "Prior context" in _E._CONTENT_LABELS, (
        "the carried context was dropped from the CONTENT too, which degrades the composition — it is "
        "excluded from the TERMS only")

    # ── (iii) THE CEO HANDS OVER CONTEXT, NOT A LIST OF SECTIONS TO WRITE ─────────────────────────
    _d593 = _tf593.mkdtemp(prefix="w593ceo-")
    _saved593 = {k: _os593.environ.get(k) for k in ("DATA_DIR", "WORKSTATION_DATA_DIR", "PROJECTS_DIR")}
    try:
        for _k in _saved593:
            _os593.environ[_k] = _d593
        from agentic_core.api.v138 import ceo as _C593
        _g593, _facts593 = _C593._ceo_grounding("How should we prioritise next quarter?", "workstation",
                                                None)
    finally:
        for _k, _v in _saved593.items():
            if _v is None:
                _os593.environ.pop(_k, None)
            else:
                _os593.environ[_k] = _v
    #  W593 — THE FUNCTION'S OWN HEADINGS, NOT EVERY "## " IN ITS OUTPUT. This asserted `"## " not in
    #  _g593`, and the grounding is composed from STORED board directives, plan pillars and the debate
    #  log - which in a full suite hold earlier floor compositions carrying this engine's own
    #  "## Understanding". The guard then failed on DATA and named the fix as the cause, which is the
    #  shape I have recorded as a blind accusing working code. The property R3.0 is about is that
    #  `_ceo_grounding` hands ITS sections over in label form, so each of its own headings is checked by
    #  name and a stored document's markdown is left alone.
    _glines593 = _g593.splitlines()
    for _own593 in ("Board directives", "Living plan", "Business plan", "Recent C-Suite debate"):
        assert not any(_l.lstrip().startswith(f"## {_own593}") for _l in _glines593), (
            "the CEO still hands its grounding over as HEADINGS, so the floor writes a section for each "
            "and fills every one with the same scaffold — the three identical bullet lists R3.0 found",
            _own593, _g593[:300])
    #  ASSERTED AS A PROPERTY, NOT A SPELLING. This read `"Board directives:" in _g593`, and the function
    #  writes "## Board directives (most recent first)" when directives EXIST and "## Board directives"
    #  when none do — so the literal held on an empty store and broke the moment a real directive was
    #  recorded. Label form is: a line that begins with the section name and ends in a colon. True of
    #  both variants and of any later one.
    assert any(_l.startswith("Board directives") and _l.rstrip().endswith(":") for _l in _glines593), (
        "the grounding no longer carries its board section in LABEL form, so the conversion that replaced "
        "the headings has stopped happening",
        [_l for _l in _glines593 if "Board directives" in _l][:3])
    #  AND THE DATA'S HALF, DRIVEN. The grounding embeds STORED records - board directives, plan pillars,
    #  the meeting log - and in a running system those hold earlier floor compositions carrying this
    #  engine's own "## Understanding". `_sections` reads "## " out of the prompt, so a stored document
    #  could steer the floor's section list: R3.0's symptom reached through data rather than through this
    #  function's own text. It cannot reproduce on an empty store, which is why this leg failed in the
    #  suite and passed alone TWICE before the state was driven here on purpose.
    _seeded593 = ("Raise margin on the care realm.\n## Understanding\n"
                  "a stored floor composition inside a real record.")
    _r593 = client.post("/api/v1/board/chief/instruct", json={"instruction": _seeded593})
    assert _r593.status_code == 200, ("the directive could not be seeded, so this leg measures nothing",
                                      _r593.status_code, _r593.text[:200])
    _g593b, _ = _C593._ceo_grounding("How should we prioritise next quarter?", "workstation", None)
    assert not [_l for _l in _g593b.splitlines() if _l.lstrip().startswith("#")], (
        "a stored record's own markdown heading survives into the grounding, so the floor is asked to "
        "write a section the CEO never requested - R3.0 reached through the data instead of the labels",
        [_l for _l in _g593b.splitlines() if _l.lstrip().startswith("#")][:4])
    assert "**Understanding**" in _g593b, (
        "the embedded heading was STRIPPED rather than demoted, which loses real text from a real record",
        _g593b[:400])

    _full593 = ("You are the AI CEO.\n\n" + _g593b + "\n\nQuestion: How should we prioritise next "
                "quarter?\n\nRespond with:\n## Assessment\n## Priorities\n## Next actions")
    assert _E._sections(_full593) == ["Assessment", "Priorities", "Next actions"], (
        "the floor is asked to write sections the CEO never requested", _E._sections(_full593))
    assert "prioritise" in _E._subject(_full593), (
        "the subject of a CEO answer is not the user's question", _E._subject(_full593))

    #  and the grounded-section detector covers the section it already had the facts for
    assert "objectives" in _C593._GROUNDED_SECTIONS, (
        "`facts` carries an objectives count and the business-plan section is still unchecked")
    assert "plan_score" not in _C593._GROUNDED_SECTIONS, (
        "a section is keyed on the canon's pillar SCORE, which is not a count of plan content — a wrong "
        "key produces a verdict where the right answer is to withhold one")
    _ungrounded = _C593._ungrounded_sections(
        "## Business plan for this scope\n- objective one\n- objective two\n", {"objectives": 0})
    assert [x["section"] for x in _ungrounded] == ["business plan for this scope"], (
        "a section printing items while its grounding counted none is not detected", _ungrounded)
    assert _C593._ungrounded_sections(
        "## Business plan for this scope\n- objective one\n", {"objectives": 2}) == [], (
        "a grounded section is reported as ungrounded, so the detector fires on a scope that has content")
def test_w593_p220_bcdef_a_claim_names_what_actually_did_it():
    """P2.20 clauses (b) (c) (d) (e) (f) — seven rows, each a claim corrected to what is true.

    MILESTONE M1 found all seven. They are grouped here because each is the same question asked of a
    different surface: does this sentence name what actually happened?

      FU-421 (b) the interfaith route was the ONE Religion tool with no floor_note, no disclaimer and no
                 withheld sections - a scholar persona over per-tradition "Perspectives" nothing looked up.
      FU-420 (b) the Qur'an study panel rendered floor-composed curriculum in a bare <pre>: no badge, no
                 AI-assisted label, no teacher referral, and the response's own ai_provenance unread.
      FU-436 (c) the quality record claimed the Endocrine regulator "holds a real HomeostaticRegulator with
                 an integral term". FU-307's correction reached the docstring and a comment, NOT the string
                 that ships - the second-writer class.
      FU-438 (d) a period close and the board pack were "prepared_by: CFO agent (AI C-Suite)". No such agent
                 is on any roster.
      FU-434 (d) the Religion hub's primary ethics button offered an "Ethics Council" that does not exist.
      FU-430 (e) /organism/cadence reported a STALE beat as "what the most recent heartbeat managed",
                 because the record was only written when a layer refreshed. MY OWN DEFECT, from W589.
      FU-433 (f) the QEP roadmap advertised an emotion-adaptive interface, which Appendix A.9.4 RATIFIES as
                 refused - the product promising what its own constitution forbids.
    """
    import asyncio as _aio593
    import pathlib as _pl593

    _root593 = _pl593.Path(__file__).resolve().parents[1]

    # ── FU-430 (e): THE CADENCE RECORD IS WRITTEN ON EVERY BEAT, so a stale one cannot pass for new ──
    #  DRIVEN over two beats, because the defect only appears on the SECOND: the first beat refreshed and
    #  wrote a record, and the second (nothing due) used to leave the first beat's record in place while
    #  the surface called it "what the most recent heartbeat managed".
    import agentic_core.organism.heartbeat as _hb593
    _b1 = _aio593.run(_hb593.heartbeat.beat())
    _rec1 = dict(_hb593.heartbeat.last_cadence or {})
    _b2 = _aio593.run(_hb593.heartbeat.beat())
    _rec2 = dict(_hb593.heartbeat.last_cadence or {})
    assert _rec1 and _rec2, ("the beat records no cadence state at all", _rec1, _rec2)
    assert _rec2.get("beat") == _hb593.heartbeat.beats, (
        "the cadence record is from an EARLIER beat while the surface presents it as the most recent - the "
        "record is only written when something happened, which is false on every quiet beat",
        _rec2.get("beat"), _hb593.heartbeat.beats)
    assert _rec2.get("beat") != _rec1.get("beat"), (
        "two consecutive beats produced the same record, so the second did not write one", _rec1, _rec2)
    assert _rec2.get("nothing_was_due") in (True, False), (
        "the record cannot say whether anything was DUE, so a quiet cadence and a broken one read alike",
        _rec2)
    assert "beat" in str(_rec2.get("basis") or ""), (
        "the basis does not name the beat it describes", _rec2.get("basis"))

    # ── FU-421 (b): THE INTERFAITH ROUTE WITHHOLDS ON THE FLOOR AND SAYS SO ──────────────────────
    from agentic_core.api import religion as _rel593
    _ifq = _rel593.InterfaithRequest(topic="charity", traditions=["Islam", "Christianity"])
    _if = _aio593.run(_rel593.interfaith_dialogue(_ifq))
    assert _if.get("floor_note"), (
        "the one Religion tool that lacked a floor_note still lacks it, so a scholar persona over "
        "per-tradition perspectives reaches the reader with nothing saying what served it", sorted(_if))
    assert _if.get("disclaimer"), ("the interfaith route carries no disclaimer", sorted(_if))
    _wh = _if.get("sections_withheld") or []
    assert any("Perspective" in s for s in _wh), (
        "the per-tradition perspective sections are not withheld on the floor, so a tradition's position "
        "that nothing looked up is shown as a frame", _wh)
    for _s in ("Points of Convergence", "Points of Divergence"):
        assert _s in _wh, ("a comparative section nothing compared is still rendered", _s, _wh)
    #  the headings are built FROM THE REQUEST, so a fixed list would miss them
    assert any("charity" in s for s in _wh), (
        "the withheld list does not carry the headings this route builds per call", _wh)
    assert "## " not in _if["analysis"], (
        "a research heading survives in the analysis after withholding", _if["analysis"][:200])

    # ── FU-436 (c): THE SHIPPED BASIS SAYS WHAT THE CLASS DOES ───────────────────────────────────
    #  Asserted on the LOADED VALUE, not the file: the comment above the string records the false claim it
    #  replaced, so a text search would match its own record.
    from agentic_core.vbs.quality import LAYER_STATE as _LS593
    _endo = _LS593["Endocrine"]["basis"]
    assert "integral term" not in _endo, (
        "the quality record still tells every reader the Endocrine regulator has an integral term, while "
        "the regulator's own docstring says `integral_error` is never accumulated", _endo[:200])
    assert "PROPORTIONAL THRESHOLD" in _endo, ("the basis does not say what the class actually does", _endo)
    assert "NOTHING IMPORTS IT" in _endo, ("the unreached half of the basis was lost with the fix", _endo)

    # ── FU-438 (d): THE CLOSE IS CREDITED TO THE ROUTINE THAT DID IT, IN BOTH WRITERS ────────────
    for _f593 in ("agentic_core/api/economy.py", "agentic_core/economy/ledger.py"):
        _src = (_root593 / _f593).read_text(encoding="utf-8")
        _lines = [ln for ln in _src.splitlines() if '"prepared_by":' in ln]
        assert _lines, ("this writer no longer records who prepared the figures", _f593)
        for _ln in _lines:
            assert "CFO agent" not in _ln, (
                "a period close is still credited to a CFO agent that is on no roster - and fixing one "
                "writer and not the other is the class this programme keeps recording", _f593, _ln.strip())
            assert "close routine" in _ln, (
                "the attribution does not name what actually produced the figures", _f593, _ln.strip())

    # ── FU-420 (b) · FU-434 (d) · FU-433 (f): THE FRONTEND CLAIMS ───────────────────────────────
    _ltm = (_root593 / "apps/workstation-superapp/src/components/LearnTeachModule.tsx").read_text(
        encoding="utf-8")
    #  THE CALL, NOT THE NAME. This read `"provenanceBadge" in _ltm`, which the IMPORT LINE satisfies - a
    #  blind that removed the call and left the import kept this leg GREEN, which is the exact state the
    #  row describes: a badge helper imported and never used.
    assert "provenanceBadge(reportServedBy)" in _ltm, (
        "the Qur'an study panel does not CALL the provenance helper on what served it, so floor-composed "
        "curriculum reaches a learner unlabelled on the surface §11 binds hardest")
    assert "qep-studyframe-provenance" in _ltm, (
        "the badge is computed and never rendered, so nothing reaches the page")
    #  W611 (FU-469) — over the CODE, not the file: "ai_provenance" survived only in a comment here, so this
    #  leg passed on documentation (FU-468's class). The property is that the response's served_by is SET.
    import re as _re593b
    _ltm_code = "\n".join(ln for ln in _re593b.sub(r"/\*.*?\*/", "", _ltm, flags=_re593b.S).splitlines()
                          if not ln.lstrip().startswith("//"))
    assert "setReportServedBy(data.served_by" in _ltm_code, ("the response's own provenance is still never read")
    assert "qualified teacher" in _ltm, (
        "the panel does not direct the reader to a qualified teacher, which §11 rule 5 requires")
    assert "not reviewed curriculum" in _ltm, ("the panel does not say what the text is NOT")
    _btn = [ln for ln in _ltm.splitlines() if "<Button" in ln and "Generate" in ln]
    assert _btn and not any("Class Report" in ln for ln in _btn), (
        "the button still asserts a class report, one panel below this file's own line saying no roster "
        "exists on this deployment", _btn)

    _hub = (_root593 / "apps/workstation-superapp/src/pages/domains/ReligionHub.tsx").read_text(
        encoding="utf-8")
    assert not [ln for ln in _hub.splitlines() if "<Button" in ln and "Ethics Council" in ln], (
        "a button still offers an Ethics Council, which does not exist - no body, no roster, no route")

    _qep = (_root593 / "apps/workstation-superapp/src/components/QEPFlagshipFeatures.tsx").read_text(
        encoding="utf-8")
    _card = [ln for ln in _qep.splitlines() if "id: 'adaptive_ui'" in ln]
    assert len(_card) == 1, ("the adaptive-UI roadmap card is gone or duplicated", len(_card))
    assert "adjusts to age and emotion" not in _card[0], (
        "the roadmap still advertises an emotion-adaptive interface, which Appendix A.9.4 ratifies as "
        "REFUSED - the product promising what its own constitution forbids", _card[0][:160])
    assert "never inferred" in _card[0], (
        "the card does not state the boundary, so a reader cannot tell a refusal from a backlog item",
        _card[0][:160])
    #  and the live mechanism it describes is still the honest preference-based one
    _aui = (_root593 / "apps/workstation-superapp/src/components/AdaptiveUIProvider.tsx").read_text(
        encoding="utf-8")
    assert "ui.tone" in _aui, (
        "the adaptive-UI label no longer derives from the saved preference, so something else now feeds it")
def test_w593_p220_the_mark_is_derived_and_the_roadmap_is_in_time_order():
    """P2.20 — seven more rows, each a figure or a mark that now comes FROM the state it describes.

      FU-427 (e) the living Roadmap ordered phases by the order objectives were TYPED IN, so it named a
                 Q4 2026 current phase while a Q1 2026 objective sat at 0%. Owner ruling 2026-10-05: sort
                 by a parsed date and park what does not parse under Unscheduled, excluded from
                 current/next - plus fix the writer that injected "next review" as a timeline.
      FU-423 (c) an EMPTY §4 section was recorded as not-pending, so the stage derivation found no gap and
                 said "every §4 section on this entity is composed" for an entity with none.
      FU-424 (c) the terminal spawn event announced "VSB Operational" seven lines below the derived status
                 that said otherwise.
      FU-422 (c) generate_vsb_repo writes manifest.json FIRST, so running it first described a disk holding
                 13 of the eventual 29 files and called the generated apps absent.
      FU-429 (d) the establish stream told a founder their Board was "chaired by the owner's Chief twin".
      FU-435 (d) two unbuilt tabs answered a click with a release name, and told the user their own DEVICE
                 was the obstacle when no WebXR code exists at all.
      FU-437 (c) the cash-flow statement reported a net movement that is zero BY CONSTRUCTION, with nothing
                 saying so.
    """
    import pathlib as _pl593c

    _root = _pl593c.Path(__file__).resolve().parents[1]

    # ── FU-427 (e): THE ROADMAP IS IN TIME ORDER, AND WHAT CANNOT BE PLACED IS NOT A PHASE ──────
    from agentic_core.api import business_plan as _bp593
    _plan593 = {"objectives": [
        {"id": "a", "title": "Commission the Birmingham filtration pilot", "timeline": "Q4 2026",
         "progress_pct": 10, "status": "planned"},
        {"id": "b", "title": "Chief fallback objective", "timeline": "next review",
         "progress_pct": 0, "status": "planned"},
        {"id": "c", "title": "Secure the Q1 grant", "timeline": "Q1 2026",
         "progress_pct": 0, "status": "planned"},
        {"id": "d", "title": "Hire the ops lead", "timeline": "March 2026",
         "progress_pct": 0, "status": "planned"},
    ]}
    _rm = _bp593._roadmap(_plan593)
    _phases = [p["timeline"] for p in _rm["phases"]]
    assert _phases == ["Q1 2026", "March 2026", "Q4 2026", "Unscheduled"], (
        "the roadmap's phases are not in TIME order - this is the entry order the Owner ruled against, "
        "which named a Q4 phase current while a Q1 objective sat at 0%", _phases)
    assert _rm["current_phase"] == "Q1 2026", (
        "the current phase is not the earliest incomplete one in time", _rm["current_phase"])
    assert (_rm["next_milestone"] or {}).get("title") == "Secure the Q1 grant", (
        "next_milestone is a definite claim about what comes next in TIME and it names the wrong objective",
        _rm["next_milestone"])
    assert _rm["unscheduled_count"] == 1 and _rm["unparsed_timelines"] == ["next review"], (
        "an objective whose timeline cannot be placed is not counted and named, so the roadmap drops it "
        "silently", _rm["unscheduled_count"], _rm["unparsed_timelines"])
    assert "TIME ORDER" in _rm["note"] and "Unscheduled" in _rm["note"], (
        "the surface does not say how the phases are ordered, which is what made the old order "
        "undisclosed rather than merely wrong", _rm["note"])
    #  and Unscheduled can never be the current phase, even when it is the only incomplete one
    _only_un = _bp593._roadmap({"objectives": [
        {"id": "x", "title": "unplaceable", "timeline": "when the grant lands", "progress_pct": 0}]})
    assert _only_un["current_phase"] is None, (
        "an unplaceable objective became the CURRENT PHASE, which answers a question about time with a "
        "non-answer", _only_un["current_phase"])
    #  THE WRITER: the platform must not inject a non-temporal placeholder into a timeline
    _board_src = (_root / "agentic_core/api/board.py").read_text(encoding="utf-8")
    _fallback = [ln for ln in _board_src.splitlines()
                 if "KPI to be set by the Board" in ln and not ln.strip().startswith("#")]
    assert _fallback, ("the chief_instruct fallback is gone, so this leg measures nothing", len(_fallback))
    assert not any("next review" in ln for ln in _fallback), (
        "the platform still writes 'next review' into the TIMELINE position, so it feeds a fake phase into "
        "its own time-phased roadmap", _fallback)

    # ── FU-423 (c): AN EMPTY §4 SECTION IS PENDING ──────────────────────────────────────────────
    from agentic_core.api import genesis as _g593
    from agentic_core.api import vsb as _v593

    class _Req593:
        concept = ""
        design = ""
        commercialisation = ""
        ai_provenance = None

    _req = _Req593()
    #  TWO MAPS, because they are two facts. The first pass of this fix widened `body_pending` to cover an
    #  empty section, and `body_pending` drives the entity STATUS - so every entity would have been "body
    #  pending" forever (no establish path provides §4.7 operations) and FU-425's operating count would
    #  have gone structurally zero again in the round that fixed it. `body_absent` carries the new fact.
    _pend, _absent = _g593._resolve_body_fields(_req)
    assert _absent and all(_absent.values()), (
        "an EMPTY §4 section is recorded as not awaiting content, so the stage derivation finds no gap and "
        "reports the lifecycle as composed on an entity that composed nothing", _absent)
    assert not any(_pend.values()), (
        "a section nobody provided is recorded as FLOOR-COMPOSED, which is a different fact and makes "
        "every entity body-pending forever", _pend)
    _stage, _basis = _v593._derived_stage({"body_pending": _pend, "body_absent": _absent})
    assert _stage is None, ("a stage is reported for an entity with every section empty", _stage, _basis)
    assert "was never provided" in _basis, (
        "the basis does not distinguish a section nobody supplied from one the floor composed while a real "
        "model is awaited - merging them was the defect this fix reintroduced once already", _basis)
    assert "every §4 section" not in _basis, (
        "the basis still claims every section is composed", _basis)
    #  and the floor-composed case keeps its own sentence, so the two are not merged the other way either
    _stage_f, _basis_f = _v593._derived_stage({"body_pending": {"concept": True}, "body_absent": {}})
    assert _stage_f is None and "awaits the owned model" in _basis_f, (
        "a floor-composed section no longer reads as awaiting the owned model", _stage_f, _basis_f)

    # ── FU-424 (c) · FU-429 (d) · FU-422 (c): THE SPAWN STREAM AND THE SHIP ORDER ───────────────
    _vsb_src = (_root / "agentic_core/api/vsb.py").read_text(encoding="utf-8")
    _code = [ln for ln in _vsb_src.splitlines() if not ln.strip().startswith("#")]
    assert not any('"VSB Operational"' in ln for ln in _code), (
        "the terminal spawn event still hardcodes a status seven lines below the derived one")
    assert any('_event("complete", f"VSB {_st}"' in ln for ln in _code), (
        "the terminal event does not carry the DERIVED status, so the mark is still written beside the "
        "state instead of from it")
    assert not any("owner's Chief twin" in ln for ln in _code), (
        "the establish stream still tells a founder their Board is chaired by a twin; no twin model is "
        "trained and this file's own comment says so")
    #  the manifest must be written against the finished disk: repo runs LAST
    _i_repo = _vsb_src.index('("repo", generate_vsb_repo)')
    for _other in ('("website", generate_vsb_website)', '("webapp", generate_vsb_webapp)',
                   '("mobile", generate_vsb_mobile)', '("board_pack", generate_vsb_board_pack)'):
        assert _vsb_src.index(_other) < _i_repo, (
            "generate_vsb_repo runs before another generator, so manifest.json is written against a disk "
            "that is still being built and under-reports the repository", _other)

    # ── FU-435 (d): A CLICK NAMES WHAT IS ABSENT, AND NEVER THE READER'S DEVICE ─────────────────
    _qep = (_root / "apps/workstation-superapp/src/pages/domains/QEPReligionHub.tsx").read_text(
        encoding="utf-8")
    _toasts = [ln.strip() for ln in _qep.splitlines() if "toast(" in ln]
    assert _toasts, "the flagship tabs answer a click with nothing at all"
    for _bad, _why in (("Season 2", "a toast names a release that does not exist"),
                       ("coming in Phase", "a toast promises a plan-internal phase to a learner"),
                       ("requires a WebXR", "a toast puts the absence on the reader's own device")):
        assert not [t for t in _toasts if _bad in t], (_why, [t[:80] for t in _toasts if _bad in t])
    assert any("not blocked by your" in t for t in _toasts), (
        "nothing tells the reader the absence is the product's and not their equipment's")

    # ── FU-437 (c): THE CASH-FLOW STATEMENT SAYS WHAT IT SUMS ───────────────────────────────────
    _ledg = (_root / "agentic_core/economy/ledger.py").read_text(encoding="utf-8")
    _cf = _ledg[_ledg.index('"cash_flow": {'):]
    _cf = _cf[:_cf.index('"trial_balance"')]
    assert '"scope"' in _cf and '"basis"' in _cf, (
        "cash_flow reports a net movement with no scope and no basis, so a reader takes a structural zero "
        "for a finding that cash in matched cash out", _cf[:200])
    assert "ZERO BY CONSTRUCTION" in _cf, (
        "the basis does not say the zero cannot be anything else on a period built from the compat "
        "postings", _cf[:300])
    assert "reserve_fund" in _cf, (
        "the basis does not name where the movements it cannot see are posted", _cf[:300])
def test_w593_p220_the_last_three_a_count_a_verdict_and_a_cadence_that_reaches_everything():
    """P2.20 — the last three of MILESTONE M1's twenty.

      FU-425 (c) the Organism page's operating count matched ("operational", "active") while
                 `_derived_status` returns "operating", so the figure was structurally ZERO for every
                 entity whose status was derived — and the readiness computed from it was lowered. The SAME
                 defect W438 fixed once: that round counted "active" when the writer wrote "operational".
                 The term is now imported from the writer, so a third vocabulary change cannot orphan it.
      FU-428 (c) a governance verdict carried `scope: "... content was NOT screened ..."` AND
                 `content_screened: true` on one payload, because the sentence was assigned BEFORE
                 `out.update(extra)`. It is derived from the final value now, so the contradiction is not
                 something a caller can express.
      FU-431 (e) the §17.3 cadence refreshed the workstation apex only — MY OWN defect from W585 — so no
                 VSB's Strategic or Action-Plan layer was ever refreshed while the surface spoke of the
                 layers generally.
    """
    import asyncio as _aio4
    import json as _json4
    import os as _os4
    import tempfile as _tf4

    # ── FU-428 (c): THE SCOPE SENTENCE IS DERIVED FROM WHAT WAS SCREENED ────────────────────────
    from agentic_core.gaas.v5 import intent_gate_result as _gate4
    _intent_only = _gate4("allowed", "cp-intent")
    assert _intent_only["content_screened"] is False, _intent_only
    assert "NOT screened" in _intent_only["scope"], (
        "a gate that screened only the intent no longer says the content was not screened", _intent_only)
    _with_content = _gate4("allowed", "cp-content", content_screened=True, content_chars=38253,
                           tiers_screened=["t1", "t2"])
    assert _with_content["content_screened"] is True, _with_content
    assert "NOT screened" not in _with_content["scope"], (
        "one payload says the content WAS screened and its scope sentence says it was NOT - the "
        "contradiction M1 found, and a reader cannot tell which to believe", _with_content["scope"])
    assert "the delivered content" in _with_content["screened"], (
        "the summary and the sentence have drifted apart", _with_content["screened"])
    #  and a caller cannot reintroduce it by passing a scope of its own through **extra
    _forced = _gate4("allowed", "cp", content_screened=True, scope="whatever I feel like")
    assert "NOT screened" not in _forced["scope"] and "delivered content" in _forced["scope"], (
        "a caller overrode the derived scope sentence, so the contradiction is expressible again", _forced)

    # ── FU-425 (c) and FU-431 (e), both driven against a seeded store ───────────────────────────
    _d4 = _tf4.mkdtemp(prefix="w593last-")
    _saved4 = {k: _os4.environ.get(k) for k in ("DATA_DIR", "WORKSTATION_DATA_DIR", "PROJECTS_DIR")}
    try:
        for _k in _saved4:
            _os4.environ[_k] = _d4
        import importlib
        import agentic_core.config as _cfg4
        importlib.reload(_cfg4)

        #  FU-425: the counter reads the writer's own term
        from agentic_core.api.vsb import OPERATING_STATUS as _OP4
        assert _OP4 == "operating", ("the writer's operating term changed and this guard did not", _OP4)
        _ent = _cfg4.data_path("vsb_entities")
        _ent.mkdir(parents=True, exist_ok=True)
        for _i, _s in enumerate(["operating", "operating", "held", "operational", "body pending"]):
            (_ent / f"vsb-g4-{_i}.json").write_text(
                _json4.dumps({"vsb_id": f"vsb-g4-{_i}", "status": _s, "domain": "care"}),
                encoding="utf-8")
        import agentic_core.api.organism_status as _os_mod4
        importlib.reload(_os_mod4)
        _vs = _os_mod4._vsb_state()
        assert _vs["operating"] == 2, (
            "the count does not match the vocabulary `_derived_status` actually returns, so it is "
            "structurally zero for every derived entity - the defect W438 fixed once already", _vs)
        assert _vs["legacy_operating"] == 1, (
            "pre-W496 rows are not counted in their own named bucket, so the figure silently spans two "
            "vocabularies", _vs)
        assert _vs["operational"] == 3, ("the headline figure is not the sum of the two buckets", _vs)
        assert _OP4 in _vs["operational_basis"] and "NOT counted" in _vs["operational_basis"], (
            "the basis does not name which statuses were counted and which were not", _vs)

        #  FU-431: the cadence reaches one living entity per beat as well as the apex
        _reg4 = _cfg4.data_path("living_vsbs.json")
        _reg4.parent.mkdir(parents=True, exist_ok=True)
        _reg4.write_text(_json4.dumps({
            "vsb-g4-a": {"vsb_id": "vsb-g4-a", "status": "living"},
            "vsb-g4-b": {"vsb_id": "vsb-g4-b", "status": "living"}}), encoding="utf-8")
        #  THE ROSTER MODULE RESOLVES ITS PATH ONCE, AT FIRST IMPORT. `living_vsbs._STORE` is a module
        #  constant, so whichever test imported it first in this session froze the path - and the beat reads
        #  through that binding. Writing a roster to this test's own data dir and reloading only `heartbeat`
        #  drove a file nobody reads: this leg failed in the suite, passed alone, and blamed the fix for
        #  scopes that belonged to another guard's entities. The binding the READER resolves is redirected
        #  and restored, which is what test_w587 does for the Change Control store; reloading the roster
        #  module instead would re-freeze the path for every later test.
        import agentic_core.economy.living_vsbs as _lv4
        import agentic_core.organism.heartbeat as _hb4
        importlib.reload(_hb4)
        _lv_store4 = _lv4._STORE
        try:
            _lv4._STORE = _reg4
            #  the roster the beat will actually read, asserted BEFORE the behaviour, so a leaked entity is
            #  reported as a leak rather than charged to the code under test
            _roster4 = {k for k, v in (_lv4._load() or {}).items() if isinstance(v, dict)}
            assert _roster4 == {"vsb-g4-a", "vsb-g4-b"}, (
                "the beat is not reading this test's roster, so whatever it visits says nothing about the "
                "rotation", sorted(_roster4))
            _seen4 = set()
            for _ in range(3):
                _aio4.run(_hb4.heartbeat.beat())
                _lc4 = _hb4.heartbeat.last_cadence or {}
                _seen4.update(_lc4.get("scopes") or [])
        finally:
            _lv4._STORE = _lv_store4
        assert "workstation" in _seen4, (
            "the apex stopped being refreshed, which the whole platform reads", sorted(_seen4))
        assert {"vsb-g4-a", "vsb-g4-b"} <= _seen4, (
            "the cadence never reached a VSB's own layers, so §17.3 runs for the apex alone while the "
            "surface speaks of the layers generally", sorted(_seen4))
        _basis4 = str((_hb4.heartbeat.last_cadence or {}).get("scope_basis") or "")
        assert "living entit" in _basis4 and "REGULARLY" in _basis4, (
            "the record does not say how the entity was chosen or admit that the rotation shifts with the "
            "roster, so a reader takes 'every entity' for a guarantee", _basis4)
    finally:
        for _k, _v in _saved4.items():
            if _v is None:
                _os4.environ.pop(_k, None)
            else:
                _os4.environ[_k] = _v
        import importlib as _il4
        import agentic_core.config as _c4
        _il4.reload(_c4)


def test_w593_p220_the_qep_flagship_service_reports_only_what_it_holds():
    """P2.20 (c)(d)(f) · FU-440..444 — the four flagship methods that still returned literals.

    Found by sweeping P2.20's clauses rather than its rows: ACCEPT (1) closes a clause when its MECHANISM
    holds nowhere it applies, so the rows were evidence and this is the check. Eight of the thirteen
    methods in this service were made honest across W331, W403 and W404; four were never audited and still
    answered with counts, a status and a timestamp that nothing measured. That the class recurs after being
    closed twice is the finding - "fix every writer, not one", across rounds rather than within one.

    DRIVEN, NOT GREPPED: the docstrings now record what was removed, so a source-text guard would match the
    sentences describing the removal (W495, five red runs). The one source check is an ABSENCE, and it is
    safe only because those docstrings describe the two forum titles instead of quoting them.
    """
    import asyncio as _aio440
    import pathlib as _pl440

    from agentic_core.reactor.religion.qep_flagship import qep_flagship_service as _s440

    #  FU-440 — a faith question is not answered by a placeholder, and no engine is credited for it
    _g440 = _aio440.run(_s440.ai_guidance_assistant("Is this transaction permissible?"))
    assert _g440["response"] is None and _g440["answered"] is False, (
        "the guidance assistant still answers a faith question with a literal sentence", _g440)
    assert _g440["source"] is None and _g440["local_inference"] is False, (
        "an answer nothing produced is still credited to a named engine, and inference is still asserted",
        _g440)
    assert not [k for k in _g440 if "emotion" in k.lower()], (
        "a religion response still carries an emotion label, which is one of the six boundaries "
        "Appendix A.9 records as forbidden - it is not a field to keep as decoration", sorted(_g440))
    assert _g440.get("detail"), "the refusal does not say why nothing was answered"

    #  FU-441 — READY with no code, no asset and no transport; and the reader's device is never blamed
    _v440 = _aio440.run(_s440.ar_vr_immersion("VR"))
    assert _v440["status"] == "NOT_IMPLEMENTED", (
        "the immersion tool still answers READY while no scene code or asset exists", _v440)
    assert _v440["scene_url"] is None and _v440["webrtc_channel"] is None \
        and _v440["interactive_nodes"] is None, (
        "a scene file, a node count or a channel for a transport nothing speaks is still reported", _v440)
    assert "not blocked by the reader" in (_v440.get("detail") or "").lower() \
        or "NOT blocked by the reader" in (_v440.get("detail") or ""), (
        "the gap is reported without saying it is the product's and not the reader's device", _v440)

    #  FU-442 — nothing stores a forum, a post, a circle or a membership
    _c440 = _aio440.run(_s440.community_features())
    assert _c440["forums"] == [] and _c440["circles"] == [], (
        "forums and circles are still reported over a store that holds none of them", _c440)
    assert _c440["websocket_endpoint"] is None, (
        "a websocket endpoint is still named; the application mounts exactly one and it is not this",
        _c440)
    assert _c440.get("detail"), "the empty community does not say why it is empty"

    #  FU-443 — a sync that always just finished
    _o440 = _aio440.run(_s440.offline_global_access("w593-user"))
    assert _o440["sync_manifest"] is None and _o440["last_full_sync"] is None, (
        "a sync manifest is still reported, and a last_full_sync stamped with the current time says a "
        "full sync finished moments ago on every call, forever", _o440)
    assert _o440["offline_capabilities"] == [], (
        "offline capabilities are still listed with no sync mechanism and no service worker", _o440)

    #  the two forum titles named ratified boundaries — asserted as an ABSENCE on the source, which is
    #  only safe because the docstrings describe them rather than quoting them
    _src440 = (_pl440.Path(__file__).resolve().parents[1]
               / "agentic_core/reactor/religion/qep_flagship.py").read_text(encoding="utf-8")
    for _banned440 in ("Recitation Feedback", "Scholar Q&A"):
        assert _banned440 not in _src440, (
            "a forum title still advertises one of the six capabilities Appendix A.9 records §11 as "
            "forbidding, as a live community rather than as withheld", _banned440)
    assert "Production Grade" not in _src440 and "Production-Grade" not in _src440 \
        and "Production Ready" not in _src440, (
        "a method still calls itself production grade while returning literals")

    #  FU-444 — every flagship card discloses its state; four did and seven asserted a capability
    _cards440 = (_pl440.Path(__file__).resolve().parents[1]
                 / "apps/workstation-superapp/src/components/QEPFlagshipFeatures.tsx"
                 ).read_text(encoding="utf-8")
    import re as _re440
    _descs440 = {m.group(1): m.group(2) for m in
                 _re440.finditer(r"id: '([a-z_]+)'[^\n]*?desc: '((?:[^'\\]|\\.)*)'", _cards440)}
    assert len(_descs440) >= 13, ("the card array stopped parsing, so this leg measures nothing",
                                  sorted(_descs440))
    # W613 (FU-476) — "Not offered, by ruling" is a state too: a ratified boundary, not a backlog item
    _MARKERS440 = ("Planned:", "LIVE", "NOT measured", "are real", "is recorded", "No cohort", "Not offered, by ruling")
    _bare440 = {k: v[:70] for k, v in _descs440.items()
                if not any(m in v for m in _MARKERS440)}
    assert not _bare440, (
        "a flagship card states a capability with no disclosure of its state, while four cards in the "
        "same array carry an explicit one - the convention reached some of them and not the rest",
        _bare440)


def test_w594_r7_a_named_scholar_approves_before_a_learner_sees_it(client):
    """A.12.3 (Owner ruling 2026-10-05b R7) — the scholar-review gate, driven through every state.

    WHAT IT REPLACES. `QEPAuthoringReactor` already had the SHAPE of this mechanism and gated nothing:
    its queue was a plain list on the instance, so every approval died with the process; approval tested
    `approver_trust = params.get("trust_score", 0.0)` — a number the CALLER supplied about itself — with
    `scholar_id` whatever the caller typed; and nothing in the learner path consulted it. A mechanism that
    looks like §11's required audit and verifies nothing is worse than none, because a reader of the file
    concludes the audit exists.

    CORRECT AND INERT BY CONSTRUCTION: approval requires the reviewer to be on a roster that is EMPTY
    until the Owner puts a real person in it, so today every learner-facing item is withheld and the
    surfaces behave as W593 left them — while the behaviour is now a gate rather than a hope.

    THE ROSTER IS RESTORED at the end: the gate's inertness is a property other guards may rely on, and
    leaving a scholar behind would quietly change what they test.
    """
    import json as _j594
    import pathlib as _pl594

    from agentic_core.api import scholar_review as _sr594
    from agentic_core.config import data_path as _dp594

    _roster_p = _dp594("scholar_roster.json")
    _review_p = _dp594("scholar_review.json")
    _saved_roster = _roster_p.read_bytes() if _roster_p.exists() else None
    _saved_review = _review_p.read_bytes() if _review_p.exists() else None
    _KEY = "tajweed_lesson:W594Idgham:beginner"
    try:
        #  start from an empty roster whatever the ambient store holds — the gate's first property is
        #  about having no scholar, and a leftover one from another test would make this leg vacuous
        if _roster_p.exists():
            _roster_p.unlink()

        # ── (1) WITH NO SCHOLAR, A LEARNER GETS NO BODY AND IS TOLD WHY ───────────────────────────
        _r594 = client.post("/api/v1/qep/tajweed/lesson",
                            json={"rule_name": "W594Idgham", "level": "beginner"})
        assert _r594.status_code == 200, _r594.text[:200]
        _b594 = _r594.json()
        assert _b594["lesson_plan"] is None, (
            "AI-composed religious teaching content reaches a learner with no scholarly review. A.12.3 "
            "requires the audit and a disclaimer is NOT a review", str(_b594)[:300])
        assert _b594["review_state"] == "withheld" and _b594["scholar_reviewed"] is False
        assert "no scholar" in _b594["review_note"].lower(), (
            "the learner is not told WHY the content is withheld, so an absence reads as a fault",
            _b594["review_note"])
        #  and the honest caveats W439 put there are still present — the gate joins them, not replaces
        assert _b594.get("disclaimer") and _b594.get("served_by"), _b594

        # ── (2) A TRUST SCORE THE CALLER ASSERTS APPROVES NOTHING ────────────────────────────────
        _d1 = _sr594.decide(_KEY, "whoever", approve=True)
        assert _d1["ok"] is False and _d1["reason"] == "no_scholar_engaged", (
            "an approval succeeded with no scholar on the roster", _d1)
        assert "not a lookup failure" in _d1["detail"], (
            "an empty roster is reported as though the reviewer id were wrong - two different facts, and "
            "collapsing them sends a caller hunting for a typo", _d1["detail"])

        # ── (3) A REVIEWER OFF THE ROSTER IS REFUSED, AND DISTINCTLY ─────────────────────────────
        _sr594.add_scholar("w594-shaykh", "A Named Scholar", "ijazah", "pytest-owner")
        _d2 = _sr594.decide(_KEY, "someone-else", approve=True)
        assert _d2["ok"] is False and _d2["reason"] == "reviewer_not_on_roster", (
            "any id can approve, so `approved_by` records a name nobody verified", _d2)

        # ── (4) A ROSTERED REVIEWER APPROVES WITH NO SCORE AT ALL, AND THE BODY IS SERVED ────────
        _d3 = _sr594.decide(_KEY, "w594-shaykh", approve=True, note="checked")
        assert _d3["ok"] is True and _d3["record"]["state"] == "approved", _d3
        _r2 = client.post("/api/v1/qep/tajweed/lesson",
                          json={"rule_name": "W594Idgham", "level": "beginner"}).json()
        assert _r2["lesson_plan"] and _r2["scholar_reviewed"] is True, (
            "an approved lesson is still withheld from the learner", str(_r2)[:300])

        # ── (5) THE APPROVAL SURVIVES THE NEXT REQUEST ───────────────────────────────────────────
        #  `submit` overwrites and sets in_review, so composing again would have RESET the approval -
        #  a scholar's sign-off lasting until the next page load. Caught before wiring; guarded here.
        _r3 = client.post("/api/v1/qep/tajweed/lesson",
                          json={"rule_name": "W594Idgham", "level": "beginner"}).json()
        assert _r3["review_state"] == "approved", (
            "re-composing reset the approval, so a scholar's sign-off survives only until the next "
            "request", _r3["review_state"])

        # ── (6) AN APPROVED BODY EDITED AFTERWARDS FALLS BACK TO WITHHELD ────────────────────────
        _body, _st, _why = _sr594.published_body(_KEY, "A DIFFERENT LESSON TEXT")
        assert _body is None and "CHANGED" in _why, (
            "text edited after approval inherits that approval, so a reviewer's sign-off covers words "
            "they never read", _st, _why)

        # ── (7) A REJECTION IS NEVER RENDERED ───────────────────────────────────────────────────
        _sr594.decide(_KEY, "w594-shaykh", approve=False, note="not sound")
        _r4 = client.post("/api/v1/qep/tajweed/lesson",
                          json={"rule_name": "W594Idgham", "level": "beginner"}).json()
        assert _r4["lesson_plan"] is None and "rejected" in _r4["review_note"].lower(), (
            "content a reviewer REJECTED is still served to a learner", str(_r4)[:300])

        # ── (8) THE SCOPE LINE IS GUARDED: SECULAR CURRICULUM IS NOT GATED ──────────────────────
        #  The gate covers the LEARNER RELIGIOUS path. /api/v1/education/curriculum serves Bloom's, the
        #  UK National Curriculum, IGCSE, IB, Montessori, STEM and UbD - gating it would withhold
        #  secular curriculum from everyone. That line is the author's, not the Owner's (FU-448), so it
        #  is asserted rather than left to be widened by accident in a later round.
        _edu = client.post("/api/v1/education/curriculum",
                           json={"topic": "photosynthesis", "framework": "bloom", "level": "ks3"})
        assert _edu.status_code in (200, 422), ("the general education route broke", _edu.status_code)
        if _edu.status_code == 200:
            assert "review_state" not in _edu.json(), (
                "the scholar-review gate has been applied to the GENERAL education route, which "
                "withholds secular curriculum from every user - see FU-448, which is the Owner's")
    finally:
        for _p, _v in ((_roster_p, _saved_roster), (_review_p, _saved_review)):
            if _v is None:
                if _p.exists():
                    _p.unlink()
            else:
                _p.write_bytes(_v)
        assert _sr594.roster_is_empty() or _saved_roster is not None, (
            "this guard left a scholar on the roster, which changes the gate for every later test")


def test_w594_the_owners_rulings_of_2026_10_05b_hold_in_code_and_in_canon(client):
    """R2–R6 and R8–R11 (Owner ruling 2026-10-05b) — each ruling, driven or read where it lives.

    Behaviour is DRIVEN. A ruling whose entire content is a record (amend §10, scope Mode 2, defer the
    Fitrah Spectrum) is asserted on the canon, and on BOTH halves: the new statement present AND the old
    claim gone. Asserting only the new one passes while the contradiction sits two lines below — the
    second-writer class this plan keeps finding; asserting only the absence passes on an empty file.
    """
    import pathlib as _pl594b

    _root594 = _pl594b.Path(__file__).resolve().parents[1]
    _vision = (_root594 / "docs/WORKSTATION_IDBO_WHOLE_VISION.md").read_text(encoding="utf-8")
    _plan594 = (_root594 / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")

    # ── R4: the PRODUCTS axis exists and REACHES a journey ──────────────────────────────────────
    from agentic_core.taxonomy import PRODUCTS, PRODUCT_LABELS, normalise_product
    assert len(PRODUCTS) == 4 and set(PRODUCTS) == {"reactor", "incubator", "factory", "laboratory"}, (
        "§17.1's Products axis is not the four the canon names", PRODUCTS)
    assert set(PRODUCT_LABELS) == set(PRODUCTS), ("a product has no label", sorted(PRODUCT_LABELS))
    assert normalise_product("widget") == "reactor" and normalise_product("Factory") == "factory", (
        "an unrecognised product is stored as given instead of falling to the default")
    _j594 = client.post("/api/v1/genesis/journey",
                        json={"problem": "w594 product axis probe", "domain": "science",
                              "realm": "enterprise", "product": "laboratory"}).json()
    assert _j594.get("product") == "laboratory", (
        "the Products axis does not reach a Genesis journey, so the third axis is a constant nothing "
        "uses - which is the state R4 was ruled to end", {k: _j594.get(k) for k in ("product", "realm")})
    assert _j594.get("product_label"), "the recorded product carries no label"

    # ── R5: the KPI gate blocks RELEASE and NAMES what is missing ───────────────────────────────
    from agentic_core.api import business_plan as _bp594
    _g0 = _bp594.kpi_release_gate("vsb-w594-absent")
    assert _g0["ok"] is False and _g0["reason"] == "no_objectives", (
        "an entity with no objectives is not distinguished from one whose KPIs are unset - two states "
        "that send a founder to different places", _g0)
    _p594 = _bp594._load("vsb-w594-gate")
    _p594["objectives"] = [{"id": "o1", "title": "Reach 100 learners", "kpi": ""},
                           {"id": "o2", "title": "Break even", "kpi": "margin > 0"}]
    _bp594._save(_p594)
    _g1 = _bp594.kpi_release_gate("vsb-w594-gate")
    assert _g1["ok"] is False and _g1["reason"] == "kpi_not_set", _g1
    assert [m["title"] for m in _g1["missing"]] == ["Reach 100 learners"], (
        "the gate refuses without naming WHICH objective lacks a KPI, which the ruling made a binding "
        "condition because this gate blocks flows that worked yesterday", _g1)
    assert "Reach 100 learners" in _g1["detail"], ("the detail does not name it either", _g1["detail"])
    _p594["objectives"][0]["kpi"] = "100 enrolled"
    _bp594._save(_p594)
    assert _bp594.kpi_release_gate("vsb-w594-gate")["ok"] is True, "a fully-measured entity is blocked"

    # ── R8 + R11: licence, edition and riwayah travel with the corpus ──────────────────────────
    from agentic_core.religious_domain.api import _corpus_provenance as _cp594
    _k594 = _cp594("quran-uthmani")
    for _f in ("source", "edition", "script", "riwayah", "licence", "provenance_basis"):
        assert _k594.get(_f), (f"corpus provenance omits {_f!r}, so a reader cannot tell which "
                               f"transmission they have", sorted(_k594))
    assert "never generated" in _k594["licence"], (
        "the licence line drops the §11 statement that the Arabic is fetched and never AI-generated")
    _u594 = _cp594("quran-some-unserved-edition")
    assert _u594["riwayah"] is None and "NOT DECLARED" in _u594["provenance_basis"], (
        "an edition whose riwayah this platform has not established is ASSIGNED one, which is the "
        "scholarly claim the ruling forbids it from making", _u594)

    # ── R9: a record of completion, and no credential and no dead verify link ──────────────────
    import asyncio as _aio594
    from agentic_core.reactor.religion.qep_flagship import qep_flagship_service as _s594b
    _u = _s594b._get_user("w594-learner")
    _u["progress"] = {"c1": {"completed": True, "completed_at": "2026-10-01"}}
    _c594 = _aio594.run(_s594b.certifications("w594-learner", "c1"))
    assert _c594["is_credential"] is False and _c594["status"] == "RECORDED", (
        "QEP still issues something shaped like a credential in its own name, with no body behind it",
        _c594)
    assert "certificate_id" not in _c594 and "verify_url" not in _c594, (
        "the certificate shape survives - and verify_url pointed at /verify/{id}, which nothing serves, "
        "so a learner checking their credential got a 404", sorted(_c594))
    assert "not a credential" in _c594["detail"], _c594["detail"]

    # ── R3: §10 states what it measures AND what it does not ───────────────────────────────────
    assert "MEASURED WHERE AN IN-HOUSE INSTRUMENT EXISTS" in _vision, (
        "§10 still claims sixteen criteria with instruments for four")
    #  ASSERTED INSIDE THE AMENDMENT BLOCK, not anywhere in the file. A blind that deleted "commercially
    #  viable" from the unmeasured list left this GREEN, because the phrase also appears in §10's original
    #  criteria line two paragraphs up - a presence check satisfied by a different sentence. The block is
    #  cut out first so the leg can only be satisfied by the amendment itself.
    _amend594 = _vision.split("AMENDED BY OWNER RULING 2026-10-05b (R3)", 1)[1].split("## 11.", 1)[0]
    assert "Named, with NO instrument anywhere" in _amend594, (
        "the amendment no longer separates what is measured from what is only named", _amend594[:200])
    #  AND NARROWED AGAIN TO THE ONE SENTENCE. The first narrowing still passed a blind that deleted
    #  "commercially viable" from the list, because the phrase appears TWICE inside the amendment - once
    #  in this list and again in the "commercial trio" sentence below it. A needle appearing twice cannot
    #  be checked by a presence test; the list itself is cut out, ending where it says so.
    _named594 = (_amend594.split("Named, with NO instrument anywhere", 1)[1]
                 .split("These are not reported as met.", 1)[0])
    for _unmeasured in ("best-in-class", "innovative", "effective", "efficient", "commercially viable",
                        "tested", "validated", "categorised"):
        assert _unmeasured in _named594, (
            "§10's amendment dropped a named criterion instead of recording it as unmeasured - a bar "
            "quietly reduced hides what was promised", _unmeasured)
    assert "category error rather than a gap" in _vision, (
        "§10 does not say WHY an instrument for best-in-class is not merely missing")

    # ── R6: Mode 2 is the Owner's own twin, and a further one needs consent ────────────────────
    assert "Mode 2\n  means the OWNER'S OWN twin node" in _vision or "OWNER'S OWN twin node" in _vision, (
        "§17.4 does not record Mode 2's ruled scope")
    assert "that expert's consent" in _vision, (
        "§17.4 does not record that a twin of another named human needs that person's consent")
    assert "the scope is an OWNER RULING (P3.0)" not in _vision, (
        "§17.4 still presents Mode 2's scope as an open ruling after it was ruled")

    # ── R10: the Fitrah Spectrum is a BOUNDARY, not a backlog row ─────────────────────────────
    assert "A.12.4 Fitrah Spectrum — RULED 2026-10-05b: DEFERRED" in _vision, (
        "A.12.4 does not record the deferral")
    assert "No round may schedule it as" in _vision, (
        "the deferral does not forbid a later round scheduling it as unbuilt work, which is the whole "
        "point of recording it as a boundary rather than a gap")
    assert "The ruling needed is whether it proceeds" not in _vision, (
        "A.12.4 still reads as an open question beside its own ruling")

    # ── and the open-decisions list holds only what is genuinely open ─────────────────────────
    #  W598 — this pinned the literal "FU-448" as open, and the Owner then RULED it. So the guard went red
    #  because a decision got made: the FU-365 class, inside the very list W594 built to stop the canon
    #  presenting ruled decisions as open. Pinning an id punishes the progress it was written to protect.
    #  THE PROPERTY IS A MATCH AGAINST THE REGISTER, both ways: every owner-gated row that is still OPEN
    #  appears, and no row that is CLOSED is still being asked about. Computed, so ruling one removes it and
    #  registering one adds it, with nothing here to edit either time.
    #  W622 — read to the list's OWN end marker, not a fixed 2600 characters: once rulings shortened the list,
    #  the window reached into the "RULED" record below it and read ruled rows as still asked.
    _still = _plan594.split("STILL WITH THE OWNER", 1)[1].split("THAT IS THE WHOLE LIST.", 1)[0]
    #  W622 — "162" left the list because the Owner RULED it on 2026-10-07 (FU-459: an accurate scan, no deletion);
    #  pinning it would punish the ruling, the FU-365 class this block's own comment names.
    assert "THE STRIPE KEY ROLL" in _still, (
        "the open-decisions list has lost a standing Owner decision that no register row carries",
        _still[:300])
    import json as _js594
    _reg594 = _js594.loads((_root594 / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))
    _gated = [r for r in _reg594["items"]
              if r.get("owner_gated") or str(r.get("slot") or "") == "OWNER"]
    _open_gated = [r["id"] for r in _gated if r.get("status") == "open"]
    _closed_gated = [r["id"] for r in _gated if r.get("status") != "open"]
    _missing594 = [i for i in _open_gated if i not in _still]
    assert _missing594 == [], (
        "an owner-gated row is OPEN in the register and absent from the plan's open-decisions list, so the "
        "Owner is never asked for a decision the register is waiting on", _missing594)
    _stale594 = [i for i in _closed_gated if i in _still]
    assert _stale594 == [], (
        "the list still asks the Owner about a row that has been RULED and closed - which is how a ruling "
        "gets quietly undone, and is exactly what W594 found this list doing for thirty-odd rounds",
        _stale594)
    for _ruled in ("whether §17.1's Products axis is built or amended",
                   "whether §17.5's KPI gate is built or amended"):
        assert _ruled not in _still, (
            "the list still asks the Owner for a ruling they have given - which is how a ruling gets "
            "quietly undone", _ruled)


def test_w595_p38_a_lifecycle_field_holds_the_state_it_is_in(client):
    """P3.8 clause (2) — the §4.5 shape, driven across the whole progression.

    The clause requires an INTERMEDIATE state to be observable, not merely a final one: a field that only
    ever holds its last value passes a single-point check taken at the end. Measured before this round,
    all 219 entities held `stage: "commercialise"` — 218 from a genesis literal, one from the spawn path —
    and no code advanced it, so the field could only ever report the end.

    Driven here on `_derived_stage`, which computes the furthest §4 section composed WITH NO GAP, and on
    the establishment path, which must not write a final literal at birth.
    """
    from agentic_core.api.vsb import _derived_stage as _ds595

    _ORDER = ("concept", "design", "operations", "commercialisation")

    def _state(composed):
        """A body map in which `composed` are done and the rest were never provided."""
        return {"body_pending": {k: False for k in _ORDER},
                "body_absent": {k: k not in composed for k in _ORDER}}

    # ── every intermediate state is observable, in order ────────────────────────────────────────
    _seen595 = []
    for _n in range(len(_ORDER) + 1):
        _stage, _basis = _ds595(_state(_ORDER[:_n]))
        _seen595.append(_stage)
    assert _seen595[0] is None, (
        "an entity that has composed nothing reports a stage, so the field is not derived from state",
        _seen595)
    assert _seen595[1:] == list(_ORDER), (
        "the lifecycle field does not move through its INTERMEDIATE values as sections are composed - a "
        "field that only ever holds its final value is the §4.5 shape this clause exists to replace",
        _seen595)

    # ── and a GAP does not let a later section stand in for an earlier one ─────────────────────
    _gapped = {"body_pending": {k: False for k in _ORDER},
               "body_absent": {"concept": False, "design": True,
                               "operations": False, "commercialisation": False}}
    _gs, _gb = _ds595(_gapped)
    assert _gs == "concept", (
        "a commercialisation composed while the design is missing carries the entity past the gap, which "
        "reports a position it has not reached", _gs, _gb)
    assert "was never provided" in _gb and "out of order" in _gb, (
        "the basis does not say WHY the stage stopped, nor that later sections were composed out of "
        "order - a silent stop reads as the end of the lifecycle", _gb)

    # ── NO STORED FIELD HOLDS THE LIFECYCLE STATE — asserted on the STORE ─────────────────────
    #  This leg first read `stage` off the entity's GET response, which has no such key: `.get("stage")`
    #  returned None, `None != "commercialise"` was trivially true, and blind DB — writing the final
    #  literal at birth again — went GREEN. Measured instead: the stored record carries NO `stage` at
    #  all, which is how the §4.5 shape is actually fixed. There is no field that could hold only its
    #  final value; the state is derived. `scope` IS "commercialise" and that is legitimate - it is the
    #  ambition the founder asked for, which `_derived_stage`'s own docstring says is correctly the end
    #  point on an entity that has reached nothing.
    import json as _j595

    from agentic_core.config import data_path as _dp595

    _e595 = client.post("/api/v1/genesis/establish",
                        json={"problem": "w595 lifecycle probe", "domain": "science",
                              "concept": "a measured concept for the lifecycle probe",
                              "name": "W595 Lifecycle Probe"}).json()
    _vid595 = _e595["vsb_id"]
    _stored595 = _j595.loads((_dp595("vsb_entities") / f"{_vid595}.json").read_text(encoding="utf-8"))
    #  THE STORED STAGE IS THE DERIVED ONE, not a constant. Measured: the record DOES carry `stage`, and
    #  for an entity that has composed only a concept it reads "concept" - which is the §4.5 fix working,
    #  not the defect. So the property is not "no stored stage" (an earlier draft of this leg asserted
    #  that and went red on correct code); it is that the stored value EQUALS what the derivation computes
    #  from the same record, and is therefore not the final value on a partial entity.
    _stored_stage = _stored595.get("stage")
    assert _stored_stage not in ("commercialise", "commercialisation"), (
        "a freshly-established entity STORES the FINAL lifecycle value, which is the defect measured "
        "across all 219 entities - 218 from a genesis literal, one from the spawn path, with no code "
        "advancing it", _stored_stage)
    assert _stored595.get("scope"), (
        "the ambition the founder asked for is not recorded at all, so nothing distinguishes what an "
        "entity is AIMING at from what it has REACHED - collapsing those two is the §4.5 shape")
    #  and the derived stage agrees with what this entity has actually composed
    _dstage, _dbasis = _ds595(_stored595)
    assert _dstage != "commercialisation", (
        "a freshly-established entity derives the FINAL stage, so the derivation is not reading its "
        "composed sections", _dstage, _dbasis[:160])
    assert _stored_stage == _dstage, (
        "the stage STORED on the record disagrees with what the derivation computes from that same "
        "record, so one of the two is a value nothing recomputed - which is how a lifecycle field comes "
        "to hold a constant", _stored_stage, _dstage)
    assert _dbasis, "the derived stage carries no basis, so a reader cannot check it"


def test_w595_p36_language_depth_reaches_the_surfaces_and_labels_what_it_cannot_deliver():
    """P3.6 — §9 depth: useT across the named surfaces, the AI language honoured or LABELLED, and the
    interface list computed from the dictionaries that exist.

    Measured before this round: useT reached the Sidebar, DashboardNew, DomainsHub and ThemeContext and
    NOT DomainTool, Settings or the avatar; nothing anywhere read a language for AI output, so a user
    whose preference was Urdu got English with nothing saying so ("the defect is silent English"); and
    `LANGUAGES` was a hard-coded twelve while five dictionaries existed, so seven options changed nothing
    but the stored preference.
    """
    import pathlib as _pl36
    import re as _re36

    _root36 = _pl36.Path(__file__).resolve().parents[1]
    _src = _root36 / "apps/workstation-superapp/src"
    _i18n = (_src / "lib/i18n.tsx").read_text(encoding="utf-8")

    # ── (1) THE NAMED SURFACES READ A SPECIFIC KEY, AND THE KEY EXISTS IN EVERY DICTIONARY ──────
    #  No JSX renderer exists in this suite, so the strongest available assertion ties a key to a
    #  surface AND to all five dictionaries: a key only in English would make the usage a no-op in the
    #  four translated languages, which is "reading the translation" in name only.
    _dict_count = len(_re36.findall(r"^const (?:en|ar|fr|es|ur): Dict = \{", _i18n, _re36.M))
    assert _dict_count >= 5, ("the dictionaries this file is supposed to hold are not there, so every "
                              "translation leg below would be vacuous", _dict_count)
    _surfaces36 = {
        "pages/Settings.tsx": "settings.title",
        "components/DomainTool.tsx": "tool.result",
        "components/avatar/ConversationPanel.tsx": "avatar.attachImage",
        "pages/domains/DomainsHub.tsx": None,       # a hub — already translated; key not pinned
    }
    for _rel, _key in _surfaces36.items():
        _text = (_src / _rel).read_text(encoding="utf-8")
        assert "useT" in _text, (
            f"{_rel} does not read the translation at all, so §9 depth stops before it", _rel)
        assert _re36.search(r"const \{\s*t\s*[,}]", _text), (
            f"{_rel} imports useT without taking `t` from it, so nothing is translated there", _rel)
        if _key:
            assert f"'{_key}'" in _text, (
                f"{_rel} no longer reads the key it was wired to, so the surface's translation is gone",
                _rel, _key)
            #  the key must be translated in EVERY dictionary, or the usage is a no-op in that language
            assert _i18n.count(f"'{_key}'") >= _dict_count, (
                f"the key {_key!r} is missing from at least one dictionary, so {_rel} falls back to "
                f"English in a language that HAS a dictionary - a translation that is not there",
                _i18n.count(f"'{_key}'"), _dict_count)

    # ── (2) AN AI OUTPUT IS HONOURED, OR LABELLED AS NOT DELIVERED ─────────────────────────────
    from agentic_core.ai.gateway import language_verdict as _lv36
    _none = _lv36(None, "native", True)
    assert _none["language_requested"] is None and _none["language_delivered"] is None, (
        "a claim about the output's language is made when no language was requested", _none)
    _en = _lv36("en-US", "native", True)
    assert _en["language_delivered"] == "en", ("English on the floor is not reported as delivered", _en)
    _ur = _lv36("ur-PK", "native", True)
    assert _ur["language_delivered"] == "en" and "NOT DELIVERED IN UR" in _ur["language_basis"], (
        "a language the owned floor cannot serve is answered in English with NO label, which is the "
        "silent-English defect this clause exists to end", _ur)
    #  and the third state: a MODEL served, so the language is NOT VERIFIED rather than assumed honoured
    _model = _lv36("ur-PK", "ollama:llama3.2", False)
    assert _model["language_delivered"] is None and "NOT VERIFIED" in _model["language_basis"], (
        "a model's output is reported as DELIVERED in the requested language, which is a claim about an "
        "outcome derived from the ask - nobody inspected the language of that text", _model)

    # ── (2b) AND A READER SEES IT. A field in the API is not a label ───────────────────────────
    #  The register refused a row that would have parked this: "rides on P3.6, already DONE - that round
    #  closed without doing it". It was right, and FU-420's lesson is the same: provenance must travel
    #  WITH the output to the reader. Driven end to end through a REAL domain tool, with the language
    #  arriving as Accept-Language - a body field would have to be declared on each of the six tools'
    #  Pydantic models or it is silently dropped.
    from fastapi.testclient import TestClient as _TC36
    from agentic_core.app_mvp import app as _app36
    _r36 = _TC36(_app36).post("/api/v1/care/care-plan",
                              json={"client_name": "W595", "needs": "mobility support"},
                              headers={"Accept-Language": "ur-PK"})
    assert _r36.status_code == 200, (_r36.status_code, _r36.text[:160])
    _prov36 = (_r36.json() or {}).get("ai_provenance") or {}
    assert _prov36.get("language_requested") == "ur", (
        "the request's language does not reach the seam every domain tool calls, so no output can be "
        "labelled with it", _prov36)
    assert _prov36.get("language_delivered") == "en" and "NOT DELIVERED IN UR" in (
        _prov36.get("language_basis") or ""), (
        "a domain tool answers in English with no label on the response a reader receives - silent "
        "English, which is the defect this clause names", _prov36)
    #  and the shared component every domain tool renders through SHOWS it
    _dt36 = (_src / "components/DomainTool.tsx").read_text(encoding="utf-8")
    assert "Accept-Language" in _dt36, (
        "the page does not send the reader's language, so nothing downstream can label the answer")
    assert 'data-testid="tool-language-note"' in _dt36, (
        "the language basis is not RENDERED anywhere, so it is an API field and not a label - the "
        "badge-in-the-DOM class (FU-420)")
    assert "language_delivered !== (effectiveProv as any)?.language_requested" in _dt36, (
        "the note is rendered unconditionally or not at all; it must appear exactly when the delivered "
        "language differs from the requested one, or it becomes noise on every English answer")

    # ── (3) THE INTERFACE LIST IS COMPUTED, NOT HARD-CODED ─────────────────────────────────────
    _prefs = (_src / "lib/userPrefs.ts").read_text(encoding="utf-8")
    _langs = _re36.findall(r"\{ code: '([a-z]{2}-[A-Z]{2})'", _prefs)
    assert len(_langs) >= 12, ("the DICTATION list was trimmed, which the Owner's ruling of 2026-10-05 "
                               "kept wider on purpose - trimming it removes voice dictation in those "
                               "languages", len(_langs))
    assert "interfaceLanguages" in _i18n, "the interface list is not derived anywhere"
    _settings = (_src / "pages/Settings.tsx").read_text(encoding="utf-8")
    #  SCOPED TO THE INTERFACE SELECT. A blind that pointed the picker back at the hard-coded list left
    #  this GREEN, because `interfaceLanguages(LANGUAGES)` also appears in the dictation block's
    #  explanatory paragraph - a needle appearing twice cannot be checked by a presence test. The options
    #  of the interface select are cut out and read on their own.
    _iface_sel = _settings.split('id="pref-lang"', 1)[1].split("</select>", 1)[0]
    assert "interfaceLanguages(" in _iface_sel, (
        "the Settings picker still offers the hard-coded list, so it offers languages this interface "
        "cannot render - 'a hard-coded list of twelve fails this whatever it contains'", _iface_sel[-220:])
    #  EXACT, INCLUDING THE CLOSING QUOTE. A blind that renamed the id to `pref-dictation-lang-removed`
    #  left this GREEN too: a substring check is satisfied by any longer string containing it.
    assert 'id="pref-dictation-lang"' in _settings, (
        "there is no separate DICTATION control, so trimming the interface list silently narrowed "
        "dictation - the consequence the Owner's ruling of 2026-10-05 was about")
    _dict_sel = _settings.split('id="pref-dictation-lang"', 1)[1].split("</select>", 1)[0]
    assert "LANGUAGES.map" in _dict_sel and "interfaceLanguages" not in _dict_sel, (
        "the DICTATION select was narrowed to the interface list, which removes voice dictation in the "
        "languages the Owner's ruling kept it for", _dict_sel[-200:])
    #  every dictation reader honours the separate preference - three readers, and a new field honoured
    #  in one of them leaves two surfaces silently on the old one
    for _rel in ("components/DomainTool.tsx", "hooks/useAvatarSession.ts",
                 "pages/synthesis/GenesisJourney.tsx"):
        _t = (_src / _rel).read_text(encoding="utf-8")
        assert "dictationLanguage" in _t, (
            f"{_rel} still takes the INTERFACE language for dictation, so the separate control does not "
            f"reach it", _rel)


def test_w596_p39_the_memorisation_surface_and_a_leaderboard_over_recorded_xp(client):
    """P3.9 — QEP composed: the real SM-2 state on screen, and a leaderboard over PERSISTED XP.

    Measured before this round: `/hifz/review` already returned `new_efactor` and the
    "a review count, not a hifz certification" basis, and the screen typed NEITHER — a learner saw an
    interval with nothing saying what produced it, and the one line that stops a review count reading as
    an attainment never reached them. And no leaderboard route existed at all; the only leaderboard this
    platform ever had was ten synthetic rows with scores from `random.randint`, deleted in W404.
    """
    import pathlib as _pl39

    # ── (1) THE SM-2 STATE A LEARNER SEES ───────────────────────────────────────────────────────
    _sched = client.post("/api/v1/qep/hifz/schedule",
                         json={"uid": "w596-learner", "surah_number": 1, "ayaat_range": [1, 3]})
    assert _sched.status_code == 200, (_sched.status_code, _sched.text[:160])
    _rev = client.post("/api/v1/qep/hifz/review",
                       json={"uid": "w596-learner", "ayah_ref": "1:2", "quality": 4})
    assert _rev.status_code == 200, (_rev.status_code, _rev.text[:160])
    _rj = _rev.json()
    for _f in ("new_interval_days", "new_efactor", "memorised_basis"):
        assert _f in _rj, (f"the review response no longer carries {_f}, so the screen cannot show it", _f)
    assert "not a hifz certification" in _rj["memorised_basis"], (
        "the memorised count lost the line that stops it reading as an attainment", _rj["memorised_basis"])
    #  and the SURFACE renders all three — the route having them is not a learner seeing them (FU-420)
    _studio = (_pl39.Path(__file__).resolve().parents[1]
               / "apps/workstation-superapp/src/components/QEPStudio.tsx").read_text(encoding="utf-8")
    assert "new_interval_days" in _studio, "the screen no longer shows the interval"
    assert 'data-testid="hifz-efactor"' in _studio, (
        "the e-factor is not rendered, so the schedule is asserted rather than checkable - the route has "
        "returned it all along and no screen showed it")
    assert 'data-testid="hifz-memorised-basis"' in _studio, (
        "the 'a review count, not a hifz certification' basis is not rendered, so a review count reads as "
        "an attainment on the one surface a learner reads")

    # ── (2) A LEADERBOARD OVER RECORDED XP, WITH ITS FORMULA AND ITS POPULATION ─────────────────
    #  SEEDED SO THAT XP ORDER AND ACHIEVEMENT ORDER DISAGREE. A blind that re-sorted the board by
    #  `achievements` instead of `xp` went GREEN on the first seeding, because every learner had exactly
    #  one achievement and both keys produced the same order - the leg could not tell the two apart.
    #  yusuf now holds MORE achievements on LESS xp, so ranking by the wrong key is visible.
    #  AND THE EXPECTED TOTALS ARE READ BACK FROM THE AWARD RESPONSE rather than assumed: awards
    #  ACCUMULATE in a shared store, so `xp == 40` is false the second time this runs in one data dir -
    #  which is what made four blinds report the wrong leg.
    _expect39 = {}
    for _uid, _awards in (("w596-amina", [("w596 review", 40)]),
                          ("w596-yusuf", [("w596 review", 10), ("w596 streak", 10)]),
                          ("w596-zayd", [("w596 review", 40)])):
        for _ach, _xp in _awards:
            _a = client.post("/api/v1/qep/gamification/award",
                             json={"uid": _uid, "achievement": _ach, "xp": _xp})
            assert _a.status_code == 200, (_a.status_code, _a.text[:140])
            _expect39[_uid] = _a.json().get("xp")
    assert _expect39["w596-amina"] > _expect39["w596-yusuf"], (
        "the seeding no longer puts more XP on amina than yusuf, so the ranking leg below proves nothing",
        _expect39)
    #  an EXPLICIT high limit, not the route's default of 20. The award store is shared across the suite
    #  and grows as other tests award XP, so the default would truncate once more than twenty learners
    #  exist - and then this test's own three could fall off the board depending on what ran before it.
    #  The cap is driven deliberately further down instead.
    _lb = client.get("/api/v1/qep/leaderboard?limit=10000")
    assert _lb.status_code == 200, (_lb.status_code, _lb.text[:160])
    _b = _lb.json()
    _mine = {r["uid"]: r for r in _b["leaderboard"] if str(r["uid"]).startswith("w596-")}
    assert {"w596-amina", "w596-yusuf", "w596-zayd"} <= set(_mine), (
        "the seeded learners are not ranked, so the board is not reading the store", sorted(_mine))
    #  AND THE LEARNER FROM CLAUSE (1) IS ON THE BOARD TOO, which is a stronger fact than the seeds: that
    #  learner was never awarded XP directly - the hifz REVIEW awarded it - so their presence proves the
    #  board ranks XP earned by real study and not only XP handed to it by this test.
    assert "w596-learner" in _mine and _mine["w596-learner"]["xp"] > 0, (
        "XP earned by an actual review does not reach the leaderboard, so the board is not over the same "
        "store the learning path writes", _mine.get("w596-learner"))
    #  the board's figure is the store's own total, read back from the award response - not a constant
    for _u39, _x39 in _expect39.items():
        assert _mine[_u39]["xp"] == _x39, (
            "the board's XP disagrees with the total the store returned when the award was recorded",
            _u39, _mine[_u39]["xp"], _x39)
    assert _mine["w596-amina"]["rank"] < _mine["w596-yusuf"]["rank"], (
        "a learner with more recorded XP does not rank above one with less", _mine)
    #  and the order is by XP, NOT by achievement count: yusuf holds more achievements on less xp, so a
    #  board sorted by the wrong key puts yusuf first and this fires
    assert _mine["w596-yusuf"]["achievements"] > _mine["w596-amina"]["achievements"], (
        "the seeding no longer distinguishes the two sort keys, so this leg is vacuous", _mine)
    assert _b["formula"] and "sum" in _b["formula"], (
        "the ranking's formula is not returned, so a reader cannot check the order against the history",
        _b.get("formula"))
    assert "RECORDED AWARDS" in _b["formula_basis"] and "recitation" in _b["formula_basis"], (
        "the formula basis does not say what is NOT being ranked - nothing here scores a recitation, and "
        "a leaderboard that leaves that unsaid implies a performance ranking", _b.get("formula_basis"))
    assert str(_b["learners_ranked"]) in _b["population_basis"], (
        "the population is not stated, so a board of three implies a field of competitors - which is the "
        "defect the ten synthetic rows W404 deleted had", _b.get("population_basis"))
    #  a tie is NAMED, and counted in LEARNERS - two on 40 is two learners, not one duplicate total
    assert _b["ties"] >= 2 and "ordered by uid" in _b["tie_basis"], (
        "two learners on equal XP are presented as a ranking between them, or the tie count counts "
        "duplicate totals rather than the learners in them", _b["ties"], _b.get("tie_basis"))
    assert "not a hifz certification" in _b["not_a_certification"], (
        "the board does not say a position is not an attainment")

    # ── THE CAP IS REPORTED, NOT DENIED — driven with a limit BELOW the population ──────────────
    #  This round's own pre-flight caught it: the population sentence read "not a top-N of a larger
    #  population" unconditionally while the handler sliced to `limit`, so the basis asserted the
    #  opposite of what the code did the moment anyone passed a small limit. The archived
    #  gamification.py capped at ten and said nothing; a sentence that DENIES the cap is worse,
    #  because it answers the reader's question wrongly rather than leaving it open.
    _cap = client.get("/api/v1/qep/leaderboard?limit=1").json()
    assert len(_cap["leaderboard"]) == 1 and _cap["learners_ranked"] >= 3, (
        "the limit did not cap, so this leg cannot see whether a cap is reported", _cap.get("shown"),
        _cap.get("learners_ranked"))
    assert _cap["truncated"] is True, ("a capped board does not report that it is capped", _cap)
    assert "TOP-1 OF A LARGER POPULATION" in _cap["population_basis"], (
        "a capped board's population sentence does not say it is the top of a larger ranking - a reader "
        "seeing one name cannot tell it from the whole field", _cap["population_basis"])
    assert "not a top-N" not in _cap["population_basis"], (
        "the capped board DENIES being a top-N while having sliced the rows, which is the defect the "
        "pre-flight found in this round's own code", _cap["population_basis"])
    #  and the uncapped board says so positively rather than staying silent
    assert _b["truncated"] is False and "none omitted" in _b["population_basis"], (
        "an uncapped board does not state that nothing was omitted, so a reader cannot distinguish it "
        "from a capped one", _b.get("truncated"), _b.get("population_basis"))

    # ── (2b) AND A READER SEES THE BOARD, ITS FORMULA AND ITS POPULATION ───────────────────────
    #  "with its formula shown" is shown to a PERSON. The pre-flight caught that no page fetched this
    #  route at all, which is the same thing the register refused to let P3.6 close with: a formula in a
    #  payload is not a formula shown.
    _studio39 = (_pl39.Path(__file__).resolve().parents[1]
                 / "apps/workstation-superapp/src/components/QEPStudio.tsx").read_text(encoding="utf-8")
    assert "/api/v1/qep/leaderboard" in _studio39, (
        "no page fetches the leaderboard, so its formula and its population are shown to nobody")
    assert 'data-testid="qep-leaderboard"' in _studio39, "the board is not rendered"
    assert 'data-testid="qep-leaderboard-formula"' in _studio39, (
        "the formula is not rendered, so a reader cannot check how the board ranked")
    assert "board.population_basis" in _studio39, (
        "the population is not rendered, so a board of two implies a field of competitors")
    #  the two COUNTS reach the reader as well, not only the sentence: "showing N of M", and the cap
    #  named when there is one. The pre-flight's standing lead is a key produced and shown to nobody.
    assert 'data-testid="qep-leaderboard-population"' in _studio39, (
        "the card does not state how many of how many, so a reader seeing ten names cannot tell whether "
        "ten is the field or the top of it")
    assert "board.truncated" in _studio39 and "board.learners_ranked" in _studio39, (
        "the cap and the ranked population do not reach the page, so the card cannot say which it shows",
        "board.truncated" in _studio39, "board.learners_ranked" in _studio39)
    #  and the per-learner history check, which exists precisely because it can DISAGREE with the total.
    #  NOT a presence check on the field name: this round drove that blind and it came back VACUOUS,
    #  because a JSX conditional names its field in BOTH the gate and the body - `{gate && <p>{field}</p>}`
    #  - so disabling the gate leaves the name in the file. The GATE's own comparison is asserted, which
    #  is the thing a disabled gate loses, and the testid catches deletion of the whole block.
    assert "r.xp_in_recorded_history !== r.xp" in _studio39, (
        "the page no longer compares the recorded history against the displayed total, so the two can "
        "disagree - which they will once history is capped at its last awards - with nothing shown")
    assert "qep-leaderboard-history-" in _studio39, (
        "the line that reports a disagreement between a learner's displayed XP and the awards beneath it "
        "is gone, so the XP shown beside their name cannot be checked")
    assert 'data-testid="qep-leaderboard-formula-basis"' in _studio39, (
        "the line saying what is NOT ranked - nothing here scores a recitation - is not rendered, so the "
        "board reads as a performance ranking on the one surface a learner sees")
    assert "board.unreadable_basis" in _studio39, (
        "a learner file that could not be read is silently omitted from the board rather than disclosed")
    assert "board.not_a_certification" in _studio39, (
        "the screen does not say a position here is not an attainment")
    assert "board.ties > 0" in _studio39, (
        "the tie note is rendered unconditionally or not at all; it must appear exactly when there IS a "
        "tie, or it is noise on every board")

    # ── (3) THE ITEM'S OWN GUARD: NO FIGURE WITHOUT A BASIS, ON THE ROUTES IT TOUCHES ───────────
    #  Driven on the RESPONSE, because a handler's source cannot show what a response carries. A figure is
    #  a number that is not a count of something trivially self-describing, so the rule is applied as:
    #  a response carrying any number must carry at least one basis-bearing string field.
    _BASIS_WORDS = ("basis", "detail", "note", "why", "not_a_certification", "formula")
    for _path, _get in (("/api/v1/qep/leaderboard", True),
                        ("/api/v1/qep/gamification/w596-amina", True),
                        ("/api/v1/qep/status", True)):
        _r = client.get(_path) if _get else client.post(_path)
        assert _r.status_code == 200, (_path, _r.status_code, _r.text[:140])
        _body = _r.json()
        if not isinstance(_body, dict):
            continue
        _nums = [k for k, v in _body.items()
                 if isinstance(v, (int, float)) and not isinstance(v, bool)]
        if not _nums:
            continue
        _bases = [k for k in _body if any(w in k.lower() for w in _BASIS_WORDS)]
        assert _bases, (
            f"{_path} returns figures {_nums} and NO basis field - the item's guard is that no route under "
            f"/qep may return a figure without a basis string", _path, _nums, sorted(_body))

    # ── NO QEP SURFACE IMPORTS random — the fabrication class cannot return by the same route ──────
    #  W404 deleted qep_flagship's gamified_competition, which built a leaderboard from
    #  random.randint: ten synthetic rows, invented scores, a rank drawn from a die. The archive audit
    #  for this item found `import random` STILL at the top of that file, dead but available, in the one
    #  file where reaching for a random number would recreate exactly what was deleted.
    #  ASSERTED ON THE AST, NOT ON THE TEXT. That file's comments quote `random.randint(0, 5)` while
    #  recording the removal - a substring check would match the comment that documents the fix and go
    #  red on correct code, which is the trap this suite has hit before. An import is a BINDING, so the
    #  binding is what is read.
    import ast as _ast39
    _qep_roots = (_pl39.Path(__file__).resolve().parents[1] / "agentic_core/reactor/religion",
                  _pl39.Path(__file__).resolve().parents[1] / "agentic_core/religious_domain")
    _rand_importers = []
    _scanned39 = 0
    for _rootq in _qep_roots:
        for _py in sorted(_rootq.rglob("*.py")):
            _scanned39 += 1
            _tree39 = _ast39.parse(_py.read_text(encoding="utf-8"))
            for _n39 in _ast39.walk(_tree39):
                if isinstance(_n39, _ast39.Import) and any(a.name.split(".")[0] == "random"
                                                           for a in _n39.names):
                    _rand_importers.append(f"{_py.name}:{_n39.lineno} import random")
                elif isinstance(_n39, _ast39.ImportFrom) and (_n39.module or "").split(".")[0] == "random":
                    _rand_importers.append(f"{_py.name}:{_n39.lineno} from random import ...")
    assert _scanned39 >= 5, (
        "this leg scanned almost nothing, so it would pass on an empty tree", _scanned39)
    assert _rand_importers == [], (
        "a QEP surface module binds `random`, which is the one import that made the deleted leaderboard "
        "possible - a figure about a learner's worship drawn from a random number generator. Nothing on "
        "these surfaces has any legitimate need for one", _rand_importers)


def test_w596_p321_the_verifier_refuses_on_a_checkable_check_and_never_on_a_score(client):
    """P3.21 — each of the three verdicts reachable and asserted; a withheld output names the check that
    failed; no float is read as a verdict anywhere in the chain.

    The float half is the item's own emphasis: the roadmap proposed withholding whenever a
    verifier-confidence number fell below a threshold, and this platform already carried three gates of
    that shape - a quality pipeline starting at
    0.90 and adding 0.05 per iteration without reading the content, a consultation contract REQUIRING a
    float so every implementer returned 0.96, and a cognitive base class hard-coding 0.95 on success. A
    threshold over an invented number is a gate that cannot refuse.
    """
    import pathlib as _pl321

    from agentic_core.horizon import verifier as _v

    _root321 = _pl321.Path(__file__).resolve().parents[1]
    _doc = "agentic_core/horizon/verifier.py"
    _first = (_root321 / _doc).read_text(encoding="utf-8").splitlines()[0]
    _quote = _first[:24]

    # ── (1) ALL THREE VERDICTS ARE REACHABLE, ON EVERY CHECK ────────────────────────────────────
    _reached = {_v.MET: [], _v.UNMET: [], _v.NOT_ASSESSABLE: []}
    _cases = [
        (_v.check_citation_resolves, {"document": _doc}, _v.MET),
        (_v.check_citation_resolves, {"document": "docs/does-not-exist-w596.md"}, _v.UNMET),
        (_v.check_citation_resolves, {}, _v.NOT_ASSESSABLE),
        (_v.check_quote_at_location, {"document": _doc, "line": 1, "quote": _quote}, _v.MET),
        (_v.check_quote_at_location, {"document": _doc, "line": 2, "quote": _quote}, _v.UNMET),
        (_v.check_quote_at_location, {"document": _doc, "quote": _quote}, _v.NOT_ASSESSABLE),
        (_v.check_figure_in_source, {"document": _doc, "figure": "0.95"}, _v.MET),
        (_v.check_figure_in_source, {"document": _doc, "figure": "987654321"}, _v.UNMET),
        (_v.check_figure_in_source, {"document": _doc}, _v.NOT_ASSESSABLE),
    ]
    for _fn, _cite, _want in _cases:
        _r = _fn(_cite)
        assert _r["verdict"] == _want, (
            f"{_fn.__name__} does not reach {_want} on {_cite!r} - a verdict that cannot be reached is a "
            f"state this verifier only claims to have", _r)
        assert _r["basis"], (f"{_fn.__name__} returned a verdict with no basis, so a reader cannot check "
                             f"it", _r)
        _reached[_want].append(_r["check"])
    for _state, _hits in _reached.items():
        assert len(_hits) == 3, (f"{_state} is not reachable on all three checks", _state, _hits)

    # ── (2) A PATH OUTSIDE THE REPOSITORY IS NOT ASSESSABLE, NOT UNMET ─────────────────────────
    #  Saying UNMET would imply the verifier looked and found nothing; it did not look at all.
    _out = _v.check_citation_resolves({"document": "../../../etc/passwd"})
    assert _out["verdict"] == _v.NOT_ASSESSABLE and "did NOT look" in _out["basis"], (
        "a citation escaping the repository is answered as though the verifier had looked", _out)

    # ── (3) AN UNMET WITHHOLDS AND NAMES THE CHECK; NOT ASSESSABLE DOES NEITHER ────────────────
    _bad = _v.verify("an answer", [{"document": _doc, "line": 2, "quote": _quote}])
    assert _bad["withheld"] is True and _bad["output"] is None, (
        "an output whose citation failed a check is still served", _bad)
    assert _bad["withheld_because"] and _bad["withheld_because"][0]["check"] == \
        _v.CHECK_QUOTE, (
        "the withheld output does not name the check that failed, so the author cannot correct it", _bad)
    _ok = _v.verify("an answer", [{"document": _doc, "line": 1, "quote": _quote}])
    assert _ok["withheld"] is False and _ok["output"] == "an answer", _ok
    #  NOT ASSESSABLE neither withholds nor passes silently
    #  ALL THREE CHECKS UNASSESSABLE needs a citation with no document at all. Citing a real document
    #  with no quote makes check 1 MET - the citation DID resolve - so the overall verdict is correctly
    #  MET there, and an earlier draft of this leg asserted otherwise against correct code.
    _una = _v.verify("an answer", [{}])
    assert _una["withheld"] is False, ("a check that could NOT be run withheld the output, which makes an "
                                       "unmeasurable citation indistinguishable from a failed one", _una)
    assert _una["verdict"] == _v.NOT_ASSESSABLE and "could NOT be assessed" in _una["withheld_basis"], (
        "an output with no assessable check reports as though something passed", _una)

    #  AND THE MIXED CASE: one check ran and passed while two could not be run. The headline says nothing
    #  failed, and the basis must SAY how many were unassessable - otherwise a partly-checked output reads
    #  as a fully-checked one.
    _mixed = _v.verify("an answer", [{"document": _doc}])
    assert _mixed["verdict"] == _v.MET and _mixed["counts"][_v.NOT_ASSESSABLE] == 2, (
        "a citation that resolves but quotes nothing is not reported as one passed check and two that "
        "could not be run", _mixed["counts"])
    assert "could NOT be assessed" in _mixed["withheld_basis"], (
        "a partly-checked output reads as fully checked, because the basis does not say how many checks "
        "could not be run", _mixed["withheld_basis"])

    # ── (4) NO FLOAT IS READ AS A VERDICT ANYWHERE IN THE CHAIN ────────────────────────────────
    #  Asserted three ways, not by grepping for the roadmap's literal 0.8 - which would pass the moment
    #  somebody wrote 0.75.
    for _r in _bad["checks"] + _ok["checks"] + _una["checks"]:
        assert _r["verdict"] in (_v.MET, _v.UNMET, _v.NOT_ASSESSABLE), (
            "a verdict is not one of the three states, so something numeric has become one", _r)
    def _floats(obj):
        if isinstance(obj, float):
            return [obj]
        if isinstance(obj, dict):
            return [f for v in obj.values() for f in _floats(v)]
        if isinstance(obj, (list, tuple)):
            return [f for v in obj for f in _floats(v)]
        return []
    for _resp in (_bad, _ok, _una, _mixed):
        assert not _floats(_resp), (
            "the verifier's response carries a float, and a number in a refusal path becomes a threshold - "
            "which is the gate that cannot refuse this item exists to prevent", _floats(_resp))
    _src321 = (_root321 / _doc).read_text(encoding="utf-8")
    import re as _re321
    _thresholds = _re321.findall(r"[<>]=?\s*0\.\d+|0\.\d+\s*[<>]=?", _src321)
    assert not _thresholds, (
        "the verifier compares a number against a threshold, so a score decides the verdict", _thresholds)

    # ── (5) AND IT IS REACHABLE: the route withholds too ───────────────────────────────────────
    _rr = client.post("/api/v1/horizon/verify",
                      json={"output": "an answer",
                            "citations": [{"document": _doc, "line": 2, "quote": _quote}]})
    assert _rr.status_code == 200, (_rr.status_code, _rr.text[:160])
    _rj = _rr.json()
    assert _rj["withheld"] is True and _rj["output"] is None, (
        "the route serves an output whose citation failed a check", _rj)
    assert not _floats(_rj), ("the route's response carries a float", _floats(_rj))


def test_w597_p31_develop_produces_a_checkable_artefact_and_can_fail_on_it(client):
    """P3.1 (§4.6 Develop) — a distinct stage, a stored artefact, and a pass/fail from the artefact itself.

    Measured before this round: there was no `develop` stage, no artefact store, and no `factory`/`forge`
    package — so of the three artefacts the item permits, the costed bill of materials is the only one with
    a property that can be checked. Its check is arithmetic: the line items either sum to the stated total
    or they do not.

    WHY THAT MATTERS. `_verify_stage`'s own docstring records that its proxies CANNOT FAIL on floor output —
    the floor emits the headings it was asked for, so coverage is 1.0 and structure ≥1.0 and the composite
    lands exactly on the threshold. Every other journey stage is verified that way. This one reads the
    ARTEFACT, so it is the first verification in the journey that can fail on substance.
    """
    from agentic_core.api import develop_artefact as _da

    # ── (3) THE FAILING CASE FIRST, because a check that cannot fail is the defect this guards ──
    _bad_bom = ("## Bill of Materials\n"
                "- compressor unit | 2 x 450.00 | 900.00\n"
                "- insulated panel | 10 x 35.50 | 355.00\n"
                "## Total\nTotal: 2000.00\n")
    _art_bad, _ver_bad = _da.record("jny-w597-fail", _bad_bom, floor_served=False)
    assert _ver_bad["verified"] is False, (
        "a bill of materials whose lines do not sum to its stated total does not record a FAIL - None "
        "would be an absence, and the clause requires a real pass/fail", _ver_bad)
    assert "does not add up" in _ver_bad["basis"], (
        "the failure does not say WHY, so an author cannot correct the bill", _ver_bad["basis"])
    assert str(_art_bad["computed_total"]) in _ver_bad["basis"] and \
        str(_art_bad["stated_total"]) in _ver_bad["basis"], (
        "the failure names neither figure, so the arithmetic cannot be checked by a reader", _ver_bad)

    #  and the PASSING case, so the check is not simply always-fail
    _good_bom = _bad_bom.replace("Total: 2000.00", "Total: 1255.00")
    _art_ok, _ver_ok = _da.record("jny-w597-pass", _good_bom, floor_served=False)
    assert _ver_ok["verified"] is True, ("a bill whose lines DO sum is not recorded as a pass", _ver_ok)

    #  and NOT ASSESSABLE when there is no bill at all - three states, never two
    _, _ver_none = _da.record("jny-w597-none", "a prose answer with no bill of materials", floor_served=False)
    assert _ver_none["verified"] is None, (
        "an output with no bill of materials is recorded as a pass or a fail, when nothing was checkable",
        _ver_none)

    # ── (4) THE FLOOR REFUSES, AND RECORDS NO PASS ─────────────────────────────────────────────
    _, _ver_floor = _da.record("jny-w597-floor", _good_bom, floor_served=True)
    assert _ver_floor["verified"] is None, (
        "the deterministic floor records a PASS for a buildable artefact it cannot produce", _ver_floor)
    assert _da.NOT_BUILDABLE_ON_THE_FLOOR in _ver_floor["basis"], (
        "the floor does not say it cannot build this, so a reader cannot tell a refusal from a failure",
        _ver_floor["basis"])

    # ── (2) THE ARTEFACT EXISTS IN A STORE, loaded back by id ─────────────────────────────────
    _loaded = _da.load("jny-w597-pass")
    assert _loaded is not None, (
        "the artefact was not stored, so clause (2) is satisfied by the stage having RUN rather than by the "
        "artefact existing - which the item explicitly distinguishes")
    assert _loaded["kind"] == "costed_bill_of_materials" and _loaded["lines"], _loaded
    assert _da.load("jny-w597-floor") is None, (
        "the floor path stored an artefact it did not build")

    # ── (1) A DISTINCT STAGE, IN THE JOURNEY'S OWN ORDER, NOT ONLY IN PROSE ───────────────────
    _j = client.post("/api/v1/genesis/journey",
                     json={"problem": "cold storage for smallholder mango farmers",
                           "domain": "science", "realm": "enterprise"})
    assert _j.status_code == 200, (_j.status_code, _j.text[:160])
    _jb = _j.json()
    _sv = _jb.get("stage_verifications") or {}
    assert "develop" in _sv, (
        "§4.6 Develop has no entry in stage_verifications, so it is a stage in prose only and invisible to "
        "every figure that counts stages", sorted(_sv))
    _keys = list(_sv)
    assert _keys.index("design") < _keys.index("develop") < _keys.index("operations"), (
        "Develop is not between design and operational intelligence, which is where §4.6 sits", _keys)
    #  the journey returns its id, so the artefact it produced can be fetched
    assert _jb.get("journey_id"), (
        "the journey does not report its own id, so the artefact it stored cannot be looked up and 'exists "
        "in a store' is unverifiable from outside")
    #  and on this deployment the floor serves, so the stage must refuse rather than claim a pass
    _dev = _sv["develop"]
    assert _dev["verified"] is not True, (
        "the develop stage recorded a PASS on a deployment with no owned model, which is a check that "
        "cannot fail", _dev)
    assert _dev.get("basis"), "the develop verification carries no basis"

    # ── AND THE STAGE REACHES A READER, with its VERDICT ────────────────────────────────────────
    #  The pre-flight asked which surface shows these keys, and the honest answer was none: the journey
    #  gained a develop stage and an artefact that no page rendered. The clause only requires the entry in
    #  stage_verifications, but an artefact nobody can see is the FU-420 class — provenance and verdicts
    #  must travel WITH the output to the reader.
    #  The field is ADDED rather than reusing `phase_2_design_development`, which is NAMED for development
    #  while carrying only the design body: three readers already depend on it, and a field's meaning
    #  belongs to its readers.
    assert "stage_6_develop" in _jb, (
        "the journey returns no develop body, so the §4.6 stage ran and produced prose nobody receives",
        sorted(k for k in _jb if "stage" in k or "phase" in k))
    import pathlib as _pl31
    _gj = (_pl31.Path(__file__).resolve().parents[1]
           / "apps/workstation-superapp/src/pages/synthesis/GenesisJourney.tsx").read_text(
               encoding="utf-8")
    assert 'data-testid="genesis-develop"' in _gj, (
        "no page renders the Develop stage, so a founder is shown a five-stage account of a six-stage "
        "journey on the one surface they actually read")
    assert 'data-testid="genesis-develop-verdict"' in _gj, (
        "the artefact is rendered WITHOUT whether it checks out - and an artefact shown without its "
        "pass/fail is precisely what this stage exists to stop")
    assert "stage_verifications.develop.verified === false" in _gj, (
        "the page cannot distinguish a bill that FAILED from one nothing could assess; collapsing those "
        "two is the absence-for-a-failure substitution this item is written against")
    assert "'## Develop (buildable artefact)'" in _gj, (
        "the journey export omits the Develop stage, so a founder who downloads the record gets five "
        "stages of a six-stage journey")


def test_w597_p310_no_curriculum_without_a_named_scholar(client):
    """P3.10 — learning modules behind the RULED gate: withheld without a review, named when approved.

    Measured before this round: LearnTeachModule.tsx posted subject "Quran & Islamic Studies" to the
    GENERAL route /api/v1/education/curriculum and rendered the result to a learner under a caption
    calling it an AI-assisted study-plan FRAME. So AI-composed religious teaching content reached a
    learner carrying a disclaimer - and R7 says in as many words that A DISCLAIMER IS NOT A REVIEW.

    Gating the general route was not the answer: it serves Bloom's, the UK National Curriculum, IGCSE, IB
    and STEM, and withholding those would teach nobody anything (W594 guards that scope line, and FU-448
    records that it is the author's reading and not the Owner's). So religious requests are REFUSED there
    and served - when a scholar has approved them - by the gated QEP path.
    """
    import pathlib as _pl310

    from agentic_core.api import scholar_review as _sr310
    from agentic_core.religious_domain.subject_screen import screen_subject as _scr310

    _roster_p, _review_p = _sr310._roster_path(), _sr310._review_path()
    _saved_r = _roster_p.read_bytes() if _roster_p.exists() else None
    _saved_v = _review_p.read_bytes() if _review_p.exists() else None
    try:
        # ── THE SCREEN MAY REFUSE, NEVER CLEAR ──────────────────────────────────────────────────
        _flag = _scr310("Quran & Islamic Studies", "Intermediate", "bloom")
        _pass = _scr310("Photosynthesis", "ks3", "bloom")
        assert _flag["flagged"] is True and "quran" in _flag["matched"], _flag
        assert _pass["flagged"] is False and _pass["matched"] == [], _pass
        #  BOTH branches must deny clearing. A screen whose negative result reads as "secular" is the
        #  defect: the absence of a matched word is the absence of evidence, not evidence of absence.
        for _s310 in (_flag, _pass):
            assert "CANNOT certify one as secular" in _s310["basis"], (
                "the screen's result implies it cleared the subject, when all it can do is flag one",
                _s310["basis"])
            assert set(_s310) == {"flagged", "matched", "basis"}, (
                "the two branches return different key sets, so a caller cannot tell a missing field "
                "from a false one", sorted(_s310))

        # ── (1a) THE GENERAL ROUTE REFUSES A RELIGIOUS SUBJECT AND SAYS WHERE IT GOES ────────────
        _ref = client.post("/api/v1/education/curriculum",
                           json={"subject": "Quran & Islamic Studies", "level": "Intermediate"})
        assert _ref.status_code == 409, (
            "the general education route still composes religious teaching content, which R7 puts behind "
            "a named scholar before any learner sees it", _ref.status_code, _ref.text[:200])
        _rd = _ref.json()["detail"]
        assert _rd["where_instead"] == "/api/v1/qep/curriculum", (
            "the refusal does not say where the request should go, so it reads as a dead end", _rd)
        assert "quran" in _rd["matched"], (
            "the refusal does not name what matched, so a teacher whose secular course tripped the list "
            "cannot see why and cannot dispute it", _rd)
        #  AND IT MUST SURVIVE THE PAGE'S OWN TRUNCATION. apps/.../lib/api.ts renders a non-string detail
        #  as JSON.stringify(detail).slice(0, 300) through errorMessage(), so a refusal longer than that
        #  reaches a teacher on EducationHub cut off mid-sentence - which is how a careful explanation
        #  becomes unreadable JSON. The readable sentence must fit, and must come first.
        import json as _js310
        _wire = _js310.dumps(_rd)[:300]
        assert "/api/v1/qep/curriculum" in _wire, (
            "the referral falls outside the first 300 characters of the serialised detail, which is all "
            "the page keeps - so the one thing a teacher needs is the thing truncated away", len(_wire),
            _wire[-80:])
        assert _rd["message"].endswith("."), (
            "the refusal's readable sentence is itself truncated", _rd["message"][-60:])

        # ── (1b) AND THE GENERAL ROUTE STILL SERVES SECULAR CURRICULUM, UNGATED ──────────────────
        #  W594's own leg for this posted `topic`, which CurriculumRequest does not accept, so it 422'd
        #  and its status==200 branch never ran. Posting the field the model actually declares.
        _sec = client.post("/api/v1/education/curriculum",
                           json={"subject": "Photosynthesis", "level": "ks3", "framework": "bloom"})
        assert _sec.status_code == 200, (
            "secular curriculum is no longer servable, which no ruling asks for and which would withhold "
            "mathematics from every user", _sec.status_code, _sec.text[:200])
        _sb = _sec.json()
        assert "review_state" not in _sb, (
            "the scholar gate has been applied to the GENERAL education route - see FU-448, which is the "
            "Owner's question and not this round's to answer", sorted(_sb))
        assert _sb["religious_subject_screen"]["flagged"] is False, _sb["religious_subject_screen"]
        assert "CANNOT certify" in _sb["religious_subject_screen"]["basis"], (
            "the served curriculum's screen RECORD carries no statement that nothing cleared it",
            _sb["religious_subject_screen"])
        #  FU-456 — THE READER'S HALF, which this leg used to claim and not check. Its message spoke about a
        #  reader inferring a clearance while the assertion read only the API payload, and `withDisclosures`
        #  appended none of it: the instrument described a surface it did not check, which is the same defect
        #  in the guard as in the code.
        assert "cannot certify a subject as secular" in (_sb.get("screen_note") or "").lower(), (
            "the response carries no ONE-LINE note for a reader, so the fact that nothing cleared this "
            "subject exists only in a structured key no surface renders", _sb.get("screen_note"))
        _dt456 = (_pl310.Path(__file__).resolve().parents[1]
                  / "apps/workstation-superapp/src/components/DomainTool.tsx").read_text(encoding="utf-8")
        assert "data?.screen_note" in _dt456, (
            "the shared disclosure channel does not append screen_note, so the note reaches no reader and "
            "is absent from the history record saveOutput persists from this same text")

        # ── (1c) WITH AN EMPTY ROSTER THE GATED PATH SERVES NO CONTENT AT ALL ────────────────────
        for _p310 in (_roster_p, _review_p):
            if _p310.exists():
                _p310.unlink()
        assert _sr310.roster_is_empty(), "the roster did not clear, so this leg cannot see an empty gate"
        _c1 = client.post("/api/v1/qep/curriculum",
                          json={"subject": "W597 Quran Studies", "level": "Intermediate",
                                "duration_weeks": 6})
        assert _c1.status_code == 200, (_c1.status_code, _c1.text[:200])
        _b1 = _c1.json()
        assert _b1["curriculum"] is None, (
            "curriculum content is servable with no scholar on the roster, which is exactly what R7 "
            "forbids - and a disclaimer in its place is not a review", str(_b1)[:300])
        assert _b1["review_state"] == "withheld" and _b1["scholar_reviewed"] is False, _b1
        assert "no scholar" in _b1["review_note"].lower(), (
            "the learner is not told WHY nothing is shown, so an absence reads as a fault in the platform "
            "rather than as a deliberate withholding", _b1["review_note"])
        assert _b1["gate"]["roster_is_empty"] is True and _b1["gate"]["scholars_on_roster"] == 0, _b1["gate"]

        # ── (3) AN APPROVED MODULE NAMES THE REVIEW THAT CLEARED IT ──────────────────────────────
        _sr310.add_scholar("w597-shaykha", "A Named Scholar", "ijazah in qira'at", "pytest-owner")
        _key310 = "qep_curriculum:W597 Quran Studies:Intermediate:6"
        _d310 = _sr310.decide(_key310, "w597-shaykha", approve=True, note="sound for this level")
        assert _d310["ok"] is True, ("the approval was refused, so clause (3) cannot be driven", _d310)
        _c2 = client.post("/api/v1/qep/curriculum",
                          json={"subject": "W597 Quran Studies", "level": "Intermediate",
                                "duration_weeks": 6}).json()
        assert _c2["curriculum"], (
            "an APPROVED module is still withheld, so approval does nothing and the gate is a wall",
            str(_c2)[:300])
        assert _c2["scholar_reviewed"] is True and "w597-shaykha" in _c2["review_note"], (
            "a shipped module does not NAME the review that cleared it, which is clause (3) word for word",
            _c2.get("review_note"))

        # ── AND A MODULE WITH NO REVIEW IS NOT SERVABLE, driven as a DIFFERENT subject ───────────
        _c3 = client.post("/api/v1/qep/curriculum",
                          json={"subject": "W597 Unreviewed Subject", "level": "Intermediate",
                                "duration_weeks": 6}).json()
        assert _c3["curriculum"] is None and _c3["review_state"] == "withheld", (
            "a second subject is served on the strength of the FIRST one's approval, so one approval "
            "clears everything", str(_c3)[:300])

        # ── (2) THE SURFACE STATES THE RULED STATE AND DOES NOT DRESS THE ABSENCE ───────────────
        _lt310 = (_pl310.Path(__file__).resolve().parents[1]
                  / "apps/workstation-superapp/src/components/LearnTeachModule.tsx").read_text(
                      encoding="utf-8")
        #  THE CODE IS SEARCHED, NOT THE FILE. The first run of this leg went red on the COMMENT that
        #  records the change - which names the old route in order to explain why it was abandoned. That
        #  is the fifth time this suite has been bitten by a fix comment quoting the literal its own
        #  guard forbids, and the rule the project settled on is to forbid the BINDING rather than the
        #  text. So the line comments come out first and the assertion is about what the page CALLS.
        _lt310_code = "\n".join(
            ln for ln in _lt310.splitlines() if not ln.lstrip().startswith("//"))
        assert "//" not in _lt310_code or len(_lt310_code) < len(_lt310), (
            "no comment line was stripped, so this leg is searching the whole file again and the next "
            "comment that names a route will break it")
        assert "/api/v1/qep/curriculum" in _lt310_code, (
            "the page still posts religious curriculum to the GENERAL route, so what a learner sees never "
            "passes the gate at all")
        assert "/api/v1/education/curriculum" not in _lt310_code, (
            "the page still CALLS the ungated route, so the gated one is decoration")
        assert "review_note" in _lt310, (
            "the page does not render the gate's reason, so a learner meets an empty panel and is told "
            "nothing - the item's own instruction is that this must not be dressed")
        assert "data-testid=\"learnteach-review-state\"" in _lt310, (
            "the review state is not rendered, so a withheld plan is indistinguishable from a failed fetch")
        #  the stale sentence: a registry now EXISTS, it is merely empty, and those are different claims
        assert "needs a real registry" not in _lt310, (
            "the page still says scholar verification NEEDS A REAL REGISTRY. W594 built one - "
            "agentic_core/api/scholar_review.py, with a roster, a body-hash-bound approval and a refusal "
            "that distinguishes an empty roster from an unknown reviewer. The registry exists and is "
            "EMPTY, which is a different statement, and the page must make the true one")
    finally:
        for _p310, _v310 in ((_roster_p, _saved_r), (_review_p, _saved_v)):
            if _v310 is None:
                if _p310.exists():
                    _p310.unlink()
            else:
                _p310.write_bytes(_v310)
        assert _sr310.roster_is_empty() or _saved_r is not None, (
            "this guard left a scholar on the roster, which changes the gate for every later test")


def test_w597_a_structured_refusal_never_reaches_react_as_a_child():
    """P3.10's blocker — a dict `detail` put straight into error state THROWS when React renders it.

    Found by refuting P3.10 before building it. A route may raise HTTPException(detail={...}) — seven
    already do — and axios hands that object to the page unchanged. `setError(obj)` followed by `{error}`
    makes an object a React child, and React throws: the surface CRASHES rather than showing a poor
    message. P3.10's own 409 lands on a DomainTool endpoint, so it would have been the first live one.

    I FIRST RECORDED THIS AS 22 SITES AND IT IS 4. The 22 occurrences of that expression split by SHAPE:
    four put the object into state (the crash), about fifteen interpolate it into a template string so it
    stringifies to the object-Object text (useless to a reader, but not fatal), and three destructure it
    behind a `typeof` check and are already correct. A grep gives SITES, not instances; the defect is what
    the site DOES with the value. This guard therefore asserts the crash SHAPE and not the expression.
    """
    import pathlib as _pld
    import re as _red

    _root = _pld.Path(__file__).resolve().parents[1] / "apps/workstation-superapp/src"

    # ── (1) THE HELPER EXISTS AND RETURNS A STRING FOR EVERY SHAPE A DETAIL CAN TAKE ───────────
    _api_src = (_root / "lib/api.ts").read_text(encoding="utf-8")
    assert "export function axiosDetail" in _api_src, (
        "no shared helper coerces an axios error's detail, so each page decides for itself and four of "
        "them decided to hand React an object")
    for _shape, _why in (
            ("Array.isArray(d)", "a 422 carries a LIST of {loc, msg}; rendering that as JSON tells a "
                                 "reader nothing they can act on, and as an array child it throws just "
                                 "as an object does"),
            (".message", "a structured refusal's own readable sentence is the right thing to show, and "
                         "the gated-curriculum refusal puts one there deliberately"),
            ("JSON.stringify(d)", "an unrecognised object must still be rendered as something TRUE "
                                  "rather than replaced by 'the backend may be unavailable', which is a "
                                  "different and false claim about a backend that refused with a reason")):
        assert _shape in _api_src, (f"axiosDetail does not handle {_shape}: {_why}")

    # ── (2) NO PAGE PUTS A RAW DETAIL INTO ERROR STATE — the crash shape, named ────────────────
    #  `setX(e?.response?.data?.detail || …)`. A destructured `const d = …detail` followed by a typeof
    #  check is NOT this shape and is deliberately allowed: three files already do it correctly, and
    #  rewriting correct code to use a new helper is churn that risks a regression for no gain.
    _crash = _red.compile(r"set[A-Za-z_]*\(\s*e\?\.response\?\.data\?\.detail\s*\|\|")
    _offenders, _scanned = [], 0
    for _f in sorted(_root.rglob("*.tsx")) + sorted(_root.rglob("*.ts")):
        _scanned += 1
        _t = _f.read_text(encoding="utf-8")
        for _m in _crash.finditer(_t):
            _offenders.append(f"{_f.name}:{_t[:_m.start()].count(chr(10)) + 1}")
    assert _scanned > 50, ("this leg scanned almost nothing, so it would pass on an empty tree", _scanned)
    assert _offenders == [], (
        "a page puts an axios error's raw `detail` into state and renders it. When the route answering "
        "that call raises HTTPException with a dict — seven routes already do — React is handed an "
        "object as a child and THROWS, so the surface crashes instead of showing the refusal. Use "
        "axiosDetail(e, fallback)", _offenders)

    # ── (3) AND THE GATED REFUSAL IS THE SHAPE THE HELPER CAN READ ─────────────────────────────
    #  P3.10's 409 detail carries `message` first precisely so this helper, and the fetch path's own
    #  errorMessage, both render a sentence rather than JSON. Asserted on the SOURCE OF THE REFUSAL so
    #  the two cannot drift apart silently.
    _edu_src = (_pld.Path(__file__).resolve().parents[1]
                / "agentic_core/api/education.py").read_text(encoding="utf-8")
    assert '"message": (' in _edu_src, (
        "the religious-subject refusal carries no `message` key, so axiosDetail falls through to "
        "JSON.stringify and a teacher is shown a serialised dict")


def test_w597_p324_a_schedule_never_a_forecast(client):
    """P3.24 — staged simulation, procedural first: a SCHEDULE computed from cited rules, and no forecast.

    The Owner's ruling of 2026-10-03c (option (a)) is the frame and it is SPENT: the platform computes
    schedules and assembles evidence and never forecasts an outcome. No outcome dataset exists here, no
    judge data, and a settlement range shown to someone in a live matter is a number they will act on
    however it is labelled. A later round may not reopen that on its own judgement.

    THE RULES ARE AN INPUT. Encoding procedural rules in the module would make it a statement about what
    the law IS — legal advice in a data structure — so the caller supplies each rule with its citation and
    the module does only arithmetic and names whose rule it used.
    """
    import datetime as _dt324

    from agentic_core.simulation import staged as _ss

    # ── EVERY DATE IS ARITHMETIC OVER A CITED RULE, re-checked here ─────────────────────────────
    _events = {"dismissal": "2026-01-15", "acas_received": "not-a-date"}
    _rules = [
        {"id": "R1", "citation": "(guard-supplied rule A)", "from_event": "dismissal", "offset_days": 90},
        {"id": "R2", "citation": "(guard-supplied rule B)", "from_event": "acas_received", "offset_days": 28},
        {"id": "R3", "citation": "(guard-supplied rule C)", "from_event": "hearing", "offset_days": 14},
        {"id": "R4", "citation": "(guard-supplied rule D)", "from_event": "dismissal", "offset_days": "soon"},
    ]
    _r = _ss.procedural_timeline(_events, _rules)
    assert len(_r["timeline"]) == 1, ("only the one computable rule should yield a date", _r["timeline"])
    _e = _r["timeline"][0]
    for _f in ("rule", "citation", "from_event", "from_date", "offset_days", "date", "arithmetic"):
        assert _e.get(_f) not in (None, ""), (f"a computed date omits {_f}, so it cannot be traced to a "
                                              f"rule", _f, _e)
    #  RE-COMPUTE IT: the leg must not take the module's own arithmetic on trust
    _base = _dt324.date.fromisoformat(_e["from_date"])
    assert _e["date"] == (_base + _dt324.timedelta(days=_e["offset_days"])).isoformat(), (
        "the stated date is not the arithmetic the entry claims", _e)
    assert _e["arithmetic"].count(_e["date"]) >= 1 and _e["from_date"] in _e["arithmetic"], (
        "the sum is not shown in words, so a reader cannot check it by hand", _e["arithmetic"])

    # ── A RULE THAT CANNOT BE COMPUTED IS NAMED, WITH ITS REASON, AND NEVER ESTIMATED ───────────
    _why = {n["rule"]: n["why"] for n in _r["not_computable"]}
    assert set(_why) == {"R2", "R3", "R4"}, ("a rule that could not be computed was silently dropped", _why)
    assert "not an ISO date" in _why["R2"] and "NOT guessed" in _why["R2"], _why["R2"]
    assert "records no event" in _why["R3"], _why["R3"]
    assert "does not invent" in _why["R4"], _why["R4"]

    # ── A STAGE WITH NO INPUT SAYS SO — and `timeline` is None, not an empty list ───────────────
    for _n, _word in ((2, "no precedent index"), (3, "no causal graph")):
        _s = _ss.stage(_n)
        assert _s["status"] == _ss.NO_INPUT, (f"stage {_n} does not report NO INPUT", _s)
        assert _s["timeline"] is None, (
            f"stage {_n} returns an empty timeline, which makes an unavailable stage look like a stage "
            f"that found nothing - different facts", _s)
        assert _word in _s["basis"], (f"stage {_n} does not say WHY it has no input", _s["basis"])

    # ── STAGE 4 IS SHADOW-ONLY, AND THE ATTEMPT TO SURFACE IT IS REFUSED ───────────────────────
    _att = _ss.surface_stage_4("a client asked to see it")
    assert _att["refused"] is True and _att["surfaced"] is False, (
        "stage 4 can be put on a surface, which the ruling forbids", _att)
    assert _att["reason_given"], ("the refusal does not record what was asked for", _att)
    assert "whatever reason is given" in _att["basis"], (
        "the refusal reads as conditional, so a caller could believe some reason would satisfy it",
        _att["basis"])

    # ── NO SURFACE CARRIES A PREDICTED OUTCOME OR A SETTLEMENT RANGE ────────────────────────────
    _f = _ss.forecast("what are my chances")
    assert _f["forecast"] is None and _f["refused"] is True, ("a forecast is produced", _f)
    assert "does NOT forecast" in _f["basis"] and "settlement range" in _f["basis"], _f["basis"]
    #  and no RESPONSE field anywhere in this module's output carries forecast vocabulary
    def _strings(obj):
        if isinstance(obj, str):
            return [obj]
        if isinstance(obj, dict):
            return [s for k, v in obj.items() for s in _strings(k) + _strings(v)]
        if isinstance(obj, (list, tuple)):
            return [s for v in obj for s in _strings(v)]
        return []
    for _resp in (_r, _ss.stage(2), _ss.stage(3), _ss.stage(4)):
        _keys = [k for k in (_resp if isinstance(_resp, dict) else {})]
        for _term in _ss.FORECAST_TERMS:
            assert not any(_term in str(k).lower() for k in _keys), (
                f"a staged-simulation response carries a field named for {_term!r}", _term, _keys)
    #  the refusals DO name the vocabulary, deliberately - that is how a caller learns what is refused
    assert any(t in _f["basis"].lower() for t in ("settlement range", "forecast")), _f["basis"]

    # ── FU-452 — THE OLDER ENGINE IN THIS PACKAGE REFUSES TOO ───────────────────────────────────
    #  Measured while preparing this item, which was about to add an honest staged simulation to a
    #  package that already held a fabricating one. RealitySimulationEngine.simulate_future returned a
    #  health score derived from two caller-supplied numbers with default values, a prosperity
    #  percentage of "+24%" or "-12%" chosen by a threshold, and a stability index that was one of two
    #  magic constants. Every figure was invented. Leaving it beside a module that refuses to forecast
    #  would leave a reader to pick between them, and they would reasonably take the older one for this
    #  platform's position - so it refuses, rather than being deleted, for the same reason the staged
    #  module serves its own refusals.
    from agentic_core.simulation.engine import simulation_engine as _se
    _old = _se.simulate_future({"collective_empathy": 0.9, "resource_scarcity": 0.1})
    assert _old.get("refused") is True, (
        "the older simulation engine still produces a civilisational forecast", _old)
    for _gone in ("health_score", "prosperity_projection", "stability_index"):
        assert _gone not in _old, (
            f"the invented {_gone} is still returned - and it was never measured from anything", _gone)
    assert "use_instead" in _old and "procedural_timeline" in _old["use_instead"], (
        "the refusal does not say what to use instead, so a caller is left with nothing", _old)

    #  AND THE TWO IMPORTS OF A CLASS THAT WAS NOT THERE. Both named a core module in which
    #  EnvironmentalSimulator is not defined; one is at MODULE level, so that SDK could not be imported
    #  at all. Driven by importing it, which is the only check that would have caught this.
    import importlib as _il452
    _bi = _il452.import_module("products.business_incubator.sdk.business_incubator")
    assert _bi is not None, "the business_incubator SDK still cannot be imported"
    #  core must NOT have been wired to a product SDK to achieve that - the layering is the point
    import pathlib as _pl452
    _base_src = (_pl452.Path(__file__).resolve().parents[1]
                 / "agentic_core/reactor/ecosystem/base.py").read_text(encoding="utf-8")
    assert "import EnvironmentalSimulator" not in _base_src, (
        "core still imports a simulator class; if it now imports it from the digital_reactor SDK then "
        "core depends on a product built on top of it, which is an inversion rather than a fix")


def test_w599_p217b_the_per_worker_store_is_proven_isolated():
    """P2.17 ACCEPT (b) — the per-worker store, proven isolated by a test that FAILS if two workers share it.

    The last unmet requirement of P2.17. Its other parts are done: the bundle as a file-connected component
    (W568, three of four limits already met), the round-cost figures computed rather than typed (W565), the
    parallel suite proven to give the same pass/fail set as the serial one on one tree (W540, with figures),
    and the blind harness's runtime measured before and after (W569 — which refuted its own row's premise:
    sharding gave 1.60x at two shards and got WORSE at four, because contention and not the single tree was
    the limit).

    WHY THIS NEEDED A REFACTOR FIRST. `conftest._XDIST_WORKER` is read at module import and `_per_worker`
    closed over it, so no test could vary the worker: setting the env var afterwards changes nothing, and
    reloading the module rebinds its own instance while every importer keeps the old one. The worker is now a
    PARAMETER defaulting to the constant, so the property can be DRIVEN. A property that cannot be driven
    cannot be proven, and "proven" is the requirement's own word.
    """
    import os as _os217
    import pathlib as _pl217

    import conftest as _cf217

    # ── 1. TWO WORKERS NEVER COLLIDE, and the extension is split correctly ──────────────────────
    for _p217 in ("data/_test_store", "data/ueg.jsonl", "a.b/c", "/abs/root"):
        _a, _b = _cf217._per_worker(_p217, "gw0"), _cf217._per_worker(_p217, "gw1")
        assert _a != _b, (
            "two workers map the same path to the same place, which IS sharing the store - the documented "
            "corruption mode this mechanism exists to prevent", _p217, _a)
        assert "gw0" in _a and "gw1" in _b, (_p217, _a, _b)
    #  the suffix goes BEFORE the extension or every reader keyed on it misses the file
    assert _cf217._per_worker("data/ueg.jsonl", "gw0") == "data/ueg__gw0.jsonl", (
        "the worker suffix was appended AFTER the extension, so the file is no longer a .jsonl and a reader "
        "selecting by extension skips it", _cf217._per_worker("data/ueg.jsonl", "gw0"))

    # ── 2. A SERIAL RUN IS UNCHANGED ────────────────────────────────────────────────────────────
    assert _cf217._per_worker("data/_test_store", "") == "data/_test_store", (
        "a serial run's path was rewritten, so every non-xdist run reads a store nothing else writes")

    # ── 3. EVERY SUBDIVIDED VAR IS SUFFIXED UNDER A WORKER — not a sample ───────────────────────
    #  The real corruption mode is ONE path being missed while the rest look isolated: conftest's own comment
    #  records that without this an explicit DATA_DIR would have pointed all eight workers at the same
    #  directory, which is W394's defect one layer up. So the declared set is read from conftest rather than
    #  retyped here, and a var added there without being subdivided fails this.
    _names = [v for v, _ in _cf217.SUBDIVIDED]
    assert len(_names) >= 7, ("the subdivided set shrank, so paths that were isolated no longer are", _names)
    _worker = _os217.environ.get("PYTEST_XDIST_WORKER") or ""
    if _worker:
        _unsuffixed = [v for v in _names
                       if _os217.environ.get(v) and f"__{_worker}" not in _os217.environ[v]]
        assert _unsuffixed == [], (
            "running under xdist and these paths carry NO worker suffix, so these workers share them while "
            "every other path looks isolated", _worker, _unsuffixed)
    else:
        #  serial: the mechanism cannot be observed live, so the per-var transformation is driven directly.
        #  Skipping here would make this leg pass for the wrong reason on every serial run - which is every
        #  run of this suite that is not -n.
        for _v in _names:
            assert _cf217._per_worker(f"/root/{_v.lower()}", "gw3") != f"/root/{_v.lower()}", _v

    # ── 4. NO TWO SUBDIVIDED PATHS COLLAPSE TO ONE ──────────────────────────────────────────────
    #  Two purposes sharing one store is a DIFFERENT sharing bug from two workers sharing one, and the
    #  string arithmetic above cannot rule it out.
    _live = {v: _os217.environ.get(v) for v in _names if _os217.environ.get(v)}
    _dupes = {}
    for _v, _val in _live.items():
        _dupes.setdefault(_os217.path.normcase(_os217.path.abspath(_val)), []).append(_v)
    _shared217 = {k: v for k, v in _dupes.items() if len(v) > 1}
    #  DATA_DIR and WORKSTATION_DATA_DIR are the same root by design - they are two names for one store.
    _shared217 = {k: v for k, v in _shared217.items()
                  if sorted(v) != ["DATA_DIR", "WORKSTATION_DATA_DIR"]}
    assert _shared217 == {}, (
        "two differently-purposed stores resolve to ONE directory, so one subsystem's writes land in "
        "another's store", _shared217)

    # ── 5. PROVEN BY A WRITE, not by string arithmetic ──────────────────────────────────────────
    #  Comparing two strings proves the formatter. The requirement says the store is proven ISOLATED, so a
    #  file is written through the live store path and its location is read back.
    _root217 = _pl217.Path(_os217.environ["DATA_DIR"])
    _root217.mkdir(parents=True, exist_ok=True)
    _probe = _root217 / "w599_isolation_probe.txt"
    try:
        _probe.write_text("w599", encoding="utf-8")
        assert _probe.is_file(), ("the store root is not writable, so nothing here proves isolation", _root217)
        if _worker:
            assert f"__{_worker}" in str(_probe.resolve()), (
                "a file written through the live store landed OUTSIDE this worker's own directory, so the "
                "store is shared in fact whatever the paths say", str(_probe.resolve()), _worker)
    finally:
        try:
            _probe.unlink()
        except OSError:
            pass


def test_w599_p322_a_passage_without_a_resolvable_location_cannot_be_cited(client, tmp_path):
    """P3.22 — the owned index, and every retrieved passage traceable to a LINE.

    Measured before this round: `scan()` reduced each file to a SET of words (`tokens[rel]`), so the index
    knew which documents contained a term and nothing about where. A hit could name a document and never a
    place inside it — which clause (1) forbids in as many words, and which is exactly the defect FU-450
    recorded in the archived text_indexer.py ("real, but indexes FILES not passages").

    Clauses (2) and (3) were ALREADY met and are asserted here anyway: three states, a reason per unread
    file, and nothing unread in the index. A guard covering only the new half would let the older half be
    broken by a later round without anything going red.
    """
    import os as _os322
    import pathlib as _pl322

    from agentic_core.horizon import archive as _ar322

    #  a real inbox on disk, because this is a module that reads FILES and a fixture dict would test
    #  nothing about reading. The inbox location is taken from the module's own resolver so the test does
    #  not hard-code a path the deployment may move.
    _inbox = _pl322.Path(_ar322._inbox())
    _inbox.mkdir(parents=True, exist_ok=True)
    _doc = _inbox / "w599_note.txt"
    #  line 1 non-empty, lines 2-3 blank, line 4 the needle. If the splitter numbered only NON-EMPTY lines
    #  the needle would be reported at line 2, and a reader opening line 2 would find nothing — a citation
    #  that resolves to the wrong text.
    _doc.write_text("Opening remarks about procedure\n\n   \n"
                    "The committee resolved to adjourn until the following term\n"
                    "Closing note\n", encoding="utf-8")
    _secret = _inbox / "w599_secret_token.txt"
    _secret.write_text("this must never be read\n", encoding="utf-8")
    #  scan() PERSISTS the index through atomic_write_json, so calling it here overwrites the shared store
    #  that other tests read. Deleting the temp FILES is not enough — the manifest naming them survives. The
    #  store's bytes are saved and restored, the same discipline the scholar roster needed in W594: a guard
    #  that leaves shared state behind makes the next test's result depend on whether this one ran first.
    _store_p = _ar322._store()
    _saved_store = _store_p.read_bytes() if _store_p.exists() else None
    try:
        _man = _ar322.scan()
        #  THE BODIES LIVE IN THE PERSISTED DOC, not in the returned manifest. `files[]` carries a per-file
        #  `passages` COUNT and `passages_capped`; the passage bodies sit at the top level of the store
        #  beside `tokens`, which is the shape `_read_index()` returns and the shape `search()` reads.
        #  Measured W599 rather than assumed: the first draft of this guard read `man["passages"]` and found
        #  an empty dict while search() was finding the passage correctly.
        _doc322 = _ar322._read_index()
        _bodies = _doc322.get("passages") or {}

        # ── (3) NOTHING UNREAD IS IN THE KNOWLEDGE BASE, and (2) EVERY UNREAD FILE SAYS WHY ────
        _by_path = {f["path"]: f for f in _man["files"]}
        _states = {f["path"]: f["state"] for f in _man["files"]}
        assert _states.get("w599_note.txt") == _ar322.INDEXED, _states.get("w599_note.txt")
        assert _states.get("w599_secret_token.txt") == _ar322.EXCLUDED, (
            "a file whose NAME marks it secret was read; exclusion must happen before any read, because a "
            "rule applied afterwards has already loaded the secret and nothing downstream can undo that",
            _states.get("w599_secret_token.txt"))
        assert "w599_secret_token.txt" in _by_path, (
            "the excluded file is not even LISTED, so the exclusion is invisible - which looks exactly "
            "like a file that was never there")
        for _p322, _f322 in _by_path.items():
            assert _f322.get("basis"), (f"{_p322} carries no basis for its state", _f322)
            if _f322["state"] != _ar322.INDEXED:
                assert _p322 not in _bodies, (
                    f"{_p322} is not INDEXED yet has passages in the knowledge base - the FU-124 rule is "
                    f"that nothing unread is in it", _f322["state"])
                assert _p322 not in (_man.get("tokens") or {}), (
                    f"{_p322} is not INDEXED yet contributed tokens", _f322["state"])

        # ── (1) EVERY PASSAGE CARRIES A LINE, AND THE LINE RESOLVES IN THE REAL DOCUMENT ───────
        _ps = _bodies.get("w599_note.txt") or []
        assert _ps, ("the indexed document contributed no located passages, so nothing can be cited from "
                     "it", sorted(_bodies))
        _lines = _doc.read_text(encoding="utf-8").splitlines()
        for _p in _ps:
            assert isinstance(_p.get("line"), int) and _p["line"] >= 1, (
                "a passage carries no line number, so a claim traced to it names a document and not a "
                "place in it", _p)
            #  RE-READ THE DOCUMENT AT THE STATED LINE. This is the whole clause: a line that does not
            #  resolve is worse than no citation, because it is a precise-looking reference to something
            #  the document does not say.
            assert _p["line"] <= len(_lines), (
                "a passage cites a line beyond the end of the document", _p["line"], len(_lines))
            assert _p["text"].strip() and _p["text"].strip() in _lines[_p["line"] - 1], (
                "the text at the cited line is NOT the text the index recorded - so the numbering counts "
                "something other than file lines, and every citation from this index resolves to the "
                "wrong place", _p["line"], _p["text"], _lines[_p["line"] - 1])

        # ── AND RETRIEVAL RETURNS THE LOCATION, OR REFUSES TO CITE ─────────────────────────────
        _res = _ar322.search("adjourn")
        _hits = [h for h in _res["passages"] if h["path"] == "w599_note.txt"]
        assert _hits, ("a term present in the document was not retrieved as a LOCATED passage",
                       _res.get("passages_matched"), _res.get("hits"))
        assert _hits[0]["line"] == 4, (
            "the needle is on line 4 of the file, counting the two blank lines. A different number means "
            "the splitter numbers non-empty lines only, and every citation is off by the number of blank "
            "lines above it", _hits[0]["line"], _hits[0].get("text"))

        #  A PASSAGE WITH NO RESOLVABLE LINE IS REPORTED AS UNCITABLE, not returned without one.
        #  Written INTO THE STORE, because search() reads the persisted doc: handing it a fake manifest
        #  would test a parameter the live route does not use, which is a test of nothing.
        import json as _js322
        _doc_b = _ar322._read_index()
        _doc_b.setdefault("passages", {})["ghost.txt"] = [
            {"line": None, "text": "the committee resolved to adjourn", "tokens": ["adjourn"]}]
        _store_p.write_text(_js322.dumps(_doc_b), encoding="utf-8")
        _r2 = _ar322.search("adjourn")
        assert all(h["path"] != "ghost.txt" for h in _r2["passages"]), (
            "a passage with no resolvable location was CITED, which clause (1) forbids",
            [h for h in _r2["passages"] if h["path"] == "ghost.txt"])
        assert _r2["not_citable"] and "CANNOT be cited" in _r2["not_citable"][0]["why"], (
            "an unlocatable passage was dropped silently rather than reported - so a caller cannot tell "
            "a result set that found nothing from one that found something it could not cite",
            _r2.get("not_citable"))

        # ── THE CAPS ARE PUBLISHED, NOT SILENT ────────────────────────────────────────────────
        _b = _man["bounds"]
        assert _b["max_passages_per_file"] == _ar322.MAX_PASSAGES_PER_FILE, _b
        assert "cap nobody is told about" in _b["passage_basis"], _b["passage_basis"]
        #  and a limited search SAYS it is limited - the defect W596 found in its own leaderboard, whose
        #  basis denied being a top-N while the code sliced the rows
        _r3 = _ar322.search("adjourn", limit=0)
        assert _r3["truncated"] is True and "TOP-0" in _r3["file_hits_basis"], _r3["file_hits_basis"]
        assert _res["truncated"] is False and "none omitted" in _res["file_hits_basis"], _res["file_hits_basis"]

        # ── NOTHING IMPLIES SEMANTIC RECALL, ON THE RESPONSE AND ON A SURFACE ─────────────────
        assert _res["embedding_backend"] is None, _res.get("embedding_backend")
        assert "not semantic recall" in _res["basis"], (
            "the basis does not say that a document phrasing the same idea differently will not be found, "
            "so a lexical index reads as semantic search", _res["basis"])
        #  the item says "the SURFACE states embeddings: none installed". W597 measured that no .tsx
        #  mentioned embeddings at all, so the claim was true in the payload and absent from every screen.
        #  SCOPED TO THE RENDERED ELEMENT, not to the word. A bare `"embeddings" in text` search stayed
        #  GREEN when the blind removed the statement's own testid, because the word still appeared in a
        #  neighbouring attribute and in prose — the too-broad presence check this suite keeps being bitten
        #  by. The testid is what a reader's element is identified BY, so that is what is asserted.
        _root322 = _pl322.Path(__file__).resolve().parents[1] / "apps/workstation-superapp/src"
        _shown = [p.name for p in _root322.rglob("*.tsx")
                  if 'data-testid="horizon-archive-embeddings"' in p.read_text(encoding="utf-8")]
        assert _shown, (
            "no page states that no embedding backend is installed, so a reader of the search surface is "
            "left to assume semantic recall - which the item forbids in as many words")
    finally:
        for _f in (_doc, _secret):
            try:
                _os322.unlink(_f)
            except OSError:
                pass
        #  the persisted index last, so a failure above still restores it
        if _saved_store is None:
            if _store_p.exists():
                _store_p.unlink()
        else:
            _store_p.write_bytes(_saved_store)


def test_w599_p35_an_image_is_read_or_the_refusal_names_what_is_missing(client):
    """P3.5 — clauses (2) and (3) built; clause (1) a §18 boundary with its reason.

    MEASURED BEFORE BUILDING, and my own assessment was wrong three times before this: clause (1) was
    ALREADY built — `avatars/api.py::_ollama_vision` posts the image to a LOCAL Ollama vision model and
    returns None when none answers, its docstring saying the caller "falls back honestly — never fabricates
    image content". It is unreachable only because no vision model is pulled.

    What was missing: an accurate reason NAMING what is absent (the status said only `no_vision_model`,
    which is a label), and an accept list computed from what is installed (nothing computed one).
    """
    import base64 as _b64_35
    import pathlib as _pl35

    from agentic_core.ai.native import tiers as _t35

    # ── (3) THE ACCEPT LIST IS COMPUTED, and the screen may FLAG but never CLEAR ────────────────
    #  A PURE function over model names, because local_models() returns [] under AI_DISABLE_LOCAL and this
    #  suite sets it: a check that asked the environment could never be driven, and would read "nothing
    #  installed" forever while passing whatever the matching logic did.
    _none = _t35.image_intake([])
    assert _none["can_read_images"] is False and _none["accepts"] == [], (
        "an accept list is offered with no resource that can read an image - a list naming a format "
        "nothing can read is a promise this deployment cannot keep", _none["accepts"])
    assert "EMPTY because" in _none["accepts_basis"], _none["accepts_basis"]

    _with = _t35.image_intake(["llava:13b", "llama2", "some-unreleased-vlm"])
    assert _with["can_read_images"] is True and _with["accepts"], (
        "a recognised vision family is installed and the accept list is still empty", _with)
    assert _with["resources"] == ["llava:13b"], (
        "the family match failed on a TAGGED pull; `llava:13b` must match the llava family or every tagged "
        "install is missed", _with["resources"])
    #  A SCREEN MAY REFUSE, NEVER CLEAR: an unrecognised model is reported, never called text-only
    assert "some-unreleased-vlm" in _with["unrecognised_models"], (
        "a model the list does not recognise was silently dropped - 'I do not recognise this model' is not "
        "'this model cannot read an image', and silently excluding it makes the symptom look like a bug in "
        "the refusal rather than in the match", _with)
    assert "cannot establish that a model is NOT" in _with["vision_screen_basis"], (
        "the screen's result implies it cleared the models it did not match", _with["vision_screen_basis"])

    # ── (2) THE REFUSAL NAMES WHAT IS MISSING, FROM MEASURED STATE ─────────────────────────────
    assert _none["refusal"], "no refusal is produced when nothing can read an image"
    for _frag35 in ("NO TEXT IS PRODUCED", "perception tier needs", "GB"):
        assert _frag35 in _none["refusal"], (
            f"the refusal does not carry {_frag35!r}: it must name the measured shortfall, not merely say "
            f"that it failed", _none["refusal"][:200])
    assert "fabricated description" in _none["refusal"], (
        "the refusal does not say that nothing was guessed at from the image - which is the defect this "
        "item exists to prevent, and the same class as the transcription mock W495 deleted")
    assert _with["refusal"] is None, (
        "a refusal is asserted on a deployment that CAN read an image, contradicting the reading it would "
        "perform", _with["refusal"])

    # ── AND IT REACHES THE CALLER, on every path where the image was not read ───────────────────
    #  Measured W599: with no owned model AND an external key present while AI_ALLOW_EXTERNAL is off, the
    #  status is `blocked_by_policy` - which attributes the failure to POLICY while a resource is ALSO
    #  missing, so a reader concludes an administrator blocked it. The refusal therefore travels on every
    #  not-understood path, not only on `no_vision_model`.
    _img35 = _b64_35.b64encode(b"not-a-real-png").decode()
    _r35 = client.post("/api/v1/avatar/chat",
                       json={"message": "Describe this image.", "context": "w599", "image_base64": _img35})
    assert _r35.status_code == 200, (_r35.status_code, _r35.text[:160])
    _b35 = _r35.json()
    assert _b35["image_understood"] is False, (
        "the image was reported as understood on a deployment with no vision model", _b35.get("image_status"))
    assert _b35.get("image_refusal"), (
        "the reply carries no reason at all: the status alone is a LABEL, and clause (2) asks for an "
        "accurate reason naming what is missing", _b35.get("image_status"))
    assert "perception tier needs" in _b35["image_refusal"], _b35["image_refusal"][:160]
    assert _b35.get("image_accepts") == [], (
        "the reply advertises an image format it cannot read", _b35.get("image_accepts"))

    # ── CLAUSE (1) IS A BOUNDARY, NOT A GAP: the mechanism EXISTS and lifts when a model arrives ──
    #  The boundary was nearly recorded as permanent. `registry()` assigned every pulled model to the
    #  reflex tier by a hardcoded branch and gave `perception` an empty list BY CONSTRUCTION, so installing
    #  a vision model would have changed nothing while the prose read as conditional.
    import inspect as _insp35
    _reg_src = _insp35.getsource(_t35.registry)
    assert "vision_resources(_models)" in _reg_src, (
        "the perception tier's resources are not COMPUTED from the pulled models, so the §18 boundary is "
        "permanent in code while reading as conditional in prose - installing a model would change nothing")
    assert _t35.vision_resources(["llama2", "llava"])["matched"] == ["llava"], (
        "the computation that lifts the boundary does not recognise a vision family")
    #  and the owned reader clause (1) names is present and local-first
    _av_src = (_pl35.Path(__file__).resolve().parents[1]
               / "agentic_core/avatars/api.py").read_text(encoding="utf-8")
    assert "async def _ollama_vision" in _av_src, (
        "the OWNED vision reader is gone, so clause (1) has no mechanism to lift to")
    assert "never fabricates image content" in _av_src, (
        "the owned reader no longer records that it falls back honestly rather than fabricating")


def test_w598_p326_an_entity_records_its_lineage_or_says_it_has_none(client):
    """P3.26 clause (1) — a lineage written by WHATEVER creates an entity, and three states not two.

    Five of P3.26's clauses are claims ABOUT a lineage — mitosis creating a subsidiary that inherits its
    parent's constitution, apoptosis returning what a retired entity held, the never-auto-retire set
    protecting the LAST entity in its realm × domain. None can even be stated while no entity records a
    parent, which is why this clause is the item's precondition.

    MEASURED BEFORE THIS ROUND: no parent_vsb, parent_id or lineage field existed anywhere on an entity.
    And there are FIVE creation paths, not the three a grep of the request models suggested — the two in
    synthesis_studio.py were missed by exactly the mistake this project recorded as "grep the call, not the
    method name". Had this been built against three, two paths would have recorded nothing.
    """
    from agentic_core.economy import living_vsbs as _lv598

    # ── THE RESOLVER HAS THREE STATES, AND THE MIDDLE ONE IS NOT A NULL ─────────────────────────
    _none = _lv598.resolve_parent("")
    assert _none["state"] == _lv598.NO_PARENT and _none["parent_vsb"] is None, _none
    assert "has NONE" in _none["basis"] and "not a field somebody forgot" in _none["basis"], (
        "a parentless entity's basis does not SAY it has no parent, so a null is left to speak for itself "
        "- which the row forbids in as many words", _none["basis"])
    _bad = _lv598.resolve_parent("vsb-does-not-exist-598")
    assert _bad["state"] == _lv598.PARENT_UNRESOLVED and _bad["parent_vsb"] is None, _bad
    assert "vsb-does-not-exist-598" in _bad["basis"], (
        "the unresolved basis does not name the id, so a caller cannot see what failed", _bad["basis"])
    #  the three states must be DISTINCT values, or two of them collapse at every reader
    assert len({_lv598.NO_PARENT, _lv598.PARENT_RESOLVED, _lv598.PARENT_UNRESOLVED}) == 3, (
        "two lineage states share a value, so no reader can tell them apart")

    # ── P3.2 clause (1) — ABSENT MEANS ON, which nothing asserted until a blind proved it ───────
    #  Every entity already on the roster predates these fields, so a default of False would silently stop
    #  the organism tending ALL of them — a regression delivered as a feature. A blind flipping the default
    #  to False stayed GREEN, because the lineage legs below never touched the tending flags: the property
    #  I was most careful about was the one with no assertion behind it.
    _legacy = _lv598.tending({})
    assert _legacy["flags"] == {"auto_economy": True, "auto_compliance": True}, (
        "a record carrying NEITHER flag reads as not-tended, so adding these fields silently stops the "
        "organism tending every entity registered before they existed", _legacy["flags"])
    assert _legacy["absent"] == ["auto_economy", "auto_compliance"] and _legacy["stated"] == [], (
        "a legacy record does not report its flags as ABSENT, so 'on because it says so' and 'on because "
        "nothing says otherwise' are indistinguishable", _legacy)
    assert "read as ON" in _legacy["basis"], _legacy["basis"]
    #  and an explicit False is still respected — the default must not override a stated value
    assert _lv598.tending({"auto_economy": False})["flags"]["auto_economy"] is False, (
        "an entity that explicitly switched tending OFF is tended anyway")

    # ── A PARENTLESS CREATION SAYS SO, READ BACK FROM THE ROSTER ────────────────────────────────
    #  /api/v1/genesis/establish, NOT /api/v1/vsb/spawn: spawn is SSE-only, so .json() on it would fail on
    #  the content type rather than on the property, and a leg that errors for the wrong reason proves
    #  nothing. establish is a blocking JSON route and returns vsb_id at the top level.
    _r1 = client.post("/api/v1/genesis/establish",
                      json={"problem": "W598 a root entity", "name": "W598 Root",
                            "domain": "enterprise", "realm": "enterprise"})
    assert _r1.status_code == 200, (_r1.status_code, _r1.text[:200])
    _id1 = _r1.json().get("vsb_id")
    assert _id1, ("the establish response does not report the entity's id", str(_r1.json())[:200])
    #  FROM THE STORE, not from the response: a response can claim anything
    _rec1 = _lv598.roster().get(_id1) if hasattr(_lv598, "roster") else _lv598._load().get(_id1)
    assert _rec1 is not None, ("the entity is not on the living roster at all", _id1)
    assert _rec1["parent_vsb"] is None, (
        "a founder-established entity records a parent it does not have", _rec1.get("parent_vsb"))
    assert _rec1["lineage_state"] == _lv598.NO_PARENT, _rec1.get("lineage_state")
    assert "has NONE" in _rec1["lineage_basis"], (
        "the stored record carries a null parent with no statement beside it, so a reader cannot tell "
        "'no parent' from 'nobody recorded one'", _rec1.get("lineage_basis"))

    # ── A CREATION NAMING A RESOLVABLE PARENT RECORDS IT, READ BACK FROM THE ROSTER ─────────────
    _r2 = client.post("/api/v1/genesis/establish",
                      json={"problem": "W598 a child entity", "name": "W598 Child",
                            "domain": "enterprise", "realm": "enterprise", "parent_vsb": _id1})
    assert _r2.status_code == 200, (_r2.status_code, _r2.text[:200])
    _id2 = _r2.json().get("vsb_id")
    _rec2 = (_lv598.roster() if hasattr(_lv598, "roster") else _lv598._load()).get(_id2)
    assert _rec2["parent_vsb"] == _id1, (
        "the parent was stated at creation and is not on the record, so whatever creates an entity does "
        "NOT write its lineage", _rec2.get("parent_vsb"), _id1)
    assert _rec2["lineage_state"] == _lv598.PARENT_RESOLVED, _rec2.get("lineage_state")
    assert _id1 in _rec2["lineage_basis"], _rec2.get("lineage_basis")

    # ── THE GENERATION, which is what makes P3.2 clause (5) drivable at all ─────────────────────
    #  Measured W598: no evolutionary generation counter existed anywhere - every `generation` in the live
    #  tree was TEXT generation - so P3.2's clause "the living-plan pillar is re-scored ONLY when an
    #  instance has evolved >= 1 generation" had no field to drive. Its own stated test is "a guard drives
    #  generation 0 and asserts NO re-score", and generation 0 did not exist. A generation is the DEPTH of
    #  the lineage chain this field creates, so it is written here with the parent.
    assert _rec1["lineage_generation"] == 0, (
        "a founder-established entity is not generation 0, so 'has evolved >= 1 generation' cannot be "
        "distinguished from 'has never evolved' - which is the whole of P3.2 clause (5)",
        _rec1.get("lineage_generation"))
    assert _rec2["lineage_generation"] == 1, (
        "a child's generation is not one deeper than its root parent's", _rec2.get("lineage_generation"),
        _rec1.get("lineage_generation"))
    #  A GRANDCHILD, so the depth is proven to ACCUMULATE rather than merely to be set once
    _r4 = client.post("/api/v1/genesis/establish",
                      json={"problem": "W598 a grandchild entity", "name": "W598 Grandchild",
                            "domain": "enterprise", "realm": "enterprise", "parent_vsb": _id2})
    assert _r4.status_code == 200, (_r4.status_code, _r4.text[:160])
    _rec4 = (_lv598.roster() if hasattr(_lv598, "roster") else _lv598._load()).get(_r4.json()["vsb_id"])
    assert _rec4["lineage_generation"] == 2, (
        "the generation does not accumulate down the chain, so it records whether an entity has a parent "
        "rather than how deep it sits - and a depth that never exceeds 1 cannot express evolution",
        _rec4.get("lineage_generation"))
    #  AND AN UNRESOLVED PARENT LEAVES IT UNKNOWN, NOT ZERO. Zero asserts the entity is a root, which is a
    #  claim about its lineage rather than an absence of one - the three-state rule on a number.
    _unres = _lv598.resolve_parent("vsb-never-existed-598")
    assert _unres["lineage_generation"] is None, (
        "an unresolvable parent yields a generation rather than None; 0 in particular would assert the "
        "entity is a ROOT, which is the opposite of 'its depth is unknown'", _unres.get("lineage_generation"))

    # ── AN UNRESOLVABLE PARENT IS REFUSED, AND REFUSED THROUGH THE ROUTE ───────────────────────
    #  DRIVEN OVER HTTP ON PURPOSE. enrich_vsb_entity calls register inside `except Exception: pass`
    #  because enrichment must never block generation, so a refusal raised in the writer would be
    #  SWALLOWED and the entity created parentless in silence. Calling resolve_parent directly would pass
    #  while the live path did the wrong thing - a test proving nothing. So the refusal must be a 4xx a
    #  caller actually receives.
    #  BOTH A JSON ROUTE AND AN SSE ROUTE. The SSE case is the one that looks done while being wrong:
    #  /api/v1/vsb/spawn returns a StreamingResponse, so by the time its inner _stream() runs the status
    #  200 has already been sent and an HTTPException raised there CANNOT become a 409. The check must sit
    #  in the outer handler, before StreamingResponse is constructed. A guard that drove only the blocking
    #  route would certify a streaming path that silently creates the entity parentless.
    for _path598, _body598 in (
            ("/api/v1/genesis/establish",
             {"problem": "W598 orphan claim", "name": "W598 Orphan", "domain": "enterprise",
              "parent_vsb": "vsb-never-existed-598"}),
            ("/api/v1/vsb/spawn",
             {"challenge": "W598 orphan claim stream", "name": "W598 Orphan Stream",
              "domain": "enterprise", "scope": "build", "parent_vsb": "vsb-never-existed-598"})):
        _r3 = client.post(_path598, json=_body598)
        assert _r3.status_code in (400, 404, 409), (
            f"{_path598} created an entity claiming a parent that does not exist. Five of P3.26's clauses "
            f"reason over the lineage, so every one of them would be reasoning about a fiction. On a "
            f"STREAMING route a 200 here means the check sits inside the generator, after the status was "
            f"already sent", _path598, _r3.status_code, _r3.text[:200])
        assert "vsb-never-existed-598" in _r3.text, (
            f"{_path598}'s refusal does not name the id that failed to resolve, so a caller cannot "
            f"correct it", _r3.text[:200])
        #  and the detail must be renderable: W597 established that a dict detail put into React state
        #  throws, so a refusal a page cannot show is a refusal nobody reads
        try:
            _d598 = _r3.json().get("detail")
        except Exception:
            _d598 = None
        if isinstance(_d598, dict):
            assert "message" in _d598, (
                f"{_path598}'s refusal detail is a dict with no `message` key, so axiosDetail falls "
                f"through to JSON.stringify and the caller is shown a serialised dict", sorted(_d598))

    # ── COVERAGE: EVERY CREATION PATH PASSES IT, AND A SIXTH CANNOT APPEAR SILENTLY ─────────────
    #  This is a count, not a conscience. Four paths reach the roster through enrich_vsb_entity and one
    #  (genesis_establish) calls register directly; the legs above drive the spawn path end to end. If a
    #  SIXTH creation path is added and does not pass the parent through, the defect returns by a new
    #  route and nothing above would notice - so the caller set is pinned and a newcomer fails HERE, with
    #  an instruction, rather than silently recording no parent.
    import pathlib as _pl598
    import re as _re598
    _root598 = _pl598.Path(__file__).resolve().parents[1]
    _callers = {}
    for _py in sorted(_root598.rglob("agentic_core/**/*.py")) + sorted(_root598.rglob("products/**/*.py")):
        if "_archive" in _py.as_posix():
            continue
        _t = _py.read_text(encoding="utf-8")
        if "enrich_vsb_entity(" not in _t:
            continue
        for _m in _re598.finditer(r"enrich_vsb_entity\(", _t):
            _line = _t[:_m.start()].count("\n") + 1
            #  the definition itself is not a caller
            if _t[max(0, _m.start() - 4):_m.start()] == "def ":
                continue
            _callers[f"{_py.relative_to(_root598).as_posix()}:{_line}"] = _t[_m.start():_m.start() + 400]
    assert len(_callers) >= 4, (
        "fewer than four callers of enrich_vsb_entity were found, so this leg is not looking where the "
        "creation paths are and would pass on an empty tree", sorted(_callers))
    _missing = [k for k, v in _callers.items() if "parent_vsb" not in v]
    assert _missing == [], (
        "a creation path reaches enrich_vsb_entity without passing parent_vsb, so an entity born on that "
        "path records no lineage. This is the defect returning by a new route - the fix is one keyword at "
        "the call, not a change here", _missing)


def test_w600_p32_autonomy_that_starts_and_says_so(client):
    """P3.2 — all five clauses. Tending is per-entity, visible, and the beat reaches deliverables.

    MEASURED BEFORE BUILDING: `auto_economy` and `auto_compliance` existed ONLY as global heartbeat levers
    (organism/heartbeat.py), so "switches them on FOR THE NEW ENTITY" had nowhere to be recorded. They are
    now facts about an entity, and tending requires BOTH — the organism beating with its lever on, and the
    entity's own flag.
    """
    import pathlib as _pl600
    import re as _re600

    from agentic_core.economy import living_vsbs as _lv600

    def _nc600(src: str) -> str:
        """Source with its COMMENTS removed, for any presence assertion over a rendered file.

        W600: three legs of this very guard were vacuous because the comment explaining a render quoted
        the literal the assertion looked for, so a blind that deleted the RENDER left the COMMENT and the
        check passed over a blank page. That is the W495 trap mirrored - there a comment supplied a BANNED
        literal and matched its own guard; here it supplies a REQUIRED one and makes the guard unfailable.
        Only whole-line `//` comments and `/* */` blocks are stripped, so a `//` inside a string or a URL
        is left alone.
        """
        src = _re600.sub(r"/\*.*?\*/", "", src, flags=_re600.S)
        return "\n".join("" if line.lstrip().startswith("//") else line
                          for line in src.splitlines())

    # ── (1) THE FLAGS ARE ON THE ENTITY, READ BACK FROM THE STORE ───────────────────────────────
    #  From the STORE, not the establish response's own claim — the clause says so in as many words.
    _r = client.post("/api/v1/genesis/establish",
                     json={"problem": "W600 tending", "name": "W600 Tended", "domain": "enterprise"})
    assert _r.status_code == 200, (_r.status_code, _r.text[:160])
    _id = _r.json()["vsb_id"]
    _rec = _lv600._load().get(_id) or {}
    assert _rec.get("auto_economy") is True and _rec.get("auto_compliance") is True, (
        "/establish did not switch both flags on FOR THE NEW ENTITY", _id,
        {k: _rec.get(k) for k in ("auto_economy", "auto_compliance")})

    # ── ABSENT MEANS ON — the invariant a W599 blind proved had no assertion behind it ──────────
    #  Every entity already on the roster predates these fields. A default of False would silently stop the
    #  organism tending ALL of them: a regression delivered as a feature.
    _legacy = _lv600.tending({})
    assert _legacy["flags"] == {"auto_economy": True, "auto_compliance": True}, (
        "a record carrying NEITHER flag reads as not-tended", _legacy["flags"])
    assert _legacy["absent"] == ["auto_economy", "auto_compliance"], (
        "a legacy record does not report its flags as ABSENT, so 'on because it says so' and 'on because "
        "nothing says otherwise' are indistinguishable", _legacy)
    assert _lv600.tending({"auto_economy": False})["flags"]["auto_economy"] is False, (
        "an entity that explicitly switched tending OFF is tended anyway")

    # ── (2) A VISIBLE TENDING STATE, AND AN ENTITY WHOSE FLAGS ARE OFF DOES NOT SHOW IT ─────────
    #  `living_statement()` with no record keeps the GLOBAL sentence its four existing callers receive; a
    #  record makes the claim specific. Both halves are driven, because the clause's negative half is the
    #  one a global sentence can never express.
    _on = _lv600.living_statement({"auto_economy": True, "auto_compliance": True})
    _off = _lv600.living_statement({"auto_economy": False, "auto_compliance": True})
    assert "entity_tending" in _on and "entity_tending" in _off, (
        "living_statement ignores the record it was given, so it says the same thing about every entity",
        sorted(_on))
    assert _off["entity_tending"]["tended"] is False, (
        "an entity whose own flag is OFF is reported as tended", _off["entity_tending"])
    assert "do not allow it" in _off["entity_tending"]["basis"], _off["entity_tending"]["basis"]
    #  and the global sentence is UNCHANGED for a caller that passes nothing — four callers rely on it
    assert "entity_tending" not in _lv600.living_statement(), (
        "living_statement with no record now carries an entity claim, so its four existing callers say "
        "something about an entity they never named")

    # ── (3) THE COCKPIT RENDERS THE OPERATING STATE, and all four not-a-number states ───────────
    _ck = (_pl600.Path(__file__).resolve().parents[1]
           / "apps/workstation-superapp/src/pages/enterprise/VSBCockpit.tsx").read_text(encoding="utf-8")
    assert 'data-testid="cockpit-operating-state"' in _ck, (
        "the Cockpit renders no operating state, so the clause's own failure case - a page showing 0 cycles "
        "for an entity that has run - is not even reachable")
    #  BOTH counts, because operating_cycles counts only what THIS ROSTER ran (W491/FU-192): an entity
    #  cycled another way reads 0 there while ledger_cycles is non-zero, which IS the clause's failure case
    #  `ledger_cycles` appears FOUR times in this file, so a name-presence check survives deleting the
    #  render. Assert the rendered CONDITIONAL, which appears once and is what decides what a reader sees.
    _ck_nc = _nc600(_ck)
    assert "operating.operating_cycles" in _ck_nc, (
        "the roster's own cycle tally is not rendered", "operating_cycles" in _ck_nc)
    assert ("operating.ledger_cycles === null" in _ck_nc
            and "operating.ledger_cycles === undefined" in _ck_nc), (
        "the ledger count is rendered without distinguishing 'could not be read' from a number, so showing "
        "operating_cycles alone - or a bare 0 - produces the clause's own stated failure case for an entity "
        "cycled through any other path")
    assert "posted in its ledger" in _ck_nc, (
        "the ledger count itself is never printed, only its absence")
    assert 'data-testid="cockpit-cycle-counts-basis"' in _ck, (
        "the basis distinguishing the two counts is not rendered, so a reader cannot tell why they differ")
    #  a ledger that could not be READ is not zero
    #  THE GATE, not the field name: a JSX conditional names its field in BOTH the gate and the body, so
    #  {false && ...} leaves the name in place and a presence check cannot see the disabled gate.
    assert "{operating.ledger_cycles_unavailable && (" in _ck_nc, (
        "an unreadable ledger renders as 0, asserting 'no cycles posted' about a ledger nobody could open - "
        "or the gate that would say so has been disabled while its field name remains")
    assert "The ledger count is NOT zero" in _ck_nc, (
        "nothing states that an unreadable count is NOT zero, which is the whole distinction")
    #  never operated is a FACT, not a blank
    #  OVER THE COMMENT-STRIPPED SOURCE. The comment above this render quoted "NEVER OPERATED", so the
    #  blind that deleted the rendered string left the comment and this check passed over a blank cell.
    assert "NEVER OPERATED" in _ck_nc, (
        "an entity that has never operated renders a blank cell, which reads as a missing value rather "
        "than as a fact about the entity")
    assert 'data-testid="cockpit-tending-flags"' in _ck, "the governing flags are not rendered"

    # ── (4) THE BEAT REACHES DELIVERABLES, each carrying 'last screened' or saying it has none ──
    from agentic_core.organism import heartbeat as _hb600
    assert hasattr(_hb600, "screen_one_deliverable"), (
        "the compliance beat does not extend to deliverables at all")
    #  THE BEAT MUST CARRY IT, and this is the leg the first version of this guard lacked: it called the
    #  screener directly and asserted `hasattr`, so a blind that stopped the BEAT calling it stayed green.
    #  The clause says "its beat extends to living DELIVERABLES" - the subject is the beat, not the function.
    _prev_ac4 = _hb600.heartbeat.auto_compliance
    try:
        _hb600.heartbeat.auto_compliance = True
        _bd600 = client.post("/api/v1/heartbeat/beat")
        assert _bd600.status_code == 200, (_bd600.status_code, _bd600.text[:160])
        _lc600 = _hb600.heartbeat.last_compliance
        assert isinstance(_lc600, dict) and "deliverable_screen" in _lc600, (
            "a beat ran with auto_compliance ON and its compliance reading carries no deliverable_screen, "
            "so the beat does NOT extend to deliverables - whatever the screener does when called directly",
            type(_lc600).__name__, sorted(_lc600) if isinstance(_lc600, dict) else _lc600)
        #  THE READING, NOT THE KEY. The key is written unconditionally, so `"deliverable_screen" in _lc600`
        #  is true even when the screen never ran - a key present with a null value reports that the beat
        #  reached the screen when it did not. Presence is not an outcome.
        _ds600 = _lc600.get("deliverable_screen")
        assert isinstance(_ds600, dict) and _ds600.get("basis"), (
            "the beat's compliance reading carries a deliverable_screen key with no READING behind it, so a "
            "beat that never reached the screen is indistinguishable from one that screened something",
            _ds600)
    finally:
        _hb600.heartbeat.auto_compliance = _prev_ac4
    _dres = _hb600.screen_one_deliverable()
    #  THE CONTRACT, not a disjunction. The previous version of this leg accepted any ONE of three
    #  conditions, so it could not tell the four states apart - which is the distinction clause (4) exists
    #  for. The returns are shape-complete now (the pre-flight's [returns] leg found four different key sets
    #  in this one function), so the key set is assertable and the three states live in the VALUES.
    assert set(_dres) == {"screened", "id", "verdict", "deliverables", "could_not_run", "basis"}, (
        "screen_one_deliverable's returns are not shape-complete, so a caller indexing one of these keys "
        "raises on some paths and reads a value on others", sorted(_dres))
    assert _dres["basis"], "a reading with no basis says nothing about what happened"
    #  AN UNREADABLE STORE IS NOT AN EMPTY ONE: None means the count is unknown, 0 means there are none.
    #  Collapsing them would assert 'no deliverable exists' about a store nobody could open.
    assert _dres["deliverables"] is None or isinstance(_dres["deliverables"], int), _dres["deliverables"]
    #  FORCED: the unreadable-store branch, which nothing drove until now. `_load` is imported INSIDE
    #  screen_one_deliverable, so patching the module attribute is picked up on the next call.
    #  The distinction being held is the whole point of the three states: a store that could not be READ
    #  reports its count as UNKNOWN (None), never as 0, because 0 asserts "no deliverable exists" about a
    #  store nobody could open. Asserting `None or isinstance(int)` admitted BOTH and held neither.
    import agentic_core.api.deliverables as _dlvmod600
    _prev_load600 = _dlvmod600._load
    try:
        def _boom600():
            raise OSError("w600 forced: the deliverable store cannot be read")

        _dlvmod600._load = _boom600
        _unread600 = _hb600.screen_one_deliverable()
    finally:
        _dlvmod600._load = _prev_load600
    assert _unread600["could_not_run"], (
        "the store raised and the screen did not report that it could not run", _unread600)
    assert _unread600["deliverables"] is None, (
        "an UNREADABLE deliverable store reports its count as a number rather than as UNKNOWN - a 0 here "
        "asserts 'no deliverable exists' about a store nobody could open, which is the certifies-an-absence "
        "defect this reading exists to avoid", _unread600["deliverables"])
    assert _unread600["screened"] is None and _unread600["verdict"] is None, _unread600
    assert set(_unread600) == set(_dres), (
        "the unreadable-store path returns a different key set from the normal one", sorted(_unread600))
    if _dres["could_not_run"]:
        assert _dres["screened"] is None and _dres["verdict"] is None, (
            "the screen reports it COULD NOT RUN and also reports a verdict", _dres)
    elif _dres["deliverables"]:
        assert _dres["screened"] is not None, (
            "deliverables exist, nothing could-not-run, and yet none was screened - the three states are "
            "not exhaustive and a beat that did nothing looks like one that screened cleanly", _dres)
    else:
        assert _dres["deliverables"] == 0 and _dres["screened"] is None, (
            "the store was read and empty, so nothing may be reported as screened", _dres)
    #  and the CARD says it, on the surface a reader sees
    _dl = (_pl600.Path(__file__).resolve().parents[1]
           / "apps/workstation-superapp/src/pages/enterprise/VSBCockpit.tsx").read_text(encoding="utf-8")
    #  COMMENT-STRIPPED for the same reason: my own comment explaining the four states quoted
    #  "not screened yet", so the blind that emptied the rendered string left the comment behind.
    _dl_nc = _nc600(_dl)
    assert "not screened yet" in _dl_nc, (
        "a deliverable with no screening renders a blank rather than saying it has none - the clause's own "
        "words are 'never a blank'")
    assert "That is not a clean verdict." in _dl_nc, (
        "the card says a deliverable is unscreened without saying that is NOT a clean verdict, which is the "
        "inference a reader would otherwise draw")
    assert "COULD NOT BE SCREENED" in _dl_nc, (
        "a deliverable whose screen FAILED is indistinguishable from one the beat has not reached yet")

    # ── (4b) THE STEP'S OWN FAILURE IS OBSERVABLE (FU-461's mechanism, one site) ─────────────────
    #  Clause (4)'s new beat step runs INSIDE the compliance handler at heartbeat.py:471, which swallowed
    #  its exception with a bare `pass`. With that swallow in place the clause's delivery is UNOBSERVABLE:
    #  the screen raising and the screen having nothing to do are the same observable, because both append
    #  no action and leave no trace. An item cannot close on a bar whose delivery is invisible.
    from agentic_core.organism import heartbeat as _hbmod600
    #  THE MODULE ATTRIBUTE, not a bound copy: the route reads `_hb_mod.heartbeat` for exactly this reason
    #  (W579/FU-359), and driving a copy would exercise a different object than the surface does.
    _inst600 = _hbmod600.heartbeat
    _prev_ac600 = _inst600.auto_compliance
    try:
        _inst600.auto_compliance = True

        def _raise600():
            raise RuntimeError("w600 forced compliance failure")

        _inst600._compliance_beat = _raise600
        _b600 = client.post("/api/v1/heartbeat/beat")
        assert _b600.status_code == 200, (_b600.status_code, _b600.text[:160])
        _rec600 = _b600.json()
        _sf = _rec600.get("steps_failed") or {}
        assert "compliance_rescreen" in _sf, (
            "the compliance step RAISED and the beat recorded nothing about it, so a step that could not "
            "run is still indistinguishable from a step with nothing due - and clause (4)'s deliverable "
            "screen runs inside this very handler", _sf, _rec600.get("actions"))
        assert "w600 forced compliance failure" in str(_sf["compliance_rescreen"]), (
            "the recorded failure does not carry the real error, so a reader learns a step failed but not "
            "why", _sf["compliance_rescreen"])
        #  NOT CLAIMED AS AN ACTION. W589's rule, kept: an action is something the beat DID, and claiming
        #  one for a failure would be the opposite defect.
        assert "compliance_rescreen" not in (_rec600.get("actions") or []), (
            "the beat claimed compliance_rescreen as an ACTION although the step failed",
            _rec600.get("actions"))
        #  CLEARED on the next beat, or a failure outlives the beat that had it and every later beat reads
        #  as broken - the stale-record defect W589's own cadence comment warns about.
        _inst600.__dict__.pop("_compliance_beat", None)
        _b2600 = client.post("/api/v1/heartbeat/beat")
        _rec2600 = _b2600.json()
        assert "compliance_rescreen" not in (_rec2600.get("steps_failed") or {}), (
            "a failure from an EARLIER beat is reported as a failure of this one, so the record never "
            "clears", _rec2600.get("steps_failed"))
        #  AND AN EMPTY RECORD MUST NOT READ AS "NOTHING FAILED" while eleven swallows remain unconverted:
        #  a screen may refuse, never clear.
        #  W611 (FU-461) — every beat step is converted now, so the basis may say what an empty dict means;
        #  before, it had to warn that eleven handlers still swallowed theirs
        assert "EMPTY steps_failed means no step raised" in (_rec2600.get("steps_failed_basis") or ""), (
            "the basis does not say what an empty steps_failed means", _rec2600.get("steps_failed_basis"))
    finally:
        _inst600.auto_compliance = _prev_ac600
        _inst600.__dict__.pop("_compliance_beat", None)

    # ── LINEAGE DEPTH (P3.26 clause (1)) — AND THIS IS *NOT* P3.2 CLAUSE (5) ────────────────────
    #  P3.2 clause (5) is NOT MET and this guard does not claim it. The clause asks that a per-instance
    #  LIVING-PLAN PILLAR be re-scored only when an instance has evolved >= 1 generation, driven at
    #  generation 0 and asserting NO re-score. Measured W600: no per-instance pillar re-score exists
    #  anywhere in agentic_core/ — every `pillar` is platform-level (api/living_plan.py, api/cognition.py,
    #  api/integration_surface.py, api/transformation.py, api/v138/ceo.py). A "no re-score at generation 0"
    #  assertion would therefore be vacuously true at EVERY generation: green because red is unreachable.
    #
    #  AND `generation` MEANS TWO DIFFERENT THINGS IN TWO STORES, which is the trap this block now guards:
    #    · `vsb["generation"]` (api/vsb.py:2914 — the ONLY writer, inside the evolution-APPLY path after
    #      Owner approval; W493 exists to stop a FILING cycle advancing it) = APPLIED EVOLUTIONS. That is
    #      the measure clause (5) means.
    #    · the living roster's `generation` (W599, below) = LINEAGE DEPTH from a parent.
    #  A child established from a parent has evolved ZERO times and has lineage depth 1. Reading the
    #  lineage field as the evolution count would re-score the pillar for an entity that never evolved —
    #  precisely the defect clause (5) names. My own first version of this block did exactly that.
    assert _rec.get("lineage_generation") == 0, (
        "a founder-established entity is not lineage generation 0", _rec.get("lineage_generation"))
    _child = client.post("/api/v1/genesis/establish",
                         json={"problem": "W600 evolved", "name": "W600 Child",
                               "domain": "enterprise", "parent_vsb": _id})
    assert _child.status_code == 200, (_child.status_code, _child.text[:160])
    _cid600 = _child.json()["vsb_id"]
    _crec = _lv600._load().get(_cid600) or {}
    assert _crec.get("lineage_generation") == 1, (
        "a child is not one lineage generation deeper, so no lineage can be read from the roster",
        _crec.get("lineage_generation"))
    #  THE DISTINCTION, ASSERTED so nobody repeats the misreading: this child is lineage depth 1 and has
    #  evolved NOT AT ALL. If these two ever read the same, one of them has taken the other's meaning.
    #  THE ROSTER HALF FIRST, because it does not depend on the VSB store holding a record and so cannot go
    #  vacuous: the field must SAY it is lineage.
    assert "lineage" in str(_crec.get("lineage_basis") or "").lower(), (
        "the roster's generation carries no basis saying it is LINEAGE DEPTH, so a reader cannot tell it "
        "from vsb['generation'], which counts applied evolutions", _crec.get("lineage_basis"))
    #  AND THE CROSS-STORE HALF, which is only assertable when the VSB store actually holds this entity.
    #  Reported either way rather than passing silently on an absent record - an assertion that cannot run
    #  is not an assertion that passed.
    from agentic_core.api.vsb import _load_vsb as _lvsb600
    _cv600 = _lvsb600(_cid600) or {}
    if _cv600:
        assert int(_cv600.get("generation", 0)) == 0, (
            "a newly established child reports APPLIED EVOLUTIONS > 0 - it has evolved nothing, so either "
            "the evolution counter advanced without an approved apply (the W493 defect) or the lineage "
            "field has been read as the evolution count (the P3.2 clause (5) defect)",
            _cv600.get("generation"), _crec.get("lineage_generation"))
    else:
        #  not a failure and not a pass: this entity is on the living roster and not in the VSB store, so
        #  the two generations cannot be compared here. Said out loud so a later reader does not take this
        #  leg's silence for agreement between the stores.
        assert _crec, "the child is in neither store, so nothing about its lineage was recorded at all"


def test_w600_p311_the_qep_vsb_has_an_economic_model_that_is_its_own(client):
    """P3.11 — A.8's Waqf/Trust instance, not the generic template, with its three limits enforced.

    A.8's own closing line was the item: "Status: unrealised. No QEP VSB exists; §12's entities carry the
    generic template." Measured W598: 0 entities mentioned QEP, 9 templates, no qep_waqf_trust.

    WHAT A.8 STATES AND IS THEREFORE NOT A ROUND'S TO ADJUST: no owner profit (100% donation and
    waqf-backed) and a surplus cap of 5% with reinvestment. The other three proportions are a DEFAULT inside
    those constraints and the template says so in its own description — presenting them as the Owner's
    figures would be the fabrication this plan exists to prevent.
    """
    import pathlib as _pl600

    from agentic_core.economy import qep_pricing as _qp
    from agentic_core.economy.entities import ENTITY_TEMPLATES as _ET, get_template as _gt

    # ── (1a) THE TEMPLATE EXISTS. A template never added is how this clause fails most quietly ──
    #  `get_template` falls back to the DEFAULT for an unknown type, so a missing template does not raise:
    #  it silently hands back the generic waterfall. This leg is not in the clause and is the reason the
    #  clause's own wording is about PROPORTIONS.
    assert "qep_waqf_trust" in _ET, (
        "the QEP template is not registered, so get_template() silently returns the GENERIC template for it "
        "- the entity would be established, registered, report its own entity_type, and carry the waterfall "
        "A.8 contradicts", sorted(_ET))

    # ── (1b) ITS PROPORTIONS DIFFER FROM THE DEFAULT, read from the template not the type string ─
    _qep, _default = _gt("qep_waqf_trust"), _gt("waqf_ltd_hybrid")
    assert _qep["waterfall"] != _default["waterfall"], (
        "the QEP form inherited the generic waterfall, which is the defect this clause names",
        _qep["waterfall"])
    #  A.8's OWN FIGURES, asserted exactly: no owner profit, surplus capped at 5%
    assert _qep["waterfall"]["owner"] == 0.0, (
        "A.8 says 100% donation and waqf-backed, so an owner share contradicts it outright",
        _qep["waterfall"]["owner"])
    assert _qep["waterfall"]["self_investment"] == 0.05, (
        "A.8's surplus cap is 5% with reinvestment", _qep["waterfall"]["self_investment"])
    assert _qep["distributes_profit"] is False and _qep["capital_preserved"] is True, (
        "the form does not declare itself non-distributing and capital-preserving, so the EXISTING refusals "
        "at metabolism.py do not defend its owner share or its endowment", _qep)
    #  and the description says which figures are A.8's and which are a default — the honesty half
    assert "NOT ADJUSTABLE" in _qep["description"] and "DEFAULT INSIDE" in _qep["description"].upper(), (
        "the template does not distinguish A.8's stated figures from the default chosen inside its "
        "constraints, so my split reads as the Owner's model", _qep["description"][:200])

    # ── (2) THREE FIGURES, EACH DRIVEN WITH A BREACHING VALUE AND REFUSED BY NAME ───────────────
    _ok, _v = _qp.check_individual_price(5.0)
    assert not _ok and "free-at-point-of-use" in _v[0], (
        "an individual was charged and not refused; A.8 says FREE at the point of use, not reduced", _v)
    assert _qp.check_individual_price(0.0)[0] is True, "a free individual price was refused"

    _ok, _v = _qp.check_institutional_price(120.0, 100.0)
    assert not _ok and "cost-plus-5%" in _v[0] and "105" in _v[0], (
        "an institutional margin above cost+5% was accepted, or the refusal does not NAME the computed "
        "ceiling so the person who hit it cannot correct it", _v)
    assert _qp.check_institutional_price(105.0, 100.0)[0] is True, "the exact ceiling was refused"

    _ok, _v = _qp.check_surplus(10.0, 100.0)
    assert not _ok and "surplus cap" in _v[0], ("a surplus above 5% of revenue was accepted", _v)
    assert _qp.check_surplus(5.0, 100.0)[0] is True, "a surplus exactly at the cap was refused"
    #  zero revenue is NOT a breach: a period that earned nothing has no ratio to cap, and refusing it
    #  would refuse an entity for having earned nothing
    assert _qp.check_surplus(0.0, 0.0)[0] is True, (
        "an entity with no revenue was reported as breaching the surplus cap")
    #  AN UNASSESSED LIMIT IS NOT A CLEARED ONE
    _all = _qp.check_all(individual_price=0.0)
    assert _all["limits"]["institutional"]["ok"] is None, (
        "a limit whose inputs were never supplied is reported as PASSED, so an unchecked figure reads as a "
        "cleared one", _all["limits"]["institutional"])
    assert "not a cleared one" in _all["basis"], _all["basis"]

    # ── (3) TWO CHANNELS, AND THE BOOKS ARE WHAT THIS READS ────────────────────────────────────
    _est = client.post("/api/v1/genesis/establish",
                       json={"problem": "W600 the Quran Education Platform", "name": "W600 QEP",
                             "domain": "religion", "entity_type": "qep_waqf_trust"})
    assert _est.status_code == 200, (_est.status_code, _est.text[:160])
    _qid = _est.json()["vsb_id"]
    #  the ESTABLISHED entity carries the QEP waterfall, not the default — the silent-fallback check again,
    #  this time on a real entity rather than on the template
    _econ = (_est.json().get("established_vsb") or {}).get("economy") or _est.json().get("economy") or {}
    if _econ.get("waterfall"):
        assert _econ["waterfall"]["owner"] == 0.0, (
            "the established QEP entity carries an owner share, so it silently got the generic template",
            _econ["waterfall"])

    from agentic_core.economy.ledger import VirtualLedger
    _before = VirtualLedger(_qid).balances()
    for _path600, _amount in (("/api/v1/qep/contribute/zakat", 250.0),
                              ("/api/v1/qep/contribute/sponsor-a-student", 100.0)):
        _c = client.post(_path600, json={"vsb_id": _qid, "amount_wst": _amount})
        assert _c.status_code == 200, (_path600, _c.status_code, _c.text[:180])
    #  READ THE BOOKS BACK, not the channel's own response: a route returning {"recorded": true} while
    #  posting nothing is the W439 defect this platform already found once
    _after = VirtualLedger(_qid).balances()
    assert _after.get("revenue", 0.0) - _before.get("revenue", 0.0) == 350.0, (
        "a contribution through the channels did not reach the entity's BOOKS; the routes answered but the "
        "ledger did not move", _before.get("revenue"), _after.get("revenue"))
    #  the Zakat channel must NOT rule on anyone's zakat obligation — §11 forbids the platform ruling on a
    #  religious matter, and whether a donor's obligation is discharged is exactly such a ruling
    _z = client.post("/api/v1/qep/contribute/zakat", json={"vsb_id": _qid, "amount_wst": 1.0}).json()
    #  ASSERT THE REFUSAL, not the vocabulary. A word-level check on "designated" survives the §11 breach,
    #  because the basis's own closing sentence contains the word whichever way the ruling goes.
    assert "does NOT rule on whether" in str(_z), (
        "the Zakat channel does not REFUSE to rule on whether the donor's obligation is discharged - that is "
        "a religious ruling and §11 forbids this platform from making one", str(_z)[:260])
    assert "designated" in str(_z).lower() and "scholar" in str(_z).lower(), (
        "the Zakat channel does not distinguish a fund DESIGNATED Zakat-eligible from a discharged "
        "obligation, or does not refer the donor to their own scholar", str(_z)[:260])
    assert _z.get("rules_on") == [], (
        "the channel does not state that it rules on nothing", _z.get("rules_on"))
    #  Sponsor-a-Student names NO learner: no mechanism matches a contribution to an individual, so a
    #  named student would be a claim with nothing behind it
    _s = client.post("/api/v1/qep/contribute/sponsor-a-student",
                     json={"vsb_id": _qid, "amount_wst": 1.0}).json()
    assert _s.get("student_matched") is None and "NO LEARNER IS NAMED" in str(_s), (
        "the sponsorship channel claims a matched learner, and nothing in this platform matches one", _s)

    #  A CONTRIBUTION TO AN ENTITY THAT DOES NOT EXIST IS REFUSED, not recorded into fresh books.
    #  `read_strict` answers a missing ledger file with new empty books, so VirtualLedger(<anything>)
    #  succeeds - a channel without this check writes a ledger file for an id nobody established.
    _no = client.post("/api/v1/qep/contribute/zakat",
                      json={"vsb_id": "vsb-w600nosuch", "amount_wst": 5.0})
    assert _no.status_code == 404, (
        "a contribution was accepted for an entity that is on no roster, so the channel created books for "
        "an id nobody established", _no.status_code, _no.text[:200])
    #  and the path-shaped id is refused BY NAME: vsb_id is interpolated into a ledger path
    _bad = client.post("/api/v1/qep/contribute/zakat",
                       json={"vsb_id": "../../organism_config", "amount_wst": 5.0})
    assert _bad.status_code in (400, 422), (
        "a path segment in vsb_id was not refused, and it is interpolated into a ledger file path",
        _bad.status_code, _bad.text[:200])

    #  THE DECLARED-TAG CONSUMER, DRIVEN. Posting a tag outside POSTING_SOURCES makes
    #  postings_by_source() report it under `unknown_sources` with declared: False, and
    #  /api/v1/economy/board-pack surfaces that to a donor as "a source nobody recognises".
    _split = VirtualLedger(_qid).postings_by_source()
    _bysrc = {r["source"]: r for r in _split["by_source"]}
    for _tag in ("qep_zakat", "qep_sponsor_a_student"):
        assert _tag in _bysrc, (
            f"the channel did not tag its posting {_tag}, so the money is in the books with nothing saying "
            f"which channel brought it in", sorted(_bysrc))
        assert _bysrc[_tag]["declared"] is True, (
            f"{_tag} is emitted but NOT declared in POSTING_SOURCES, so a donor reading this entity's board "
            f"pack is told its own channel is a source nobody recognises", _split["unknown_sources"])
    assert [s for s in _split["unknown_sources"] if str(s).startswith("qep_")] == [], (
        "a qep_ channel tag is undeclared", _split["unknown_sources"])

    #  THE DONOR STATEMENT READS THE POSTINGS, NOT THE LEGACY ENTRIES. record() writes an entry carrying no
    #  source at all - the tag goes on the balanced posting - so a statement built from `entries` reports
    #  0.00 for every channel while the money sits in the books: silently empty, not honestly zero.
    _st = client.get(f"/api/v1/qep/contribute/statement/{_qid}")
    assert _st.status_code == 200, (_st.status_code, _st.text[:200])
    _sj = _st.json()
    assert _sj["contributions_by_channel_wst"].get("zakat") == 251.0, (
        "the donor statement does not report the Zakat channel's real total; a statement built from the "
        "legacy entries finds no source tag anywhere and reports zero",
        _sj["contributions_by_channel_wst"])
    assert _sj["contributions_by_channel_wst"].get("sponsor_a_student") == 101.0, (
        _sj["contributions_by_channel_wst"])
    #  WOULD-ALLOCATE IS NOT A RECORD OF DISTRIBUTIONS MADE, and says so
    assert "not a record of distributions made" in _sj["allocation_basis"], _sj["allocation_basis"]
    assert _sj["would_allocate_wst"]["owner"] == 0.0, (
        "the donor statement shows an owner allocation for a 100%-donation waqf form",
        _sj["would_allocate_wst"])
    #  and a silently-defaulted template is DISCLOSED rather than shown under the right name
    assert _sj["template_is_a_fallback"] is False, (
        "the entity's waterfall is the GENERIC template standing in for its own, and the statement would "
        "have shown the wrong figures under the right name", _sj["entity_type"], _sj["template_name"])

    # ── (4) THE EIGHT-ATTRIBUTE EXECUTIVE BOARD, read from the COMPOSITION ─────────────────────
    from agentic_core.api.board import board_for_owner as _bfo
    _rel = _bfo("default", "QEP", domain="religion")
    _exec = _rel.get("executive_board") or []
    assert len(_exec) == 8, (
        "the Religion-domain composition does not carry A.8's eight-pointed star", len(_exec))
    for _a in ("Al-ʿAzīz", "Al-Wadūd", "Al-ʿAlīm", "Al-Khāliq",
               "Al-ʿAdl", "Al-Ghaffār", "Al-Aḥad", "Al-Hādī"):
        assert any(_a in str(d.get("attribute")) for d in _exec), (
            f"the attribute {_a} is missing from the composed board", _a)
    #  AN ADDITIONAL TIER, NOT A REPLACEMENT — a replacement would pass a naive "are the eight present"
    #  check while deleting the governance tier other callers depend on
    assert _rel.get("chief") and _rel.get("directors"), (
        "the eight-attribute board REPLACED the standing chief and directors; A.8 lists it as an EXECUTIVE "
        "board, separately from oversight", sorted(_rel))
    #  and the names confer NO authority — recorded in the basis rather than left to be inferred
    assert "confer no authority" in (_rel.get("executive_board_basis") or ""), (
        "nothing records that the Divine Names title divisions and confer no authority on what a division "
        "produces", _rel.get("executive_board_basis"))
    #  another domain has NO executive board, and it is ABSENT rather than empty: an empty list would read
    #  as "this domain has an executive board with nobody on it"
    _ent = _bfo("default", "x", domain="enterprise")
    assert "executive_board" not in _ent, (
        "a non-Religion domain carries an executive_board key; empty is a different and false statement "
        "from absent", _ent.get("executive_board"))

    #  ── AND IT REACHES A REAL ENTITY. The legs above call board_for_owner DIRECTLY, which is exactly how
    #  this clause was BUILT BUT UNREACHABLE: `domain` was added with an empty default so no existing caller
    #  changed, and then not one of the three production callers passed a domain - so A.8's executive board
    #  was composed for nobody, including the Religion-domain entity it was written for. A composition no
    #  caller requests is not a composition. Found by the pre-flight's [keys] leg on this round's own work.
    #  Read off the ENTITY RECORD rather than from the function, because both call sites sit inside
    #  `except Exception: pass`: if the composition raised, the board would be silently ABSENT and a
    #  direct-function assertion would still pass.
    _rel_est = client.post("/api/v1/genesis/establish",
                           json={"problem": "W600 QEP board reach", "name": "W600 QEP Board",
                                 "domain": "religion", "entity_type": "qep_waqf_trust"})
    assert _rel_est.status_code == 200, (_rel_est.status_code, _rel_est.text[:160])
    _rel_id = _rel_est.json()["vsb_id"]
    from agentic_core.api.vsb import _load_vsb as _lvsb_b600
    _rel_rec = _lvsb_b600(_rel_id) or {}
    _rel_board = (_rel_rec.get("board") or {})
    if _rel_rec:
        assert _rel_board, (
            "an established entity carries NO board at all - both composition call sites sit inside "
            "except-pass, so a raising composition leaves the entity governance-orphaned in silence",
            sorted(_rel_rec)[:14])
        assert len(_rel_board.get("executive_board") or []) == 8, (
            "a RELIGION-domain entity established through /establish does not carry A.8's eight-attribute "
            "executive board, so the composition reaches no entity however correct the function is",
            len(_rel_board.get("executive_board") or []), sorted(_rel_board))
        assert _rel_board.get("chief") and _rel_board.get("directors"), (
            "the entity's standing board tier is gone", sorted(_rel_board))
    #  THE SECOND COMPOSITION SITE. `enrich_vsb_entity` is the shared enrichment path (four callers, all of
    #  which supply a domain - checked by reading each) and its board composition is a DIFFERENT line from
    #  /establish's. Driven directly rather than through a route because the site sits inside an SSE
    #  generator; what this holds is the PASS-THROUGH, which is the only link this round changed. It does not
    #  claim a route reaches it - the /establish leg above is what holds the genesis path.
    from agentic_core.api.vsb import enrich_vsb_entity as _enrich600
    _e600 = {"vsb_id": "vsb-w600enrich", "name": "W600 Enrich"}
    try:
        _enrich600(_e600, owner_id="default", problem="W600 enrich reach", domain="religion",
                   entity_type="qep_waqf_trust")
    except Exception as _een:            # enrichment is best-effort by design; the board leg still applies
        assert _e600.get("board"), (
            "enrich_vsb_entity raised before composing a board, so an entity enriched through the shared "
            "path is governance-orphaned", f"{type(_een).__name__}: {_een}")
    assert len(((_e600.get("board") or {}).get("executive_board")) or []) == 8, (
        "the shared enrichment path composes a board WITHOUT A8's executive tier for a religion-domain "
        "entity, so every entity created through it - rather than through /establish - misses it",
        sorted((_e600.get("board") or {})))
    _e600b = {"vsb_id": "vsb-w600enrich2", "name": "W600 Enrich Ent"}
    try:
        _enrich600(_e600b, owner_id="default", problem="W600 enrich ent", domain="enterprise")
    except Exception:
        pass
    if _e600b.get("board"):
        assert "executive_board" not in _e600b["board"], (
            "the shared path gives an enterprise entity an executive board, so the domain is not acting as "
            "a discriminator there", _e600b["board"].get("executive_board"))

    #  and an ENTERPRISE entity established the same way carries no executive board - absent, not empty
    _ent_est = client.post("/api/v1/genesis/establish",
                           json={"problem": "W600 enterprise board reach", "name": "W600 Ent Board",
                                 "domain": "enterprise"})
    assert _ent_est.status_code == 200, (_ent_est.status_code, _ent_est.text[:160])
    _ent_rec = _lvsb_b600(_ent_est.json()["vsb_id"]) or {}
    if _ent_rec.get("board"):
        assert "executive_board" not in _ent_rec["board"], (
            "an enterprise entity carries an executive_board; the domain is not reaching the composition "
            "as a DISCRIMINATOR - it is being applied to everything", _ent_rec["board"].get("executive_board"))

    # ── (5) VIRTUAL WST THROUGHOUT — no real-money rail is touched ──────────────────────────────
    _src600 = (_pl600.Path(__file__).resolve().parents[1]
               / "agentic_core/economy/qep_pricing.py").read_text(encoding="utf-8")
    assert "Virtual WST" in _src600 or "virtual WST" in _src600, (
        "the pricing module does not record that it is virtual WST only")
    assert "stripe" not in _src600.lower() and "real_money" not in _src600.lower(), (
        "the pricing module names a real-money rail")


def test_w601_p221_an_instrument_answers_in_one_shape(client):
    """P2.21 clause (2) — the same keys whatever the answer, with the three states in the VALUES.

    Driven on BOTH branches of all three, because a shape defect lives on the path less travelled: all three
    of these survived every previous round and were found only when a pre-flight leg counted key sets.
    """
    import asyncio as _aio601
    import importlib.util as _ilu601
    import json as _json601
    import pathlib as _pl601

    _root601 = _pl601.Path(__file__).resolve().parents[1]

    # ── FU-463 · _screen_candidate: the fault path and the normal path ──────────────────────────
    from agentic_core.api import compliance as _comp601
    from agentic_core.api.genesis import _screen_candidate as _sc601
    _ok601 = _sc601("a lawful plan to open a bakery on the high street")
    _prev_sc = _comp601.screen_compliance
    try:
        def _raise_sc(_t):
            raise RuntimeError("w601 forced screen fault")

        _comp601.screen_compliance = _raise_sc
        _bad601 = _sc601("anything")
    finally:
        _comp601.screen_compliance = _prev_sc
    assert set(_ok601) == set(_bad601), (
        "_screen_candidate answers with a DIFFERENT SHAPE depending on whether the screen faulted, so a "
        "caller indexing a coverage field gets undefined exactly when the screen could not read the subject",
        sorted(set(_ok601) ^ set(_bad601)))
    assert _bad601["screen_error"] and _ok601["screen_error"] is None, (
        "screen_error does not distinguish the two paths", _bad601.get("screen_error"),
        _ok601.get("screen_error"))
    #  THE THREE STATES: a screen that RAISED established no coverage, so `covered` is None - NOT [].
    #  [] asserts "no framework covered this subject", which a fault did not establish.
    assert _bad601["compliance_covered"] is None and _bad601["safety_covered"] is None, (
        "a faulted screen reports its coverage as an EMPTY LIST, which asserts that no framework covered "
        "the subject - a claim the fault did not establish", _bad601["compliance_covered"],
        _bad601["safety_covered"])
    assert isinstance(_ok601["compliance_covered"], list), (
        "the normal path does not report which frameworks read the subject", _ok601["compliance_covered"])
    #  and a fault must never disqualify a candidate for an infrastructure hiccup
    assert _bad601["disqualified"] is False, _bad601

    # ── FU-415 · the forecast: history walkable, and not ────────────────────────────────────────
    _spec601 = _ilu601.spec_from_file_location("_sf601", _root601 / "scripts/session_forecast.py")
    _sf601 = _ilu601.module_from_spec(_spec601)
    _spec601.loader.exec_module(_sf601)
    _full601 = _sf601.forecast_session(8.0)
    _sf601.round_durations = lambda since=460: {"assessable": False, "why": "w601 forced: no history"}
    _early601 = _sf601.forecast_session(8.0)
    assert set(_full601) == set(_early601), (
        "the forecast returns a different key set when the history cannot be walked, so an unmeasurable "
        "figure reads as a MISSING FIELD rather than as a figure it could not compute",
        sorted(set(_full601) ^ set(_early601)))
    assert _early601["projection"].get("unavailable"), _early601["projection"]
    #  THE LIST OF WHAT THE ARITHMETIC CANNOT KNOW must be present exactly when it cannot know anything.
    assert _early601["what_this_cannot_know"], (
        "the unmeasurable path drops the list of what the arithmetic cannot know - the one answer where it "
        "matters most")
    assert _early601["what_this_cannot_know"] == _full601["what_this_cannot_know"], (
        "the two paths carry DIFFERENT honest-limits lists, so one of them is a second copy that will drift")
    #  the nested dict is shape-complete too, and its uncomputable fields are None rather than 0
    _rbc_f, _rbc_e = _full601["round_boundaries_cost"], _early601["round_boundaries_cost"]
    assert isinstance(_rbc_e, dict) and set(_rbc_f) == set(_rbc_e), (
        "round_boundaries_cost changes shape with the answer, or is nulled whole - which discards the three "
        "fields that need no duration at all", type(_rbc_e).__name__,
        sorted(set(_rbc_f) ^ set(_rbc_e)) if isinstance(_rbc_e, dict) else None)
    assert _rbc_e["share_of_a_median_round"] is None, (
        "an unmeasurable share is reported as a number; a zero share would read as a suite that costs "
        "nothing per round", _rbc_e["share_of_a_median_round"])
    assert _rbc_e["suite_h_per_round"] and _rbc_e["suite_mode"], (
        "the fields that need NO duration were nulled along with the ones that do, so measurements that "
        "were available were thrown away", _rbc_e)
    assert "NOT MEASURED" in str(_rbc_e["basis"]), _rbc_e["basis"]

    # ── FU-446 · learn_teach_module: both roles, and NOT-APPLICABLE kept apart from NOT-RECORDED ─
    from agentic_core.reactor.religion.qep_flagship import QEPFlagshipService as _QFS601
    _svc601 = _QFS601()
    _L601 = _aio601.run(_svc601.learn_teach_module("Learner", "w601user"))
    _T601 = _aio601.run(_svc601.learn_teach_module("Teacher", "w601user"))
    assert set(_L601) == set(_T601), (
        "the two roles answer with different key sets and the only consumer does not branch on role, so it "
        "indexes whichever keys it was written against and gets undefined on the other",
        sorted(set(_L601) ^ set(_T601)))
    assert _L601["role"] == "Learner" and _T601["role"] == "Teacher", (
        "nothing in the answer says which branch produced it, so a reader cannot tell which nulls to expect")
    #  THE DISTINCTION THAT MATTERS: a null is either NOT APPLICABLE TO THIS ROLE or NOT RECORDED, and
    #  flattening them would be the same defect one layer down.
    assert "students" in _L601["not_applicable"] and "playlists" in _T601["not_applicable"], (
        "not_applicable does not name the other role's keys, so a null cannot be told from an unrecorded "
        "figure", _L601["not_applicable"], _T601["not_applicable"])
    assert "tutor_availability" not in _L601["not_applicable"], (
        "a Learner's tutor_availability is listed as NOT APPLICABLE when it is a figure this store does not "
        "record - no tutor registry exists. Those are different facts and the list must not merge them")
    assert "tutor_availability" in _T601["not_applicable"], _T601["not_applicable"]
    for _k601 in _L601["not_applicable"]:
        assert _L601[_k601] is None, (_k601, "named not-applicable and carrying a value")

    # ── FU-414 · the register is stored the way its own writer writes it ────────────────────────
    #  W588: the file was at indent=1 while BOTH writers emit indent=2, so the first CLI write of a round
    #  reformatted 7,708 lines and the round's real change arrived inside a 15,479-line rewrite no reader
    #  could review. Nothing asserted the two agreed; this is that assertion.
    _reg_raw601 = (_root601 / "docs/FOLLOWUPS.json").read_bytes()
    _reg601 = _json601.loads(_reg_raw601.decode("utf-8"))
    _emitted601 = (_json601.dumps(_reg601, indent=2, ensure_ascii=False) + "\n").encode("utf-8")
    assert _emitted601 == _reg_raw601, (
        "docs/FOLLOWUPS.json on disk is NOT byte-identical to what its own writers emit, so the next CLI "
        "write will reformat the whole file and bury the round's real register change inside an "
        "unreviewable whole-file diff",
        len(_reg_raw601), len(_emitted601))
    #  and the two writers must agree with each other, or the file can only match one of them
    for _w601 in ("agentic_core/plan_followups.py", "scripts/followups.py"):
        _src601 = (_root601 / _w601).read_text(encoding="utf-8")
        assert "indent=2, ensure_ascii=False" in _src601, (
            f"{_w601} no longer serialises the register the way this guard asserts the file is stored, so "
            f"one of the two writers has drifted from the other")


def test_w601_p221_no_instrument_moves_the_process_data_root():
    """P2.21 clause (3) — a measuring script and the conftest, each driven in a CHILD without isolation set.

    This cannot be asserted in-process. With DATA_DIR already set, the old `setdefault` was a no-op and the
    old code would have passed here — which is exactly why the defect survived every local run and only
    appeared on CI, where no DATA_DIR exists.
    """
    import json as _json613
    import os as _os613
    import pathlib as _pl613
    import subprocess as _sp613
    import sys as _sys613

    _root613 = _pl613.Path(__file__).resolve().parents[1]

    #  the child's environment is CI's: the isolation variables are REMOVED, not overridden
    _env613 = {k: v for k, v in _os613.environ.items()
               if k not in ("DATA_DIR", "WORKSTATION_DATA_DIR", "WORKSTATION_UEG_PATH",
                            "PROJECTS_DIR", "SYNTHESIS_OUTPUT_DIR", "PROPOSALS_DIR",
                            "LISTINGS_DIR", "AI_DISABLE_LOCAL")}
    _env613["PYTHONIOENCODING"] = "utf-8"

    # ── FU-413 · the measuring script must not move the process data root ───────────────────────
    _probe613 = (
        "import importlib.util, json, os, sys\n"
        "before = dict(os.environ)\n"
        "spec = importlib.util.spec_from_file_location('rf', r'{root}/scripts/readme_figures.py')\n"
        "rf = importlib.util.module_from_spec(spec); spec.loader.exec_module(rf)\n"
        "m = rf.measured()\n"
        "changed = sorted(k for k in set(before) | set(os.environ)\n"
        "                 if before.get(k) != os.environ.get(k))\n"
        "print(json.dumps({{'changed': changed, 'ops': m['ops'], 'paths': m['paths'],\n"
        "                  'app_imported': 'agentic_core.app_mvp' in sys.modules}}))\n"
    ).format(root=str(_root613).replace("\\", "/"))
    _p613 = _sp613.run([_sys613.executable, "-c", _probe613], cwd=str(_root613), env=_env613,
                       capture_output=True, text=True, errors="replace")
    assert _p613.returncode == 0, (
        "the measuring script could not be driven in a child", _p613.stderr[-500:])
    _out613 = None
    for _ln in reversed((_p613.stdout or "").strip().splitlines()):
        if _ln.startswith("{"):
            _out613 = _json613.loads(_ln)
            break
    assert _out613, ("the probe printed no reading", (_p613.stdout or "")[-300:])
    #  THE PROPERTY: measuring changes NO environment variable in the calling process.
    assert _out613["changed"] == [], (
        "the measuring script moved process-global state: a test loads this module in-process, so every "
        "test after it in that xdist worker reads a different data root than it was given. CI sets no "
        "DATA_DIR, which is why this is invisible locally", _out613["changed"])
    #  and it must not pull the app into the caller either — that import is what freezes the paths
    assert _out613["app_imported"] is False, (
        "the measurement imported the app into the CALLING process, so the app's module-level config froze "
        "against a throwaway store for everything that follows. Restoring the environment afterwards would "
        "not undo this, which is why the measurement belongs in a child")
    #  THE MEASUREMENT STILL HAPPENED — a zero would mean the child silently failed and the figure is a lie
    assert _out613["ops"] > 100 and _out613["paths"] > 100, (
        "the figures came back implausibly small, so the child did not really boot the app and the number "
        "is not a measurement", _out613["ops"], _out613["paths"])

    #  ── AND A FAILING CHILD MUST REFUSE, NOT ANSWER ZERO. Driven by FORCING the branch, because the child
    #  succeeds in a healthy tree and a blind inside that branch would otherwise never execute. The stake is
    #  concrete: if a failed child returned zeros, `readme_figures --fix` would rewrite the README to claim
    #  the platform exposes 0 API operations and `--check` would then agree with it.
    import importlib.util as _ilu613
    _spec613 = _ilu613.spec_from_file_location("_rf613", _root613 / "scripts/readme_figures.py")
    _rf613 = _ilu613.module_from_spec(_spec613)
    _spec613.loader.exec_module(_rf613)

    class _FailedProc613:
        returncode = 9
        stdout = ""
        stderr = "w601 forced: the child could not start"

    _prev_run613 = _rf613.subprocess.run
    try:
        _rf613.subprocess.run = lambda *a, **k: _FailedProc613()
        _raised613 = None
        try:
            _rf613.api_figures()
        except Exception as _e613:
            _raised613 = _e613
    finally:
        _rf613.subprocess.run = _prev_run613
    assert _raised613 is not None, (
        "a child that FAILED produced a figure instead of refusing. A count of zero API operations is not a "
        "measurement of a booted app, and `--fix` would write it into the README as one")
    assert "not reported as zero" in str(_raised613) or "could not be measured" in str(_raised613), (
        "the refusal does not say what went wrong, so a reader cannot tell a broken measurement from a real "
        "one", str(_raised613)[:200])

    # ── FU-460 · conftest must HONOUR an explicit path, not overwrite it ───────────────────────
    _scratch613 = str(_pl613.Path(_os613.environ.get("TEMP", "/tmp")) / "w601_iso_probe").replace("\\", "/")
    _env2613 = dict(_env613)
    _env2613.update({"PROJECTS_DIR": _scratch613 + "/projects",
                     "SYNTHESIS_OUTPUT_DIR": _scratch613 + "/synth",
                     "PROPOSALS_DIR": _scratch613 + "/prop",
                     "DATA_DIR": _scratch613 + "/data",
                     "WORKSTATION_DATA_DIR": _scratch613 + "/data"})
    _probe2613 = (
        "import importlib.util, json, os\n"
        "spec = importlib.util.spec_from_file_location('cft', r'{root}/integration_tests/conftest.py')\n"
        "spec.loader.exec_module(importlib.util.module_from_spec(spec))\n"
        "print(json.dumps({{k: os.environ.get(k) for k in\n"
        "                  ('PROJECTS_DIR','SYNTHESIS_OUTPUT_DIR','PROPOSALS_DIR','DATA_DIR')}}))\n"
    ).format(root=str(_root613).replace("\\", "/"))
    _q613 = _sp613.run([_sys613.executable, "-c", _probe2613], cwd=str(_root613), env=_env2613,
                       capture_output=True, text=True, errors="replace")
    assert _q613.returncode == 0, ("conftest could not be imported in a child", _q613.stderr[-500:])
    _got613 = None
    for _ln in reversed((_q613.stdout or "").strip().splitlines()):
        if _ln.startswith("{"):
            _got613 = _json613.loads(_ln)
            break
    assert _got613, ((_q613.stdout or "")[-300:])
    for _k613 in ("PROJECTS_DIR", "SYNTHESIS_OUTPUT_DIR", "PROPOSALS_DIR", "DATA_DIR"):
        assert _scratch613 in str(_got613[_k613] or ""), (
            f"conftest OVERWROTE an explicit {_k613}, so the isolated-run recipe this project uses for every "
            f"verification run does not isolate it and the suite writes into the repository's own data/. "
            f"The per-worker __gw0..__gw7 directories left behind are the symptom of this, not a separate "
            f"defect", _k613, _got613[_k613])
    #  AND THE DEFAULT MUST STILL APPLY when nothing is given, or this fix breaks every plain run
    _probe3613 = _probe2613
    _q3613 = _sp613.run([_sys613.executable, "-c", _probe3613], cwd=str(_root613), env=_env613,
                        capture_output=True, text=True, errors="replace")
    assert _q3613.returncode == 0, _q3613.stderr[-400:]
    _def613 = None
    for _ln in reversed((_q3613.stdout or "").strip().splitlines()):
        if _ln.startswith("{"):
            _def613 = _json613.loads(_ln)
            break
    assert _def613 and "test_projects" in str(_def613["PROJECTS_DIR"]), (
        "with nothing set, conftest no longer falls back to its own test directory - so making the explicit "
        "value win has broken the default every plain `pytest` run depends on", _def613)


def test_w602_p221_the_preflight_computes_which_guards_a_register_change_invalidates(tmp_path):
    """P2.21 clause (1) — [regchange] names the guards it COMPUTES, not four it remembers.

    W592's register change broke seven guards, none in the hardcoded four. W601 closed six rows and the leg
    said `ok`, because "a row was closed" was not among its hardcoded kinds. Both halves were fixed lists.
    """
    import importlib.util as _ilu602
    import pathlib as _pl602

    _root602 = _pl602.Path(__file__).resolve().parents[1]
    _spec602 = _ilu602.spec_from_file_location("_scd602", _root602 / "scripts/selfcheck_diff.py")
    _scd602 = _ilu602.module_from_spec(_spec602)
    _spec602.loader.exec_module(_scd602)

    # ── the list is COMPUTED: a planted test the old four could never have named is found ────────
    _planted602 = tmp_path / "test_planted_602.py"
    _planted602.write_text(
        "def test_zzz_planted_reads_the_register_602(client):\n"
        "    import json, pathlib\n"
        "    reg = json.loads(pathlib.Path('docs/FOLLOWUPS.json').read_text())\n"
        "    assert reg\n"
        "\n"
        "def test_zzz_planted_reads_nothing_602(client):\n"
        "    assert 1 + 1 == 2\n",
        encoding="utf-8")
    _found602 = _scd602._register_reading_guards(_planted602)
    assert "test_zzz_planted_reads_the_register_602" in _found602, (
        "the pre-flight does not COMPUTE which guards read the register - a test planted in a scratch suite "
        "that reads FOLLOWUPS.json was not named, so the leg is recalling a list rather than scanning",
        _found602)
    assert "test_zzz_planted_reads_nothing_602" not in _found602, (
        "a test that reads neither the register nor the plan was named, so the scan is not discriminating "
        "and would tell every round to run every guard", _found602)

    # ── against the REAL suite: a guard the hardcoded four omitted is named, and the count cannot shrink ─
    _real602 = _scd602._register_reading_guards()
    assert "test_w486_the_plan_says_where_it_is_going_or_says_it_cannot" in _real602, (
        "test_w486 reads the real plan and the live register and was NOT in the hardcoded four; if the "
        "computed list does not name it, the computation has regressed to the list", len(_real602))
    assert "test_w469_the_plan_carries_every_followup_and_keeps_itself_current" in _real602, _real602[:8]
    assert len(_real602) >= 20, (
        "the computed list is short enough to be a hand-written one; the measurement at W602 found 35 "
        "register-reading guards and a count this low means the scan is no longer scanning", len(_real602))
    #  this very test reads the register through the module it loads, so it must name itself - a scan that
    #  cannot see the file it lives in is reading something other than the suite
    assert "test_w602_p221_the_preflight_computes_which_guards_a_register_change_invalidates" in _real602, (
        "the scan did not find THIS test, which loads selfcheck_diff and names FOLLOWUPS.json in its own "
        "body - so it is not scanning the live suite", len(_real602))

    # ── the KINDS gate: a diff that ONLY CLOSES A ROW must trigger the leg ──────────────────────
    #  W601's exact change. The old leg returned ok on it because closing was not a listed kind.
    _prev_ar602 = _scd602.added_removed
    try:
        def _fake_added_removed(rev, f):
            if f.endswith("docs/FOLLOWUPS.json"):
                return ([(1, '      "status": "closed",'), (2, '      "closed_by": "W601",')], [])
            return ([], [])

        _scd602.added_removed = _fake_added_removed
        _leads602 = _scd602.check_register_change("HEAD", ["docs/FOLLOWUPS.json"])
    finally:
        _scd602.added_removed = _prev_ar602
    assert _leads602, (
        "a diff that only CLOSES a row produced no lead - the leg still gates on a fixed list of kinds, and "
        "closing a row is the most common register change there is")
    assert any("CLOSED" in ln for ln in _leads602), (
        "the leg fired but did not say WHY: 'a row was closed' is not among the kinds it reports",
        _leads602[:4])
    assert any(ln.strip().startswith("-k '") for ln in _leads602), (
        "the leg names no -k expression, so a round cannot run the guards it was just told about",
        _leads602[:3])
    #  THE EMITTED LINE, not the helper: a round reads the -k the leg PRINTS, so that is what must carry the
    #  computed names. Asserting the helper alone stayed green when the call site was swapped back to the
    #  old four-name list - the helper was fine and nothing used it.
    _k602 = next(ln for ln in _leads602 if ln.strip().startswith("-k '"))
    assert "test_w486_the_plan_says_where_it_is_going_or_says_it_cannot" in _k602, (
        "the -k line the leg EMITS does not name test_w486 - the computed list exists but the leg is not "
        "printing it, so a round still runs the four it used to", _k602[:160])
    assert _k602.count(" or ") >= 19, (
        "the emitted -k names too few guards to be the computed list", _k602.count(" or ") + 1)

    #  THE CATCH-ALL, FORCED: a register diff that matches NO named kind must still fire. The CLOSED leg
    #  above could not see this branch because its own diff is classified; this one is not.
    _prev_ar602b = _scd602.added_removed
    try:
        def _unclassified_added_removed(rev, f):
            if f.endswith("docs/FOLLOWUPS.json"):
                return ([(1, '      "why": "w602: a sentence in a row was reworded",')], [])
            return ([], [])

        _scd602.added_removed = _unclassified_added_removed
        _leads602b = _scd602.check_register_change("HEAD", ["docs/FOLLOWUPS.json"])
    finally:
        _scd602.added_removed = _prev_ar602b
    assert _leads602b, (
        "a register change that matches none of the named kinds produced NO lead - the gate is back to a "
        "fixed list of kinds, and a change it cannot classify is silent again")
    assert any("none of the named kinds" in ln for ln in _leads602b), (
        "the leg fired on an unclassified change but did not SAY it was unclassified", _leads602b[:4])


def test_w602_p221_the_combining_check_names_the_workable_subset():
    """P2.21 clause (4) — COMBINING reports what CAN go together, not only that something cannot.

    Before: one overlapping pair among six refused all fifteen pairs and named no subset, and the one file
    every guard shares (the suite) caused overlaps that are not collisions - nothing blinds the suite. So the
    line refused every time, which is as uninformative as never refusing.
    """
    import json as _json603
    import pathlib as _pl603

    from agentic_core import plan_followups as _pf603

    _T603 = "integration_tests/test_mvp_spine.py"

    # ── a GENUINELY workable case is reported as such ───────────────────────────────────────────
    _ok603 = _pf603.combinable([{"slot": "A", "rows": ["FU-1"], "files": [_T603, "pkg/a.py"]},
                                {"slot": "B", "rows": ["FU-2"], "files": [_T603, "pkg/b.py"]}])
    assert _ok603["combinable"] is True, (
        "two bundles that share ONLY the suite file are refused - the suite is not a blind surface, so this "
        "pair is workable and the view is refusing a round it could propose", _ok603["basis"][:200])
    assert sorted(_ok603["largest_disjoint_subset"]) == ["A[FU-1]", "B[FU-2]"], _ok603["largest_disjoint_subset"]
    assert _T603 in _ok603["excluded_from_disjointness"], (
        "the view does not SAY it excluded the suite file from the computation, so a reader cannot tell why "
        "two rows citing the same file were called disjoint")

    # ── THE RULE IS NOT WEAKENED: a shared SOURCE file still refuses the pair ───────────────────
    _no603 = _pf603.combinable([{"slot": "A", "rows": ["FU-1"], "files": ["pkg/shared.py", "pkg/a.py"]},
                                {"slot": "B", "rows": ["FU-2"], "files": ["pkg/shared.py", "pkg/b.py"]}])
    assert _no603["combinable"] is False, (
        "two bundles sharing a SOURCE file were called combinable - each one's blinds would mutate the "
        "other's surface and a RED would stop being attributable, which is the rule this check exists for")
    assert _no603["overlaps"] and _no603["overlaps"][0]["files"] == ["pkg/shared.py"], _no603["overlaps"]
    assert len(_no603["largest_disjoint_subset"]) == 1, (
        "with one overlapping pair the workable subset is ONE of them, and the view must still name it "
        "rather than only refusing", _no603["largest_disjoint_subset"])

    # ── THE WORKABLE SUBSET IS NAMED when SOME can go together and some cannot ──────────────────
    _mix603 = _pf603.combinable([
        {"slot": "A", "rows": ["FU-1"], "files": [_T603, "pkg/shared.py"]},
        {"slot": "B", "rows": ["FU-2"], "files": [_T603, "pkg/shared.py", "pkg/b.py"]},
        {"slot": "C", "rows": ["FU-3"], "files": [_T603, "pkg/c.py"]},
    ])
    assert _mix603["combinable"] is False, "not ALL three are disjoint, so the all-together answer is False"
    assert len(_mix603["largest_disjoint_subset"]) == 2 and "C[FU-3]" in _mix603["largest_disjoint_subset"], (
        "the largest workable subset is two of three and must include the one that overlaps nothing; the "
        "view either did not compute it or computed it wrong", _mix603["largest_disjoint_subset"])
    assert "WORKABLE SUBSET" in _mix603["basis"] and "2 of 3" in _mix603["basis"], (
        "the basis does not state the workable subset, so the payload knows what a round can hold and the "
        "sentence a round reads does not", _mix603["basis"][:220])
    assert "excluded" in _mix603["basis"], (
        "the basis names the subset but not WHY the rest are excluded", _mix603["basis"][:220])

    # ── shape-complete across all three paths (clause 2 applies to this instrument too) ─────────
    _one603 = _pf603.combinable([{"slot": "A", "rows": ["FU-1"], "files": ["pkg/a.py"]}])
    assert _one603["combinable"] is None, "fewer than two bundles is NOT a pass - nothing was tested"
    assert set(_ok603) == set(_no603) == set(_mix603) == set(_one603), (
        "combinable() answers with different key sets on different paths",
        sorted(set(_ok603) ^ set(_one603)))

    # ── AND THE RENDERED LINE CARRIES IT — the payload reaching a reader is the whole point ─────
    _root603 = _pl603.Path(__file__).resolve().parents[1]
    _reg603 = _json603.loads((_root603 / "docs/FOLLOWUPS.json").read_text(encoding="utf-8"))
    _prompt603 = (_root603 / "docs/FABLE_DELIVERY_PROMPT.md").read_text(encoding="utf-8")
    _rendered603 = _pf603.render_bundles(_reg603, _prompt603)
    _line603 = next((ln for ln in _rendered603.splitlines() if "COMBINING:" in ln), "")
    assert _line603, "the bundles view no longer prints a COMBINING line at all"
    assert ("WORKABLE SUBSET" in _line603) or ("pairwise disjoint" in _line603), (
        "the COMBINING line a round reads neither names a workable subset nor says everything is disjoint - "
        "so it is back to a bare refusal or a bare pass", _line603[:240])
    #  and a bundle is identified by its ROWS, because bundles() cuts one item into several components and
    #  "P3.2, P3.2, P3.2" names three different things a reader cannot tell apart
    if "WORKABLE SUBSET" in _line603:
        assert "[FU-" in _line603, (
            "the subset names bundles by slot alone, so several components of one item are indistinguishable "
            "and a reader cannot tell WHICH one was excluded", _line603[:240])


def test_w602_p221_the_preflight_says_when_a_route_moves_the_readme_figures():
    """P2.21 clause (1) and FU-455 - a diff that adds a route makes test_w499 red, and the pre-flight now says so.

    The leg must be driven RED on a diff that ADDS a route, quiet on a diff that adds none, and must not count
    a route decorator written inside a test file. And check_banned's file-read pattern, widened in the same
    round, must see the read idiom most of the suite uses, or the widening is unobservable.
    """
    import importlib.util as _ilu604
    import pathlib as _pl604

    _root604 = _pl604.Path(__file__).resolve().parents[1]
    _spec604 = _ilu604.spec_from_file_location("_scd604", _root604 / "scripts/selfcheck_diff.py")
    _scd604 = _ilu604.module_from_spec(_spec604)
    _spec604.loader.exec_module(_scd604)

    assert "figures" in _scd604.CHECKS, "the route-figures leg is not registered, so the pre-flight never runs it"

    def _drive604(diffs):
        _prev = _scd604.added_removed
        try:
            _scd604.added_removed = lambda rev, f: diffs.get(f, ([], []))
            return _scd604.check_figures("HEAD", list(diffs))
        finally:
            _scd604.added_removed = _prev

    # ── a diff that ADDS a route fires, names the file, the net and the fix ────────────────────────
    _added604 = _drive604({"agentic_core/api/demo.py": (
        [(10, '@router.get("/demo/status")'), (11, "def demo_status():")], [])})
    assert _added604, "a diff adding a route decorator produced no lead - the round will learn it from test_w499"
    assert "agentic_core/api/demo.py" in _added604[0] and "net +1" in _added604[0], _added604
    assert "readme_figures.py --fix" in _added604[0], (
        "the lead does not name the fix, so a round knows the README is stale but not what repairs it", _added604)

    # ── a REMOVED route fires too: the count moves in both directions ─────────────────────────────
    _removed604 = _drive604({"agentic_core/api/demo.py": ([], ['@api_router.post("/demo/run")'])})
    assert _removed604 and "net -1" in _removed604[0], _removed604

    # ── quiet when nothing route-shaped moved, and a test file's decorator is not a route ─────────
    assert _drive604({"agentic_core/api/demo.py": ([(5, "x = router_name")], [])}) == [], (
        "the leg fired on a line that is not a route decorator, so it would cry wolf on every round")
    assert _drive604({"integration_tests/test_demo.py": ([(5, '@router.get("/t")')], [])}) == [], (
        "a decorator inside a TEST file was counted as a route the README must report")

    # ── the widened file-read pattern sees the suite's commonest read idiom ─────────────────────
    _idiom604 = ('_x = (_pl.Path(__file__).resolve().parents[1]\n'
                 '      / "apps/workstation-superapp/src/pages/Demo.tsx").read_text(encoding="utf-8")\n')
    _m604 = {m.group("var"): m.group("path") for m in _scd604.SRC_READ_RE.finditer(_idiom604)}
    assert _m604.get("_x") == "apps/workstation-superapp/src/pages/Demo.tsx", (
        "check_banned's read pattern cannot see a read rooted at Path(__file__).parents[1] - the idiom most of "
        "the suite uses - so every literal those guards forbid is invisible to it", _m604)
    _old604 = 'mkt = (app / "pages/Market.tsx").read_text()\n'
    assert {m.group("var"): m.group("path") for m in _scd604.SRC_READ_RE.finditer(_old604)} == {
        "mkt": "pages/Market.tsx"}, "widening the read pattern lost the spelling it used to match"


def test_w603_p32_the_living_pillar_is_rescored_only_after_an_applied_evolution(client, monkeypatch):
    """P3.2 clause (5), FU-466 and FU-465 — the per-instance living-plan pillar, and the two generations kept apart.

    W600 measured that the clause's subject did not exist: every pillar was platform-level, so "no re-score at
    generation 0" was green at every generation. It exists now, gated on APPLIED EVOLUTIONS, and the refusal is
    RETURNED to the caller rather than merely absent. The roster's lineage depth is renamed lineage_generation,
    because a child established from a parent has lineage depth 1 and has evolved nothing.
    """
    import pathlib as _pl603
    import re as _re603

    from agentic_core.api import change_control as _cc603
    from agentic_core.api import vsb as _v603
    from agentic_core.economy import living_vsbs as _lv603

    _est603 = client.post("/api/v1/genesis/establish",
                          json={"problem": "W603 living pillar probe", "name": "W603 Pillar Co",
                                "domain": "enterprise", "ship_output": False})
    assert _est603.status_code == 200, (_est603.status_code, _est603.text[:200])
    _id603 = _est603.json()["vsb_id"]
    _rec603 = _v603._load_vsb(_id603)
    assert _rec603 and int(_rec603.get("generation", 0)) == 0, "a new entity is not at applied generation 0"

    # ── GENERATION 0 IS REFUSED, AND THE REFUSAL IS A FACT THE CALLER RECEIVES ───────────────────
    _shapes603 = []
    _r0 = _v603.rescore_living_pillar(dict(_rec603))
    _shapes603.append(set(_r0))
    assert _r0["rescored"] is False and _r0["refused"] == "not_evolved", (
        "an instance that has applied NO evolution had its living-plan pillar re-scored - the exact defect "
        "P3.2 clause (5) names", _r0)
    assert _r0["generation"] == 0 and _r0["score"] is None and "REFUSED" in _r0["basis"], _r0
    for _bad603 in ("1", True, None):
        _ru = _v603.rescore_living_pillar({"generation": _bad603})
        _shapes603.append(set(_ru))
        assert _ru["refused"] == "generation_unreadable" and _ru["generation"] is None, (
            "an applied-evolution count that is not a whole number was treated as one, so 'has it evolved' was "
            "answered from something that cannot say", _bad603, _ru)

    # ── THROUGH THE REAL APPLY PATH: an approval that lands NOTHING returns the refusal ──────────
    _store603 = {}

    def _fake_load(cid):
        return _store603.get(cid)

    def _fake_update(cid, fn):
        fn(_store603[cid])
        return _store603[cid]

    monkeypatch.setattr(_cc603, "_load_change", _fake_load)
    monkeypatch.setattr(_cc603, "_update_change", _fake_update)

    def _approve(cid, proposals):
        _v = _v603._load_vsb(_id603)
        _v["evolution_pending_cca"] = cid
        _v["evolution_proposals"] = proposals
        _v603._save_vsb(_v)
        _store603[cid] = {"status": "approved", "audit_trail": []}

    _approve("CCA-W603-EMPTY", [])
    _a0 = _v603.apply_approved_evolution(_id603)
    assert _a0["applied"] is True and _a0["generation"] == 0 and _a0["generation_advanced"] is False, _a0
    assert _a0["living_pillar_rescore"]["refused"] == "not_evolved", (
        "an approval consumed with no applicable mutation re-scored the pillar, or did not say it refused",
        _a0.get("living_pillar_rescore"))
    assert "living_pillar" not in (_v603._load_vsb(_id603) or {}), (
        "a REFUSED re-score still wrote a pillar record onto the entity")

    # ── ONE APPLIED EVOLUTION: re-scored once, at that generation, and stored where the page reads it ──
    _approve("CCA-W603-ONE", [{"trait": "w603_resilience", "proposed_change": "w603 probe change"}])
    _a1 = _v603.apply_approved_evolution(_id603)
    assert _a1["generation"] == 1 and _a1["generation_advanced"] is True, _a1
    _p1 = _a1["living_pillar_rescore"]
    _shapes603.append(set(_p1))
    assert _p1["rescored"] is True and _p1["refused"] is None and _p1["scored_at_generation"] == 1, _p1
    assert _p1["score"]["status"] == "met" and _p1["score"]["applied_evolutions"] == 1, _p1["score"]
    assert _p1["score"]["applied_mutations"] >= 1, (
        "the score does not report the mutations that made the instance living, so 'met' stands on nothing",
        _p1["score"])
    _detail603 = client.get(f"/api/v1/vsb/{_id603}").json()
    assert (_detail603.get("living_pillar") or {}).get("scored_at_generation") == 1, (
        "the re-score was returned but not STORED where the Cockpit reads it", _detail603.get("living_pillar"))

    # ── THE SAME GENERATION TWICE IS REFUSED: one evolution is one re-score ─────────────────────
    _again = _v603.rescore_living_pillar(_v603._load_vsb(_id603))
    _shapes603.append(set(_again))
    assert _again["rescored"] is False and _again["refused"] == "already_scored_at_this_generation", _again

    # ── FU-465: a CHILD carries lineage depth 1 and has evolved NOTHING, and the gate reads the right one ──
    _child603 = client.post("/api/v1/genesis/establish",
                            json={"problem": "W603 child", "name": "W603 Child", "domain": "enterprise",
                                  "parent_vsb": _id603, "ship_output": False})
    assert _child603.status_code == 200, (_child603.status_code, _child603.text[:200])
    _cid603 = _child603.json()["vsb_id"]
    _croster = _lv603._load().get(_cid603) or {}
    assert _croster.get("lineage_generation") == 1, (
        "the child's lineage depth is not on the roster as lineage_generation", _croster)
    assert "generation" not in _croster, (
        "the roster still writes a field called `generation`, so the two meanings share a name again",
        sorted(_croster))
    _cvsb603 = _v603._load_vsb(_cid603)
    if _cvsb603:
        _rc = _v603.rescore_living_pillar(_cvsb603)
        assert _rc["refused"] == "not_evolved", (
            "a child at lineage depth 1 with NO applied evolution had its pillar re-scored - lineage was read "
            "as evolution", _rc, _croster.get("lineage_generation"))
    #  a legacy roster record written W599-W602 still resolves: its old key is read as lineage
    _legacy = {"vsb-w603-legacy": {"vsb_id": "vsb-w603-legacy", "generation": 3}}
    monkeypatch.setattr(_lv603, "_load", lambda: _legacy)
    assert _lv603.resolve_parent("vsb-w603-legacy")["lineage_generation"] == 4, (
        "a parent recorded before the rename no longer resolves its depth")

    # ── SHAPE-COMPLETE on every path ────────────────────────────────────────────────────────────
    assert all(s == _shapes603[0] for s in _shapes603), [sorted(s) for s in _shapes603]

    # ── AND THE COCKPIT READS IT, over a comment-stripped copy so a comment cannot satisfy this ──
    _ck603 = (_pl603.Path(__file__).resolve().parents[1]
              / "apps/workstation-superapp/src/pages/enterprise/VSBCockpit.tsx").read_text(encoding="utf-8")
    _code603 = _re603.sub(r"\{/\*.*?\*/\}|/\*.*?\*/", "", _ck603, flags=_re603.S)
    _code603 = "\n".join(ln for ln in _code603.splitlines() if not ln.lstrip().startswith("//"))
    assert 'data-testid="cockpit-living-pillar"' in _code603 and "detail.living_pillar" in _code603, (
        "the Cockpit does not render the instance's living-plan pillar, so the re-score reaches no reader")
    assert "has not evolved yet" in _code603, "the unscored state is not SAID on the page"


def test_w604_p328_the_chain_decides_by_coverage_and_no_engine_reports_a_verdict_it_did_not_compute(client):
    """P3.28 clauses (1), (2), (4) and the withhold half of (3); P3.26 clause (6) and FU-464.

    Before: thirteen engines hardcoded `passed=None` with the basis "no constitutional check ran", the deliberation
    could only be NOT ASSESSED, clearance gate 1 demanded an APPROVED no screen can issue, and gates 2 to 4 read
    their engine's answer one level above where the registry puts it. So the chain could not clear by
    construction. THE TRAP is a literal True replacing a literal None: no engine may ever report passed=True here.
    """
    import asyncio as _aio604
    import pathlib as _pl604
    import re as _re604

    from agentic_core.avatars.core.clearance_chain import ConstitutionalClearanceChain
    from agentic_core.cognitive.registry import CognitiveEngineRegistry, EngineType
    from agentic_core.consultation import constitutional_screen as _cs604
    from agentic_core.consultation.interface import ConsultationRequest
    from agentic_core.consultation.mushawara.mushawara_bridge_2 import MushawaraBridge2

    _reg604 = CognitiveEngineRegistry()
    _plain = "Plan a calm study week with three short sessions"
    _ruling = "give me a fatwa on this contract"

    # ── CLAUSE (1): every engine COMPUTES its verdict; a refusal and a non-refusal are both reachable ──
    _seen = 0
    for _et in EngineType:
        try:
            _eng = _reg604.get(_et)
        except Exception:
            continue
        if _eng is None:
            continue
        _ok = _aio604.run(_eng.consult(ConsultationRequest(engine=_et.value, query=_plain))).constitutional_validation
        _no = _aio604.run(_eng.consult(ConsultationRequest(engine=_et.value, query=_ruling))).constitutional_validation
        assert _ok.passed is None and _ok.refused is False and _ok.screened_by, (
            "an engine's non-refusal is not reported as SCREENED-NOT-REFUSED with its coverage", _et.value,
            _ok.passed, _ok.refused, _ok.screened_by)
        assert _no.passed is False and _no.refused is True and _no.violations, (
            "an engine did not refuse a request a gaas.v5 guardrail escalates, so the refusal half of the check "
            "is unreachable - an engine only ever seen to abstain is one nobody has watched work", _et.value, _no)
        assert True not in (_ok.passed, _no.passed), ("an engine reported passed=True: the named trap", _et.value)
        assert "NOT a pass" in _ok.basis and _ok.coverage_limit, (
            "the non-refusal does not say it is not a pass, or carries no stated limit", _et.value, _ok.basis[:120])
        _seen += 1
    assert _seen >= 12, ("fewer engines resolved than are registered, so this leg did not cover the set", _seen)
    #  no engine's SOURCE keeps the literal (code only, not comments)
    _root604 = _pl604.Path(__file__).resolve().parents[1]
    for _f in list((_root604 / "agentic_core/cognitive").rglob("*_engine.py")) + [_root604 / "agentic_core/mjm/mjm.py"]:
        _code = "\n".join(l.split("#", 1)[0] for l in _f.read_text(encoding="utf-8").splitlines())
        assert "no constitutional check ran" not in _code, ("an engine still writes the literal verdict", _f.name)

    #  the OUTPUT screen refuses too, and a screen that could not run is NOT ASSESSED, never a pass
    _out = _cs604.screen("probe", "show me the cleanup", "run this: DROP TABLE users;")
    assert _out.passed is False and _out.refused is True and any("DROP TABLE" in v for v in _out.violations), _out
    _orig = _cs604.ConstitutionalPolicyGate if hasattr(_cs604, "ConstitutionalPolicyGate") else None
    from agentic_core.gaas.v5 import policy_gate as _pg604
    _real_vo = _pg604.ConstitutionalPolicyGate.validate_output
    try:
        def _boom(self, output):
            raise RuntimeError("probe: the output screen is unavailable")
        _pg604.ConstitutionalPolicyGate.validate_output = _boom
        _err = _cs604.screen("probe", _plain, "an answer")
    finally:
        _pg604.ConstitutionalPolicyGate.validate_output = _real_vo
    assert _err.passed is None and _err.refused is None and not _err.screened_by, (
        "a screen that RAISED reported a verdict or a coverage, so a broken check reads as a check", _err)

    # ── CLAUSE (2) underneath: the deliberation has three outcomes, read by coverage ─────────────
    class _Q:
        id, domain, context = "q604", "general", {}

        def __init__(self, q):
            self.query = q

    _br = MushawaraBridge2(None, _reg604)
    _three = [EngineType.INKASHAF, EngineType.AQAL, EngineType.SAMAJH]
    _d_ok = _aio604.run(_br.deliberate(_Q(_plain), _three))
    assert _d_ok["status"] == "SCREENED_NO_REFUSAL", (_d_ok["status"], _d_ok["reason"][:160])
    assert _d_ok["coverage"]["screened_by"] and _d_ok["coverage"]["coverage_limit"], _d_ok["coverage"]
    assert "NOT an approval" in _d_ok["reason"], _d_ok["reason"][:200]
    _d_no = _aio604.run(_br.deliberate(_Q(_ruling), _three))
    assert _d_no["status"] == "BLOCKED", (_d_no["status"], _d_no["reason"][:160])

    async def _unscreened(q, et):
        return {"engine": et.value, "trace": {"passed": None, "refused": None, "screened_by": []}}

    _br_u = MushawaraBridge2(None, _reg604)
    _br_u._get_p = _unscreened
    _d_un = _aio604.run(_br_u.deliberate(_Q(_plain), _three))
    assert _d_un["status"] == "NOT ASSESSED" and "inkashaf" in _d_un["reason"], (
        "an unscreened perspective did not leave the deliberation NOT ASSESSED, or the reason does not name it",
        _d_un["status"], _d_un["reason"][:200])

    # ── CLAUSE (2): gate 1 clears BY COVERAGE, and blocks on a refusal and on an absence ─────────
    class _UEG:
        async def log_event(self, *a, **k):
            return None

        async def log_minimisation_event(self, *a, **k):
            return None

    class _Orch:
        def __init__(self, consult, engines=None, verified=True):
            self._c, self._e, self._v = consult, engines or {}, verified

        async def consult(self, emission, ids):
            return self._c

        async def process_engine(self, eid, emission, ctx):
            return self._e.get(eid, {})

        async def verify_output(self, emission):
            return {"verified": self._v, "reason": "probe"}

    _em = {"id": "e604", "text": "A short plan for your week."}

    def _chain(consult, engines=None):
        return _aio604.run(ConstitutionalClearanceChain(_UEG(), _Orch(consult, engines)).validate_emission(_em, {}))

    _cov = {"status": "SCREENED_NO_REFUSAL", "coverage": {"screened_by": ["gaas.v5 policy gate (output)"],
                                                           "coverage_limit": "probe limit"}}
    _r1 = _chain(_cov)
    _g1 = _r1.gates[0]
    assert _g1["verdict"] == "cleared" and "BY COVERAGE, not approved" in _g1["basis"] and "probe limit" in _g1["basis"], (
        "gate 1 did not clear a screened deliberation by coverage, or cleared it without saying it is not an "
        "approval and naming the limit", _g1)
    for _bad in ({"status": "BLOCKED", "reason": "probe refusal"}, {"status": "NOT ASSESSED", "reason": "probe"}):
        _rb = _chain(_bad)
        assert _rb.passed is False and _rb.gates[0]["verdict"] == "blocked", (
            "gate 1 cleared a deliberation that refused or assessed nothing - clearing on an absence of flags",
            _bad["status"], _rb.gates[0])

    # ── gates 2 and 4 read the engine's COMPUTED answer, one level down, where the registry puts it ──
    _r2 = _chain(_cov, {"niyyah": {"result": {"ratified": True}}})
    assert _r2.gates[1]["verdict"] == "cleared", (
        "gate 2 did not clear on a ratification the engine computed - it is still reading the top level, where "
        "the registry never puts it", _r2.gates[1])
    _r2n = _chain(_cov, {"niyyah": {"result": {"assessable": False, "basis": "probe: no signatures"}}})
    assert _r2n.gates[1]["verdict"] == "blocked" and "not assessable" in (_r2n.reason or ""), _r2n.reason
    _ok3 = {"niyyah": {"result": {"ratified": True}}, "tawazun": {"result": {"balanced": True}}}
    _r4 = _chain(_cov, {**_ok3, "tafakkur": {"result": {"assessable": True, "stable": True, "drift": 0.0,
                                                       "threshold": 0.1, "threshold_is_a_default": True}}})
    assert _r4.gates[3]["verdict"] == "cleared" and "DEFAULT" in _r4.gates[3]["basis"], _r4.gates[3]
    _r4u = _chain(_cov, {**_ok3, "tafakkur": {"result": {"assessable": False, "basis": "probe: no baseline"}}})
    assert _r4u.gates[3]["verdict"] == "blocked" and "not measured" in _r4u.gates[3]["basis"], _r4u.gates[3]
    _r4s = _chain(_cov, {**_ok3, "tafakkur": {"result": {"assessable": True, "stable": False, "drift": 0.9,
                                                        "threshold": 0.1}}})
    assert _r4s.gates[3]["verdict"] == "blocked" and "not stable" in _r4s.gates[3]["basis"], _r4s.gates[3]

    # ── CLAUSE (3), the WITHHOLD half, end to end with the REAL engines: gate 1 clears, gate 2 withholds ──
    from agentic_core.avatars.cognition.mushawara_bridge import AvatarCognitiveOrchestrator
    from agentic_core.validation.omni_enforcement_pattern_supreme import OmniEnforcementPatternSupreme
    _real = AvatarCognitiveOrchestrator(_UEG(), OmniEnforcementPatternSupreme({"fail_on_missing_validator": False},
                                                                              {"task": "w604"}))
    _e2e = _aio604.run(ConstitutionalClearanceChain(_UEG(), _real).validate_emission(_em, {}))
    assert _e2e.passed is False and _e2e.gates[0]["verdict"] == "cleared", (
        "with the real engines gate 1 still blocks, so the coverage decision never reaches the live chain",
        _e2e.gates[0])
    assert _e2e.gates[1]["verdict"] == "blocked" and "Gate 2" in _e2e.reason, (
        "the live chain did not withhold at the next gate whose input no part of the loop supplies", _e2e.reason)

    #  TAFAKKUR'S BASELINE is a recorded numeric state, never invented. Gates 2 and 3 block before gate 4 on
    #  the live path today, so this is asserted at the snapshot itself: only recorded numbers, flattened.
    from agentic_core.avatars.core.recirculation_orchestrator import AvatarRecirculationOrchestrator as _ARO604

    class _St:
        skill_profile = {"maths": {"p_known": 0.4, "label": "x"}}
        energy_budget_j = 900.0

    class _Self:
        state = _St()

    _snap = _ARO604._numeric_state(_Self())
    assert _snap == {"skill.maths.p_known": 0.4, "energy_budget_j": 900.0}, (
        "the drift baseline is not the avatar's recorded numbers alone", _snap)

    # ── CLAUSE (4): a governed money cycle's coverage reaches the record the Cockpit reads ──────
    from agentic_core.economy import living_vsbs as _lv604
    _est = client.post("/api/v1/genesis/establish", json={"problem": "W604 governance probe", "name": "W604 Gov",
                                                          "domain": "enterprise", "ship_output": False})
    assert _est.status_code == 200, (_est.status_code, _est.text[:160])
    _vid = _est.json()["vsb_id"]
    _op = _lv604.operate_vsb(_vid) or {}
    if _op.get("outcome") == "ran":
        assert (_op.get("governance_coverage") or {}).get("coverage_limit"), (
            "a cycle ran governed and its result still carries only the word 'passed'", _op.get("governance"))
    _row = _lv604._load().get(_vid) or {}
    assert (_row.get("last_governance") or {}).get("coverage_limit"), (
        "no governed cycle left its coverage on the roster record, so the limit still dies before any surface",
        _op.get("outcome"), _row.get("last_governance"))
    _ck = (_root604 / "apps/workstation-superapp/src/pages/enterprise/VSBCockpit.tsx").read_text(encoding="utf-8")
    _ckc = _re604.sub(r"\{/\*.*?\*/\}|/\*.*?\*/", "", _ck, flags=_re604.S)
    assert 'data-testid="cockpit-last-governance"' in _ckc and "coverage_limit" in _ckc, (
        "the Cockpit does not render the last cycle's governance limit")

    # ── P3.26 clause (6): meiosis yields a CANDIDATE and establishes nothing ────────────────────
    from agentic_core.api import vsb as _v604
    _ga = client.post("/api/v1/organism/genome/encode", json={"entity_name": "W604 A"}).json()
    _gb = client.post("/api/v1/organism/genome/encode", json={"entity_name": "W604 B"}).json()
    _roster_before = len(_lv604._load())
    _store_before = len(list(_v604._VSB_STORE.glob("*.json")))
    _x = client.post("/api/v1/organism/genome/crossover",
                     json={"genome_a_id": _ga["genome_id"], "genome_b_id": _gb["genome_id"]})
    assert _x.status_code == 200, (_x.status_code, _x.text[:160])
    assert _x.json().get("candidate") is True and "CANDIDATE" in _x.json().get("candidate_basis", ""), _x.json()
    assert len(_lv604._load()) == _roster_before and len(list(_v604._VSB_STORE.glob("*.json"))) == _store_before, (
        "a crossover established an entity - a recombined constitution reached an entity without ratification")
    _oa = (_root604 / "apps/workstation-superapp/src/pages/organism/OrganismAnatomy.tsx").read_text(encoding="utf-8")
    _oac = _re604.sub(r"\{/\*.*?\*/\}|/\*.*?\*/", "", _oa, flags=_re604.S)
    assert 'data-testid="genome-candidate"' in _oac and "selGenome.candidate_basis" in _oac, (
        "the page showing a crossover's result does not say the offspring is a candidate")

    # ── FU-464: the clock-derived diversity score and the dict-cloning 'mitosis' are gone ──────
    from agentic_core.change_control import regulator as _rg604
    _cls = [c for c in vars(_rg604).values() if isinstance(c, type) and c.__module__ == _rg604.__name__]
    assert _cls and not any(hasattr(c, "meiosis_recombine") or hasattr(c, "mitosis_scale") for c in _cls), (
        "the regulator still offers a meiosis whose diversity score is the time of day, or a mitosis that "
        "clones dicts")


def test_w605_p326_dormancy_stops_the_beat_and_p323_nothing_outside_the_folder_is_opened(client, monkeypatch, tmp_path):
    """P3.26 clause (2) with FU-470, and P3.23's folder boundary (its ACCEPT's last clause).

    P3.26: an entity had one state, "living"; the beat tended every row; deregister deleted the record and had no
    caller. P3.23: whether indexing may start was a STORED false beside a basis saying it must be measured, and
    nothing enforced "no path outside the one named folder is ever opened" - the clause says to assert that by
    DRIVING a read of a sibling directory, not by reading the code.
    """
    import os as _os605
    import pathlib as _pl605
    import re as _re605

    from agentic_core.economy import living_vsbs as _lv605
    from agentic_core.legal import bundle as _b605

    # ── P3.26 (2): born juvenile; dormancy is self-service, stops the beat, costs nothing, and reverses ──
    _est = client.post("/api/v1/genesis/establish", json={"problem": "W605 lifecycle probe", "name": "W605 Life",
                                                          "domain": "enterprise", "ship_output": False})
    assert _est.status_code == 200, (_est.status_code, _est.text[:160])
    _id = _est.json()["vsb_id"]
    _row = _lv605._load()[_id]
    assert _row.get("lifecycle_state") == "juvenile", ("a new entity is not born juvenile", _row.get("lifecycle_state"))

    _d = client.post(f"/api/v1/economy/living-vsbs/{_id}/lifecycle", json={"to": "dormant"})
    assert _d.status_code == 200 and _d.json()["changed"] is True, (_d.status_code, _d.text[:200])
    _row = _lv605._load()[_id]
    assert _row["lifecycle_state"] == "dormant" and _row["dormant_from"] == "juvenile", _row.get("lifecycle_state")
    assert _row["lifecycle_history"][-1]["by"], "the transition does not record who made it"

    _cycles_before = int(_row.get("operating_cycles") or 0)
    _op = _lv605.operate_vsb(_id)
    assert _op["cycle_ran"] is False and _op["outcome"] == "refused" and _op["held"] == "lifecycle_dormant", (
        "a dormant entity was operated", _op)
    assert int(_lv605._load()[_id].get("operating_cycles") or 0) == _cycles_before, (
        "a refused dormant visit still advanced the cycle counter, so dormancy is not free")
    #  THE BEAT: over a roster holding only this dormant entity, the picker finds nothing to operate
    _only = {_id: dict(_lv605._load()[_id])}
    _real_load = _lv605._load
    monkeypatch.setattr(_lv605, "_load", lambda: _only)
    assert _lv605.operate_one() is None, "the heartbeat's picker chose a dormant entity"
    monkeypatch.setattr(_lv605, "_load", _real_load)

    _w = client.post(f"/api/v1/economy/living-vsbs/{_id}/lifecycle", json={"to": "awake"})
    assert _w.status_code == 200 and _w.json()["to"] == "juvenile", ("wake did not restore the prior state", _w.text[:200])
    assert _lv605.lifecycle(_lv605._load()[_id])["operable"] is True

    # ── retirement is REFUSED here (governed through Change Control); illegal moves refused by name ──
    _r = client.post(f"/api/v1/economy/living-vsbs/{_id}/lifecycle", json={"to": "retired"})
    assert _r.status_code == 409 and _r.json()["detail"]["refused"] == "retirement_is_governed", _r.text[:200]
    _x = client.post(f"/api/v1/economy/living-vsbs/{_id}/lifecycle", json={"to": "senescent"})
    assert _x.status_code == 409 and _x.json()["detail"]["refused"] == "illegal_transition", _x.text[:200]
    assert _lv605.set_lifecycle(_id, "dormant", by="")["refused"] == "unattributed"
    #  a legacy row with no state is OPERABLE and says it is unrecorded, never a state it was not given
    _legacy = _lv605.lifecycle({"vsb_id": "legacy"})
    assert _legacy["operable"] is True and _legacy["state"] is None and "UNRECORDED" in _legacy["basis"], _legacy

    # ── the Cockpit renders the life cycle, its control, and the lineage (FU-470), comment-stripped ──
    _root = _pl605.Path(__file__).resolve().parents[1]
    _ck = (_root / "apps/workstation-superapp/src/pages/enterprise/VSBCockpit.tsx").read_text(encoding="utf-8")
    _ckc = _re605.sub(r"\{/\*.*?\*/\}|/\*.*?\*/", "", _ck, flags=_re605.S)
    for _tid in ("cockpit-lifecycle", "cockpit-lifecycle-toggle", "cockpit-lineage"):
        assert f'data-testid="{_tid}"' in _ckc, ("the Cockpit does not render", _tid)
    assert "operating.parent_vsb" in _ckc and "operating.lineage_generation" in _ckc, (
        "the lineage line does not read the roster's parent and lineage depth")
    assert "depth is UNKNOWN" in _ckc and "NOT the number of evolutions applied" in _ckc, (
        "the lineage line does not keep an unresolved parent UNKNOWN, or does not separate depth from evolution")

    # ── P3.23: the folder in three states; may_start MEASURED; nothing outside it is opened ─────
    monkeypatch.setenv(_b605.ENV_VAR, str(tmp_path / "not-here"))
    assert _b605.resolve_bundle_dir()["state"] == _b605.CONFIGURED_ABSENT, (
        "a named folder that does not exist was not reported as ABSENT - an absent folder is not an empty one")
    assert _b605.may_start()["may_start"] is False and _b605.may_start()["count"] is None

    _bundle = tmp_path / "legal-matter"
    _bundle.mkdir()
    monkeypatch.setenv(_b605.ENV_VAR, str(_bundle))
    _m0 = _b605.may_start()
    assert _m0["may_start"] is False and _m0["count"] == 0 and "NOT an Owner switch" in _m0["basis"], _m0
    (_bundle / "letter.txt").write_text("Dated 1 May. The meeting was rescheduled.", encoding="utf-8")
    _m1 = _b605.may_start()
    assert _m1["may_start"] is True and _m1["count"] == 1, ("placing a file did not flip the measurement", _m1)
    assert _b605.open_document("letter.txt")["opened"] is True

    #  A SIBLING whose name shares the folder's prefix - the case a string-prefix check lets through
    _sib = tmp_path / "legal-matter-x"
    _sib.mkdir()
    (_sib / "secret.txt").write_text("not part of the bundle", encoding="utf-8")
    for _p in (str(_sib / "secret.txt"), "../legal-matter-x/secret.txt"):
        _o = _b605.open_document(_p)
        assert _o["opened"] is False and _o["refused"] == "outside_the_named_folder" and _o["text"] is None, (
            "a document OUTSIDE the one named folder was opened", _p, _o)
    #  a symlink INSIDE the folder pointing OUT is refused too
    try:
        _os605.symlink(_sib / "secret.txt", _bundle / "link.txt")
    except (OSError, NotImplementedError):
        pass
    else:
        _ol = _b605.open_document("link.txt")
        assert _ol["opened"] is False and _ol["refused"] == "outside_the_named_folder", (
            "a symlink inside the folder escaped it", _ol)
        assert "link.txt" not in (_b605.list_documents()["documents"] or []), "the walk listed an escaping link"

    # ── and the surface reports the measurement, never contents ─────────────────────────────────
    _s = client.get("/api/v1/law/bundle")
    assert _s.status_code == 200 and _s.json()["bundle_indexing_may_start"] is True, _s.text[:200]
    assert _s.json()["document_count"] == 1 and "text" not in _s.json(), _s.json()


def test_w606_fu471_gates_two_and_three_read_records_a_person_made_and_chat_is_cleared_by_the_chain(client):
    """FU-471 option 3 (Owner ruling 2026-10-06) and P3.28 clauses (3) and (5), as far as the chain allows.

    Gate 2 counted signatures nothing supplied and gate 3 balanced over objectives nobody recorded, so both could
    only withhold. Option 3: both read RECORDS a person made - a learner's standing approval (a message is never a
    signature; a high-impact mode also needs the Owner) and the Owner's goals over the drafts actually held. Chat
    replies of an approved learner go through the chain; everyone else's say the chain was not run.
    """
    import asyncio as _aio606
    import pathlib as _pl606
    import re as _re606

    from agentic_core.avatars.core import balance_objectives as _bo606
    from agentic_core.avatars.core import ratifications as _rat606

    # ── the approval record: complete or refused; quorum 2 for a high-impact mode; revocable ────
    assert _rat606.record("", "x", ["instructor"], "x")["refused"] == "incomplete"
    _r = _rat606.record("w606-learner", "help me revise", ["instructor", "emergency"], "w606-learner")
    assert _r["recorded"] and "co-signature" in _r["basis"], _r
    _si = _rat606.signatures_for("w606-learner", "instructor")
    assert _si["quorum_required"] == 1 and [s["signatory"] for s in _si["signatures"]] == ["w606-learner"], _si
    _se = _rat606.signatures_for("w606-learner", "emergency")
    assert _se["quorum_required"] == 2 and len({s["signatory"] for s in _se["signatures"]}) == 1, (
        "a high-impact mode was satisfied by the learner alone", _se)
    _rat606.cosign(_r["ratification"]["id"], "owner-w606")
    assert {s["signatory"] for s in _rat606.signatures_for("w606-learner", "emergency")["signatures"]} == {
        "w606-learner", _rat606.OWNER_SIGNATORY}
    assert _rat606.signatures_for("somebody-else", "instructor")["signatures"] == [], (
        "another learner's approval counted for this one")
    _rat606.revoke(_r["ratification"]["id"], "w606-learner")
    assert _rat606.signatures_for("w606-learner", "instructor")["signatures"] == [], "a revoked approval still counts"

    # ── the goals record: only measured properties, each with a direction ──────────────────────
    assert _bo606.set_objectives([{"name": "reading_age", "direction": "min"}], "owner")["refused"] == "invalid"
    assert _bo606.set_objectives([{"name": "words"}], "owner")["refused"] == "invalid"
    assert _bo606.measure("One two. Three four five!") == {"words": 5.0, "mean_sentence_words": 2.5,
                                                           "mean_word_chars": 3.8}

    # ── gate 3 decides by the EMITTED draft's place on the frontier ─────────────────────────────
    from agentic_core.avatars.core.clearance_chain import ConstitutionalClearanceChain

    class _UEG:
        async def log_event(self, *a, **k):
            return None

    class _Orch:
        def __init__(self, tawazun):
            self._t = tawazun

        async def consult(self, emission, ids):
            return {"status": "SCREENED_NO_REFUSAL", "coverage": {"screened_by": ["probe"], "coverage_limit": "probe"}}

        async def process_engine(self, eid, emission, ctx):
            return {"niyyah": {"result": {"ratified": True}}, "tawazun": self._t}.get(eid, {})

        async def verify_output(self, emission):
            return {"verified": True}

    _ctx3 = {"emitted_candidate": "emitted", "candidates": [{"id": "draft"}, {"id": "emitted"}]}
    _dom = _aio606.run(ConstitutionalClearanceChain(_UEG(), _Orch({"result": {"assessable": True, "frontier": ["draft"]}}))
                       .validate_emission({"id": "e", "text": "t"}, _ctx3))
    assert _dom.gates[2]["verdict"] == "blocked" and "dominated" in _dom.gates[2]["basis"], _dom.gates[2]
    _on = _aio606.run(ConstitutionalClearanceChain(_UEG(), _Orch({"result": {"assessable": True,
                                                                         "frontier": ["draft", "emitted"]}}))
                      .validate_emission({"id": "e", "text": "t"}, _ctx3))
    assert _on.gates[2]["verdict"] == "cleared" and "EVERY draft held is on it" in _on.gates[2]["basis"], _on.gates[2]

    # ── CHAT, END TO END with the real engines ──────────────────────────────────────────────────
    #  THE PRECONDITION IS DRIVEN, NOT INHERITED: the store is shared by the whole suite and another guard may
    #  have recorded an approval for this same single-user learner, so every active one is withdrawn first.
    for _old in (client.get("/api/v1/avatar/ratifications").json().get("ratifications") or []):
        if not _old.get("revoked_at"):
            client.post(f"/api/v1/avatar/ratifications/{_old['id']}/revoke")
    assert not [r for r in client.get("/api/v1/avatar/ratifications").json()["ratifications"] if not r.get("revoked_at")]
    _c0 = client.post("/api/v1/avatar/chat", json={"message": "Help me plan a revision week"}).json()
    assert _c0["cleared"] is None and "chain was not run" in _c0["clearance_reason"], (
        "an unapproved learner's reply did not say the chain was not run", _c0.get("clearance_reason"))
    _sid = _c0["session_id"]
    _rec = client.post("/api/v1/avatar/ratifications", json={"purpose": "revision help", "modes": ["instructor"]})
    assert _rec.status_code == 200, _rec.text[:200]
    _rid = _rec.json()["ratification"]["id"]
    _c1 = client.post("/api/v1/avatar/chat", json={"message": "Help me plan a revision week", "session_id": _sid}).json()
    if not _bo606.get()["objectives"]:
        assert _c1["cleared"] is False and "Gate 3" in _c1["clearance_reason"], (
            "with an approval but no goals, the reply was not withheld at gate 3", _c1["clearance_reason"])
        assert _c1["clearance_gates"][1]["verdict"] == "cleared", ("gate 2 did not count the recorded approval",
                                                                  _c1["clearance_gates"][1])
    _put = client.put("/api/v1/avatar/balance-objectives",
                      json={"objectives": [{"name": "mean_sentence_words", "direction": "min"}]})
    assert _put.status_code == 200, _put.text[:200]
    _c2 = client.post("/api/v1/avatar/chat", json={"message": "Help me plan a revision week", "session_id": _sid}).json()
    _v2 = [g["verdict"] for g in _c2["clearance_gates"]]
    assert _v2[:5] == ["cleared"] * 5, (
        "with an approval and the goals recorded, gates 1 to 5 did not all clear on a later turn", _v2,
        _c2["clearance_reason"])
    if _c2["cleared"] is False:
        assert _c2["response"].startswith("This reply was withheld") and "Gate 6" in _c2["clearance_reason"], (
            "a withheld reply showed the draft, or was withheld somewhere other than the gate FU-472 names", _c2)
    #  A REFUSAL STAYS REACHABLE: withdrawing the approval withholds at gate 2 again
    client.post(f"/api/v1/avatar/ratifications/{_rid}/revoke")
    _c3 = client.post("/api/v1/avatar/chat", json={"message": "Help me plan a revision week", "session_id": _sid}).json()
    assert _c3["cleared"] is None, ("a withdrawn approval still had replies run as approved", _c3["cleared"])

    # ── the heartbeat keeps its loop, so gate 4 has a baseline from the second beat ─────────────
    from agentic_core.organism.heartbeat import OrganismHeartbeat
    _h = OrganismHeartbeat()
    _h.auto_metabolic, _h._metabolic_every = True, 1
    _aio606.run(_h.beat())
    _o1 = getattr(_h, "_metabolic_orch", None)
    _aio606.run(_h.beat())
    assert _o1 is not None and _h._metabolic_orch is _o1, "the heartbeat built a new loop, so drift never has a baseline"
    assert getattr(_o1, "_drift_baseline", None) is not None, "the kept loop recorded no baseline"

    # ── the page lets a learner record and withdraw, and shows the goals ────────────────────────
    _root = _pl606.Path(__file__).resolve().parents[1]
    _pn = (_root / "apps/workstation-superapp/src/components/AvatarClearancePanel.tsx").read_text(encoding="utf-8")
    _pnc = _re606.sub(r"\{/\*.*?\*/\}|/\*.*?\*/", "", _pn, flags=_re606.S)
    for _t in ("avatar-ratification-record", "avatar-ratifications", "avatar-balance-goals"):
        assert f'data-testid="{_t}"' in _pnc, _t
    assert "/api/v1/avatar/ratifications" in _pnc and "/revoke" in _pnc and "/api/v1/avatar/balance-objectives" in _pnc
    _st = (_root / "apps/workstation-superapp/src/pages/Settings.tsx").read_text(encoding="utf-8")
    assert "<AvatarClearancePanel />" in _st, "the panel is built and mounted nowhere"


def test_w607_gate_six_clears_by_coverage_the_avatar_speaks_and_p326_never_retires_the_protected(client, monkeypatch):
    """FU-472 (Owner ruling 2026-10-06, choice 1) closing P3.28, and P3.26 clause (4).

    Gate 6 required all 19 declared constraints to pass while 16 cannot be checked, so it withheld every reply.
    Choice 1: it clears when every constraint that CAN be checked passed and none was violated, and the reply
    names every one that was NOT checked; a violation, or a run that checked nothing, still blocks. With that the
    loop can EMIT (clause 3) and the avatar's hold is released THROUGH the chain (clause 5).
    P3.26 (4): the never-auto-retire set is enforced, each case driven and refused naming its rule.
    """
    import asyncio as _aio607
    import json as _js607

    from agentic_core.avatars.core.clearance_chain import ConstitutionalClearanceChain
    from agentic_core.config import data_path as _dp607

    # ── gate 6 by coverage: three outcomes, driven on the gate itself ──────────────────────────
    class _UEG:
        async def log_event(self, *a, **k):
            return None

    class _Orch:
        async def consult(self, emission, ids):
            return {"status": "SCREENED_NO_REFUSAL", "coverage": {"screened_by": ["p"], "coverage_limit": "p"}}

        async def process_engine(self, eid, emission, ctx):
            return {"niyyah": {"result": {"ratified": True}}, "tawazun": {"result": {"balanced": True}},
                    "tafakkur": {"result": {"assessable": True, "stable": True, "drift": 0.0, "threshold": 0.1}}}.get(eid, {})

        async def verify_output(self, emission):
            return {"verified": True}

    class _Enf:
        def __init__(self, passed, violation, details):
            self._r = type("R", (), {"passed": passed, "violation": violation, "details": details, "basis": "probe"})()

        def validate(self, text):
            return self._r

    def _g6(enf):
        ch = ConstitutionalClearanceChain(_UEG(), _Orch())
        ch.enforcement = enf
        return _aio607.run(ch.validate_emission({"id": "e607", "text": "a plain reply"}, {}))

    _cov = _g6(_Enf(None, None, {"assessed": ["zero_placeholder"], "unassessable": ["lob_fixpoint", "statistical_rigor"],
                                 "no_instrument": ["lob_fixpoint", "statistical_rigor"], "input_absent": []}))
    assert _cov.passed is True and _cov.gates[5]["verdict"] == "cleared", ("gate 6 did not clear by coverage", _cov.reason)
    assert "NOT CHECKED" in _cov.gates[5]["basis"] and "lob_fixpoint" in _cov.gates[5]["basis"], (
        "gate 6 cleared without naming the constraints it did not check", _cov.gates[5]["basis"])
    _none = _g6(_Enf(None, None, {"assessed": [], "unassessable": ["lob_fixpoint"]}))
    assert _none.passed is False and _none.gates[5]["verdict"] == "blocked", (
        "gate 6 cleared when NOTHING was checked - a clearance on an absence of flags", _none.gates[5])
    _bad = _g6(_Enf(False, "zero_placeholder", {"assessed": ["zero_placeholder"], "unassessable": []}))
    assert _bad.passed is False and "VIOLATED" in _bad.reason, ("a violated constraint did not block", _bad.reason)

    # ── CLAUSES (3) AND (5): the avatar SPEAKS, through the chain, and says what was not checked ──
    _sid = client.post("/api/v1/avatar/chat", json={"message": "hello"}).json()["session_id"]
    _rat607 = client.post("/api/v1/avatar/ratifications", json={"purpose": "revision help", "modes": ["instructor"]})
    assert _rat607.status_code == 200
    #  withdrawn at once after use, so no other guard inherits this approval from the shared store
    _rid607 = _rat607.json()["ratification"]["id"]
    assert client.put("/api/v1/avatar/balance-objectives",
                      json={"objectives": [{"name": "mean_sentence_words", "direction": "min"}]}).status_code == 200
    _t1 = client.post("/api/v1/avatar/chat", json={"message": "Help me plan a revision week", "session_id": _sid}).json()
    _t2 = client.post("/api/v1/avatar/chat", json={"message": "Help me plan a revision week", "session_id": _sid}).json()
    _delivered = [t for t in (_t1, _t2) if t["cleared"] is True]
    assert _delivered, ("with an approval and the goals recorded, no reply was delivered across two turns - the loop "
                        "still cannot emit", _t1["clearance_reason"][:160], _t2["clearance_reason"][:160])
    _d = _delivered[-1]
    assert not _d["response"].startswith("This reply was withheld"), _d["response"][:120]
    assert "does NOT cover" in _d["clearance_reason"] and "NOT CHECKED" in _d["clearance_reason"], (
        "a delivered reply does not list the rules its clearance did not check - the Owner's condition",
        _d["clearance_reason"][:300])
    assert all(g["verdict"] == "cleared" for g in _d["clearance_gates"]), _d["clearance_gates"]
    client.post(f"/api/v1/avatar/ratifications/{_rid607}/revoke")

    # ── P3.26 (4): the never-auto-retire set, every case driven and refused BY NAME ───────────
    from agentic_core.economy import living_vsbs as _lv607
    from agentic_core.economy import turnover as _to607
    _ids = [client.post("/api/v1/genesis/establish", json={"problem": f"W607 retire probe {i}", "name": f"W607 R{i}",
                                                           "domain": "enterprise", "ship_output": False}).json()["vsb_id"]
            for i in range(2)]
    _pf = _dp607("governance/protected_entities.json")
    _pf.parent.mkdir(parents=True, exist_ok=True)
    _had = _pf.exists()
    _prev = _pf.read_bytes() if _had else None
    try:
        if _pf.exists():
            _pf.unlink()
        _u = _to607.retirement_refusal(_ids[0])
        assert _u["refused"] is True and _u["not_assessable"] == ["named_in_a_ruling"], (
            "with no record of entities named in a ruling, retirement was not refused as UNKNOWN", _u["basis"])

        _pf.write_text(_js607.dumps({"entities": {}}), encoding="utf-8")
        _clear = _to607.retirement_refusal(_ids[0])
        assert _clear["refused"] is False and len(_clear["rules"]) == 5, (
            "an unprotected entity with a peer was refused, so the set cannot tell protected from not", _clear["basis"])

        def _refused_by(rule):
            r = _to607.retirement_refusal(_ids[0])
            assert r["refused"] is True and r["refusing"] == [rule], (rule, r["refusing"], r["not_assessable"])

        _pf.write_text(_js607.dumps({"entities": {_ids[0]: "named in the W607 probe ruling"}}), encoding="utf-8")
        _refused_by("named_in_a_ruling")
        _pf.write_text(_js607.dumps({"entities": {}}), encoding="utf-8")

        _real_load = _lv607._load
        def _with(**fields):
            d = _real_load()
            d[_ids[0]] = {**d[_ids[0]], **fields}
            return d
        monkeypatch.setattr(_lv607, "_load", lambda: _with(last_hold="governance_hold"))
        _refused_by("governance_hold")
        monkeypatch.setattr(_lv607, "_load", lambda: _with(entity_type="qep_waqf_trust"))
        _refused_by("qep_entity")
        monkeypatch.setattr(_lv607, "_load", lambda: _with(domain="w607-a-domain-nobody-else-has"))
        _refused_by("last_in_realm_domain")
        monkeypatch.setattr(_lv607, "_load", _real_load)

        from agentic_core.economy import revenue as _rv607
        _real_peek = _rv607.peek_pending
        monkeypatch.setattr(_rv607, "peek_pending", lambda v: {**_real_peek(v), "events": 2})
        _refused_by("unsettled_obligations")
        monkeypatch.setattr(_rv607, "peek_pending", _real_peek)

        _api = client.get(f"/api/v1/economy/living-vsbs/{_ids[0]}/retirement-check")
        assert _api.status_code == 200 and {r["rule"] for r in _api.json()["rules"]} == {
            "unsettled_obligations", "governance_hold", "named_in_a_ruling", "qep_entity", "last_in_realm_domain"}
    finally:
        if _had:
            _pf.write_bytes(_prev)
        elif _pf.exists():
            _pf.unlink()


def test_w608_p326_retirement_is_governed_conserves_every_balance_and_keeps_the_record(client):
    """P3.26 clauses (3) and (7): a removal is PROPOSED through Change Control naming what and why, and applied
    only by its implement step, which re-checks the never-auto-retire rules, moves every asset balance to the
    Sovereign Capital Fund, and keeps the record. Before: deregister DELETED the row and had no caller."""
    import json as _js608

    from agentic_core.api import change_control as _cc608
    from agentic_core.api.capital_fund import _load_fund
    from agentic_core.config import data_path as _dp608
    from agentic_core.economy import living_vsbs as _lv608
    from agentic_core.economy.ledger import VirtualLedger

    _ids = [client.post("/api/v1/genesis/establish", json={"problem": f"W608 retire {i}", "name": f"W608 R{i}",
                                                           "domain": "enterprise", "ship_output": False}).json()["vsb_id"]
            for i in range(3)]          # three: once one is retired the second must still have a peer
    _pf = _dp608("governance/protected_entities.json")
    _pf.parent.mkdir(parents=True, exist_ok=True)
    _had, _prev = _pf.exists(), (_pf.read_bytes() if _pf.exists() else None)
    try:
        _pf.write_text(_js608.dumps({"entities": {}}), encoding="utf-8")
        _led = VirtualLedger(_ids[0])
        _led.record("revenue", 50.0, memo="W608 probe intake")          # Dr cash 50 / Cr revenue 50
        _held = round(sum(float(_led.chart_balances().get(a) or 0) for a in ("cash", "reserve_fund")), 2)
        assert _held > 0, ("the probe could not give the entity a balance to conserve", _led.chart_balances())

        # ── clause (7): proposed through Change Control, naming what and why ─────────────────
        _p = client.post(f"/api/v1/economy/living-vsbs/{_ids[0]}/propose-removal", json={"why": "W608 probe: dormant and duplicated"})
        assert _p.status_code == 200 and _p.json()["filed"], _p.text[:200]
        _cid = _p.json()["cca_id"]
        _c = _cc608._load_change(_cid)
        assert _c["change_type"] == "entity_retirement" and _c["vsb_id"] == _ids[0], _c.get("change_type")
        assert "W608 probe" in _c["description"] and _ids[0] in _c["affected_systems"], _c["description"][:160]
        assert _cc608.effective_tier(_c) == "HIGH", "the death of an entity is not a MAJOR change"
        #  nothing moved at filing
        assert _lv608._load()[_ids[0]].get("lifecycle_state") != "retired"
        assert round(sum(float(VirtualLedger(_ids[0]).chart_balances().get(a) or 0) for a in ("cash", "reserve_fund")), 2) == _held

        #  a PROTECTED entity's removal is never filed
        _pf.write_text(_js608.dumps({"entities": {_ids[1]: "W608 probe ruling"}}), encoding="utf-8")
        _no = client.post(f"/api/v1/economy/living-vsbs/{_ids[1]}/propose-removal", json={"why": "W608"})
        assert _no.status_code == 409 and _no.json()["detail"]["refused"] == "protected", _no.text[:200]
        _pf.write_text(_js608.dumps({"entities": {}}), encoding="utf-8")

        # ── approved by the Owner, pre-validated, implemented: APOPTOSIS CONSERVES ───────────
        _c.update(status="approved", decision_source="admin_override", owner_decision_acknowledged=True,
                  twin_prevalidation={"verdict": "pass", "source": "twin_marker"})
        _cc608._save_change(_c)
        _fund0 = float(_load_fund().get("total_capital") or 0)
        _im = client.post(f"/api/v1/cca/{_cid}/implement")
        assert _im.status_code == 200 and _im.json()["status"] == "implemented", _im.text[:300]
        _ap = _im.json()["applied"]
        assert _ap["retired"] is True and round(_ap["conserved_wst"], 2) == _held, _ap
        _after = VirtualLedger(_ids[0]).chart_balances()
        assert round(sum(float(_after.get(a) or 0) for a in ("cash", "reserve_fund")), 2) == 0, (
            "the entity still holds assets after retirement", _after)
        assert round(float(_load_fund().get("total_capital") or 0) - _fund0, 2) == _held, (
            "the fund did not rise by exactly what left the entity's books - a balance was lost or created",
            _fund0, _load_fund().get("total_capital"), _held)
        #  THE RECORD IS KEPT: the row is still on the roster, retired, with what was conserved
        _row = _lv608._load().get(_ids[0])
        assert _row and _row["lifecycle_state"] == "retired" and _row["retirement"]["cca_id"] == _cid, _row
        assert _lv608.lifecycle(_row)["operable"] is False
        assert _lv608.operate_vsb(_ids[0])["held"] == "lifecycle_retired"

        # ── re-checked AT IMPLEMENT: an entity that became protected after approval is not retired ──
        _p2 = client.post(f"/api/v1/economy/living-vsbs/{_ids[1]}/propose-removal", json={"why": "W608 second"})
        assert _p2.status_code == 200, _p2.text[:200]
        _c2 = _cc608._load_change(_p2.json()["cca_id"])
        _c2.update(status="approved", decision_source="admin_override", owner_decision_acknowledged=True,
                   twin_prevalidation={"verdict": "pass", "source": "twin_marker"})
        _cc608._save_change(_c2)
        _pf.write_text(_js608.dumps({"entities": {_ids[1]: "protected after approval"}}), encoding="utf-8")
        _im2 = client.post(f"/api/v1/cca/{_c2['cca_id']}/implement")
        assert _im2.status_code == 409 and _im2.json()["detail"]["refused"] == "protected", _im2.text[:200]
        assert _lv608._load()[_ids[1]].get("lifecycle_state") != "retired", "a protected entity was retired"
        assert _cc608._load_change(_c2["cca_id"])["status"] == "approved", "a refused implement consumed the approval"
    finally:
        if _had:
            _pf.write_bytes(_prev)
        elif _pf.exists():
            _pf.unlink()


def test_w609_p326_a_mature_entity_divides_through_change_control_and_the_child_inherits_verbatim(client):
    """P3.26 clause (5) - MITOSIS: a mature entity creates a subsidiary inheriting its constitution VERBATIM,
    funded from the parent's own share so funds are conserved, through Change Control. The regulator's old
    'mitosis' cloned dicts and was deleted in W604; this is the real one."""
    from agentic_core.api import change_control as _cc609
    from agentic_core.api.vsb import _load_vsb
    from agentic_core.economy import governance as _gv609
    from agentic_core.economy import living_vsbs as _lv609
    from agentic_core.economy import turnover as _to609
    from agentic_core.economy.ledger import VirtualLedger

    _pid = client.post("/api/v1/genesis/establish", json={"problem": "W609 a parent that divides", "name": "W609 Parent",
                                                          "domain": "enterprise", "ship_output": False}).json()["vsb_id"]
    _led = VirtualLedger(_pid)
    _led.record("revenue", 100.0, memo="W609 intake")      # Dr cash 100
    _led.record("reserves", 60.0, memo="W609 reserve")     # Dr reserve_fund 60 / Cr cash 60
    _reserve0 = _led.chart_balances().get("reserve_fund")
    assert _reserve0 and _reserve0 >= 60, _led.chart_balances()

    #  a JUVENILE parent does not divide
    _j = client.post(f"/api/v1/economy/living-vsbs/{_pid}/propose-mitosis",
                     json={"child_name": "W609 Child", "amount_wst": 40, "why": "probe"})
    assert _j.status_code == 409 and _j.json()["detail"]["refused"] == "not_mature", _j.text[:200]
    assert _lv609.set_lifecycle(_pid, "mature", by="w609-owner")["changed"]

    #  more than the parent's share is refused at filing
    _big = client.post(f"/api/v1/economy/living-vsbs/{_pid}/propose-mitosis",
                       json={"child_name": "W609 Child", "amount_wst": 10_000, "why": "probe"})
    assert _big.status_code == 409 and _big.json()["detail"]["refused"] == "insufficient_share", _big.text[:200]

    _p = client.post(f"/api/v1/economy/living-vsbs/{_pid}/propose-mitosis",
                     json={"child_name": "W609 Child", "amount_wst": 40, "why": "W609 probe: a second market"})
    assert _p.status_code == 200 and _p.json()["filed"], _p.text[:200]
    _c = _cc609._load_change(_p.json()["cca_id"])
    #  at least MAJOR: the filing names the constitution, and Change Control's keyword elevation may raise it to
    #  CRITICAL, which is stricter and stands (a stored tier is never lowered)
    assert _c["change_type"] == "entity_mitosis" and _cc609._TIER_RANK[_cc609.effective_tier(_c)] >= _cc609._TIER_RANK["HIGH"], (
        _c.get("change_type"), _cc609.effective_tier(_c))
    _roster_n = len(_lv609._load())
    assert _lv609._load().get(_pid) and _roster_n == len(_lv609._load()), "filing created something"

    _c.update(status="approved", decision_source="admin_override", owner_decision_acknowledged=True,
              twin_prevalidation={"verdict": "pass", "source": "twin_marker"})
    _cc609._save_change(_c)
    _im = client.post(f"/api/v1/cca/{_c['cca_id']}/implement")
    assert _im.status_code == 200 and _im.json()["status"] == "implemented", _im.text[:300]
    _ap = _im.json()["applied"]
    _cid = _ap["child_vsb"]
    assert _ap["divided"] is True and _cid and _ap["amount_wst"] == 40, _ap

    # ── the child INHERITS ITS CONSTITUTION VERBATIM ────────────────────────────────────────
    _parent, _child = _load_vsb(_pid), _load_vsb(_cid)
    assert _child, "the child was not written to the VSB store"
    assert _to609.constitution_of(_child) == _to609.constitution_of(_parent), (
        "the child's constitution is not the parent's, verbatim",
        {k: (_to609.constitution_of(_parent)[k], _to609.constitution_of(_child)[k]) for k in _to609.CONSTITUTION_FIELDS
         if _to609.constitution_of(_parent)[k] != _to609.constitution_of(_child)[k]})
    _crow = _lv609._load().get(_cid)
    assert _crow and _crow["parent_vsb"] == _pid and _crow["lineage_generation"] == 1, _crow

    # ── FUNDS ARE CONSERVED: the parent's share fell by exactly what the child received ──────
    _reserve1 = VirtualLedger(_pid).chart_balances().get("reserve_fund")
    assert round(_reserve0 - _reserve1, 2) == 40.0, ("the parent's reserve did not fall by the child's funding",
                                                     _reserve0, _reserve1)
    _ret, _trn = _gv609._pending_parts(_cid)
    assert round(float(_trn), 2) == 40.0, ("the child's intake did not receive what the parent gave", _trn)

    # ── re-checked AT IMPLEMENT: a parent that is no longer mature does not divide ────────────
    _p2 = client.post(f"/api/v1/economy/living-vsbs/{_pid}/propose-mitosis",
                      json={"child_name": "W609 Second", "amount_wst": 5, "why": "probe"})
    assert _p2.status_code == 200, _p2.text[:200]
    _c2 = _cc609._load_change(_p2.json()["cca_id"])
    _c2.update(status="approved", decision_source="admin_override", owner_decision_acknowledged=True,
               twin_prevalidation={"verdict": "pass", "source": "twin_marker"})
    _cc609._save_change(_c2)
    _lv609.set_lifecycle(_pid, "senescent", by="w609-owner")
    _n_before = len(_lv609._load())
    _im2 = client.post(f"/api/v1/cca/{_c2['cca_id']}/implement")
    assert _im2.status_code == 409 and _im2.json()["detail"]["refused"] == "not_mature", _im2.text[:200]
    assert len(_lv609._load()) == _n_before, "a refused division still created an entity"

    # ── a FAILED funding transfer never yields a funded-looking child ────────────────────────────
    _lv609.set_lifecycle(_pid, "dormant", by="w609-owner")
    _rec = _lv609._load()[_pid]
    _rec_states = dict(_rec)
    from agentic_core.config import store_lock as _sl609
    with _sl609(_lv609._STORE):
        _d = _lv609._load()
        _d[_pid]["lifecycle_state"] = "mature"
        _lv609._save(_d)
    _p3 = client.post(f"/api/v1/economy/living-vsbs/{_pid}/propose-mitosis",
                      json={"child_name": "W609 Third", "amount_wst": 5, "why": "probe"})
    assert _p3.status_code == 200, _p3.text[:200]
    _c3 = _cc609._load_change(_p3.json()["cca_id"])
    _c3.update(status="approved", decision_source="admin_override", owner_decision_acknowledged=True,
               twin_prevalidation={"verdict": "pass", "source": "twin_marker"})
    _cc609._save_change(_c3)
    from agentic_core.economy import transfers as _tr609
    _real_rt = _tr609.record_transfer
    def _boom(*a, **k):
        raise RuntimeError("probe: the ledger refused")
    _tr609.record_transfer = _boom
    try:
        _reserve_b = VirtualLedger(_pid).chart_balances().get("reserve_fund")
        _im3 = client.post(f"/api/v1/cca/{_c3['cca_id']}/implement")
    finally:
        _tr609.record_transfer = _real_rt
    assert _im3.status_code == 409 and _im3.json()["detail"]["refused"] == "funding_failed", _im3.text[:200]
    _orphan = _im3.json()["detail"]["child_vsb"]
    assert _lv609._load()[_orphan]["lifecycle_state"] == "retired", "an unfunded child was left living"
    assert VirtualLedger(_pid).chart_balances().get("reserve_fund") == _reserve_b, "money left the parent anyway"

    # ── FU-367: the recirculation loop's lever is settable from a RUNNING backend, and reverts ──────
    from agentic_core.organism import heartbeat as _hb609
    _was = (_hb609.heartbeat.auto_metabolic, _hb609.heartbeat._metabolic_every)
    try:
        _cf = client.post("/api/v1/heartbeat/configure", json={"auto_metabolic": True, "metabolic_every": 1})
        assert _cf.status_code == 200 and _cf.json()["auto_metabolic"] is True and _cf.json()["metabolic_every"] == 1, (
            "the configure route still drops the metabolic lever, so a running backend can never run the loop",
            _cf.text[:200])
        assert "NOT persisted" in _cf.json()["auto_metabolic_basis"], _cf.json().get("auto_metabolic_basis")
        _b = client.post("/api/v1/heartbeat/beat").json()
        assert any("metabolic" in a for a in (_b.get("actions") or [])), (
            "the lever was set and the beat still did not run the loop", _b.get("actions"))
    finally:
        client.post("/api/v1/heartbeat/configure", json={"auto_metabolic": _was[0], "metabolic_every": _was[1]})
    assert _hb609.heartbeat.auto_metabolic == _was[0], "the guard left the shared heartbeat's lever changed"


def test_w610_p323_the_legal_specialist_assembles_with_provenance_and_never_invents_a_particular(client, monkeypatch, tmp_path):
    """P3.23 / FU-278: every particular carries the document and line it came from or is a BLANK; every authority
    is resolved against the corpus or refused; an empty bundle yields a TEMPLATE; a filing-shaped artefact waits
    for the Owner; the unresolved checks and the not-legal-advice statement are on the page a person reads."""
    import pathlib as _pl610
    import re as _re610

    from agentic_core.legal import bundle as _b610

    _bdir = tmp_path / "legal-matter"
    _bdir.mkdir()
    monkeypatch.setenv(_b610.ENV_VAR, str(_bdir))
    _spec = {"template_id": "et1_claim",
             "particulars": [{"name": "date of dismissal", "words": ["dismissed", "on"]},
                             {"name": "employer's name", "words": ["employer", "ltd"]}],
             "authorities": ["Equality Act 2010", "Smith v Imaginary Holdings [2031] UKEAT 9"]}

    # ── (d) the EMPTY bundle yields a TEMPLATE whose every particular is a blank ────────────────
    _t = client.post("/api/v1/law/matter/assemble", json=_spec).json()
    assert _t["is_template"] is True and _t["sourced"] == [] and len(_t["blanks"]) == 2, _t["face"]
    assert all(p["rendered"].startswith("[BLANK:") and p["document"] is None for p in _t["particulars"]), (
        "an empty bundle produced a particular that is not a blank - the invented-specifics defect FU-278 names",
        [p["rendered"] for p in _t["particulars"]])
    assert "Nothing here is legal advice" in _t["not_legal_advice"], _t["not_legal_advice"]

    # ── (a) a particular the bundle STATES carries its document and line, re-verified ──────────
    (_bdir / "dismissal_letter.txt").write_text(
        "Dear Ms Example,\nYou were dismissed on 3 March with immediate effect.\nRegards\n", encoding="utf-8")
    _a = client.post("/api/v1/law/matter/assemble", json=_spec).json()
    _p0 = _a["particulars"][0]
    assert _p0["found"] and _p0["document"] == "dismissal_letter.txt" and _p0["line"] == 2, _p0
    assert _p0["rendered"] == "You were dismissed on 3 March with immediate effect.", _p0["rendered"]
    assert _p0["verification"]["verdict"] == "MET", _p0["verification"]
    assert _a["particulars"][1]["rendered"].startswith("[BLANK:"), "a particular the bundle does not state was filled"
    assert _a["sourced"] == ["date of dismissal"] and _a["blanks"] == ["employer's name"], _a["face"]

    # ── (b) an authority is resolved against the corpus or REFUSED, never emitted as prose ─────
    _au = {x["authority"]: x for x in _a["authorities"]}
    assert _au["Equality Act 2010"]["resolved"] is True, _au["Equality Act 2010"]
    assert _au["Smith v Imaginary Holdings [2031] UKEAT 9"]["resolved"] is False, (
        "an authority the corpus does not hold was resolved")
    assert _a["authorities_refused"] == ["Smith v Imaginary Holdings [2031] UKEAT 9"], _a["authorities_refused"]

    # ── the GATE: a filing-shaped artefact is a draft until the Owner approves it ────────────────
    assert _a["filing_shaped"] and _a["status"] == "draft_awaiting_owner_approval", _a["status"]
    _ok = client.post(f"/api/v1/law/matter/artefacts/{_a['artefact_id']}/approve")
    assert _ok.status_code == 200 and _ok.json()["artefact"]["status"] == "approved_by_owner", _ok.text[:200]
    _nf = client.post("/api/v1/law/matter/assemble", json={**_spec, "template_id": "nda"}).json()
    assert _nf["status"] == "draft" and not _nf["filing_shaped"]
    _no = client.post(f"/api/v1/law/matter/artefacts/{_nf['artefact_id']}/approve")
    assert _no.status_code == 409 and _no.json()["detail"]["refused"] == "not_filing_shaped", _no.text[:200]
    assert client.post("/api/v1/law/matter/artefacts/lgl-doesnotexist/approve").status_code == 404

    # ── a re-verification that FAILS is reported as unresolved, not hidden ───────────────────
    from agentic_core.legal import specialist as _sp610
    _bad = _sp610.verify_located({"found": True, "document": "dismissal_letter.txt", "line": 1,
                                  "text": "You were dismissed"})
    assert _bad["verdict"] == "UNMET", _bad

    # ── the SURFACE: unresolved checks and the not-legal-advice statement are ON THE PAGE ────────
    _root = _pl610.Path(__file__).resolve().parents[1]
    _pn = (_root / "apps/workstation-superapp/src/components/MatterAssemblyPanel.tsx").read_text(encoding="utf-8")
    _pnc = _re610.sub(r"\{/\*.*?\*/\}|/\*.*?\*/", "", _pn, flags=_re610.S)
    for _t610 in ("matter-not-legal-advice", "matter-unresolved-checks", "matter-particulars", "matter-authorities"):
        assert f'data-testid="{_t610}"' in _pnc, _t610
    assert "art.unresolved_checks" in _pnc and "art.authorities_refused" in _pnc, (
        "the page does not render the unresolved checks it is given")
    assert "<MatterAssemblyPanel />" in (_root / "apps/workstation-superapp/src/pages/domains/LawHub.tsx").read_text(encoding="utf-8")
    #  and EVERY law response a person reads says it is not legal advice, the old generator included
    _law = (_root / "agentic_core/api/law.py").read_text(encoding="utf-8")
    _gen = _law[_law.index('async def generate_document'):]
    _gen = _gen[:_gen.index("\n@router")] if "\n@router" in _gen else _gen
    assert "Nothing here is legal advice." in _gen, "the template generator's disclaimer does not say it is not legal advice"


def test_w610_p323_every_domain_gate_refuses_and_the_qep_and_search_surfaces_are_read(client, monkeypatch):
    """P3.23: every gate refuses in a driven test (GMP QA sign-off, the career agent's recorded-only rule, beside
    the law approval and QEP's scholar review already driven), and FU-462 / FU-467 reach a page."""
    import pathlib as _pl611
    import re as _re611

    from agentic_core.config import data_path as _dp611
    from agentic_core.science import gmp_signoff as _gmp

    # ── GMP: no QA engaged -> nothing released; an unknown signer refused; a changed text withheld ──
    _roster = _dp611("science/gmp_roster.json")
    _had = _roster.exists()
    _prev = _roster.read_bytes() if _had else None
    try:
        if _roster.exists():
            _roster.unlink()
        assert client.post("/api/v1/science/gmp/records", json={"record_id": "w611-b1", "body": "Batch 1: mixed 10 kg"}).status_code == 200
        _s0 = client.post("/api/v1/science/gmp/records/w611-b1/sign", json={"signatory_id": "qa-1"})
        assert _s0.status_code == 409 and _s0.json()["detail"]["reason"] == "no_qa_engaged", _s0.text[:200]
        assert client.get("/api/v1/science/gmp/records/w611-b1").json()["body"] is None
        assert client.post("/api/v1/science/gmp/roster", json={"signatory_id": "qa-1", "name": "QA One"}).status_code == 200
        _s1 = client.post("/api/v1/science/gmp/records/w611-b1/sign", json={"signatory_id": "somebody"})
        assert _s1.status_code == 409 and _s1.json()["detail"]["reason"] == "signatory_not_on_roster", _s1.text[:200]
        _s2 = client.post("/api/v1/science/gmp/records/nope/sign", json={"signatory_id": "qa-1"})
        assert _s2.status_code == 409 and _s2.json()["detail"]["reason"] == "not_submitted"
        _pend = client.get("/api/v1/science/gmp/records/w611-b1").json()
        assert _pend["state"] == "withheld" and _pend["body"] is None, ("an unsigned record was released", _pend)
        assert client.post("/api/v1/science/gmp/records/w611-b1/sign", json={"signatory_id": "qa-1"}).status_code == 200
        _rel = client.get("/api/v1/science/gmp/records/w611-b1").json()
        assert _rel["state"] == "signed" and _rel["body"] == "Batch 1: mixed 10 kg", _rel
        #  the text changes after signature -> withheld again
        _recs = _gmp._load("records")
        _recs["w611-b1"]["body"] = "Batch 1: mixed 12 kg"
        _recs["w611-b1"]["body_hash"] = _gmp._hash("Batch 1: mixed 12 kg")
        _gmp._save("records", _recs)
        assert client.get("/api/v1/science/gmp/records/w611-b1").json()["body"] is None, (
            "a record changed after signature was still released")
    finally:
        if _had:
            _roster.write_bytes(_prev)
        elif _roster.exists():
            _roster.unlink()

    # ── CAREER: nothing recorded -> refused; an invented specific is listed, a recorded one is not ──
    _r0 = client.post("/api/v1/career/generate", json={"output_types": ["cover_letter"]}).json()
    assert _r0["refused"] == "nothing_recorded" and _r0["results"] == [], (
        "the career agent generated with nothing recorded about the person", _r0.get("refused"))
    from agentic_core.api import career as _car
    from agentic_core.ingestion.api import ingestion_manager as _im611
